# v4.4.0 (A-15): dblclick - the case body, verbatim
function Invoke-Handler-dblclick([string]$Cmd, [string[]]$Rest) {
      # dblclick <x> <y> [--to <sel>] [--guard-text <s>|--guard-region x,y,w,h=s] [--force] (guards like click)
      $p = Split-Target $Rest
      if ($p.Words.Count -lt 2) { throw 'usage: dblclick <x> <y> [--to <sel>] [--guard-text <s>|--guard-region x,y,w,h=s] [--allow-outside] [--force]' }
      $tgt = $null
      if ($p.Sel -or $p.GuardText -or $p.GuardRegion) {
        $tgt = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
        Emit-ResolveNote
        Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      }
      Invoke-HitWindowCheck ([int]$p.Words[0]) ([int]$p.Words[1]) $tgt ($p.Sel -ne '') $p.AllowOutside
      Log-Action (Get-RedactedLogArgs $Rest @() $p.LogPayload) "coords=$($p.Words[0]),$($p.Words[1])" $Cmd
      $ecb = Get-ExpectChangeBaseline $p $tgt
      [void][DT]::SetCursorPos([int]$p.Words[0], [int]$p.Words[1])
      Start-Sleep -Milliseconds 150
      1..2 | ForEach-Object {
        [DT]::mouse_event($MOUSE_LDOWN, 0, 0, 0, [IntPtr]::Zero)
        Start-Sleep -Milliseconds 40
        [DT]::mouse_event($MOUSE_LUP, 0, 0, 0, [IntPtr]::Zero)
        Start-Sleep -Milliseconds 60
      }
      "double-clicked $($p.Words[0]),$($p.Words[1])"
      Invoke-ExpectChangeCheck $p $ecb 'double-clicked'
      Invoke-ActionExpectation $p $tgt 'double-clicked'
}

# CU-REL-02 (v4.5.1): validate the legacy raw-delta form and the explicit notch form
# before the handler moves the pointer or calls the input backend.
function Resolve-WheelRequest([string[]]$Words, [string]$Unit, [string]$Axis) {
      $unitKey = ([string]$Unit).ToLowerInvariant()
      $axisKey = ([string]$Axis).ToLowerInvariant()
      if ($unitKey -notin @('raw', 'notches')) { throw "wheel: '--unit' must be raw or notches, got '$Unit'" }
      if ($axisKey -notin @('vertical', 'horizontal')) { throw "wheel: '--axis' must be vertical or horizontal, got '$Axis'" }
      $wordsCopy = @($Words)
      $amountPresent = $wordsCopy.Count -gt 0
      if ($unitKey -eq 'notches' -and -not $amountPresent) { throw "wheel: '--unit notches' requires an explicit amount" }
      $original = if ($amountPresent) { [string]$wordsCopy[0] } else { '-120' }
      if ($original -notmatch '^-?\d+$') { throw "wheel: amount must be a whole integer, got '$original'" }
      $amount64 = [long]0
      $parsed = [long]::TryParse($original, [Globalization.NumberStyles]::AllowLeadingSign, [Globalization.CultureInfo]::InvariantCulture, [ref]$amount64)
      if (-not $parsed) { throw "wheel: amount is outside the supported integer range, got '$original'" }
      if ($unitKey -eq 'notches') {
        $minNotches = [long][Math]::Ceiling(([double][int]::MinValue) / 120.0)
        $maxNotches = [long][Math]::Floor(([double][int]::MaxValue) / 120.0)
        if ($amount64 -lt $minNotches -or $amount64 -gt $maxNotches) {
          throw "wheel: notches amount '$original' overflows the signed 32-bit raw delta after multiplying by 120"
        }
        $rawDelta = [int]($amount64 * 120)
      } else {
        if ($amount64 -lt [int]::MinValue -or $amount64 -gt [int]::MaxValue) {
          throw "wheel: raw amount '$original' must fit a signed 32-bit delta"
        }
        $rawDelta = [int]$amount64
      }
      $direction = if ($rawDelta -eq 0) { 'none' }
        elseif ($axisKey -eq 'vertical' -and $rawDelta -gt 0) { 'up' }
        elseif ($axisKey -eq 'vertical') { 'down' }
        elseif ($rawDelta -gt 0) { 'right' }
        else { 'left' }
      $inputFlag = if ($axisKey -eq 'vertical') { $MOUSE_WHEEL } else { $MOUSE_HWHEEL }
      $eventName = if ($axisKey -eq 'vertical') { 'MOUSE_WHEEL' } else { 'MOUSE_HWHEEL' }
      return [pscustomobject]@{
        OriginalAmount = $original
        AmountSource = if ($amountPresent) { 'argument' } else { 'legacy-default' }
        Unit = $unitKey
        Axis = $axisKey
        Direction = $direction
        RawDelta = $rawDelta
        InputFlag = [uint32]$inputFlag
        EventName = $eventName
      }
}

# CU-REL-03 (v4.5.2): obtain a fresh target rectangle and point observation before any
# focus-first click and again after it. A top-level identity match is necessary but is not
# a claim that the exact child control accepted the wheel event.
function Get-WheelPointObservation([int]$X, [int]$Y, $Target, [string]$Phase, [bool]$RequireForeground = $false) {
      $rect = $null
      if ($null -ne $Target) {
        if (-not [DT]::IsWindow($Target.Handle)) { throw "wheel target guard ($Phase): target hwnd=$($Target.Handle) no longer exists; no wheel input was sent." }
        if ([DT]::IsIconic($Target.Handle)) { throw "wheel target guard ($Phase): target hwnd=$($Target.Handle) is minimized; no wheel input was sent." }
        if (-not [DT]::IsWindowVisible($Target.Handle)) { throw "wheel target guard ($Phase): target hwnd=$($Target.Handle) is not visible; no wheel input was sent." }
        $rect = Get-WindowVisibleRect $Target.Handle
        if ($null -eq $rect -or $rect.W -le 0 -or $rect.H -le 0 -or $rect.X -le -32000 -or $rect.Y -le -32000) {
          throw "wheel target guard ($Phase): target hwnd=$($Target.Handle) has no usable visible rectangle; no wheel input was sent. Re-read it with 'wins'."
        }
        $Target | Add-Member -NotePropertyName Left -NotePropertyValue $rect.X -Force
        $Target | Add-Member -NotePropertyName Top -NotePropertyValue $rect.Y -Force
        $Target | Add-Member -NotePropertyName W -NotePropertyValue $rect.W -Force
        $Target | Add-Member -NotePropertyName H -NotePropertyValue $rect.H -Force
        $Target | Add-Member -NotePropertyName Right -NotePropertyValue ($rect.X + $rect.W) -Force
        $Target | Add-Member -NotePropertyName Bottom -NotePropertyValue ($rect.Y + $rect.H) -Force
        if ($X -lt $rect.X -or $X -ge ($rect.X + $rect.W) -or $Y -lt $rect.Y -or $Y -ge ($rect.Y + $rect.H)) {
          throw "wheel target guard ($Phase): scroll point ($X,$Y) is outside target hwnd=$($Target.Handle) visible rect ($($rect.X),$($rect.Y),$($rect.W)x$($rect.H)); no wheel input was sent."
        }
      }
      $hit = Get-HitWindow $X $Y
      $foreground = [DT]::GetForegroundWindow()
      if ($null -ne $Target) {
        $observed = if ($null -eq $hit) { '(none)' } else { "pid=$($hit.Pid) hwnd=$($hit.Hwnd) title='$($hit.Title)'" }
        if ($null -eq $hit -or $hit.Hwnd -ne $Target.Handle) {
          throw "wheel target guard ($Phase): scroll point ($X,$Y) observes $observed, not target hwnd=$($Target.Handle) '$($Target.Title)'; no wheel input was sent."
        }
        if ($RequireForeground -and $foreground -ne $Target.Handle) {
          throw "wheel target guard ($Phase): --focus-first left foreground hwnd=$foreground instead of target hwnd=$($Target.Handle); no wheel input was sent."
        }
      }
      return [pscustomobject]@{ X = $X; Y = $Y; Hit = $hit; Foreground = $foreground; Rect = $rect; TargetVerified = ($null -ne $Target); Phase = $Phase }
}

# CU-REL-04 (v4.5.3): read the nearest usable ScrollPattern at the selected point,
# walking only within the selected top-level window. UIA absence is a measurement
# limit, never a synthetic position.
function Get-WheelScrollObservation([int]$X, [int]$Y, $Target, [string]$Axis) {
      $r = @{ Available = $false; Reason = 'uia-unavailable'; Position = $null; ContainerId = ''; Axis = $Axis }
      try {
        Add-Type -AssemblyName UIAutomationClient
        Add-Type -AssemblyName UIAutomationTypes
        $root = [System.Windows.Automation.AutomationElement]::FromHandle($Target.Handle)
        if ($null -eq $root) { $r.Reason = 'target-uia-root-unavailable'; return $r }
        $rootId = (@($root.GetRuntimeId()) -join ',')
        if (-not $rootId) { $r.Reason = 'target-uia-identity-unavailable'; return $r }
        $point = New-Object System.Windows.Point($X, $Y)
        $node = [System.Windows.Automation.AutomationElement]::FromPoint($point)
        if ($null -eq $node) { $r.Reason = 'point-uia-element-unavailable'; return $r }
        $walker = [System.Windows.Automation.TreeWalker]::ControlViewWalker
        $rootSeen = $false
        for ($depth = 0; $depth -le 64 -and $null -ne $node; $depth++) {
          $nodeId = ''
          try { $nodeId = (@($node.GetRuntimeId()) -join ',') } catch { }
          if ($nodeId -and $nodeId -ceq $rootId) { $rootSeen = $true }
          if ($nodeId) {
            try {
              $pattern = $node.GetCurrentPattern([System.Windows.Automation.ScrollPattern]::Pattern)
              $info = $pattern.Current
              $scrollable = if ($Axis -ceq 'vertical') { [bool]$info.VerticallyScrollable } else { [bool]$info.HorizontallyScrollable }
              $position = if ($Axis -ceq 'vertical') { [double]$info.VerticalScrollPercent } else { [double]$info.HorizontalScrollPercent }
              if ($scrollable -and $position -ge 0 -and $position -le 100) {
                return @{ Available = $true; Reason = ''; Position = $position; ContainerId = $nodeId; Axis = $Axis }
              }
            } catch { }
          }
          if ($rootSeen) { break }
          try { $node = $walker.GetParent($node) } catch { $node = $null }
        }
        $r.Reason = if ($rootSeen) { 'no-scroll-pattern-for-axis' } else { 'point-not-in-selected-window-tree' }
        return $r
      } catch {
        $r.Reason = 'uia-scroll-read-failed'
        return $r
      }
}

# Pure: map the requested direction to the UIA edge. The caller avoids sending
# an event when the known position is already at that edge.
function Test-WheelScrollBoundary([double]$Position, [string]$Axis, [int]$RawDelta) {
      if ($RawDelta -eq 0) { return $false }
      if ($Axis -ceq 'vertical') {
        if ($RawDelta -gt 0) { return ($Position -le 0) }
        return ($Position -ge 100)
      }
      if ($RawDelta -gt 0) { return ($Position -ge 100) }
      return ($Position -le 0)
}

# Pure: a same-axis position change in the wrong direction is not a successful
# observation of this request (and may reflect unrelated activity).
function Test-WheelScrollDirection([double]$Before, [double]$After, [string]$Axis, [int]$RawDelta) {
      if ([Math]::Abs($After - $Before) -lt 0.01 -or $RawDelta -eq 0) { return $false }
      if ($Axis -ceq 'vertical') {
        if ($RawDelta -gt 0) { return ($After -lt $Before) }
        return ($After -gt $Before)
      }
      if ($RawDelta -gt 0) { return ($After -gt $Before) }
      return ($After -lt $Before)
}

# CU-REL-04: a bounded ControlView scan for a caller-specified visible UIA name.
# It reports no text only when the complete bounded tree was readable; otherwise
# the caller must report verification unavailable.
function Get-WheelVisibleTextObservation($Target, [string]$Needle) {
      $r = @{ Available = $false; Found = $false; Reason = 'uia-unavailable'; Scanned = 0; NodeId = '' }
      if ([string]::IsNullOrWhiteSpace($Needle)) { $r.Reason = 'empty-needle'; return $r }
      try {
        Add-Type -AssemblyName UIAutomationClient
        Add-Type -AssemblyName UIAutomationTypes
        $root = [System.Windows.Automation.AutomationElement]::FromHandle($Target.Handle)
        if ($null -eq $root) { $r.Reason = 'target-uia-root-unavailable'; return $r }
        $walker = [System.Windows.Automation.TreeWalker]::ControlViewWalker
        $nodes = New-Object System.Collections.ArrayList
        [void]$nodes.Add($root)
        $cursor = 0; $incomplete = 0; $maxNodes = 512
        while ($cursor -lt $nodes.Count) {
          if ($cursor -ge $maxNodes) { $r.Reason = 'uia-node-cap'; $r.Scanned = $cursor; return $r }
          $node = $nodes[$cursor]
          $cursor++
          $name = ''; $offscreen = $true; $rect = $null
          try { $name = [string]$node.Current.Name } catch { $incomplete++ }
          try { $offscreen = [bool]$node.Current.IsOffscreen } catch { $incomplete++ }
          try { $rect = $node.Current.BoundingRectangle } catch { $incomplete++ }
          if (-not $offscreen -and $null -ne $rect -and -not $rect.IsEmpty -and $rect.Width -gt 0 -and $rect.Height -gt 0 -and $name.Length -gt 0) {
            $right = [double]$Target.Right; $bottom = [double]$Target.Bottom
            $inside = ($rect.X -lt $right) -and (($rect.X + $rect.Width) -gt [double]$Target.Left) -and
              ($rect.Y -lt $bottom) -and (($rect.Y + $rect.Height) -gt [double]$Target.Top)
            if ($inside -and $name.IndexOf($Needle, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
              $id = ''
              try { $id = (@($node.GetRuntimeId()) -join ',') } catch { }
              return @{ Available = $true; Found = $true; Reason = ''; Scanned = $cursor; NodeId = $id }
            }
          }
          try {
            $child = $walker.GetFirstChild($node)
            while ($null -ne $child) {
              if ($nodes.Count -ge $maxNodes) { $r.Reason = 'uia-node-cap'; $r.Scanned = $cursor; return $r }
              [void]$nodes.Add($child)
              $child = $walker.GetNextSibling($child)
            }
          } catch { $r.Reason = 'uia-child-enumeration-failed'; $r.Scanned = $cursor; return $r }
        }
        if ($incomplete -gt 0) { $r.Reason = 'uia-properties-incomplete'; $r.Scanned = $cursor; return $r }
        return @{ Available = $true; Found = $false; Reason = ''; Scanned = $cursor; NodeId = '' }
      } catch {
        $r.Reason = 'uia-content-read-failed'
        return $r
      }
}

# CU-REL-03 (v4.5.2): target flags assert the window under the actual scroll point.
# --at no longer invents the window centre: it requires explicit x/y for a panel.
# Without a selector, the old current-cursor path remains available.
function Invoke-Handler-wheel([string]$Cmd, [string[]]$Rest) {
      # wheel [amount] [x y] [--unit raw|notches] [--axis vertical|horizontal]
      #       [--to <sel>|--at <sel>] [--focus-first] [--expect-change ...]
      #       [--verify-scroll [--expect-change x,y,w,h]|--expect-visible-text <needle>]
      $own = Strip-OwnFlags $Rest 'wheel'
      $ff = [bool]$own.Values['--focus-first']
      $verifyScroll = [bool]$own.Values['--verify-scroll']
      $expectVisibleText = [string]$own.Values['--expect-visible-text']
      $unit = if ($own.Present['--unit']) { [string]$own.Values['--unit'] } else { 'raw' }
      $axis = if ($own.Present['--axis']) { [string]$own.Values['--axis'] } else { 'vertical' }
      if ($unit.ToLowerInvariant() -notin @('raw', 'notches')) { throw "wheel: '--unit' must be raw or notches, got '$unit'" }
      if ($axis.ToLowerInvariant() -notin @('vertical', 'horizontal')) { throw "wheel: '--axis' must be vertical or horizontal, got '$axis'" }
      $atPresent = [bool]$own.Present['--at']
      $atSel = "$($own.Values['--at'])"
      if ($atPresent -and (-not $atSel -or $atSel -like '--*')) { throw "wheel: '--at' needs a window selector value" }
      $p = Split-Target @($own.Rest) 'wheel'
      if ($atPresent -and $p.Sel) { throw "wheel: choose one target selector, either '--to <sel>' or '--at <sel>', not both" }
      if ($p.Sel -like '--*') { throw "wheel: '--to' needs a window selector value, got flag '$($p.Sel)'" }
      $wordCount = @($p.Words).Count
      if ($wordCount -notin @(0, 1, 3)) { throw "usage: wheel [amount] [x y] [--unit raw|notches] [--axis vertical|horizontal] [--to <sel>|--at <sel>] [--focus-first] [--expect-change [x,y,w,h]] [--verify-scroll [--expect-change x,y,w,h]|--expect-visible-text <needle>] - coordinates must be a complete x/y pair" }
      if ($atPresent -and $wordCount -ne 3) { throw "wheel: '--at <sel>' requires explicit x y coordinates for the scroll point; a window centre does not identify the target control" }
      $wheelRequest = Resolve-WheelRequest @($p.Words) $unit $axis
      $verificationRequested = $verifyScroll -or -not [string]::IsNullOrWhiteSpace($expectVisibleText)
      if ($verifyScroll -and -not [string]::IsNullOrWhiteSpace($expectVisibleText)) { throw "wheel: choose one verification route: '--verify-scroll' or '--expect-visible-text <needle>'" }
      if ($own.Present['--expect-visible-text'] -and [string]::IsNullOrWhiteSpace($expectVisibleText)) { throw "wheel: '--expect-visible-text' needs a non-empty UIA name substring" }
      if ($expectVisibleText.Length -gt 512) { throw 'wheel: --expect-visible-text is limited to 512 characters' }
      if ($verificationRequested -and (-not ($p.Sel -or $atPresent) -or $wordCount -ne 3)) {
        throw 'wheel verification requires --to <sel> or --at <sel> and an explicit amount x y scroll point; no input was sent'
      }
      if ($verificationRequested -and [int]$wheelRequest.RawDelta -eq 0) { throw 'wheel verification requires a non-zero wheel delta; no input was sent' }
      if (-not [string]::IsNullOrWhiteSpace($expectVisibleText) -and $p.ExpectChange) {
        throw "wheel: '--expect-visible-text' cannot be combined with pixel-only '--expect-change'"
      }
      $wx = 0; $wy = 0
      if ($wordCount -eq 3) {
        $wx = Read-FlagNumber 'wheel x' $p.Words[1] $true '(screen pixels)'
        $wy = Read-FlagNumber 'wheel y' $p.Words[2] $true '(screen pixels)'
      }
      $targetSel = if ($atPresent) { $atSel } else { [string]$p.Sel }
      $targetSource = if ($atPresent) { '--at' } elseif ($p.Sel) { '--to' } else { '' }
      if (-not $targetSel -and ($p.Force -or $p.AlwaysActivate -or $p.ExpectHandle)) {
        throw "wheel: '--force', '--always-activate' and '--expect-handle' require '--to <sel>' or '--at <sel>'"
      }
      $tgt = $null
      if ($targetSel) {
        $tgt = Resolve-Target $targetSel $p.Force $p.AlwaysActivate $p.ExpectHandle
        Emit-ResolveNote
      }
      $posInfo = 'at current cursor position'
      if ($wordCount -eq 3) {
        $posInfo = "at ($wx,$wy)"
        $requestedX = $wx; $requestedY = $wy
      } else {
        $requestedPoint = New-Object DT+POINT
        [void][DT]::GetCursorPos([ref]$requestedPoint)
        $requestedX = $requestedPoint.X; $requestedY = $requestedPoint.Y
      }
      if ($tgt) {
        # Reject a wrong destination before moving the pointer. The post-move read below
        # catches a target or layout change between this check and injection.
        [void](Get-WheelPointObservation $requestedX $requestedY $tgt 'before cursor move' $false)
      }
      if ($wordCount -eq 3) {
        [void][DT]::SetCursorPos($wx, $wy)
        Start-Sleep -Milliseconds 150
      }
      $pt = New-Object DT+POINT
      [void][DT]::GetCursorPos([ref]$pt)
      if ($wordCount -eq 3 -and ($pt.X -ne $wx -or $pt.Y -ne $wy)) {
        throw "wheel: requested scroll point ($wx,$wy) but the cursor is at ($($pt.X),$($pt.Y)); no wheel input was sent"
      }
      $pre = Get-WheelPointObservation $pt.X $pt.Y $tgt 'before focus-first' $false
      if ($ff) {
        # This is an intentional real click. The target and landing checks above run before it.
        Move-Click $pt.X $pt.Y 'left'
        $posInfo += ' +clicked first (--focus-first)'
        Start-Sleep -Milliseconds 150
        $ptAfterClick = New-Object DT+POINT
        [void][DT]::GetCursorPos([ref]$ptAfterClick)
        if ($ptAfterClick.X -ne $pt.X -or $ptAfterClick.Y -ne $pt.Y) {
          throw "wheel target guard (after focus-first click): cursor moved from selected scroll point ($($pt.X),$($pt.Y)) to ($($ptAfterClick.X),$($ptAfterClick.Y)); no wheel input was sent"
        }
        $pre = Get-WheelPointObservation $ptAfterClick.X $ptAfterClick.Y $tgt 'after focus-first click' ($null -ne $tgt)
        $pt = $ptAfterClick
      }
      # Capture the effect baseline after the optional click, so it measures only the wheel.
      $ecb = $null
      $verifyMode = 'none'
      $verifyBase = $null
      $pixelRegion = $null
      $pixelHashBefore = ''
      if ($verificationRequested -and $null -eq $tgt) { throw 'wheel verification requires a resolved target window; no wheel input was sent' }
      if (-not [string]::IsNullOrWhiteSpace($expectVisibleText)) {
        $verifyBase = Get-WheelVisibleTextObservation $tgt $expectVisibleText
        if (-not $verifyBase.Available) { throw "wheel verification unavailable before input: UIA visible-text read '$($verifyBase.Reason)'; no wheel input was sent" }
        if ($verifyBase.Found) {
          return "wheel axis=$($wheelRequest.Axis) direction=$($wheelRequest.Direction) raw-delta=$($wheelRequest.RawDelta) scroll-point=($($pre.X),$($pre.Y)) target-check=matched via $targetSource hwnd=$($tgt.Handle) requested=0 SendInput-inserted=0/1 verification=target-content-already-visible evidence=UIA-visible-descendant samples=1 waited-ms=0; no wheel event was sent"
        }
        $verifyMode = 'content'
      } elseif ($verifyScroll) {
        $verifyBase = Get-WheelScrollObservation $pre.X $pre.Y $tgt $wheelRequest.Axis
        if ($verifyBase.Available) {
          if (Test-WheelScrollBoundary ([double]$verifyBase.Position) $wheelRequest.Axis ([int]$wheelRequest.RawDelta)) {
            return "wheel axis=$($wheelRequest.Axis) direction=$($wheelRequest.Direction) position=$($verifyBase.Position) scroll-point=($($pre.X),$($pre.Y)) target-check=matched via $targetSource hwnd=$($tgt.Handle) requested=0 SendInput-inserted=0/1 verification=at-boundary evidence=UIA-ScrollPattern samples=1 waited-ms=0; no wheel event was sent"
          }
          $verifyMode = 'position'
        } elseif ($p.ExpectChange) {
          $ecNorm = ConvertTo-ExpectChangeRect ([string]$p.ExpectChange)
          if ($null -eq $ecNorm) { throw "wheel: UIA ScrollPattern unavailable ($($verifyBase.Reason)); pixel fallback requires explicit --expect-change x,y,w,h" }
          $pixelParams = @{ ExpectChange = $p.ExpectChange; Sel = $targetSel }
          $pixelRegion = Get-ExpectChangeRegion $pixelParams $tgt
          $pr = $pre.Rect
          if ($pixelRegion.X -lt $pr.X -or $pixelRegion.Y -lt $pr.Y -or
              ($pixelRegion.X + $pixelRegion.W) -gt ($pr.X + $pr.W) -or ($pixelRegion.Y + $pixelRegion.H) -gt ($pr.Y + $pr.H)) {
            throw 'wheel: pixel fallback rectangle must be fully inside the selected target visible rectangle; no wheel input was sent'
          }
          $pixelHashBefore = Get-RegionHash $pixelRegion.X $pixelRegion.Y $pixelRegion.W $pixelRegion.H
          $verifyMode = 'pixel'
        } else {
          throw "wheel verification unavailable before input: UIA ScrollPattern '$($verifyBase.Reason)' and no explicit local pixel region; add '--expect-change x,y,w,h' only if pixel-only evidence is acceptable; no wheel input was sent"
        }
      }
      if ($p.ExpectChange -and -not $verificationRequested) {
        $ecp = $p
        if ($tgt -and -not $p.Sel) { $ecp = @{ ExpectChange = $p.ExpectChange; Sel = $targetSel } }
        $ecb = Get-ExpectChangeBaseline $ecp $tgt
      }
      $observed = if ($null -eq $pre.Hit) { '(none)' } else { "pid=$($pre.Hit.Pid) hwnd=$($pre.Hit.Hwnd) title='$($pre.Hit.Title)'" }
      $targetInfo = if ($null -eq $tgt) { 'target=unspecified' } else { "target-check=matched via $targetSource hwnd=$($tgt.Handle)" }
      $effectInfo = if ($verificationRequested) { 'effect-check=bounded-opt-in' } elseif ($p.ExpectChange) { 'effect-check=opt-in-pixel-hash' } else { 'effect=not-verified' }
      Log-Action @($p.Words) "scroll-point=$($pre.X),$($pre.Y) $targetInfo observed=$observed request=$($wheelRequest.EventName):$($wheelRequest.RawDelta)" $Cmd
      $inserted = [DT]::SendWheelInput([int]$wheelRequest.RawDelta, [uint32]$wheelRequest.InputFlag)
      if ([uint32]$inserted -ne 1) {
        $win32 = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error()
        throw "wheel: SendInput inserted $inserted of 1 requested event (win32 error $win32); no automatic retry was attempted and no successful wheel receipt was produced"
      }
      if (-not $verificationRequested) { Start-Sleep -Milliseconds 300 }
      $p2 = New-Object DT+POINT
      [void][DT]::GetCursorPos([ref]$p2)
      $receipt = "wheel $($wheelRequest.OriginalAmount) unit=$($wheelRequest.Unit) axis=$($wheelRequest.Axis) direction=$($wheelRequest.Direction) raw-delta=$($wheelRequest.RawDelta) amount-source=$($wheelRequest.AmountSource) requested=1 event=$($wheelRequest.EventName) SendInput-inserted=$inserted/1 scroll-point=($($pre.X),$($pre.Y)) observed-before-injection=$observed $targetInfo foreground-before-injection=$($pre.Foreground) $effectInfo  $posInfo  cursor-after=($($p2.X),$($p2.Y))"
      if (-not $verificationRequested) {
        Write-Output $receipt
        if ($ecb) { Invoke-ExpectChangeCheck $p $ecb 'wheel' }
        return
      }
      $verifySw = [System.Diagnostics.Stopwatch]::StartNew()
      $verifySamples = 0; $verifyStatus = ''; $verifyDetail = ''; $verifyPosition = $null; $verifyHash = ''
      $maxWaitMs = 1200; $pollMs = 100; $maxSamples = 13
      while ($verifySamples -lt $maxSamples -and $verifySw.ElapsedMilliseconds -le $maxWaitMs) {
        $verifySamples++
        try { $post = Get-WheelPointObservation $pre.X $pre.Y $tgt 'during effect verification' $false }
        catch { $verifyStatus = 'target-changed'; $verifyDetail = $_.Exception.Message; break }
        if ($null -ne $tgt -and $null -ne $pre.Rect -and
            ($post.Rect.X -ne $pre.Rect.X -or $post.Rect.Y -ne $pre.Rect.Y -or $post.Rect.W -ne $pre.Rect.W -or $post.Rect.H -ne $pre.Rect.H)) {
          $verifyStatus = 'target-changed'; $verifyDetail = 'target-visible-rectangle-changed'; break
        }
        if ($verifyMode -eq 'position') {
          $current = Get-WheelScrollObservation $pre.X $pre.Y $tgt $wheelRequest.Axis
          if (-not $current.Available) { $verifyStatus = 'unavailable'; $verifyDetail = [string]$current.Reason; break }
          if ($current.ContainerId -cne $verifyBase.ContainerId) { $verifyStatus = 'target-changed'; $verifyDetail = 'scroll-container-identity-changed'; break }
          $verifyPosition = [double]$current.Position
          if ([Math]::Abs($verifyPosition - [double]$verifyBase.Position) -ge 0.01) {
            if (Test-WheelScrollDirection ([double]$verifyBase.Position) $verifyPosition $wheelRequest.Axis ([int]$wheelRequest.RawDelta)) { $verifyStatus = 'position-changed' }
            else { $verifyStatus = 'unexpected-position-change'; $verifyDetail = 'observed-direction-differs-from-request' }
            break
          }
          if (Test-WheelScrollBoundary $verifyPosition $wheelRequest.Axis ([int]$wheelRequest.RawDelta)) { $verifyStatus = 'at-boundary'; break }
        } elseif ($verifyMode -eq 'content') {
          $current = Get-WheelVisibleTextObservation $tgt $expectVisibleText
          if (-not $current.Available) { $verifyStatus = 'unavailable'; $verifyDetail = [string]$current.Reason; break }
          if ($current.Found) { $verifyStatus = 'target-content-appeared'; $verifyDetail = "node=$($current.NodeId)"; break }
        } else {
          $verifyHash = Get-RegionHash $pixelRegion.X $pixelRegion.Y $pixelRegion.W $pixelRegion.H
          if ($verifyHash -cne $pixelHashBefore) { $verifyStatus = 'pixel-changed-only'; break }
        }
        if ($verifySamples -ge $maxSamples -or $verifySw.ElapsedMilliseconds -ge $maxWaitMs) { break }
        Start-Sleep -Milliseconds $pollMs
      }
      $verifyWait = [int]$verifySw.ElapsedMilliseconds
      if (-not $verifyStatus) {
        $verifyStatus = if ($verifyMode -eq 'position') { 'no-observed-effect' } elseif ($verifyMode -eq 'content') { 'target-content-not-appeared' } else { 'no-pixel-change' }
        if ($verifyMode -eq 'pixel') { $verifyDetail = 'boundary=unknown' }
      }
      $verifyEvidence = if ($verifyMode -eq 'position') { "evidence=UIA-ScrollPattern position=$($verifyBase.Position)->$verifyPosition container=$($verifyBase.ContainerId)" }
        elseif ($verifyMode -eq 'content') { "evidence=UIA-visible-descendant scan-before=$($verifyBase.Scanned) $verifyDetail" }
        else { "evidence=local-pixel-only rect=($($pixelRegion.X),$($pixelRegion.Y),$($pixelRegion.W)x$($pixelRegion.H)) hash-before=$pixelHashBefore hash-after=$verifyHash $verifyDetail" }
      $verifyReceipt = "$receipt verification=$verifyStatus wait-ms=$verifyWait samples=$verifySamples attribution=not-proven $verifyEvidence"
      Write-Output $verifyReceipt
      if ($verifyStatus -notin @('position-changed', 'target-content-appeared', 'at-boundary', 'pixel-changed-only')) {
        throw "wheel verification status=$verifyStatus after SendInput-inserted=1/1 ($verifyDetail); no automatic retry was attempted"
      }
}

# v4.4.0 (A-15): relclick - the case body, verbatim
function Invoke-Handler-relclick([string]$Cmd, [string[]]$Rest) {
      # CU-REL-01 (v4.4.1): this case used to add the offsets to the rect read at SELECT time and
      # click, going through NONE of the pre-action checks its siblings pass. So a window that moved
      # or restored between the read and the click, an offset that landed outside it, and a point
      # covered by some other top-level window all still printed a confident "clicked" line.
      # It now resolves through the common target path (handle pin, activation with the
      # was-already-foreground skip, the did-not-become-foreground refusal), measures the window
      # AGAIN after that activation, passes the shared landing check plus the new identity check,
      # and refuses unless the window physically under the point IS the resolved target.
      # Positional form is unchanged: relclick <sel> <dx> <dy>.
      $p = Split-Target $Rest
      if ($p.Sel) { throw "relclick: the selector is the FIRST positional argument of this command - pass 'relclick <sel> <dx> <dy>', not --to (got --to '$($p.Sel)')" }
      if (@($p.Words).Count -lt 3) { throw 'usage: relclick <sel> <dx> <dy> [--guard-text <s>|--guard-region x,y,w,h=s] [--allow-outside] [--force]' }
      $rcSel = [string]$p.Words[0]
      $rcDx = [int]$p.Words[1]
      $rcDy = [int]$p.Words[2]
      $tgt = Resolve-Target $rcSel $p.Force $p.AlwaysActivate $p.ExpectHandle
      Emit-ResolveNote
      # v4.4.1 CU-REL-01: the rect is read again, by handle, AFTER the activation above - restoring
      # or re-raising a window moves it, and Get-TargetRect prefers the snapshot taken at select
      # time. The six geometry fields are pinned onto the target so every reader in this call (the
      # content guard and the landing check both go through Get-TargetRect) judges the SAME
      # rectangle this click is computed from; otherwise one call computes from one rect and
      # refuses against another.
      $rcRect = Get-WindowVisibleRect $tgt.Handle
      if ($null -eq $rcRect) { throw "relclick: the target window could not be measured after activation (handle gone?) - NOTHING was clicked. Re-read it with 'wins'." }
      if ($rcRect.X -le -32000 -or $rcRect.Y -le -32000) { throw "relclick: the target still sits at the parked position ($($rcRect.X),$($rcRect.Y)) - it is minimized or off-screen, so NOTHING was clicked. Run 'win-restore <sel>' first." }
      $tgt | Add-Member -NotePropertyName Left -NotePropertyValue $rcRect.X -Force
      $tgt | Add-Member -NotePropertyName Top -NotePropertyValue $rcRect.Y -Force
      $tgt | Add-Member -NotePropertyName W -NotePropertyValue $rcRect.W -Force
      $tgt | Add-Member -NotePropertyName H -NotePropertyValue $rcRect.H -Force
      $tgt | Add-Member -NotePropertyName Right -NotePropertyValue ($rcRect.X + $rcRect.W) -Force
      $tgt | Add-Member -NotePropertyName Bottom -NotePropertyValue ($rcRect.Y + $rcRect.H) -Force
      Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      $rcX = $rcRect.X + $rcDx
      $rcY = $rcRect.Y + $rcDy
      Invoke-HitWindowCheck $rcX $rcY $tgt $true $p.AllowOutside
      # The rect check above answers "is the point inside the target". It does not answer "whose
      # window is under the point", and that second half is what relclick never asked.
      $rcHit = Get-HitWindow $rcX $rcY
      if (-not (Test-LandingOnTarget $rcHit $tgt)) {
        if (-not $p.AllowOutside) { throw (Format-LandingVerdict $rcX $rcY $rcHit $tgt $false) }
        Write-Output (Format-LandingVerdict $rcX $rcY $rcHit $tgt $true)
      }
      $rcLanding = $(if ($null -eq $rcHit) { 'none' } else { "$($rcHit.Hwnd)" })
      $rcLogArgs = Get-RedactedLogArgs $Rest @() $p.LogPayload
      Log-Action $rcLogArgs "pid=$($tgt.Pid) title='$($tgt.Title)' screen=$rcX,$rcY rect=($($rcRect.X),$($rcRect.Y),$($rcRect.W)x$($rcRect.H)) origin=fresh-after-activation landing=$rcLanding sel='$rcSel'" $Cmd
      Move-Click $rcX $rcY 'left'
      "clicked window-relative ($rcDx,$rcDy) -> screen ($rcX,$rcY) of pid=$($tgt.Pid) hwnd=$($tgt.Handle) rect=($($rcRect.X),$($rcRect.Y),$($rcRect.W)x$($rcRect.H)) (origin re-read after activation, landing window=$rcLanding)"
}

# v4.4.0 (A-15): drag - the case body, verbatim
function Invoke-Handler-drag([string]$Cmd, [string[]]$Rest) {
      # drag <x1> <y1> <x2> <y2> [--steps n] [--hold ms] [--to <sel>] [--guard-text <s>] [--force]
      # Press, interpolate across the path, release. Covers dragging windows,
      # sliders and scrollbars that wheel events cannot move. Guards like click.
      # v1.5.5 (D-1): --steps/--hold stripped before Split-Target (see hover above);
      # both were unreachable dead code before this commit.
      # v3.1.0 (P-01): drag is the only two-point command in the family, so BOTH
      # endpoints pass the landing check BEFORE the button goes down - each point
      # prints its own hit-window line, and with --to a point outside the target's
      # visible rect is refused while nothing is held (a refusal after mouse-down
      # would leave the drag stuck mid-path on whatever the cursor crossed);
      # --allow-outside releases the check and says so, as on the one-point commands.
      $own = Strip-OwnFlags $Rest 'drag'
      $steps = [int]$own.Values['--steps']
      $hold = [int]$own.Values['--hold']
      $p = Split-Target @($own.Rest) 'drag'
      if ($p.Words.Count -lt 4) { throw 'usage: drag <x1> <y1> <x2> <y2> [--steps n] [--hold ms] [--to <sel>] [--guard-text <s>] [--force]' }
      # X-02: every sibling of this case (click / dblclick / relclick / wheel / press-down /
      # press-up / drag-to / menu-pick) initialises $tgt before the conditional resolve; drag
      # was the one that did not, so a drag WITHOUT --to reached Invoke-HitWindowCheck with a
      # never-set variable. Non-strict that reads as $null; under StrictMode it is a terminating
      # error and the whole command dies before moving the cursor.
      $tgt = $null
      if ($p.Sel -or $p.GuardText -or $p.GuardRegion) {
        $tgt = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
        Emit-ResolveNote
        Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      }
      $x1 = [int]$p.Words[0]; $y1 = [int]$p.Words[1]; $x2 = [int]$p.Words[2]; $y2 = [int]$p.Words[3]
      # Both verdicts exist BEFORE the press - the order here is load-bearing.
      Invoke-HitWindowCheck $x1 $y1 $tgt ($p.Sel -ne '') $p.AllowOutside
      Invoke-HitWindowCheck $x2 $y2 $tgt ($p.Sel -ne '') $p.AllowOutside
      $ecb = Get-ExpectChangeBaseline $p $tgt
      Log-Action (Get-RedactedLogArgs $Rest @() $p.LogPayload) "coords=$x1,$y1 -> $x2,$y2" $Cmd
      [void][DT]::SetCursorPos($x1, $y1)
      Start-Sleep -Milliseconds 150
      [DT]::mouse_event($MOUSE_LDOWN, 0, 0, 0, [IntPtr]::Zero)
      Start-Sleep -Milliseconds $hold
      for ($s = 1; $s -le $steps; $s++) {
        $ix = [int][math]::Round($x1 + ($x2 - $x1) * $s / $steps)
        $iy = [int][math]::Round($y1 + ($y2 - $y1) * $s / $steps)
        [void][DT]::SetCursorPos($ix, $iy)
        Start-Sleep -Milliseconds 12
      }
      [void][DT]::SetCursorPos($x2, $y2)
      Start-Sleep -Milliseconds 100
      [DT]::mouse_event($MOUSE_LUP, 0, 0, 0, [IntPtr]::Zero)
      Start-Sleep -Milliseconds 200
      "dragged ($x1,$y1) -> ($x2,$y2) steps=$steps hold=${hold}ms"
      Invoke-ExpectChangeCheck $p $ecb 'dragged'
}

# v4.4.0 (A-15): drag-to - the case body, verbatim
function Invoke-Handler-drag-to([string]$Cmd, [string[]]$Rest) {
      # drag-to <x> <y> [--steps n] [--to <sel>] [--guard-text <s>] [--force]
      # Travel while HELD. Refuses when nothing is pressed - the one-call form is
      # `drag <x1> <y1> <x2> <y2>`, and silently "working" without a press would be
      # the silent-success shape this repo keeps having to pin shut.
      $own = Strip-OwnFlags $Rest 'drag-to'
      $steps = [int]$own.Values['--steps']
      $p = Split-Target @($own.Rest) 'drag-to'
      if ($p.Words.Count -lt 2) { throw 'usage: drag-to <x> <y> [--steps n] [--to <sel>] [--guard-text <s>] [--force]' }
      $tgt = $null
      if ($p.Sel -or $p.GuardText -or $p.GuardRegion) {
        $tgt = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
        Emit-ResolveNote
        Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      }
      $dg = Get-PressGate 'drag-to' 'drag-to' (Get-LeftButtonDown)
      if ($dg.Refuse) {
        if (Test-PressHoldFired) { Close-PressHold @("$($p.Words[0])", "$($p.Words[1])") '' $Cmd }
        throw "drag-to: $($dg.Reason)"
      }
      $ecb = Get-ExpectChangeBaseline $p $tgt
      $from = New-Object DT+POINT
      [void][DT]::GetCursorPos([ref]$from)
      $x2 = [int]$p.Words[0]; $y2 = [int]$p.Words[1]
      Invoke-HitWindowCheck $x2 $y2 $tgt ($p.Sel -ne '') $p.AllowOutside
      Log-Action (Get-RedactedLogArgs $Rest @() $p.LogPayload) "($($from.X),$($from.Y)) -> $x2,$y2 button=HELD id=$script:PressId" $Cmd
      for ($s = 1; $s -le $steps; $s++) {
        $ix = [int][math]::Round($from.X + ($x2 - $from.X) * $s / $steps)
        $iy = [int][math]::Round($from.Y + ($y2 - $from.Y) * $s / $steps)
        [void][DT]::SetCursorPos($ix, $iy)
        Start-Sleep -Milliseconds 12
      }
      [void][DT]::SetCursorPos($x2, $y2)
      Start-Sleep -Milliseconds 100
      $dgMeas = 'no'
      if (Get-LeftButtonDown) { $dgMeas = 'yes' }
      if ($dgMeas -ne 'yes') {
        # The hold ended mid-travel (a --max-hold that expired, or somebody else let
        # go). Calling that a drag would be a lie: the drop happened somewhere along
        # the path, not at the destination the caller asked for.
        $dgLostId = "$script:PressId"
        $dgCause = 'external'
        if (Test-PressHoldFired) { $dgCause = 'max-hold'; Close-PressHold @("$x2", "$y2") '' $Cmd }
        else { Stop-PressHoldTimer; $script:PressId = '' }
        throw "drag-to: the button was released mid-travel (measured-down=no, cause=$dgCause, id=$dgLostId) - the drag did NOT end in a held state, so do not assume anything was dropped at ($x2,$y2)"
      }
      "dragged-to ($($from.X),$($from.Y)) -> ($x2,$y2) steps=$steps, button still DOWN (measured-down=$dgMeas) - press-up lets go"
      Invoke-ExpectChangeCheck $p $ecb 'dragged-to'
}

# v4.4.0 (A-15): press-down - the case body, verbatim
function Invoke-Handler-press-down([string]$Cmd, [string[]]$Rest) {
      # press-down <x> <y> [--max-hold ms] [--to <sel>] [--guard-text <s>|--guard-region x,y,w=h] [--force]
      # Press and LEAVE IT DOWN, so the caller can look before letting go (the slider
      # shape: the verdict is taken on release). Guards and hit-window like click.
      # A top-level CLI press-down then stays alive until the hold ends - an echo that
      # promises auto-release while the process has already exited would be a lie; as a
      # script step it returns at once and the armed timer holds the deadline while the
      # later steps (shot / find-text / drag-to / press-up) run.
      $own = Strip-OwnFlags $Rest 'press-down'
      $maxHold = [int]$own.Values['--max-hold']
      $p = Split-Target @($own.Rest) 'press-down'
      if ($p.Words.Count -lt 2) { throw 'usage: press-down <x> <y> [--max-hold ms] [--to <sel>] [--guard-text <s>] [--force]' }
      $tgt = $null
      if ($p.Sel -or $p.GuardText -or $p.GuardRegion) {
        $tgt = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
        Emit-ResolveNote
        Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      }
      Invoke-HitWindowCheck ([int]$p.Words[0]) ([int]$p.Words[1]) $tgt ($p.Sel -ne '') $p.AllowOutside
      $pg = Get-PressGate 'press-down' 'press-down' (Get-LeftButtonDown)
      if ($pg.Refuse) { throw "press-down: $($pg.Reason)" }
      $script:PressSeq++
      $prId = "p$PID-$($script:PressSeq)"
      $script:PressId = $prId
      $prLog = @($p.Words[0], $p.Words[1], "id=$prId")
      Log-Action $prLog "coords=$($p.Words[0]),$($p.Words[1]) button=DOWN max-hold=${maxHold}ms" $Cmd
      [void][DT]::SetCursorPos([int]$p.Words[0], [int]$p.Words[1])
      Start-Sleep -Milliseconds 150
      Invoke-LeftPress $true
      Start-PressHoldTimer $maxHold
      $prMeas = 'no'
      if (Get-LeftButtonDown) { $prMeas = 'yes' }
      if ($prMeas -ne 'yes') {
        # The press did not take. Echoing "button is DOWN" anyway is the lie this
        # whole feature exists to avoid, and drag-to / press-up would then act on a
        # state that does not exist.
        Release-Press $prId 'press-not-registered' $prLog $Cmd
        throw 'press-down: the press was sent but the left button does NOT read as down (measured-down=no) - refusing to claim a hold that is not real'
      }
      "button is DOWN at ($($p.Words[0]),$($p.Words[1])) id=$prId, will auto-release after ${maxHold}ms (measured-down=$prMeas) - drag-to to travel, press-up to let go"
      if ($script:PressTopLevel) {
        $prWhy = Wait-PressRelease $maxHold
        if ($prWhy -eq 'max-hold') {
          Close-PressHold $prLog $prId $Cmd
          "auto-released after ${maxHold}ms (id=$prId cause=max-hold)"
        }
        elseif ($prWhy -eq 'external') {
          Stop-PressHoldTimer
          Log-Action $prLog (Format-PressReleaseLine $prId '' 'external') $Cmd
          $script:PressId = ''
          "released before its deadline by something outside this process (id=$prId cause=external)"
        }
        else { Release-Press $prId 'deadline' $prLog $Cmd }
      }
}

# v4.4.0 (A-15): press-up - the case body, verbatim
function Invoke-Handler-press-up([string]$Cmd, [string[]]$Rest) {
      # press-up <x> <y> [--to <sel>] [--force] - let go (at that point). The drop is
      # where a slider verdict is taken, so --expect-change is honoured here.
      $p = Split-Target $Rest 'press-up'
      if ($p.Words.Count -lt 2) { throw 'usage: press-up <x> <y> [--to <sel>] [--expect-change [x,y,w,h]] [--force]' }
      $tgt = $null
      if ($p.Sel -or $p.GuardText -or $p.GuardRegion) {
        $tgt = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
        Emit-ResolveNote
        Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      }
      $pu = Get-PressGate 'press-up' 'press-up' (Get-LeftButtonDown)
      if ($pu.Refuse) {
        # Nothing is down, but the deadline may be what took it up: write the matching
        # UP line for that DOWN instead of leaving the pair dangling.
        if (Test-PressHoldFired) { Close-PressHold @($p.Words[0], $p.Words[1]) '' $Cmd }
        throw "press-up: $($pu.Reason)"
      }
      Invoke-HitWindowCheck ([int]$p.Words[0]) ([int]$p.Words[1]) $tgt ($p.Sel -ne '') $p.AllowOutside
      $ecb = Get-ExpectChangeBaseline $p $tgt
      [void][DT]::SetCursorPos([int]$p.Words[0], [int]$p.Words[1])
      Start-Sleep -Milliseconds 150
      Release-Press '' 'press-up' @($p.Words[0], $p.Words[1]) $Cmd
      Start-Sleep -Milliseconds 200
      Invoke-ExpectChangeCheck $p $ecb 'dropped'
}

# v4.4.0 (A-15): find-click - the case body, verbatim
function Invoke-Handler-find-click([string]$Cmd, [string[]]$Rest) {
      # find-click <sel|x y w h> <needle...> [--index n] - OCR decides where to
      # click, in ONE call: locate the text with the scaled 2x-retry matcher and
      # click the hit's centre. This is menu-pick for arbitrary regions/windows
      # (not just popup menus) and the fix for "click -> wait-stable -> shoot ->
      # eyeball" being three calls to learn a click did nothing (audit
      # 2026-09-29b #4). Mutates the desktop: audited, and guards apply like click.
      # v1.5.5 (D-1): --index stripped before Split-Target, and its value can no
      # longer leak into the needle (previously the flag was unreachable at all).
      $own = Strip-OwnFlags $Rest 'find-click'
      $index = [int]$own.Values['--index']
      $aimLine = [bool]$own.Values['--aim-line']
      $p = Split-Target @($own.Rest) 'find-click'
      if ($p.Words.Count -lt 2) { throw 'usage: find-click <sel|x y w h> <needle...> [--index n] [--aim-line] [--allow-outside]' }
      $region = Resolve-Region $p.Words 0
      $rw = Region-WordCount $p.Words 0
      if ($p.Words.Count -le $rw) { throw 'find-click: empty needle' }
      $needle = (@($p.Words[$rw..($p.Words.Count - 1)]) -join ' ').Trim()
      if (-not $needle) { throw 'find-click: empty needle' }
      $tgt = $null
      if ($p.Sel -or $p.GuardText -or $p.GuardRegion) {
        $tgt = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
        Emit-ResolveNote
        Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      }
      $f = Find-OcrHitsScaled $region.X $region.Y $region.W $region.H $needle $p.Scale $p.MaxTiles $p.NoTile
      $hits = $f.Hits
      if ($hits.Count -eq 0) {
        $missRect = "($($region.X),$($region.Y)) $($region.W)x$($region.H)"
        throw "find-click: '$needle' not found in region $missRect - nothing clicked ($(Format-OcrRetryNote $f)); $(Format-OcrSampleTail $f.Lines 8 @{ Rect = $missRect; Retry = (Format-OcrRetryNote $f); Occlusion = $(if ($p.GuardText -or $p.GuardRegion) { 'checked-by-guard-above' } else { 'not-scanned' }); Needle = $needle })"
      }
      if ($index -ge $hits.Count) { throw "find-click: --index $index but only $($hits.Count) hit(s)" }
      # J-05: said BEFORE the click, so a caller that meant "the second one" can still stop
      # and re-run with --index while the line/occurrence distinction is on screen.
      $j05f = Format-MultiOccurrenceHint $needle $hits
      if ($j05f) { Write-Output $j05f }
      $hit = $hits[$index]
      $cx = $hit.X + [int]($hit.W / 2)
      $cy = $hit.Y + [int]($hit.H / 2)
      # v1.5.9 (P-2): aim at the needle's own sub-span of the matched line, not the
      # line centre. The echo always says which aiming ran, so a caller can tell a
      # sub-span click from a line-centre one (and --aim-line is the rollback).
      $aimNote = ' aim=line-centre (--aim-line)'
      if (-not $aimLine) {
        $aim = Get-NeedleAimX "$($hit.Text)" $hit.X $hit.W $needle
        if ($aim.Matched) {
          $cx = $aim.AimX
          $aimNote = " aim=substring $($aim.SpanStart)-$($aim.SpanEnd)/$($aim.NormLen) of line"
          if ((($aim.SpanEnd - $aim.SpanStart) / $aim.NormLen) -le 0.6) {
            Write-Output 'NOTE: matched line is wider than needle -- aimed at needle sub-span, not line centre'
          }
        } else {
          $aimNote = ' aim=line-centre (needle not locatable in line text)'
        }
      }
      Invoke-HitWindowCheck $cx $cy $tgt ($p.Sel -ne '') $p.AllowOutside
      $ecb = Get-ExpectChangeBaseline $p $tgt
      Log-Action (Get-RedactedLogArgs $Rest @($p.Words[$rw..($p.Words.Count - 1)]) $p.LogPayload) "needle='$needle' hit=$($index + 1)/$($hits.Count) at=$cx,$cy$aimNote" $Cmd
      Move-Click $cx $cy 'left'
      "find-click: clicked '$($hit.Text)' at ($cx,$cy) (hit $($index + 1)/$($hits.Count))$aimNote$(if ($f.Scaled) { ' [found via 2x upscale]' })$(Get-OcrFoldMarker $hits)"
      Invoke-ExpectChangeCheck $p $ecb 'find-click'
      Invoke-ActionExpectation $p $tgt 'clicked'
}

# v4.4.0 (A-15): win-move - the case body, verbatim
function Invoke-Handler-win-move([string]$Cmd, [string[]]$Rest) {
      # win-move <sel> <x> <y> - place the VISIBLE window top-left at x,y.
      if ($Rest.Count -lt 3) { throw 'usage: win-move <sel> <x> <y>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      Emit-ResolveNote
      if ([DT]::IsIconic($w.Handle)) { [void][DT]::ShowWindow($w.Handle, 9); Start-Sleep -Milliseconds 250 }
      $adj = Get-VisibleAdjust $w.Handle
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)' visible=($($Rest[1]),$($Rest[2]))" $Cmd
      [void][DT]::MoveWindow($w.Handle, ([int]$Rest[1] - $adj.DL), ([int]$Rest[2] - $adj.DT), ($w.W + $adj.DL + $adj.DR), ($w.H + $adj.DT + $adj.DB), $true)
      Start-Sleep -Milliseconds 250
      $w2 = Resolve-Window $Rest[0]
      "moved pid=$($w.Pid) -> visible top-left ($($w2.Left),$($w2.Top)) size=$($w2.W)x$($w2.H)"
}

# v4.4.0 (A-15): win-resize - the case body, verbatim
function Invoke-Handler-win-resize([string]$Cmd, [string[]]$Rest) {
      # win-resize <sel> <w> <h> - set the VISIBLE size (MoveWindow alone would
      # size the invisible-border rect instead, off by ~7-11px per side).
      if ($Rest.Count -lt 3) { throw 'usage: win-resize <sel> <w> <h>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      Emit-ResolveNote
      if ([DT]::IsIconic($w.Handle)) { [void][DT]::ShowWindow($w.Handle, 9); Start-Sleep -Milliseconds 250 }
      $adj = Get-VisibleAdjust $w.Handle
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)' visible=$($Rest[1])x$($Rest[2])" $Cmd
      [void][DT]::MoveWindow($w.Handle, ($w.Left - $adj.DL), ($w.Top - $adj.DT), ([int]$Rest[1] + $adj.DL + $adj.DR), ([int]$Rest[2] + $adj.DT + $adj.DB), $true)
      Start-Sleep -Milliseconds 250
      $w2 = Resolve-Window $Rest[0]
      "resized pid=$($w.Pid) -> visible ($($w2.Left),$($w2.Top)) size=$($w2.W)x$($w2.H)"
}

# v4.4.0 (A-15): win-max - the case body, verbatim
function Invoke-Handler-win-max([string]$Cmd, [string[]]$Rest) {
      if ($Rest.Count -lt 1) { throw 'usage: win-max <sel>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)'" $Cmd
      [void][DT]::ShowWindow($w.Handle, 3)   # SW_MAXIMIZE
      Start-Sleep -Milliseconds 250
      "maximized pid=$($w.Pid) title='$($w.Title)' zoomed=$([DT]::IsZoomed($w.Handle))"
}

# v4.4.0 (A-15): win-min - the case body, verbatim
function Invoke-Handler-win-min([string]$Cmd, [string[]]$Rest) {
      if ($Rest.Count -lt 1) { throw 'usage: win-min <sel>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)'" $Cmd
      [void][DT]::ShowWindow($w.Handle, 6)   # SW_MINIMIZE
      Start-Sleep -Milliseconds 250
      "minimized pid=$($w.Pid) title='$($w.Title)' iconic=$([DT]::IsIconic($w.Handle))"
}

# v4.4.0 (A-15): win-restore - the case body, verbatim
function Invoke-Handler-win-restore([string]$Cmd, [string[]]$Rest) {
      if ($Rest.Count -lt 1) { throw 'usage: win-restore <sel>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)'" $Cmd
      [void][DT]::ShowWindow($w.Handle, 9)   # SW_RESTORE
      Start-Sleep -Milliseconds 250
      "restored pid=$($w.Pid) title='$($w.Title)' iconic=$([DT]::IsIconic($w.Handle)) zoomed=$([DT]::IsZoomed($w.Handle))"
}

# v4.4.0 (A-15): win-close - the case body, verbatim
function Invoke-Handler-win-close([string]$Cmd, [string[]]$Rest) {
      # win-close <sel> - WM_CLOSE, graceful: no focus theft, and the app gets
      # to prompt. Strictly safer than Alt+F4, which hits whatever IS foreground.
      if ($Rest.Count -lt 1) { throw 'usage: win-close <sel>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)'" $Cmd
      $sent = [DT]::PostMessage($w.Handle, 0x0010, [IntPtr]::Zero, [IntPtr]::Zero)
      "close requested (WM_CLOSE) pid=$($w.Pid) title='$($w.Title)' posted=$sent (the app may still show a confirm dialog)"
}

# v4.4.0 (A-15): dialog-cancel - the case body, verbatim
function Invoke-Handler-dialog-cancel([string]$Cmd, [string[]]$Rest) {
      # v3.0.0 (B-5): close a dialog by its CANCEL control, or by Escape when the tree has no
      # cancel-shaped button. This command can never CONFIRM anything (see Get-DialogCancelStems
      # for why "close" is not in the set), and it proves its own result by the handle being
      # gone rather than by the click having been delivered.
      $own = Strip-OwnFlags $Rest 'dialog-cancel'
      $p = Split-Target @($own.Rest) 'dialog-cancel'
      $sel = ''
      if ($p.Sel) { $sel = $p.Sel } elseif (@($p.Words).Count -ge 1) { $sel = "$($p.Words[0])" }
      if (-not $sel) { throw 'usage: dialog-cancel <sel> [--allow-window] [--expect-handle <hwnd>] [--expect|--expect-gone ...]' }
      $w = Resolve-Window $sel
      if (-not $w) { throw "no window matching: $sel" }
      $pin = Test-HandlePin $p.ExpectHandle $w.Handle
      if (-not $pin.Ok) {
        throw "dialog-cancel: handle pin - this call may only act on $($pin.Expected) but '$sel' is hwnd=$($pin.Actual) pid=$($w.Pid) '$($w.Title)' ($(Format-HandlePinReason $pin)) - NOTHING was pressed."
      }
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)'" $Cmd
      "target: pid=$($w.Pid) hwnd=$($w.Handle) class='$($w.Class)' title='$($w.Title)' (no activation - UIA invoke needs no foreground)"
      $r = Invoke-DialogCancel $w ([bool]$own.Values['--allow-window'])
      "cancelled-via=$($r.Via) pressed='$($r.Pressed)' window-gone=$([bool]$r.Confirmed) waited=$($r.WaitedMs)ms"
      "detail: $($r.Note)"
      if (-not $r.Confirmed) {
        throw "dialog-cancel: NOT CONFIRMED - the dialog (pid=$($w.Pid) hwnd=$($w.Handle)) is still on screen after $($r.WaitedMs)ms via $($r.Via). Nothing more was pressed. Inspect with uia-tree '$sel' 40."
      }
      Invoke-ActionExpectation $p $null 'dialog-cancel'
}

# v4.4.0 (A-15): menu-pick - the case body, verbatim
function Invoke-Handler-menu-pick([string]$Cmd, [string[]]$Rest) {
      # menu-pick <sel> <needle...> [--index n] [--allow-window]
      # Resolve the POPUP window itself (context menus are their own top-level
      # windows; find it in `wins`), OCR its rows, click the row containing the
      # needle. Replaces crop -> measure -> convert -> mis-click loops on
      # fixed-line-height menus.
      if ($Rest.Count -lt 2) { throw 'usage: menu-pick <sel> <needle...> [--index n] [--allow-window] [--expect <needle>|--expect-gone <needle>]' }
      # v1.5.7 (J-06): --index/--allow-window come from the flag table now. The expect family
      # stays parsed HERE (menu-pick declares exactly those shared flags in
      # Get-CommandSharedMap) because this command never calls Split-Target and its
      # timeout/interval defaults (6.0s / 300ms) are its own documented behaviour - moving
      # them into Split-Target would silently change defaults for existing scripts.
      $own = Strip-OwnFlags $Rest 'menu-pick'
      $idx = [int]$own.Values['--index']
      $hadIndex = [bool]$own.Present['--index']
      $allowWindow = [bool]$own.Values['--allow-window']
      # v3.1.0 (P-06): the parse moved into the pure Resolve-MenuPickArgs so the trailing-flag
      # hole (a flag as the LAST token bound its operand to $null -> the expectation silently
      # never ran, and --timeout became 0) is pinned by offline unit checks.
      $mpRes = Resolve-MenuPickArgs @($own.Rest)
      $expect = $mpRes.Expect
      $expectGone = $mpRes.ExpectGone
      $expectRegion = $mpRes.ExpectRegion
      $timeoutSec = $mpRes.TimeoutSec
      $intervalMs = $mpRes.IntervalMs
      $Rest = @($mpRes.Words)
      if ($Rest.Count -lt 2) { throw 'usage: menu-pick <sel> <needle...> [--index n] [--allow-window]' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      Emit-ResolveNote
      # Pointing this at a whole application window (or the desktop) turns "pick
      # the menu row" into "click the first pixel anywhere that happens to contain
      # the text", which is how a send ends up in the wrong conversation. The
      # v1.5.2 predicate is class+shape, NOT the WS_POPUP bit - see Test-MenuWindow
      # (audit R-04: Progman/Settings/Weixin all carry WS_POPUP and were accepted).
      $scrMenu = [System.Windows.Forms.SystemInformation]::VirtualScreen
      $menuVerdict = Test-MenuWindow $w ([int]$scrMenu.Width) ([int]$scrMenu.Height)
      if (-not $menuVerdict.Menu -and -not $allowWindow) {
        throw "menu-pick: target '$($w.Title)' ($($w.W)x$($w.H), class=$($w.Class)) is NOT a menu window ($($menuVerdict.Reason)). Picking a row from a whole app/desktop surface can click anything that merely contains the text - take the real popup from 'wins' (Win32 menus are class #32768), or pass --allow-window if pointing at this window is really intended."
      }
      if ($menuVerdict.Menu) {
        Write-Output "menu target accepted: $($menuVerdict.Reason)"
      } else {
        Write-Output "menu-pick: --allow-window overrides the shape rule ($($menuVerdict.Reason))"
      }
      $needle = (@($Rest[1..($Rest.Count - 1)]) -join ' ').Trim()
      if (-not $needle) { throw 'menu-pick: empty needle' }
      $m = Find-OcrHitsScaled $w.Left $w.Top $w.W $w.H $needle
      $hits = $m.Hits; $lines = $m.Lines
      if ($hits.Count -eq 0) {
        throw "menu-pick: row '$needle' not found in menu window '$($w.Title)' ($($w.W)x$($w.H)); $(Format-OcrSampleTail $lines 12 @{ Rect = "window '$($w.Title)' ($($w.Left),$($w.Top)) $($w.W)x$($w.H)"; Retry = (Format-OcrRetryNote $m); Occlusion = 'menu window, gate not run'; Needle = $needle })"
      }
      if ($idx -ge $hits.Count) { throw "menu-pick: --index $idx out of range ($($hits.Count) row(s) matched)" }
      if ($hits.Count -gt 1 -and -not $hadIndex) {
        Write-Output "menu-pick: WARN $($hits.Count) rows contain '$needle'; picking #$idx - pass --index to choose"
      }
      # J-05: same wording, same producer as find-text/find-click (one renderer per family).
      $j05m = Format-MultiOccurrenceHint $needle $hits
      if ($j05m) { Write-Output $j05m }
      $hit = $hits[$idx]
      $cx = $hit.X + [int]($hit.W / 2)
      $cy = $hit.Y + [int]($hit.H / 2)
      Log-Action (Get-RedactedLogArgs $Rest @($Rest[1..($Rest.Count - 1)]) $false) "pid=$($w.Pid) title='$($w.Title)' row='$($hit.Text)' at=$cx,$cy" $Cmd
      Move-Click $cx $cy 'left'
      "menu-pick: clicked row '$($hit.Text)' at ($cx,$cy) rect=($($hit.X),$($hit.Y),$($hit.W)x$($hit.H))$(if ($m.Scaled) { ' [found via 2x upscale]' })"
      Invoke-ActionExpectation @{ Expect = $expect; ExpectGone = $expectGone; ExpectRegion = $expectRegion; TimeoutSec = $timeoutSec; IntervalMs = $intervalMs } $w 'menu-picked'
}

# v4.4.0 (A-15): open-and-pick - the case body, verbatim
function Invoke-Handler-open-and-pick([string]$Cmd, [string[]]$Rest) {
      # open-and-pick <sel> <opener-x> <opener-y> <needle...> [--region x,y,w,h] [--expect ...]
      # A-1 (J-03 A, owner-adjudicated): one process does click opener -> beat -> shoot the
      # target window (or its --region sub-rect) -> OCR needle -> click the hit's centre.
      # For self-drawn dropdowns / right-click menus that menu-pick cannot see (not
      # #32768, not transient-popup shaped). Deliberately does NOT add an index: the
      # adjudicated shape has none; the pick is the FIRST matching line. Coordinates are
      # WINDOW-RELATIVE (the opener lives inside the target). The 400 ms beat before the
      # shot is the popup's appearance window and is echoed, not hidden. Live behaviour
      # (the real two clicks) is proven in --live; parsing and refusal shapes are
      # provable offline and pinned in selftest.
      $own = Strip-OwnFlags $Rest 'open-and-pick'
      $p = Split-Target @($own.Rest) 'open-and-pick'
      if ($p.Words.Count -lt 4) { throw 'usage: open-and-pick <sel> <opener-x> <opener-y> <needle...> [--region x,y,w,h]' }
      $regionSpec = "$($own.Values['--region'])"
      $region = Parse-OpenPickRegion $regionSpec
      $needle = (@($p.Words[3..($p.Words.Count - 1)]) -join ' ').Trim()
      if (-not $needle) { throw 'open-and-pick: empty needle' }
      if ("$($p.Words[1])" -notmatch '^-?[0-9]+$' -or "$($p.Words[2])" -notmatch '^-?[0-9]+$') { throw "open-and-pick: opener coordinates must be integers, got: '$($p.Words[1])' '$($p.Words[2])'" }
      $ox = [int]$p.Words[1]; $oy = [int]$p.Words[2]
      $tgt = Resolve-Target $p.Words[0] $p.Force $p.AlwaysActivate $p.ExpectHandle
      Emit-ResolveNote
      $irect = Get-TargetRect $tgt
      if ($null -eq $irect) { throw 'open-and-pick: cannot determine target window rect' }
      if ($region) {
        if ($region.W -gt $irect.W -or $region.H -gt $irect.H) { throw "open-and-pick: --region $($region.W)x$($region.H) exceeds window $($irect.W)x$($irect.H)" }
      }
      Invoke-ContentGuard $tgt $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      $openX = $irect.X + $ox; $openY = $irect.Y + $oy
      Invoke-HitWindowCheck $openX $openY $tgt $true $p.AllowOutside
      Log-Action (Get-RedactedLogArgs $Rest @($p.Words[3..($p.Words.Count - 1)]) $p.LogPayload) "opener click at=$openX,$openY needle pending" $Cmd
      Move-Click $openX $openY 'left'
      Start-Sleep -Milliseconds 400
      $srect = Get-TargetRect $tgt
      if ($null -eq $srect) { throw 'open-and-pick: target window rect disappeared after the opener click' }
      $scanX = $srect.X + $(if ($region) { $region.X } else { 0 })
      $scanY = $srect.Y + $(if ($region) { $region.Y } else { 0 })
      $scanW = $(if ($region) { $region.W } else { $srect.W })
      $scanH = $(if ($region) { $region.H } else { $srect.H })
      $f = Find-OcrHitsScaled $scanX $scanY $scanW $scanH $needle $p.Scale $p.MaxTiles $p.NoTile
      $hits = $f.Hits
      if ($hits.Count -eq 0) {
        $missRect = "($($scanX),$($scanY)) $($scanW)x$($scanH)"
        throw "open-and-pick: '$needle' not found in region $missRect after opener click - nothing picked ($(Format-OcrRetryNote $f)); $(Format-OcrSampleTail $f.Lines 8 @{ Rect = $missRect; Retry = (Format-OcrRetryNote $f); Occlusion = 'scanned-after-opener'; Needle = $needle })"
      }
      $hit = $hits[0]
      $cx = $hit.X + [int]($hit.W / 2)
      $cy = $hit.Y + [int]($hit.H / 2)
      Invoke-HitWindowCheck $cx $cy $tgt $true $p.AllowOutside
      $ecb = Get-ExpectChangeBaseline $p $tgt
      Log-Action (Get-RedactedLogArgs $Rest @($p.Words[3..($p.Words.Count - 1)]) $p.LogPayload) "needle='$needle' hit=1/$($hits.Count) at=$cx,$cy" $Cmd
      Move-Click $cx $cy 'left'
      "open-and-pick: opener ($openX,$openY) beat 400ms, clicked '$($hit.Text)' at ($cx,$cy) (hit 1/$($hits.Count))$(if ($f.Scaled) { ' [found via 2x upscale]' })$(Get-OcrFoldMarker $hits)"
      Invoke-ExpectChangeCheck $p $ecb 'open-and-pick'
      Invoke-ActionExpectation $p $tgt 'picked'
}


# lib/handlers-ui.ps1 - the ui-group handlers, lifted out of desktop.ps1 (A-17..A-19 line).
#    Byte-identical to what the dispatcher carried after A-15 pen 2: the union of the lifted lines was
#    hashed before the cut and the same bytes are re-hashed from this file afterwards (printed by
#    handler-lift.js, and recorded in the ledger row for this card). The group membership is declared in
#    $script:StHandlerGroups and reconciled against the definitions by lint (A-16) - this file is named in
#    $script:StHandlerFiles in the same write that removes the code from the entry, so neither half can
#    land on its own.

# v4.4.0 (A-15): chrome-tabs - the case body, verbatim
function Invoke-Handler-chrome-tabs([string]$Cmd, [string[]]$Rest) {
      # chrome-tabs [--json] - enumerate open tabs via CDP's HTTP endpoint (no socket).
      # The base is the loopback gate's OUTPUT and that base is what every request
      # below uses - the gate is on the real path, not decoration.
      # Chrome >=136 REFUSES --remote-debugging-port on the DEFAULT profile ("DevTools
      # remote debugging requires a non-default data directory", measured 2026-09-30),
      # so this group only ever talks to a non-default --user-data-dir instance.
      $base = Get-CdpLoopbackBase "127.0.0.1:$script:CdpPort"
      $tabs = @(Get-CdpTargets $base 'page')
      if ($script:Json) {
        [pscustomobject]@{ tabs = @($tabs | ForEach-Object { [pscustomobject]@{ id = $_.id; title = $_.title; domain = (Get-CdpUrlDomain $_.url) } }) } | ConvertTo-Json -Compress -Depth 4
      } else {
        "chrome-tabs: $($tabs.Count) page(s) on $base/json (host+port only - a token can sit in the path as happily as in the query)"
        $n = 0
        foreach ($t in $tabs) { $n++; "T{0:D2} host={1}  title={2}" -f $n, (Get-CdpUrlDomain $t.url), ([string]$t.title) }
      }
}

# v4.4.0 (A-15): chrome-read - the case body, verbatim
function Invoke-Handler-chrome-read([string]$Cmd, [string[]]$Rest) {
      # chrome-read <sel> - visible text of the matching tab's page (body.innerText),
      # through one Runtime.evaluate round trip. Read-only.
      # v3.1.0 (P-06): the selector is REQUIRED. Get-CdpPageId falls back to the FIRST page
      # when it gets an empty selector, so `chrome-read` with a missing argument used to read
      # whichever tab happened to be first and exit 0 - while chrome-find and chrome-click both
      # refuse. Same family, one command silently answering for a page nobody named.
      $base = Get-CdpLoopbackBase "127.0.0.1:$script:CdpPort"
      if ($Rest.Count -lt 1) { throw 'usage: chrome-read <sel>  (the selector names the tab - there is no default tab)' }
      $p = Get-CdpPageId $base $Rest[0]
      $r = Invoke-CdpEval $base $p.Page.id 'document.body.innerText'
      if (-not $r.Ok) { throw "chrome-read: $($r.Error)" }
      $lines = @("$($r.Value)" -split "`r?`n" | Where-Object { $_.Trim().Length -gt 0 })
      $shown = @($lines | Select-Object -First 40)
      "chrome-read: tab '$($p.Page.title)' ($($p.Count) page(s) open): $($lines.Count) non-empty line(s)$(if ($lines.Count -gt $shown.Count) { ", showing first $($shown.Count) ($($lines.Count - $shown.Count) more not shown)" })"
      foreach ($ln in $shown) { $ln.Trim() }
}

# v4.4.0 (A-15): chrome-find - the case body, verbatim
function Invoke-Handler-chrome-find([string]$Cmd, [string[]]$Rest) {
      # chrome-find <sel> <text> - locate the innermost element whose text contains
      # <text>, return its rect CONVERTED to physical screen coordinates. The scale
      # factor is measured per call (window.devicePixelRatio), the client origin is
      # derived from window.screenX/Y plus outer/inner deltas - A-3 reconciles the
      # result against find-text OCR (<=3px), never against our own claim.
      $base = Get-CdpLoopbackBase "127.0.0.1:$script:CdpPort"
      if ($Rest.Count -lt 2) { throw 'usage: chrome-find <sel> <text...>' }
      $p = Get-CdpPageId $base $Rest[0]
      $needle = (@($Rest[1..($Rest.Count - 1)]) -join ' ').Trim()
      $needleJson = $needle | ConvertTo-Json -Compress
      $js = @"
const needle = $needleJson;
const els = Array.from(document.querySelectorAll('body *'));
const matches = els.filter(e => e.getClientRects().length > 0 && ((e.innerText || '').indexOf(needle) >= 0));
if (matches.length === 0) { return { found: false }; }
let best = matches[0];
for (const m of matches) { if ((m.innerText || '').length < (best.innerText || '').length) { best = m; } }
best.scrollIntoView({ block: 'center' });
const r = best.getBoundingClientRect();
return { found: true, count: matches.length, rect: { left: r.left, top: r.top, width: r.width, height: r.height }, text: (best.innerText || '').slice(0, 60) };
"@
      $r = Invoke-CdpJson $base $p.Page.id $js
      if (-not $r.Ok) { throw "chrome-find: $($r.Error)" }
      if (-not $r.Value.found) { throw "chrome-find: no element matching '$needle' on page '$($p.Page.title)' (DOM scan, 0 matching leaf elements - this is a DOM verdict, not an OCR miss)" }
      $m = Invoke-CdpJson $base $p.Page.id 'return { dpr: window.devicePixelRatio, iw: window.innerWidth, ih: window.innerHeight, sx: window.screenX, sy: window.screenY, ow: window.outerWidth, oh: window.outerHeight };'
      if (-not $m.Ok) { throw "chrome-find: metrics probe failed: $($m.Error)" }
      $dpr = [double]$m.Value.dpr
      if ($dpr -le 0) { throw "chrome-find: the page reported devicePixelRatio=$dpr - refusing to map through a nonsense scale factor" }
      # sx/ow are not decoration: the JS fallback route needs the X axis of its own. A
      # probe that stops reporting them must not leave the mapping silently half-blind.
      if ($null -eq $m.Value.sx -or $null -eq $m.Value.ow) { throw "chrome-find: the metrics probe returned no screenX/outerWidth - refusing to guess the viewport's left edge" }
      $co = Get-CdpViewportOrigin $base $dpr ([int]$m.Value.ih) ([int]$m.Value.iw) ([int]$m.Value.sy) ([int]$m.Value.oh) ([int]$m.Value.ih) ([int]$m.Value.sx) ([int]$m.Value.ow)
      if (-not $co.Ok) { throw "chrome-find: cannot place the viewport on the screen: $($co.Error)" }
      $clientX = $co.X; $clientY = $co.Y
      $sr = Convert-CdpRectToScreen $r.Value.rect $dpr $clientX $clientY
      $cx = $sr.X + [int]($sr.W / 2); $cy = $sr.Y + [int]($sr.H / 2)
      "chrome-find: '$needle' on '$($p.Page.title)' ($($r.Value.count) leaf hit(s)) rect screen=($($sr.X),$($sr.Y),$($sr.W)x$($sr.H)) centre=($cx,$cy) dpr=$dpr clientOrigin=($clientX,$clientY) origin-formula=$($co.Formula) origin-window-pid=$($co.Pid) -> click $cx $cy"
}

# v4.4.0 (A-15): chrome-click - body verbatim from the case, plus the flag the G-17 ruling allows
function Invoke-Handler-chrome-click([string]$Cmd, [string[]]$Rest, [ref]$SkipTail) {
      # chrome-click <sel> <text> [-dry] - chrome-find then click its centre with the
      # regular injected click. v3.1.0 (P-06) corrected the promise: this command's selector
      # names a CDP PAGE, not a window, so there is no target rect to enforce a landing
      # guard against - what applies is the AUDIT line and the hit-window ECHO (which window is
      # actually under the mapped point), never landing enforcement. DOM-level synthetic clicks
      # are NOT used: they bypass the guards this tool exists to enforce. -dry stops after
      # printing the mapping.
      $base = Get-CdpLoopbackBase "127.0.0.1:$script:CdpPort"
      if ($Rest.Count -lt 2) { throw 'usage: chrome-click <sel> <text...> [-dry]' }
      $dry = $false
      $words = New-Object System.Collections.ArrayList
      foreach ($t in $Rest) { if ($t -eq '-dry') { $dry = $true } else { [void]$words.Add($t) } }
      $Rest = @($words)
      $findOut = $null
      try { $findOut = Invoke-DesktopCommand 'chrome-find' @($Rest) } catch { throw ("chrome-click: " + $_.Exception.Message) }
      $line = (@($findOut) | Where-Object { $_ -like 'chrome-find:*' } | Select-Object -First 1)   # selection-not-display: single mapping line, not a list cut
      if ("$line" -notmatch 'centre=\((-?\d+),(-?\d+)\)') { throw 'chrome-click: could not parse centre from chrome-find output' }
      $cx = [int]$Matches[1]; $cy = [int]$Matches[2]
      if ($dry) { "chrome-click: [dry run] would click $cx,$cy (from chrome-find mapping)"; $SkipTail.Value = $true; return }
      # v3.1.0 (P-06): the CDP->screen mapping is the part most likely to be wrong (scale,
      # scroll, a second monitor), so name the window actually under the point BEFORE the
      # click lands. Echo-only (no target rect exists for a page selector), same shape as
      # `move` uses. A mapping that lands on the wrong window is now visible in the same line
      # the operator already reads, instead of only in hindsight.
      Invoke-HitWindowCheck $cx $cy $null $false $false
      Log-Action @($Rest) "cdp pick at=$cx,$cy" $Cmd
      Move-Click $cx $cy 'left'
      "chrome-click: clicked $cx,$cy (from chrome-find mapping)"
}

# v4.4.0 (A-15): chrome-menu-read - the case body, verbatim
function Invoke-Handler-chrome-menu-read([string]$Cmd, [string[]]$Rest) {
      # chrome-menu-read - OPEN Chrome's app menu, list every MenuItem Name UIA exposes,
      # then dismiss it WITHOUT clicking anything (Escape). This is how the option-B exit
      # route gets evidence on a browser that is still in use: it answers "can this
      # build's menu be read by literal Name, and is exactly one item the exit?" without
      # quitting the browser. NOT read-only - it opens a menu - and it refuses (exit 1)
      # when the exit item cannot be picked, so a caller never reads "menu seen" as
      # "exit drivable".
      $w = Resolve-Window 'Chrome'
      if (-not $w) { throw 'chrome-menu-read: no Chrome window found - there is no menu to read' }
      Log-Action @('chrome-menu-read') "opening the app menu of pid $($w.Pid) to read item names; no item clicked" $Cmd
      $rd = Read-ChromeMenuItems $w 4000
      $pick = Find-ChromeExitItem $rd.Items
      "chrome-menu-read: pid=$($w.Pid) opened-via=$($rd.Via) menu-items=$($rd.Count) dismissed=$($rd.Dismissed) exit-item='$($pick.Name)' exit-verdict=$($pick.Reason)"
      if ($rd.Count -gt 0) { "items: $(@($rd.Items) -join ' ;; ')" }
      if (-not $rd.Opened) { throw "chrome-menu-read: $($rd.Error)" }
      if (-not $pick.Ok) { throw "chrome-menu-read: no exit item was picked - $($pick.Reason). Chrome is still running and nothing was clicked; option B is not drivable on this build." }
}

# v4.4.0 (A-15): chrome-debug-off - the case body, verbatim
function Invoke-Handler-chrome-debug-off([string]$Cmd, [string[]]$Rest) {
      # chrome-debug-off - the B-3 shutdown path: relaunch Chrome WITHOUT the debug
      # flag, then VERIFY the port is dead - /json/version must stop answering and
      # chrome-tabs must refuse. Omission IS the shutdown; Chrome only opens the port
      # when asked. The close goes through Restart-ChromeWithFlags, which prefers
      # Browser.close over WM_CLOSE because WM_CLOSE was measured to leave chrome.exe
      # alive headless (service-worker extension) while still holding 9222 - and a
      # relaunch into that survivor is a singleton hand-off, not a restart.
      $base = Get-CdpLoopbackBase "127.0.0.1:$script:CdpPort"
      $tabsBefore = @(Get-CdpTargets $base 'page')
      Log-Action @('chrome-debug-off') "closing chrome, $($tabsBefore.Count) page(s) expected to come back; relaunch carries no debug flag" $Cmd
      $rs = Restart-ChromeWithFlags @('--restore-last-session') $base 30000
      if (-not $rs.Closed) { throw "chrome-debug-off: $($rs.Error)" }
      $swR = [System.Diagnostics.Stopwatch]::StartNew()
      $portDead = $false
      while ($swR.ElapsedMilliseconds -lt 20000) {
        try { [void](Invoke-RestMethod -Uri "$base/json/version" -TimeoutSec 2); Start-Sleep -Milliseconds 600 } catch { $portDead = $true; break }
      }
      if (-not $portDead) { throw "chrome-debug-off: $base/json/version still answering 20s after the relaunch - the debug port did not close, investigate before trusting the box (chrome processes: $(@(Get-Process chrome -ErrorAction SilentlyContinue).Count))" }
      "chrome-debug-off: Chrome closed via $($rs.CloseVia) close-note=[$($rs.CloseNote)] anchored-pid=$($rs.AnchorPid) anchored-by=$($rs.AnchoredBy) scope=$($rs.Scope) ($($tabsBefore.Count) page(s) saved, waited $($rs.WaitedMs)ms for that browser's $($rs.Scoped) process(es) to exit) and relaunched WITHOUT the debug flag"
      "VERIFIED: $base/json/version no longer answers after $($swR.ElapsedMilliseconds)ms - CDP surface closed (chrome-tabs now refuses, which is the proof)"
      if ($null -eq $rs.Window) { "WARNING: no Chrome window 30s after the relaunch - the port is closed but Chrome did not come back visibly; open it manually" }
}

# v4.4.0 (A-15): chrome-a11y - the case body, verbatim
function Invoke-Handler-chrome-a11y([string]$Cmd, [string[]]$Rest) {
      # chrome-a11y <on|off> - the A-plan relaunch. THIS is the page-driving route for
      # the owner's DEFAULT profile: measured 2026-09-30 on Chrome 154, Chrome refuses
      # --remote-debugging-port there outright and prints
      #   "DevTools remote debugging requires a non-default data directory."
      # so CDP (chrome-*) can only ever drive a NON-default --user-data-dir instance.
      # --force-renderer-accessibility needs no such trade: the page DOM reaches the
      # UIA tree and the existing uia-* family drives real logged-in tabs.
      #   on  -> relaunch with --force-renderer-accessibility --restore-last-session
      #   off -> relaunch with just --restore-last-session (tree returns to collapsed)
      # Self-verifies by product, never by echo: the page-area control count and the
      # TabItem count are measured before and after, so a relaunch that changed nothing
      # cannot be reported as a success, and a restore that lost tabs cannot be hidden.
      if ($Rest.Count -lt 1) { throw 'usage: chrome-a11y <on|off>' }
      $mode = "$($Rest[0])".ToLower()
      if ($mode -ne 'on' -and $mode -ne 'off') { throw "chrome-a11y: mode must be 'on' or 'off' (got '$($Rest[0])')" }
      $wBefore = Resolve-Window 'Chrome'
      if (-not $wBefore) { throw 'chrome-a11y: no Chrome window found - there is no Chrome to relaunch' }
      $before = Measure-A11yTree $wBefore 40
      $flags = @('--restore-last-session')
      if ($mode -eq 'on') { $flags = @('--force-renderer-accessibility', '--restore-last-session') }
      Log-Action @('chrome-a11y') "mode=$mode tabs-before=$($before.Tabs) page-area-before=$($before.PageHits) verdict-before=$($before.Verdict)" $Cmd
      # owner ruling 2: reconcile tabs across EVERY restart this command performs.
      # The manifest goes to a UTF-8 BOM file, never the GBK console.
      $tmBefore = Write-TabManifest $wBefore 'before'
      if ($tmBefore.Error) { throw "chrome-a11y: tab manifest (before) failed: $($tmBefore.Error)" }
      "tab-manifest=$($tmBefore.Path) tabs-before=$($tmBefore.Count)"
      $rs = Restart-ChromeWithFlags $flags '' 45000
      if (-not $rs.Closed) { throw "chrome-a11y: $($rs.Error)" }
      if ($null -eq $rs.Window) { throw "chrome-a11y: Chrome closed but no window came back 45s after the relaunch - open Chrome yourself; the flag was not applied to a live instance" }
      # the tree fills in as pages commit, so re-measure until the verdict flips or the
      # patience runs out - the same "+ verified / NOT met" split the click family uses.
      $after = $null
      $swA = [System.Diagnostics.Stopwatch]::StartNew()
      $wantVerdict = $(if ($mode -eq 'on') { 'exposed' } else { 'collapsed' })
      $wpin = $rs.Window
      while ($swA.ElapsedMilliseconds -lt 20000) {
        # stay on the instance WE launched: a title match could wander onto a second
        # Chrome running from a different --user-data-dir and be measured instead
        $wpid = Resolve-Window ([string]$rs.Window.Pid)
        if ($wpid) { $wpin = $wpid }
        $after = Measure-A11yTree $wpin 40
        if ($after.Verdict -eq $wantVerdict) { break }
        Start-Sleep -Milliseconds 1000
      }
      $met = ($after.Verdict -eq $wantVerdict)
      # reconcile the tabs BEFORE any a11y-verdict throw: the tabs are the owner's
      # state, and a mismatch must stop here - a second restart would make Chrome
      # treat the still-open session as old data and clear it (owner ruling 3).
      $tmAfter = Write-TabManifest $wpin 'after'
      if ($tmAfter.Error) { throw "chrome-a11y: tab manifest (after) failed: $($tmAfter.Error)" }
      $tmCmp = Compare-TabManifest $tmBefore.Lines $tmAfter.Lines
      "tab-manifest=$($tmAfter.Path) tabs-after=$($tmAfter.Count) tab-verify=$($tmCmp.Reason)"
      if (-not $tmCmp.Ok) { throw "chrome-a11y: TAB MISMATCH across the restart - $($tmCmp.Reason). Stopping without a second restart (ruling 3: restarting again makes Chrome treat the open session as old data and clear it). Compare the two manifest files and restore tabs by hand." }
      "chrome-a11y: mode=$mode closed-via=$($rs.CloseVia) close-note=[$($rs.CloseNote)] exit-item='$($rs.ExitName)' scope=$($rs.Scope) waited=$($rs.WaitedMs)ms relaunched-pid=$($rs.Window.Pid) launch-args=[$($rs.LaunchArgs)]"
      "VERIFIED page-tree: before=$($before.Verdict) (nodes=$($before.Nodes) page-area=$($before.PageHits) tabs=$($before.Tabs)) -> after=$($after.Verdict) (nodes=$($after.Nodes) page-area=$($after.PageHits) tabs=$($after.Tabs) kinds=[$($after.Kinds)]) patience $([int]$swA.ElapsedMilliseconds)ms/20000ms met=$met"
      if ($after.Tabs -ne $before.Tabs) { "NOTE: tab count changed across the relaunch: $($before.Tabs) -> $($after.Tabs). Names to check: this command cannot tell you WHICH tabs went missing, run uia-tree <sel> 40 | grep TabItem" }
      # WHAT THIS CAN AND CANNOT PROVE (measured 2026-09-30, owner's own Chrome, A-6b):
      # the same DEFAULT-profile window read page-area 0 on the first UIA contact 110 ms
      # after a NO-FLAG relaunch and 19 / 100 nodes on the next three contacts - Chrome
      # enables renderer accessibility because a UIA client connected, not because of the
      # switch. With the flag the steady reading was identical (19 / 100). So 'exposed'
      # after 'on' is NOT proof the flag caused it, and this command's real job is the
      # graceful relaunch + the tab reconciliation, with the tree numbers reported as
      # observations. What stays sound: if 'on' still measures ZERO after the re-probe
      # patience, the operator has nothing drivable and must be told.
      if ($mode -eq 'on' -and -not $met) { throw "chrome-a11y: relaunched WITH the flag but the page area still exposes 0 interactive controls after 20s of patience - the flag did not take (survivor process? a different profile?). Nothing is drivable via uia-* on this page; do not fall back to clicking coordinates blindly." }
      if ($mode -eq 'off' -and $after.PageHits -gt 0) { "NOTE: the flag is gone but the page area still exposes $($after.PageHits) interactive controls - Chrome keeps renderer accessibility on for any connected UIA client, so chrome-a11y off removes the SWITCH, it does not close a surface. Do not treat 'off' as a privacy boundary." }
}

# v4.4.0 (A-15): a11y-probe - the case body, verbatim
function Invoke-Handler-a11y-probe([string]$Cmd, [string[]]$Rest) {
      # a11y-probe <sel> [bigDepth] - READ-ONLY diagnosis for Chromium/Electron shells:
      # how many controls does the UIA tree expose, and does the PAGE AREA (lower half
      # of the window) hold any interactive control? Verdict page-tree=exposed|collapsed
      # answers "can uia-* drive this app's content" BEFORE attempts fail.
      # A-6b (v1.8.0, measured on the owner's own Chrome): 'collapsed' is often just a
      # COLD-START artifact - Chrome lights renderer accessibility when a UIA client
      # connects, and the walk that triggered it has already finished. Same unflagged
      # process: contact #1 = page-area 0 / 60 nodes, contacts #2-4 = 19 / 100. So a
      # zero here is re-measured ONCE before it is allowed to become a verdict.
      # bigDepth is a real limit now (Uia-WalkAll honours it) - the same selector at
      # depth 3 and depth 40 must report different node counts.
      if ($Rest.Count -lt 1) { throw 'usage: a11y-probe <sel> [bigDepth]' }
      $bigDepth = $(if ($Rest.Count -ge 2 -and $Rest[1]) { [int]$Rest[1] } else { 40 })
      # validated BEFORE any window is resolved: refusing early is what makes this
      # reachable offline, and 0 would silently mean "unlimited" on a command whose
      # whole purpose is reporting the depth it actually walked.
      if ($bigDepth -lt 1) { throw "a11y-probe: bigDepth must be >= 1 (got $bigDepth) - 0 would mean unlimited and this command advertises the depth it walked" }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      $m = Measure-A11yTree $w $bigDepth
      if ($m.Verdict -eq 'no-root') { throw "a11y-probe: no UIA root for pid $($w.Pid)" }
      $reprobe = 'no'
      if ($m.Verdict -eq 'collapsed') {
        # Measure again before a zero is allowed to become a verdict: on Chrome the first
        # UIA contact itself enables renderer accessibility, and that first walk is over
        # before the tree exists (measured on the owner's own default-profile Chrome,
        # no flag: contact #1 page-area=0/60 nodes, contact #2 19/100, #3 19/100).
        $m2 = Measure-A11yTree $w $bigDepth
        $reprobe = $(if ($m2.PageHits -gt 0) { 'yes, lit to ' + $m2.PageHits } else { 'yes, still 0' })
        if ($m2.PageHits -gt 0) { $m = $m2 }
      }
      "a11y-probe: class='$($w.Class)' title='$($w.Title)' depth-walked=$bigDepth nodes=$($m.Nodes) interactive=$($m.Interactive) rectless=$($m.Rectless) page-area-interactive=$($m.PageHits) page-kinds=[$($m.Kinds)] page-sample=[$($m.Sample)] cold-zero-reprobe=$reprobe -> page-tree=$($m.Verdict)"
      if ($m.Verdict -eq 'collapsed') {
        "NOTE: still 0 interactive controls in the page area AFTER a re-probe, so this is not the cold-start artifact - UIA genuinely cannot drive this window's content right now. Order of operations: (1) check the fixture - a page whose lower half holds no interactive elements measures 0 with the tree wide open (that bad fixture cost this project one wrong conclusion on 2026-09-30); (2) chrome-a11y on to relaunch Chrome with --force-renderer-accessibility; (3) CDP (chrome-tabs/chrome-find) exists only for NON-default --user-data-dir instances - Chrome 136+ refuses the debug port on a default profile; (4) whole-page OCR + coordinates last, and 'OCR found nothing' is never evidence of absence."
      }
}

# v4.4.0 (A-15): uia-tree - the case body, verbatim
function Invoke-Handler-uia-tree([string]$Cmd, [string[]]$Rest) {
      # v2.4.0: --actions-all / --no-actions / --no-paths are stripped before the
      # positional shape <sel> [maxDepth] is applied; an unknown --word is refused
      # (a swallowed flag is how a fake knob ships).
      # v4.2.0 (external feedback item 4, 2026-10-10): the reporter wanted "--out <file>"
      # because they did not know `--dump` exists - and --out CANNOT exist here: under
      # `powershell -File` the token binds at PowerShell's own parameter layer as -Out*
      # and dies with "AmbiguousParameter (OutVariable|OutBuffer)" before this file runs
      # (measured 2026-10-10). So the file half stays the ONE existing producer
      # (Emit-DumpOutput, uia-tree has been in Get-DumpCommandSet since v3.0.0) and this
      # command's usage line points at it; a second writer would be a second truncation
      # rule. --path is the genuinely missing half and lives here.
      $aAll = $false; $aOff = $false; $pOff = $false
      $pathTok = ''
      $pos = New-Object System.Collections.ArrayList
      $uiCount = @($Rest).Count
      for ($ui = 0; $ui -lt $uiCount; $ui++) {
        $w0 = "$(@($Rest)[$ui])"
        if ($w0 -eq '--actions-all') { $aAll = $true }
        elseif ($w0 -eq '--no-actions') { $aOff = $true }
        elseif ($w0 -eq '--no-paths') { $pOff = $true }
        elseif ($w0 -eq '--path') {
          if (($ui + 1) -ge @($Rest).Count) { throw 'uia-tree: --path needs a token copied from a line''s path= field, e.g. --path /0/1/6' }
          $ui++; $pathTok = "$(@($Rest)[$ui])"
          if ($pathTok -notmatch '^(/\d+)+$') { throw "uia-tree: --path must look like /0/1/6 (digits after slashes, exactly as printed on the line), got: $pathTok" }
        }
        elseif ($w0.StartsWith('--')) { throw "uia-tree: unknown flag '$w0' (valid: --actions-all | --no-actions | --no-paths | --path </0/1/...>; and --dump <file> for the whole tree as UTF-8 - uia-tree is in its accepted set)" }
        else { [void]$pos.Add($w0) }
      }
      if ($aAll -and $aOff) { throw 'uia-tree: --actions-all and --no-actions are mutually exclusive' }
      if (@($pos).Count -lt 1) { throw 'usage: uia-tree <sel> [maxDepth] [--actions-all|--no-actions] [--no-paths] [--path </0/1/...>] [--dump <file>]' }
      $w = Resolve-Window $pos[0]
      if (-not $w) { throw "no window matching: $($pos[0])" }
      $depth = if (@($pos).Count -ge 2 -and $pos[1]) { [int]$pos[1] } else { 6 }
      # a path deeper than the walked bound would print NOTHING and read as "that node
      # does not exist", so the bound is raised to reach it - and the header says which
      # depth really ran (the depth lint below reads that same line).
      $depthNote = ''
      if ($pathTok) {
        $needDepth = (@($pathTok -split '/')).Count - 2
        if ($needDepth -lt 0) { $needDepth = 0 }
        if ($depth -lt $needDepth) { $depthNote = "note: depth raised $depth -> $needDepth to reach --path $pathTok"; $depth = $needDepth }
      }
      $rr = Uia-Roots $w
      if ($rr.Roots.Count -lt 1) { throw "no UIA root for pid $($w.Pid)" }
      # Paths are per-root unambiguous only when there is exactly ONE root (the
      # normal FromHandle case); the pid-enum fallback can list several, and
      # identical /0/... labels on different roots would be a lie, so there the
      # path fields stay off (actions still probe).
      $usePaths = (-not $pOff) -and (@($rr.Roots).Count -eq 1)
      if ($pathTok -and -not $usePaths) {
        throw "uia-tree: --path needs path= fields on the lines - roots=$($rr.Roots.Count)$([char]32)(a pid with several top-level windows prints none) or --no-paths was passed. Drop --path, or select a window whose tree has one root"
      }
      $outLines = New-Object System.Collections.ArrayList
      [void]$outLines.Add("scan: handle=$($w.Handle) title='$($w.Title)' pick=$($w.Pick) roots=$($rr.Roots.Count) via=$($rr.Via) depth=$depth")
      if ($depthNote) { [void]$outLines.Add($depthNote) }
      $ctx = @{ NoActions = $aOff; AllActions = $aAll; NoPaths = (-not $usePaths); Nodes = 0; Probed = 0; ProbeMs = 0.0; Sw = [System.Diagnostics.Stopwatch]::StartNew() }
      foreach ($r in $rr.Roots) {
        $rn = ''
        try { $rn = $r.Current.Name } catch { }
        [void]$outLines.Add("root: $rn")
        foreach ($dl in @(Uia-Dump $r 0 $depth $ctx '/0')) { [void]$outLines.Add([string]$dl) }
      }
      $ctx.Sw.Stop()
      # v4.2.0: --path keeps the ancestor chain (where in the tree am I) and the subtree
      # (what this node says), drops every sibling, and reports both counts - a filter
      # that silently matched nothing would read as "the node is gone". The decision lives
      # in Test-UiaPathFilter (pure) so both directions are offline checks.
      if ($pathTok) {
        $fp = Test-UiaPathFilter @($outLines) $pathTok
        if (-not $fp.Ok) { throw "uia-tree: --path $pathTok matched no line at depth $depth - copy the token verbatim from a path= field, or raise [maxDepth]" }
        $outLines = New-Object System.Collections.ArrayList
        foreach ($fl in @($fp.Lines)) { [void]$outLines.Add($fl) }
        [void]$outLines.Add("filter: $($fp.Summary), walked depth=$depth")
      }
      foreach ($ol in $outLines) { Write-Output $ol }
      # Cost self-report on STDERR, so --no-actions keeps stdout byte-identical to
      # the pre-2.4.0 output (the disabled marker still prints, on the diagnostic
      # stream where cost accounting belongs).
      if ($aOff) {
        [Console]::Error.WriteLine('actions-probed=0 (disabled)')
      } else {
        $tag = 'allowlist'; if ($aAll) { $tag = 'all' }
        [Console]::Error.WriteLine('actions-probed=' + $ctx.Probed + ' of ' + $ctx.Nodes + ' nodes (' + $tag + ') elapsed=' + [int]$ctx.ProbeMs + 'ms')
      }
}

# v4.4.0 (A-15): uia-path - the case body, verbatim
function Invoke-Handler-uia-path([string]$Cmd, [string[]]$Rest) {
      # v2.4.0: READ-ONLY resolver for the path handles uia-tree prints. Shares the
      # walk and the refusal shapes with the @path action routes, so a path that
      # fails here fails there for the SAME reason.
      if ($Rest.Count -lt 2) { throw 'usage: uia-path <sel> @/0/2/1 [maxDepth]' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      $maxD = if ($Rest.Count -ge 3 -and $Rest[2]) { [int]$Rest[2] } else { 0 }
      $rr = Uia-Roots $w
      if ($rr.Roots.Count -lt 1) { throw "no UIA root for pid $($w.Pid)" }
      $res = Resolve-UiaPath $rr.Roots $Rest[1] $maxD
      if (-not $res.Ok) {
        Write-Output (Format-UiaPathRefusal $Rest[1] $res $null $null)
        throw "uia-path: path refused ($($res.Reason))"
      }
      $toks = Get-UiaActionTokens $res.El
      Uia-Line $res.El 0 $res.Path $toks
}

# v4.4.0 (A-15): uia-find - the case body, verbatim
function Invoke-Handler-uia-find([string]$Cmd, [string[]]$Rest) {
      if ($Rest.Count -lt 2) { throw 'usage: uia-find <sel> <nameSub> [typeRe]' }
      # An empty nameSub makes the pattern '**', which matches EVERY element: measured
      # 2026-09-30 as hits=149 for an empty needle, i.e. a "found" that proves nothing and
      # quietly turns a broken caller into a green one. Refuse before touching any window.
      if ("$($Rest[1])".Trim().Length -lt 1) { throw 'uia-find: <nameSub> must not be empty - an empty substring matches every element, so a hit would prove nothing' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      $typeRe = if ($Rest.Count -ge 3) { $Rest[2] } else { '' }
      # v2.1.0 (plan doc 1.2): the walk is handed to Search-UiaTree as a delegate so a cold
      # first contact can be re-measured once before it becomes a verdict. The 400 ms
      # patience lives HERE (it is a production timing), not in the rule - that is what
      # keeps the rule an offline unit test with both directions pinned.
      # v4.2.0 (feedback item 5): the bound is spelled OUT here instead of living in
      # Uia-WalkAll's default, and it travels with the walk so the echo can print the
      # depth that actually ran - "uia-find found nothing" and "uia-find walked nothing"
      # used to be the same line.
      $uDepth = 0
      $uwf = {
        param($contact)
        if ($contact -gt 1) { Start-Sleep -Milliseconds 400 }
        $rr = Uia-Roots $w
        if ($rr.Roots.Count -lt 1) { throw "no UIA root for pid $($w.Pid)" }
        $els = @(Uia-WalkAll $rr.Roots $uDepth)
        return @{ Elements = $els; Scanned = @($els).Count; Walked = @($els).Count; Depth = [int]$uDepth; Roots = @($rr.Roots).Count; Via = $rr.Via }
      }
      $uFloor = Get-UiaReprobeFloor
      $us = Search-UiaTree $uwf $Rest[1] $typeRe $uFloor
      foreach ($el in @($us.Hits)) { Uia-Line $el 0 }
      "scanned $($us.Scanned) elements in $($us.Roots) root(s) via=$($us.Via), walk-depth=$(Format-UiaWalkDepth ([int](Get-OptValue $us 'Depth'))), hits=$( @($us.Hits).Count) - walks=$($us.Walks) reprobe-floor=$uFloor cold-zero-reprobe=$($us.Reprobe)"
      if (@($us.Hits).Count -eq 0) {
        # Zero is never evidence of absence (the standing rule of this project), and after
        # a re-contact it is not a cold-start artifact either - say which, and hand the
        # caller the OCR road instead of letting them fall back to eyeballing a screenshot.
        "NOTE: $($us.Reason). UIA exposes no element whose Name contains this text - that is NOT proof it is not on screen: it may be painted without a control, sit in a web document the tree has not lit, or live in a Value/HelpText instead of a Name. Next road: find-text <sel> <text> (or 'find', which tries UIA and OCR and reports which one answered)."
      }
}

# v4.4.0 (A-15): uia-click - body verbatim from the case, plus the flag the G-17 ruling allows
function Invoke-Handler-uia-click([string]$Cmd, [string[]]$Rest, [ref]$SkipTail) {
      # v2.4.0 path-handle form routed to Invoke-UiaClickByPath: the @ prefix is
      # the ONLY routing mark, so without it the historical nameSub route below
      # runs with unchanged semantics.
      if ($Rest.Count -ge 2 -and "$($Rest[1])".StartsWith('@')) { Invoke-UiaClickByPath $Rest; $SkipTail.Value = $true; return }
      if ($Rest.Count -lt 2) { throw 'usage: uia-click <sel> <nameSub>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      $rr = Uia-Roots $w
      if ($rr.Roots.Count -lt 1) { throw "no UIA root for pid $($w.Pid)" }
      $el = Uia-Find $rr.Roots $Rest[1] 'Button|MenuItem|ListItem|TabItem|Hyperlink|Text|Edit|ComboBox|CheckBox|RadioButton'
      if (-not $el) { throw "no clickable element matching: $($Rest[1])" }
      # v3.0.1 (audit #7): this route used to carry its OWN copy of the click tail, which
      # is how the same missing-rectangle bug lived in two places. Both routes now run
      # through Invoke-UiaClickable, so both refuse the same way.
      Invoke-UiaClickable $el
}

# v4.4.0 (A-15): uia-focus - body verbatim from the case, plus the flag the G-17 ruling allows
function Invoke-Handler-uia-focus([string]$Cmd, [string[]]$Rest, [ref]$SkipTail) {
      # v2.4.0 path-handle form: same @-prefix routing as uia-click.
      if ($Rest.Count -ge 2 -and "$($Rest[1])".StartsWith('@')) { Invoke-UiaFocusByPath $Rest; $SkipTail.Value = $true; return }
      if ($Rest.Count -lt 2) { throw 'usage: uia-focus <sel> <nameSub>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      $rr = Uia-Roots $w
      if ($rr.Roots.Count -lt 1) { throw "no UIA root for pid $($w.Pid)" }
      $el = Uia-Find $rr.Roots $Rest[1] ''
      if (-not $el) { throw "no element matching: $($Rest[1])" }
      $el.SetFocus()
      "focused element: $($Rest[1])"
}

# v4.4.0 (A-15): uia-settext - body verbatim from the case, plus the flag the G-17 ruling allows
function Invoke-Handler-uia-settext([string]$Cmd, [string[]]$Rest, [ref]$SkipTail) {
      # uia-settext <sel> <nameSub> <file> - ValuePattern.SetValue with the UTF-8
      # content of <file>; no keyboard, no clipboard. Readback-verified.
      # v2.4.0 path-handle form: uia-settext <sel> @/0/2/1 <file> "Type|nameSub|X,Y,WxH".
      if ($Rest.Count -ge 2 -and "$($Rest[1])".StartsWith('@')) { Invoke-UiaSettextByPath $Rest $Cmd; $SkipTail.Value = $true; return }
      if ($Rest.Count -lt 3) { throw 'usage: uia-settext <sel> <nameSub> <file>' }
      $w = Resolve-Window $Rest[0]
      if (-not $w) { throw "no window matching: $($Rest[0])" }
      if (-not (Test-Path -LiteralPath $Rest[2] -PathType Leaf)) { throw "file not found: $($Rest[2])" }
      # v1.5.2 WP-5: same strict UTF-8 gate as paste (audit R-11) - a GBK/ANSI
      # file must not be written into a real control as mojibake.
      $text = (Read-SendFileUtf8 $Rest[2]).Text
      $rr = Uia-Roots $w
      if ($rr.Roots.Count -lt 1) { throw "no UIA root for pid $($w.Pid)" }
      # Element pick: pass 1 = name match with a settable ValuePattern (edit
      # boxes often carry their current value as Name, so pass 2 also looks
      # for a settable descendant inside any name-matched container, e.g. the
      # "filename:" label/host pane of a save dialog).
      # v3.0.1 (audit #1): both tests below shipped as `Test-NameSubstring  ` with NO
      # arguments from the commit that introduced them (0e90ca5, v2.0.0). PowerShell
      # binds the missing parameters to $null, the helper answers $false for a null
      # name, and the nameSub route therefore always fell through to
      # "no element matching" - the @path form was the only working uia-settext.
      $all = Uia-WalkAll $rr.Roots
      $el = $null
      $named = $null   # first element whose Name matches, even if not settable
      foreach ($cand in $all) {
        $cn = ''
        try { $cn = $cand.Current.Name } catch { }
        if ((Test-NameSubstring $cn $Rest[1])) {
          if ($null -eq $named) { $named = $cand }
          if ($null -ne (Uia-SettableValue $cand)) { $el = $cand; break }
        }
      }
      if (-not $el) {
        foreach ($cand in $all) {
          $cn = ''
          try { $cn = $cand.Current.Name } catch { }
          if ((Test-NameSubstring $cn $Rest[1])) {
            foreach ($d in (Uia-WalkAll @($cand))) {
              if ($null -ne (Uia-SettableValue $d)) { $el = $d; break }
            }
            if ($el) { break }
          }
        }
      }
      if (-not $el) {
        if ($null -ne $named) {
          $nn = ''
          try { $nn = $named.Current.Name } catch { }
          throw "element '$nn' matched but exposes no settable ValuePattern; fall back to: click the field then paste <file>"
        }
        throw "no element matching: $($Rest[1])"
      }
      $nm = ''
      try { $nm = $el.Current.Name } catch { }
      Log-Action $Rest "pid=$($w.Pid) title='$($w.Title)' element='$nm' file=$($Rest[2])" $Cmd
      $via = ''
      $vp = Uia-SettableValue $el
      if ($null -ne $vp) {
        $vp.SetValue($text)
        $via = 'ValuePattern'
      } else {
        # TextPattern is checked for diagnostics only - it exposes no setter.
        $tp = $null
        try { $tp = $el.GetCurrentPattern([System.Windows.Automation.TextPattern]::Pattern) } catch { }
        if ($null -ne $tp) {
          throw "element '$nm' exposes TextPattern but no settable ValuePattern; fall back to: click the field then paste <file>"
        }
        throw "element '$nm' exposes no settable text pattern; fall back to: click the field then paste <file>"
      }
      $back = $null
      try { $back = $el.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern).Current.Value } catch { }
      if ($null -eq $back) { try { $back = $el.Current.Name } catch { } }
      if ($back -ne $text) { throw "uia-settext readback mismatch on element '$nm' (wrote $($text.Length) chars)" }
      "set text via $via on element '$nm': wrote $($text.Length) chars, readback match=True"
}

# v4.4.0 (A-15): type - the case body, verbatim
function Invoke-Handler-type([string]$Cmd, [string[]]$Rest) {
      # type [--to <sel>] <text...> [--verify] [--guard-text <s>|--guard-region x,y,w,h=s] [--force]
      # v1.3.0: chars go out via SendInput KEYEVENTF_UNICODE - they bypass the
      # IME entirely (no candidate window) and work for CJK as well as ASCII.
      # The payload is literal (no SendKeys escaping); control combos still
      # belong to `keys`. --verify OCR-reads the target window afterwards.
      $p = Split-Target $Rest
      if ($p.Words.Count -lt 1) { throw 'usage: type [--to <sel>] <text...> [--verify] [--guard-text <s>|--guard-region x,y,w,h=s] [--force]' }
      $text = ($p.Words -join ' ')
      $target = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
      Emit-ResolveNote
      Invoke-ContentGuard $target $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      Log-Action (Get-RedactedLogArgs $Rest $p.Words $p.LogPayload) "pid=$($target.Pid) title='$($target.Title)'" $Cmd
      $err = [DT]::SendUnicodeText($text)
      if ($err) { throw "type: $err" }
      Start-Sleep -Milliseconds 300
      $ver = ''
      if ($p.Verify) { $ver = Invoke-TypedVerify $target $text $p.VerifyTimeout }
      $warn = Test-PostSendForeground $target $p.Force
      "typed $($text.Length) chars (unicode SendInput, IME bypassed), target pid=$($target.Pid) title='$($target.Title)'  (foreground after send: $(Get-ForegroundInfo))$ver"
      Invoke-ActionExpectation $p $target 'typed'
      if ($warn) { Write-Output $warn; if ($warn -notlike 'NOTICE*') { exit 1 } }
}

# v4.4.0 (A-15): type-in - the case body, verbatim
function Invoke-Handler-type-in([string]$Cmd, [string[]]$Rest) {
      # type-in <x> <y> [--tab <n>] <text...> [--verify]
      # Compound command for webview/Electron forms where a click only produces
      # a selection state and never gives the input element keyboard focus:
      # click the spot -> optionally send <n> TABs to move focus to the real
      # input -> type. Text goes via SendInput Unicode (IME bypassed); the TABs
      # stay SendKeys because they are keys, not characters. For CJK payloads
      # this now works directly - no clipboard detour needed.
      # v1.5.7 (J-06): --tab comes from the flag table (range-checked, default 0, and it can
      # no longer be fed a flag as its value). The payload/verify parsing below stays here
      # because type-in never calls Split-Target - see Get-CommandSharedMap.
      $own = Strip-OwnFlags $Rest 'type-in'
      $ti = @($own.Rest)
      if ($ti.Count -lt 3) { throw 'usage: type-in <x> <y> [--tab <n>] <text...> [--verify] [--verify-timeout <sec>] [--log-payload]  (a literal -- payload goes through --needle)' }
      $x = [int]$ti[0]; $y = [int]$ti[1]
      $words = @($ti[2..($ti.Count - 1)])
      $tabs = [int]$own.Values['--tab']
      $verify = $false
      $logPayload = $false
      # v1.5.3: --verify-timeout is honoured here too (same default 4s as type)
      $vTimeout = 4
      $out = New-Object System.Collections.ArrayList
      $wi = 0
      while ($wi -lt $words.Count) {
        $t = "$($words[$wi])"
        if ($t -eq '--verify') { $verify = $true }
        elseif ($t -eq '--log-payload') { $logPayload = $true }
        elseif ($t -eq '--verify-timeout') {
          $wi++
          if ($wi -ge $words.Count) { throw 'type-in: --verify-timeout needs seconds (e.g. --verify-timeout 8)' }
          if ("$($words[$wi])" -notmatch '^[0-9]+(\.[0-9]+)?$') { throw "type-in: --verify-timeout needs a number of seconds, got: $($words[$wi])" }
          $vTimeout = Read-FlagNumber '--verify-timeout' $words[$wi] $false '(seconds)'
          if ($vTimeout -lt 0.5) { throw "type-in: --verify-timeout must be >= 0.5 seconds (the check polls every 400ms), got: $vTimeout" }
        }
        elseif ($t -eq '--needle') {
          # v1.5.3: the same escape route the rest of the grammar offers. Without
          # it, adding the unknown-flag throw below would make a literal '--xxx'
          # payload impossible to type through type-in (it used to fall through
          # into the text untouched, which is also why a mistyped flag name could
          # be typed into a real window).
          $wi++
          if ($wi -ge $words.Count) { throw 'type-in: --needle needs a value' }
          [void]$out.Add("$($words[$wi])")
        }
        elseif ($t -like '--*') { throw (Get-UnknownFlagMessage 'type-in' $t) }
        else { [void]$out.Add($t) }
        $wi++
      }
      $words = @($out)
      if ($words.Count -lt 1) { throw 'usage: type-in <x> <y> [--tab <n>] <text...> [--verify] [--verify-timeout <sec>] [--log-payload]' }
      $text = ($words -join ' ')
      Log-Action (Get-RedactedLogArgs $Rest $words $logPayload) "click=$x,$y tabs=$tabs" $Cmd
      Move-Click $x $y 'left'
      $before = Get-ForegroundInfo
      for ($t = 0; $t -lt $tabs; $t++) {
        [System.Windows.Forms.SendKeys]::SendWait('{TAB}')
        Start-Sleep -Milliseconds 120
      }
      $err = [DT]::SendUnicodeText($text)
      if ($err) { throw "type-in: $err" }
      Start-Sleep -Milliseconds 300
      $ver = ''
      if ($verify) {
        $fgH = [DT]::GetForegroundWindow()
        $fgw = @(Get-WinList | Where-Object { $_.Handle -eq $fgH })[0]
        $ver = Invoke-TypedVerify $fgw $text $vTimeout
      }
      "type-in: clicked ($x,$y), tabs=$tabs, typed $($text.Length) chars (unicode SendInput)  (fg before: $before; fg after: $(Get-ForegroundInfo))$ver"
}

# v4.4.0 (A-15): keys - the case body, verbatim
function Invoke-Handler-keys([string]$Cmd, [string[]]$Rest) {
      # keys [--to <sel>] <spec> [--guard-text <s>|--guard-region x,y,w,h=s] [--force]
      $p = Split-Target $Rest
      if ($p.Words.Count -lt 1) { throw 'usage: keys [--to <sel>] <spec> [--guard-text <s>|--guard-region x,y,w,h=s] [--force]' }
      $spec = $p.Words[0]
      $target = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
      Emit-ResolveNote
      Invoke-ContentGuard $target $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      Log-Action (Get-RedactedLogArgs $Rest @($spec) $p.LogPayload) "pid=$($target.Pid) title='$($target.Title)'" $Cmd
      [System.Windows.Forms.SendKeys]::SendWait($spec)
      Start-Sleep -Milliseconds 300
      $warn = Test-PostSendForeground $target $p.Force
      "sent keys '$spec', target pid=$($target.Pid) title='$($target.Title)'  (foreground after send: $(Get-ForegroundInfo))"
      Invoke-ActionExpectation $p $target 'sent keys'
      if ($warn) { Write-Output $warn; if ($warn -notlike 'NOTICE*') { exit 1 } }
}

# v4.4.0 (A-15): ime - the case body, verbatim
function Invoke-Handler-ime([string]$Cmd, [string[]]$Rest) {
      # ime - read-only: which keyboard layout/IME the FOREGROUND window's
      # thread is using. ime=yes means SendKeys-based `keys` can be swallowed
      # (type no longer cares: it bypasses the IME via SendInput Unicode).
      $f = Get-FgThreadInfo
      "foreground pid=$($f.Pid) title='$($f.Title)'  $(Format-Hkl $f.Hkl)"
}

# v4.4.0 (A-15): paste - the case body, verbatim
function Invoke-Handler-paste([string]$Cmd, [string[]]$Rest) {
      # paste [--to <sel>] <file> [--guard-text <s>|--guard-region x,y,w,h=s] [--force]
      # reads UTF-8, clipboard + Ctrl+V. v1.3.0 note: `type` now handles CJK
      # directly (SendInput Unicode) - paste stays the path for apps that only
      # accept clipboard input or for very long/multiline payloads.
      $p = Split-Target $Rest
      if ($p.Words.Count -lt 1) { throw 'usage: paste [--to <sel>] <file> [--guard-text <s>|--guard-region x,y,w,h=s] [--expect <s>|--expect-gone <s>|--expect-region x,y,w,h=s] [--timeout s] [--interval ms] [--no-expect] [--force]' }
      $file = $p.Words[0]
      if (-not (Test-Path $file)) { throw "file not found: $file" }
      $target = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
      Emit-ResolveNote
      # Guard BEFORE touching the clipboard: a failed guard must leave the
      # user's clipboard and the target both untouched.
      Invoke-ContentGuard $target $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      # v1.5.2 WP-5: strict UTF-8 read - an ANSI/GBK file must error out, not
      # paste garbage into the user's target window. Read BEFORE the clipboard
      # snapshot and the audit line: a rejected file changes nothing at all.
      $readRes = Read-SendFileUtf8 $file
      $text = $readRes.Text
      $bomNote = ''
      if ($readRes.HadBom) { $bomNote = ' [UTF-8 BOM stripped]' }
      $clip = Save-ClipboardState
      Log-Action (Get-RedactedLogArgs $Rest @() $p.LogPayload) "pid=$($target.Pid) title='$($target.Title)' file=$file" $Cmd
      # v2.2.0 (plan doc 3): the receipt half is measured BEFORE the send so the comparison is
      # honest, and only when the payload is long enough that a chip fold is possible - a short
      # payload pays nothing and keeps the verbatim-only judgement.
      $rcpBase = Get-PasteReceiptBaseline $p $target $text
      Set-Clipboard -Value $text
      Start-Sleep -Milliseconds 400
      [System.Windows.Forms.SendKeys]::SendWait('^v')
      Start-Sleep -Milliseconds 500
      $restoreNote = Restore-ClipboardState $clip
      $warn = Test-PostSendForeground $target $p.Force
      "pasted $($text.Length) chars from $file$bomNote, target pid=$($target.Pid) title='$($target.Title)'  (foreground after send: $(Get-ForegroundInfo))  [$restoreNote]"
      Invoke-ActionExpectation $p $target 'pasted'
      # v1.5.9 (P-1, default-on per owner ruling): with no expect flag given, prove the
      # payload landed by OCR-reading its tail back from the target; unreadable = WARN
      # + exit 1 (via the throw below, so script steps record a FAIL instead of dying).
      # --no-expect restores the send-only contract; actions.log gets the char count only.
      $auto = Invoke-AutoPasteExpect $p $target (Get-AutoExpectNeedle $text) $rcpBase $text.Length
      if ($auto.Ran) {
        Log-Action @("autoexpect=$($auto.NeedleChars)chars", "readback=$($auto.Criterion)") "target pid=$($target.Pid) verified=$(if ($auto.Ok) { 'yes' } else { 'no' })" $Cmd
        # The knob and the numbers it judged are both spoken - a receipt accepted on a
        # baseline nobody printed is the same unauditable judgement this repo keeps hunting.
        if ($null -ne $rcpBase) {
          Write-Output ('      receipt: fold-threshold=' + (Get-PasteFoldThreshold) + ' payload=' + $text.Length + 'chars baseline(nodes=' + $rcpBase.Nodes + ', h=' + $rcpBase.H + ', lines=' + $rcpBase.Lines + ')')
        }
        Write-Output $auto.Message
        Confirm-AutoExpect $auto
      }
      if ($warn) { Write-Output $warn; if ($warn -notlike 'NOTICE*') { exit 1 } }
}

# v4.4.0 (A-15): paste-file - the case body, verbatim
function Invoke-Handler-paste-file([string]$Cmd, [string[]]$Rest) {
      # paste-file [--to <sel>] <path> [--guard-text <s>|--guard-region x,y,w,h=s] [--force]
      # = copy-file + foreground guard + content guard + Ctrl+V, previous
      # clipboard restored. --guard-text/--guard-region are the "am I really
      # talking to the right conversation" check: the file goes out only if the
      # needle is visible in the target window (probed incident: a guard-green
      # window whose active chat had silently switched to a private friend).
      $p = Split-Target $Rest
      if ($p.Words.Count -lt 1) { throw 'usage: paste-file [--to <sel>] <path> [--guard-text <s>|--guard-region x,y,w,h=s] [--expect <s>|--expect-gone <s>|--expect-region x,y,w,h=s] [--timeout s] [--interval ms] [--no-expect] [--force]' }
      if (-not (Test-Path -LiteralPath $p.Words[0] -PathType Leaf)) { throw "file not found: $($p.Words[0])" }
      $fi = Get-Item -LiteralPath $p.Words[0]
      $target = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
      Emit-ResolveNote
      Invoke-ContentGuard $target $p.GuardText $p.GuardRegion $p.Scale $p.MaxTiles $p.NoTile $p.Occlude $p.AllowOccluded $p.OcclGrid
      $clip = Save-ClipboardState
      Log-Action (Get-RedactedLogArgs $Rest @() $p.LogPayload) "pid=$($target.Pid) title='$($target.Title)' file=$($fi.FullName)" $Cmd
      $ok = Set-ClipboardFileDrop $fi.FullName
      if (-not $ok) { throw "clipboard verification failed for: $($fi.FullName)" }
      [System.Windows.Forms.SendKeys]::SendWait('^v')
      Start-Sleep -Milliseconds 500
      $restoreNote = Restore-ClipboardState $clip
      $warn = Test-PostSendForeground $target $p.Force
      "pasted file $($fi.Name) bytes=$($fi.Length), target pid=$($target.Pid) title='$($target.Title)'  (foreground after send: $(Get-ForegroundInfo))  [$restoreNote]"
      Invoke-ActionExpectation $p $target 'pasted file'
      # v1.5.9 (P-1): same default-on readback as paste; the FileDrop's name is the
      # payload handle the target renders, so the needle comes from the file name.
      $auto = Invoke-AutoPasteExpect $p $target (Get-AutoExpectNeedle $fi.Name)
      if ($auto.Ran) {
        Log-Action @("autoexpect=$($auto.NeedleChars)chars") "target pid=$($target.Pid) verified=$(if ($auto.Ok) { 'yes' } else { 'no' })" $Cmd
        Write-Output $auto.Message
        Confirm-AutoExpect $auto
      }
      if ($warn) { Write-Output $warn; if ($warn -notlike 'NOTICE*') { exit 1 } }
}

# v4.4.0 (A-15): copy-file - the case body, verbatim
function Invoke-Handler-copy-file([string]$Cmd, [string[]]$Rest) {
      # copy-file <path> - put a local file on the clipboard as FileDrop and
      # verify the drop list really contains it. Deliberately does NOT restore
      # the previous clipboard: leaving the file there is the point of this
      # command (paste / paste-file do restore).
      if ($Rest.Count -lt 1) { throw 'usage: copy-file <path>' }
      if (-not (Test-Path -LiteralPath $Rest[0] -PathType Leaf)) { throw "file not found: $($Rest[0])" }
      $fi = Get-Item -LiteralPath $Rest[0]
      Log-Action $Rest "file=$($fi.FullName) bytes=$($fi.Length)" $Cmd
      $ok = Set-ClipboardFileDrop $fi.FullName
      if (-not $ok) { throw "clipboard verification failed for: $($fi.FullName)" }
      "copied $($fi.Name)  bytes=$($fi.Length)  clipboard verified: $($fi.FullName)"
}


# lib/handlers-batch.ps1 - the batch-group handlers, lifted out of desktop.ps1 (A-17..A-19 line).
#    Byte-identical to what the dispatcher carried after A-15 pen 2: the union of the lifted lines was
#    hashed before the cut and the same bytes are re-hashed from this file afterwards (printed by
#    handler-lift.js, and recorded in the ledger row for this card). The group membership is declared in
#    $script:StHandlerGroups and reconciled against the definitions by lint (A-16) - this file is named in
#    $script:StHandlerFiles in the same write that removes the code from the entry, so neither half can
#    land on its own.

# v4.4.0 (A-15): imgclick - the case body, verbatim
function Invoke-Handler-imgclick([string]$Cmd, [string[]]$Rest) {
      # imgclick <outPath> <ix> <iy> [--to <sel>] [--expect <needle>|--expect-gone <needle>] [--dry] [--allow-outside] [--stale-ok]
      # v1.5.0 WP-3: reverse-map an image pixel through <outPath>.map.txt and
      # click the derived screen point. Replaces painted-out ix/scale math;
      # --dry prints the mapping and stops. A missing sidecar is a hard error.
      # v1.5.1 WP-B: the sidecar is validated against the window's CURRENT rect
      # before anything is clicked - a window that moved/resized since capture
      # (>2px) is refused instead of silently clicked at the stale position;
      # --stale-ok maps against the old origin anyway. rect/zoom captures have
      # no host window and say so in the echo (staleness not verifiable).
      $own = Strip-OwnFlags $Rest 'imgclick'
      $dry = [bool]$own.Values['--dry']
      $staleOk = [bool]$own.Values['--stale-ok']
      $p = Split-Target @($own.Rest) 'imgclick'
      if ($p.Words.Count -ne 3) { throw 'usage: imgclick <outPath> <ix> <iy> [--to <sel>] [--expect <needle>|--expect-gone <needle>] [--dry] [--allow-outside] [--stale-ok]' }
      $img = $p.Words[0]
      $ix = [int]$p.Words[1]; $iy = [int]$p.Words[2]
      $map = Read-MapSidecar $img
      if ($ix -lt 0 -or $ix -ge $map.OutW -or $iy -lt 0 -or $iy -ge $map.OutH) { throw "imgclick: image coords ($ix,$iy) outside $($map.OutW)x$($map.OutH) of $img" }
      $st = Test-MapSidecarStale $map
      if ($st.Verdict -eq 'gone') { throw "imgclick: $($st.Msg)" }
      if ($st.Verdict -eq 'stale' -and -not $staleOk) { throw "imgclick: $($st.Msg)" }
      $sp = Convert-ImageToScreen $map $ix $iy
      $staleNote = ''
      if ($st.Verdict -eq 'unverifiable') { $staleNote = "  ($($st.Msg))" }
      elseif ($st.Verdict -eq 'stale') { $staleNote = "  [stale-ok] $($st.Msg)" }
      # v1.5.7 (D-6, owner's added condition): grid lines are painted ON this image, so a
      # point read off it can land on a line. Silently mapping it through would be the
      # same class of lie as an unstated truncation.
      $gridWarn = $(if ($map.Grid -gt 0) { "  WARNING: source image carries a grid overlay (step=$($map.Grid)px, labelled in screen coords) - a point measured off it may sit on a grid line; read the labels or prefer find-text <small region> --needle <text>" } else { '' })
      # v1.7.0 (J-07 A, "do not lose" #1): the echo must carry the mapping provenance -
      # which sidecar, and the actual image->screen formula (scale-aware: 1:1 wins read
      # "screen = image + (L,T)", scaled rect/zoom reads "screen = image / k + (L,T)").
      $mapForm = $(if ($map.Scale -eq 1) { "screen = image + ($($map.OriginX),$($map.OriginY))" } else { "screen = image / $($map.Scale) + ($($map.OriginX),$($map.OriginY))" })
      "imgclick: $img ($($map.OutW)x$($map.OutH) kind=$($map.Kind) scale=$($map.Scale)) image ($ix,$iy) -> screen ($($sp.X),$($sp.Y))  [map: $img.map.txt; $mapForm]$staleNote$gridWarn"
      if ($dry) {
        "  [dry run] not clicked"
      } else {
        $tgt = $null
        if ($p.Sel) {
          $tgt = Resolve-Target $p.Sel $p.Force $p.AlwaysActivate $p.ExpectHandle
          Emit-ResolveNote
        }
        Invoke-HitWindowCheck $sp.X $sp.Y $tgt ($p.Sel -ne '') $p.AllowOutside
        Log-Action (Get-RedactedLogArgs $Rest @() $p.LogPayload) "img=$img ix=$ix iy=$iy -> $($sp.X),$($sp.Y)" $Cmd
        Move-Click $sp.X $sp.Y 'left'
        "clicked $($sp.X),$($sp.Y)"
        Invoke-ActionExpectation $p $tgt 'clicked'
      }
}

# v4.4.0 (A-15): zoom - the case body, verbatim
function Invoke-Handler-zoom([string]$Cmd, [string[]]$Rest) {
      # zoom <x> <y> <w> <h> [scale] [outPath] - capture a small region and
      # enlarge it (NearestNeighbor) so tiny text/buttons are readable in one
      # shot instead of iterating manual rect crops. Echo gives the mapping
      # back to screen pixels: screen = (x + ix/scale, y + iy/scale).
      if ($Rest.Count -lt 4) { throw 'usage: zoom <x> <y> <w> <h> [scale] [outPath]' }
      $x = [int]$Rest[0]; $y = [int]$Rest[1]; $w = [int]$Rest[2]; $h = [int]$Rest[3]
      if ($w -le 0 -or $h -le 0) { throw 'zoom: w and h must be positive' }
      $scale = 2.0; $path = ''
      if ($Rest.Count -gt 4) {
        foreach ($a in @($Rest[4..($Rest.Count - 1)])) {
          if ($a -match '^\d+(\.\d+)?$') { $scale = [double]$a }
          elseif (-not $path) { $path = $a }
        }
      }
      if ($scale -lt 1 -or $scale -gt 8) { throw 'zoom: scale must be within 1..8' }
      if (-not $path) { $path = Default-ShotName 'zoom' }
      Ensure-OutDir
      $src = New-Object System.Drawing.Bitmap($w, $h)
      $gs = [System.Drawing.Graphics]::FromImage($src)
      $gs.CopyFromScreen($x, $y, 0, 0, (New-Object System.Drawing.Size($w, $h)))
      $gs.Dispose()
      $ow = [int]($w * $scale); $oh = [int]($h * $scale)
      $dst = New-Object System.Drawing.Bitmap($ow, $oh)
      $gd = [System.Drawing.Graphics]::FromImage($dst)
      $gd.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor
      $gd.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::Half
      $gd.DrawImage($src, 0, 0, $ow, $oh)
      $gd.Dispose(); $src.Dispose()
      $dst.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
      $dst.Dispose()
      $size = (Get-Item -LiteralPath $path).Length
      Write-MapSidecar $path $x $y $scale $ow $oh 'zoom'
      "saved $path  src=($x,$y) ${w}x${h} scale=${scale}x image=${ow}x${oh}  bytes=$size"
      "click mapping: screen = ($x + ix/$scale, $y + iy/$scale)  (ix,iy = pixel in zoom image)"
      "map: $path.map.txt  (imgclick <image> <ix> <iy> maps back and clicks; unmap prints only)"
}

# v4.4.0 (A-15): ime-en - the case body, verbatim
function Invoke-Handler-ime-en([string]$Cmd, [string[]]$Rest) {
      # ime-en - actively switch the foreground IME to alphanumeric (English)
      # and POLL-VERIFY; some TSF IMEs ignore the control message, and the
      # verification turns that into an honest ERROR instead of a false OK.
      $f = Get-FgThreadInfo
      $orig = Get-ImeMode $f.Hwnd
      if ($orig -lt 0) { throw "no default IME window for pid=$($f.Pid) title='$($f.Title)'" }
      if ($orig -eq 0) { "already alphanumeric: pid=$($f.Pid) title='$($f.Title)'"; exit 0 }
      if (Set-ImeModeVerified $f.Hwnd 0) {
        "ime-en: pid=$($f.Pid) title='$($f.Title)' now alphanumeric (previous $(Format-ImeMode $orig); restore with: ime-cn 0x$($orig.ToString('X')))"
      } else {
        throw "ime-en: IME did not accept the switch (mode still $(Format-ImeMode (Get-ImeMode $f.Hwnd))); switch manually (Ctrl+Space / Shift) or use paste"
      }
}

# v4.4.0 (A-15): ime-cn - the case body, verbatim
function Invoke-Handler-ime-cn([string]$Cmd, [string[]]$Rest) {
      # ime-cn - switch back to a Chinese (native) conversion mode and verify.
      # Default 0x1 (native, halfwidth symbols); pass the exact mode that
      # ime-en reported to restore it bit-exact, e.g. ime-cn 0x401.
      $f = Get-FgThreadInfo
      $mode = 0x1
      if ($Rest.Count -ge 1 -and $Rest[0]) { $mode = [Convert]::ToInt32(($Rest[0] -replace '^0x', ''), 16) }
      if (Set-ImeModeVerified $f.Hwnd $mode) {
        "ime-cn: pid=$($f.Pid) title='$($f.Title)' now $(Format-ImeMode $mode)"
      } else {
        throw "ime-cn: IME did not accept the switch (mode still $(Format-ImeMode (Get-ImeMode $f.Hwnd)))"
      }
}

# v4.4.0 (A-15): ime-state - the case body, verbatim
function Invoke-Handler-ime-state([string]$Cmd, [string[]]$Rest) {
      # ime-state - the CONVERSION mode (Chinese composition vs alphanumeric)
      # of the foreground thread's IME, which the HKL cannot show. Read via the
      # default IME window (sub-codes probed live, see Get-ImeMode).
      $f = Get-FgThreadInfo
      $mode = Get-ImeMode $f.Hwnd
      if ($mode -lt 0) { throw "no default IME window for pid=$($f.Pid) title='$($f.Title)'" }
      if ($script:Json) {
        Get-ImeStateView $f.Pid $f.Title $mode | ConvertTo-Json -Compress
      } else {
        "foreground pid=$($f.Pid) title='$($f.Title)'  $(Format-ImeMode $mode)  (0 = type English directly; native = IME composes)"
      }
}

# v4.4.0 (A-15): challenge-probe - the case body, verbatim
function Invoke-Handler-challenge-probe([string]$Cmd, [string[]]$Rest) {
      # challenge-probe <sel> [--allow-attempt --attempt-click x,y]
      # READ-ONLY by default: whole-window OCR, match the challenge corpus, report
      # type/confidence/staleness and the human-handoff block. The window's pixels are
      # hashed and recorded so a challenge that sits unchanged across calls reads as
      # STALE (expired ticket - dismiss it, do not solve it). --allow-attempt arms the
      # ONE authorized interaction: a single caller-named click inside this window;
      # if the challenge survives it, a fuse is recorded and every later attempt on
      # the same challenge image is refused. No solver exists here by design.
      $cpAllow = $false; $cpClick = $null
      $cpWords = @($Rest)
      if ($cpWords.Count -lt 1) { throw 'usage: challenge-probe <sel> [--allow-attempt --attempt-click x,y]' }
      $cpSel = "$($cpWords[0])"
      for ($cpi = 1; $cpi -lt $cpWords.Count; $cpi++) {
        $t = "$($cpWords[$cpi])"
        if ($t -eq '--allow-attempt') { $cpAllow = $true }
        elseif ($t -eq '--attempt-click') {
          $cpi++
          if ($cpi -ge $cpWords.Count) { throw 'challenge-probe: --attempt-click needs x,y' }
          $cpParts = "$($cpWords[$cpi])" -split ','
          if (@($cpParts).Count -ne 2 -or @($cpParts | Where-Object { $_ -match '^\d+$' }).Count -ne 2) { throw "challenge-probe: --attempt-click expects x,y (window-relative pixels), got: $($cpWords[$cpi])" }
          $cpClick = @{ X = [int]$cpParts[0]; Y = [int]$cpParts[1] }
        }
        else { throw "challenge-probe: unknown flag '$t' (valid: --allow-attempt | --attempt-click x,y)" }
      }
      if ($cpAllow -and ($null -eq $cpClick)) { throw 'challenge-probe: --allow-attempt also needs --attempt-click x,y - an authorized attempt is ONE caller-named click, never a free hand' }
      $cw = Resolve-Window $cpSel
      if (-not $cw) { throw "no window matching: $cpSel" }
      # hash + OCR read the CLIENT area, not the frame: a focus flip repaints the title
      # bar and would make an unchanged challenge read as changed (measured: stale=False
      # on the second sample of a static image when the window lost focus in between)
      $cpCr = New-Object DT+RECT
      [void][DT]::GetClientRect($cw.Handle, [ref]$cpCr)
      $cpPt = New-Object DT+POINT
      [void][DT]::ClientToScreen($cw.Handle, [ref]$cpPt)
      $cpCx = [int]$cpPt.X; $cpCy = [int]$cpPt.Y
      $cpCw = [int]($cpCr.Right - $cpCr.Left); $cpCh = [int]($cpCr.Bottom - $cpCr.Top)
      $cpLines = Invoke-OcrRegion $cpCx $cpCy $cpCw $cpCh
      $cpVerdict = Test-ChallengeLines $cpLines
      # v3.1.0 (P-05): two full client-area captures (CopyFromScreen + PNG encode + MD5) used to
      # run here and be discarded - staleness is decided by the IDENTITY hash below (the challenge
      # text), never by pixels. Nothing ever read them (measured: two assignments, zero uses), so
      # every challenge-probe call paid for two screenshots to throw the bytes away. A lint now
      # refuses the shape "assigned and never read" for this name again.
      $cpHash = Get-ChallengeIdentityHash $cpVerdict
      # v4.0.1 (audit finding 2): the file's own existence is asked separately from whether this
      # call could read it, because "never logged" and "could not read" are different answers and
      # only the first one may be reported as first-seen.
      $cpLogExists = [bool](Test-Path -LiteralPath $ActionLog)
      $cpLogErr = ''
      $cpLog = @()
      if ($cpLogExists) {
        try { $cpLog = @(Get-Content -LiteralPath $ActionLog -Encoding UTF8 -ErrorAction Stop) }
        catch { $cpLogErr = $_.Exception.Message }
      }
      $cpState = Test-ChallengeLogLines $cpLog $cw.Pid
      $cpStale = Test-ChallengeStale $cpState.LastHash $cpHash
      # v4.1.1 (self-caught, would have made the finding-2 fix decoration): the sighting line used
      # to be an UNGUARDED write that ran BEFORE the state was ever consulted. On a fully locked
      # log it threw an unrelated IOException first, so neither the honest `stale=unknown(...)`
      # echo nor the refusal below could be reached. The write is attempted here and its failure
      # is folded INTO the state - a log we cannot write is a fuse we cannot arm.
      $cpSeenErr = ''
      try { Log-Action @("pid=$($cw.Pid)") "seen hash=$cpHash" $Cmd } catch { $cpSeenErr = $_.Exception.Message }
      if ($cpStale.Stale -eq $true) { try { Log-Action @("pid=$($cw.Pid)") "stale hash=$cpHash" $Cmd } catch { } }
      $cpLogState = Resolve-ChallengeLogState $cpLogExists ($cpLogErr -eq '') ($cpSeenErr -eq '')
      if (-not $cpVerdict.Challenge) {
        $cpNote = ''
        try {
          if (Test-SparseReadability ([int]$cw.W) ([int]$cw.H) (@($cpLines).Count) 1.5) { $cpNote = ' note=large-area-unreadable' }
        } catch { }
        "challenge: none lines=$(@($cpLines).Count)$cpNote"
        exit 0
      }
      "challenge: type=$($cpVerdict.Type) confidence=$($cpVerdict.Confidence) matched=[$(@($cpVerdict.Matched) -join ', ')] lines=$(@($cpLines).Count) rect=($([int]$cw.Left),$([int]$cw.Top),$([int]$cw.W)x$([int]$cw.H))"
      $cpStaleTxt = $cpStale.Stale
      $cpLogWhy = ''
      if ($cpLogErr) { $cpLogWhy = $cpLogErr } elseif ($cpSeenErr) { $cpLogWhy = $cpSeenErr }
      if ($cpLogState -ceq 'unreadable') { $cpStaleTxt = "unknown(log-unreadable: $cpLogWhy)" }
      if ($cpLogState -ceq 'unwritable') { $cpStaleTxt = "unknown(log-unwritable: $cpLogWhy)" }
      "stale=$cpStaleTxt$(if ($cpStale.Recommend) { " recommend=$($cpStale.Recommend)" })"
      "action: DO NOT treat a needle miss on this window as 'the card is gone' - this window is covered by an in-window challenge modal; judge the underlying target only after the challenge is dismissed"
      $cpShot = Join-Path $OutDir ('challenge-' + (Get-Date -Format 'yyyyMMddTHHmmss') + '.png')
      Save-RectEx $cw.Left $cw.Top $cw.W $cw.H $cpShot 0 -1 @() | Write-Output
      @((Build-ChallengeHandoff $cpVerdict $cw ($cpHash.Substring(0, 8)) $cpShot)) | ForEach-Object { Write-Output $_ }
      if (-not $cpAllow) {
        "attempt: not authorized (pass --allow-attempt --attempt-click x,y to permit ONE caller-named click; retries escalate account risk-control). There is NO solver in this tool by design - the boundary is deliberate, see README known limitations"
        Log-Action @("pid=$($cw.Pid)") "challenge type=$($cpVerdict.Type) verdict=reported-no-attempt" $Cmd
        exit 0
      }
      # An UNKNOWN fuse is treated as ARMED. This fuse exists only because a second attempt on the
      # same challenge image escalates account risk-control, so "could not check" - whether the
      # check failed because the log would not open for READING or because it would not accept the
      # sighting WRITE - must not buy a retry. The refusal is logged best-effort, and when even
      # that write fails the thrown message says so instead of implying an audit line that exists.
      if ($cpLogState -ceq 'unreadable' -or $cpLogState -ceq 'unwritable') {
        $cpFuseNote = ''
        try { Log-Action @("pid=$($cw.Pid)") "fuse-unknown hash=$cpHash reason=log-$($cpLogState.Substring(1))" $Cmd }
        catch { $cpFuseNote = ' - and the audit line could not be written either: ' + $_.Exception.Message }
        throw "challenge attempt refused: $ActionLog could not be used to check the fuse ($cpLogWhy), so the fuse state for pid=$($cw.Pid) is UNKNOWN and an unknown fuse is treated as armed (retries escalate account risk-control)$cpFuseNote. Free the log (another process is holding it) or have a human complete or dismiss the challenge"
      }
      if ($cpState.FuseHash -eq $cpHash) {
        Log-Action @("pid=$($cw.Pid)") "fuse-blocked hash=$cpHash" $Cmd
        throw "challenge attempt refused: the fuse for this exact challenge image (pid=$($cw.Pid) hash=$($cpHash.Substring(0, 8))) is armed from a previous failed attempt - a human completes or dismisses the challenge, or it is refreshed to a new image; retries escalate account risk-control"
      }
      Log-Action @("pid=$($cw.Pid)", "attempt-click=$($cpClick.X),$($cpClick.Y)") "attempt type=$($cpVerdict.Type) pre-hash=$cpHash" $Cmd
      $cpAx = [int]($cw.Left + $cpClick.X)
      $cpAy = [int]($cw.Top + $cpClick.Y)
      $cpClickErr = ''
      try {
        $null = Invoke-DesktopCommand 'click' @([string]$cpAx, [string]$cpAy, '--to', $cpSel)
      } catch {
        # the click never landed (guards refused, window vanished, ...) - that is still
        # a FAILED attempt: arm the fuse, tell the caller why, stop touching the challenge
        $cpClickErr = "$($_.Exception.Message)"
      }
      Start-Sleep -Milliseconds 800
      $cpLines2 = Invoke-OcrRegion $cpCx $cpCy $cpCw $cpCh
      $cpVerdict2 = Test-ChallengeLines $cpLines2
      $cpHash2 = Get-ChallengeIdentityHash $cpVerdict2
      if (-not $cpVerdict2.Challenge) {
        Log-Action @("pid=$($cw.Pid)") "attempt-cleared post-hash=$cpHash2" $Cmd
        "challenge attempt: cleared (no challenge text remains after the one authorized click)"
        exit 0
      }
      Log-Action @("pid=$($cw.Pid)") "fuse hash=$cpHash2" $Cmd
      $cpEm = [string][char]0x2014
      $cpWhy = 'the challenge is still on the window after the click'
      if ($cpClickErr) { $cpWhy = "the authorized click itself failed: $cpClickErr" }
      throw ("challenge attempt FAILED $cpEm refusing further interaction with this challenge (retries escalate account risk-control); fuse armed for pid=$($cw.Pid) hash=$($cpHash2.Substring(0, 8)) - $cpWhy")
}

# v4.4.0 (A-15): shots-cleanup - the case body, verbatim
function Invoke-Handler-shots-cleanup([string]$Cmd, [string[]]$Rest) {
      # shots-cleanup [--keep N] [--go] [--quarantine <dir>]
      # v1.5.2 WP-7 (audit R-14): bound the runtime screenshot dir. DRY RUN by
      # default; --go does NOT delete - it moves the files into the machine's
      # designated quarantine folder and appends a MANIFEST.md line per file
      # (original path + SHA256 + size + times), so every move can be undone.
      # v2.5.2/v2.5.3: the --go target is no longer a machine-specific folder baked
      # into the script - precedence: explicit --quarantine > DTX_QUARANTINE process
      # env > DTX_QUARANTINE User-scope registry > Machine-scope registry, else the
      # command REFUSES (exit 2) naming both remedies and echoing no path. The
      # registry tiers exist because a process env block is a startup snapshot:
      # resident hosts predate any later User-level write, so $env: alone would
      # refuse on exactly the machine that set the variable. Dry run never needed
      # the target, so it works unchanged on a machine with nothing configured.
      $keepN = 100; $go = $false; $quarFlag = ''
      $words = @($Rest)
      for ($i = 0; $i -lt $words.Count; $i++) {
        if ($words[$i] -eq '--keep') { $i++; $keepN = Read-FlagNumber '--keep' $words[$i] $true '(images to keep)' }
        elseif ($words[$i] -eq '--go') { $go = $true }
        elseif ($words[$i] -eq '--quarantine') { $i++; $quarFlag = $words[$i] }
        else { throw "shots-cleanup: unknown flag '$($words[$i])' (valid: --keep <n> | --go | --quarantine <dir>)" }
      }
      if ($keepN -lt 0) { throw "shots-cleanup: --keep must be >= 0, got: $keepN" }
      Ensure-OutDir
      $all = @(Get-ChildItem -LiteralPath $OutDir -File | Where-Object { $_.Name -like '*.png' -or $_.Name -like '*.jpg' -or $_.Name -like '*.map.txt' })
      $plan = Get-ShotCleanupPlan $all $keepN
      "shots-cleanup: $($all.Count) capture file(s) in $OutDir, keep newest $keepN image(s) -> keep $($plan.Keep.Count), move $($plan.Move.Count) ($($plan.Bytes) bytes)"
      if ($plan.Move.Count -eq 0) { 'nothing to do'; exit 0 }
      $shown = 0
      foreach ($m in $plan.Move) {
        if ($shown -lt 12) {
          $shown++
          "  MOVE $($m.Name)  $($m.Length) bytes  $($m.LastWriteTimeUtc.ToString('yyyy-MM-dd HH:mm'))Z"
        }
      }
      if ($plan.Move.Count -gt $shown) { "  ... and $($plan.Move.Count - $shown) more" }
      if (-not $go) { 'DRY RUN - nothing moved. Pass --go to MOVE them to the quarantine folder (never delete).'; exit 0 }
      # v2.5.3: resolve the --go target here (only --go needs one). Refusal and the
      # missing-folder branch below are DIFFERENT failures and stay separate: this one
      # means "no target was configured at all", that one means "the configured target
      # is not there".
      $qResolved = Resolve-ShotsCleanupQuarantine $quarFlag
      $quar = $qResolved.Dir
      if (-not $quar) {
        Write-Output 'ERROR: shots-cleanup --go refused: no quarantine target. Pass --quarantine <dir> or set the DTX_QUARANTINE environment variable (process env or User/Machine registry scope); the baked-in machine default was removed on purpose.'
        exit 2
      }
      "shots-cleanup: quarantine target resolved by: $($qResolved.Source)"
      if (-not (Test-Path -LiteralPath $quar)) { throw "shots-cleanup: quarantine folder does not exist: $quar - create it first or pass --quarantine <existing parent>" }
      # v2.6.0: the loop moved into Move-ShotsToQuarantine so the automatic trim uses the
      # same code. The heading text, the MANIFEST format and both echo lines are unchanged.
      $qHeading = "## shots-cleanup v1.5.2 " + (Get-Date).ToUniversalTime().ToString('yyyy-MM-dd HH:mm') + " UTC (keep newest $keepN, moved $(@($plan.Move).Count))"
      $qRes = Move-ShotsToQuarantine $plan.Move $quar 'shots_' $qHeading
      foreach ($ft in @($qRes.Failures)) { "$ft" }
      Log-Action @("shots-cleanup", "--keep", "$keepN", '--go') "moved=$($qRes.Moved) failed=$($qRes.Failed) unrecorded=$(@($qRes.Unrecorded).Count) dest=$($qRes.Dest)" $Cmd
      "shots-cleanup: moved $($qRes.Moved) file(s) to $($qRes.Dest) (manifest: $($qRes.Manifest)), $($qRes.Failed) failed - nothing was deleted"
      if (@($qRes.Unrecorded).Count -gt 0) {
        # TB-3: this is not a move failure, it is an EVIDENCE failure, and the two must not share a
        # counter. The mover stopped on its own because a file it had already moved could not get its
        # MANIFEST row written - so the run that looks partially successful is the one where the undo
        # trail has a hole. Named on stdout with the entry contract's ERROR: prefix, and red.
        Write-Output "ERROR: shots-cleanup --go: $(@($qRes.Unrecorded).Count) moved file(s) have NO manifest row (manifest: $($qRes.Manifest)) - the run stopped rather than moving more files without a record"
        exit 1
      }
      if ($qRes.Failed -gt 0) {
        # v3.1.0 (P-05): the entry contract is "exit 1 AND stdout carries ERROR: ..." - the
        # summary line above is prose, so a caller that only greps for ERROR: read a partially
        # failed run as clean. The exit-2 refusal path in this same command already names itself
        # properly; only this path did not. Failures are still echoed one by one above.
        Write-Output "ERROR: shots-cleanup --go: $($qRes.Failed) move(s) FAILED, $($qRes.Moved) moved - failure lines above, manifest: $($qRes.Manifest)"
        exit 1
      }
}

# v4.4.0 (A-15): unmap - the case body, verbatim
function Invoke-Handler-unmap([string]$Cmd, [string[]]$Rest) {
      # unmap <outPath> <ix> <iy> [--stale-ok] - side-effect-free inverse mapping:
      # print the screen point for an image pixel (no click, no log). imgclick
      # minus click. v1.5.1 WP-B: same staleness contract as imgclick - a win
      # sidecar whose window moved/resized fails rather than printing a wrong
      # answer (--stale-ok overrides); rect/zoom sidecars say unverifiable.
      $own = Strip-OwnFlags $Rest 'unmap'
      $staleOk = [bool]$own.Values['--stale-ok']
      $Rest = @($own.Rest)
      if ($Rest.Count -ne 3) { throw 'usage: unmap <outPath> <ix> <iy> [--stale-ok]' }
      $map = Read-MapSidecar $Rest[0]
      $ix = [int]$Rest[1]; $iy = [int]$Rest[2]
      if ($ix -lt 0 -or $ix -ge $map.OutW -or $iy -lt 0 -or $iy -ge $map.OutH) { throw "unmap: image coords ($ix,$iy) outside $($map.OutW)x$($map.OutH) of $($Rest[0])" }
      $st = Test-MapSidecarStale $map
      if ($st.Verdict -eq 'gone') { throw "unmap: $($st.Msg)" }
      if ($st.Verdict -eq 'stale' -and -not $staleOk) { throw "unmap: $($st.Msg)" }
      $sp = Convert-ImageToScreen $map $ix $iy
      $staleNote = ''
      if ($st.Verdict -eq 'unverifiable') { $staleNote = "  ($($st.Msg))" }
      elseif ($st.Verdict -eq 'stale') { $staleNote = "  [stale-ok] $($st.Msg)" }
      # v1.5.7 (D-6): same admission as imgclick - unmap prints only, so the grid note
      # belongs on its output too (the number it prints may have been read off a line).
      $gridWarn = $(if ($map.Grid -gt 0) { "  WARNING: source image carries a grid overlay (step=$($map.Grid)px, labelled in screen coords)" } else { '' })
      "unmap: $($Rest[0]) ($($map.OutW)x$($map.OutH) kind=$($map.Kind) scale=$($map.Scale)) image ($ix,$iy) -> screen ($($sp.X),$($sp.Y))$staleNote$gridWarn"
}


# CU-CALL (v4.5.0): per-invocation caller history and overlap warnings.
# State is local to one Windows logon session and input desktop; it never lives under the repo.

if (-not ('DtxCallProcessNative' -as [type])) {
  Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class DtxCallProcessNative {
  [DllImport("kernel32.dll", SetLastError = true)]
  public static extern bool GetProcessTimes(IntPtr process, out long creation, out long exit, out long kernel, out long user);
}
"@
}

function Get-DtxCallContextValue($Context, [string]$Name, $Default = $null) {
  if (($null -ne $Context) -and ($Context -is [System.Collections.IDictionary]) -and $Context.Contains($Name)) {
    return $Context[$Name]
  }
  return $Default
}

function ConvertTo-DtxCallSafeText([string]$Value, [int]$Limit) {
  $safe = [regex]::Replace([string]$Value, '[\x00-\x1F\x7F]', ' ')
  $safe = [regex]::Replace($safe, '\s+', ' ').Trim()
  if ($safe.Length -gt $Limit) { $safe = $safe.Substring(0, $Limit) }
  return $safe
}

function Get-DtxCallSha256([string]$Value) {
  $sha = [System.Security.Cryptography.SHA256]::Create()
  try {
    $bytes = [System.Text.Encoding]::UTF8.GetBytes([string]$Value)
    return ([System.BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-', '').ToLowerInvariant()
  } finally { $sha.Dispose() }
}

function Get-DtxCallIdentity($Context = $null) {
  $explicitLabel = [string](Get-DtxCallContextValue $Context 'CallerLabel' ([Environment]::GetEnvironmentVariable('DTX_CALLER_LABEL', 'Process')))
  $explicitSession = [string](Get-DtxCallContextValue $Context 'CallerSessionId' ([Environment]::GetEnvironmentVariable('DTX_CALLER_SESSION_ID', 'Process')))
  $codexThread = [string](Get-DtxCallContextValue $Context 'CodexThreadId' ([Environment]::GetEnvironmentVariable('CODEX_THREAD_ID', 'Process')))
  $codexSession = [string](Get-DtxCallContextValue $Context 'CodexSessionId' ([Environment]::GetEnvironmentVariable('CODEX_SESSION_ID', 'Process')))
  if ($null -ne (Get-DtxCallContextValue $Context 'IdentitySource' $null)) {
    return [pscustomobject]@{
      CallerLabel = ConvertTo-DtxCallSafeText $explicitLabel 80
      CallerSessionId = ConvertTo-DtxCallSafeText $explicitSession 96
      IdentitySource = ConvertTo-DtxCallSafeText ([string]$Context.IdentitySource) 48
    }
  }
  if (($explicitLabel.Length -gt 0) -or ($explicitSession.Length -gt 0)) {
    return [pscustomobject]@{
      CallerLabel = if ($explicitLabel) { ConvertTo-DtxCallSafeText $explicitLabel 80 } else { 'unknown' }
      CallerSessionId = if ($explicitSession) { ConvertTo-DtxCallSafeText $explicitSession 96 } else { 'unknown' }
      IdentitySource = if ($explicitLabel -and $explicitSession) { 'explicit-environment' } else { 'partial-explicit-environment' }
    }
  }
  if ($codexThread.Length -gt 0) {
    return [pscustomobject]@{ CallerLabel = 'Codex'; CallerSessionId = ConvertTo-DtxCallSafeText $codexThread 96; IdentitySource = 'codex-thread-environment' }
  }
  if ($codexSession.Length -gt 0) {
    return [pscustomobject]@{ CallerLabel = 'Codex'; CallerSessionId = ConvertTo-DtxCallSafeText $codexSession 96; IdentitySource = 'codex-session-environment' }
  }
  return [pscustomobject]@{ CallerLabel = 'unknown'; CallerSessionId = 'unknown'; IdentitySource = 'unknown' }
}

function Get-DtxCallTargetSummary([string]$Command, [string[]]$Arguments) {
  $commandKey = ([string]$Command).ToLowerInvariant()
  $selector = ''
  $argsCopy = @($Arguments)
  for ($i = 0; $i -lt $argsCopy.Count; $i++) {
    if (([string]$argsCopy[$i] -ceq '--to') -or ([string]$argsCopy[$i] -ceq '--at')) {
      if (($i + 1) -lt $argsCopy.Count) { $selector = [string]$argsCopy[$i + 1] }
      break
    }
  }
  if (-not $selector -and @('focus','info','win','rect-of','assert-window','read-text','uia-tree','wait-win','wait-gone') -ccontains $commandKey) {
    if ($argsCopy.Count -gt 0 -and -not ([string]$argsCopy[0]).StartsWith('--')) { $selector = [string]$argsCopy[0] }
  }
  if ($selector) {
    $kind = if ($selector -match '^\d+$') { 'pid' }
      elseif ($selector -match '^(?i:proc):') { 'proc' }
      elseif ($selector -match '^(?i:class):') { 'class' }
      elseif ($selector -match '^(?i:(t|title)):' ) { 'title' }
      else { 'selector' }
    return ('selector-kind=' + $kind + ';selector-sha256=' + (Get-DtxCallSha256 $selector).Substring(0, 16))
  }
  if (@('click','rclick','dblclick','wheel','move','drag','hover','relclick') -ccontains $commandKey) { return 'coordinates-or-current-pointer' }
  return 'not-specified'
}

function Get-DtxCallProcessBirth([int]$ProcessId) {
  $process = [System.Diagnostics.Process]::GetProcessById($ProcessId)
  try {
    $creation = [long]0
    $exit = [long]0
    $kernel = [long]0
    $user = [long]0
    if (-not [DtxCallProcessNative]::GetProcessTimes($process.Handle, [ref]$creation, [ref]$exit, [ref]$kernel, [ref]$user)) {
      throw (New-Object ComponentModel.Win32Exception([Runtime.InteropServices.Marshal]::GetLastWin32Error()))
    }
    return [pscustomobject]@{
      FileTime = $creation.ToString([Globalization.CultureInfo]::InvariantCulture)
      Utc = [DateTime]::FromFileTimeUtc($creation).ToString('o', [Globalization.CultureInfo]::InvariantCulture)
    }
  }
  finally { $process.Dispose() }
}

function Get-DtxCallParentInfo($Context = $null) {
  $given = Get-DtxCallContextValue $Context 'ParentInfo' $null
  if ($null -ne $given) { return $given }
  try {
    $currentId = [System.Diagnostics.Process]::GetCurrentProcess().Id
    $row = Get-CimInstance -ClassName Win32_Process -Filter ('ProcessId = ' + $currentId) -Property ProcessId,ParentProcessId -ErrorAction Stop
    $parentId = [int]$row.ParentProcessId
    if ($parentId -le 0) { throw 'parent process id unavailable' }
    $parent = [System.Diagnostics.Process]::GetProcessById($parentId)
    try {
      $parentBirth = Get-DtxCallProcessBirth $parentId
      $parentName = ConvertTo-DtxCallSafeText $parent.ProcessName 64
    } finally { $parent.Dispose() }
    return [pscustomobject]@{ ParentPid = $parentId; ParentName = $parentName; ParentStartUtc = $parentBirth.Utc; ParentStartFileTime = $parentBirth.FileTime; Known = $true }
  } catch {
    return [pscustomobject]@{ ParentPid = 0; ParentName = 'unknown'; ParentStartUtc = ''; ParentStartFileTime = ''; Known = $false }
  }
}

function New-DtxCallDesktopIdentity([string]$WindowStation, [string]$DesktopName) {
  $station = ConvertTo-DtxCallSafeText $WindowStation 64
  $desktop = ConvertTo-DtxCallSafeText $DesktopName 64
  if (($station.Length -eq 0) -or ($desktop.Length -eq 0)) { throw 'window station or desktop name unavailable' }
  return ('window-station=' + $station + ';desktop=' + $desktop)
}

function Get-DtxCallObjectName([IntPtr]$Handle) {
  if ($Handle -eq [IntPtr]::Zero) { throw 'window object handle unavailable' }
  $needed = 0
  [void][DT]::GetUserObjectInformation($Handle, 2, [IntPtr]::Zero, 0, [ref]$needed)
  if (($needed -lt 4) -or ($needed -gt 2048)) { throw 'desktop name size unavailable' }
  $buffer = [Runtime.InteropServices.Marshal]::AllocHGlobal($needed)
  try {
    if (-not [DT]::GetUserObjectInformation($Handle, 2, $buffer, $needed, [ref]$needed)) { throw 'window object name read failed' }
    $name = [Runtime.InteropServices.Marshal]::PtrToStringUni($buffer)
    if ([string]::IsNullOrWhiteSpace($name)) { throw 'window object name empty' }
    return ConvertTo-DtxCallSafeText $name 64
  } finally { [Runtime.InteropServices.Marshal]::FreeHGlobal($buffer) }
}

function Get-DtxCallDesktopName {
  $station = [DT]::GetProcessWindowStation()
  if ($station -eq [IntPtr]::Zero) { throw 'process window station unavailable' }
  $stationName = Get-DtxCallObjectName $station
  $threadId = [DT]::GetCurrentThreadId()
  if ($threadId -eq 0) { throw 'current thread id unavailable' }
  $desktop = [DT]::GetThreadDesktop($threadId)
  if ($desktop -eq [IntPtr]::Zero) { throw 'thread desktop unavailable' }
  $desktopName = Get-DtxCallObjectName $desktop
  return New-DtxCallDesktopIdentity $stationName $desktopName
}

function Enter-DtxCallLock([string]$Path, [int]$TimeoutMs = 300) {
  $watch = [System.Diagnostics.Stopwatch]::StartNew()
  while ($watch.ElapsedMilliseconds -lt $TimeoutMs) {
    try { return [System.IO.File]::Open($Path, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None) }
    catch [System.IO.IOException] { Start-Sleep -Milliseconds 15 }
  }
  return $null
}

function Write-DtxCallAtomicJson([string]$Path, $Value) {
  $tmp = $Path + '.' + [Guid]::NewGuid().ToString('N') + '.tmp'
  $json = ConvertTo-Json -InputObject $Value -Depth 8 -Compress
  [System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding($false)))
  try {
    if ([System.IO.File]::Exists($Path)) {
      $backup = $Path + '.' + [Guid]::NewGuid().ToString('N') + '.bak'
      try { [System.IO.File]::Replace($tmp, $Path, $backup) }
      finally { if ([System.IO.File]::Exists($backup)) { [System.IO.File]::Delete($backup) } }
    }
    else { [System.IO.File]::Move($tmp, $Path) }
  } finally { if ([System.IO.File]::Exists($tmp)) { [System.IO.File]::Delete($tmp) } }
}

function Read-DtxCallRecord([string]$Path) {
  $raw = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
  return ConvertFrom-Json -InputObject $raw -ErrorAction Stop
}

function Test-DtxCallHistoryHasId([string]$HistoryRoot, [string]$StartUtc, [string]$InvocationId) {
  $day = ([DateTime]::Parse($StartUtc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind)).ToUniversalTime().ToString('yyyyMMdd')
  $needle = '"invocation_id":"' + $InvocationId + '"'
  foreach ($path in @([System.IO.Directory]::GetFiles($HistoryRoot, ('calls-' + $day + '-*.jsonl')))) {
    $raw = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    if ($raw.Contains($needle)) { return $true }
  }
  return $false
}

function Write-DtxCallHistory($Record, [string]$HistoryRoot) {
  $day = ([DateTime]::Parse([string]$Record.started_utc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind)).ToUniversalTime().ToString('yyyyMMdd')
  $json = ConvertTo-Json -InputObject $Record -Depth 8 -Compress
  $bytes = [System.Text.Encoding]::UTF8.GetBytes($json + "`n")
  if ($bytes.Length -gt 16384) { throw 'history record exceeds the 16 KiB record limit' }
  $paths = @([System.IO.Directory]::GetFiles($HistoryRoot, ('calls-' + $day + '-*.jsonl')))
  $maxSeq = 0
  $latest = ''
  foreach ($path in $paths) {
    $m = [regex]::Match([System.IO.Path]::GetFileName($path), '^calls-' + $day + '-([0-9]{4})\.jsonl$')
    if ($m.Success) {
      $seq = [int]$m.Groups[1].Value
      if ($seq -gt $maxSeq) { $maxSeq = $seq; $latest = $path }
    }
  }
  $maxSegmentBytes = 4194304
  if (($latest -eq '') -or (([System.IO.FileInfo]$latest).Length + $bytes.Length -gt $maxSegmentBytes)) {
    $maxSeq++
    $latest = Join-Path $HistoryRoot ('calls-' + $day + '-' + $maxSeq.ToString('0000') + '.jsonl')
  }
  $stream = [System.IO.File]::Open($latest, [System.IO.FileMode]::Append, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read)
  try { $stream.Write($bytes, 0, $bytes.Length); $stream.Flush($true) }
  finally { $stream.Dispose() }
}

function Get-DtxCallProcessState($Record) {
  try {
    $actual = Get-DtxCallProcessBirth ([int]$Record.tool_pid)
    if ([string]$actual.FileTime -ceq [string]$Record.tool_process_start_filetime) { return 'alive' }
    return 'pid-reused'
  } catch [ArgumentException] { return 'dead' }
  catch { return 'unknown' }
}

function Get-DtxCallInternalParent($ActiveById, $ParentInfo, [string]$Root) {
  $parentId = [Environment]::GetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_ID', 'Process')
  $parentPid = [Environment]::GetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_PID', 'Process')
  $parentStart = [Environment]::GetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_START_FILETIME', 'Process')
  $parentToken = [Environment]::GetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_TOKEN', 'Process')
  if ((-not $parentId) -or (-not $parentPid) -or (-not $parentStart) -or (-not $parentToken)) { return $null }
  if ((-not $ParentInfo.Known) -or ([int]$ParentInfo.ParentPid -ne [int]$parentPid)) { return $null }
  if ([string]$ParentInfo.ParentStartFileTime -cne [string]$parentStart) { return $null }
  if (-not $ActiveById.ContainsKey([string]$parentId)) { return $null }
  $parentRecord = $ActiveById[[string]$parentId]
  if (([string]$parentRecord.status -cne 'active') -or ([int]$parentRecord.tool_pid -ne [int]$parentPid)) { return $null }
  if ([string]$parentRecord.tool_process_start_filetime -cne [string]$parentStart) { return $null }
  if ((Get-DtxCallSha256 $parentToken) -cne [string]$parentRecord.internal_token_sha256) { return $null }
  return $parentRecord
}

function Start-DtxCallTracking([string]$Command, [string[]]$Arguments, $Context = $null) {
  $lock = $null
  try {
    $localRoot = [string](Get-DtxCallContextValue $Context 'RootBase' $null)
    if (-not $localRoot) { $localRoot = [Environment]::GetFolderPath([Environment+SpecialFolder]::LocalApplicationData) }
    $sessionId = [string](Get-DtxCallContextValue $Context 'WindowsSessionId' $null)
    if (-not $sessionId) { $sessionId = [string][System.Diagnostics.Process]::GetCurrentProcess().SessionId }
    $desktopName = [string](Get-DtxCallContextValue $Context 'DesktopName' $null)
    if (-not $desktopName) { $desktopName = Get-DtxCallDesktopName }
    if (($localRoot.Length -eq 0) -or ($sessionId -notmatch '^\d{1,8}$') -or ($desktopName.Length -eq 0)) { throw 'call-state identity unavailable' }
    $desktopKey = 'desktop-' + (Get-DtxCallSha256 $desktopName).Substring(0, 16)
    $stateRoot = Join-Path (Join-Path (Join-Path $localRoot 'AgentComputerUse\runtime\v1') $sessionId) $desktopKey
    $activeRoot = Join-Path $stateRoot 'active'
    $historyRoot = Join-Path $stateRoot 'history'
    [void][System.IO.Directory]::CreateDirectory($activeRoot)
    [void][System.IO.Directory]::CreateDirectory($historyRoot)
    $lockPath = Join-Path $stateRoot 'state.lock'
    $identity = Get-DtxCallIdentity $Context
    $parentInfo = Get-DtxCallParentInfo $Context
    $invocationId = [Guid]::NewGuid().ToString('N')
    $tokenBytes = New-Object byte[] 32
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($tokenBytes) } finally { $rng.Dispose() }
    $token = [System.BitConverter]::ToString($tokenBytes).Replace('-', '').ToLowerInvariant()
    $process = [System.Diagnostics.Process]::GetCurrentProcess()
    try {
      $processBirth = Get-DtxCallProcessBirth ([int]$PID)
      $processName = ConvertTo-DtxCallSafeText $process.ProcessName 64
    } finally { $process.Dispose() }
    $processStart = [string]$processBirth.Utc
    $processStartFileTime = [string]$processBirth.FileTime
    $started = [DateTime]::UtcNow.ToString('o', [Globalization.CultureInfo]::InvariantCulture)
    $sourcePath = [string](Get-DtxCallContextValue $Context 'SourcePath' (Get-Variable -Name ToolEntryPath -Scope Script -ValueOnly -ErrorAction SilentlyContinue))
    if ($sourcePath) { try { $sourcePath = [System.IO.Path]::GetFullPath($sourcePath) } catch { } }
    $toolVersion = [string](Get-DtxCallContextValue $Context 'ToolVersion' (Get-Variable -Name ToolVersion -Scope Script -ValueOnly -ErrorAction SilentlyContinue))
    if (-not $toolVersion) { $toolVersion = 'unknown' }
    $lock = Enter-DtxCallLock $lockPath 300
    if ($null -eq $lock) { throw 'lock-timeout' }

    $stateUnknown = $false
    $activeRecords = New-Object System.Collections.ArrayList
    $activeById = @{}
    foreach ($activePath in @([System.IO.Directory]::GetFiles($activeRoot, '*.json'))) {
      try { $record = Read-DtxCallRecord $activePath }
      catch { $stateUnknown = $true; continue }
      if ([string]$record.status -ceq 'complete') {
        try {
          if (-not (Test-DtxCallHistoryHasId $historyRoot ([string]$record.started_utc) ([string]$record.invocation_id))) { Write-DtxCallHistory $record $historyRoot }
          [System.IO.File]::Delete($activePath)
        } catch { $stateUnknown = $true }
        continue
      }
      if ([string]$record.status -cne 'active') { $stateUnknown = $true; continue }
      $processState = Get-DtxCallProcessState $record
      if ($processState -eq 'alive') {
        [void]$activeRecords.Add($record)
        $activeById[[string]$record.invocation_id] = $record
        continue
      }
      if ($processState -eq 'unknown') { $stateUnknown = $true; continue }
      $observed = [DateTime]::UtcNow.ToString('o', [Globalization.CultureInfo]::InvariantCulture)
      $record.status = 'complete'
      $record.ended_utc = $observed
      $record.duration_ms = [long]([DateTime]::Parse($observed).Subtract([DateTime]::Parse([string]$record.started_utc)).TotalMilliseconds)
      $record.result_category = if ($processState -eq 'pid-reused') { 'pid-reused-observed' } else { 'process-disappeared-observed' }
      $record.exit_code = $null
      $record.end_time_kind = 'observed-during-recovery'
      $record.internal_token_sha256 = ''
      try {
        Write-DtxCallAtomicJson $activePath $record
        if (-not (Test-DtxCallHistoryHasId $historyRoot ([string]$record.started_utc) ([string]$record.invocation_id))) { Write-DtxCallHistory $record $historyRoot }
        [System.IO.File]::Delete($activePath)
      } catch { $stateUnknown = $true }
    }

    $verifiedParent = Get-DtxCallInternalParent $activeById $parentInfo $stateRoot
    $rootInvocationId = if ($null -ne $verifiedParent) { [string]$verifiedParent.root_invocation_id } else { $invocationId }
    $parentLink = if ($null -ne $verifiedParent) { [string]$verifiedParent.invocation_id } else { '' }
    $record = [pscustomobject]@{
      schema_version = 1
      invocation_id = $invocationId
      root_invocation_id = $rootInvocationId
      internal_parent_invocation_id = $parentLink
      internal_chain_verified = [bool]($null -ne $verifiedParent)
      status = 'active'
      ended_utc = ''
      duration_ms = $null
      result_category = 'running'
      exit_code = $null
      error_category = ''
      end_time_kind = ''
      caller_label = ConvertTo-DtxCallSafeText ([string]$identity.CallerLabel) 80
      caller_session_id = ConvertTo-DtxCallSafeText ([string]$identity.CallerSessionId) 96
      identity_source = ConvertTo-DtxCallSafeText ([string]$identity.IdentitySource) 48
      command = ConvertTo-DtxCallSafeText $Command 64
      target_summary = Get-DtxCallTargetSummary $Command $Arguments
      tool_pid = [int]$PID
      tool_process_name = $processName
      tool_process_start_utc = $processStart
      tool_process_start_filetime = $processStartFileTime
      parent_pid = [int]$parentInfo.ParentPid
      parent_process_name = ConvertTo-DtxCallSafeText ([string]$parentInfo.ParentName) 64
      parent_process_start_utc = [string]$parentInfo.ParentStartUtc
      parent_process_start_filetime = [string]$parentInfo.ParentStartFileTime
      source_path = ConvertTo-DtxCallSafeText $sourcePath 512
      source_version = ConvertTo-DtxCallSafeText $toolVersion 32
      windows_session_id = $sessionId
      desktop_name = $desktopName
      started_utc = $started
      internal_token_sha256 = Get-DtxCallSha256 $token
    }
    $activePath = Join-Path $activeRoot ($invocationId + '.json')
    Write-DtxCallAtomicJson $activePath $record
    $activeById[$invocationId] = $record

    $overlapGroups = @{}
    foreach ($other in @($activeRecords)) {
      $otherRoot = [string]$other.root_invocation_id
      if ($otherRoot -ceq $rootInvocationId) { continue }
      if (-not $overlapGroups.ContainsKey($otherRoot)) { $overlapGroups[$otherRoot] = $other }
      elseif (($other.invocation_id -ceq $otherRoot) -or ([DateTime]::Parse([string]$other.started_utc) -lt [DateTime]::Parse([string]$overlapGroups[$otherRoot].started_utc))) { $overlapGroups[$otherRoot] = $other }
    }
    $lock.Dispose()
    $lock = $null
    if ($stateUnknown) { [Console]::Error.WriteLine('WARNING: desktop tool call-state=unknown; one or more state records could not be verified. This run is not reported as idle.') }
    if (([string]$identity.CallerLabel -ceq 'unknown') -or ([string]$identity.CallerSessionId -ceq 'unknown')) {
      [Console]::Error.WriteLine('WARNING: desktop tool caller identity=unknown; this invocation remains separately tracked and does not establish desktop exclusivity.')
    }
    foreach ($otherEntry in @($overlapGroups.GetEnumerator())) {
      $otherRoot = [string]$otherEntry.Key
      $other = $otherEntry.Value
      $otherStartedUtc = [string]$other.started_utc
      if ($other.started_utc -is [DateTime]) {
        $otherStartedUtc = $other.started_utc.ToUniversalTime().ToString('o', [Globalization.CultureInfo]::InvariantCulture)
      }
      [Console]::Error.WriteLine('WARNING: desktop tool overlap: caller=' + (ConvertTo-DtxCallSafeText ([string]$other.caller_label) 80) +
        ' session=' + (ConvertTo-DtxCallSafeText ([string]$other.caller_session_id) 8) +
        ' command=' + (ConvertTo-DtxCallSafeText ([string]$other.command) 64) +
        ' started=' + $otherStartedUtc + '; this call may steal focus or invalidate reads.')
    }

    $markerNames = @('DTX_CALL_INTERNAL_PARENT_ID','DTX_CALL_INTERNAL_PARENT_PID','DTX_CALL_INTERNAL_PARENT_START_FILETIME','DTX_CALL_INTERNAL_PARENT_TOKEN')
    $savedMarkers = @{}
    foreach ($markerName in $markerNames) { $savedMarkers[$markerName] = [Environment]::GetEnvironmentVariable($markerName, 'Process') }
    [Environment]::SetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_ID', $invocationId, 'Process')
    [Environment]::SetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_PID', [string]$PID, 'Process')
    [Environment]::SetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_START_FILETIME', $processStartFileTime, 'Process')
    [Environment]::SetEnvironmentVariable('DTX_CALL_INTERNAL_PARENT_TOKEN', $token, 'Process')
    return [pscustomobject]@{ Enabled = $true; InvocationId = $invocationId; ActivePath = $activePath; HistoryRoot = $historyRoot; LockPath = $lockPath; Record = $record; Token = $token; SavedMarkers = $savedMarkers }
  } catch {
    $reason = if ($_.Exception.Message -ceq 'lock-timeout') { 'lock-timeout' } else { 'state-unavailable' }
    [Console]::Error.WriteLine('WARNING: desktop tool call-state=unknown reason=' + $reason + '; no idle claim is made.')
    return $null
  } finally { if ($null -ne $lock) { $lock.Dispose() } }
}

function Complete-DtxCallTracking($Lease, [string]$ResultCategory, [int]$ExitCode, [string]$ErrorCategory = '') {
  if (($null -eq $Lease) -or (-not $Lease.Enabled)) { return }
  $lock = $null
  try {
    $record = $Lease.Record
    $record.status = 'complete'
    $record.ended_utc = [DateTime]::UtcNow.ToString('o', [Globalization.CultureInfo]::InvariantCulture)
    $record.duration_ms = [long]([DateTime]::Parse([string]$record.ended_utc).Subtract([DateTime]::Parse([string]$record.started_utc)).TotalMilliseconds)
    $record.result_category = ConvertTo-DtxCallSafeText $ResultCategory 48
    $record.exit_code = [int]$ExitCode
    $record.error_category = ConvertTo-DtxCallSafeText $ErrorCategory 48
    $record.end_time_kind = 'recorded-at-process-exit'
    $record.internal_token_sha256 = ''
    # Each lease file has one writer, so an atomic replacement can mark completion before
    # we wait for the shared history lock. A later invocation can finish history recovery.
    Write-DtxCallAtomicJson ([string]$Lease.ActivePath) $record
    $lock = Enter-DtxCallLock ([string]$Lease.LockPath) 300
    if ($null -eq $lock) { throw 'lock-timeout' }
    # A concurrent recovery scan may have observed this completed active record after
    # the atomic status write but before this caller acquired the history lock.
    # Keep the history append idempotent under that handoff race.
    if (-not (Test-DtxCallHistoryHasId ([string]$Lease.HistoryRoot) ([string]$record.started_utc) ([string]$record.invocation_id))) {
      Write-DtxCallHistory $record ([string]$Lease.HistoryRoot)
    }
    [System.IO.File]::Delete([string]$Lease.ActivePath)
  } catch {
    [Console]::Error.WriteLine('WARNING: desktop tool call-history=unknown; this command result is unchanged and recovery may record the active lease later.')
  } finally {
    if ($null -ne $lock) { $lock.Dispose() }
    foreach ($markerEntry in @($Lease.SavedMarkers.GetEnumerator())) { [Environment]::SetEnvironmentVariable([string]$markerEntry.Key, [string]$markerEntry.Value, 'Process') }
  }
}

# lib/selftest.ps1 - the selftest section, lifted out of desktop.ps1 by A-11b.
# Bodies are byte-identical to what the entry carried; the only reason this file can exist at all
# is A-11a: inside a dot-sourced file $PSCommandPath names THIS file and $PSScriptRoot names lib/,
# so the section goes through $script:ToolEntryPath / $script:ToolRootPath, which the entry
# publishes at load time. A lint counts bare reads of either automatic variable per section and the
# count here must stay zero - a future card that moves code and reintroduces one fails by name.
function Invoke-SelfTest([string[]]$Rest) {
  # v2.6.0: a selftest run must never have its own captures moved out from under it -
  # `--live` writes st-* fixtures early and reads them back later, and the automatic
  # trim after each capture would sweep exactly the files still to be asserted. The flag
  # is never cleared: selftest is terminal for the process, and the worst a later command
  # in the same process can suffer is one skipped trim.
  $script:NoAutoTrim = $true
  # v4.3.0 (--index): a static listing read from this file's own source; never runs a check.
  # Combined use with any other selftest flag is refused by name, not ignored.
  if (@($Rest) -contains '--index') {
    foreach ($ixOther in @('--live', '--timing', '--only')) {
      if (@($Rest) -contains $ixOther) { throw ('selftest: --index cannot be combined with ' + $ixOther + ' (it lists checks; it never runs them)') }
    }
    $script:StModeLine = Get-SourceModeLine "$script:StSourceMode" @($script:StSourceFiles).Count
    Write-Output ('      ' + $script:StModeLine)
    if ("$script:StSourceMode" -ceq 'aggregate') {
      $script:StSourceSpans = Get-SourceLineSpans $script:ToolRootPath $script:StSourceFiles
      $ixLines = @((Get-AggregatedSource $script:ToolRootPath $script:StSourceFiles) -split "`r?`n")
    } else {
      $ixLines = @([System.IO.File]::ReadAllLines($script:ToolEntryPath, [System.Text.Encoding]::UTF8))
    }
    $ixEntries = @((Get-SelftestIndexEntries $ixLines).Entries)
    $ixStatic = @($ixEntries | Where-Object { $_.Kind -ceq 'static' }).Count
    $ixRegion = @($ixEntries | Where-Object { $_.Kind -ceq 'region' }).Count
    $ixTempl = @($ixEntries | Where-Object { $_.Kind -ceq 'template' }).Count
    Write-Output ('selftest index: ' + @($ixEntries).Count + ' entries (static=' + $ixStatic + ' region=' + $ixRegion + ' template=' + $ixTempl + ') declared-offline=' + $script:DeclaredCheckTotal)
    foreach ($ixE in @($ixEntries | Sort-Object -Property Line, Name)) {
      if ($ixE.Kind -ceq 'static') { Write-Output ((Format-SourceLineRef ([int]$ixE.Line)) + "`t" + [string]$ixE.Name) }
      else { Write-Output ('+' + "`t" + [string]$ixE.Name) }
    }
    return
  }
  $live = @($Rest) -contains '--live'
  $script:StPass = 0; $script:StFail = 0; $script:StSkip = 0
  $script:StPassLines = New-Object System.Collections.ArrayList
  # StrictMode is on: ST-Check/ST-Skip read this on EVERY call, so it must exist before
  # the first check runs - an unset script variable aborts the whole gate, which is a
  # louder failure than the one it guards but a useless one. Regions set it to a list.
  $script:StRecord = $null
  # v4.3.0 (--only): scope filter. Parsed here (the --index fast path above returned already).
  # Consulted ONLY through Test-StOnlyAbsorb, whose only two call sites are the emitters.
  $script:StOnlyPat = Resolve-SelftestOnlyPattern $Rest
  $script:StOnlyActive = ($script:StOnlyPat -ne '')
  $script:StAbsorbed = 0
  $script:StAbsorbedFail = 0
  $script:StEmittedAll = New-Object System.Collections.ArrayList
  if ($script:StOnlyActive) {
    if ($live) { throw 'selftest: --only cannot be combined with --live (the live ladder runs as a whole)' }
    Write-Output ("      filter: --only '" + $script:StOnlyPat + "' - only matching checks are reported; every check still executes and absorbed results are disclosed in the summary, not in the exit code")
  }
  # v4.2.4 (--timing): the per-check cost profile. The stopwatch starts HERE, before the file
  # reads its own source, so the first check's delta also carries the gate's own setup - the
  # profile answers "where do the minutes go", it is not there to flatter the first check.
  $script:StTiming = (@($Rest) -contains '--timing')
  $script:StSw = [System.Diagnostics.Stopwatch]::StartNew()
  $script:StLastMs = 0.0
  $self = $script:ToolEntryPath
  $src = if ("$script:StSourceMode" -ceq 'aggregate') { Get-AggregatedSource $script:ToolRootPath $script:StSourceFiles } else { Get-Content -LiteralPath $self -Raw }
  # !! Built here, not only in the --index fast path: every echo below resolves through it,
  #    and an empty span map would print beyond-aggregate for every single line number.
  if ($script:StSourceMode -ceq 'aggregate') { $script:StSourceSpans = Get-SourceLineSpans $script:ToolRootPath $script:StSourceFiles }
  $script:StModeLine = Get-SourceModeLine "$script:StSourceMode" @($script:StSourceFiles).Count
  Write-Output ('      ' + $script:StModeLine)
  # v4.1.3: the region helpers below need the file's own lines from the FIRST gated
  # region onward, which is earlier than $codeLines is built - so the raw split is
  # published here. Line numbers match $codeLines exactly (that pass never deletes lines).
  $script:StSourceLines = @($src -split "`r?`n")

  # v4.1.3 (external review D): the call operator resolves through PATH, so a harness whose
  # PATH lacks WindowsPowerShell cannot spawn a child at all - three offline checks then
  # reported a product failure for the caller's environment. The git family in this same
  # file already treats "no git in PATH" as "nothing to measure" and SKIPS; that stance is
  # now shared. One probe, and every `& powershell` check accounts for itself either way.
  # (Start-Process -FilePath 'powershell.exe' still resolves through App Paths, so the
  # fixture families that spawn that way are unaffected - measured in the 4-context matrix.)
  $script:PsChildOk = $true
  $script:PsChildWhy = ''
  try {
    if ($null -eq (Get-Command powershell.exe -ErrorAction SilentlyContinue)) {
      $script:PsChildOk = $false
      $script:PsChildWhy = 'no powershell.exe resolvable in PATH'
    }
  } catch {
    $script:PsChildOk = $false
    $script:PsChildWhy = 'probe threw: ' + $_.Exception.Message
  }
  Write-Output ('      child-spawn probe: ok=' + [bool]$script:PsChildOk + $(if ($script:PsChildOk) { '' } else { ' reason=' + $script:PsChildWhy }))

  # G-21 (owner ruling 2026-10-20 14:4x, item 3): the two child faces are ONE question only if
  # nobody measures them. Measured on this box in both engines
  # (start-process-face-ps51.json and start-process-face-pwsh7.json in the G-21 evidence directory,
  # whose full path is registered in the construction ledger): with
  # System32\WindowsPowerShell off PATH, Get-Command powershell.exe answers nothing and a bare
  # `& powershell` yields an empty face, while `Start-Process powershell -Wait -PassThru` STILL runs
  # the child and reads back its exit code, because Start-Process resolves through App Paths. A block
  # that raises its fixture with Start-Process and then drives the tool with `& powershell` therefore
  # needs BOTH answers, each carrying its own reason. The value below is a runtime probe of a real
  # child - NOT a count of how many sites reference it; lint (G-21) prints the two apart.
  $script:PsStartOk = $true
  $script:PsStartWhy = ''
  try {
    $psStartProbe = Start-Process powershell -ArgumentList '-NoProfile', '-Command', 'exit 0' -Wait -PassThru -WindowStyle Hidden -ErrorAction Stop
    if ($null -eq $psStartProbe -or $psStartProbe.ExitCode -ne 0) {
      $script:PsStartOk = $false
      $script:PsStartWhy = 'Start-Process powershell gave no clean exit (child=' + $(if ($psStartProbe) { [string]$psStartProbe.ExitCode } else { 'null' }) + ')'
    }
  } catch {
    $script:PsStartOk = $false
    $script:PsStartWhy = 'Start-Process probe threw: ' + $_.Exception.Message
  }
  Write-Output ('      start-process probe: ok=' + [bool]$script:PsStartOk + $(if ($script:PsStartOk) { '' } else { ' reason=' + $script:PsStartWhy }))

  # v4.4.0 (A-14c): shared state that the families consume is produced HERE, not inside one gate body.
  # A-14b measured it: nearly every remaining family reads $codeLines / $clCount / $code (and the
  # production-window pair), while those were built inside the wrapper-lint and J-05 bodies. A lifted
  # family cannot read a caller local - $Ctx is the only channel by design - so the producers move up
  # and get published. No check moves with them, and the emitted order is asserted unchanged in this
  # same commit: relocating production must not be able to shuffle what a run reports.
  # One pass over the real source lines, blanking everything inside a here-string.
  # Needed twice: Usage() documents the literal shapes "@(Fn)" and "return ,$list",
  # and scanning that prose would both misclassify Usage as a comma-returning
  # helper and make the helper list (hence the whole lint) garbage while still
  # reporting PASS. Line numbers stay true because we never delete lines.
  $codeLines = @()
  $inHere = $false
  foreach ($l in ($src -split "`r?`n")) {
    if ($inHere) {
      $codeLines += ''
      if ($l -match "^'@") { $inHere = $false }
      continue
    }
    if ($l -match "@'\s*$") { $codeLines += ''; $inHere = $true; continue }
    $codeLines += $l
  }
  # v4.2.4 (perf): hoist the count ONCE. @( ) re-copies the array on every evaluation, so a
  # for-condition carrying @($codeLines).Count is O(n^2) - measured on this very file: the
  # three-round loop with the count inline cost 44,885 ms, the identical loop with it hoisted
  # cost 81 ms. $codeLines is built once above and never reassigned afterwards, so one hoist
  # covers every scan below without changing what any of them read.
  $clCount = $codeLines.Count
  $code = $codeLines -join "`n"
  $srcLines = @($src -split "`r?`n")
  # v4.4.0 (A-14j): three more shared inputs are produced here rather than inside the docs-contract
  # body, for the same reason as the A-14c set - window-targeting and chrome-cdp read them, and a
  # lifted family cannot reach a caller local. The usage page is built from $src, and the case-start
  # scan walks the dispatcher body once; both are pure measurements, so hoisting them changes no
  # verdict, only where the number is produced.
  $hLines = Get-UsageLines
  # the coverage lint: every real command the dispatcher accepts must be findable in help.
  $hCaseStarts = @{}
  $hFnStart = -1; $hFnEnd = $codeLines.Count
  for ($i = 0; $i -lt $codeLines.Count; $i++) { if ($codeLines[$i] -match '^function Invoke-DesktopCommand') { $hFnStart = $i; break } }
  if ($hFnStart -ge 0) { for ($i = $hFnStart + 1; $i -lt $codeLines.Count; $i++) { if ($codeLines[$i] -match '^function ') { $hFnEnd = $i; break } } }
  for ($i = $hFnStart; $i -lt $hFnEnd; $i++) {
    if ($codeLines[$i] -match ('^\s{4}' + "'" + '([a-z0-9-]+)' + "'" + ' \{$')) {
      $hn = "$($Matches[1])"
      if (-not $hCaseStarts.ContainsKey($hn)) { $hCaseStarts[$hn] = $i }
    }
  }

  # count PRODUCTION sites only: the selftest bodies call these helpers themselves, and a scan that
  # does not exclude its own test code measures the wrong thing (9 here at first).
  # v4.4.0 (A-14f): the window used to be "up to the next ^function", which stops at the first family
  # file - so every family that moved out was re-counted as production (measured 2026-10-15: the
  # attempt-gate and F2 normalizer lints reddened on the move). It is now the AST extent of EVERY
  # selftest body, orchestrator plus each lifted family, and lint (A-14f) checks that no foreign
  # function hides inside that span - the width is verified, not assumed.
  # ST-Check is deliberately NOT named here: it lives in the entry's tail, which in aggregate
  # coordinates sits after every family file, so naming it stretched the span across the whole
  # dispatcher and made production code read as exempt. lint (A-14f) is what keeps that honest.
  $j5Names = @('Invoke-SelfTest')
  foreach ($j5k in @($script:StFamilyLifted)) { $j5Names += Get-FamilyFunctionName $j5k }
  $j5SelfParsed = Parse-SourceForInventory (@($script:StSourceLines) -join "`n")
  $j5Window = Get-SelftestWindow $j5SelfParsed @($j5Names)
  $j5ProdEnd = $codeLines.Count
  $j5ProdStart = 0
  if (("$j5Window" -ne '-absent') -and ("$j5Window" -ne '-no-parse')) {
    $j5W = @([string]$j5Window -split "`t", 2)
    $j5ProdStart = ([int]$j5W[0] - 1)
    $j5ProdEnd = [int]$j5W[1]
  }

  # ---------- v4.4.0 (A-14r): two producers hoisted out of the gate bodies ----------
  # Both were inline leftovers: the comma scan fed a body two runs away, and the production slice fed the
  # move-and-manifest gate plus the P-06 gate. A lifted family may only be handed published context, so
  # each is computed HERE - above every publish - and handed over as a key. Neither is a re-derivation
  # of the window: the slice uses $j5ProdStart/$j5ProdEnd exactly as computed above, which is the whole
  # reason it could move without inventing a second window scan (lint (A-14i) refuses that shape).
  # Value invariance is asserted at the publish site by lint (A-14r), not argued: the slice length has to
  # equal the window formula, and the helper list has to be the same object the setup built.
  $a14fExempt = @('Invoke-SelfTest', 'ST-Check')
  foreach ($a14fK in @($script:StFamilyLifted)) { $a14fExempt += Get-FamilyFunctionName $a14fK }
  $commaFns = New-Object System.Collections.ArrayList
  foreach ($cn in (@((Get-CommaReturningHelperNames "$code" @($a14fExempt)) -split ','))) {
    if ($cn -ne '') { [void]$commaFns.Add([string]$cn) }
  }
  $stDefIdx = $j5ProdStart
  $stEndIdx = $j5ProdEnd
  $mvProd = @($codeLines)
  if ($stDefIdx -ge 0) {
    $mvProd = @($codeLines[0..($stDefIdx - 1)])
    if ($stEndIdx -lt $clCount) { $mvProd = @($mvProd + @($codeLines[$stEndIdx..($clCount - 1)])) }
  }

  # assembled marker: a scan line must not contain its own search string (it would match itself)
  $evMark = 'Format-Expectation' + 'Verdict '
  # production sites only ($j5ProdStart/$j5ProdEnd are the selftest body bounds computed just above)
  # - counting the units that call the formatter is not counting wiring. v4.4.0 (A-14m): this producer
  # moved up here from the inline body because the family that READS the result is moving out of the
  # section, and a lifted body may only be handed published context - not a caller local.
  $evWire = @()
  for ($ei = 0; $ei -lt $codeLines.Count; $ei++) {
    if ($ei -ge $j5ProdStart -and $ei -lt $j5ProdEnd) { continue }
    if ($codeLines[$ei] -match '^\s*#') { continue }
    if ($codeLines[$ei].Contains($evMark)) { $evWire += ($ei + 1) }
  }
  # v4.4.0 (A-14o): hoisted out of the F-00-A body so a lifted family can be handed it. Deterministic
  # scans over $codeLines, which is built above this point and never rewritten after it - the values
  # the inline gates read are the same objects they were before the move.
  $gaDispStart = -1; $gaDispEnd = $codeLines.Count; $gaHelpStart = -1; $gaHelpEnd = -1
  for ($gai = 0; $gai -lt $codeLines.Count; $gai++) {
    if ($codeLines[$gai] -match ('^function Invoke-' + 'DesktopCommand')) { $gaDispStart = $gai }
    elseif (($gaDispStart -ge 0) -and ($codeLines[$gai] -match '^function ')) { $gaDispEnd = $gai; break }
  }
  for ($gai = 0; $gai -lt $codeLines.Count; $gai++) {
    if ($codeLines[$gai] -match ('^function Get-' + 'UsageText')) { $gaHelpStart = $gai }
    elseif (($gaHelpStart -ge 0) -and ($codeLines[$gai] -match '^function ')) { $gaHelpEnd = $gai; break }
  }
  $gaCases = @()
  $gaCurName = ''; $gaCurStart = -1
  for ($gai = $gaDispStart; $gai -lt $gaDispEnd; $gai++) {
    if ($codeLines[$gai] -match "^    '([A-Za-z0-9-]+)' \{") {
      if ($gaCurStart -ge 0) { $gaCases += ,@($gaCurName, $gaCurStart, $gai) }
      $gaCurName = $Matches[1]; $gaCurStart = $gai
    }
  }
  if ($gaCurStart -ge 0) { $gaCases += ,@($gaCurName, $gaCurStart, $gaDispEnd) }
  $gaCasesCount = @($gaCases).Count
  $gaCaseIdx = {
    param($nm)
    for ($gk = 0; $gk -lt $gaCasesCount; $gk++) { if ($gaCases[$gk][0] -eq $nm) { return $gk } }
    return -1
  }
  # v4.4.0 (A-14b, A-beta): the two families that used to be this section's contiguous head are
  # their own files now. $Ctx is the only channel between them and this scope, the calls sit
  # exactly where the bodies sat, and nothing in this section changed its relative order.
  $Ctx = @{}
  $Ctx['self'] = $self
  $Ctx['src'] = $src
  # the published set is the family contract; lint (A-14c) reconciles it against $script:StCtxKeys
  $Ctx['codeLines'] = $codeLines
  $Ctx['clCount'] = $clCount
  $Ctx['code'] = $code
  $Ctx['j5ProdStart'] = $j5ProdStart
  $Ctx['j5ProdEnd'] = $j5ProdEnd
  $Ctx['srcLines'] = $srcLines
  $Ctx['hLines'] = $hLines
  $Ctx['hCaseStarts'] = $hCaseStarts
  $Ctx['hFnStart'] = $hFnStart
  $Ctx['hFnEnd'] = $hFnEnd
  $Ctx['evMark'] = $evMark
  $Ctx['evWire'] = $evWire
  $Ctx['gaCases'] = $gaCases
  $Ctx['gaCaseIdx'] = $gaCaseIdx
  # A-14p: the live family needs the audit path, the capture folder and the mode flag. All three are
  # settled before this point (entry load-time globals and the --live parse at the top of the body), so
  # publishing them here hands over the same value the inline body has always read.
  $Ctx['actionLog'] = $ActionLog
  $Ctx['outDir'] = $OutDir
  $Ctx['live'] = $live
  # A-14q: gate-meta's gates read the case-table count and the help/dispatcher bounds alongside the
  # arrays already handed over. Every producer sits ABOVE this point (155 j5SelfParsed, 180 the ga*
  # bounds, 198 gaCasesCount - measured by a14q-producers.js), so this is the safe half of the A-14p
  # rule: a value that already exists may be published, a live enumeration may not be re-taken earlier.
  $Ctx['gaCasesCount'] = $gaCasesCount
  $Ctx['gaDispStart'] = $gaDispStart
  $Ctx['gaHelpStart'] = $gaHelpStart
  $Ctx['gaHelpEnd'] = $gaHelpEnd
  $Ctx['j5SelfParsed'] = $j5SelfParsed
  # v4.4.0 (A-14r): the two hoisted producers join the published surface. Registering a key without
  # publishing it is caught by lint (A-14c) - it did catch it, on the first run of this card.
  $Ctx['commaFns'] = $commaFns
  $Ctx['stDefIdx'] = $stDefIdx
  $Ctx['stEndIdx'] = $stEndIdx
  $Ctx['mvProd'] = $mvProd
  # v4.5.5 (TB-1): the version definition joins the published surface so the version family can pin
  # definition == header == runtime source_version without a lifted body reaching into the entry's
  # script scope. The constant is settled at load time, so this is a settled publish, not a re-read.
  $Ctx['ToolVersion'] = "$script:ToolVersion"
  Invoke-SelftestFamily-SplitMachine $Ctx
  Invoke-SelftestFamily-RepoContract $Ctx
  # ---------- v4.4.0 (A-14l): state handed back out of a lifted family is declared on both sides ----------
  # A lifted body still produces values the orchestration reads later. Those travel back through $Ctx and
  # get re-bound by name, so the downstream bodies stay byte-identical - but an undeclared write is
  # invisible to every table, and a declared-but-unwritten key re-binds to $null. Both directions are
  # measured here, and the witnesses below run even while no family declares an export: a gate over an
  # empty set is precisely how a silent green is born.
  $a14lGaps = @()
  # Every lifted family is scanned, including the ones that declare NO hand-back: for those the
  # declared list is empty, so the scan's job is to refuse any write into the context at all. Skipping
  # them was a coverage hole - a family could start writing $Ctx keys and only the A-14b contract would
  # notice, while the gate whose name promises this direction stayed silent by construction.
  foreach ($a14lK in @($script:StFamilyLifted)) {
    $a14lGaps += Get-FamilyExportGap $j5SelfParsed (Get-FamilyFunctionName $a14lK) @(Get-FamilyExportNames $a14lK)
  }
  $a14lGapCount = 0
  foreach ($a14lG in @($a14lGaps)) { if ([string]$a14lG -ne '') { $a14lGapCount = $a14lGapCount + 1 } }
  $a14lPlant = @(
    'function Invoke-SelftestFamily-Written {',
    '  $Ctx[''declared''] = 1',
    '  return 1',
    '}',
    'function Invoke-SelftestFamily-Silent {',
    '  return 1',
    '}'
  )
  $a14lPlantParsed = Parse-SourceForInventory ($a14lPlant -join "`n")
  # one witness per direction: a declared key the body never writes, a written key nobody declared,
  # and a body that is not there at all
  $a14lPDeclOnly = Get-FamilyExportGap $a14lPlantParsed 'Invoke-SelftestFamily-Written' @('declared', 'missing')
  $a14lPUndecl = Get-FamilyExportGap $a14lPlantParsed 'Invoke-SelftestFamily-Written' @()
  $a14lPSilent = Get-FamilyExportGap $a14lPlantParsed 'Invoke-SelftestFamily-Silent' @('x')
  $a14lPAbsent = Get-FamilyExportGap $a14lPlantParsed 'Nowhere-At-All' @('x')
  ST-Check 'lint (A-14l): every exported key a lifted family declares is actually handed back, every hand-back is declared, and the scanner reports both mistakes plus the absent body on planted sources' (
    ($a14lGapCount -eq 0) -and ($a14lPDeclOnly -ceq 'missing=declared-not-written') -and
    ($a14lPUndecl -ceq 'declared=written-not-declared') -and ($a14lPSilent -ceq 'x=declared-not-written') -and
    ($a14lPAbsent -ceq '-absent'))
  foreach ($a14lG in @($a14lGaps)) { if ([string]$a14lG -ne '') { Write-Output ('      A-14l export gap: ' + [string]$a14lG) } }
  Write-Output ('      A-14l exports: families=' + @($script:StFamilyLifted).Count +
    ' declared-not-written=[' + ("$a14lPDeclOnly") + '] written-not-declared=[' + ("$a14lPUndecl") +
    '] silent=[' + ("$a14lPSilent") + '] absent=' + ("$a14lPAbsent"))
  # ---------- v4.4.0 (A-14l): a declared hand-back is only useful if the orchestration binds it back ----------
  # The family side is measured above; this is the caller side, and it is the half a later card can break
  # without touching a family file at all (delete one re-bind line, or move it above the call). Three more
  # refusals come from the same leaf: a doubled re-bind, a hand-back nobody reads, and a hand-back declared
  # for a family that was never lifted - a dead table row that claims a channel which does not exist, and
  # the loop over lifted families would never look at it.
  $a14lRbPlant = @(
    'function Invoke-SelftestFamily-RbGood($Ctx) { return 1 }',
    '  Invoke-SelftestFamily-RbGood $Ctx',
    '  $good = $Ctx[''good'']',
    '  Write-Output $good',
    'function Invoke-SelftestFamily-RbEarly($Ctx) { return 1 }',
    '  $early = $Ctx[''early'']',
    '  Invoke-SelftestFamily-RbEarly $Ctx',
    'function Invoke-SelftestFamily-RbDup($Ctx) { return 1 }',
    '  Invoke-SelftestFamily-RbDup $Ctx',
    '  $dup = $Ctx[''dup'']',
    '  $dup = $Ctx[''dup'']',
    'function Invoke-SelftestFamily-RbQuiet($Ctx) { return 1 }',
    '  Invoke-SelftestFamily-RbQuiet $Ctx',
    '  $unread = $Ctx[''unread'']',
    'function Invoke-SelftestFamily-RbNoCall($Ctx) { return 1 }'
  )
  $a14lRbPlantParsed = Parse-SourceForInventory ($a14lRbPlant -join "`n")
  $a14lRbGood = Get-FamilyExportReadbackGap $a14lRbPlantParsed @($a14lRbPlant) 'Invoke-SelftestFamily-RbGood' @('good')
  $a14lRbEarly = Get-FamilyExportReadbackGap $a14lRbPlantParsed @($a14lRbPlant) 'Invoke-SelftestFamily-RbEarly' @('early')
  $a14lRbDup = Get-FamilyExportReadbackGap $a14lRbPlantParsed @($a14lRbPlant) 'Invoke-SelftestFamily-RbDup' @('dup')
  $a14lRbQuiet = Get-FamilyExportReadbackGap $a14lRbPlantParsed @($a14lRbPlant) 'Invoke-SelftestFamily-RbQuiet' @('unread', 'gone')
  $a14lRbNoCall = Get-FamilyExportReadbackGap $a14lRbPlantParsed @($a14lRbPlant) 'Invoke-SelftestFamily-RbNoCall' @('x')
  $a14lRbNoBody = Get-FamilyExportReadbackGap $a14lRbPlantParsed @($a14lRbPlant) 'Invoke-SelftestFamily-NoSuchBody' @('x')
  $a14lRbGaps = @()
  $a14lRbUnknown = @()
  foreach ($a14lX in @(Get-HashKeys $script:StFamilyExports)) {
    $a14lSeen = $false
    foreach ($a14lK in @($script:StFamilyLifted)) { if (([string]$a14lK) -ceq ([string]$a14lX)) { $a14lSeen = $true } }
    if (-not $a14lSeen) { $a14lRbUnknown += ([string]$a14lX) }
  }
  foreach ($a14lK in @($script:StFamilyLifted)) {
    $a14lEx = @(Get-FamilyExportNames $a14lK)
    if ($a14lEx.Count -eq 0) { continue }
    $a14lRbGaps += Get-FamilyExportReadbackGap $j5SelfParsed @($script:StSourceLines) (Get-FamilyFunctionName ([string]$a14lK)) $a14lEx
  }
  $a14lRbCount = 0
  foreach ($a14lG in @($a14lRbGaps)) { if ([string]$a14lG -ne '') { $a14lRbCount = $a14lRbCount + 1 } }
  ST-Check 'lint (A-14l): every declared hand-back is re-bound by name below its family call and read by a body that stayed in the section, no hand-back is declared for a family that was not lifted, and the scanner reports a missing, an early, a doubled and an unread re-bind plus the absent call and the absent body on planted sources' (
    ($a14lRbCount -eq 0) -and (@($a14lRbUnknown).Count -eq 0) -and
    ($a14lRbGood -ceq '') -and ($a14lRbEarly -ceq 'early=read-before-call') -and
    ($a14lRbDup -ceq 'dup=read-back-dup2') -and
    ($a14lRbQuiet -ceq 'unread=no-downstream-reader;gone=never-read-back') -and
    ($a14lRbNoCall -ceq 'Invoke-SelftestFamily-RbNoCall-no-call') -and ($a14lRbNoBody -ceq '-absent-body'))
  foreach ($a14lG in @($a14lRbGaps)) { if ([string]$a14lG -ne '') { Write-Output ('      A-14l read-back gap: ' + [string]$a14lG) } }
  Write-Output ('      A-14l read-backs: families-with-exports=' + @($a14lRbGaps).Count + ' unknown=[' + ($a14lRbUnknown -join ';') +
    '] plants=[good=' + ("$a14lRbGood") + ' early=' + ("$a14lRbEarly") + ' dup=' + ("$a14lRbDup") +
    ' quiet=' + ("$a14lRbQuiet") + ' no-call=' + ("$a14lRbNoCall") + ' no-body=' + ("$a14lRbNoBody") + ']')
  Write-Output "      comma-returning helpers: $($commaFns -join ', ')"

  foreach ($fn in $commaFns) {
    $pat = '[@$]\(\s*' + [regex]::Escape($fn) + '\b'
    $bad = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt $codeLines.Count; $i++) {
      $l = $codeLines[$i]
      if ($l -match 'SELFTEST-EXEMPT') { continue }
      if ($l -match $pat) { [void]$bad.Add($i + 1) }
    }
    ST-Check "lint: no @()/`$() wrapper around $fn" ($bad.Count -eq 0)
    if ($bad.Count -gt 0) { Write-Output "      planted at line(s): $(Format-SourceLineList $bad)" }
    # positive control: prove the pattern is not vacuous, i.e. it WOULD fire
    $planted = '$x = @(' + $fn + ' $a $b)'
    ST-Check "lint: pattern detects a planted violation for $fn" ($planted -match $pat)
  }

  # v1.5.0 task invariant: new helpers return hashtables, and even a hashtable
  # result must never be wrapped in @()/$() - pointless at best, Object[1]{...}
  # at worst. Same no-wrapper rule, same planted-violation control per helper.
  $hashFns = @('Get-OcrTilePlan', 'Get-ScreenBitmap', 'Invoke-OcrBitmap', 'Merge-OcrTileLines', 'Invoke-OcrBitmapTiled', 'Invoke-OcrRegionTiled', 'Get-HitWindow', 'Read-MapSidecar', 'Convert-ImageToScreen', 'Get-OcclusionPoints', 'Merge-OcclusionHits', 'Get-OcclusionScan', 'Get-OcclusionVerdict', 'Get-RegionOwners', 'Resolve-OcclusionMode', 'Split-OcclusionFlags', 'Invoke-OcclusionGate', 'Invoke-OcclusionOwners', 'Get-WindowVisibleRect', 'Test-MapSidecarStale', 'Split-ReplayFlags', 'Test-ReplayStepRedacted', 'Resolve-ClipboardKind', 'Read-SendFileUtf8', 'Get-UiaVerifyCrossCheck', 'Get-UiaWindowNames', 'New-OcrJsonEnvelope', 'Format-OcclusionCovering', 'Get-OwnFlagTable', 'Get-OwnFlagSpec', 'Strip-OwnFlags')
  foreach ($fn in $hashFns) {
    $pat = '[@$]\(\s*' + [regex]::Escape($fn) + '\b'
    $bad = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt $codeLines.Count; $i++) {
      $l = $codeLines[$i]
      if ($l -match 'SELFTEST-EXEMPT') { continue }
      if ($l -match $pat) { [void]$bad.Add($i + 1) }
    }
    ST-Check "lint: no @()/`$() wrapper around hashtable helper $fn" ($bad.Count -eq 0)
    $planted = '$x = @(' + $fn + ' $a $b)'
    ST-Check "lint: pattern detects a planted violation for $fn" ($planted -match $pat)
  }
  # negative control: a legit BARE hashtable-helper call must not trip the pattern
  ST-Check 'lint: bare hashtable helper call does not match the wrapper pattern' (
    'Invoke-OcrRegionTiled $x $y $w $h 2.0 16' -notmatch '[@$]\(\s*Invoke-OcrRegionTiled\b')

  # v4.4.0 (A-14i): family flags-grammar now lives in lib/selftest-flags-grammar.ps1; the call sits
  # at the position its first piece had, and the thirteen pieces behind it moved up to join it.
  Invoke-SelftestFamily-FlagsGrammar $Ctx
  # v4.4.0 (A-14q + A-14r): family gate-meta lives in lib/selftest-gate-meta.ps1 - the last family.
  # A-14q moved 18 of its 24 banner runs; A-14r moves 4 more (the ones held back because a re-bound
  # hand-back or an un-hoisted producer was still read inline) and moves the CALL to sit below the
  # publish further in, because registering the five keys never proved the values were ready when
  # gate-meta ran - lint (A-14r) measures that chain per name. Two runs stay for structure: the live
  # window-snapshot production with the A-14p publish site, and the --index/--only tail, which grades
  # this run's own transcript and belongs at the end.
  # v4.4.0 (A-14h): family capture-ocr now lives in lib/selftest-capture-ocr.ps1; the call sits at
  # the position its first piece had, and the seven pieces behind it moved up to join it.
  Invoke-SelftestFamily-CaptureOcr $Ctx
  # v4.4.0 (A-14l): family popup-occlusion now lives in lib/selftest-popup-occlusion.ps1; the call sits
  # at the position its first piece had, and its four later pieces moved up to join it (this family is
  # the popup/occlusion set). The five names below are the hand-back: every one of them is still
  # read by inline bodies further down this section, so they come back by declaration, not by scope luck.
  Invoke-SelftestFamily-PopupOcclusion $Ctx
  $dcCase = $Ctx['dcCase']
  $dcKnown = $Ctx['dcKnown']
  $wA = $Ctx['wA']
  $wB = $Ctx['wB']
  $wT = $Ctx['wT']
  # >>> A-14r CHAIN - fenced so the cutter leaves this block in the orchestration: it judges the order of
  #     lines that exist only here, and it reads $Ctx as the orchestrator rather than as a family.
  # v4.4.0 (A-14r): the chain is now produce -> named re-bind -> PUBLISH -> consume. Registering the five
  # keys would not prove a consumer can read a value that exists, so the order is measured from the
  # source and the values are pinned: each published entry must be the SAME object the re-bind just
  # bound (an interleaved value reddens it), the shapes must be what the consumers use, and the gate-meta
  # call must sit BELOW the publish - which is the point of this card, because the call used to run
  # above it and only got away with it because its hand-back consumers stayed inline.
  $Ctx['dcCase'] = $dcCase
  $Ctx['dcKnown'] = $dcKnown
  $Ctx['wA'] = $wA
  $Ctx['wB'] = $wB
  $Ctx['wT'] = $wT
  $a14rChainGap = Get-HandbackChainGap $codeLines 'Invoke-SelftestFamily-PopupOcclusion' 'Invoke-SelftestFamily-GateMeta' @('dcCase', 'dcKnown', 'wA', 'wB', 'wT')
  $a14rOrder = ($a14rChainGap -ceq '')
  $a14rSame = ([object]::ReferenceEquals($Ctx['wA'], $wA)) -and ([object]::ReferenceEquals($Ctx['wB'], $wB)) -and ([object]::ReferenceEquals($Ctx['wT'], $wT))
  $a14rShape = (@($Ctx['dcCase']).Count -ge 1) -and (@($Ctx['dcKnown']).Count -ge 1) -and ($null -ne $Ctx['wA'].Handle) -and ($Ctx['wT'].Transparent -eq $true)
  $a14rSlice = (@($Ctx['mvProd']).Count -eq ($clCount - ($j5ProdEnd - $j5ProdStart)))
  $a14rComma = (@($Ctx['commaFns']).Count -eq @($commaFns).Count) -and ($Ctx['commaFns'].Count -ge 3)
  ST-Check 'lint (A-14r): the hand-back chain is ordered produce -> re-bind -> publish -> family call, the published values are the very objects re-bound above, and the two hoisted producers hand over the value the setup computed' (
    $a14rOrder -and $a14rSame -and $a14rShape -and $a14rSlice -and $a14rComma)
  Write-Output ('      A-14r chain: gap=[' + $a14rChainGap + ']' +
    ' same-objects=' + $a14rSame + ' mvProd=' + (@($Ctx['mvProd']).Count) + '/' + ($clCount - ($j5ProdEnd - $j5ProdStart)) +
    ' commaFns=' + (@($Ctx['commaFns']).Count) + '/' + @($commaFns).Count + ' dcCase=' + (@($Ctx['dcCase']).Count))
  # <<< A-14r CHAIN
  # v4.4.0 (A-14r): the call sits HERE, below the publish it consumes. The four runs lifted by this
  # cut read $dcCase / $dcKnown / $wA out of $Ctx (bound by the adapter in the family file), so the
  # chain the gate above just certified is the channel they really use.
  Invoke-SelftestFamily-GateMeta $Ctx
  # v4.4.0 (A-14m): family audit-output now lives in lib/selftest-audit-output.ps1; the call sits at
  # the position its first piece had, and its four later pieces moved up to join it (this family is the
  # audit/outlet set). One line from its third piece is deliberately left in place below: the
  # dialog-cancel echo reads the hand-back names A-14l binds into this scope, and a lifted family
  # reads only published context - routing a value between two families would be a new channel.
  Invoke-SelftestFamily-AuditOutput $Ctx
  # v4.4.0 (A-14j): family window-targeting now lives in lib/selftest-window-targeting.ps1; the call
  # sits at the position its first piece had, and the nine pieces behind it moved up to join it.
  Invoke-SelftestFamily-WindowTargeting $Ctx
  # v4.4.0 (A-14n): family expect-family now lives in lib/selftest-expect-family.ps1; the call sits at
  # the position its first run had, and its later runs moved up to join it (this family is the
  # expectation set). The F-02 section rides inside a try/finally, so its deeper-indented banner does
  # not delimit a run; the live --verify-timeout banner of this family is nested in a body that has
  # not moved and stays here; and the dialog-cancel echo below stays because it reads hand-back names
  # A-14l binds in this scope.
  Invoke-SelftestFamily-ExpectFamily $Ctx
  Invoke-SelftestFamily-ClipboardInput $Ctx
  # ---------- unit: window model ----------
  $wins = @(Get-WinList)
  ST-Check 'unit: Get-WinList non-empty' ($wins.Count -gt 0)
  $w0 = $wins | Sort-Object -Property Area -Descending | Select-Object -First 1
  # A-14p: published IN PLACE on purpose. Get-WinList enumerates live windows; hoisting the production
  # into setup would move that snapshot hundreds of gates earlier and let the live family judge a
  # different desktop than the one this point in the run has always seen. A-14o's precondition checks
  # (no later write, consumers re-initialise) were both run: 967/969 are the only writes in the
  # section, and the family reads them once each, downstream of here.
  $Ctx['wins'] = $wins
  $Ctx['w0'] = $w0
  # A-14p: the publish is here, not in setup, and this check is what pins that choice. ReferenceEquals
  # says the family receives the very snapshot this line produced - a hoisted re-derivation would pass a
  # count test and still be a different enumeration taken at a different moment.
  $a14pSameWins = [object]::ReferenceEquals($Ctx['wins'], $wins)
  $a14pSameW0 = [object]::ReferenceEquals($Ctx['w0'], $w0)
  $a14pWinsN = @($Ctx['wins']).Count
  $a14pW0Pid = -1
  if ($null -ne $Ctx['w0']) { $a14pW0Pid = [int]$Ctx['w0'].Pid }
  ST-Check 'lint (A-14p): the live window snapshot is published where it is produced and handed over as the same objects, so no family can receive a re-taken enumeration' (
    ($a14pSameWins -eq $true) -and ($a14pSameW0 -eq $true) -and ($a14pWinsN -ge 1) -and ($a14pW0Pid -gt 0))
  Write-Output ('      A-14p in-place publish: same-wins=' + $a14pSameWins + ' same-w0=' + $a14pSameW0 +
    ' rows=' + $a14pWinsN + ' w0-pid=' + $a14pW0Pid)
  ST-Check 'unit: every row carries pid/proc/class/handle/title' (
    $w0.Pid -gt 0 -and $w0.Proc -and $w0.Class -and $w0.Handle -ne [IntPtr]::Zero -and $null -ne $w0.Title)
  # v1.5.7 (D-7): owner/main are part of the row contract now, and the map must leave
  # EXACTLY ONE main=yes per process - two of them would make the note meaningless and
  # zero of them would mean every pick looks wrong.
  ST-Check 'unit: every row carries owner and main (D-7 columns exist on all rows)' (
    $null -ne $w0.PSObject.Properties['Owner'] -and ($w0.Main -ceq 'yes' -or $w0.Main -ceq 'no'))
  $badMain = @($wins | Group-Object -Property Pid | Where-Object { @($_.Group | Where-Object { $_.Main -ceq 'yes' }).Count -ne 1 })
  ST-Check 'unit: exactly one main=yes per pid on the real window list' (@($badMain).Count -eq 0)
  foreach ($bm in @($badMain)) { Write-Output "      pid=$($bm.Name) rows=$(@($bm.Group).Count) main=yes count=$(@($bm.Group | Where-Object { $_.Main -ceq 'yes' }).Count)" }
  $rw = Resolve-Window ([string]$w0.Pid)
  ST-Check 'unit: Resolve-Window by numeric pid selects a window' ($null -ne $rw)
  $cm = New-Object System.Collections.ArrayList
  foreach ($w in $wins) { if ($w.Popup) { [void]$cm.Add($w) } }
  Write-Output "      popup windows visible right now: $($cm.Count)"

  # v4.4.0 (A-14k): family docs-contract now lives in lib/selftest-docs-contract.ps1;
  # the call sits at the position its first piece had, and its four later pieces moved up to join it (this family is the outward-documentation set).
  Invoke-SelftestFamily-DocsContract $Ctx
  # v4.4.0 (A-14k): family chrome-cdp now lives in lib/selftest-chrome-cdp.ps1;
  # the call sits at the position its first piece had, and its three later pieces moved up to join it (this family is the CDP/a11y set).
  Invoke-SelftestFamily-ChromeCdp $Ctx
  Invoke-SelftestFamily-DragPress $Ctx
  Invoke-SelftestFamily-ChallengeWorkflow $Ctx
  Invoke-SelftestFamily-LiveSuite $Ctx
  # ---------- v4.3.0: --index / --only contracts ----------
  $xi = Get-SelftestIndexEntries @($script:StSourceLines)
  $xiEntries = @($xi.Entries)
  $xiPlant = @()
  $xiPlant += "  ST-Check 'unit: planted index probe must be found' (1 -eq 1)"
  $xiPlant += "  ST-Skip 'unit: planted skip probe must be found' 'because'"
  $xiPlant += "  ST-Check 'unit: planted ''quoted'' probe must be found' (1 -eq 1)"
  $xiPlant += "  # ST-Check 'unit: planted comment must NOT be found' (1 -eq 1)"
  # v4.4.2 (SUP-0842-A item 1): the comment plant above is space-indented only, and a filter written
  #    `^#` instead of `^[ \t]*#` would still pass it - so a name quoted inside an INDENTED or a
  #    TAB-indented comment (the shape that lives in a prose example, and the one an offline census
  #    tool got wrong on 2026-10-21) would inflate the published name set without any gate noticing.
  $xiPlant += "`t# ST-Check 'unit: planted tab comment must NOT be found' (1 -eq 1)"
  $xiPlant += "# ST-Check 'unit: planted flush comment must NOT be found' (1 -eq 1)"
  $xiPNames = @(@((Get-SelftestIndexEntries $xiPlant).Entries) | Where-Object { $_.Kind -ceq 'static' } | ForEach-Object { $_.Name })
  Write-Output ('      index plant census: found=' + @($xiPNames).Count + ' of ' + @($xiPlant).Count + ' planted lines')
  ST-Check 'unit (index): extraction finds planted checks (including a doubled-quote name) and ignores comments (the scan is not vacuous)' (
    (@($xiPNames).Count -eq 3) -and (@($xiPNames) -contains 'unit: planted index probe must be found') -and (@($xiPNames) -contains 'unit: planted skip probe must be found') -and (@($xiPNames) -contains "unit: planted 'quoted' probe must be found") -and
    (-not (@($xiPNames) -contains 'unit: planted tab comment must NOT be found')) -and (-not (@($xiPNames) -contains 'unit: planted flush comment must NOT be found')))

  $xiBad = New-Object System.Collections.ArrayList
  foreach ($xe in $xiEntries) {
    if ($xe.Kind -cne 'static') { continue }
    $xLn = [int]$xe.Line
    if (($xLn -lt 1) -or ($xLn -gt @($script:StSourceLines).Count)) { [void]$xiBad.Add([string]$xe.Name); continue }
    $xTxt = [string]$script:StSourceLines[$xLn - 1]
    if (-not ($xTxt.Contains([string]$xe.Name) -or $xTxt.Contains(([string]$xe.Name).Replace("'", "''")))) { [void]$xiBad.Add([string]$xe.Name) }
  }
  ST-Check 'unit (index): every static entry points at a line that carries its name (full pass, not a sample) and the entry count clears a floor' (
    (@($xiBad).Count -eq 0) -and (@($xiEntries).Count -ge [int]$script:DeclaredCheckTotal))
  if (@($xiBad).Count -gt 0) { Write-Output ('      index entries whose line does not carry the name: ' + @($xiBad).Count) }

  $xmBad = 0
  if (-not (Test-OnlyPatternMatch 'P-06' 'lint (P-06): kept')) { $xmBad++ }
  if (Test-OnlyPatternMatch 'P-06' 'lint (P-01): other') { $xmBad++ }
  if (-not (Test-OnlyPatternMatch 'p-06' 'lint (P-06): case stays insensitive')) { $xmBad++ }
  if (Test-OnlyPatternMatch 'P-0.' 'P-06 dot stays literal') { $xmBad++ }
  if (-not (Test-OnlyPatternMatch 'contract' 'contract: region check')) { $xmBad++ }
  ST-Check 'unit (only): the matcher is a literal, case-insensitive substring (no regex, no wildcards)' ($xmBad -eq 0)

  $xrOk = 0
  if ((Resolve-SelftestOnlyPattern @()) -eq '') { $xrOk++ }
  if ((Resolve-SelftestOnlyPattern @('--only', 'P-06')) -eq 'P-06') { $xrOk++ }
  foreach ($xrBad in @(@('--live', '--only'), @('--only', '--live'), @('--only', 'a', '--only', 'b'))) {
    $xrThrew = $false
    try { [void](Resolve-SelftestOnlyPattern $xrBad) } catch { $xrThrew = $true }
    if ($xrThrew) { $xrOk++ }
  }
  ST-Check 'unit (only): value parsing leaves an absent flag alone and refuses missing, flag-like and duplicate values' ($xrOk -eq 5)

  $xsLegacy = Format-SelftestSummary 853 0 2 0 0 ''
  $xsFiltered = Format-SelftestSummary 3 1 0 851 4 'P-06'
  ST-Check 'unit (only): the summary is byte-identical without a filter and discloses the absorbed counts with one' (
    ($xsLegacy -ceq '----- selftest: 853 passed, 0 failed, 2 skipped -----') -and
    ($xsFiltered -ceq "----- selftest: 3 passed, 1 failed, 0 skipped (--only 'P-06': 4 reported, 851 absorbed incl. 4 failed, of 855) -----"))

  $xwAbsorb = @($srcLines | Where-Object { ([string]$_).Contains('Test-St' + 'OnlyAbsorb ') }).Count
  $xwActive = @($srcLines | Where-Object { ([string]$_).Contains('$script:St' + 'OnlyActive') }).Count
  $xwResolve = @($srcLines | Where-Object { ([string]$_).Contains('= Resolve-Selftest' + 'OnlyPattern ') }).Count
  ST-Check 'lint (only): one resolver call site, one absorb helper called by exactly the two emitters, state read in four pinned places (a drifting rename reads as red)' (
    ($xwResolve -eq 1) -and ($xwAbsorb -eq 2) -and ($xwActive -eq 4))
  Write-Output ('      only plumbing: resolve=' + $xwResolve + ' absorb=' + $xwAbsorb + ' active=' + $xwActive)

  if ($script:PsChildOk) {
    $xiChildOut = Join-Path $env:TEMP ('st_idxe2e_' + [guid]::NewGuid().ToString('N') + '.txt')
    $xiChildArgs = '-NoProfile -ExecutionPolicy Bypass -File "' + $self + '" selftest --index'
    $xiCp = Start-Process -FilePath 'powershell.exe' -ArgumentList $xiChildArgs -RedirectStandardOutput $xiChildOut -RedirectStandardError ($xiChildOut + '.err') -Wait -PassThru -NoNewWindow
    $xiChildTxt = ''
    if (Test-Path -LiteralPath $xiChildOut) { $xiChildTxt = [string](Get-Content -Raw -LiteralPath $xiChildOut) }
    $xiChildN = @(($xiChildTxt -split "`r?`n") | Where-Object { (([string]$_).Contains("`t")) }).Count
    ST-Check 'e2e (index): a real child lists the checks without running them (no summary line, entry floor met)' (
      ($xiCp.ExitCode -eq 0) -and ($xiChildTxt.Contains('selftest index: ')) -and (-not $xiChildTxt.Contains(' passed,')) -and ($xiChildN -ge [int]$script:DeclaredCheckTotal))
    Remove-Item -LiteralPath $xiChildOut -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath ($xiChildOut + '.err') -Force -ErrorAction SilentlyContinue

    $xiComboOut = Join-Path $env:TEMP ('st_idxcombo_' + [guid]::NewGuid().ToString('N') + '.txt')
    $xiComboArgs = '-NoProfile -ExecutionPolicy Bypass -File "' + $self + '" selftest --index --live'
    $xiCb = Start-Process -FilePath 'powershell.exe' -ArgumentList $xiComboArgs -RedirectStandardOutput $xiComboOut -RedirectStandardError ($xiComboOut + '.err') -Wait -PassThru -NoNewWindow
    $xiComboTxt = ''
    if (Test-Path -LiteralPath $xiComboOut) { $xiComboTxt = [string](Get-Content -Raw -LiteralPath $xiComboOut) }
    if (Test-Path -LiteralPath ($xiComboOut + '.err')) { $xiComboTxt += [string](Get-Content -Raw -LiteralPath ($xiComboOut + '.err')) }
    ST-Check 'e2e (index): the fast path refuses a combined flag by name and exits 1' (
      ($xiCb.ExitCode -eq 1) -and ($xiComboTxt.Contains('--index cannot be combined with --live')))
    Remove-Item -LiteralPath $xiComboOut -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath ($xiComboOut + '.err') -Force -ErrorAction SilentlyContinue
  } else {
    ST-Skip 'e2e (index): a real child lists the checks without running them (no summary line, entry floor met)' ('no powershell.exe resolvable in PATH: ' + $script:PsChildWhy)
    ST-Skip 'e2e (index): the fast path refuses a combined flag by name and exits 1' ('no powershell.exe resolvable in PATH: ' + $script:PsChildWhy)
  }

  $xiSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
  $xiTpl = New-Object System.Collections.ArrayList
  foreach ($xe in $xiEntries) {
    if ($xe.Kind -ceq 'template') { [void]$xiTpl.Add([string]$xe.Pattern) } else { [void]$xiSet.Add([string]$xe.Name) }
  }
  $xiMiss = New-Object System.Collections.ArrayList
  foreach ($xn in @($script:StEmittedAll)) {
    $xOkName = $xiSet.Contains([string]$xn)
    if (-not $xOkName) {
      foreach ($xp in @($xiTpl)) { if ([string]$xn -match $xp) { $xOkName = $true; break } }
    }
    if (-not $xOkName) { [void]$xiMiss.Add([string]$xn) }
  }
  ST-Check 'contract: selftest index lists every check name this run emitted (the index cannot rot silently)' (
    (@($script:StEmittedAll).Count -ge 700) -and (@($xiMiss).Count -eq 0))
  if (@($xiMiss).Count -gt 0) { Write-Output ('      emitted but missing from the index: ' + (@($xiMiss) -join ' | ')) }

  ST-Check 'contract: selftest PASS line count equals passed summary count' (@($script:StPassLines).Count -eq $script:StPass)
  # v3.0.0 (S-4): the LAST check, so the arithmetic covers every check above AND itself.
  # Only the offline run is pinned - a --live run legitimately has more checks, and pretending
  # otherwise would make the declaration a live-mode failure instead of a version record. The
  # live path reports SKIP with the number it saw, which is the honest form of "not measured".
  $s4Total = [int]$script:StPass + [int]$script:StFail + [int]$script:StSkip + 1
  if ($live) {
    ST-Skip 'contract: declared check total (live run adds checks, so the offline declaration does not apply)' "live-total=$s4Total"
  } elseif ($script:StOnlyActive) {
    ST-Skip 'contract: declared check total (a scoped run reports a subset, so the offline declaration does not apply)' "filtered=$s4Total"
  } else {
    ST-Check 'contract: this version declares its offline check total and the run matches it' ($s4Total -eq [int]$script:DeclaredCheckTotal)
    if ($s4Total -ne [int]$script:DeclaredCheckTotal) {
      Write-Output "      declared=$($script:DeclaredCheckTotal) this-run-would-be=$s4Total - set the declaration at the top of the file (RAISING AN EXPECTED COUNT; it does not loosen any check)"
    }
  }
  Write-Output (Format-SelftestSummary $script:StPass $script:StFail $script:StSkip $script:StAbsorbed $script:StAbsorbedFail $script:StOnlyPat)
  if ($script:StFail -gt 0) { throw "selftest: $($script:StFail) check(s) FAILED" }
}


# lib/selftest-split-machine.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1 by A-14b (A-beta).
# Bodies are byte-identical to what the section carried; this file exists so that a family of
# checks can be read, moved and counted on its own. The only channel to the orchestrator is the
# explicit context object: shared state arrives through $Ctx and nothing else, because the
# dynamic-scope chain that used to feed these lines is exactly the implicit link A-08/A-09/A-11
# proved can break silently on a move.
# Family: the split machine itself - the source set, the aggregate line map, the mode announcement,
function Invoke-SelftestFamily-SplitMachine($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $self = [string]$Ctx['self']
  $src = [string]$Ctx['src']
#   the AST inventories and the audit-name contracts. It is the head of the section by design:
#   every gate that measures how this file was cut lives here, so a bad cut reports itself.
  # ---------- lint: file encoding invariants ----------
  $bytes = [System.IO.File]::ReadAllBytes($self)
  $hasBom = ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)
  ST-Check 'lint: UTF-8 BOM present + pure ASCII beyond it (v1.5.0 task invariant; BOM+ASCII parses identically on PS 5.1)' ($hasBom -and (([regex]::Matches($src, '[^\x00-\x7F]')).Count -eq 0))
  ST-Check 'lint: file is pure ASCII' (([regex]::Matches($src, '[^\x00-\x7F]')).Count -eq 0)
  # ---------- v4.4.0 (A-03): the source set is under test, not merely in use ----------
  # Planted fixtures: until the first lib/ file exists the aggregate path is unreachable in
  # the live tree, so the loader, the order it promises and the mode split are measured here
  # instead of being trusted because the run happened to be green.
  $a03Root = Join-Path ([System.IO.Path]::GetTempPath()) ('acu-a03-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))
  try {
    New-Item -ItemType Directory -Path $a03Root | Out-Null
    $a03Enc = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText((Join-Path $a03Root 'first.ps1'), 'MARKER-ONE-line', $a03Enc)
    [System.IO.File]::WriteAllText((Join-Path $a03Root 'second.ps1'), 'MARKER-TWO-line', $a03Enc)
    $a03Fwd = Get-AggregatedSource $a03Root @('first.ps1', 'second.ps1')
    $a03Rev = Get-AggregatedSource $a03Root @('second.ps1', 'first.ps1')
    ST-Check 'unit (A-03): the aggregator concatenates planted sources in the declared order' (
      ($a03Fwd.IndexOf('MARKER-ONE') -ge 0) -and ($a03Fwd.IndexOf('MARKER-ONE') -lt $a03Fwd.IndexOf('MARKER-TWO')))
    ST-Check 'unit (A-03): the same aggregator flips the verdict on a reversed declaration (order is measured, not assumed)' (
      $a03Rev.IndexOf('MARKER-ONE') -gt $a03Rev.IndexOf('MARKER-TWO'))
    $a03Threw = ''
    try { [void](Get-AggregatedSource $a03Root @('first.ps1', 'not-there.ps1')) } catch { $a03Threw = "$($_.Exception.Message)" }
    ST-Check 'unit (A-03): a declared file missing on disk throws and names it (a half-landed split cannot read as green)' (
      $a03Threw.Contains('not-there.ps1'))
    $a03NoLib = Get-SourceModeBeside $a03Root
    New-Item -ItemType Directory -Path (Join-Path $a03Root 'lib') | Out-Null
    $a03WithLib = Get-SourceModeBeside $a03Root
    ST-Check 'unit (A-03): the mode discriminator reads both ways on planted roots (no lib = single-file, lib = aggregate)' (
      ($a03NoLib -ceq 'single-file') -and ($a03WithLib -ceq 'aggregate'))
  } finally {
    if (Test-Path -LiteralPath $a03Root) { Remove-Item -LiteralPath $a03Root -Recurse -Force }
  }
  ST-Check 'lint (A-03): the entry declares itself first, and the predicate rejects a planted reversed set (it cannot pass by being always true) ' (
    (Test-EntryFirstSource @($script:StSourceFiles)) -and (-not (Test-EntryFirstSource @('lib\\z.ps1', 'desktop.ps1'))))
  $a03Ghost = Get-LoadTimeInitsMissing @('$script:RealOne = 1') @('$script:RealOne = 1', '$script:GhostTwo = 2')
  ST-Check 'unit (A-03): the load-time inventory predicate flags a planted missing statement (it cannot pass by seeing nothing)' (
    ($a03Ghost -ceq '$script:GhostTwo = 2'))
  $a03MissingInits = Get-LoadTimeInitsMissing @($script:StSourceLines) $script:StLoadTimeInits
  ST-Check 'lint (A-03): all eleven load-time statements still match verbatim, name and value (a pure move cannot drop or rewrite state)' (
    ($a03MissingInits -ceq ''))
  if ("$a03MissingInits" -ne '') { Write-Output ('      missing load-time inits: ' + $a03MissingInits) }
  # ---------- v4.4.0 (A-04): an aggregate line number must name its file ----------
  $a04Plant = @(
    [pscustomobject]@{ File = 'a.ps1'; Start = 1; Count = 3 },
    [pscustomobject]@{ File = 'lib/b.ps1'; Start = 5; Count = 4 }
  )
  $a04InA = Resolve-SourceLineFromSpans 2 $a04Plant
  $a04InB = Resolve-SourceLineFromSpans 6 $a04Plant
  $a04Out = Resolve-SourceLineFromSpans 99 $a04Plant
  # The aggregate gate that reads the real tree SKIPs until a lib/ directory exists (A-11), so
  # the boundary rule is measured here on a planted pair - otherwise it would ship untested.
  $a04SRoot = Join-Path ([System.IO.Path]::GetTempPath()) ('acu-a04-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))
  New-Item -ItemType Directory -Path $a04SRoot | Out-Null
  $a04Enc2 = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText((Join-Path $a04SRoot 'one.ps1'), "a`r`nb`r`nc`r`n", $a04Enc2)
  [System.IO.File]::WriteAllText((Join-Path $a04SRoot 'two.ps1'), "d`r`ne`r`n", $a04Enc2)
  $a04Sp = @(Get-SourceLineSpans $a04SRoot @('one.ps1', 'two.ps1'))
  $a04AggLen = @((Get-AggregatedSource $a04SRoot @('one.ps1', 'two.ps1')) -split "`r?`n").Count
  $a04SpThrew = ''
  try { [void](Get-SourceLineSpans $a04SRoot @('gone.ps1')) } catch { $a04SpThrew = "$($_.Exception.Message)" }
  Remove-Item -LiteralPath $a04SRoot -Recurse -Force
  ST-Check 'unit (A-04): resolver names the owner both sides of a boundary, the planted pair pins the boundary arithmetic, and a declared missing file throws' (
    ($a04InA -ceq 'a.ps1:2') -and ($a04InB -ceq 'lib/b.ps1:2') -and ([string]$a04Out).StartsWith('beyond-aggregate:') -and
    (@($a04Sp).Count -eq 2) -and ([int]$a04Sp[0].Start -eq 1) -and ([int]$a04Sp[0].Count -eq 4) -and
    ([int]$a04Sp[1].Start -eq 5) -and ([int]$a04Sp[1].Count -eq 3) -and
    ([int]$a04Sp[0].Count + [int]$a04Sp[1].Count -eq $a04AggLen) -and
    $a04SpThrew.Contains('gone.ps1'))
  # !! Every token below is ASSEMBLED at run time. A scan token written out as a literal is
  #    present in the very text this gate reads, so the gate would report its own source as a
  #    violation forever (P-05, P-06 and X-01 are this file's named precedents for exactly that).
  $a04D = [char]0x24
  $a04Q = [char]0x27
  $a04Shapes = @(
    ('line ' + $a04D + '(' + '$ti + 1)'),
    ('line ' + $a04D + '(' + '$ri + 1)'),
    ('line ' + $a04D + '(' + '$k + 1)'),
    ('"line " + ' + $a04D + 'gaLineNo'),
    ($a04Q + 'line ' + $a04Q + ' + (' + $a04D + 'ari + 1)')
  )
  $a04Needle = 'Format-SourceLineRef' + ' ('
  $a04Left = @()
  foreach ($sh in $a04Shapes) {
    if (@(@($script:StSourceLines) | Where-Object { ([string]$_).Contains([string]$sh) }).Count -gt 0) { $a04Left += [string]$sh }
  }
  # and the scan is proven ABLE to match: a planted line assembled from the same token must
  # be caught, otherwise "zero left" would be a gate that cannot go red.
  $a04Planted = ('  [void]$x.Add("' + $a04Shapes[0] + ': planted")')
  $a04Canary = 0
  foreach ($sh in $a04Shapes) { if (([string]$a04Planted).Contains([string]$sh)) { $a04Canary++ } }
  $a04Calls = @(@($script:StSourceLines) | Where-Object { ([string]$_).Contains($a04Needle) }).Count
  ST-Check 'lint (A-04): none of the five A-04 echo shapes prints a bare index any more, the resolver has call sites, and the scan catches a planted shape' (
    (@($a04Left).Count -eq 0) -and ($a04Canary -ge 1) -and ($a04Calls -ge 9))
  Write-Output ('      A-04 resolver: call sites=' + $a04Calls + ' bare shapes left=' + @($a04Left).Count + ' shapes scanned=' + @($a04Shapes).Count + ' canary=' + $a04Canary)
  if ("$script:StSourceMode" -ceq 'aggregate') {
    $a04Bad = @()
    foreach ($sp in @($script:StSourceSpans)) {
      $own = @([System.IO.File]::ReadAllLines((Join-Path $script:ToolRootPath ([string]$sp.File)), [System.Text.Encoding]::UTF8))
      $aggAt = [string]$script:StSourceLines[[int]$sp.Start - 1]
      if ("$aggAt" -cne "$($own[0])") { $a04Bad += ([string]$sp.File) }
    }
    ST-Check 'lint (A-04): every declared file really begins on the aggregate line the span map claims (first line against first line)' (
      @($a04Bad).Count -eq 0)
    if (@($a04Bad).Count -gt 0) { Write-Output ('      span starts that do not line up: ' + ($a04Bad -join ' ')) }
  } else {
    ST-Skip 'lint (A-04): every declared file really begins on the aggregate line the span map claims (first line against first line)' 'single-file source mode (no lib/ beside the entry) - one file, no boundary to miss'
  }
  # ---------- v4.4.0 (A-05): the source set and the dot-import list must agree ----------
  $a05Root = Join-Path ([System.IO.Path]::GetTempPath()) ('acu-a05-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))
  New-Item -ItemType Directory -Path $a05Root | Out-Null
  New-Item -ItemType Directory -Path (Join-Path $a05Root 'lib') | Out-Null
  $a05Enc = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText((Join-Path $a05Root 'desktop.ps1'), "entry`r`n", $a05Enc)
  [System.IO.File]::WriteAllText((Join-Path $a05Root 'lib\ghost.ps1'), "x`r`n", $a05Enc)
  $a05Miss = Get-SourceSetDiscrepancy $a05Root @('desktop.ps1', 'lib/ghost.ps1', 'lib/gone.ps1')
  $a05Undecl = Get-SourceSetDiscrepancy $a05Root @('desktop.ps1')
  $a05Both = Get-SourceSetDiscrepancy $a05Root @('desktop.ps1', 'lib/ghost.ps1')
  ST-Check 'unit (A-05): the source-set predicate names a declared-missing file, names an on-disk-undeclared file, and stays silent when both sides agree' (
    $a05Miss.Contains('declared-missing:lib/gone.ps1') -and (-not $a05Miss.Contains('undeclared')) -and
    $a05Undecl.Contains('on-disk-undeclared:lib/ghost.ps1') -and (-not $a05Undecl.Contains('declared-missing')) -and ($a05Both -ceq ''))
  $a05Lines = @(
    ". (Join-Path `$PSScriptRoot 'lib/a.ps1') # <<< stitch: lib/a.ps1",
    ". (Join-Path `$PSScriptRoot 'lib/b.ps1') # <<< stitch: lib/b.ps1"
  )
  $a05Ok = Get-DotImportDiscrepancy $a05Lines @('desktop.ps1', 'lib/a.ps1', 'lib/b.ps1')
  $a05Swap = Get-DotImportDiscrepancy $a05Lines @('desktop.ps1', 'lib/b.ps1', 'lib/a.ps1')
  $a05Short = Get-DotImportDiscrepancy ($a05Lines[0..0]) @('desktop.ps1', 'lib/a.ps1', 'lib/b.ps1')
  $a05NoMark = Get-DotImportDiscrepancy @(". (Join-Path `$PSScriptRoot 'lib/a.ps1')") @('desktop.ps1', 'lib/a.ps1')
  # v4.4.0 (S-93): the swap that used to be invisible - the MARKERS stay in declared order and the REAL
  # paths trade places. A predicate that reads the comment cannot see it; one that reads the loader can.
  $a05PathSwap = Get-DotImportDiscrepancy @(". (Join-Path `$PSScriptRoot 'lib/b.ps1') # <<< stitch: lib/a.ps1", ". (Join-Path `$PSScriptRoot 'lib/a.ps1') # <<< stitch: lib/b.ps1") @('desktop.ps1', 'lib/a.ps1', 'lib/b.ps1')
  Remove-Item -LiteralPath $a05Root -Recurse -Force
  ST-Check 'unit (A-05): the dot-import predicate passes on an ordered pair, names a swapped pair, names a missing line, and names an import with no stitch marker' (
