  $a09Var = [string][char]0x24 + 'Cmd'
  $a09Own = $a09Var + 'Name'
  $a09Plant = @(
    'function F-Borrower($a) { return $Cmd }',
    'function F-Owner([string]$Cmd) { return $Cmd }',
    'function F-Silent($a) { return $a }'
  )
  $a09PlantParsed = Parse-SourceForInventory ($a09Plant -join "`n")
  $a09Bare = Get-VarUseCountInFunction $a07Parsed "$script:StCommandToken" $a09Var
  $a09OwnUses = Get-VarUseCountInFunction $a07Parsed "$script:StCommandToken" $a09Own
  $a09PlantBorrow = Get-VarUseCountInFunction $a09PlantParsed 'F-Borrower' $a09Var
  $a09PlantAbsent = Get-VarUseCountInFunction $a09PlantParsed 'F-No-Such' $a09Var
  ST-Check 'lint (A-09): the audited command body reads no caller-scope command variable at all and uses its own declared parameter twice, while a planted borrow and an absent function both come back named' (
    ($a09Bare -ceq '0') -and ($a09OwnUses -ceq '2') -and ($a09PlantBorrow -ceq '1') -and ($a09PlantAbsent -ceq '-absent'))
  $a09OwnerList = Get-VarUseOwnerList $a07Parsed $a09Var
  $a09OwnerGap = Get-InventoryDiscrepancy $a09OwnerList $script:StCmdVarUses
  $a09Uses = @($a09OwnerList -split ';').Count
  $a09EntryDeclares = $false
  foreach ($a09N in @((Get-EntryParamNameString $a07Parsed) -split ';')) { if ([string]$a09N -ceq 'Cmd') { $a09EntryDeclares = $true } }
  $a09Undeclared = Get-UndeclaredVarUseDiscrepancy $a07Parsed $a09Var $a09EntryDeclares
  $a09NoExemption = Get-UndeclaredVarUseDiscrepancy $a07Parsed $a09Var $false
  $a09PlantNote = Get-UndeclaredVarUseDiscrepancy $a09PlantParsed $a09Var $true
  ST-Check 'lint (A-09): every use of the dispatcher command variable sits in an owner that declares it, a planted borrower is named with its count while a planted owner is left alone, and the top-level exemption is itself load-bearing' (
    ($a09Undeclared -ceq '') -and ($a09PlantNote.Contains('fn:F-Borrower=uses1-undeclared')) -and
    (-not $a09PlantNote.Contains('fn:F-Owner=')) -and ($a09NoExemption.Contains('script-uses15-without-entry-param')))
  if ($a09Undeclared -ne '') { Write-Output ('      undeclared uses: ' + $a09Undeclared) }
  $a09DYes = Get-FunctionDeclaresParameter $a09PlantParsed 'F-Owner' 'Cmd'
  $a09DNo = Get-FunctionDeclaresParameter $a09PlantParsed 'F-Borrower' 'Cmd'
  $a09DAbsent = Get-FunctionDeclaresParameter $a09PlantParsed 'F-No-Such' 'Cmd'
  ST-Check 'unit (A-09): the declare-check keeps yes, no and absent distinguishable, and the registered owners account for every use of the dispatcher variable (the count is in the detail line, not in the name)' (
    ($a09DYes -ceq 'yes') -and ($a09DNo -ceq 'no') -and ($a09DAbsent -ceq 'absent') -and
    ($a09OwnerGap -ceq '') -and ($a09Uses -eq 83) -and (@($script:StCmdVarUses).Count -eq 42))
  if ($a09OwnerGap -ne '') { Write-Output ('      use owners: ' + $a09OwnerGap) }
  Write-Output ('      A-09: uses=' + $a09Uses + ' owners=' + @($script:StCmdVarUses).Count + ' entry-declares=' + $a09EntryDeclares +
    ' bare-reads-in-audited-body=' + $a09Bare + ' own-param-uses=' + $a09OwnUses + ' undeclared=[' + $a09Undeclared + ']')

  # ---------- v4.4.0 (A-11a): the path anchors are the only way a moved section can name the tool ----------
  $a11Parsed = $a07Parsed
  $a11SelfCount = Get-PathReadCountInFunction $a11Parsed 'Invoke-SelfTest'
  $a11Absent = Get-PathReadCountInFunction $a11Parsed 'F-No-Such-Function'
  $a11Plant = @(
    'function F-UsesAutoPath($a) { return ($a + $PSScriptRoot) }',
    'function F-UsesAnchor($a) { return ($a + $script:ToolRootPath) }'
  )
  $a11PlantParsed = Parse-SourceForInventory ($a11Plant -join "`n")
  $a11PlantAuto = Get-PathReadCountInFunction $a11PlantParsed 'F-UsesAutoPath'
  $a11PlantAnchor = Get-PathReadCountInFunction $a11PlantParsed 'F-UsesAnchor'
  ST-Check 'unit (A-11a): the path-read counter sees a planted automatic-variable read, stays at zero for a planted anchor read, and says absent for a function that is not there' (
    ($a11PlantAuto -ceq '1') -and ($a11PlantAnchor -ceq '0') -and ($a11Absent -ceq '-absent'))
  $a11Owners = Get-PathReadOwnerList $a11Parsed
  $a11OwnerGap = Get-InventoryDiscrepancy $a11Owners $script:StPathReadOwners
  # A-11b/A-13/A-14b: every dot-import line is itself a read of $PSScriptRoot at the entry top level
  # (twenty-two of them now) - and that is the one place where it still means the tool root. Registered,
  # not excused. A family file that reintroduced a bare read would show up as an unlisted owner row.
  $a11Total = 0
  if ("$a11Owners" -ne '') { $a11Total = @($a11Owners -split ';').Count }
  # A-22: the owner table attributes each remaining read to the FILE that holds it. In a stitched artifact
  #    there is only one file and the twenty-two dot-import reads are gone by construction, so the table
  #    cannot be reconciled here - it is an aggregate-mode claim, like the A-05 pair above. The two
  #    mode-independent claims (the planted predicate, and the anchors resolving) stay executed in both.
  if ($script:StSourceMode -ceq 'aggregate') {
    ST-Check 'lint (A-11a): the selftest section no longer reads an automatic path variable, and the readers that remain are exactly the registered sections that have not moved yet' (
      ($a11OwnerGap -ceq '') -and ($a11Total -eq 31) -and (@($script:StPathReadOwners).Count -eq 6) -and
      ($a11SelfCount -ceq '0'))
    if ($a11OwnerGap -ne '') { Write-Output ('      path readers: ' + $a11OwnerGap) }
  } else {
    ST-Skip 'lint (A-11a): the selftest section no longer reads an automatic path variable, and the readers that remain are exactly the registered sections that have not moved yet' 'single-file source mode (no lib/ beside the entry) - one file, and the dot-import reads the table counts were replaced by the stitcher'
  }
  $a11Mapped = $script:StFileMap['desktop.ps1']
  $a11LeafOk = [bool](Test-Path -LiteralPath "$script:ToolEntryPath" -PathType Leaf)
  $a11DirOk = $false
  if ($a11LeafOk) { $a11DirOk = ((Get-Item -LiteralPath "$script:ToolEntryPath").Directory.FullName -ceq "$script:ToolRootPath") }
  $a11MapOk = ("$script:ToolEntryPath" -ceq "$a11Mapped")
  ST-Check 'lint (A-11a): the published anchors resolve to a real entry file whose directory is the published root, and the entry they name is the same path the source list maps desktop.ps1 to' (
    $a11LeafOk -and $a11DirOk -and $a11MapOk -and (("$script:ToolRootPath").Length -gt 3))
  Write-Output ('      A-11a anchors: root=[' + "$script:ToolRootPath" + '] entry=[' + ("$script:ToolEntryPath").Substring(0, [Math]::Min(46, ("$script:ToolEntryPath").Length)) + ']' +
    ' selftest-path-reads=' + $a11SelfCount + ' remaining-reads=' + $a11Total + ' registered-owners=' + @($script:StPathReadOwners).Count)

  # ---------- v4.4.0 (A-12): a line number in the moved section has to say which file it means ----------
  # A-11b put the section at the END of the aggregate, so a bare index echoed from here points at a
  # position a reader cannot locate in either visible file. Seven readings still printed raw aggregate
  # indices; they now go through the resolver, which yields 'file:line' in aggregate mode and the same
  # bare number in single-file mode (the installed product must not change shape - A-04's rule).
  # The scan is assembled from characters for the same reason A-04's is: a literal of a forbidden
  # shape is found by the gate that forbids it. The canary proves "zero left" is a measurement.
  $a12D = [string][char]0x24
  $a12Shapes = @(
    ('(@(' + $a12D + 'j5Wire) -join '),
    ('(@(' + $a12D + 'evWire) -join '),
    ('((@(' + $a12D + 'tewCalls) | ForEach-Object'),
    ('(@(' + $a12D + 'dcCase) -join '),
    ('(' + $a12D + 'xEmit -join '),
    ('(@(' + $a12D + 'f2CallSites) -join '),
    ('(@(' + $a12D + 'c6Hard) -join ')
  )
  $a12Left = @()
  foreach ($a12Sh in $a12Shapes) {
    if (@(@($script:StSourceLines) | Where-Object { ([string]$_).Contains([string]$a12Sh) }).Count -gt 0) { $a12Left += [string]$a12Sh }
  }
  $a12Planted = ('  Write-Output "      J-05 sites: $(@(' + $a12D + 'j5Wire).Count) (lines $(@(' + $a12D + 'j5Wire) -join '' ''))"')
  $a12Canary = 0
  foreach ($a12Sh in $a12Shapes) { if (([string]$a12Planted).Contains([string]$a12Sh)) { $a12Canary = $a12Canary + 1 } }
  ST-Check 'lint (A-12): the seven readings A-11b left as bare aggregate indices are resolver-routed, and the scan catches a planted bare join (so zero-left means measured, not blind)' (
    (@($a12Left).Count -eq 0) -and ($a12Canary -ge 1) -and (@($a12Shapes).Count -eq 7))
  Write-Output ('      A-12 bare-index scan: shapes=' + @($a12Shapes).Count + ' left=' + @($a12Left).Count + ' canary=' + $a12Canary)
  if (@($a12Left).Count -gt 0) { Write-Output ('      still bare: ' + ($a12Left -join ' | ')) }
  # The other thing A-11b changed: the audited command and the double that replaces it now live in
  # DIFFERENT files. Attribution is read off the span resolver rather than a remembered line number,
  # so the check moves with the code instead of rotting where it was written.
  $a12ProdMark = 'function ' + "$script:StCommandToken" + '('
  $a12StubMark = '} = { param(' + $a12D + 'la, ' + $a12D + 'detail'
  $a12ProdLine = -1
  $a12StubLine = -1
  for ($a12i = 0; $a12i -lt @($script:StSourceLines).Count; $a12i++) {
    $a12t = [string]$script:StSourceLines[$a12i]
    if (($a12ProdLine -lt 0) -and $a12t.StartsWith($a12ProdMark)) { $a12ProdLine = $a12i + 1 }
    if (($a12StubLine -lt 0) -and $a12t.Contains($a12StubMark)) { $a12StubLine = $a12i + 1 }
  }
  $a12ProdRef = [string](Format-SourceLineRef $a12ProdLine)
  $a12StubRef = [string](Format-SourceLineRef $a12StubLine)
  $a12Align = Get-StubAlignmentDiscrepancy $a07Parsed "$script:StCommandToken"
  $a12Attribution = $false
  if ("$script:StSourceMode" -ceq 'aggregate') {
    # v4.4.0 (A-14o): the predicate used to name the file that held the double, and lifting that body
    # (A-14o moved it to lib/selftest-drag-press.ps1) made a true claim read false. Ask the question the
    # sentence actually asks: the double must sit INSIDE THE SELFTEST SPAN - the window the section
    # publishes - and the definition in the entry. A file name is not a boundary; the span is.
    $a12InWindow = ($a12StubLine -gt [int]$Ctx['j5ProdStart']) -and ($a12StubLine -le [int]$Ctx['j5ProdEnd'])
    $a12Attribution = ($a12ProdRef.StartsWith('desktop.ps1:')) -and $a12InWindow
  } else {
    $a12Attribution = (-not $a12ProdRef.Contains(':')) -and (-not $a12StubRef.Contains(':'))
  }
  ST-Check 'lint (A-12): the audited command is defined in the entry while its test double is installed inside the moved section, each is attributed to the file that really holds it, and the double still matches the production arity' (
    ($a12ProdLine -gt 0) -and ($a12StubLine -gt 0) -and ($a12ProdLine -ne $a12StubLine) -and
    $a12Attribution -and ($a12Align -ceq ''))
  Write-Output ('      A-12 table seam: production=[' + $a12ProdRef + '] double=[' + $a12StubRef + '] alignment=[' + $a12Align + '] mode=' + "$script:StSourceMode")

  # ---------- v4.4.0 (A-14a): the selftest body is attributed to families, by banner text ----
  # The partition must be MEASURED, not guessed: v7 B.3's keyword sketch left 3,610 lines
  # unclassified, which is larger than any real family. So every banner in the selftest body is
  # enumerated here, claimed by exactly one declared family (precedence is data), and each family's
  # banner count and line span are compared with the registered table. When A-14b starts cutting the
  # body into family files, a family that shrinks by accident shows up in this line, not in a comment.
  $a14Scope = @('Invoke-SelfTest')
  foreach ($a14lk in @($script:StFamilyLifted)) { $a14Scope += Get-FamilyFunctionName $a14lk }
  $a14Records = Get-FamilyBannerRecords $a07Parsed @($script:StSourceLines) $a14Scope
  $a14Assign = Get-FamilyAssignText "$a14Records" $script:StFamilyOrder $script:StFamilyFragments
  $a14Notes = Get-FamilyAgreement "$a14Assign" $script:StFamilyOrder $script:StFamilyCounts
  $a14BannerCount = 0
  if ("$a14Records" -ne '') { $a14BannerCount = @("$a14Records" -split "`n").Count }
  ST-Check 'lint (A-14a): every banner in the selftest body is claimed by exactly one declared family, and the measured tallies equal the registered table (a shrunk or empty family is named with its numbers)' (
    ("$a14Notes" -ceq '') -and ($a14BannerCount -eq 165) -and (@($script:StFamilyOrder).Count -eq 15) -and
    (@($script:StFamilyCounts.Keys).Count -eq 15))
  if ("$a14Notes" -ne '') { Write-Output ('      family attribution drift: ' + $a14Notes) }
  Write-Output ('      A-14a families=' + @($script:StFamilyOrder).Count + ' banners=' + $a14BannerCount + ' measured=[' + (("$a14Assign" -split "`n") -join ' / ') + ']')
  $a14PlantRec = (@(
    ("live: v9.9.9 verification-challenge workflow end to end" + "`t" + 7),
    ("v9.9.9 verification-challenge workflow offline shapes" + "`t" + 3),
    ("a banner nobody claimed in a thousand years" + "`t" + 11)
  ) -join "`n")
  $a14PlantAssign = Get-FamilyAssignText $a14PlantRec $script:StFamilyOrder $script:StFamilyFragments
  $a14PlantOk = Get-FamilyAgreement $a14PlantAssign @('live-suite', 'challenge-workflow') @{ 'live-suite' = 'banners=1,lines=7'; 'challenge-workflow' = 'banners=1,lines=3' }
  $a14PlantShrunk = Get-FamilyAgreement $a14PlantAssign @('live-suite', 'challenge-workflow') @{ 'live-suite' = 'banners=9,lines=99'; 'challenge-workflow' = 'banners=1,lines=3' }
  $a14PlantEmpty = Get-FamilyAgreement $a14PlantAssign @('live-suite', 'challenge-workflow', 'drag-press') @{ 'live-suite' = 'banners=1,lines=7'; 'challenge-workflow' = 'banners=1,lines=3'; 'drag-press' = 'banners=3,lines=191' }
  ST-Check 'unit (A-14a): live banners are claimed by the mode family ahead of their topic family, an unclaimed banner is reported instead of dropped, and a shrunk or empty registered family is named with both numbers' (
    ($a14PlantAssign.Contains('live-suite' + [string][char]9 + '1' + [string][char]9 + '7')) -and
    ($a14PlantAssign.Contains('challenge-workflow' + [string][char]9 + '1' + [string][char]9 + '3')) -and
    (-not $a14PlantAssign.Contains('challenge-workflow' + [string][char]9 + '2')) -and
    ($a14PlantOk.Contains('unclaimed-banners=1-lines=11')) -and
    ($a14PlantShrunk.Contains('live-suite=gotbanners=1,lines=7-wantbanners=9,lines=99')) -and
    ($a14PlantEmpty.Contains('drag-press=registered-but-empty')))
  $a14ScopePlant = @(
    'function Invoke-SelfTest([string[]]$Rest) {',
    '  # ---------- v9.9.9 alpha banner inside ----------',
    '  $x = 1',
    '  # ---------- v9.9.9 beta banner inside ----------',
    '  return $x',
    '}',
    'function Other-Thing {',
    '  # ---------- v9.9.9 gamma banner outside ----------',
    '}'
  )
  $a14ScopeParsed = Parse-SourceForInventory ($a14ScopePlant -join "`n")
  $a14ScopeRec = Get-FamilyBannerRecords $a14ScopeParsed @($a14ScopePlant)
  $a14ScopeCount = 0
  if ("$a14ScopeRec" -ne '') { $a14ScopeCount = @("$a14ScopeRec" -split "`n").Count }
  $a14ScopeAbsentParsed = Parse-SourceForInventory 'function Other-Thing { return 1 }'
  $a14ScopeAbsent = Get-FamilyBannerRecords $a14ScopeAbsentParsed @('function Other-Thing { return 1 }')
  $a14ScopeNoParse = Get-FamilyBannerRecords $null @('x')
  ST-Check 'unit (A-14a): the banner scan counts only what sits inside the selftest body, and answers -absent or -no-parse rather than zero when the body or the parse is not there (a count of nothing must never read as a count of zero)' (
    ($a14ScopeCount -eq 2) -and ("$a14ScopeRec".Contains('alpha banner inside')) -and ("$a14ScopeRec".Contains('beta banner inside')) -and
    (-not "$a14ScopeRec".Contains('gamma banner outside')) -and ("$a14ScopeAbsent" -ceq '-absent') -and ("$a14ScopeNoParse" -ceq '-no-parse'))

  # ---------- v4.4.0 (A-14b): a lifted family keeps its own state contract ----------
  # The cut above is only safe if the family that moved out still gets the same state it had when it
  # was inline. That cannot be asserted by "it still runs green": a missing context value reaches a
  # gate as an empty string, and an empty string satisfies a comparison that was never given a
  # non-empty witness. So the contract is measured on both sides - what the orchestrator publishes,
  # what each family asks for, and what each family still reaches for by bare name.
  $a14bPub = Get-CtxPublishedKeys $a07Parsed @($script:StSourceLines)
  $a14bPre = 'lib/selftest-'
  $a14bSuf = '.ps1'
  $a14bMissing = @()
  $a14bOrphan = @()
  $a14bGaps = @()
  foreach ($a14bKey in @($script:StFamilyLifted)) {
    $a14bWant = $a14bPre + [string]$a14bKey + $a14bSuf
    $a14bInList = $false
    foreach ($a14bF in @($script:StSourceFiles)) { if (([string]$a14bF) -ceq $a14bWant) { $a14bInList = $true } }
    if (-not $a14bInList) { $a14bMissing += ([string]$a14bKey + '=' + $a14bWant) }
    # v4.4.0 (A-14l): a family may also write its declared hand-backs back into the context object, so the
    # surface it is allowed to touch is the published keys plus its own export list. A sentinel in the
    # published list never equals a key name, so an unmeasurable publish side still reddens every ask.
    $a14bAllow = (@(@([string]$a14bPub -split ',') + @(Get-FamilyExportNames $a14bKey)) -join ',')
    $a14bGaps += Get-FamilyCtxGap $a07Parsed @($script:StSourceLines) (Get-FamilyFunctionName $a14bKey) $a14bAllow
  }
  # ---------- v4.4.0 (A-14q): the two exemptions above are measured against a real breach ----------
  # An exemption is only honest if the wall still stands next to it. One planted family uses both
  # shapes this lift carries (a nested function with its own parameters, an automatic-variable read)
  # and must come back CLEAN; a second planted family reads a plain caller local and must still be
  # named with its line. If either half is wrong the check says so - it cannot pass by measuring nothing.
  $a14qPlant = @(
    'function Invoke-SelftestFamily-CleanPlanted($Ctx) {',
    '  function Inner-Planted([string]$p, [int]$q) { return ($p + [string]$q) }',
    '  $r = Inner-Planted ''x'' 1',
    '  if ($PSVersionTable.PSVersion.Major -ge 5) { $r = ($r + ''5'') }',
    '  return $r',
    '}',
    'function Invoke-SelftestFamily-LeakPlanted($Ctx) {',
    '  return ($someCallerLocal + 1)',
    '}')
  $a14qPlantParsed = Parse-SourceForInventory ($a14qPlant -join "`n")
  $a14qCleanGap = Get-FamilyCtxGap $a14qPlantParsed @($a14qPlant) 'Invoke-SelftestFamily-CleanPlanted' 'nothing'
  $a14qLeakGap = Get-FamilyCtxGap $a14qPlantParsed @($a14qPlant) 'Invoke-SelftestFamily-LeakPlanted' 'nothing'
  # ---------- v4.4.0 (S-92): the two shapes that used to read as clean ----------
  # Planted, so the fix is measured and not asserted: a DOUBLE-QUOTED ask for an unpublished key must be
  # named, and a single-quoted string that merely CONTAINS $live = 1 must not be credited with binding
  # it - while the line that really assigns $note still has to count as a binding (the control half,
  # without which "I stripped strings" could pass by stripping everything).
  $a92Plant = @(
    'function Invoke-SelftestFamily-DqWritePlanted($Ctx) {',
    '  $Ctx["undeclaredWritePlanted"] = 1',
    '}',
    'function Invoke-SelftestFamily-DqPlanted($Ctx) {',
    '  $v = $Ctx["unpublishedPlanted"]',
    '  return $v',
    '}',
    'function Invoke-SelftestFamily-FakeBindPlanted($Ctx) {',
    '  $note = ''x $live = 1 y''',
    '  return $live',
    '}')
  $a92Parsed = Parse-SourceForInventory ($a92Plant -join "`n")
  $a92DqGap = Get-FamilyCtxGap $a92Parsed @($a92Plant) 'Invoke-SelftestFamily-DqPlanted' 'nothing'
  $a92WriteGap = Get-FamilyExportGap $a92Parsed 'Invoke-SelftestFamily-DqWritePlanted' @()
  $a92FakeGap = Get-FamilyCtxGap $a92Parsed @($a92Plant) 'Invoke-SelftestFamily-FakeBindPlanted' 'nothing'
  ST-Check 'unit (S-92): a double-quoted context ask is scanned, and a binding that lives inside a single-quoted string is not credited (the real assignment on the same line still is)' (
    ($a92DqGap.Contains('unpublishedPlanted=asked-not-published-at-')) -and
    ($a92FakeGap.Contains('live=free-read-at-')) -and (-not $a92FakeGap.Contains('note=free-read')) -and
    ($a92WriteGap.Contains('undeclaredWritePlanted=written-not-declared')))
  Write-Output ('      S-92 fixtures: dq=[' + "$a92DqGap" + '] fakebind=[' + "$a92FakeGap" + '] write=[' + "$a92WriteGap" + ']')
  ST-Check 'unit (A-14q): a nested function binding its own parameters and an automatic-variable read are not scope leaks, while a plain caller-local read still is (both sides of the exemption measured)' (
    ("$a14qCleanGap" -ceq '') -and ("$a14qLeakGap").Contains('somecallerlocal=free-read-at-'))
  Write-Output ('      A-14q gap fixtures: clean=[' + "$a14qCleanGap" + '] leak=[' + "$a14qLeakGap" + ']')

  # the reverse direction: a file named lib/selftest-<x>.ps1 in the source set without <x> being a
  # declared lifted family is a body of gates nothing attributes, which is how a split gets lost
  foreach ($a14bF in @($script:StSourceFiles)) {
    $a14bTxt = [string]$a14bF
    if (-not $a14bTxt.StartsWith($a14bPre)) { continue }
    if (-not $a14bTxt.EndsWith($a14bSuf)) { continue }
    $a14bMid = $a14bTxt.Substring($a14bPre.Length, $a14bTxt.Length - $a14bPre.Length - $a14bSuf.Length)
    $a14bKnown = $false
    foreach ($a14bKey in @($script:StFamilyLifted)) { if (([string]$a14bKey) -ceq $a14bMid) { $a14bKnown = $true } }
    if (-not $a14bKnown) { $a14bOrphan += $a14bMid }
  }
  $a14bGapCount = 0
  foreach ($a14bG in @($a14bGaps)) { if ([string]$a14bG -ne '') { $a14bGapCount = $a14bGapCount + 1 } }
  ST-Check 'lint (A-14b): every lifted family has its file in the declared source set, every lib/selftest-<key>.ps1 in the set has a lifted family behind it, and the context the section publishes is not empty' (
    (@($a14bMissing).Count -eq 0) -and (@($a14bOrphan).Count -eq 0) -and ("$a14bPub" -ne '-none') -and ("$a14bPub" -ne '-no-parse'))
  Write-Output ('      A-14b set: published=[' + $a14bPub + '] file-missing=[' + ($a14bMissing -join ';') + '] orphan=[' + ($a14bOrphan -join ';') + ']')
  ST-Check 'lint (A-14b): a lifted family asks only for published context keys or its own declared hand-backs, and reads no plain variable out of the caller scope (each breach names the variable and its line)' (
    ($a14bGapCount -eq 0))
  foreach ($a14bG in @($a14bGaps)) { if ([string]$a14bG -ne '') { Write-Output ('      A-14b state gap: ' + $a14bG) } }

  # Gates must stay COUNTABLE after the move: the registered number per body is what proves a family
  # file kept its checks, and an empty family - the signature of a body dropped in transit - is refused.
  # The zero has to have a witness: a counter that answers '0' for everything would pass a comparison
  # against a registered 0, and a counter that never answers 0 cannot catch an emptied family. So plant
  # one body with no checks and one with a check, and require the counter to tell them apart.
  $a14bZeroPlant = @(
    'function F-Empty-Family-Planted { return 1 }',
    'function F-One-Check-Planted { ST-Check (1 -eq 1) }'
  )
  $a14bZeroParsed = Parse-SourceForInventory ($a14bZeroPlant -join "`n")
  $a14bZeroGot = Get-CheckCallCountInFunction $a14bZeroParsed 'F-Empty-Family-Planted'
  $a14bOneGot = Get-CheckCallCountInFunction $a14bZeroParsed 'F-One-Check-Planted'
  $a14bCountNotes = @()
  $a14bTotal = 0
  foreach ($a14bRow in @($script:StFamilyCheckCounts)) {
    $a14bPair = @([string]$a14bRow -split '=', 2)
    $a14bBody = [string]$a14bPair[0]
    $a14bWant = [string]$a14bPair[1]
    $a14bGot = Get-CheckCallCountInFunction $a07Parsed $a14bBody
    if ($a14bGot -ceq $a14bWant) {
      $a14bTotal = $a14bTotal + [int]$a14bWant
      if (([int]$a14bWant) -lt 1) { $a14bCountNotes += ($a14bBody + '=registered-empty-body') }
      continue
    }
    $a14bCountNotes += ($a14bBody + '-want' + $a14bWant + '-got' + $a14bGot)
  }
  foreach ($a14bN in (@('Invoke-SelfTest') + @(foreach ($a14bKey in @($script:StFamilyLifted)) { Get-FamilyFunctionName $a14bKey }))) {
    $a14bListed = $false
    foreach ($a14bRow in @($script:StFamilyCheckCounts)) { if (([string]$a14bRow).StartsWith(([string]$a14bN) + '=')) { $a14bListed = $true } }
    if (-not $a14bListed) { $a14bCountNotes += ([string]$a14bN + '=body-unlisted') }
  }
  ST-Check 'lint (A-14b): each selftest body carries the registered number of check emitters, no lifted family is counted as empty, and no body can hold gates without being listed' (
    (@($a14bCountNotes).Count -eq 0) -and ($a14bTotal -ge 3) -and ($a14bZeroGot -ceq '0') -and ($a14bOneGot -ceq '1'))
  Write-Output ('      A-14b check counts: total=' + $a14bTotal + ' planted-empty=' + $a14bZeroGot + ' planted-one=' + $a14bOneGot + ' notes=[' + ($a14bCountNotes -join ';') + ']')

  # ---------- v4.4.0 (A-14c): the published context surface is itself a declared contract ----------
  # A-14b proved a family may only ask for published keys; this proves the PUBLISH side is the one
  # someone chose. Both halves matter: an extra key is a channel opened in passing, a dropped key is
  # a family quietly handed a null. The scan reads the orchestrator's own assignments, and the
  # comparison prints both sorted lists, so a mismatch names the side that moved.
  $a14cPub = Get-CtxPublishedKeys $a07Parsed @($script:StSourceLines)
  $a14cGot = @()
  if (("$a14cPub" -ne '-none') -and ("$a14cPub" -ne '-no-parse')) { $a14cGot = @([string]$a14cPub -split ',') }
  $a14cGotSorted = (@($a14cGot | Sort-Object) -join ',')
  $a14cWantSorted = (@($script:StCtxKeys | Sort-Object) -join ',')
  # The surface must carry VALUES, not just names: a publish line that ships $null would satisfy a
  # key comparison and leave a family with an empty array (the exact silent form A-08's audit column
  # took). So measure the handover live - $codeLines length must equal the $clCount that was hoisted
  # from it, and both must be far above the size of any empty handover.
  $a14cArrLen = @($Ctx['codeLines']).Count
  $a14cCountVal = 0
  $a14cParseOk = [int]::TryParse([string]$Ctx['clCount'], [ref]$a14cCountVal)
  if (-not $a14cParseOk) { $a14cCountVal = -1 }
  ST-Check 'lint (A-14c): the context keys this section publishes equal the registered list, so no family channel opens or closes without a name in the table' (
    ($a14cGotSorted -ceq $a14cWantSorted) -and (@($a14cGot).Count -eq @($script:StCtxKeys).Count) -and (@($a14cGot).Count -ge 2))
  $a14cHLines = @($Ctx['hLines']).Count
  $a14cHCases = @(Get-HashKeys $Ctx['hCaseStarts']).Count
  $a14cHFnEnd = 0
  $a14cHFnOk = [int]::TryParse([string]$Ctx['hFnEnd'], [ref]$a14cHFnEnd)
  if (-not $a14cHFnOk) { $a14cHFnEnd = -1 }
  # v4.4.0 (A-14m): the hoisted marker and its scan result must arrive as values. A handed-over name
  # that is $null would make the reader below compare against an empty string and stay green.
  $a14cEvMarkHit = ([string]$Ctx['evMark']).Contains('Verdict')
  $a14cEvWireN = @($Ctx['evWire']).Count
  # v4.4.0 (A-14o): the case table has to arrive as a table AND as a callable - a handed-over name
  # (or a $null index) would make the reader that asks for a case come back empty and stay green.
  $a14oCasesN = @($Ctx['gaCases']).Count
  # The kind is checked BEFORE the call. Casting a name to a scriptblock parses it, so a handed-over
  # string would throw here and kill the run instead of reporting the breach - a gate has to survive the
  # exact failure it exists to catch (found by this card's own mutant harness, case O3).
  $a14oIdxKind = ($Ctx['gaCaseIdx'] -is [scriptblock])
  $a14oIdxHit = -99
  $a14oIdxMiss = -99
  if ($a14oIdxKind) {
    $a14oIdxHit = & ([scriptblock]$Ctx['gaCaseIdx']) 'click'
    $a14oIdxMiss = & ([scriptblock]$Ctx['gaCaseIdx']) 'no-such-command-planted'
  }
  # A-14p: the three settled values must be a real path pair and a real boolean; the window snapshot
  # must arrive as rows with a usable pid. Each is checked in the shape its consumer uses, so a
  # published NAME (string where an array belongs) or a $null cannot pass by being truthy-ish.
  $a14pLogOk = ($Ctx['actionLog'] -is [string]) -and (([string]$Ctx['actionLog']).EndsWith('actions.log'))
  $a14pOutOk = ($Ctx['outDir'] -is [string]) -and (([string]$Ctx['outDir']).EndsWith('shots'))
  $a14pLiveOk = ($Ctx['live'] -is [bool])
  # v4.4.0 (A-14q): the five names gate-meta reads must arrive as the shapes its consumers use. A
  # handed-over NAME would make an index comparison silently false; a parse object without its root
  # would make the banner scan answer -no-parse inside the family while the run stayed green. Each
  # is measured, not asserted: the count has to EQUAL the table it indexes, the bounds have to order
  # the way the loops expect, and the parse has to still carry an AST root.
  $a14qCasesInt = -1
  [void][int]::TryParse([string]$Ctx['gaCasesCount'], [ref]$a14qCasesInt)
  $a14qCasesMatch = ($a14qCasesInt -eq @($Ctx['gaCases']).Count)
  $a14qHelpStartInt = -1
  [void][int]::TryParse([string]$Ctx['gaHelpStart'], [ref]$a14qHelpStartInt)
  $a14qHelpEndInt = -1
  [void][int]::TryParse([string]$Ctx['gaHelpEnd'], [ref]$a14qHelpEndInt)
  $a14qDispInt = -1
  [void][int]::TryParse([string]$Ctx['gaDispStart'], [ref]$a14qDispInt)
  $a14qBoundsOk = ($a14qHelpStartInt -ge 0) -and ($a14qHelpEndInt -gt $a14qHelpStartInt) -and ($a14qDispInt -ge 0)
  $a14qParseRootOk = ($Ctx['j5SelfParsed']).Root -is [System.Management.Automation.Language.ScriptBlockAst]
  ST-Check 'unit (A-14c): the published context arrives as values, not as names - the handed line array and its hoisted count agree with each other and neither is an empty handover' (
    ($a14cArrLen -eq $a14cCountVal) -and ($a14cArrLen -gt 1000) -and ([int]$Ctx['j5ProdEnd'] -ge [int]$Ctx['j5ProdStart']) -and
    (@($Ctx['srcLines']).Count -eq $a14cArrLen) -and
    ($a14cHLines -gt 100) -and ($a14cHCases -ge 40) -and ($a14cHFnEnd -gt 0) -and
    ($a14cEvMarkHit -eq $true) -and ($a14cEvWireN -eq 2) -and
    ($a14oCasesN -ge 40) -and ($a14oIdxKind -eq $true) -and ($a14oIdxHit -ge 0) -and ($a14oIdxMiss -eq -1) -and
    ($a14pLogOk -eq $true) -and ($a14pOutOk -eq $true) -and ($a14pLiveOk -eq $true) -and
    ($a14qCasesMatch -eq $true) -and ($a14qBoundsOk -eq $true) -and ($a14qParseRootOk -eq $true))
  Write-Output ('      A-14c published: got=[' + $a14cGotSorted + '] want=[' + $a14cWantSorted + '] mode=' + ("$a14cPub"))
  Write-Output ('      A-14c live handover: codeLines=' + $a14cArrLen + ' clCount=' + $a14cCountVal +
    ' j5window=[' + [string]$Ctx['j5ProdStart'] + '..' + [string]$Ctx['j5ProdEnd'] + ']' +
    ' help=[' + $a14cHLines + ' lines, ' + $a14cHCases + ' cases, fnEnd=' + $a14cHFnEnd + ']')
  Write-Output ('      A-14o handover: gaCases=' + $a14oCasesN + ' kind-is-scriptblock=' + $a14oIdxKind + ' idx(click)=' + $a14oIdxHit + ' idx(planted-miss)=' + $a14oIdxMiss)
  Write-Output ('      A-14m handover: evMark-hit=' + $a14cEvMarkHit + ' evWire-sites=' + $a14cEvWireN)
  Write-Output ('      A-14q handover: cases-count=' + $a14qCasesInt + ' matches-table=' + $a14qCasesMatch +
    ' help=[' + $a14qHelpStartInt + '..' + $a14qHelpEndInt + '] disp-start=' + $a14qDispInt +
    ' parse-root-is-ast=' + $a14qParseRootOk)
  # A-14p: only the three values published in setup are witnessed here. The window snapshot is published
  # later in the body (in place, because it is a live enumeration) and this family runs before that
  # point - a first version of this witness reported w0-pid=-1, which was the gate correctly refusing an
  # ordering that never existed. Its check lives at the publish site instead (lint (A-14p) below).
  Write-Output ('      A-14p handover: actionLog-path=' + $a14pLogOk + ' outDir-path=' + $a14pOutOk +
    ' live-is-bool=' + $a14pLiveOk)

  # ---------- v4.4.0 (A-14f): the exemption window is measured, and its width is checked ----------
  # A window that says "everything from here to the next ^function" stops at the first family file, so
  # each family that moved out was quietly re-counted as production - two lints reddened on the move.
  # The fix is an AST extent over every selftest body; the thing that makes the fix safe is this gate:
  # a wider blanket exempts whatever happens to sit under it, so a foreign function inside the span is
  # named, and the planted case below proves the naming is not vacuous.
  $a14fNames = @('Invoke-SelfTest')
  foreach ($a14fK in @($script:StFamilyLifted)) { $a14fNames += Get-FamilyFunctionName $a14fK }
  $a14fWin = Get-SelftestWindow $a07Parsed @($a14fNames)
  $a14fForeign = Get-ForeignFunctionNames $a07Parsed @($a14fNames) "$a14fWin"
  $a14fPlant = @(
    'function Invoke-SelfTest {',
    '  return 1',
    '}',
    'function Helper-Inside-Window {',
    '  return 3',
    '}',
    'function Invoke-SelftestFamily-Fake {',
    '  return 2',
    '}',
    'function Truly-Outside {',
    '  return 4',
    '}'
  )
  $a14fPlantParsed = Parse-SourceForInventory ($a14fPlant -join "`n")
  $a14fPlantWin = Get-SelftestWindow $a14fPlantParsed @('Invoke-SelfTest', 'Invoke-SelftestFamily-Fake')
  $a14fPlantForeign = Get-ForeignFunctionNames $a14fPlantParsed @('Invoke-SelfTest', 'Invoke-SelftestFamily-Fake') "$a14fPlantWin"
  $a14fAbsentWin = Get-SelftestWindow (Parse-SourceForInventory 'function Other-Thing { return 1 }') @('Invoke-SelfTest')
  $a14fBadWindow = Get-ForeignFunctionNames $a14fPlantParsed @('Invoke-SelfTest') 'not-a-window'
  ST-Check 'lint (A-14f): the production window spans every selftest body by AST extent, no foreign function hides inside it, and the scan names a planted one instead of answering empty' (
    (("$a14fWin" -ne '-absent') -and ("$a14fWin" -ne '-no-parse')) -and ($a14fForeign -ceq '') -and
    ($a14fPlantForeign -ceq 'Helper-Inside-Window') -and ($a14fAbsentWin -ceq '-absent') -and ($a14fBadWindow -ceq '-bad-window'))
  Write-Output ('      A-14f window: [' + ("$a14fWin").Replace("`t", '..') + '] bodies=' + @($a14fNames).Count +
    ' foreign=[' + ("$a14fForeign") + '] planted=[' + ("$a14fPlantForeign") + '] absent=' + ("$a14fAbsentWin"))

  # and the scalars handed to the families must still BE the window - a stale pair would re-widen
  # production for every lifted body while every name-level check stayed green
  $a14fW = @([string]$a14fWin -split "`t", 2)
  ST-Check 'unit (A-14f): the window published through $Ctx is the same pair of numbers the AST measures now, so no lifted body is exempted by a stale span' (
    (@($a14fW).Count -eq 2) -and ([int]$Ctx['j5ProdStart'] -eq ([int]$a14fW[0] - 1)) -and ([int]$Ctx['j5ProdEnd'] -eq [int]$a14fW[1]))

  # ---------- v4.4.0 (A-14r): the chain predicate is planted in every breach shape it can name ----------
  # lint (A-14r) at the publish site judges the live tree, so it cannot be broken without editing the
  # tree; this gate judges the PREDICATE, and every fixture below is a shape the orchestration could
  # really drift into. The three the owner named for this card are here: a publish that was never
  # written, a consume that runs before the publish, and a publish carrying a different variable than
  # the re-bind bound. An expectation of "" would be a false green, so the clean fixture is only one
  # of the four readings asserted.
  $a14rChain = @('Invoke-SelftestFamily-PopupOcclusion $Ctx',
    '  $dcCase = $Ctx[''dcCase'']',
    '  $wT = $Ctx[''wT'']',
    '  $Ctx[''dcCase''] = $dcCase',
    '  $Ctx[''wT''] = $wT',
    'Invoke-SelftestFamily-GateMeta $Ctx')
  $a14rNoPub = @($a14rChain[0..3]) + @($a14rChain[5])
  $a14rEarly = @('Invoke-SelftestFamily-PopupOcclusion $Ctx',
    '  $dcCase = $Ctx[''dcCase'']',
    '  $wT = $Ctx[''wT'']',
    'Invoke-SelftestFamily-GateMeta $Ctx',
    '  $Ctx[''dcCase''] = $dcCase',
    '  $Ctx[''wT''] = $wT')
  $a14rCross = @('Invoke-SelftestFamily-PopupOcclusion $Ctx',
    '  $wA = $Ctx[''wA'']',
    '  $wB = $Ctx[''wB'']',
    '  $Ctx[''wA''] = $wB',
    'Invoke-SelftestFamily-GateMeta $Ctx')
  $a14rP = 'Invoke-SelftestFamily-PopupOcclusion'
  $a14rC = 'Invoke-SelftestFamily-GateMeta'
  $a14rG0 = Get-HandbackChainGap $a14rChain $a14rP $a14rC @('dcCase', 'wT')
  $a14rG1 = Get-HandbackChainGap $a14rNoPub $a14rP $a14rC @('dcCase', 'wT')
  $a14rG2 = Get-HandbackChainGap $a14rEarly $a14rP $a14rC @('dcCase', 'wT')
  $a14rG3 = Get-HandbackChainGap $a14rCross $a14rP $a14rC @('wA', 'wB')
  $a14rG4 = Get-HandbackChainGap @('Write-Output nothing-at-all') $a14rP $a14rC @('wA')
  $a14rSwap = @($a14rChain[0], $a14rChain[3], $a14rChain[1], $a14rChain[4], $a14rChain[2], $a14rChain[5])
  $a14rRev = @($a14rChain[5], $a14rChain[0], $a14rChain[1], $a14rChain[2], $a14rChain[3], $a14rChain[4])
  $a14rG5 = Get-HandbackChainGap $a14rSwap $a14rP $a14rC @('dcCase', 'wT')
  $a14rG6 = Get-HandbackChainGap $a14rRev $a14rP $a14rC @('dcCase', 'wT')
  $a14rG7 = Get-HandbackChainGap $a14rChain $a14rP $a14rP @('dcCase')
  $a14rG8 = Get-HandbackChainGap $a14rChain '' $a14rC @('dcCase')
  $a14rG9 = Get-HandbackChainGap $a14rChain $a14rP $a14rC @()
  ST-Check 'unit (A-14r): the chain predicate passes the ordered fixture and names every breach it can emit - missing publish, consume above the publish, a crossed value, a reversed pair, a publish before its re-bind - and refuses blank needles and an empty name list' (
    ($a14rG0 -ceq '') -and ($a14rG1 -ceq 'no-publish:wT') -and
    ($a14rG2 -ceq 'no-publish:dcCase,no-publish:wT') -and ($a14rG3 -ceq 'publish-name-wA=$wB,no-publish:wB') -and
    ($a14rG4 -ceq 'no-produce:Invoke-SelftestFamily-PopupOcclusion,no-consume:Invoke-SelftestFamily-GateMeta') -and
    ($a14rG5 -ceq 'order-rebind-publish-dcCase=2/1,order-rebind-publish-wT=4/3') -and
    ($a14rG6 -ceq 'order-produce-consume=1/0') -and ($a14rG7 -ceq 'bad-needles') -and
    ($a14rG8 -ceq 'bad-needles') -and ($a14rG9 -ceq 'bad-names'))
  Write-Output ('      A-14r chain fixtures: clean=[' + $a14rG0 + '] no-publish=[' + $a14rG1 +
    '] early=[' + $a14rG2 + '] crossed=[' + $a14rG3 + '] absent=[' + $a14rG4 +
    '] swap=[' + $a14rG5 + '] rev=[' + $a14rG6 + '] sameNeedle=[' + $a14rG7 + '] blank=[' + $a14rG8 + '] noNames=[' + $a14rG9 + ']')

  # ---------- v4.4.0 (A-16): a handler group leaves the entry only by naming the file it goes to ----------
  $a16Gap = Get-HandlerGroupGap $a07Parsed $script:StHandlerGroups $script:StHandlerFiles $script:StSourceSpans
  # A-22: same split as A-11a/A-05 - "defined in the file it names" needs the span map, which only exists
  #    in aggregate mode. The count row below still prints in both modes, so a reader always sees what the
  #    tables hold even where the ownership claim is not the thing under test.
  if ($script:StSourceMode -ceq 'aggregate') {
    ST-Check 'lint (A-16): every declared handler group is defined exactly once, in the file it names, with nothing left behind in the entry and nothing ungrouped (26/21/21/8 = all 76)' (
      ($a16Gap -ceq ''))
    if ($a16Gap -ne '') { Write-Output ('      group gap: ' + $a16Gap) }
  } else {
    ST-Skip 'lint (A-16): every declared handler group is defined exactly once, in the file it names, with nothing left behind in the entry and nothing ungrouped (26/21/21/8 = all 76)' 'single-file source mode (no lib/ beside the entry) - the artifact has one file by construction, so file ownership is not a claim it can carry'
  }
  Write-Output ('      A-16 groups: declared=' + @(Get-HashKeys $script:StHandlerGroups).Count + ' named-files=' +
    (@(Get-HashKeys $script:StHandlerFiles | Where-Object { [string]$script:StHandlerFiles[$_] -ne '' }).Count) + ' handlers-seen=' +
    (@($a07Parsed.Root.FindAll({ param($n) ($n -is [System.Management.Automation.Language.FunctionDefinitionAst]) -and ($n.Name -clike 'Invoke-Handler-*') }, $true)).Count))

  # ---------- v4.4.0 (A-23): the exits inside moved bodies are named, and an artifact imports nothing ----------
  # criterion-5 . The thirteen exits that arrived with the case bodies are keyed by CASE; the eleven that never
  # lived in a case body are keyed by OWNER. Neither cohort can absorb a planting into the other, and
  # both readings come off the same AST the rest of this family uses, so a stitched artifact has to say
  # the same thing as the tree - which is the reason it is measured by name and not by file path.
  $a23Keys = @((Get-ExitOwnerList $a07Parsed) -split ';' | Where-Object { [string]$_ -ne '' })
  $a23CaseKeys = @($a23Keys | Where-Object { (-not ([string]$_).StartsWith('fn:')) -and ($_ -cne '<script>') })
  $a23OtherKeys = @($a23Keys | Where-Object { ([string]$_).StartsWith('fn:') -or ($_ -ceq '<script>') })
  $a23GapHandler = Get-InventoryDiscrepancy ((@($a23CaseKeys) -join ';')) $script:StHandlerExitAllowList
  $a23GapEntry = Get-InventoryDiscrepancy ((@($a23OtherKeys) -join ';')) $script:StEntryExitAllowList
  ST-Check 'lint (A-23): every exit inside a moved handler body is named by its case, the seven registered cases account for exactly thirteen, and a fourteenth is red' (
    ($a23GapHandler -ceq '') -and (@($a23CaseKeys).Count -eq 13) -and (@($script:StHandlerExitAllowList).Count -eq 7))
  if ($a23GapHandler -ne '') { Write-Output ('      handler exits: ' + $a23GapHandler) }
  ST-Check 'lint (A-23): the eleven exits that were never inside a moved body are named by owner too, so an exit planted outside a handler cannot be absorbed into the thirteen above' (
    ($a23GapEntry -ceq '') -and (@($a23OtherKeys).Count -eq 11) -and (@($a23Keys).Count -eq 24) -and (@($a23CaseKeys).Count -eq 13))
  if ($a23GapEntry -ne '') { Write-Output ('      entry exits: ' + $a23GapEntry) }
  # positive control for the predicate itself: a clean fixture counted by case, a planted handler named
  # as an owner nobody declared, a count that moved named, an entry that is gone named, and '-no-parse'
  # distinguishable from a measured zero.
  $a23FixTwoExit = 'function Invoke-Handler-demo($c) { if ($c) { exit 1 }' + "`n" + '  exit 0 }'
  $a23FixThreeExit = $a23FixTwoExit + "`n" + 'function Invoke-Handler-extra($c) { exit 7 }'
  $a23FixKeys = @((Get-ExitOwnerList (Parse-SourceForInventory $a23FixThreeExit)) -split ';' | Where-Object { [string]$_ -ne '' })
  $a23FixGap = Get-InventoryDiscrepancy ((@((Get-ExitOwnerList (Parse-SourceForInventory $a23FixTwoExit)) -split ';' | Where-Object { [string]$_ -ne '' })) -join ';') @('demo=1')
  $a23FixPlantGap = Get-InventoryDiscrepancy ((@($a23FixKeys) -join ';')) @('demo=2')
  $a23FixMissing = Get-InventoryDiscrepancy 'demo;demo' @('demo=2', 'gone=1')
  ST-Check 'unit (A-23): the exit-owner predicate counts a planted fixture by case, names a planted extra handler as an undeclared owner, names a count that moved and an entry that is gone, and answers -no-parse rather than empty' (
    ((@($a23FixKeys) -join ';') -ceq 'demo;demo;extra') -and ($a23FixPlantGap.Contains('observed:extra-declared=0')) -and
    ($a23FixGap.Contains('demo:got2-want1')) -and ($a23FixMissing.Contains('gone:got0-want1')) -and
    ((Get-ExitOwnerList $null) -ceq '-no-parse'))
  Write-Output ('      A-23 exit census: handler=' + @($a23CaseKeys).Count + ' entry=' + @($a23OtherKeys).Count +
    ' exit-statements-total=' + @($a23Keys).Count + ' aggregate-lines=' + @($script:StSourceLines).Count +
    ' parse-errors=' + [int]$a07Parsed.ErrorCount +
    ' registered-cases=' + @($script:StHandlerExitAllowList).Count + ' registered-entry-owners=' + @($script:StEntryExitAllowList).Count +
    ' fixture=' + (@($a23FixKeys) -join ';'))

  # criterion-9 . Only an artifact can be asked this: in this tree the markers and the imports ARE the loader, so
  # the claim is skipped out loud (and counted). When it does run, a breach count of zero only means
  # something if the scan really looked at a big source and had the data spans it protects on record -
  # otherwise an empty scan would report a clean install.
  if ($script:StSourceMode -ceq 'aggregate') {
    ST-Skip 'lint (A-23): the stitched artifact leaves no stitch marker attached to code and no dot-source of a lib path still executing' 'source-tree mode - this tree legitimately carries both the markers and the imports; the claim belongs to the artifact (see the single-file run)'
  } else {
    $a23Res = Get-StitchResidue @($script:StSourceLines)
    ST-Check 'lint (A-23): the stitched artifact leaves no stitch marker attached to code and no dot-source of a lib path still executing' (
      (@($script:StSourceLines).Count -gt 1000) -and ([int]$a23Res.ParseErrors -eq 0) -and ([int]$a23Res.DataSpans -gt 0) -and
      ($a23Res.Count -eq 0))
    Write-Output ('      A-23 artifact residue: lines=' + @($script:StSourceLines).Count + ' breaches=' + [int]$a23Res.Count +
      ' protected-data-spans=' + [int]$a23Res.DataSpans + ' parse-errors=' + [int]$a23Res.ParseErrors +
      ' breach-list=[' + ([string]$a23Res.Breaches) + ']')
  }
  # and the predicate has to answer on planted input in BOTH modes, or the skip above hides a ruler with no
  # marks: a dot-source of a lib path and a call-operator import are each named, a marker written as a
  # bare line of code is named, and the same marker inside a quoted string or a trailing comment is not.
  $a23Ndl = Get-CharCodeWord @(0x3C, 0x3C, 0x20, 0x73, 0x74, 0x69, 0x74, 0x63, 0x68, 0x3A, 0x20)
  $a23Fx1 = '. (Join-Path $PSScriptRoot ' + "'" + 'lib/x.ps1' + "'" + ') # ' + $a23Ndl + 'lib/x.ps1'
  $a23Fx2 = '& (Join-Path $PSScriptRoot ' + "'" + 'lib/q.ps1' + "'" + ')'
  $a23Fx3 = '# a sentence about ' + $a23Ndl + 'lib/z.ps1'
  $a23Fx4 = '$q = ' + "'" + $a23Ndl + "inside a string'"
  $a23FixLines = @($a23Fx1, $a23Fx2, $a23Fx3, $a23Fx4, 'Write-Output 1')
  $a23FixRes = Get-StitchResidue $a23FixLines
  $a23FixCleanRes = Get-StitchResidue @('Write-Output 1', ('$other = ' + "'" + 'nothing here' + "'"))
  $a23BareRes = Get-StitchResidue @('$v = 1', ('x ' + $a23Ndl + 'lib/b.ps1'))
  ST-Check 'unit (A-23): the residue predicate names a dot-source and a call-operator import of a lib path, names a marker written as code, leaves the same marker alone inside a quoted string and inside a comment, and reports zero on a clean fixture' (
    (([string]$a23FixRes.Breaches).Contains('dot-import-at-1')) -and (([string]$a23FixRes.Breaches).Contains('dot-import-at-2')) -and
    ($a23FixRes.Count -eq 2) -and (-not ([string]$a23FixRes.Breaches).Contains('marker-at-1')) -and
    (-not ([string]$a23FixRes.Breaches).Contains('marker-at-3')) -and (-not ([string]$a23FixRes.Breaches).Contains('marker-at-4')) -and
    ($a23FixCleanRes.Count -eq 0) -and ([int]$a23FixRes.DataSpans -ge 3) -and
    (([string]$a23BareRes.Breaches).Contains('marker-at-2')) -and (@($a23Ndl).Count -eq 1) -and ($a23Ndl.Length -eq 11))
  Write-Output ('      A-23 residue fixture: breaches=[' + [string]$a23FixRes.Breaches + '] data-spans=' + [int]$a23FixRes.DataSpans +
    ' bare-marker-fixture=[' + [string]$a23BareRes.Breaches + ']')

  # ---------- v4.4.0 (A-23): the declared version may not appear in a lib file's code (criterion-10) ----------
  # The version is read out of the entry's own authoritative slot, never hardcoded: a card that bumps the
  # version has to see this scan follow it, and a card that writes the number into the scan would be
  # pinning yesterday's value. Comments are the only thing excluded, and only the parser's opinion of what
  # a comment is counts - see the ruling note on Get-CodeTextWithoutComments.
  $a23Version = 'missing'
  if ("$src" -match '(?m)^# version: ([0-9.]+)') { $a23Version = [string]$Matches[1] }
  $a23LibFiles = @($script:StSourceFiles | Where-Object { ([string]$_) -cne 'desktop.ps1' })
  if ($script:StSourceMode -ceq 'aggregate') {
    $a23Scanned = 0
    $a23Unreadable = 0
    $a23Unparsed = 0
    $a23CodeHits = @()
    $a23CommentTokens = 0
    $a23Bytes = 0
    $a23CodeTokens = 0
    $a23Literals = 0
    $a23Searched = 0
    foreach ($f in @($a23LibFiles)) {
      $fp = Join-Path $script:ToolRootPath ([string]$f)
      if (-not (Test-Path -LiteralPath $fp -PathType Leaf)) { $a23Unreadable = $a23Unreadable + 1; continue }
      $nc = Get-CodeTextWithoutComments $fp
      $a23Scanned = $a23Scanned + 1
      $a23Bytes = $a23Bytes + [int]$nc.Bytes
      $a23CommentTokens = $a23CommentTokens + [int]$nc.CommentTokens
      $a23CodeTokens = $a23CodeTokens + [int]$nc.CodeTokens
      $a23Literals = $a23Literals + [int]$nc.LiteralSamples
      $a23Searched = $a23Searched + [int]$nc.SearchedChars
      if ([int]$nc.ParseErrors -gt 0) { $a23Unparsed = $a23Unparsed + 1; continue }
      if (($a23Version -cne 'missing') -and (([string]$nc.Text).Contains($a23Version))) { $a23CodeHits += ([string]$f) }
    }
    # the face of the scan is part of the claim, not a footnote: a zero hit only counts when the size of what
    # was searched and the number of literals in range are both non-zero and printed next to the zero.
    ST-Check 'lint (A-23): the version this entry declares appears in no lib file code - every declared lib file was read and parsed, comments alone are excluded, and an unreadable or unparseable file is a failure not a skip' (
      ($a23Version -cne 'missing') -and (@($a23LibFiles).Count -ge 7) -and ($a23Scanned -eq @($a23LibFiles).Count) -and
      ($a23Unreadable -eq 0) -and ($a23Unparsed -eq 0) -and ($a23CommentTokens -gt 0) -and ($a23Bytes -gt 100000) -and
      ($a23CodeTokens -gt 10000) -and ($a23Literals -gt 1000) -and ($a23Searched -gt 100000) -and
      (@($a23CodeHits).Count -eq 0))
    if (@($a23CodeHits).Count -gt 0) { Write-Output ('      version literal in code: ' + ((@($a23CodeHits) | Sort-Object -Unique) -join ', ')) }
    Write-Output ('      A-23 version scan: version=' + $a23Version + ' files=' + $a23Scanned + '/' + @($a23LibFiles).Count +
      ' bytes=' + $a23Bytes + ' comment-tokens=' + $a23CommentTokens + ' unreadable=' + $a23Unreadable + ' unparsed=' + $a23Unparsed +
      ' code-tokens=' + $a23CodeTokens + ' literal-samples=' + $a23Literals + ' searched-chars=' + $a23Searched +
      ' code-hits=' + @($a23CodeHits).Count)
  } else {
    ST-Skip 'lint (A-23): the version this entry declares appears in no lib file code - every declared lib file was read and parsed, comments alone are excluded, and an unreadable or unparseable file is a failure not a skip' 'single-file source mode (no lib/ beside the entry) - there is no lib set to scan here; the scan and its lower bound belong to the source tree'
  }
  # the exclusion has to be the parser's comment and nothing else: the same literal in a trailing comment
  # is invisible to the scan, in a single-quoted string and in a here-string it is still there, and a file
  # that does not parse is reported rather than passed over. That is the baseline-green / mutant-red pair
  # the ruling asks for, measured here so the gate above is never called a permanent green.
  $a23Tmp = Join-Path $env:TEMP ('a23-version-scan-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))
  New-Item -ItemType Directory -Path $a23Tmp -Force | Out-Null
  try {
    $a23VerTok = '9.9.9'
    Set-Content -LiteralPath (Join-Path $a23Tmp 'in-comment.ps1') -Value ('$x = 1 # v' + $a23VerTok + ' landing note' + "`n" + '$y = 2') -Encoding UTF8
    Set-Content -LiteralPath (Join-Path $a23Tmp 'in-string.ps1') -Value ('$x = ' + "'" + 'v' + $a23VerTok + "'" + "`n" + '$y = 2') -Encoding UTF8
    Set-Content -LiteralPath (Join-Path $a23Tmp 'in-herestring.ps1') -Value ('$x = @(' + '"' + "`n" + 'v' + $a23VerTok + "`n" + '"' + '@' + "`n" + '$y = 2') -Encoding UTF8
    Set-Content -LiteralPath (Join-Path $a23Tmp 'broken.ps1') -Value '$x = ( unclosed' -Encoding UTF8
    $a23InComment = Get-CodeTextWithoutComments (Join-Path $a23Tmp 'in-comment.ps1')
    $a23InString = Get-CodeTextWithoutComments (Join-Path $a23Tmp 'in-string.ps1')
    $a23InHere = Get-CodeTextWithoutComments (Join-Path $a23Tmp 'in-herestring.ps1')
    $a23Broken = Get-CodeTextWithoutComments (Join-Path $a23Tmp 'broken.ps1')
    ST-Check 'unit (A-23): the comment blanker removes the version from a comment but leaves it in a string and in a here-string, keeps the byte length it was given, reports a parse error instead of an empty scan, and states the size of the face it searched' (
        (-not (([string]$a23InComment.Text).Contains($a23VerTok))) -and ([int]$a23InComment.CommentTokens -eq 1) -and
        ([int]$a23InComment.BlankedChars -gt 0) -and ([int]$a23InComment.Bytes -eq [System.Text.Encoding]::UTF8.GetByteCount(([string]$a23InComment.Text))) -and
        ([int]$a23InComment.CodeTokens -ge 4) -and ([int]$a23InComment.SearchedChars -gt 0) -and
        (([string]$a23InString.Text).Contains($a23VerTok)) -and (([string]$a23InHere.Text).Contains($a23VerTok)) -and
        ([int]$a23InString.LiteralSamples -ge 1) -and ([int]$a23InHere.LiteralSamples -ge 1) -and
        (([string]$a23Broken.Text).Contains('unclosed')) -and ([int]$a23Broken.ParseErrors -ge 1))
    Write-Output ('      A-23 blanker fixture: comment-tokens=' + [int]$a23InComment.CommentTokens + ' blanked=' + [int]$a23InComment.BlankedChars +
      ' string-kept=' + ([string]$a23InString.Text).Contains($a23VerTok) + ' here-kept=' + ([string]$a23InHere.Text).Contains($a23VerTok) +
      ' broken-parse-errors=' + [int]$a23Broken.ParseErrors + ' code-tokens=' + [int]$a23InComment.CodeTokens +
      ' literal-samples=' + [int]$a23InString.LiteralSamples)
  } finally {
    Remove-Item -LiteralPath $a23Tmp -Recurse -Force
  }
}



# lib/selftest-repo-contract.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1 by A-14b (A-beta).
# Bodies are byte-identical to what the section carried; this file exists so that a family of
# checks can be read, moved and counted on its own. The only channel to the orchestrator is the
# explicit context object: shared state arrives through $Ctx and nothing else, because the
# dynamic-scope chain that used to feed these lines is exactly the implicit link A-08/A-09/A-11
# proved can break silently on a move.
# Family: the repository contract - the version tokens in their four carriers, the tracked-file
function Invoke-SelftestFamily-RepoContract($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $self = [string]$Ctx['self']
  $src = [string]$Ctx['src']
#   inventory and the offline-check total this version declares. These are the checks that only
#   mean something inside a checkout, and they are the reason $script:ToolRootPath exists.
  # ---------- lint: version number sync across the 4 locations ----------
  # Spec section 6 wants a machine guard on the version sync list. ASCII-only
  # implementation: the two CJK-named docs are located by "the .md files that
  # are not README.md" (exact count asserted first), and each is checked by its
  # FIRST vX.Y.Z token within the first 12 lines (overview header line 3,
  # iteration log latest-entry heading line 7 - keep those shapes).
  $vMain = 'missing'
  if ($src -match '(?m)^# version: ([0-9.]+)') { $vMain = $Matches[1] }
  $vUsage = 'missing'
  if ($src -match 'desktop\.ps1 v([0-9.]+) - Windows') { $vUsage = $Matches[1] }
  ST-Check 'version: desktop.ps1 header == Usage banner' (($vMain -ne 'missing') -and ($vUsage -eq $vMain))
  # v2.5.0: the block below pins the REPOSITORY-level contract (version carriers +
  # tracked inventory). From an installed copy - the skill ships desktop.ps1 on its
  # own - there is no repository to check, so these checks report SKIP with a reason
  # instead of FAIL. Inside a checkout (even with files deleted) they run as before.
  $isRepoRoot = $false
  try {
    $tl = @(& git -C $script:ToolRootPath rev-parse --show-toplevel 2>$null)
    if (@($tl).Count -ge 1) {
      $tlNorm = ("$($tl[0])" -replace '\\', '/').TrimEnd('/').ToLowerInvariant()
      $prNorm = ("$script:ToolRootPath" -replace '\\', '/').TrimEnd('/').ToLowerInvariant()
      if ($tlNorm -eq $prNorm) { $isRepoRoot = $true }
    }
  } catch { $isRepoRoot = $false }
  # the authority-set helper, pinned BEFORE the guard that uses it: a tracked name must survive,
  # an untracked marker doc must be dropped AND named, and "no git" must fall back to the disk
  # list with the mode labelled - not read as "nothing is tracked", which would have turned this
  # guard red on every machine where git had a bad moment.
  # v4.1.3 (external review A, the third silent-drop family): these three are PURE unit checks
  # on synthetic inputs - they never touch git - but they sat INSIDE the repository-checkout
  # guard below, so a box where git is unresolvable lost three checks silently (measured:
  # context C and D both drop exactly these three). They moved out, so the guard now covers
  # only the checks that genuinely need a checkout.
  $adKeep = Split-AuthorityDocNames @('READMEX.md', 'review-report.md') @('READMEX.md') $true
  $adNoGit = Split-AuthorityDocNames @('READMEX.md', 'review-report.md') @() $false
  $adAll = Split-AuthorityDocNames @('READMEX.md') @('READMEX.md') $true
  ST-Check 'unit: authority docs - an untracked marker doc is dropped and reported, never silently' (
    (@($adKeep.Kept) -contains 'READMEX.md') -and (-not (@($adKeep.Kept) -contains 'review-report.md')) -and
    (@($adKeep.Dropped) -contains 'review-report.md') -and ($adKeep.Mode -eq 'tracked'))
  ST-Check 'unit: authority docs - no git falls back to the disk list and says which mode it used' (
    ($adNoGit.Mode -eq 'disk-fallback') -and (@($adNoGit.Kept).Count -eq 2) -and (@($adNoGit.Dropped).Count -eq 0))
  ST-Check 'unit: authority docs - a fully tracked authority set is kept whole (the normal case, so the two above cannot pass by dropping everything)' (
    (@($adAll.Kept).Count -eq 1) -and (@($adAll.Dropped).Count -eq 0))
  $skipNoRepo = 'not a repository checkout - repository-level check does not apply (installed copy)'
  if ($isRepoRoot) {
  $readmePath = Join-Path $script:ToolRootPath 'README.md'
  $vReadme = 'missing'
  if (Test-Path $readmePath) {
    $rl1 = Get-Content -LiteralPath $readmePath -TotalCount 1
    if ($rl1 -match 'v([0-9.]+)') { $vReadme = $Matches[1] }
  }
  ST-Check 'version: README H1 == desktop.ps1 header' ($vReadme -eq $vMain)
  # Authority docs are identified by content (their first line mentions
  # desktop.ps1), not by counting .md files - the repo root now also carries
  # task-order docs (e.g. the v1.5.0 work order) that must not participate in
  # the version check. -Encoding UTF8 is mandatory: read as ANSI/GBK, a
  # fullwidth bracket's UTF-8 bytes swallow the following ASCII 'd' and the
  # marker regex silently misses.
  $mdDisk = @(Get-ChildItem -LiteralPath $script:ToolRootPath -Filter '*.md' | ForEach-Object { $_.Name } | Where-Object { $_ -ne 'README.md' })
  # -z, because this repo's tracked names are CJK and the quoted form is not comparable.
  $trackedMd = @(); $haveTracked = $false
  try {
    $lsRaw = & git -C $script:ToolRootPath ls-files -z '*.md' 2>$null
    if ($LASTEXITCODE -eq 0) {
      $haveTracked = $true
      $trackedMd = @(($lsRaw -join ([string][char]0)) -split [char]0 | ForEach-Object { "$_".Trim() } | Where-Object { "$_" -ne '' })
    }
  } catch { $haveTracked = $false }
  $authSet = Split-AuthorityDocNames $mdDisk $trackedMd $haveTracked
  if (@($authSet.Dropped).Count -gt 0) {
    Write-Output ('      authority docs: ignored untracked (not part of the authority surface): ' + (@($authSet.Dropped) -join ' '))
  }
  $mds = @(Get-ChildItem -LiteralPath $script:ToolRootPath -Filter '*.md' | Where-Object {
    (@($authSet.Kept) -contains $_.Name) -and ((Get-Content -LiteralPath $_.FullName -TotalCount 1 -Encoding UTF8) -match 'desktop\.ps1')
  })
  ST-Check 'version: exactly two content-marked authority docs (first line mentions desktop.ps1)' ($mds.Count -eq 2)
  # Positive named guard (v1.5.0 residual): a content-only enumeration still
  # passes if a doc is RENAMED to another .md that keeps the marker on line 1.
  # Pin the two expected names; code points keep this file pure ASCII.
  $ovName = "$([char]0x9879)$([char]0x76EE)$([char]0x603B)$([char]0x89C8).md"
  $ilogName = "$([char]0x8FED)$([char]0x4EE3)$([char]0x65E5)$([char]0x5FD7).md"
  ST-Check 'version: named authority docs exist (overview + iteration log)' (
    (Test-Path -LiteralPath (Join-Path $script:ToolRootPath $ovName)) -and (Test-Path -LiteralPath (Join-Path $script:ToolRootPath $ilogName)))
  $mdOk = ($mds.Count -eq 2)
  foreach ($m in $mds) {
    $head = (Get-Content -LiteralPath $m.FullName -TotalCount 12 -Encoding UTF8) -join "`n"
    $v = 'missing'
    if ($head -match 'v([0-9.]+)') { $v = $Matches[1] }
    if ($v -ne $vMain) { $mdOk = $false }
  }
  ST-Check 'version: overview header + iteration log latest entry == desktop.ps1 header' $mdOk
  } else {
    ST-Skip 'version: README H1 == desktop.ps1 header' $skipNoRepo
    ST-Skip 'version: exactly two content-marked authority docs (first line mentions desktop.ps1)' $skipNoRepo
    ST-Skip 'version: named authority docs exist (overview + iteration log)' $skipNoRepo
    ST-Skip 'version: overview header + iteration log latest entry == desktop.ps1 header' $skipNoRepo
  }

  # ---------- v4.5.5 (TB-1): the version definition, the entry header and the runtime source_version are one source ----------
  # The constant had drifted to 4.5.3 against a 4.5.5 header while the four checks above compared
  # only the prose carriers - nothing pinned the definition the caller runtime actually writes into
  # its records. Three checks close it: the live single-source lint, the record-level source_version
  # flow, and the three planted counterexamples (missing / wrong value / frozen write).
  $tb1HeaderCount = @([regex]::Matches([string]$src, '(?m)^# version: [0-9.]+')).Count
  $tb1DefPattern = '(?m)^\s*\' + [char]0x24 + 'script:ToolVersion\s*=\s*' + [char]39 + '([^' + [char]39 + ']+)' + [char]39
  $tb1Defs = @([regex]::Matches([string]$src, $tb1DefPattern))
  $tb1DefValue = 'missing'
  if ($tb1Defs.Count -ge 1) { $tb1DefValue = [string]$tb1Defs[0].Groups[1].Value }
  ST-Check 'lint (TB-1): the version definition is non-empty, assigned exactly once, the header declares its version exactly once, and definition == header == Usage banner == the version the orchestrator published' (
    ($tb1Defs.Count -eq 1) -and ($tb1DefValue -cmatch '^[0-9]+\.[0-9]+\.[0-9]+$') -and
    ($tb1HeaderCount -eq 1) -and ($tb1DefValue -ceq $vMain) -and ($vMain -ceq $vUsage) -and
    ($tb1DefValue -ceq [string]$Ctx['ToolVersion']))
  Write-Output ('      TB-1 sources: definition=' + $tb1DefValue + ' header=' + $vMain + ' usage=' + $vUsage + ' ctx=' + [string]$Ctx['ToolVersion'] + ' headerCount=' + $tb1HeaderCount)

  # The record-level half: the caller runtime must write the version it resolved - an explicit
  # context override wins, the no-context path falls back to the entry's loaded definition, and the
  # record carries that value in source_version. Fixture machinery mirrors the gate-meta caller
  # fixtures: a unique temp RootBase inside the system temp root, everything released in finally.
  $tb1Lease = $null
  $tb1Root = Join-Path $env:TEMP ('dtx-tb1-source-version-' + [guid]::NewGuid().ToString('N'))
  $tb1OwnRoot = $false
  $tb1OverrideWritten = 'not-run'
  $tb1FallbackWritten = 'not-run'
  try {
    $tb1TempExpect = [IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd([char]92) + [IO.Path]::DirectorySeparatorChar
    if (-not ([IO.Path]::GetFullPath($tb1Root)).StartsWith($tb1TempExpect, [StringComparison]::OrdinalIgnoreCase)) { throw 'refusing a probe path outside the system temp root' }
    New-Item -Path $tb1Root -ItemType Directory -ErrorAction Stop | Out-Null
    $tb1OwnRoot = $true
    $tb1Parent = [pscustomobject]@{ ParentPid = 0; ParentName = 'unknown'; ParentStartUtc = ''; ParentStartFileTime = ''; Known = $false }
    $tb1OverrideCtx = [ordered]@{
      RootBase = $tb1Root
      WindowsSessionId = '771'
      DesktopName = 'Default'
      CallerLabel = 'TB1-override'
      CallerSessionId = 'source-version'
      IdentitySource = 'selftest-explicit'
      ParentInfo = $tb1Parent
      SourcePath = 'D:\synthetic\tb1.ps1'
      ToolVersion = '9.9.9-tb1-fixture'
    }
    $tb1Lease = Start-DtxCallTracking 'info' @('tb1-override-probe') $tb1OverrideCtx
    if ($null -eq $tb1Lease) { throw 'TB-1 override fixture did not register' }
    $tb1OverrideWritten = [string]$tb1Lease.Record.source_version
    Complete-DtxCallTracking $tb1Lease 'completed' 0 ''
    $tb1Lease = $null
    $tb1FallbackCtx = [ordered]@{
      RootBase = $tb1Root
      WindowsSessionId = '772'
      DesktopName = 'Default'
      CallerLabel = 'TB1-fallback'
      CallerSessionId = 'source-version'
      IdentitySource = 'selftest-explicit'
      ParentInfo = $tb1Parent
      SourcePath = 'D:\synthetic\tb1.ps1'
    }
    $tb1Lease = Start-DtxCallTracking 'info' @('tb1-fallback-probe') $tb1FallbackCtx
    if ($null -eq $tb1Lease) { throw 'TB-1 fallback fixture did not register' }
    $tb1FallbackWritten = [string]$tb1Lease.Record.source_version
    Complete-DtxCallTracking $tb1Lease 'completed' 0 ''
    $tb1Lease = $null
    ST-Check 'unit (TB-1): the caller record writes the resolved version - an explicit fixture override wins and the no-context path carries the version the orchestrator published (the definition, not a frozen literal)' (
      ($tb1OverrideWritten -ceq '9.9.9-tb1-fixture') -and
      ($tb1FallbackWritten -ceq [string]$Ctx['ToolVersion']) -and
      ($tb1FallbackWritten -ceq $tb1DefValue))
    Write-Output ('      TB-1 records: override=' + $tb1OverrideWritten + ' fallback=' + $tb1FallbackWritten)
  } finally {
    if ($null -ne $tb1Lease) { Complete-DtxCallTracking $tb1Lease 'completed' 0 ''; $tb1Lease = $null }
    if ($tb1OwnRoot) { Remove-Item -LiteralPath $tb1Root -Recurse -Force -ErrorAction SilentlyContinue }
  }

  # The teeth: the same three questions the live lint asks, run against planted copies - a source
  # without the definition, a definition on the wrong value, and a writer that freezes the version
  # as a literal so a later definition change would not reach the records. A matching control
  # passes, so the detector is a comparison and not an always-red hammer.
  $tb1PlantDetector = {
    param([string]$PlantSource, [string]$PlantHeader, [string]$PlantWritten)
    $pd = @([regex]::Matches([string]$PlantSource, ('(?m)^\s*\' + [char]0x24 + 'script:ToolVersion\s*=\s*' + [char]39 + '([^' + [char]39 + ']+)' + [char]39)))
    if ($pd.Count -eq 0) { return 'definition-missing' }
    if ($pd.Count -gt 1) { return 'definition-not-once' }
    $pdValue = [string]$pd[0].Groups[1].Value
    if ($pdValue -notmatch '^[0-9]+\.[0-9]+\.[0-9]+$') { return 'definition-malformed' }
    if ($pdValue -cne [string]$PlantHeader) { return 'definition-header-mismatch' }
    if (([string]$PlantWritten -ne '') -and ([string]$PlantWritten -cne $pdValue)) { return 'frozen-write-rejected' }
    return ''
  }
  $tb1Dollar = [char]0x24
  $tb1Quote = [char]39
  $tb1PlantMissing = 'an entry body whose definition line was removed'
  $tb1PlantWrong = $tb1Dollar + 'script:ToolVersion = ' + $tb1Quote + '0.0.0' + $tb1Quote
  $tb1PlantFrozenDef = $tb1Dollar + 'script:ToolVersion = ' + $tb1Quote + '5.5.5' + $tb1Quote
  $tb1LiveSource = $tb1Dollar + 'script:ToolVersion = ' + $tb1Quote + [string]$Ctx['ToolVersion'] + $tb1Quote
  $tb1PlantFlags = @(
    (& $tb1PlantDetector $tb1PlantMissing ([string]$Ctx['ToolVersion']) ''),
    (& $tb1PlantDetector $tb1PlantWrong ([string]$Ctx['ToolVersion']) '0.0.0'),
    (& $tb1PlantDetector $tb1PlantFrozenDef '5.5.5' '0.0.0'),
    (& $tb1PlantDetector $tb1LiveSource ([string]$Ctx['ToolVersion']) ([string]$Ctx['ToolVersion']))
  )
  ST-Check 'unit (TB-1): the planted missing-definition, wrong-value and frozen-literal copies are each rejected by the detector comparison (the live lint asks the same three questions inline, it does not call this detector), and a matching control passes' (
    ($tb1PlantFlags[0] -ceq 'definition-missing') -and
    ($tb1PlantFlags[1] -ceq 'definition-header-mismatch') -and
    ($tb1PlantFlags[2] -ceq 'frozen-write-rejected') -and
    ($tb1PlantFlags[3] -ceq ''))
  Write-Output ('      TB-1 plants: ' + ($tb1PlantFlags -join ' / '))

  # ---------- lint: the tracked-file count written in the overview IS the real one ----------
  # 2026-10-01 round-3 finding: this number drifted three times in one day (9, then 17,
  # then written as 15 while the tree held 16) and nothing noticed, because it was prose
  # no gate measured - a cold-starting agent reads the inventory line and inherits the
  # wrong count. Pinned: the overview must carry tracked=<N> and N must equal git ls-files.
  if ($isRepoRoot) {
  $tfDoc = -1
  foreach ($m in $mds) {
    foreach ($l in @(Get-Content -LiteralPath $m.FullName -Encoding UTF8)) {
      if ("$l" -match 'tracked=(\d+)') { $tfDoc = [int]$Matches[1]; break }
    }
  }
  $tfReal = 0
  try { $tfReal = @((& git -C $script:ToolRootPath ls-files 2>$null) | Where-Object { "$_" -ne '' }).Count } catch { $tfReal = 0 }
  ST-Check 'lint: the overview states the tracked-file count and it equals git ls-files (no stale inventory)' (
    ($tfDoc -gt 0) -and ($tfReal -gt 0) -and ($tfDoc -eq $tfReal))
  Write-Output ("      tracked files: doc=$tfDoc git=$tfReal")
  # ---------- v4.1.3: tracked in the INDEX is not the same as present on the DISK ----------
  # Found the hard way, during this very round: thirteen tracked task-order documents were
  # deleted from this working tree while the gate was running, and nothing noticed. The lint
  # above reads `git ls-files`, which answers from the INDEX - an unstaged deletion is
  # invisible to it. That is the same disease this version is about: "cannot see it" reported
  # as "nothing wrong". The two views must now agree, and every missing name is printed.
  $tfOnDisk = @()
  try {
    $tfRaw = & git -C $script:ToolRootPath ls-files -z 2>$null
    if ($LASTEXITCODE -eq 0) {
      $tfOnDisk = @((($tfRaw -join ([string][char]0)) -split [char]0 | ForEach-Object { "$_".Trim() } | Where-Object { "$_" -ne '' }))
    }
  } catch { $tfOnDisk = @() }
  $tfMissing = @($tfOnDisk | Where-Object { -not (Test-Path -LiteralPath (Join-Path $script:ToolRootPath "$_")) })
  # The predicate gets a planted absent name, because a check that passes by measuring an
  # empty set is exactly the failure mode being fixed here.
  $tfPlantCaught = 0
  foreach ($tfName in @('DTX-no-such-tracked-file-ZQX.md')) {
    if (-not (Test-Path -LiteralPath (Join-Path $script:ToolRootPath "$tfName"))) { $tfPlantCaught++ }
  }
  ST-Check 'lint: every name tracked in the index exists on disk (an unstaged deletion cannot read as "nothing wrong")' (
    (@($tfOnDisk).Count -gt 0) -and (@($tfMissing).Count -eq 0))
  ST-Check 'lint: the tracked-on-disk predicate flags a planted absent name (the check above cannot pass by seeing nothing)' (
    $tfPlantCaught -eq 1)
  if (@($tfMissing).Count -gt 0) { Write-Output ("      tracked but absent on disk (" + @($tfMissing).Count + '): ' + ((@($tfMissing) | Sort-Object) -join ', ')) }
  Write-Output ('      tracked inventory: index=' + @($tfOnDisk).Count + ' present=' + (@($tfOnDisk).Count - @($tfMissing).Count))
  } else {
    ST-Skip 'lint: the overview states the tracked-file count and it equals git ls-files (no stale inventory)' $skipNoRepo
    ST-Skip 'lint: every name tracked in the index exists on disk (an unstaged deletion cannot read as "nothing wrong")' $skipNoRepo
    ST-Skip 'lint: the tracked-on-disk predicate flags a planted absent name (the check above cannot pass by seeing nothing)' $skipNoRepo
  }

  # ---------- lint: the overview header's offline-check total IS the declaration in this file ----------
  # F-01 (supervisor, 2026-10-05). The overview has carried "N checks" as prose since v3.0.0 and
  # nothing compared it: it sat at 777 across two batches while the file declared 785, with the
  # whole suite green the entire time. Same disease the tracked-file count had before it was
  # pinned - a number a human maintains is a number that drifts. Built from code points so this
  # file stays pure ASCII, and the MATCH IS COUNTED: a scan that found nothing fails, it may not
  # pass by reading an empty set (pit: a zero-hit assertion needs a planted sample that hits 1).
  $ocTotalSeen = -1
  $ocOvName = "$([char]0x9879)$([char]0x76EE)$([char]0x603B)$([char]0x89C8).md"
  $ocOvPath = Join-Path $script:ToolRootPath $ocOvName
  $ocPat = '^> .*' + [string]::Join('', @([char]0x79BB, [char]0x7EBF, [char]0x5224, [char]0x636E)) + ' \*\*([0-9]+) ' + [string]([char]0x6761)
  $ocHave = Test-Path -LiteralPath $ocOvPath
  if ($ocHave) {
    foreach ($ocL in @(Get-Content -LiteralPath $ocOvPath -Encoding UTF8)) {
      if ("$ocL" -match $ocPat) { $ocTotalSeen = [int]$Matches[1]; break }
    }
  }
  # The overview is an INTERNAL document - the published tree does not carry it. A check that
  # reads it must SKIP there (naming why), not sit structurally red: measured when the v3.1.0
  # sync first ran the public tree, this case failed with doc=-1 because no such file exists.
  # In a tree that DOES have the overview, "present but unmatched" still fails (doc=-1).
  if ($ocHave) {
    ST-Check 'lint (F-01): the overview header states the offline check total and it equals DeclaredCheckTotal (no human-maintained number survives)' (
      ($ocTotalSeen -gt 0) -and ($ocTotalSeen -eq [int]$script:DeclaredCheckTotal))
  } else {
    ST-Skip 'lint (F-01): the overview header states the offline check total and it equals DeclaredCheckTotal (no human-maintained number survives)' 'no internal overview in this tree - the published tree does not carry it'
  }
  Write-Output ("      overview check total: doc=$ocTotalSeen declared=$($script:DeclaredCheckTotal)")

}

# lib/selftest-clipboard-input.ps1 - family clipboard-input of the selftest section, lifted out of
# lib/selftest.ps1 by A-14d (A-beta). Bodies are byte-identical to what the section carried.
# Why this family could go first: A-14b measured every family's unmet state reads, and this one
# needed exactly one thing - $codeLines - which A-14c hoisted into the orchestrator and published
# through $Ctx. So this is the first lift that moves state through the declared channel instead of
# through the call chain, and nothing outside it reads anything it binds (measured: 0 exports).
# Three of its four banners were already contiguous; the parked-pick block moves to join them, which
# is a reordering this card reports rather than hides.
function Invoke-SelftestFamily-ClipboardInput($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $codeLines = $Ctx['codeLines']

  # ---------- unit: v1.5.2 WP-4 clipboard kind branch (audit R-05) ----------
  # The 'both' state cannot be produced faithfully from a script (see the note on
  # Save-ClipboardState), so the branch itself is pinned here - text and FileDrop
  # must no longer be exclusive buckets.
  ST-Check 'unit: clipboard kind - text+FileDrop together is its own kind' ((Resolve-ClipboardKind $true $true) -ceq 'both')
  ST-Check 'unit: clipboard kind - text alone' ((Resolve-ClipboardKind $true $false) -ceq 'text')
  ST-Check 'unit: clipboard kind - FileDrop alone' ((Resolve-ClipboardKind $false $true) -ceq 'files')
  ST-Check 'unit: clipboard kind - neither' ((Resolve-ClipboardKind $false $false) -ceq 'other')

  # ---------- unit: v1.5.2 WP-5 confusable fold is a marked SECOND pass --------
  # audit R-10: OCR reads 'QXHELLO123' as 'QXHELL01231' and 'DTX-AuditInput' as
  # 'DTX-Auditlnput', so a --verify that really succeeded used to report FAILURE.
  # The fold may only ever be a second pass, and a folded hit must never look like
  # an exact one (task order section 6: a broadened match presented as confirmed
  # is the false green the guards exist to prevent).
  $foldLines = New-Object System.Collections.ArrayList
  [void]$foldLines.Add([pscustomobject]@{ Text = 'QXHELL01231'; X = 10; Y = 10; W = 80; H = 14 })
  $fx1 = Find-OcrHits $foldLines 'QXHELLO123'
  ST-Check 'unit: confusable fold rescans only after the exact pass misses' (@($fx1).Count -eq 1)
  ST-Check 'unit: a folded hit is marked Folded' ($fx1[0].PSObject.Properties['Folded'] -and $fx1[0].Folded -eq $true)
  $foldMark = Get-OcrFoldMarker $fx1
  ST-Check 'unit: folded hit echo says confusable-fold' ($foldMark -like '*confusable-fold*')
  $exactLines = New-Object System.Collections.ArrayList
  [void]$exactLines.Add([pscustomobject]@{ Text = 'QXHELLO123'; X = 10; Y = 10; W = 80; H = 14 })
  $fx2 = Find-OcrHits $exactLines 'QXHELLO123'
  ST-Check 'unit: exact hit is NOT marked and prints no fold marker' (
    @($fx2).Count -eq 1 -and -not $fx2[0].PSObject.Properties['Folded'] -and (Get-OcrFoldMarker $fx2) -eq '')
  # the fold set is closed on purpose: S/5, Z/2, B/8 must NOT be folded.
  # NOTE the deliberate bare-call form below: wrapping a Find-OcrHits call in an
  # @() gives Object[1]{ArrayList} whose Count is always 1 - the very trap this
  # lint exists for, and it bit while these very cases were being written (the
  # selftest caught it, which is the proof the gate has teeth).
  $noFoldLines = New-Object System.Collections.ArrayList
  [void]$noFoldLines.Add([pscustomobject]@{ Text = 'RATE5OK'; X = 1; Y = 1; W = 40; H = 12 })
  $nf1 = Find-OcrHits $noFoldLines 'RATE S OK'
  ST-Check 'unit: S/5 is deliberately not folded (no broadened false green)' ($nf1.Count -eq 0)
  $zLines = New-Object System.Collections.ArrayList
  [void]$zLines.Add([pscustomobject]@{ Text = 'LINK2UP'; X = 1; Y = 1; W = 40; H = 12 })
  $nf2 = Find-OcrHits $zLines 'LINKZUP'
  ST-Check 'unit: Z/2 is deliberately not folded' ($nf2.Count -eq 0)
  # ---------- unit: v1.5.2 WP-5 strict UTF-8 gate for sent files (audit R-11) ----------
  $u8ok = Join-Path $env:TEMP ('dtx-utf8-' + [guid]::NewGuid().ToString('N') + '.txt')
  $u8bom = Join-Path $env:TEMP ('dtx-bom-' + [guid]::NewGuid().ToString('N') + '.txt')
  $u8gbk = Join-Path $env:TEMP ('dtx-gbk-' + [guid]::NewGuid().ToString('N') + '.txt')
  try {
    [System.IO.File]::WriteAllBytes($u8ok, [System.Text.Encoding]::UTF8.GetBytes('QX UTF8 OK'))
    $bomBytes = [System.Text.Encoding]::UTF8.GetBytes('QX BOM TEXT')
    $withBom = New-Object byte[] ($bomBytes.Length + 3)
    $withBom[0] = 0xEF; $withBom[1] = 0xBB; $withBom[2] = 0xBF
    [System.Array]::Copy($bomBytes, 0, $withBom, 3, $bomBytes.Length)
    [System.IO.File]::WriteAllBytes($u8bom, $withBom)
    # GBK 'zhong wen' bytes: invalid as UTF-8 - this is the exact file shape that
    # used to paste as 53 chars of garbage with exit 0
    [System.IO.File]::WriteAllBytes($u8gbk, [byte[]]@(0xD6, 0xD0, 0xCE, 0xC4))
    $r1 = Read-SendFileUtf8 $u8ok
    ST-Check 'unit: valid UTF-8 file reads exactly, no BOM' ($r1.Text -ceq 'QX UTF8 OK' -and $r1.HadBom -eq $false)
    $r2 = Read-SendFileUtf8 $u8bom
    ST-Check 'unit: UTF-8 BOM is detected and stripped from the payload' ($r2.Text -ceq 'QX BOM TEXT' -and $r2.HadBom -eq $true)
    $r3err = ''
    try { [void](Read-SendFileUtf8 $u8gbk) } catch { $r3err = $_.Exception.Message }
    ST-Check 'unit: a GBK/ANSI file is REFUSED with an actionable message' (
      $r3err -like 'file is not valid UTF-8*' -and $r3err -like '*Re-save as UTF-8*' -and $r3err -like '*D6 D0 CE C4*')
    Write-Output "      UTF-8 gate message: $r3err"
  } catch {
    ST-Check 'unit: UTF-8 gate tests run' $false
    Write-Output "      UTF-8 gate error: $($_.Exception.Message)"
  } finally {
    foreach ($tfu in @($u8ok, $u8bom, $u8gbk)) { if (Test-Path -LiteralPath $tfu) { Remove-Item -LiteralPath $tfu -Force -ErrorAction SilentlyContinue } }
  }


  # ---------- unit + lint: v4.2.0 feedback item 6 - a parked pick says parked ----------
  ST-Check 'unit: a minimized pick is labelled parked on BOTH bases, a live pick keeps its basis' (
    ((Get-WindowPickLabel 'fg' $false) -ceq 'fg') -and ((Get-WindowPickLabel 'largest' $false) -ceq 'largest') -and
    ((Get-WindowPickLabel 'fg' $true) -ceq 'parked') -and ((Get-WindowPickLabel 'largest' $true) -ceq 'parked'))
  ST-Check 'unit: Test-WindowIconic answers false for no window and for a synthetic handle instead of throwing' (
    ((Test-WindowIconic $null) -eq $false) -and ((Test-WindowIconic @{ Handle = [IntPtr]::Zero }) -eq $false))
  # the scan pattern is written WITH escapes so this very line cannot match itself.
  # both needles assembled by concatenation: a literal would make this line its own hit
  # (measured: the Iconic scan reported 3 = 2 production + 1 check).
  $p6IconNeedle = 'Add-Member -NotePropertyName ' + 'Iconic'
  $p6EchoNeedle = 'iconic=' + [char]36 + '(Get-OptValue'
  $p6IconicSites = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($p6IconNeedle) })
  $p6EchoSites = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($p6EchoNeedle) })
  ST-Check 'lint: both Resolve-Window branches stamp Iconic, and assert-window echoes it (one site each)' (
    (@($p6IconicSites).Count -eq 2) -and (@($p6EchoSites).Count -eq 1))
  $d7RowNoOwner = Format-WinRowText ([pscustomobject]@{ Pid = 1; Proc = 'p'; Class = 'c'; Popup = $false; Owner = [int64]0; Main = 'yes'; Left = 0; Top = 0; Right = 8; Bottom = 6; W = 8; H = 6; Title = 'T' })
  ST-Check 'unit: wins text row prints owner=- for an unowned window and carries main=' ($d7RowNoOwner.Contains('owner=- main=yes'))
  $d7RowOwner = Format-WinRowText ([pscustomobject]@{ Pid = 1; Proc = 'p'; Class = 'c'; Popup = $false; Owner = [int64]42; Main = 'no'; Left = 0; Top = 0; Right = 8; Bottom = 6; W = 8; H = 6; Title = 'T' })
  ST-Check 'unit: wins text row prints the real owner handle when there is one' ($d7RowOwner.Contains('owner=42 main=no'))
  # the two views of one row must not drift: the text row has exactly one producer, and the
  # JSON key set is pinned so a future column edit is a deliberate contract change.
  # !! Every search marker below is built by CONCATENATION: a scan line that contains its
  # own search string matches itself (this exact trap made the first version of these two
  # checks report "2 projection lines" - one real, one the check).
  $d7RowPat = 'rect=(' + '$($_.Left),$($_.Top))'
  $d7InlineRow = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($d7RowPat) })
  $d7CallPat = 'Format-WinRowText ' + '$_'
  $d7Calls = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($d7CallPat) })
  ST-Check 'lint: wins prints through Format-WinRowText and has no second copy of the row shape' (
    @($d7InlineRow).Count -eq 0 -and @($d7Calls).Count -eq 1)
  foreach ($d in @($d7InlineRow)) { Write-Output "      second copy of the row shape: $($d.Trim())" }
  $d7JsonPat = 'popup = [bool]$_.Popup;' + ' owner ='
  $d7JsonLine = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($d7JsonPat) })
  $d7Keys = @()
  if (@($d7JsonLine).Count -eq 1) {
    $d7Keys = @([regex]::Matches($d7JsonLine[0], '([a-z_]+) = ') | ForEach-Object { $_.Groups[1].Value })
  }
  $d7Want = @('pid', 'proc', 'class', 'popup', 'owner', 'main', 'x', 'y', 'w', 'h', 'title')
  ST-Check 'unit: wins --json row key set is exactly the pinned 11 keys (add/drop = deliberate contract edit)' (
    @($d7JsonLine).Count -eq 1 -and (@($d7Keys | Sort-Object) -join ',') -ceq (($d7Want | Sort-Object) -join ','))
  if (@($d7JsonLine).Count -ne 1) { Write-Output "      wins json projection lines found: $(@($d7JsonLine).Count)" }
  if (@($d7Keys).Count -gt 0) { Write-Output "      wins json keys: $(@($d7Keys) -join ' ')" }

}

# lib/selftest-challenge-workflow.ps1 - family challenge-workflow of the selftest section, lifted out
# of lib/selftest.ps1 by A-14g (A-beta). Bodies are byte-identical to what the section carried.
# Two banners, 204 lines: the verification-challenge workflow (J-02: detect, classify, staleness, one
# authorized attempt, fuse, handoff - and explicitly NO solver) and the process-entry environment
# normalizer (F2). A-14e attempted this same cut and reverted it: two production lints reddened
# because the window they exempt themselves by was an open interval that stopped at the first family
# file. A-14f replaced that window with the AST span of every selftest body, which is what makes
# this card possible without touching those lints. The second block moves forward to join the first;
# the reordering is counted in the card notes, not waved away.
function Invoke-SelftestFamily-ChallengeWorkflow($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $codeLines = $Ctx['codeLines']
  $clCount = $Ctx['clCount']
  $j5ProdStart = $Ctx['j5ProdStart']
  $j5ProdEnd = $Ctx['j5ProdEnd']
  $srcLines = $Ctx['srcLines']

  # ---------- v1.10.0: verification-challenge workflow (J-02 boundary: detect/classify/staleness/one-authorized-attempt/fuse/handoff; NO solver) ----------
  # Synthetic OCR lines only - the real thing is a live concern. Corpus needles come
  # FROM Get-ChallengeCorpus (a second hand-built copy here would drift silently).
  $c40Corpus = @(Get-ChallengeCorpus)
  $c40Drag = @($c40Corpus | Where-Object { $_.Kind -eq 'slider' })[0].Needle
  $c40Puzzle = @($c40Corpus | Where-Object { $_.Kind -eq 'slider' })[1].Needle
  $c40Secure = @($c40Corpus | Where-Object { $_.Needle.Length -eq 4 })[0].Needle
  $c40Mk = { param($txt, $x, $y) [pscustomobject]@{ Text = $txt; X = $x; Y = $y; W = 300; H = 34 } }
  $c40Slider = Test-ChallengeLines @((& $c40Mk "$c40Drag$c40Puzzle" 40 30), (& $c40Mk 'some ordinary card text' 40 90))
  ST-Check 'unit: challenge matcher - a slider-affordance line classifies slider-captcha and its line is the handle' (
    $c40Slider.Challenge -and ($c40Slider.Type -eq 'slider-captcha') -and ($null -ne $c40Slider.Handle) -and ($c40Slider.Handle.Y -eq 30))
  $c40Plain = Test-ChallengeLines @((& $c40Mk 'order summary row one' 40 30), (& $c40Mk 'order summary row two' 40 90), (& $c40Mk 'order summary row three' 40 150))
  ST-Check 'unit: challenge matcher - dense ordinary text reads none (the two directions of V-1)' (-not $c40Plain.Challenge)
  $c40Single = Test-ChallengeLines @((& $c40Mk "$c40Secure page" 40 30))
  $c40High = Test-ChallengeLines @((& $c40Mk "$c40Drag$c40Puzzle" 40 30), (& $c40Mk "$c40Secure" 40 90))
  ST-Check 'unit: challenge matcher - one hit reads medium, several hits read high' (
    ($c40Single.Confidence -eq 'medium') -and ($c40High.Confidence -eq 'high') -and (@($c40High.Matched).Count -ge 3))
  $c40S1 = Test-ChallengeStale '' 'aabb'
  $c40S2 = Test-ChallengeStale 'aabb' 'aabb'
  $c40S3 = Test-ChallengeStale 'aabb' 'ccdd'
  ST-Check 'unit: challenge staleness - first-seen / unchanged reads stale=yes with the dismiss advice / changed reads stale=no' (
    ($c40S1.Stale -eq 'first-seen') -and ($c40S2.Stale -eq $true) -and $c40S2.Recommend.Contains('dismiss-not-solve') -and ($c40S3.Stale -eq $false))
  $c40Id = Get-ChallengeIdentityHash @{ Type = 'slider-captcha'; Confidence = 'high'; Matched = @('drag', 'secure'); Lines = 3; Handle = [pscustomobject]@{ X = 1; Y = 2; W = 3; H = 4 } }
  $c40Id2 = Get-ChallengeIdentityHash @{ Type = 'slider-captcha'; Confidence = 'high'; Matched = @('secure', 'drag'); Lines = 3; Handle = [pscustomobject]@{ X = 1; Y = 2; W = 3; H = 4 } }
  $c40Id3 = Get-ChallengeIdentityHash @{ Type = 'slider-captcha'; Confidence = 'high'; Matched = @('secure'); Lines = 3; Handle = [pscustomobject]@{ X = 1; Y = 2; W = 3; H = 4 } }
  ST-Check 'unit: challenge identity hash is stable across corpus order and changes when the recognized challenge changes' (
    $c40Id -eq $c40Id2 -and $c40Id -ne $c40Id3 -and $c40Id -match '^[0-9a-f]{32}$')
  $c40Log1 = '2026-10-01 00:00:00 UTC | challenge-probe | pid=111 | seen hash=0000000000000000000000000000aaaa'
  $c40Log2 = '2026-10-01 00:00:01 UTC | challenge-probe | pid=222 | seen hash=0000000000000000000000000000bbbb'
  $c40Log3 = '2026-10-01 00:00:02 UTC | challenge-probe | pid=111 | fuse hash=0000000000000000000000000000cccc'
  $c40Log4 = '2026-10-01 00:00:03 UTC | click | 10 20 | pid=111 title=x'
  $c40State = Test-ChallengeLogLines @($c40Log1, $c40Log2, $c40Log3, $c40Log4) 111
  $c40StateOther = Test-ChallengeLogLines @($c40Log1, $c40Log2, $c40Log3, $c40Log4) 222
  ST-Check 'unit: challenge log state - seen and fuse hashes extracted per pid, other pids and act lines ignored' (
    ($c40State.LastHash -eq '0000000000000000000000000000aaaa') -and ($c40State.FuseHash -eq '0000000000000000000000000000cccc') -and
    ($c40StateOther.LastHash -eq '0000000000000000000000000000bbbb') -and ($c40StateOther.FuseHash -eq ''))
  # v4.0.1 (audit finding 2): the three read outcomes must not collapse into one another. `absent`
  # is the only state allowed to become first-seen; `unreadable` has to stay a separate answer,
  # which is what the last clause pins - if both branches ever return the same token, this goes
  # red instead of quietly re-opening the fail-open fuse.
  $c40LbAbsent = Resolve-ChallengeLogState $false $false
  $c40LbUnread = Resolve-ChallengeLogState $true $false
  $c40LbUnwrit = Resolve-ChallengeLogState $true $true $false
  $c40LbOk = Resolve-ChallengeLogState $true $true
  $c40LbDflt = Resolve-ChallengeLogState $true $true $true
  # pairwise distinctness is the whole point: if any two branches ever return the same token the
  # unique-count drops and this goes red instead of quietly re-opening the fail-open fuse.
  $c40LbSet = @($c40LbAbsent, $c40LbUnread, $c40LbUnwrit, $c40LbOk) | Sort-Object -Unique
  ST-Check 'unit: challenge log read state - absent / unreadable / unwritable / ok are four pairwise distinct answers and the 2-arg form still means the write succeeded' (
    ($c40LbAbsent -ceq 'absent') -and ($c40LbUnread -ceq 'unreadable') -and ($c40LbUnwrit -ceq 'unwritable') -and ($c40LbOk -ceq 'ok') -and
    (@($c40LbSet).Count -eq 4) -and ($c40LbDflt -ceq $c40LbOk))
  # v4.1.1 (X-02 residual, surfaced by the second external review round): a bare LOCAL null-init
  # sitting next to a script-scoped read is NOT an initialiser for that read - it is dead code that
  # LOOKS like the guard, and under StrictMode the finally then raises a second error that masks
  # the real one. Two instances were live in the file (the challenge fixture and the popup-gate
  # fixture). The predicate is proven against a planted copy of the shape, because a lint that has
  # never fired on a known-bad input is not a lint. Plant strings are ASSEMBLED at runtime so this
  # very block cannot be flagged by the scan it defines.
  $scopeOffenders = {
    param($slArr)
    $bad2 = @()
    foreach ($sl in $slArr) {
      $mScope = [regex]::Match([string]$sl, '^\s*\$([A-Za-z][A-Za-z0-9_]*)\s*=\s*\$null\s*$')
      if (-not $mScope.Success) { continue }
      $sName = $mScope.Groups[1].Value
      $asScript = 0; $asBare = 0
      foreach ($sl2 in $slArr) {
        $s2 = [string]$sl2
        $asScript += ([regex]::Matches($s2, ('\$script:' + [regex]::Escape($sName) + '(?![A-Za-z0-9_])'))).Count
        $asBare += ([regex]::Matches($s2, ('\$' + [regex]::Escape($sName) + '(?![A-Za-z0-9_])'))).Count
      }
      if ($asScript -gt 0 -and $asBare -le 1) { $bad2 += $sName }
    }
    return ,@($bad2)
  }
  $scopeReal = & $scopeOffenders $codeLines
  $plStem = 'zz' + 'Proc'
  $scopePlant = @(
    ('      $' + $plStem + ' = ' + '$null'),
    '      try {',
    ('        $script:' + $plStem + ' = Start-Process x'),
    '      } finally {',
    ('        if ($script:' + $plStem + ') { Stop-Process }'),
    '      }'
  )
  $scopeCaught = & $scopeOffenders $scopePlant
  Write-Output ('      scope-shadow offenders=' + (@($scopeReal).Count) + ' [' + (@($scopeReal) -join ',') + '] plant-caught=' + (@($scopeCaught).Count))
  ST-Check 'lint: no bare local null-initialiser may stand in for the script-scoped variable a finally actually reads, and the predicate catches a planted copy of the shape' (
    (@($scopeReal).Count -eq 0) -and (@($scopeCaught).Count -eq 1) -and ($scopeCaught[0] -ceq $plStem))
  $c40HandWin = [pscustomobject]@{ Title = 'DTX-ChalProbe'; Pid = 4242; Left = 150; Top = 700; W = 700; H = 420 }
  $c40Hand = Build-ChallengeHandoff $c40Slider $c40HandWin 'deadbeef' 'shots\challenge-x.png'
  $c40HandAll = "$($c40Hand -join [char]10)"
  ST-Check 'unit: challenge handoff carries all four contract fields (type= / rect= / handle: / shot:) - V-4 named contract' (
    $c40HandAll.Contains('type=slider-captcha') -and $c40HandAll.Contains('rect=(150,700,700x420)') -and $c40HandAll.Contains('  handle: (') -and $c40HandAll.Contains('  shot: shots\challenge-x.png'))
  $c40HandNoHandle = Build-ChallengeHandoff $c40Plain $c40HandWin 'deadbeef' 'shots\challenge-x.png'
  ST-Check 'unit: challenge handoff without a slider line still carries the handle field as not-found (the field never disappears)' (
    (("$($c40HandNoHandle -join [char]10)")).Contains('  handle: not-found'))
  $c41DefN = 0; $c41CallN = 0; $c41FuseMsg = 0; $c41NotAuth = 0; $c41NoSolver = 0
  for ($c41i = 0; $c41i -lt $codeLines.Count; $c41i++) {
    if ($c41i -ge $j5ProdStart -and $c41i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c41i] -match '^\s*#') { continue }
    if ($codeLines[$c41i].StartsWith('function Get-ChallengeCorpus')) { $c41DefN++ }
    if ($codeLines[$c41i].Contains('(Get-ChallengeCorpus)') -and (-not $codeLines[$c41i].Contains('$c40'))) { $c41CallN++ }
    if ($codeLines[$c41i].Contains(('challenge attempt FAILED '))) { $c41FuseMsg++ }
    if ($codeLines[$c41i].Contains(('attempt: not authorized (pass --allow-' + 'attempt'))) { $c41NotAuth++ }
    if ($codeLines[$c41i].Contains(('There is NO solver ' + 'in this tool by design'))) { $c41NoSolver++ }
  }
  ST-Check 'lint: the challenge corpus has exactly one definition and one production consumer (a second copy would drift silently)' (
    ($c41DefN -eq 1) -and ($c41CallN -eq 1))
  ST-Check 'lint: the attempt gate speaks once (not-authorized hint, FAILED fuse message) and the no-solver boundary is stated in code, not just docs' (
    ($c41FuseMsg -eq 1) -and ($c41NotAuth -eq 1) -and ($c41NoSolver -ge 1))
  # v2.2.0 (R5-B): the act-count witness cannot tell "a guard refused the click" from "the
  # click landed and the challenge stayed up" - both read exit 1 + FAILED + delta 0. The
  # FAILED line already says which, so the live echo must carry it, and that carry must not
  # be removable without going red here. Both markers live in the SELFTEST body, so this
  # scans exactly the range the production-wiring loop above deliberately skips.
  $c41Reason = 0; $c41WhyCap = 0
  for ($c41j = $j5ProdStart; $c41j -lt $j5ProdEnd; $c41j++) {
    if ($codeLines[$c41j].Contains(('click-' + 'reason='))) { $c41Reason++ }
    if ($codeLines[$c41j].Contains(('$chFail' + 'Lines = @('))) { $c41WhyCap++ }
  }
  ST-Check 'lint: the V-3 live echo carries the tool own refusal reason (click-reason field spoken exactly once, fed by exactly one FAILED-line capture) - a flat act delta must be self-classifying' (
    ($c41Reason -eq 1) -and ($c41WhyCap -eq 1))
  Write-Output ("      challenge wiring: corpus-def=$c41DefN corpus-call=$c41CallN fuse-msg=$c41FuseMsg not-auth=$c41NotAuth")


  # ---------- v4.2.2 (F2): the process-entry environment normalizer ----------
  # A process environment block can carry one name twice in different casing. Windows resolves
  # every lookup case-insensitively, but PS 5.1's Start-Process copies the block into its own
  # case-insensitive dictionary and dies on the twin - measured 2026-10-10, and it took the whole
  # offline gate down before its summary line. Three checks in the house shape: the pure decision
  # fed SYNTHETIC input (including a planted twin), the raw reader being non-vacuous (a reader
  # that sees nothing would make any box look clean - the "0 hits" rule), and the wiring counted
  # over the production region (one raw read, one removal primitive, no second implementation).
  $f2NoDup = Get-DuplicateCaseEnvNames @('PATH', 'TEMP')
  $f2OneDup = Get-DuplicateCaseEnvNames @('PATH', 'Path')
  $f2Triple = Get-DuplicateCaseEnvNames @('HTTP_PROXY', 'http_proxy', 'Http_Proxy')
  $f2Exact = Get-DuplicateCaseEnvNames @('PATH', 'PATH')
  $f2Near = Get-DuplicateCaseEnvNames @('PATH', 'PATHX')
  ST-Check 'unit (F2): the duplicate-case finder keeps the FIRST spelling, names every later one, and never touches a name that merely looks similar' (
    (@($f2NoDup).Count -eq 0) -and (@($f2OneDup).Count -eq 1) -and ($f2OneDup[0] -ceq 'Path') -and
    (@($f2Triple).Count -eq 2) -and ($f2Triple[0] -ceq 'http_proxy') -and ($f2Triple[1] -ceq 'Http_Proxy') -and
    (@($f2Exact).Count -eq 1) -and ($f2Exact[0] -ceq 'PATH') -and (@($f2Near).Count -eq 0))
  $f2RawAll = @([DT]::RawEnvNames())
  $f2RawEquals = @($f2RawAll | Where-Object { ([string]$_).Contains('=') })
  ST-Check 'unit (F2): the raw environment reader sees this process own block and returns NAMES, never NAME=VALUE (an empty or unsplit read would make every box look clean)' (
    ($f2RawAll.Count -ge 10) -and (@($f2RawAll | Where-Object { ([string]$_).Length -gt 0 }).Count -eq $f2RawAll.Count) -and
    ($f2RawEquals.Count -eq 0) -and (@($f2RawAll | Where-Object { ([string]$_) -ieq 'PATH' }).Count -ge 1))
  $f2CallSites = @()
  $f2RemoveSites = @()
  for ($f2I = 0; $f2I -lt $clCount; $f2I++) {
    if ($f2I -ge $j5ProdStart -and $f2I -lt $j5ProdEnd) { continue }
    $f2L = [string]$codeLines[$f2I]
    if ($f2L -match '^\s*#') { continue }
    if ($f2L.Contains('Get-DuplicateCaseEnvNames $envRawNames')) { $f2CallSites += ($f2I + 1) }
    if ($f2L.Contains('SetEnvironmentVariable($envDn')) { $f2RemoveSites += ($f2I + 1) }
  }
  ST-Check 'lint (F2): the entry normalizer is wired exactly once - one raw read, one removal primitive, and no second implementation' (
    (@($f2CallSites).Count -eq 1) -and (@($f2RemoveSites).Count -eq 1))
  Write-Output ("      env normalizer: call-sites=[" + (Format-SourceLineList $f2CallSites) + "] remove-sites=[" + (Format-SourceLineList $f2RemoveSites) + "] raw-names=" + $f2RawAll.Count)

  # v3.1.0 (F-03): that block now carries a SECOND skip shape - a private-history anchor read from a
  # re-rooted public clone. It has to be pinned, not trusted: an unasserted skip is how this project
  # shipped two "silently always green" cases already. The counts below are EXACT on purpose - a floor
  # would survive deleting either half of the narrowing conjunction, and the private tree MUST still
  # go red when its own anchors disappear. 3 = the assignment, the branch, and this file's own
  # conjunction mark (which names the gate variable, not the full conjunction, so the conjunction
  # count stays 1 and only the real branch can satisfy it).
  $pubGateMark = '$anchPub' + 'lished'
  $pubSkipMark = 'are private-history anchors and this is the ' + 'published tree'
  $pubProbeMark = "'cat-file', '-e', (" + '$anchOid'
  $pubConjMark = '$anchPublished -and $anchMissing' + '.Count -gt 0'
  $pubNoBytesMark = 'NO bytes were ' + 'compared'
  $pubGateLines = 0; $pubSkipLines = 0; $pubProbeLines = 0; $pubConjLines = 0; $pubNoBytesLines = 0
  foreach ($ep in $srcLines) {
    $eps = [string]$ep
    if ($eps.Contains($pubGateMark)) { $pubGateLines++ }
    if ($eps.Contains($pubSkipMark)) { $pubSkipLines++ }
    if ($eps.Contains($pubProbeMark)) { $pubProbeLines++ }
    if ($eps.Contains($pubConjMark)) { $pubConjLines++ }
    if ($eps.Contains($pubNoBytesMark)) { $pubNoBytesLines++ }
  }
  # X-02: this helper shipped WITHOUT a test of its own, and that is exactly how the bug below hid.
  # A hashtable's Keys / Values / Count are INTRINSIC members, not keys, so an early
  # "if IDictionary -> return $null when the key is absent" made them read as missing. It surfaced
  # only when a later batch rewrote a $spec.Keys read and the run died on "cannot index a null array"
  # with 584 verdicts flipped. Intrinsic members must keep resolving through PSObject.
  $x02Hasht = @{ A = 1 }
  $x02Obj = [pscustomobject]@{ A = 2 }
  $x02ObjNoA = [pscustomobject]@{ B = 3 }
  ST-Check 'unit (X-02): Get-OptValue separates an absent KEY from an INTRINSIC member (hashtable Keys/Count are not keys - that early return once turned them into null, which is why the helper has a test now)' (
    ((Get-OptValue $x02Hasht 'A') -eq 1) -and
    ($null -eq (Get-OptValue $x02Hasht 'MissingKey')) -and
    ($null -ne (Get-OptValue $x02Hasht 'Keys')) -and (@(Get-OptValue $x02Hasht 'Keys').Count -eq 1) -and
    ((Get-OptValue $x02Hasht 'Count') -eq 1) -and
    ($null -ne (Get-OptValue $x02Hasht 'Values')) -and ($((Get-OptValue $x02Hasht 'Values')[0]) -eq 1) -and
    ((Get-OptValue $x02Obj 'A') -eq 2) -and
    ($null -eq (Get-OptValue $x02ObjNoA 'A')) -and
    ($null -eq (Get-OptValue $null 'A'))
  )
  ST-Check 'lint (F-03): the BOM anchor publishes a SECOND, narrowed skip (published tree AND missing private anchor), self-reports that no bytes were compared, and the private tree keeps its red' (
    ($pubGateLines -eq 3) -and ($pubSkipLines -eq 1) -and ($pubProbeLines -eq 1) -and ($pubConjLines -eq 1) -and ($pubNoBytesLines -eq 1))
  Write-Output ("      anchor skip shapes: gate=$pubGateLines pub-skip=$pubSkipLines presence-probe=$pubProbeLines conjunction=$pubConjLines no-bytes-disclosure=$pubNoBytesLines")


}

# lib/selftest-capture-ocr.ps1 - family capture-ocr of the selftest section, lifted out of
# lib/selftest.ps1 by A-14h (A-beta). Bodies are byte-identical to what the section carried.
# Eight banners in six gathered pieces (two pairs were already adjacent): read-text on a saved
# capture, one OCR tail for every miss, CJK spacing Windows OCR invents, the retry decision, the
# tiled planner and merge, the folded long-payload receipt, the sparse-read hint and needle
# sub-span aiming. State arrives only through $Ctx; lint (A-14b) names any read that reaches past it.
# These pieces were scattered between lines 509 and 3625, so gathering them reorders the section -
# the card counts that by name and position rather than claiming the order does not matter.
function Invoke-SelftestFamily-CaptureOcr($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $self = [string]$Ctx['self']
  $src = [string]$Ctx['src']
  $codeLines = $Ctx['codeLines']
  $clCount = $Ctx['clCount']
  $code = $Ctx['code']
  $j5ProdStart = $Ctx['j5ProdStart']
  $j5ProdEnd = $Ctx['j5ProdEnd']

  # ---------- v2.7.0: OCR a saved capture (read-text --file) ----------
  # This is the check that finally makes the OCR road MEASURABLE: it renders a known
  # string to a PNG with GDI+ and reads it back through the same engine the live road
  # uses, with no window raised and no desktop touched. It is NOT gated behind --live,
  # because the whole point is that it can run anywhere, any time - and it is the harness
  # the recognizer A/B (en-US vs zh-Hans language pack) is meant to be run through.
  # On a box with no OCR language pack it SKIPS with a reason; skipping must not move the
  # badge total (that is the v2.5.4 fix, and this check is one of its first users).
  $ocrPackTag = ''
  try {
    $oe = Get-OcrEngine
    if ($null -ne $oe) { $ocrPackTag = "$($oe.RecognizerLanguage.LanguageTag)" }
  } catch { $ocrPackTag = '' }
  $ocDir = Join-Path $env:TEMP ('st_ocrfile_' + [guid]::NewGuid().ToString('N'))
  # v4.1.3 (external review B): the else branch below holds NINETEEN checks, while this
  # branch used to emit ONE skip - so every engine that cannot reach the recognizer lost
  # eighteen checks without saying so (measured here: pwsh 7 emits 795 of 815). The skip
  # side now accounts for the whole region by name, read back out of this file's source.
  $script:StRecord = New-Object System.Collections.ArrayList
  if ($ocrPackTag -eq '') {
    ST-SkipRegion 'ocr-file' 'no OCR language pack / recognizer unreachable from this engine - the road itself is unavailable, so this is not a regression'
  } else {
    # REGION-BEGIN ocr-file  (every ST-Check between here and REGION-END is accounted for
    # by ST-SkipRegion when the recognizer is missing - a check that needs something ELSE
    # must not join this region, or the skip side would excuse it too)
    New-Item -ItemType Directory -Force -Path $ocDir | Out-Null
    $ocPng = Join-Path $ocDir 'render.png'
    $ocWant = 'File Edit View Run Terminal Help'
    $ab = New-Object System.Drawing.Bitmap(1200, 90)
    $ag = [System.Drawing.Graphics]::FromImage($ab)
    $ag.Clear([System.Drawing.Color]::White)
    $ag.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAlias
    $af = New-Object System.Drawing.Font('Segoe UI', 28, [System.Drawing.FontStyle]::Regular)
    $ag.DrawString($ocWant, $af, [System.Drawing.Brushes]::Black, 10, 20)
    $ag.Dispose(); $af.Dispose()
    $ab.Save($ocPng, [System.Drawing.Imaging.ImageFormat]::Png)
    $ocW = [int]$ab.Width; $ocH = [int]$ab.Height
    $ab.Dispose()
    try {
      # The round trip goes through the REAL command line, not the function: the first
      # version of this check called Invoke-OcrFile directly and passed while the CLI was
      # broken (Split-Path -LiteralPath -Leaf dies on PowerShell 5.1, and it only lives in
      # the CLI's header). A check must exercise the path a caller exercises.
      $cliOut = Join-Path $ocDir 'cli.txt'
      $cliArgs = '-NoProfile -ExecutionPolicy Bypass -File "' + $self + '" read-text --file "' + $ocPng + '"'
      $cli = Start-Process -FilePath 'powershell.exe' -ArgumentList $cliArgs -RedirectStandardOutput $cliOut -RedirectStandardError "$cliOut.err" -Wait -PassThru -NoNewWindow
      $cliTxt = ''
      if (Test-Path -LiteralPath $cliOut) { $cliTxt += (Get-Content -Raw -LiteralPath $cliOut) }
      if (Test-Path -LiteralPath "$cliOut.err") { $cliTxt += (Get-Content -Raw -LiteralPath "$cliOut.err") }
      $cliGot = ''
      foreach ($cl in ($cliTxt -split "`r?`n")) {
        if ($cl -match '^L\d\d img-rect=') { $cliGot += (($cl -replace '^L\d\d img-rect=\([0-9,\-x]+\)\s*', '') + ' ') }
      }
      $gotNorm = ($cliGot -replace '\s+', ' ').Trim()
      $wantNorm = ($ocWant -replace '\s+', ' ').Trim()
      ST-Check 'e2e: read-text --file round-trips a rendered string back through the recognizer' (
        ($cli.ExitCode -eq 0) -and ("$gotNorm" -ceq "$wantNorm") -and ($cliTxt -match 'source=file') -and ($cliTxt -match 'NOT a screen rect'))
      Write-Output ("      ocr-file: pack=$ocrPackTag exit=$($cli.ExitCode) wanted=[$wantNorm] got=[$gotNorm]")
      $fr = Invoke-OcrFile $ocPng 1.0
      ST-Check 'e2e: read-text --file reports the image size and keeps every rect inside it' (
        ($fr.W -eq $ocW) -and ($fr.H -eq $ocH) -and (@($fr.Lines | Where-Object { $_.X -lt 0 -or $_.Y -lt 0 -or ($_.X + $_.W) -gt $ocW -or ($_.Y + $_.H) -gt $ocH }).Count -eq 0))
      # The refusal is user-visible behavior, so it is pinned end to end: a child that
      # exits non-zero AND names both the img-rect label and the pinned-contract reason.
      # The argument string carries EMBEDDED quotes on purpose: PS 5.1's Start-Process
      # -ArgumentList array form does not quote elements containing spaces.
      $jrOut = Join-Path $ocDir 'jsonrefusal.txt'
      $jrArgs = '-NoProfile -ExecutionPolicy Bypass -File "' + $self + '" read-text --file "' + $ocPng + '" --json'
      $jr = Start-Process -FilePath 'powershell.exe' -ArgumentList $jrArgs -RedirectStandardOutput $jrOut -RedirectStandardError "$jrOut.err" -Wait -PassThru -NoNewWindow
      $jrTxt = ''
      if (Test-Path -LiteralPath $jrOut) { $jrTxt += (Get-Content -Raw -LiteralPath $jrOut) }
      if (Test-Path -LiteralPath "$jrOut.err") { $jrTxt += (Get-Content -Raw -LiteralPath "$jrOut.err") }
      ST-Check 'e2e: read-text --file refuses --json instead of emitting an ambiguous coordinate space' (
        ($jr.ExitCode -ne 0) -and ("$jrTxt" -match 'img-rect') -and ("$jrTxt" -match 'pinned'))
      # The header and the per-line label are the only things standing between a caller
      # and clicking a glyph's image px, so the documentation of them is a check, not a
      # comment. Whitespace MUST be collapsed before matching: the Usage page is an array
      # of indented lines, so a phrase that wraps across a line break would never match
      # (this cost one red run - the phrase was in the help all along).
      $usageTxt = ((@(Get-UsageLines)) -join ' ') -replace '\s+', ' '
      ST-Check 'lint: the file-mode help names the img-rect label and says the coords are not a screen rect' (
        ($usageTxt.Contains('img-rect=')) -and ($usageTxt.Contains('NOT a screen rect')) -and ($usageTxt.Contains('--file <png>')))
      ST-Check 'lint: the file-mode help documents the retry ladder, its own floor, its opt-out and the engine-cap skip' (
        ($usageTxt.Contains('--scale tiled')) -and ($usageTxt.Contains('auto-retry')) -and
        ($usageTxt.Contains('30000 px2')) -and ($usageTxt.Contains('300k px2')) -and
        ($usageTxt.Contains('--no-tile')) -and ($usageTxt.Contains('never "region"')) -and
        ($usageTxt.Contains('four un-upscaled overlapping crops')) -and
        ($usageTxt.Contains("dimension limit rules the upscale out")))
      # v2.9.0 changed what a read-text header LOOKS like, so the change is pinned where a
      # reader finds it: the help must name the label, say the lowered line belongs to
      # read-text alone, and point at the negative paths that still shout at the band.
      ST-Check 'lint: the help states the readability label and that only read-text lowered its line' (
        ($usageTxt.Contains('readability=')) -and ($usageTxt.Contains('FOR read-text ONLY')) -and
        ($usageTxt.Contains('0.1')) -and ($usageTxt.Contains('find-text / assert-text / expect')))

      # ---- v2.8.0 end to end. These drive the command line, not the functions, because
      # the defect fixed this round was precisely "a flag that is accepted and does
      # nothing": a function-level check would have stayed green through it.
      $stRun = {
        param([string]$Path, [string]$Extra, [string]$OutName)
        $o = Join-Path $ocDir $OutName
        $a = '-NoProfile -ExecutionPolicy Bypass -File "' + $self + '" read-text --file "' + $Path + '" ' + $Extra
        $pr = Start-Process -FilePath 'powershell.exe' -ArgumentList $a -RedirectStandardOutput $o -RedirectStandardError "$o.err" -Wait -PassThru -NoNewWindow
        $txt = ''
        if (Test-Path -LiteralPath $o) { $txt += (Get-Content -Raw -LiteralPath $o) }
        if (Test-Path -LiteralPath "$o.err") { $txt += (Get-Content -Raw -LiteralPath "$o.err") }
        return @{ Exit = $pr.ExitCode; Txt = $txt }
      }
      # (1) --scale tiled must subdivide. The 1200x90 menu-bar render is far below the
      # engine's 10000px limit, so the only thing that can produce tiles >= 2 here is the
      # v2.8.0 override - which is what this asserts.
      $tT = & $stRun $ocPng '--scale tiled' 'tiled.txt'
      $tTiles = 0
      if ($tT.Txt -match 'tiled:\s+(\d+) tile') { $tTiles = [int]$Matches[1] }
      $tOut = New-Object System.Collections.ArrayList
      # 16px of slack, on purpose: the Windows engine jitters line bboxes (observed up to
      # ~90px on tiles sitting exactly at its dimension limit), and a strictly-in-bounds
      # assertion here would turn that engine artifact into a red gate. What must hold is
      # that no rect is off by a LOT - that is what a mapping bug looks like.
      foreach ($cl in ($tT.Txt -split "`r?`n")) {
        if ($cl -match '^L\d\d img-rect=\((-?\d+),(-?\d+),(\d+)x(\d+)\)') {
          $lx = [int]$Matches[1]; $ly = [int]$Matches[2]; $lw = [int]$Matches[3]; $lh = [int]$Matches[4]
          if ($lx -lt -16 -or $ly -lt -16 -or ($lx + $lw) -gt ($ocW + 16) -or ($ly + $lh) -gt ($ocH + 16)) { [void]$tOut.Add($cl) }
        }
      }
      ST-Check 'e2e: --scale tiled in file mode subdivides the image and keeps every img-rect inside it' (
        ($tT.Exit -eq 0) -and ($tTiles -ge 2) -and (@($tOut).Count -eq 0) -and ($tT.Txt -match 'source=file scale=2'))
      Write-Output ("      file tiling: tiles=$tTiles out-of-bounds=$(@($tOut).Count)")
      # (2) an empty read must go through the LADDER and every pass must report its own
      # count - including zeros, and including a pass that never ran because --max-tiles
      # refused it. The three cases that used to be indistinguishable ("this is a photo",
      # "the recognizer lost a region", "nobody looked") have to print differently.
      $gyPng = Join-Path $ocDir 'gray.png'
      $gb = New-Object System.Drawing.Bitmap(800, 500)
      $gg = [System.Drawing.Graphics]::FromImage($gb)
      $gg.Clear([System.Drawing.Color]::FromArgb(128, 128, 128))
      $gg.Dispose()
      $gb.Save($gyPng, [System.Drawing.Imaging.ImageFormat]::Png); $gb.Dispose()
      $tR = & $stRun $gyPng '' 'retry.txt'
      $tN = & $stRun $gyPng '--no-tile' 'notile.txt'
      ST-Check 'e2e: an empty capture is re-read through the ladder and each pass reports its own count' (
        ($tR.Exit -eq 0) -and ($tR.Txt -match 'auto-retry') -and
        ($tR.Txt -match 'whole-image@1x=0 line\(s\)') -and ($tR.Txt -match 'whole@2x=0 line\(s\)') -and
        ($tR.Txt -match 'quadrants@1x=0 line\(s\) \(4 tiles\)') -and ($tR.Txt -match 'kept=0'))
      ST-Check 'e2e: --no-tile suppresses the ladder (the opt-out has to be real, not decorative)' (
        ($tN.Exit -eq 0) -and (-not ($tN.Txt -match 'auto-retry')))
      $tM = & $stRun $gyPng '--max-tiles 2' 'maxtiles.txt'
      ST-Check 'e2e: a ladder pass the tile budget refuses is reported as skipped, not as a bare 0' (
        ($tM.Exit -eq 0) -and ($tM.Txt -match 'auto-retry') -and ($tM.Txt -match 'quadrants@1x=skipped') -and
        ($tM.Txt -match 'quadrants needs 4 tiles') -and ($tM.Txt -match '--max-tiles 2'))
      # (2b) THE REGRESSION v2.8.0 SHIPPED WITH. Its ladder was gated on the sparse WARN's
      # 300k px2 band, which sits ABOVE the real 228,800 px2 capture the retry exists for -
      # so that capture got no warning, no retry, and printed exactly like a blank image.
      # 400x300 = 120,000 px2 is below the old band and above the empty-read floor: it must
      # now come back with a ladder report.
      $smPng = Join-Path $ocDir 'gray-small.png'
      $sbk = New-Object System.Drawing.Bitmap(400, 300)
      $sgk = [System.Drawing.Graphics]::FromImage($sbk)
      $sgk.Clear([System.Drawing.Color]::FromArgb(120, 120, 120))
      $sgk.Dispose()
      $sbk.Save($smPng, [System.Drawing.Imaging.ImageFormat]::Png); $sbk.Dispose()
      $tS2 = & $stRun $smPng '' 'retrysmall.txt'
      ST-Check 'e2e: an empty read below the WARN band still gets the ladder (v2.8.0 gated it out and shipped that way)' (
        ($tS2.Exit -eq 0) -and ($tS2.Txt -match 'auto-retry') -and ($tS2.Txt -match 'quadrants@1x=') -and
        ($tS2.Txt -match 'floor=30000'))
      # The ladder PRINTS the scale it used, so that number is part of the contract, not an
      # internal detail: the first build of the quadrant pass returned no Scale key at all,
      # and a recovered capture announced itself as "scale=0" - a self-report that is
      # silently wrong is worse than no self-report. Pinned at the function boundary because
      # the CLI only shows the adopted branch, which the gray fixtures never reach.
      $qRes = Invoke-OcrFileQuadrants $ocPng 16
      $qOut = @($qRes.Lines | Where-Object { $_.X -lt 0 -or $_.Y -lt 0 -or ($_.X + $_.W) -gt $ocW -or ($_.Y + $_.H) -gt $ocH })
      ST-Check 'unit: the quadrant pass states the scale it really read at and keeps every rect inside the image' (
        ($qRes.Scale -eq 1.0) -and ($qRes.Tiles -eq 4) -and (@($qRes.Lines).Count -ge 1) -and (@($qOut).Count -eq 0))
      $lRes = Invoke-OcrFileRetryLadder $gyPng 16
      $lRes2 = Invoke-OcrFileRetryLadder $ocPng 16
      ST-Check 'unit: the ladder never reports a scale it did not use, whichever pass it keeps' (
        (@(1.0, 2.0) -contains [double]$lRes.Scale) -and (@(1.0, 2.0) -contains [double]$lRes2.Scale) -and
        ($lRes.Report -match 'whole@2x=') -and ($lRes2.Report -match 'whole@2x='))
      # v3.0.1 (audit item 8, reproduced 2026-10-05 on a 6000x200 capture): the first rung
      # upscaled unconditionally and the engine THROWS on an oversized bitmap rather than
      # returning nothing, so the throw ended the command and the quadrant pass - the one
      # built for wide images - never ran. Any stored capture wider than half the cap was
      # simply unreadable in file mode. Both directions below use the SAME file; the only
      # difference is the cap, so the skip cannot be explained by a broken fixture.
      $ldSkip = Invoke-OcrFileRetryLadder $ocPng 16 100
      ST-Check 'unit: a first rung the engine cannot fit is skipped WITH A REASON and the quadrant pass still delivers the text' (
        ($ldSkip.Report -match 'whole@2x=skipped \(') -and (@($ldSkip.Lines).Count -ge 1) -and ($ldSkip.Scale -eq 1.0))
      $ldFit = Invoke-OcrFileRetryLadder $ocPng 16 20000
      ST-Check 'unit: the same capture under a cap it DOES fit runs the first rung (a limit, not an unconditional branch)' (
        ($ldFit.Report -match 'whole@2x=[0-9]+ line') -and ($ldFit.Scale -eq 2.0))
      $ldEdge = @((Get-OcrFileRung1Fit 5000 200 10000).Fits, (Get-OcrFileRung1Fit 5001 200 10000).Fits,
        (Get-OcrFileRung1Fit 100 100 0).Fits, (Get-OcrFileRung1Fit 4999 4999 9998).Fits)
      ST-Check 'unit: the rung-1 fit test is inclusive at the cap and distrustful of an unknown cap' (
        ($ldEdge[0] -eq $true) -and ($ldEdge[1] -eq $false) -and ($ldEdge[2] -eq $false) -and ($ldEdge[3] -eq $true))
      Write-Output ("      rung1 fit: 5000x200@10000=" + $ldEdge[0] + " 5001=" + $ldEdge[1] + " cap0=" + $ldEdge[2] + " exact=" + $ldEdge[3])
      # (3) v2.9.0: the changed rule, asserted on RENDERED output in both directions.
      # A merely-sparse read now carries the measurement and stays quiet; a near-zero read
      # still shouts and still says "image", never "region". The middle fixture is the SAME
      # file read twice at two thresholds, so the quiet one cannot be explained by a blank
      # capture or a broken fixture - only by the threshold moving.
      $spPng = Join-Path $ocDir 'sparse.png'
      $sb = New-Object System.Drawing.Bitmap(800, 500)
      $sg = [System.Drawing.Graphics]::FromImage($sb)
      $sg.Clear([System.Drawing.Color]::White)
      $sfont = New-Object System.Drawing.Font('Segoe UI', 26, [System.Drawing.FontStyle]::Regular)
      $sg.DrawString('DTX sparse capture row one', $sfont, [System.Drawing.Brushes]::Black, [single]20, [single]30)
      $sg.DrawString('DTX sparse capture row two', $sfont, [System.Drawing.Brushes]::Black, [single]20, [single]90)
      $sg.Dispose(); $sfont.Dispose()
      $sb.Save($spPng, [System.Drawing.Imaging.ImageFormat]::Png); $sb.Dispose()
      $tS = & $stRun $spPng '' 'sparse.txt'
      ST-Check 'e2e: a merely sparse read carries readability= and stays quiet (the shout that fired on 18.6% of real traffic is now a measurement)' (
        ($tS.Exit -eq 0) -and ($tS.Txt -match 'readability=0\.5 lines per 100k px2') -and
        ($tS.Txt -match 'warn-below=0\.1') -and ($tS.Txt -match 'band=small-area') -and
        (-not ($tS.Txt -match 'WARN:')))
      $tSO = & $stRun $spPng '--min-line-density 1.5' 'sparse-old.txt'
      ST-Check 'e2e: the very same capture at the old 1.5 band DOES shout, so the quiet above is the threshold, not a blank fixture' (
        ($tSO.Exit -eq 0) -and ($tSO.Txt -match 'WARN: image is 800x500') -and ($tSO.Txt -match 'active-threshold=1'))
      $nzPng = Join-Path $ocDir 'nearzero.png'
      $nb = New-Object System.Drawing.Bitmap(2000, 1200)
      $ng = [System.Drawing.Graphics]::FromImage($nb)
      $ng.Clear([System.Drawing.Color]::White)
      $nfont = New-Object System.Drawing.Font('Segoe UI', 30, [System.Drawing.FontStyle]::Regular)
      $ng.DrawString('DTX near zero capture row one', $nfont, [System.Drawing.Brushes]::Black, [single]40, [single]60)
      $ng.DrawString('DTX near zero capture row two', $nfont, [System.Drawing.Brushes]::Black, [single]40, [single]120)
      $ng.Dispose(); $nfont.Dispose()
      $nb.Save($nzPng, [System.Drawing.Imaging.ImageFormat]::Png); $nb.Dispose()
      $tN2 = & $stRun $nzPng '' 'nearzero.txt'
      $nzLines = @($tN2.Txt -split "`r?`n" | Where-Object { $_ -match '^L\d\d img-rect=' }).Count
      ST-Check 'e2e: a near-zero read on a large capture still shouts, names it an image, and offers the ladder' (
        ($tN2.Exit -eq 0) -and ($tN2.Txt -match 'WARN: image is 2000x1200') -and (-not ($tN2.Txt -match 'WARN: region')) -and
        ($tN2.Txt -match 'readability=0\.0[0-9]') -and ($tN2.Txt -match 'warn-below=0\.1') -and
        ($tN2.Txt -match '--scale tiled') -and ($nzLines -ge 1))
      Write-Output ("      readability pair: sparse exit=$($tS.Exit) shouted=" + $(if ($tS.Txt -match 'WARN:') { 'yes' } else { 'no' }) +
        " old-band shouted=" + $(if ($tSO.Txt -match 'WARN:') { 'yes' } else { 'no' }) + " nearzero-lines=$nzLines")
    } finally {
      Remove-Item -LiteralPath $ocDir -Recurse -Force -ErrorAction SilentlyContinue
    }
    # REGION-END ocr-file
  }
  $ocrFileEmitted = @($script:StRecord)
  $script:StRecord = $null
  ST-ReconcileRegion 'ocr-file' $ocrFileEmitted

  # ---------- unit: v1.5.5 (D-4) one OCR tail for every miss ----------
  $ot3 = Format-OcrSampleTail (@(
    [pscustomobject]@{ Text = 'alpha' }, [pscustomobject]@{ Text = 'beta' }, [pscustomobject]@{ Text = 'gamma' })) 8
  ST-Check 'unit: an OCR tail under the cap reports the total and says nothing is hidden' (
    $ot3 -ceq "OCR read 3 line(s) total: 'alpha', 'beta', 'gamma'")
  $otManyLines = @(1..11 | ForEach-Object { [pscustomobject]@{ Text = "L$_" } })
  $otMany = Format-OcrSampleTail $otManyLines 8
  # expected value is built as its own value first: `-ceq 'a' + 'b'` binds left to
  # right, i.e. ($x -ceq 'a') + 'b', and the assertion would compare a string.
  $otManyHead = ((1..8 | ForEach-Object { "'L{0}'" -f $_ }) -join ', ')
  $otManyWant = "OCR read 11 line(s) total: $otManyHead (+3 more lines not shown)"
  $otShown = (@([regex]::Matches($otMany, "'L[0-9]+'") | ForEach-Object { $_.Value }) | Sort-Object -Unique).Count
  ST-Check 'unit: an OCR tail over the cap names the hidden count, and the count is the real arithmetic' (
    $otMany -ceq $otManyWant -and $otShown -eq 8 -and $otMany.Contains('(+3 more'))
  ST-Check 'unit: an empty OCR read is reported as zero lines, never as a missing field' (
    (Format-OcrSampleTail @() 8) -ceq 'OCR read 0 line(s) total: ')
  ST-Check 'unit: a non-positive cap falls back to 8 instead of showing nothing' (
    (Format-OcrSampleTail $otManyLines 0) -ceq $otMany)

  # ---------- unit: CJK spacing that Windows OCR invents (built from code points
  # so this file stays pure ASCII) ----------
  $wen = [char]0x6587; $jian = [char]0x4EF6; $qing = [char]0x6E05; $dan = [char]0x5355
  $spaced = [string]$wen + ' ' + $jian + ' ' + $qing + ' ' + $dan
  $tight = [string]$wen + $jian + $qing + $dan
  ST-Check 'unit: Normalize-OcrText collapses CJK-CJK gaps' ((Normalize-OcrText $spaced) -eq $tight)
  ST-Check 'unit: Normalize-OcrText leaves English spacing alone' ((Normalize-OcrText 'a b c') -eq 'a b c')
  $cnLines = New-Object System.Collections.ArrayList
  [void]$cnLines.Add([pscustomobject]@{ Text = $spaced; X = 1; Y = 1; W = 40; H = 12 })
  ST-Check 'unit: natural CJK needle hits an OCR-spaced line' ((Find-OcrHits $cnLines ([string]$qing + $dan)).Count -eq 1)
  ST-Check 'unit: spaced CJK needle still hits (no regression)' ((Find-OcrHits $cnLines $spaced).Count -eq 1)
  # OCR renders a typed ASCII hyphen as U+2014 in terminal text; without folding,
  # every hyphenated --verify needle misses.
  $emdash = [string]('HELLO' + [char]0x2014 + 'VERIFY-TEST')
  ST-Check 'unit: dash confusables fold to ASCII hyphen' ((Normalize-OcrText $emdash) -eq 'HELLO-VERIFY-TEST')
  $dashLines = New-Object System.Collections.ArrayList
  [void]$dashLines.Add([pscustomobject]@{ Text = $emdash; X = 1; Y = 1; W = 90; H = 12 })
  ST-Check 'unit: hyphen needle hits an em-dash OCR line' ((Find-OcrHits $dashLines 'HELLO-VERIFY-TEST').Count -eq 1)
  # ---------- unit: OCR retry decision + normalization ----------
  # The old hardcoded 2200/1200 retry guard sat BELOW real window sizes, so
  # whole-window searches silently skipped the 2x pass while the miss message
  # claimed it ran (audit 2026-09-29b #1). Pin the engine-driven decision here.
  ST-Check 'unit: Test-OcrRetryFits - real-size windows retry' (
    (Test-OcrRetryFits 2361 1469 10000) -and (Test-OcrRetryFits 3840 2160 10000))
  ST-Check 'unit: Test-OcrRetryFits - boundary at engine limit' (
    (Test-OcrRetryFits 5000 5000 10000) -and -not (Test-OcrRetryFits 5001 100 10000) -and -not (Test-OcrRetryFits 6000 4000 10000))
  ST-Check 'unit: Test-OcrRetryFits - unknown engine limit means no retry' (-not (Test-OcrRetryFits 100 100 0))
  $fwComma = [string][char]0xFF0C
  $ocrDigits = "100 $fwComma 000 $fwComma 000"
  ST-Check 'unit: Normalize-OcrText folds fullwidth comma padding (100,000,000)' (
    (Find-OcrHits @([pscustomobject]@{ Text = $ocrDigits; X = 0; Y = 0; W = 1; H = 1 }) '100,000,000').Count -eq 1)

  # ---------- unit: tiled OCR planner + merge (v1.5.0 WP-1) ----------
  $pl = Get-OcrTilePlan 2482 1514 2.0 10000 64 16
  ST-Check 'tileplan: single tile when 2x fits the engine limit' ($pl.Error -eq '' -and $pl.Count -eq 1 -and $pl.Covered)
  $pl2 = Get-OcrTilePlan 6000 3000 2.0 10000 64 16
  ST-Check 'tileplan: oversized region tiles with full coverage' ($pl2.Error -eq '' -and $pl2.Count -gt 1 -and $pl2.Covered)
  $sizeOk = $true
  foreach ($t in $pl2.Tiles) { if (($t.W * 2) -gt 10000 -or ($t.H * 2) -gt 10000) { $sizeOk = $false } }
  ST-Check 'tileplan: every tile scaled stays within maxDim' $sizeOk
  $tw2 = $pl2.Tiles[0].W; $th2 = $pl2.Tiles[0].H
  $ovlOk = $true
  $ux = @($pl2.Tiles | ForEach-Object { $_.X } | Sort-Object -Unique)
  for ($i = 1; $i -lt $ux.Count; $i++) { if (($tw2 - ($ux[$i] - $ux[$i - 1])) -lt 64) { $ovlOk = $false } }
  $uy = @($pl2.Tiles | ForEach-Object { $_.Y } | Sort-Object -Unique)
  for ($i = 1; $i -lt $uy.Count; $i++) { if (($th2 - ($uy[$i] - $uy[$i - 1])) -lt 64) { $ovlOk = $false } }
  ST-Check 'tileplan: adjacent tiles overlap at least the requested 64px' $ovlOk
  # "any (w,h,scale,maxDim)" broadened: independent union math over several
  # shapes, plus per-tile size and per-adjacent-pair overlap on each of them.
  $plShapes = @(
    @(2482, 1514, 2.0, 10000, 64, 16),
    @(6000, 3000, 2.0, 10000, 64, 16),
    @(9000, 2000, 1.0, 10000, 64, 16),
    @(300, 300, 2.0, 4096, 64, 16),
    @(6100, 1700, 2.0, 10000, 64, 16)
  )
  $shapeOk = $true
  foreach ($cs in $plShapes) {
    $ps2 = Get-OcrTilePlan $cs[0] $cs[1] $cs[2] $cs[3] $cs[4] $cs[5]
    if ($ps2.Error) { $shapeOk = $false; continue }
    $tw2s = $ps2.Tiles[0].W; $th2s = $ps2.Tiles[0].H
    $sxs = @($ps2.Tiles | ForEach-Object { $_.X } | Sort-Object -Unique)
    $sys = @($ps2.Tiles | ForEach-Object { $_.Y } | Sort-Object -Unique)
    $cxs = ($sxs[0] -eq 0) -and (($sxs[$sxs.Count - 1] + $tw2s) -ge $cs[0])
    for ($k = 1; $k -lt $sxs.Count; $k++) { if (($sxs[$k] - $sxs[$k - 1]) -gt $tw2s) { $cxs = $false } }
    $cys = ($sys[0] -eq 0) -and (($sys[$sys.Count - 1] + $th2s) -ge $cs[1])
    for ($k = 1; $k -lt $sys.Count; $k++) { if (($sys[$k] - $sys[$k - 1]) -gt $th2s) { $cys = $false } }
    $ovS = $true
    for ($k = 1; $k -lt $sxs.Count; $k++) { if (($sxs[$k] - $sxs[$k - 1]) -gt ($tw2s - $cs[4])) { $ovS = $false } }
    for ($k = 1; $k -lt $sys.Count; $k++) { if (($sys[$k] - $sys[$k - 1]) -gt ($th2s - $cs[4])) { $ovS = $false } }
    $szS = $true
    foreach ($t2 in $ps2.Tiles) { if (($t2.W * $cs[2]) -gt $cs[3] -or ($t2.H * $cs[2]) -gt $cs[3]) { $szS = $false } }
    if (-not ($cxs -and $cys -and $ps2.Covered -and $ovS -and $szS)) { $shapeOk = $false }
  }
  ST-Check 'tileplan: coverage + size + overlap hold across shapes (independent union math)' $shapeOk
  $plX = Get-OcrTilePlan 6000 3000 2.0 10000 64 1
  ST-Check 'tileplan: over max-tiles refuses with the real count in Error' ($plX.Error -match 'needs \d+ tiles' -and $plX.Tiles.Count -eq 0)
  $plR = Get-OcrTilePlan 6000 3000 2.0 10000 64 16
  $plS = Get-OcrTilePlan 6000 3000 2.0 10000 64 16
  $det = ($plR.Count -eq $plS.Count)
  if ($det) { for ($i = 0; $i -lt $plR.Tiles.Count; $i++) { if ($plR.Tiles[$i].X -ne $plS.Tiles[$i].X -or $plR.Tiles[$i].Y -ne $plS.Tiles[$i].Y -or $plR.Tiles[$i].W -ne $plS.Tiles[$i].W -or $plR.Tiles[$i].H -ne $plS.Tiles[$i].H) { $det = $false } } }
  ST-Check 'tileplan: same args -> identical row-major order (index reproducible)' ($det -and $plR.Covered)
  $mk = { param($t, $x, $y) [pscustomobject]@{ Text = $t; X = $x; Y = $y; W = 100; H = 14 } }
  $tileA = @(& $mk 'SAME LINE' 100 200; & $mk 'OTHER' 10 20)
  $tileB = @(& $mk 'SAME LINE' 102 201)
  $tileC = @(& $mk 'SAME LINE' 110 200)
  $mrg = Merge-OcrTileLines @($tileA, $tileB, $tileC)
  ST-Check 'merge: 2px-overlap duplicate collapses, 10px distinct stays' ($mrg.Lines.Count -eq 3 -and $mrg.Duplicates -eq 1)

  # ---------- unit + lint: v2.2.0 plan doc section 3, the folded-long-payload receipt ----------
  # The judgement table. Each case feeds numbers of the same shape the IO pair produces, so
  # the RULE is provable offline; the IO pair itself is proven live by the fold fixture.
  $pvV = @{ VerbatimOk = $true; Threshold = 200; HeightMin = 8; PayloadChars = 12000; UiaBefore = 14; UiaAfter = 14; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'aaaa1111' }
  $pvOk = Get-PasteReceiptVerdict $pvV
  # The knob's DEFAULT is pinned too, and the boundary is measured against the shipped value
  # rather than a number copied into the test: a threshold nobody reads can be quietly set to
  # "never" and every other case in the table keeps passing.
  $pvThr = [int](Get-PasteFoldThreshold)
  $pvAt = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = $pvThr; HeightMin = (Get-PasteReceiptHeightMin); PayloadChars = $pvThr; UiaBefore = 14; UiaAfter = 15; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'aaaa1111' }
  $pvUnder = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = $pvThr; HeightMin = (Get-PasteReceiptHeightMin); PayloadChars = ($pvThr - 1); UiaBefore = 14; UiaAfter = 15; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'aaaa1111' }
  ST-Check 'unit: the shipped fold-threshold is one specific spoken number (200) - a default no check reads can be set to "never" while the whole table stays green' (
    ($pvThr -eq 200) -and ([int](Get-PasteReceiptHeightMin) -eq 8))
  ST-Check 'unit: a payload AT the fold-threshold engages the receipt route and one char under it does not (the boundary is the knob, measured against the shipped value)' (
    $pvAt.Ok -and (-not $pvUnder.Ok) -and $pvUnder.Detail.Contains('under fold-threshold'))
  ST-Check 'unit: paste receipt - a verbatim read-back wins outright and is never labelled a degradation' (
    $pvOk.Ok -and (-not $pvOk.Degraded) -and ($pvOk.Criterion -ceq 'verbatim-tail'))
  $pvShort = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 60; UiaBefore = 14; UiaAfter = 99; HeightBefore = 240; HeightAfter = 900; LinesBefore = 1; LinesAfter = 9; HashBefore = 'aaaa1111'; HashAfter = 'bbbb2222' }
  ST-Check 'unit: paste receipt - a SHORT payload whose body is not visible stays a failure even if the window threw a fit (a weak receipt must not excuse a small paste)' (
    (-not $pvShort.Ok) -and ($pvShort.Criterion -ceq 'verbatim-tail') -and $pvShort.Detail.Contains('under fold-threshold'))
  $pvKnob = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 0; HeightMin = 8; PayloadChars = 12000; UiaBefore = 14; UiaAfter = 99; HeightBefore = 240; HeightAfter = 900; LinesBefore = 1; LinesAfter = 9; HashBefore = 'aaaa1111'; HashAfter = 'bbbb2222' }
  ST-Check 'unit: paste receipt - fold-threshold=0 switches the receipt route off and NAMES the knob that did it (an inert knob is the fake-flag shape this repo has been bitten by)' (
    (-not $pvKnob.Ok) -and $pvKnob.Detail.Contains('fold-threshold=0'))
  $pvNodes = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 8556; UiaBefore = 14; UiaAfter = 15; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'aaaa1111' }
  ST-Check 'unit: paste receipt - one NEW ui automation node is enough on a long payload, and it is reported as the degraded criterion with the numbers it measured' (
    $pvNodes.Ok -and $pvNodes.Degraded -and ($pvNodes.Criterion -ceq 'uia-nodes') -and $pvNodes.Detail.Contains('nodes 14->15'))
  $pvGrow = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 12774; UiaBefore = -1; UiaAfter = -1; HeightBefore = 240; HeightAfter = 260; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'bbbb2222' }
  ST-Check 'unit: paste receipt - ui automation unreadable (both sides -1) still leaves the height leg, which must quote before and after' (
    $pvGrow.Ok -and ($pvGrow.Criterion -ceq 'grow-height') -and $pvGrow.Detail.Contains('h 240->260'))
  $pvTiny = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 12774; UiaBefore = 14; UiaAfter = 14; HeightBefore = 240; HeightAfter = 244; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'aaaa1111' }
  ST-Check 'unit: paste receipt - a 4px growth under the floor does NOT count as a receipt (a drifting rect must not be enough to pass)' (
    (-not $pvTiny.Ok) -and ($pvTiny.Criterion -ceq 'none-of-three'))
  $pvLines = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 12774; UiaBefore = 14; UiaAfter = 14; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 3; HashBefore = 'aaaa1111'; HashAfter = 'bbbb2222' }
  ST-Check 'unit: paste receipt - line count changed WITH a different pixel hash counts as content arriving (the chip replacing the body is exactly this shape)' (
    $pvLines.Ok -and ($pvLines.Criterion -ceq 'lines-changed') -and $pvLines.Detail.Contains('lines 5->3'))
  $pvPixel = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 12774; UiaBefore = 14; UiaAfter = 14; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'bbbb2222' }
  ST-Check 'unit: paste receipt - pixels moving alone is NOT a receipt (a blinking caret would otherwise pass every paste ever made)' (
    (-not $pvPixel.Ok) -and ($pvPixel.Criterion -ceq 'none-of-three'))
  $pvNone = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 12774; UiaBefore = 14; UiaAfter = 14; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'aaaa1111' }
  ST-Check 'unit: paste receipt - refusing names ALL THREE legs with what each one measured (a bare not-visible leaves the caller guessing whether the receipt route even ran)' (
    (-not $pvNone.Ok) -and $pvNone.Detail.Contains('nodes 14->14') -and $pvNone.Detail.Contains('h 240->240') -and $pvNone.Detail.Contains('lines 5->5'))
  # ---------- unit: v1.5.9/P-4b sparse-read hint - dual area bands, wording, synthetic pair, wiring ----------
  # C-plan: area >= 300000 px2 remains the floor; a small-area region (<500000 px2)
  # uses the relaxed 1.0 threshold while a large region uses 1.5. Both sides of
  # every boundary are asserted - a threshold with only a positive case has no teeth.
  ST-Check 'unit: sparse predicate fires on a large near-empty region (2000x1200, 0 lines)' (Test-SparseReadability 2000 1200 0 1.5)
  ST-Check 'unit: sparse predicate stays quiet on the same region densely read (60 lines)' (-not (Test-SparseReadability 2000 1200 60 1.5))
  ST-Check 'unit: sparse predicate never fires below the 300k px2 area floor (500x300, 0 lines)' (-not (Test-SparseReadability 500 300 0 1.5))
  ST-Check 'unit: sparse predicate 0 disables the hint entirely (huge region, 0 lines)' (-not (Test-SparseReadability 2000 1200 0 0))
  ST-Check 'unit: sparse predicate threshold is a strict less-than (exactly 1.5 lines/100k px2 stays quiet, one line less fires)' (
    (-not (Test-SparseReadability 2000 1200 36 1.5)) -and (Test-SparseReadability 2000 1200 35 1.5))
  ST-Check 'unit: sparse predicate relaxes the small-area band for a legal sparse dialog (749x540, 5 lines)' (-not (Test-SparseReadability 749 540 5 1.5))
  ST-Check 'unit: sparse predicate still warns on a truly masked large region (2000x1200, 2 lines)' (Test-SparseReadability 2000 1200 2 1.5)
  ST-Check 'unit: sparse predicate small-area band has a live boundary (749x540, 4 lines warns)' (Test-SparseReadability 749 540 4 1.5)
  # v2.9.0: read-text's OWN loud threshold moved from the band to the near-zero rule, because
  # the 489-capture survey showed 1.5 cuts through the mode of ordinary traffic (214 quiet reads
  # sit in [1.5,2.0) alone; 91 of 489 = 18.6% shouted) while every genuine failure shape sits far
  # lower. Both directions here, on the two shapes the survey actually produced - and the second
  # one asserts the OLD value too, so "quiet" cannot be explained by a broken predicate.
  ST-Check 'unit: the modal-scrim shape (2 lines on 1722x1597 = density 0.07) still shouts at the new 0.1 default' (
    (Test-SparseReadability 1722 1597 2 0.1))
  ST-Check 'unit: an ordinary sparse window (40 lines on 1722x1597 = density 1.45) is quiet at 0.1 and was NOT quiet at 1.5' (
    (-not (Test-SparseReadability 1722 1597 40 0.1)) -and (Test-SparseReadability 1722 1597 40 1.5))
  ST-Check 'unit: the small-area cap cannot lift a lowered threshold (0.1 on a 749x540 dialog warns only below 0.1)' (
    (Get-SparseReadPolicy ([long]749 * 540) 0.1).Threshold -eq 0.1 -and (-not (Test-SparseReadability 749 540 5 0.1)))
  # and the split itself must be visible in the source: exactly ONE command lowered its default.
  $mldLow = @($codeLines | Where-Object { $_ -match '\$minLineDensity = 0\.1\s*$' }).Count
  $mldBand = @($codeLines | Where-Object { $_ -match '\$minLineDensity = 1\.5\s*$' }).Count
  ST-Check 'lint: read-text alone dropped to the near-zero default; the two absence-claiming paths keep the band' (
    ($mldLow -eq 1) -and ($mldBand -eq 2))
  # the readability label must reach BOTH headers (file mode and screen mode) and be produced in
  # exactly one place, or one mode silently stops reporting its own quality. The token is
  # assembled at runtime: this scan line would otherwise match its own search string and the
  # count would be off by one forever (same self-evasion idiom as the badge lint).
  $rlTok = 'read' + 'Label'
  $rlSites = @($codeLines | Where-Object { $_.Contains($rlTok) -and $_ -notmatch '^\s*#' }).Count
  ST-Check 'lint: the readability label has one producer and reaches both read-text headers' ($rlSites -eq 4)
  if ($rlSites -ne 4) { Write-Output "      readability label sites: $rlSites (want 4: init + build + 2 headers)" }
  $srw = Build-SparseReadWarn 2482 1514 2 1.5
  ST-Check 'unit: sparse WARN wording names the size, the count, the modal/scrim suspicion and the escape hatch' (
    $srw.Contains('WARN: region is 2482x1514 but only 2 line(s) read') -and
    $srw.Contains('in-window modal/scrim, a loading veil, or a very low-contrast theme') -and
    $srw.Contains('Do NOT treat "not found" as "absent"') -and
    $srw.Contains('sparse-policy=large-area') -and $srw.Contains('active-threshold=1.5') -and
    $srw.Contains('min-line-density=1.5') -and $srw.Contains('--min-line-density 0 to silence'))
  # v2.8.0: the SAME producer must speak two dialects, because a file-mode read is not a
  # window. Both directions are asserted: a one-sided check ("says image") would also pass
  # if the word region simply vanished from the sentence.
  $srwImg = Build-SparseReadWarn 2482 1514 2 1.5 'image'
  ST-Check 'unit: the sparse WARN calls a stored capture an image and offers the subdivided re-read' (
    $srwImg.Contains('WARN: image is 2482x1514 but only 2 line(s) read') -and
    (-not $srwImg.Contains('region')) -and
    (-not $srwImg.Contains('window')) -and
    $srwImg.Contains('mostly graphics') -and
    $srwImg.Contains('--scale tiled') -and
    $srwImg.Contains('Do NOT treat "not found" as "absent"') -and
    $srwImg.Contains('sparse-policy=large-area'))
  ST-Check 'unit: the default subject still speaks screen mode (region + window wording intact)' (
    $srw.Contains('WARN: region is 2482x1514') -and (-not $srw.Contains('WARN: image is')))

  # v2.8.0: the engine's own dimension limit (10000 measured on this box) sits far above any
  # screenshot, so the live road's "tile only when too big" rule yields ONE tile for a stored
  # image and the flag would be decorative. The override has to actually subdivide - and it
  # must never be able to RAISE the limit, or a tile would exceed what the engine accepts.
  $gtmSmall = Get-OcrTilePlan 920 520 2.0 10000 64 16
  $gtmCut = Get-OcrTilePlan 920 520 2.0 (Get-FileTileMaxDim 920 520 2.0) 64 16
  ST-Check 'unit: file tiling halves the long side so one capture becomes several reads (real limit gives 1)' (
    ($gtmSmall.Count -eq 1) -and ($gtmCut.Count -ge 2) -and (-not $gtmSmall.Error) -and (-not $gtmCut.Error))
  $gtmWide = Get-FileTileMaxDim 400 3000 2.0
  $gtmWidePlan = Get-OcrTilePlan 400 3000 2.0 $gtmWide 64 64
  $gtmOver = @($gtmWidePlan.Tiles | Where-Object { ($_.W * 2) -gt 10000 -or ($_.H * 2) -gt 10000 })
  ST-Check 'unit: file tiling cuts the LONGER side and never asks for a tile above the engine limit' (
    ($gtmWide -eq 3000) -and ((Get-FileTileMaxDim 0 0 0) -ge 32) -and
    (-not $gtmWidePlan.Error) -and (@($gtmWidePlan.Tiles).Count -ge 2) -and (@($gtmOver).Count -eq 0))
  # v2.8.1: the empty-read floor is its own producer, and the boundary must be the one the
  # measurement asked for. 1040x220 = 228,800 px2 is the REAL capture that v2.8.0's retry
  # skipped because it borrowed the WARN band - it must be inside the new floor, and a chip
  # small enough that "no text" is the honest answer must stay outside.
  ST-Check 'unit: empty-read predicate fires on the 228,800 px2 capture the WARN band is above, and stays off a 100x100 chip' (
    (Test-EmptyReadSuspect 1040 220) -and (Get-EmptyReadAreaFloor -eq 30000) -and
    (-not (Test-EmptyReadSuspect 100 100)) -and (Test-EmptyReadSuspect 173 174))
  $qrA = Get-QuadrantRects 920 520 64
  $qrOdd = Get-QuadrantRects 1001 77 64
  $qrBad = @()
  foreach ($r in @($qrA.Rects + $qrOdd.Rects)) {
    if ($r.X -lt 0 -or $r.Y -lt 0 -or $r.Width -lt 1 -or $r.Height -lt 1) { $qrBad += 'shape' }
  }
  ST-Check 'unit: quadrant crops cover the image, stay inside it, and overlap on the inner edges' (
    ($qrA.Count -eq 4) -and (@($qrBad).Count -eq 0) -and
    (@($qrA.Rects | Where-Object { ($_.X + $_.Width) -le 920 -and ($_.Y + $_.Height) -le 520 }).Count -eq 4) -and
    ((@($qrA.Rects | Where-Object { $_.X -gt 0 })[0]).X -eq (460 - 64)) -and
    ($qrOdd.Count -eq 4) -and ((@($qrOdd.Rects | Where-Object { $_.Y -eq 0 }).Count) -eq 2) -and
    ((Get-QuadrantRects 0 0 0).Error -ne ''))
  # the overlap must never be able to produce a zero-width crop on a narrow image
  $qrThin = Get-QuadrantRects 300 20 64
  ST-Check 'unit: a crop overlap larger than the image is clamped, not turned into a zero-width tile' (
    ($qrThin.Count -eq 4) -and (@($qrThin.Rects | Where-Object { $_.Width -lt 1 -or $_.Height -lt 1 }).Count -eq 0))

  # Synthetic-bitmap two-state pair (the task order's acceptance). Memory-only canvases:
  # no window is created and no screen is captured, so the pair runs in the OFFLINE gate.
  # v4.1.3 (external review B): "catch-guarded" used to mean the caught error was fed to the
  # assertion as a FAIL condition, so an engine that cannot reach the recognizer reported a
  # product failure for a missing capability - against the contract this file states at the
  # read-text --file check ("On a box with no OCR language pack it SKIPS with a reason").
  # The pair is now gated on the same probe the live family uses, and the region accounts
  # for itself by name, so the total cannot move between machines.
  $script:StRecord = New-Object System.Collections.ArrayList
  if ($ocrPackTag -eq '') {
    ST-SkipRegion 'ocr-synthetic' 'no OCR language pack / recognizer unreachable from this engine - the bitmap road cannot be measured, so this is not a regression'
  } else {
  # REGION-BEGIN ocr-synthetic
  $srGrayErr = ''
  $srGray = New-Object System.Drawing.Bitmap(2000, 1200)
  $sgGray = [System.Drawing.Graphics]::FromImage($srGray)
  $sgGray.Clear([System.Drawing.Color]::FromArgb(128, 128, 128))
  $sgGray.Dispose()
  $srGrayLines = @()
  try { $srGrayLines = @((Invoke-OcrBitmap $srGray).Lines) } catch { $srGrayErr = $_.Exception.Message }
  ST-Check 'unit: synthetic 2000x1200 pure-gray bitmap OCRs to 0 lines and trips the sparse predicate' (
    (-not $srGrayErr) -and @($srGrayLines).Count -eq 0 -and (Test-SparseReadability 2000 1200 @($srGrayLines).Count 1.5))
  if ($srGrayErr) { Write-Output "      OCR unavailable: $srGrayErr" }
  $srDenseErr = ''
  $srDense = New-Object System.Drawing.Bitmap(2000, 1200)
  $sgDense = [System.Drawing.Graphics]::FromImage($srDense)
  $sgDense.Clear([System.Drawing.Color]::White)
  $fntD = New-Object System.Drawing.Font('Consolas', 10, [System.Drawing.FontStyle]::Regular)
  $brsD = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::Black)
  for ($sd = 0; $sd -lt 60; $sd++) { $sgDense.DrawString("DTX dense readability row $sd of 60", $fntD, $brsD, [single]10, [single](8 + $sd * 19)) }
  $sgDense.Dispose(); $fntD.Dispose(); $brsD.Dispose()
  $srDenseLines = @()
  try { $srDenseLines = @((Invoke-OcrBitmap $srDense).Lines) } catch { $srDenseErr = $_.Exception.Message }
  ST-Check 'unit: synthetic 2000x1200 60-row bitmap reads dense enough to stay quiet (measured, not assumed)' (
    (-not $srDenseErr) -and @($srDenseLines).Count -ge 36 -and (-not (Test-SparseReadability 2000 1200 @($srDenseLines).Count 1.5)))
  if ($srDenseErr) { Write-Output "      OCR unavailable: $srDenseErr" }
  Write-Output "      synthetic sparse pair: gray=$(@($srGrayLines).Count) line(s), dense=$(@($srDenseLines).Count) line(s) (density $([math]::Round(@($srDenseLines).Count / 24.0, 2)) lines per 100k px2, threshold 1.5)"
  $srGray.Dispose(); $srDense.Dispose()
  # REGION-END ocr-synthetic
  }
  $ocrSynEmitted = @($script:StRecord)
  $script:StRecord = $null
  ST-ReconcileRegion 'ocr-synthetic' $ocrSynEmitted

  # Wiring: the hint must stay attached to all negative paths, the wording must
  # keep its single producer, and the tuning flag must stay reachable everywhere it is
  # documented (Split-Target + both read commands). v1.10.0 adds the 4th consumer: the
  # challenge-probe none-path note (the task order names it as P-4's existing behaviour
  # carried over), so the pinned count moves 4 -> 5.
  # v2.8.0 moved 5 -> 6: the file-mode auto-retry consulted THIS predicate rather than
  # inventing a second area floor. v2.8.1 moves it back 6 -> 5, and the reason is a
  # measurement, not a tidy-up: re-running the two real captures that motivated the retry
  # showed that retry recovered NEITHER, and the 1040x220 one (228,800 px2) never even
  # reached it, because the WARN band's 300k floor sits ABOVE that image. An EMPTY read is
  # suspicious at a far smaller size than a SPARSE one, so emptiness now has its own
  # producer (Get-EmptyReadAreaFloor, pinned by name and value in its own unit check).
  # This lint going DOWN therefore means the two rules were SPLIT, not that a negative path
  # lost its hint - the five sites below are the same five that carried it before v2.8.0.
  $srSites = @()
  for ($sri = 0; $sri -lt $codeLines.Count; $sri++) {
    if ($sri -ge $j5ProdStart -and $sri -lt $j5ProdEnd) { continue }
    if ($codeLines[$sri] -match '^\s*#') { continue }
    if ($codeLines[$sri].Contains('Test-SparseReadability')) { $srSites += ($sri + 1) }
  }
  ST-Check 'lint: the sparse predicate is wired on all negative paths (exactly 5 sites: 1 def + read-text + find-text + expect + challenge-probe)' (@($srSites).Count -eq 5)
  if (@($srSites).Count -ne 5) { Write-Output "      sparse predicate sites: $(@($srSites) -join ', ')" }
  # and the empty-read rule must have exactly one floor producer too, so a second literal
  # cannot quietly appear somewhere else and disagree with the one the report prints.
  $erSites = @()
  for ($sri = 0; $sri -lt $codeLines.Count; $sri++) {
    if ($sri -ge $j5ProdStart -and $sri -lt $j5ProdEnd) { continue }
    if ($codeLines[$sri] -match '^\s*#') { continue }
    if ($codeLines[$sri].Contains('Get-EmptyReadAreaFloor')) { $erSites += ($sri + 1) }
  }
  ST-Check 'lint: the empty-read floor has one producer and two named consumers (def + predicate + header)' (@($erSites).Count -eq 3)
  if (@($erSites).Count -ne 3) { Write-Output "      empty-read floor sites: $(@($erSites) -join ', ')" }
  $srBuildSites = @()
  for ($sri = 0; $sri -lt $codeLines.Count; $sri++) {
    if ($sri -ge $j5ProdStart -and $sri -lt $j5ProdEnd) { continue }
    if ($codeLines[$sri] -match '^\s*#') { continue }
    if ($codeLines[$sri].Contains('Build-SparseReadWarn')) { $srBuildSites += ($sri + 1) }
  }
  ST-Check 'lint: the sparse WARN has one producer and three consumers (exactly 4 sites)' (@($srBuildSites).Count -eq 4)
  if (@($srBuildSites).Count -ne 4) { Write-Output "      sparse WARN sites: $(@($srBuildSites) -join ', ')" }
  $srFlagSites = @()
  for ($sri = 0; $sri -lt $codeLines.Count; $sri++) {
    if ($sri -ge $j5ProdStart -and $sri -lt $j5ProdEnd) { continue }
    if ($codeLines[$sri] -match '^\s*#') { continue }
    if ($codeLines[$sri].Contains("-eq '--min-line-density'")) { $srFlagSites += ($sri + 1) }
  }
  ST-Check 'lint: --min-line-density is parsed by Split-Target AND both read commands (exactly 3 sites)' (@($srFlagSites).Count -eq 3)
  if (@($srFlagSites).Count -ne 3) { Write-Output "      min-line-density parse sites: $(Format-SourceLineList @($srFlagSites))" }

  # ---------- unit: v1.5.9 P-2 needle sub-span aiming - pure mapping + synthetic line ----------
  # Pure mapping units first: the CJK case reproduces the real incident (two tabs OCR'd
  # as one line; the needle is the left tab), the Latin case pins the proportional math.
  $gaCjk = Get-NeedleAimX ([string]::Join(' ', @([char]0x6267, [char]0x884C, [char]0x5386, [char]0x53F2, [char]0x4EFB, [char]0x52A1, [char]0x6A21, [char]0x677F))) 100 800 ([string]::Join('', @([char]0x6267, [char]0x884C, [char]0x5386, [char]0x53F2)))
  ST-Check 'unit: needle aim maps the CJK needle onto its own sub-span (the two-tab incident: left tab, not the gap)' (
    $gaCjk.Matched -and $gaCjk.AimX -eq 300 -and $gaCjk.SpanStart -eq 0 -and $gaCjk.SpanEnd -eq 4 -and $gaCjk.NormLen -eq 8)
  $gaLat = Get-NeedleAimX 'AAA BBB' 0 700 'BBB'
  ST-Check 'unit: needle aim maps a Latin needle proportionally (BBB span 4-7 of 7 -> centre 550)' (
    $gaLat.Matched -and $gaLat.AimX -eq 550 -and $gaLat.SpanStart -eq 4 -and $gaLat.SpanEnd -eq 7)
  ST-Check 'unit: needle aim matches case-insensitively' ((Get-NeedleAimX 'AAA BBB' 0 700 'aaa').Matched)
  $gaMiss = Get-NeedleAimX 'AAA BBB' 0 700 'ZZZ'
  ST-Check 'unit: needle aim reports a miss and hands back the line centre (honest fallback)' (
    (-not $gaMiss.Matched) -and $gaMiss.AimX -eq 350 -and ((Get-NeedleAimX 'AAA BBB' 0 700 '').Matched -eq $false))

  # Synthetic merged-line pair (the task order's acceptance, one deviation documented in
  # the iteration log): the task order sketched two drawn blocks "AAA" / "BBB", but the
  # engine reads Latin letter runs with NON-deterministic inserted spaces ('AAAB BB' vs
  # 'AAA BBB' on identical bitmaps - measured while building this unit), so a Latin
  # needle's contiguity - and therefore its aim - would flake. The row is therefore drawn
  # as ONE string with an ideographic-space gap (U+3000): CJK inter-glyph spaces are
  # folded by Normalize-OcrText BY DESIGN, so both needles always match after
  # normalization, whatever the engine inserts. Assertions are stated on the READ rect
  # and hold for either normalization length (6 = gap folded, 7 = gap kept as a char):
  # the row merges into ONE OCR line (the incident shape), the hit count stays 1
  # (J-05 granularity), each needle's aim moves to its own side of the line centre by at
  # least 1/7 of the line width - i.e. the OLD line-centre behaviour clicked a materially
  # different, wrong point - and the needle/line ratio stays in NOTE territory.
  # v4.1.3 (external review B): gated like the synthetic pair above - and the three checks
  # nested under the merged-line precondition now report SKIP when it does not hold,
  # instead of vanishing (measured: pwsh 7 lost exactly those three on top of the pair).
  $script:StRecord = New-Object System.Collections.ArrayList
  if ($ocrPackTag -eq '') {
    ST-SkipRegion 'ocr-merged' 'no OCR language pack / recognizer unreachable from this engine - the merged-line shape cannot be measured, so this is not a regression'
  } else {
  # REGION-BEGIN ocr-merged
  $gaBmp = New-Object System.Drawing.Bitmap(460, 100)
  $gaG = [System.Drawing.Graphics]::FromImage($gaBmp)
  $gaG.Clear([System.Drawing.Color]::White)
  $gaFnt = New-Object System.Drawing.Font('Microsoft YaHei UI', 24, [System.Drawing.FontStyle]::Regular)
  $gaBrs = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::Black)
  $gaL = [string]::Join('', @([char]0x6728, [char]0x6C34, [char]0x706B))
  $gaR = [string]::Join('', @([char]0x571F, [char]0x91D1, [char]0x7530))
  $gaRow = $gaL + [string][char]0x3000 + $gaR
  $gaG.DrawString($gaRow, $gaFnt, $gaBrs, [single]40, [single]25)
  $gaG.Dispose(); $gaFnt.Dispose(); $gaBrs.Dispose()
  $gaErr = ''
  $gaLines = @()
  try { $gaLines = @((Invoke-OcrBitmap $gaBmp).Lines) } catch { $gaErr = $_.Exception.Message }
  $gaMerged = @($gaLines | Where-Object { (($_.Text -replace '\s', '') -replace [string][char]0x3000, '') -like ('*' + $gaL + $gaR + '*') })
  ST-Check 'unit: synthetic two-block CJK row OCRs as ONE merged line (the incident shape, engine-verified)' (
    (-not $gaErr) -and @($gaMerged).Count -eq 1)
  if ($gaErr) { Write-Output "      OCR unavailable: $gaErr" }
  if (@($gaMerged).Count -ne 1) { Write-Output ("      merged-line diagnostics: " + ((@($gaLines | ForEach-Object { "'" + $_.Text + "'@" + $_.X + "+" + $_.W })) -join ' | ')) }
  if (@($gaMerged).Count -eq 1) {
    $gaHit = $gaMerged[0]
    $gaHitsL = Find-OcrHits @($gaLines) $gaL
    ST-Check 'unit: the merged row is still exactly ONE hit for the left needle (J-05 line granularity intact)' (@($gaHitsL).Count -eq 1)
    $gaAimL = Get-NeedleAimX "$($gaHit.Text)" $gaHit.X $gaHit.W $gaL
    $gaAimR = Get-NeedleAimX "$($gaHit.Text)" $gaHit.X $gaHit.W $gaR
    $gaCentre = $gaHit.X + [int]($gaHit.W / 2)
    $gaW7 = [int]($gaHit.W / 7)
    ST-Check 'unit: both needles aim into their own half, each at least 1/7 line-width away from the old line-centre point' (
      $gaAimL.Matched -and $gaAimR.Matched -and ($gaAimL.AimX -lt $gaCentre) -and ($gaCentre -lt $gaAimR.AimX) -and
      (($gaCentre - $gaAimL.AimX) -gt $gaW7) -and (($gaAimR.AimX - $gaCentre) -gt $gaW7))
    ST-Check 'unit: the merged line is much wider than either needle, so the wider-than-needle NOTE condition holds' (
      ((($gaAimL.SpanEnd - $gaAimL.SpanStart) / $gaAimL.NormLen) -le 0.6) -and
      ((($gaAimR.SpanEnd - $gaAimR.SpanStart) / $gaAimR.NormLen) -le 0.6))
    Write-Output "      synthetic aim pair: line rect=($($gaHit.X),$($gaHit.Y),$($gaHit.W)x$($gaHit.H)) text='$($gaHit.Text)' normLen=$($gaAimL.NormLen) aimL=$($gaAimL.AimX) aimR=$($gaAimR.AimX) lineCentre=$gaCentre"
  } else {
    # v4.1.3 (external review B): these three sat behind a precondition and used to be
    # skipped from EXISTING when it did not hold - the run got shorter instead of narrower,
    # and that is where a third of the missing 24 went. They now account for themselves.
    ST-Skip 'unit: the merged row is still exactly ONE hit for the left needle (J-05 line granularity intact)' 'the merged-line precondition did not hold - there is no single line to aim at'
    ST-Skip 'unit: both needles aim into their own half, each at least 1/7 line-width away from the old line-centre point' 'the merged-line precondition did not hold - there is no single line to aim at'
    ST-Skip 'unit: the merged line is much wider than either needle, so the wider-than-needle NOTE condition holds' 'the merged-line precondition did not hold - there is no single line to aim at'
  }
  $gaBmp.Dispose()
  # REGION-END ocr-merged
  }
  $ocrMergedEmitted = @($script:StRecord)
  $script:StRecord = $null
  ST-ReconcileRegion 'ocr-merged' $ocrMergedEmitted

  $aimSites = @()
  for ($gai = 0; $gai -lt $codeLines.Count; $gai++) {
    if ($gai -ge $j5ProdStart -and $gai -lt $j5ProdEnd) { continue }
    if ($codeLines[$gai] -match '^\s*#') { continue }
    if ($codeLines[$gai].Contains('Get-NeedleAimX')) { $aimSites += ($gai + 1) }
  }
  ST-Check 'lint: find-click wires the needle sub-span aiming (exactly 2 sites: 1 def + 1 call)' (@($aimSites).Count -eq 2)
  if (@($aimSites).Count -ne 2) { Write-Output "      needle aim sites: $(@($aimSites) -join ', ')" }
  $aimFlagSites = @()
  for ($gai = 0; $gai -lt $codeLines.Count; $gai++) {
    if ($gai -ge $j5ProdStart -and $gai -lt $j5ProdEnd) { continue }
    if ($codeLines[$gai] -match '^\s*#') { continue }
    if ($codeLines[$gai].Contains('--aim-line')) { $aimFlagSites += ($gai + 1) }
  }
  ST-Check 'lint: --aim-line has its table entry, handler read, usage flag and echo note (exactly 4 code sites; help text is the D-1 lint''s source, not this scan)' (@($aimFlagSites).Count -eq 4)
  if (@($aimFlagSites).Count -ne 4) { Write-Output "      aim-line sites: $(Format-SourceLineList @($aimFlagSites))" }

}

# lib/selftest-flags-grammar.ps1 - family flags-grammar of the selftest section, lifted out of
# lib/selftest.ps1 by A-14i (A-beta). Bodies are byte-identical to what the section carried.
# Fourteen banners in six gathered pieces: numeric arguments failing readably, menu-pick parser and
# its target predicate, the same hole elsewhere in the dispatcher, the chrome family promises, flag
# reachability, Strip-OwnFlags, the sibling-flag hint, bool-flag shared routing, the auto-grid
# decision, miss tails and premises, truncation self-report, and the six "do not lose" contracts.
# State arrives only through $Ctx and lint (A-14b) names anything that reaches past it. Gathering
# sixteen hundred lines of scatter into one function reorders the section; the card counts that by
# name and position. The clipboard-input CALL statement (1750..1752) is deliberately left in the
# orchestrator - a call belongs to the orchestration, not to whichever body happens to precede it.
function Invoke-SelftestFamily-FlagsGrammar($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $src = [string]$Ctx['src']
  $codeLines = $Ctx['codeLines']
  $clCount = $Ctx['clCount']
  $code = $Ctx['code']
  $j5ProdStart = $Ctx['j5ProdStart']
  $j5ProdEnd = $Ctx['j5ProdEnd']
  # A-15: the case-shape gate needs the parse of the whole aggregate (the AST says what the switch
  # really has) and the two counts the other gates print, so the comparison is a cross-check and not
  # a fourth scan invented beside three that already exist.
  $j5SelfParsed = $Ctx['j5SelfParsed']
  $srcLines = $Ctx['srcLines']
  $gaCasesCount = $Ctx['gaCasesCount']
  $hCaseStarts = $Ctx['hCaseStarts']

  # ---------- unit: v1.5.2 R-12 numeric arguments fail readably ----------
  # Before: 'click abc def' surfaced the .NET binder message (Cannot convert value
  # "abc" to type "System.Int32") - true but not an instruction. One table drives
  # a pre-flight check so the family cannot split into "some nice, some internals".
  ST-Check 'unit: int args - valid pixels pass the gate' (
    (Test-IntArgs 'click' @('500', '600')) -and (Test-IntArgs 'rect' @('0', '0', '10', '10')))
  ST-Check 'unit: int args - negative coordinates are legal (multi-monitor)' (
    Test-IntArgs 'move' @('-32000', '-32000'))
  $ia1 = ''
  try { [void](Test-IntArgs 'click' @('abc', 'def')) } catch { $ia1 = $_.Exception.Message }
  ST-Check 'unit: int args - a bad coordinate gives an instruction, not .NET noise' (
    $ia1 -like "*must be a whole number of screen pixels*" -and $ia1 -notlike '*System.Int32*' -and $ia1 -like '*usage: click*')
  Write-Output "      int-arg message: $ia1"
  $ia2 = ''
  try { [void](Test-IntArgs 'move' @('12.5', '20')) } catch { $ia2 = $_.Exception.Message }
  ST-Check 'unit: int args - a fractional coordinate is refused with the same shape' (
    $ia2 -like "*got '12.5'*" -and $ia2 -notlike '*System.Int32*')
  $ia3 = ''
  try { [void](Test-IntArgs 'rect' @('0', '0', '3840')) } catch { $ia3 = $_.Exception.Message }
  ST-Check 'unit: int args - a missing coordinate says which one' ($ia3 -like '*missing argument #4*')
  ST-Check 'unit: int args - flags anywhere disable the positional gate (click --to X 500 600 stays legal)' (
    (Test-IntArgs 'click' @('--to', 'Notepad', '500', '600')) -and (Test-IntArgs 'relclick' @('sel', '--x', '1')))
  ST-Check 'unit: int args - commands with no declared numeric shape are untouched' (
    (Test-IntArgs 'focus' @('Notepad')) -and (Test-IntArgs 'wins' @()))
  # NOTE the foreach: 'Get-IntArgSpec a, Get-IntArgSpec b' would pass ONE array
  # argument to the first call instead of two calls (same family of trap as R-01)
  $iaNamed = @('rect', 'zoom', 'color-at', 'find-color', 'assert-color', 'move', 'click', 'rclick', 'dblclick', 'drag', 'hover', 'wheel', 'relclick', 'win-move', 'win-resize', 'imgclick', 'unmap', 'press-down', 'drag-to', 'press-up')
  $iaFound = 0
  foreach ($c in $iaNamed) { $sp = Get-IntArgSpec $c; if ($null -ne $sp) { $iaFound++ } }
  ST-Check 'unit: int args - the table covers every coordinate command (>= 20)' ($iaFound -ge 20)
  Write-Output "      int-arg table entries: $iaFound of $($iaNamed.Count)"


  # One grammar for every needle-consuming command: bare token, --needle <text>,
  # and unknown --xxx must THROW (never join the search). There is deliberately
  # NO bare -- terminator: powershell.exe swallows it at its own parameter-binding
  # layer before this parser runs, so exercising it in a test would be a green
  # light on a path no user can reach (it was implemented, measured unreachable,
  # and removed again).
  $nt1 = Resolve-NeedleToken 'QXNEEDLE'
  ST-Check 'unit: grammar - bare positional token is literal' ($nt1.Kind -ceq 'literal')
  $nt3 = Resolve-NeedleToken '--needle'
  ST-Check 'unit: grammar - --needle is the explicit form' ($nt3.Kind -ceq 'explicit')
  $nt4 = Resolve-NeedleToken '--expct'
  ST-Check 'unit: grammar - unknown flag is refused, not searched' ($nt4.Kind -ceq 'unknown')
  $nt7 = Resolve-NeedleToken '--'
  ST-Check 'unit: grammar - a lone -- is not a supported terminator (so it throws)' ($nt7.Kind -ceq 'unknown')
  $nt6 = Resolve-NeedleToken '-32000'
  ST-Check 'unit: grammar - a single-dash value token is not treated as a flag' ($nt6.Kind -ceq 'literal')
  $err6 = Get-NeedleFlagError 'find-text' '--expct'
  ST-Check 'unit: grammar - the refusal names exactly one escape route (--needle)' (
    $err6 -like '*unknown flag*' -and $err6 -like '*--needle*' -and $err6 -notlike '*terminator*')
  # the grammar must be wired into every loop that takes a needle - counting the
  # throw sites is the anti-drift nail (find-text/read-text/assert-text/menu-pick
  # each throw with their own command name; Split-Target covers click/type/keys/
  # paste/paste-file/find-click style commands with the shared message)
  $grammarSites = ([regex]::Matches($code, "unknown flag '")).Count
  ST-Check 'unit: grammar - every needle loop throws on an unknown flag (>= 5 sites)' ($grammarSites -ge 5)
  # nothing may half-implement the terminator again (branch or state variable).
  # The patterns are BUILT by concatenation so this line cannot match itself -
  # an earlier version counted its own pattern text and went red on a clean file.
  $termPat = "-eq '" + '--' + "'"
  $statePat = 'lit' + 'All'
  ST-Check 'unit: grammar - no -- terminator branch survives in the source' (
    ([regex]::Matches($code, [regex]::Escape($termPat))).Count -eq 0 -and ([regex]::Matches($code, $statePat)).Count -eq 0)
  Write-Output "      needle grammar refusal sites in source: $grammarSites"

  # ---------- v3.1.0 (P-06): menu-pick's extracted parser, four directions ----------
  $mp6Good = Resolve-MenuPickArgs @('Some Menu', 'File', '--expect', 'Done', '--timeout', '2.5')
  ST-Check 'unit (P-06): Resolve-MenuPickArgs keeps the documented defaults and reads a trailing operand when one is there' (
    (@($mp6Good.Words).Count -eq 2) -and ($mp6Good.Expect -eq 'Done') -and ([double]$mp6Good.TimeoutSec -eq 2.5) -and ($mp6Good.IntervalMs -eq 300))
  $mp6Err = ''
  try { $null = Resolve-MenuPickArgs @('Some Menu', 'File', '--expect') } catch { $mp6Err = "$($_.Exception.Message)" }
  ST-Check 'unit (P-06): a flag that lost its operand is REFUSED by name instead of binding $null (the old shape dropped the expectation and reported green)' (
    ($mp6Err -like '*--expect needs a value*') -and ($mp6Err -like '*silently dropped*'))
  $mp6Err2 = ''
  try { $null = Resolve-MenuPickArgs @('Some Menu', 'File', '--timeout', 'soon') } catch { $mp6Err2 = "$($_.Exception.Message)" }
  ST-Check 'unit (P-06): menu-pick --timeout goes through Read-FlagNumber (a non-number names the flag, no raw cast error)' (
    ($mp6Err2 -like '*--timeout*') -and ($mp6Err2 -like '*soon*'))
  $mp6Err3 = ''
  try { $null = Resolve-MenuPickArgs @('Some Menu', 'File', '--tolerence', '3') } catch { $mp6Err3 = "$($_.Exception.Message)" }
  ST-Check 'unit (P-06): an unknown --xxx in menu-pick is refused through the shared message, not fed to the positional words' (
    ($mp6Err3 -like '*--tolerence*') -and ($mp6Err3.Length -gt 0))
  # ---------- v3.1.0 (P-06): the same hole elsewhere - a family lint over the dispatcher ----------
  # Every hand-written `while ($i -lt $Rest.Count)` loop must refuse an unknown --xxx BEFORE the
  # else that pushes it into the positional words. find-color / assert-color / wait-stable did not
  # (measured: `--tolerence 30` was swallowed as a positional word and the command ran with the
  # default tolerance, exit 0). The loop COUNT is asserted too: a scan that sees nothing must fail.
  $hfLoops = 0; $hfBad = @()
  for ($hfi = 0; $hfi -lt $clCount; $hfi++) {
    if ("$($codeLines[$hfi])" -match 'while \(\$i -lt \$Rest\.Count\) \{') {
      $hfLoops++
      # The window is the loop itself, not a fixed line count: find-text refuses unknown flags
      # fourteen lines into its chain, so a 9-line lookahead reported an honest command as an
      # offender (measured). The loop's closing brace sits at six spaces in this file's style.
      $hfEnd = $hfi
      for ($hfj = $hfi + 1; $hfj -lt $clCount; $hfj++) {
        if ("$($codeLines[$hfj])" -match '^\s{6}\}\s*$') { $hfEnd = $hfj; break }
      }
      $hfWin = (@($codeLines[$hfi..$hfEnd]) -join "`n")
      if ($hfWin.Contains('[void]$words.Add($Rest[$i])') -and (-not $hfWin.Contains("-like '--*'"))) { $hfBad += ($hfi + 1) }
    }
  }
  ST-Check 'lint (P-06): no hand-written dispatcher flag loop swallows an unknown --xxx (loops-seen floor makes an empty scan fail)' (
    ($hfLoops -ge 3) -and (@($hfBad).Count -eq 0))
  Write-Output ('      flag loops: seen=' + $hfLoops + ' offenders=[' + (@($hfBad) -join ' ') + ']')
  # ---------- v3.1.0 (P-06): the chrome family's own promises ----------
  # v4.4.0 (A-15): this command's code may live in its handler now, so the promise is checked against
  # the command's code (case plus handler). The old scan read a pure move as a missing promise.
  $ccBody = Get-CommandCodeText $codeLines 'chrome-click'
  ST-Check 'lint (P-06): chrome-click carries the two things its comment now claims - a hit-window echo before the click and the audit line' (
    ($ccBody.Contains('Invoke-HitWindowCheck $cx $cy')) -and ($ccBody.Contains('Log-Action')) -and (-not $ccBody.Contains('applies verbatim')))
  # v4.4.0 (A-15): this command's code may live in its handler now, so the promise is checked against
  # the command's code (case plus handler). The old scan read a pure move as a missing promise.
  $crBody = Get-CommandCodeText $codeLines 'chrome-read'
  ST-Check 'lint (P-06): chrome-read refuses a missing selector instead of reading whichever tab is first (its siblings refuse)' (
    $crBody.Contains('usage: chrome-read <sel>'))
  # ---------- lint: v1.5.5 (A-4) a flag must be REACHABLE, not just parsed ----------
  # Why this exists (D-1): hover --dwell, drag --steps/--hold and find-click --index
  # were all documented in help AND parsed in their handler - but the parsing ran after
  # Split-Target had already refused the token, so every one of them was unreachable and
  # 297 green selftest checks never noticed. Documented-vs-reachable is a shape no unit
  # test of the parser can see, so the dispatcher source itself gets scanned here.
  $d1CaseStarts = @{}
  $d1FnStart = -1; $d1FnEnd = $codeLines.Count
  for ($i = 0; $i -lt $codeLines.Count; $i++) { if ($codeLines[$i] -match '^function Invoke-DesktopCommand') { $d1FnStart = $i; break } }
  if ($d1FnStart -ge 0) {
    for ($i = $d1FnStart + 1; $i -lt $codeLines.Count; $i++) { if ($codeLines[$i] -match '^function ') { $d1FnEnd = $i; break } }
    for ($i = $d1FnStart; $i -lt $d1FnEnd; $i++) {
      if ($codeLines[$i] -match ('^\s{4}' + "'" + '([a-z0-9-]+)' + "'" + ' \{$')) {
        $d1Name = "$($Matches[1])"
        if (-not $d1CaseStarts.ContainsKey($d1Name)) { $d1CaseStarts[$d1Name] = $i }
      }
    }
  }
  # a scan that finds nothing is a silent pass - pin the scan itself first.
  # .Count is used bare on purpose: in PS 5.1 @(hashtable) wraps the table into ONE array
  # element, so @($t).Count is always 1 and a scan that found nothing would look identical
  # to one that found everything. That exact shape made the first version of this lint
  # report "1 case" while its own >= 50 guard sat there red - the guard worked, the number
  # it printed did not. KEYS are enumerated through Get-HashKeys, never .Keys: a key named
  # 'keys' shadows the property (see Get-HashKeys), and this table is keyed by command names.
  ST-Check 'lint: dispatcher case scan sees the dispatcher (>= 50 cases inside Invoke-DesktopCommand)' ($d1CaseStarts.Count -ge 50)
  if ($d1CaseStarts.Count -lt 50) { Write-Output "      cases found: $($d1CaseStarts.Count)" }
  $d1Shared = @(Get-SharedFlagSet)
  $d1Dead = New-Object System.Collections.ArrayList
  $d1SplitSeen = 0
  foreach ($cmd in @(Get-HashKeys $d1CaseStarts)) {
    # v4.4.0 (A-15 pen 2): a named command's body now lives in its handler, so this scan walks every range
    #    the command owns. Reading only the case span would leave the lint green while it looked at a
    #    three-line stub - a hollow ruler, and this file already argues about that failure mode, so the
    #    walk is paired with a coverage count instead of trusted.
    $d1RgA = @(Get-CommandCodeRanges $codeLines $cmd)
    # A comment that mentions Split-Target is not a call to it - the first version of
    # this lint read hover's explanatory comment as the call site and reported
    # "strip comes after split" for all three commands. Comment lines are skipped.
    $splitAt = -1; $d1BodyEnd = -1
    foreach ($d1rA in $d1RgA) {
      for ($k = [int]$d1rA[0]; $k -lt [int]$d1rA[1]; $k++) {
        if ($codeLines[$k] -match '^\s*#') { continue }
        if ($codeLines[$k] -match 'Split-Target') { $splitAt = $k; $d1BodyEnd = [int]$d1rA[1]; break }
      }
      if ($splitAt -ge 0) { break }
    }
    if ($splitAt -lt 0) { continue }
    $d1SplitSeen = $d1SplitSeen + 1
    for ($k = $splitAt + 1; $k -lt $d1BodyEnd; $k++) {
      if ($codeLines[$k] -match '^\s*#') { continue }
      foreach ($mm in [regex]::Matches($codeLines[$k], '-(eq|like|in|contains)\s+''(--[a-z0-9-]+)''')) {
        $fl = $mm.Groups[2].Value
        if ($d1Shared -contains $fl) { continue }
        if (@((Get-OwnFlagSpec $cmd).Keys) -contains $fl) { continue }
        [void]$d1Dead.Add("$cmd : '$fl' compared at line $(Format-SourceLineRef ($k + 1)), after Split-Target already refused it")
      }
    }
  }
  ST-Check 'lint: no handler parses a flag its own Split-Target call has already refused (the D-1 shape)' (@($d1Dead).Count -eq 0)
  ST-Check 'lint (A-15c): the dead-flag scan is not hollow - it counted the command bodies that really do call Split-Target (a scan whose input emptied out at the wrap would report zero findings forever)' ($d1SplitSeen -ge 5)
  Write-Output ('      dead-flag scan: Split-Target bodies seen=' + $d1SplitSeen)
  foreach ($d in @($d1Dead)) { Write-Output "      unreachable flag: $d" }
  # the printed "valid here" list must be the parser, not a copy of it
  $d1St = -1
  for ($i = 0; $i -lt $codeLines.Count; $i++) { if ($codeLines[$i] -match '^function Split-Target') { $d1St = $i; break } }
  $d1Branches = New-Object System.Collections.ArrayList
  if ($d1St -ge 0) {
    for ($i = $d1St + 1; $i -lt $codeLines.Count; $i++) {
      if ($codeLines[$i] -match '^function ') { break }
      foreach ($mm in [regex]::Matches($codeLines[$i], '\$t\s+-eq\s+''(--[a-z0-9-]+)''')) { [void]$d1Branches.Add($mm.Groups[1].Value) }
    }
  }
  $d1Missing = @((@(Get-SharedFlagSet) | Where-Object { -not (@($d1Branches) -contains $_) }))
  $d1Extra = @((@($d1Branches) | Where-Object { -not ($d1Shared -contains $_) }) | Sort-Object -Unique)
  ST-Check 'lint: Get-SharedFlagSet is exactly Split-Target branch set (error text cannot lie)' (
    $d1St -ge 0 -and @($d1Missing).Count -eq 0 -and @($d1Extra).Count -eq 0 -and @($d1Branches).Count -ge 20)
  if (@($d1Missing).Count -gt 0) { Write-Output "      listed but not parsed: $(@($d1Missing) -join ' ')" }
  if (@($d1Extra).Count -gt 0) { Write-Output "      parsed but not listed: $(@($d1Extra) -join ' ')" }
  Write-Output "      flag scan: $($d1CaseStarts.Count) dispatcher cases, $(@($d1Branches).Count) shared flags, $((Get-OwnFlagTable).Count) commands with private flags"
  # every private flag must be stripped BEFORE its command's Split-Target call, its
  # parsed value must be READ by the handler, and it must be documented in that
  # command's help block - all three halves of "reachable". A flag that is stripped
  # into $own.Values and never used is the same dead end as one that was refused: the
  # table would say it works while the behaviour stayed frozen.
  $d1Src = $src -split "`r?`n"
  $d1OwnBad = New-Object System.Collections.ArrayList
  foreach ($cmd in @(Get-HashKeys (Get-OwnFlagTable))) {
    if (-not $d1CaseStarts.ContainsKey($cmd)) { [void]$d1OwnBad.Add("$cmd : in the flag table but has no dispatcher case"); continue }
    # v4.4.0 (A-15 pen 2): same reason - the strip/split sites are in the handler now, so the text walked
    #    is the command's own code wherever it lives, in file order (the ordering verdict needs that).
    $d1Lines = @((Get-CommandCodeText $codeLines $cmd) -split "`n")
    $stripAt = -1; $splitAt = -1
    $d1Block = ''
    for ($k = 0; $k -lt $d1Lines.Count; $k++) {
      if ($d1Lines[$k] -match '^\s*#') { continue }
      if ($stripAt -lt 0 -and $d1Lines[$k] -match 'Strip-OwnFlags') { $stripAt = $k }
      if ($splitAt -lt 0 -and $d1Lines[$k] -match 'Split-Target') { $splitAt = $k }
      $d1Block += $d1Lines[$k]
    }
    # v3.1.0 (P-06): a handler may delegate its own argument parse to a pure Resolve-*Args
    # function - menu-pick did exactly that so a trailing-flag hole could be tested offline.
    # FOLLOW the delegation instead of exempting it: the branch has to exist in the called
    # parser, and only functions named Resolve-*Args that the case body actually calls are
    # folded in, so no command can claim routing a flag it parses nowhere.
    foreach ($dm in @([regex]::Matches($d1Block, '(Resolve-[A-Za-z0-9]+Args)'))) {
      $d1Fn = $dm.Groups[1].Value
      $d1Fs = -1; $d1Fe = -1
      for ($dq = 0; $dq -lt $d1Src.Count; $dq++) {
        if ($d1Fs -lt 0) { if ($d1Src[$dq].StartsWith('function ' + $d1Fn)) { $d1Fs = $dq }; continue }
        if ($d1Src[$dq] -eq '}') { $d1Fe = $dq; break }
      }
      if ($d1Fs -ge 0 -and $d1Fe -gt ($d1Fs + 1)) { $d1Block += ("`n" + (@($d1Src[($d1Fs + 1)..($d1Fe - 1)]) -join "`n")) }
    }
    # v1.5.7 (J-06): the ordering rule only makes sense for a command that CALLS
    # Split-Target. menu-pick / type-in / unmap parse their own arguments and never reach it,
    # so requiring a Split-Target site there produced a false gap for three honest commands.
    if ($stripAt -lt 0) {
      [void]$d1OwnBad.Add("$cmd : is in the flag table but the handler never calls Strip-OwnFlags")
    } elseif ($splitAt -ge 0 -and $stripAt -gt $splitAt) {
      [void]$d1OwnBad.Add("$cmd : private flags are stripped AFTER Split-Target refused them (strip@$stripAt split@$splitAt)")
    }
    # its help block: from the synopsis line to the next synopsis line of ANY command
    $d1Hl = -1
    for ($k = 0; $k -lt $d1Src.Count; $k++) { if ($d1Src[$k] -match ('^\s{4}' + [regex]::Escape($cmd) + '\s')) { $d1Hl = $k; break } }
    if ($d1Hl -lt 0) { [void]$d1OwnBad.Add("$cmd : no help synopsis line found"); continue }
    $d1Doc = ''
    for ($k = $d1Hl; $k -lt $d1Src.Count; $k++) {
      if ($k -gt $d1Hl -and $d1Src[$k] -match '^\s{4}[a-z][a-z0-9-]*\s') { break }
      $d1Doc += $d1Src[$k]
    }
    $d1Spec = Get-OwnFlagSpec $cmd
    foreach ($fl in @(Get-HashKeys $d1Spec)) {
      # Contains, not -like: '[' is a WILDCARD character class in -like patterns,
      # so the first version of this check blew up on the pattern itself.
      if (-not $d1Doc.Contains('[' + $fl)) { [void]$d1OwnBad.Add("$cmd : '$fl' is stripped+parsed but not documented in its help block") }
      if (-not $d1Block.Contains("Values['" + $fl + "']")) { [void]$d1OwnBad.Add("$cmd : '$fl' is parsed but the handler never reads its value") }
      # J-06: a table flag must not ALSO be hand-compared in the same body - that is two
      # implementations of one flag, which is how "the table says it works" and "the code
      # says otherwise" can both be true at once.
      if ($d1Block.Contains("-eq '" + $fl + "'") -or $d1Block.Contains("-like '" + $fl + "'")) {
        [void]$d1OwnBad.Add("$cmd : '$fl' is table-driven AND hand-compared in the handler")
      }
    }
    # J-06: a command that parses its own arguments declares the shared flags it routes;
    # every one of them must have a real branch, or the declaration is a lie in the error text.
    if ($splitAt -lt 0) {
      foreach ($ds in @(Get-CommandSharedSet $cmd)) {
        if (-not $d1Block.Contains("-eq '" + $ds + "'")) { [void]$d1OwnBad.Add("$cmd : declares it routes '$ds' but nothing here parses it") }
      }
    }
  }
  ST-Check 'lint: every private flag is stripped before Split-Target, read by the handler and documented in help (D-1 anti-drift)' (@($d1OwnBad).Count -eq 0)
  foreach ($d in @($d1OwnBad)) { Write-Output "      flag-reachability gap: $d" }
  # positive controls: neither scan is vacuous
  $d1Plant = "      if (`$p.Words[`$i] -eq '--dwell') { x }"
  $d1PlantHit = $false
  foreach ($mm in [regex]::Matches($d1Plant, '-(eq|like|in|contains)\s+''(--[a-z0-9-]+)''')) { if ($mm.Groups[2].Value -ceq '--dwell') { $d1PlantHit = $true } }
  ST-Check 'lint: dead-flag pattern detects a planted D-1 violation' ($d1PlantHit)
  $d1BranchPlant = "    } elseif (`$t -eq '--demo') {"
  $d1BranchHit = $false
  foreach ($mm in [regex]::Matches($d1BranchPlant, '\$t\s+-eq\s+''(--[a-z0-9-]+)''')) { if ($mm.Groups[1].Value -ceq '--demo') { $d1BranchHit = $true } }
  ST-Check 'lint: branch-scan pattern detects a planted shared flag' ($d1BranchHit)

  # ---------- unit: v1.5.5 Strip-OwnFlags (the flags are now actually reachable) ----------
  $sfHover = Strip-OwnFlags @('10', '20', '--dwell', '1500', '--to', 'Win') 'hover'
  ST-Check 'unit: hover --dwell is stripped with its value and the rest still parses' (
    (@((Get-OptValue $sfHover 'Rest')) -join ' ') -ceq '10 20 --to Win' -and [int]$sfHover.Values['--dwell'] -eq 1500)
  $sfDrag = Strip-OwnFlags @('1', '2', '3', '4', '--steps', '30', '--hold', '50') 'drag'
  ST-Check 'unit: drag strips both of its flags and honours declared defaults' (
    (@((Get-OptValue $sfDrag 'Rest')) -join ' ') -ceq '1 2 3 4' -and [int]$sfDrag.Values['--steps'] -eq 30 -and [int]$sfDrag.Values['--hold'] -eq 50)
  $sfDef = Strip-OwnFlags @('1', '2', '3', '4') 'drag'
  ST-Check 'unit: an absent private flag reports its documented default, not null' (
    [int]$sfDef.Values['--steps'] -eq 14 -and [int]$sfDef.Values['--hold'] -eq 120)
  $sfE1 = ''
  try { [void](Strip-OwnFlags @('1', '2', '--dwell', '--to', 'Win') 'hover') } catch { $sfE1 = $_.Exception.Message }
  ST-Check 'unit: --dwell refuses to eat the next FLAG as its value (selector must not vanish)' (
    $sfE1 -like "*'--dwell' got the flag '--to' instead of its value*" -and $sfE1 -notlike '*needs a value*')
  $sfE2 = ''
  try { [void](Strip-OwnFlags @('1', '2', '--dwell', 'abc') 'hover') } catch { $sfE2 = $_.Exception.Message }
  ST-Check 'unit: --dwell rejects a non-numeric value by name' ($sfE2 -like "*'--dwell' needs a whole number, got: 'abc'*")
  $sfE3 = ''
  try { [void](Strip-OwnFlags @('1', '2', '--steps', '9999') 'drag') } catch { $sfE3 = $_.Exception.Message }
  ST-Check 'unit: --steps outside its declared range is refused with the range printed' (
    $sfE3 -like "*'--steps' must be 1..200, got: 9999*")
  $sfE4 = ''
  try { [void](Strip-OwnFlags @('1', '2', '--dwell') 'hover') } catch { $sfE4 = $_.Exception.Message }
  ST-Check 'unit: a private flag with nothing after it says what it needs' (
    $sfE4 -like "*'--dwell' needs a value*" -and $sfE4 -notlike '*valid here*')
  $sfE5 = ''
  try { [void](Strip-OwnFlags @('10', '20', '--index', '1') 'hover') } catch { $sfE5 = $_.Exception.Message }
  # --index belongs to find-click AND (since J-06) menu-pick: the message must name every
  # owner, in sorted order, so it cannot change between runs.
  ST-Check 'unit: another command private flag names every owner of it, not as a typo' (
    $sfE5.Contains("'--index' is a flag of find-click, menu-pick, not of this command") -and $sfE5.Contains('valid here:') -and $sfE5.Contains('--dwell'))
  # the D-5 wording: coordinate-only commands must not be sent hunting for a needle.
  # The test is on the ADVICE SENTENCE, not on the word --needle - --needle is a shared
  # flag that genuinely reaches hover's parser, so it must appear in its "valid here"
  # list. Asserting it away would make the message lie about its own parser.
  $uw1 = Get-UnknownFlagMessage 'hover' '--zz'
  $uw2 = Get-UnknownFlagMessage 'find-text' '--zz'
  $uw3 = Get-UnknownFlagMessage '' '--zz'
  ST-Check 'unit: unknown-flag text lists the real flag set and drops the needle advice for coordinate commands' (
    $uw1 -like "*for 'hover'*" -and $uw1 -like '*valid here:*--dwell*' -and $uw1 -notlike '*pass it as*' -and
    $uw2 -like '*pass it as --needle*' -and $uw2 -like "*for 'find-text'*")
  ST-Check 'unit: an unlabelled Split-Target call still offers the needle escape route (no regression)' (
    $uw3 -like '*unknown flag*' -and $uw3 -like '*pass it as --needle*')
  ST-Check 'unit: Test-CoordinateOnlyCommand is derived, not guessed (hover yes, relclick no, nothing no)' (
    (Test-CoordinateOnlyCommand 'hover') -eq $true -and (Test-CoordinateOnlyCommand 'drag') -eq $true -and
    (Test-CoordinateOnlyCommand 'relclick') -eq $false -and (Test-CoordinateOnlyCommand 'find-text') -eq $false -and
    (Test-CoordinateOnlyCommand '') -eq $false)
  # ---------- unit + lint: v4.2.0 feedback item 3 - the sibling-flag hint ----------
  # The three hand-written rect-family refusals live inside dispatcher cases that need a
  # screen to run, so the wiring itself is asserted as a source scan: all three, exactly
  # once each. The wording is asserted through the pure helper it is built from.
  # the needle is assembled so this very check line cannot match itself (a literal here
  # would count its own source as a fourth call site).
  $aliasCallNeedle = '$' + '(Get-RectFlagAliasHint'
  $aliasSites = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($aliasCallNeedle) })
  ST-Check 'lint: every hand-written rect-family unknown-flag refusal appends the sibling-flag hint (read-text, find-text, assert-text)' (
    (@($aliasSites).Count -eq 3) -and
    (@($aliasSites | Where-Object { $_.Contains('"read-text: unknown flag') }).Count -eq 1) -and
    (@($aliasSites | Where-Object { $_.Contains('"find-text: unknown flag') }).Count -eq 1) -and
    (@($aliasSites | Where-Object { $_.Contains('"assert-text: unknown flag') }).Count -eq 1))
  $aliasHint = Get-RectFlagAliasHint 'read-text' '--region'
  ST-Check 'unit: a sibling flag names its real owner AND the positional rectangle this command takes' (
    $aliasHint.Contains('POSITIONALLY as ''read-text <sel|x y w h>''') -and
    $aliasHint.Contains('''--region'' is the spelling used by ''find'''))
  ST-Check 'unit: an unknown flag that is not a known sibling alias adds no noise' (
    ((Get-RectFlagAliasHint 'read-text' '--json') -ceq '') -and
    ((Get-RectFlagAliasHint 'click' '--region') -ceq '') -and
    ((Get-UnknownFlagMessage 'find-text' '--region').Contains('POSITIONALLY as ''find-text <sel|x y w h> <needle...>''')))

  # ---------- unit: v1.5.7 (J-06) Bool flags, per-command shared routing ----------
  $sfDry = Strip-OwnFlags @('img.png', '10', '20', '--dry') 'imgclick'
  ST-Check 'unit: a Bool flag takes no value, defaults false and reports presence' (
    (@($sfDry.Rest) -join ' ') -ceq 'img.png 10 20' -and $sfDry.Values['--dry'] -eq $true -and
    $sfDry.Present['--dry'] -eq $true -and $sfDry.Present['--stale-ok'] -eq $false)
  $sfNone = Strip-OwnFlags @('img.png', '10', '20') 'imgclick'
  ST-Check 'unit: an absent Bool flag is false and Present says so (--dry vs --index 0 differ)' (
    $sfNone.Values['--dry'] -eq $false -and $sfNone.Present['--dry'] -eq $false -and @($sfNone.Rest).Count -eq 3)
  $sfMenu = Strip-OwnFlags @('Pop', 'OK', '--allow-window', '--index', '2') 'menu-pick'
  ST-Check 'unit: menu-pick strips its two flags before its own parser sees them' (
    (Get-OptValue $sfMenu 'Values')['--allow-window'] -eq $true -and [int](Get-OptValue $sfMenu 'Values')['--index'] -eq 2 -and
    ((@($sfMenu.Rest) -join ' ') -ceq 'Pop OK'))
  $sfMenuExpect = Strip-OwnFlags @('Pop', 'OK', '--expect', 'Saved') 'menu-pick'
  ST-Check 'unit: menu-pick lets through exactly the shared flags it declares' (
    (@($sfMenuExpect.Rest) -join ' ') -ceq 'Pop OK --expect Saved')
  $sfMenuTo = ''
  try { [void](Strip-OwnFlags @('Pop', 'OK', '--to', 'X') 'menu-pick') } catch { $sfMenuTo = $_.Exception.Message }
  ST-Check 'unit: menu-pick refuses --to (it never routed it) with the central wording' (
    $sfMenuTo.Contains("unknown flag '--to' for 'menu-pick'") -and $sfMenuTo.Contains('pass it as --needle <text>'))
  $sfUnmap = ''
  try { [void](Strip-OwnFlags @('a.png', '1', '2', '--dry') 'unmap') } catch { $sfUnmap = $_.Exception.Message }
  # --dry is imgclick's, so the refusal names the owner (unmap has no --dry of its own);
  # --allow-occluded belongs to nobody in unmap's world, so the generic wording + the
  # honest one-flag list is what a reader gets. Neither may offer --needle: unmap has none.
  ST-Check 'unit: unmap names the real owner of a flag it does not take' (
    $sfUnmap.Contains("'--dry' is a flag of imgclick, not of this command") -and $sfUnmap.Contains('valid here: --stale-ok') -and
    -not $sfUnmap.Contains('pass it as --needle'))
  $sfUnmap2 = ''
  try { [void](Strip-OwnFlags @('a.png', '1', '2', '--allow-occluded') 'unmap') } catch { $sfUnmap2 = $_.Exception.Message }
  ST-Check 'unit: unmap refuses an unknown flag with only what it really accepts' (
    $sfUnmap2.Contains("unknown flag '--allow-occluded' for 'unmap'") -and $sfUnmap2.Contains('valid here: --stale-ok') -and
    -not $sfUnmap2.Contains('--occlude '))
  $sfTi = Strip-OwnFlags @('--tab', '2', '100', '200', 'hello') 'type-in'
  ST-Check 'unit: type-in --tab works in any position now (it used to break x/y parsing)' (
    [int](Get-OptValue $sfTi 'Values')['--tab'] -eq 2 -and ((@($sfTi.Rest) -join ' ') -ceq '100 200 hello'))
  $sfTiBad = ''
  try { [void](Strip-OwnFlags @('100', '200', '--tab', '--verify') 'type-in') } catch { $sfTiBad = $_.Exception.Message }
  ST-Check 'unit: --tab refuses a FLAG as its value instead of typing a number away' ($sfTiBad.Contains("got the flag '--verify' instead of its value"))
  $sfTiRange = ''
  try { [void](Strip-OwnFlags @('100', '200', '--tab', '99', 'x') 'type-in') } catch { $sfTiRange = $_.Exception.Message }
  ST-Check 'unit: type-in --tab range comes from the table (0..20)' ($sfTiRange.Contains("'--tab' must be 0..20, got: 99"))
  ST-Check 'unit: every command in the shared map declares a subset of the shared set (and the map is non-empty: >= 4 keys, so an empty table cannot satisfy it by comparing nothing)' (
    $(
      $bad = @()
      # X-02: this used to wrap the map in @() and then index the WRAPPER by a command NAME.
      # Wrapping a hashtable in @() yields ONE hashtable element (not its entries), so that
      # index silently answered $null and the inner loop ran zero times - the check compared
      # nothing and could never have gone red. Index the dictionary itself, like the
      # production getter for the same table does.
      $csMap = Get-CommandSharedMap
      foreach ($k in @(Get-HashKeys $csMap)) {
        foreach ($f in (Get-OptValue $csMap $k)) { if (-not (@(Get-SharedFlagSet) -contains $f)) { $bad += "$k=$f" } }
      }
      # v4.0.1 (audit observation 6): the green condition is "nothing bad found", which an empty
      # table satisfies for free - the exact shape that made this check vacuous before X-02
      # batch 4 fixed the indexing. The floor is what makes "it compared something" part of the
      # assertion. EXPECTATION ADDED, not relaxed: 4 is the measured key count, and a legitimate
      # shrink below it has to be stated here rather than silently passing.
      (@($bad).Count -eq 0) -and (@(Get-HashKeys $csMap).Count -ge 4)
    ))
  # the flag-reachability lint must now cover the migrated commands, not just three
  ST-Check 'unit: the private-flag table covers 13 commands (J-06 migrated four, v1.6.0 adds open-and-pick, v2.0.0 adds wheel modifiers, v2.0.1 adds the press trio, v2.1.0 adds find, v3.0.0 adds dialog-cancel; EXPECTATION RAISED 12->13, and the two lints either side still refuse an entry that is unused or a flag that is undeclared)' (
    @(Get-HashKeys (Get-OwnFlagTable)).Count -eq 13)

  # the escape route must survive the strip: everything after a value-taking flag is DATA.
  # J-06's central unknown-flag refusal nearly ate `--needle <--payload>` and only a --live
  # round (type-in --verify-timeout ladder) noticed, so this shape is now pinned offline too.
  $sfNd = ''
  $sfNdRest = ''
  try { $sfNd = Strip-OwnFlags @('10', '20', '--needle', '--DTXVT', '--verify') 'type-in'; $sfNdRest = (@($sfNd.Rest) -join ' ') } catch { $sfNdRest = 'THREW: ' + $_.Exception.Message }
  ST-Check 'unit: a --needle payload starting with -- passes the strip untouched' (
    $sfNdRest -ceq '10 20 --needle --DTXVT --verify' -and [int]$sfNd.Values['--tab'] -eq 0)
  $sfNd2Rest = ''
  try { $x2 = Strip-OwnFlags @('Win', '--needle', '--fit', '--index', '1') 'find-click'; $sfNd2Rest = (@($x2.Rest) -join ' ') + '|' + [int]$x2.Values['--index'] } catch { $sfNd2Rest = 'THREW: ' + $_.Exception.Message }
  ST-Check 'unit: find-click keeps --needle <--literal> while stripping its own --index' (
    $sfNd2Rest -ceq 'Win --needle --fit|1')
  $sfNd3Rest = ''
  try { $x3 = Strip-OwnFlags @('Pop', '--needle', '--x', '--expect', '--y') 'menu-pick'; $sfNd3Rest = (@($x3.Rest) -join ' ') } catch { $sfNd3Rest = 'THREW: ' + $_.Exception.Message }
  ST-Check 'unit: menu-pick passes two value flags whose data begins with --' ($sfNd3Rest -ceq 'Pop --needle --x --expect --y')
  $sfVsBad = @(@(Get-SharedValueFlagSet) | Where-Object { -not (@(Get-SharedFlagSet) -contains $_) })
  ST-Check 'unit: every value-taking shared flag is in the shared set (no typo in the route table)' (
    @($sfVsBad).Count -eq 0 -and @(Get-SharedValueFlagSet).Count -ge 10)
  if (@($sfVsBad).Count -gt 0) { Write-Output ("      value flag not shared: " + (@($sfVsBad) -join ' ')) }

  # ---------- unit: v1.5.7 (D-6) the auto-grid decision is explicit, and travels ----------
  $gFit = Parse-CaptureFlags @('--fit', '1400')
  ST-Check 'unit: --fit is recorded as a USER choice (the auto-grid rule depends on it)' (
    $gFit.Fit -eq 1400 -and $gFit.FitUser -eq $true -and $gFit.GridUser -eq $false -and $gFit.Grid -le 0)
  $gPlain = Parse-CaptureFlags @('something')
  ST-Check 'unit: a capture nobody fitted has no grid claim (default behaviour unchanged)' (
    $gPlain.FitUser -eq $false -and $gPlain.GridUser -eq $false)
  $gNoGrid = Parse-CaptureFlags @('--fit', '1400', '--no-grid')
  ST-Check 'unit: --no-grid overrides the auto grid and says it was the user speaking' (
    $gNoGrid.GridUser -eq $true -and $gNoGrid.Grid -le 0)
  $gExplicit = Parse-CaptureFlags @('--grid', '25')
  ST-Check 'unit: an explicit --grid step still wins over any default' (
    $gExplicit.Grid -eq 25 -and $gExplicit.GridUser -eq $true)
  $gSide = Join-Path $env:TEMP ('dtx-grid-sidecar-' + [guid]::NewGuid().ToString('N') + '.png')
  Write-MapSidecar $gSide 10 20 0.5 100 80 'rect' $null 50
  $gBack = Read-MapSidecar $gSide
  $gSide2 = Join-Path $env:TEMP ('dtx-grid-sidecar-' + [guid]::NewGuid().ToString('N') + '.png')
  Write-MapSidecar $gSide2 10 20 1.0 100 80 'rect'
  $gBack2 = Read-MapSidecar $gSide2
  Remove-Item -LiteralPath @(($gSide + '.map.txt'), ($gSide2 + '.map.txt')) -Force -ErrorAction SilentlyContinue
  ST-Check 'unit: a grid step round-trips through the sidecar, and its absence reads as 0' (
    $gBack.Grid -eq 50 -and $gBack2.Grid -eq 0)
  # the bitmap is the only thing imgclick reads, so every capture that can auto-grid must
  # hand Save-RectEx the user's flag context - a missed call site would silently disable
  # the rule for that one command (the v1.5.3 / v1.5.6 "only lives in the signature" family)
  # Internal captures (script steps) pass literal "0 -1 @()" - they have no user flags to
  # forward, so the rule is stated over the call sites that DO read the parsed flags:
  # any Save-RectEx that consumes $pf.X must also hand over $pf itself.
  $gForw = New-Object System.Collections.ArrayList
  for ($gi = 0; $gi -lt $codeLines.Count; $gi++) {
    $gl = $codeLines[$gi]
    if ($gl -match '^\s*#') { continue }
    if ($gl -notmatch 'Save-RectEx .* \$pf\.') { continue }
    if ($gl -notmatch '\$pf\s*\|\s*Write-Output') { [void]$gForw.Add("$($gi + 1): $($gl.Trim())") }
  }
  ST-Check 'lint: every capture call site forwards the flag context (no command quietly loses the auto grid)' (@($gForw).Count -eq 0)
  foreach ($gf in @($gForw)) { Write-Output "      Save-RectEx call without the cf argument: $gf" }

  # ---------- contract: v1.5.5 (D-4) no miss message writes its own tail ----------
  # Why this is a LINT and not just a live case: the live check that the tails match
  # only runs with --live, so the fast gate sat green while one call site quietly went
  # back to hand-written wording (measured: bypassing find-click's call site left the
  # offline run at full green before this lint existed). Rule derived, not enumerated -
  # any refusal that reports a missing needle must get its OCR evidence from the one
  # formatter. find-color is correctly excluded: it searches pixels, so it has no OCR
  # lines to report.
  # The mark is ASSEMBLED rather than written as one literal: a line that contains the
  # mark text would be counted by this very scan (it reads the whole file, selftest
  # included) and reported as a bypass - which is exactly how the first version of this
  # block failed on its own definition.
  $d4Mark = "'" + '$needle' + "' not found"
  $d4Sites = 0
  $d4NoTail = New-Object System.Collections.ArrayList
  for ($d4i = 0; $d4i -lt $codeLines.Count; $d4i++) {
    if ($codeLines[$d4i] -match '^\s*#') { continue }
    if ($codeLines[$d4i].Contains($d4Mark)) {
      $d4Sites++
      if (-not $codeLines[$d4i].Contains('Format-OcrSampleTail')) { [void]$d4NoTail.Add($d4i + 1) }
    }
  }
  ST-Check 'contract: every needle-miss refusal reports its OCR evidence through Format-OcrSampleTail (>= 5 sites)' (
    $d4Sites -ge 5 -and @($d4NoTail).Count -eq 0)
  foreach ($d4n in @($d4NoTail)) { Write-Output "      miss message bypasses the tail formatter: line $d4n" }
  $d4Plant = '        throw "x: ' + $d4Mark + ' in region; 3 lines"'
  ST-Check 'contract: the tail-bypass scan detects a planted hand-written miss message' (
    $d4Plant.Contains($d4Mark) -and -not $d4Plant.Contains('Format-OcrSampleTail'))

  # ---------- contract: v1.5.7 (owner supplement 3 + J-06) truncation must self-report ----------
  # "total N / shown M / hidden N-M" is the generalised R-25 lesson: every list this tool
  # cuts must say it cut something. Checked by scanning production code for
  # Select-Object -First and requiring a hidden-count token within the same statement
  # (the line plus the two around it). Sites that CHOOSE rather than display (picking the
  # largest window, taking the first hit for a report field) carry the marker
  # "selection-not-display" - the lint cannot read intent, so the code has to say it.
  $t0 = $codeLines.Count
  # A-14i: this used to be a SECOND copy of the window judgement - it hunted '^function Invoke-SelfTest'
  # and stopped at the next '^function '. One copy is stale by construction once a body moves into its
  # own file (measured: this very lift reddened this lint, because the span no longer covered the family
  # it lived in). There is now exactly one window in this section - the AST span the orchestrator
  # publishes through $Ctx - and lint (A-14f) is what keeps that span honest.
  $tSelfStart = $j5ProdStart
  $tSelfEnd = $j5ProdEnd
  $tSilent = New-Object System.Collections.ArrayList
  $tSeen = 0
  for ($ti = 0; $ti -lt $t0; $ti++) {
    if ($ti -ge $tSelfStart -and $ti -lt $tSelfEnd) { continue }
    if ($codeLines[$ti] -match '^\s*#') { continue }
    if ($codeLines[$ti] -notmatch 'Select-Object -First') { continue }
    $tSeen++
    if ($codeLines[$ti].Contains('selection-not-display')) { continue }
    $tNear = ''
    # +/-4 lines: the "we hid some" statement has to be part of the same statement, and a
    # multi-line pipeline legitimately says it on the reporting line rather than the cut.
    for ($tj = [Math]::Max(0, $ti - 4); $tj -le [Math]::Min($t0 - 1, $ti + 4); $tj++) { $tNear += $codeLines[$tj] }
    if ($tNear -match 'more|hidden|cut|not shown|\+K|of \$\(') { continue }
    [void]$tSilent.Add("line $(Format-SourceLineRef ($ti + 1)): $($codeLines[$ti].Trim())")
  }
  ST-Check 'contract: no user-visible list is truncated silently (>= 6 truncation sites scanned)' (
    $tSeen -ge 6 -and @($tSilent).Count -eq 0)
  foreach ($tS in @($tSilent)) { Write-Output "      silent truncation: $tS" }
  Write-Output "      truncation scan: $tSeen site(s) outside selftest, $(@($tSilent).Count) silent"
  $tPlant = '  $x = @($rows | Select-Object -First 4); foreach ($r in $x) { Write-Output $r.Text }'
  ST-Check 'contract: the truncation scan catches a planted silent cut' (
    $tPlant -match 'Select-Object -First' -and $tPlant -notmatch 'more|hidden|cut|not shown|\+K|of \$\(' -and
    -not $tPlant.Contains('selection-not-display'))

  # ---------- unit: v1.5.7 (supplement 3) a miss carries every premise on one line ----------
  $pmLines = @('alpha', 'beta', 'gamma', 'delta', 'epsilon') | ForEach-Object { [pscustomobject]@{ Text = $_ } }
  $pmCtx = @{ Rect = '(10,20) 300x200'; Retry = 'also retried at 2x'; Occlusion = '12% scan=read occluded=12%'; Needle = 'QXW' }
  $pmOut = Format-OcrSampleTail $pmLines 2 $pmCtx
  ST-Check 'unit: a miss line carries rect / scan / occlusion / fold-pass / shown-of-total on the SAME line' (
    $pmOut.Contains('premises:') -and $pmOut.Contains('rect=(10,20) 300x200') -and $pmOut.Contains('scan=also retried at 2x') -and
    $pmOut.Contains('occluded=12%') -and $pmOut.Contains('fold-pass=ran(identical)') -and $pmOut.Contains('shown=2 of 5') -and
    $pmOut.Contains('(+3 more lines not shown)'))
  ST-Check 'unit: the premises fit on one line (a fragment must not be readable as the whole fact)' (
    @($pmOut -split "`r?`n").Count -eq 1)
  $pmFold = Format-OcrSampleTail $pmLines 8 @{ Needle = 'I0l1O' }
  ST-Check 'unit: fold-pass prints the folded needle actually searched on the second pass' ($pmFold.Contains('fold-pass=ran(lollo)'))
  $pmBare = Format-OcrSampleTail $pmLines 8
  ST-Check 'unit: without a context the tail is unchanged (v1.5.5 callers must not shift)' (
    -not $pmBare.Contains('premises:') -and $pmBare.Contains('OCR read 5 line(s) total:'))

  # ---------- unit: v1.5.2 WP-3 menu-pick target predicate (audit R-04) ----------
  # The old rule was "has the WS_POPUP style bit". On this machine the desktop,
  # the Settings shell, Weixin and several app shells carry that bit, so the
  # documented refusal of "non-popup targets" protected nothing. Synthetic windows
  # only - pure geometry, no desktop touched.
  $sW = 3840; $sH = 2160
  $mwProgman = [pscustomobject]@{ Class = 'Progman'; W = 3840; H = 2160; Title = 'Program Manager' }
  $mwWorkerW = [pscustomobject]@{ Class = 'WorkerW'; W = 800; H = 600; Title = '' }
  $mwWin32 = [pscustomobject]@{ Class = '#32768'; W = 345; H = 435; Title = '' }
  $mwForms = [pscustomobject]@{ Class = 'WindowsForms10.Window.8.app'; W = 345; H = 435; Title = 'ctx' }
  $mwApp = [pscustomobject]@{ Class = 'Chrome_WidgetWin_1'; W = 2500; H = 1500; Title = 'app' }
  $mwOverlay = [pscustomobject]@{ Class = 'CEF-OSC-WIDGET'; W = 3839; H = 2160; Title = 'NVIDIA GeForce Overlay' }
  $vProgman = Test-MenuWindow $mwProgman $sW $sH
  ST-Check 'unit: menu rule refuses the desktop by class, not by size' (
    $vProgman.Menu -eq $false -and $vProgman.Reason -like '*shell surface*')
  $vWorkerW = Test-MenuWindow $mwWorkerW $sW $sH
  ST-Check 'unit: menu rule refuses a small WorkerW (explicit shell exclusion beats the area rule)' (
    $vWorkerW.Menu -eq $false -and $vWorkerW.Reason -like '*shell surface*')
  $v32768 = Test-MenuWindow $mwWin32 $sW $sH
  ST-Check 'unit: menu rule accepts class #32768' ($v32768.Menu -eq $true -and $v32768.Reason -like '*#32768*')
  $vForms = Test-MenuWindow $mwForms $sW $sH
  ST-Check 'unit: menu rule accepts a transient popup shape' ($vForms.Menu -eq $true -and $vForms.Reason -like '*popup shape*')
  $vApp = Test-MenuWindow $mwApp $sW $sH
  ST-Check 'unit: menu rule refuses a large app window (would click anything)' ($vApp.Menu -eq $false)
  $vOver = Test-MenuWindow $mwOverlay $sW $sH
  ST-Check 'unit: menu rule refuses a full-screen overlay' ($vOver.Menu -eq $false -and $vOver.Reason -like '*spans the screen*')
  ST-Check 'unit: menu rule refuses a null window' ((Test-MenuWindow $null $sW $sH).Menu -eq $false)
  ST-Check 'unit: menu rule with no screen size accepts #32768 by class and refuses shape matches' (
    (Test-MenuWindow $mwWin32 0 0).Menu -eq $true -and (Test-MenuWindow $mwApp 0 0).Menu -eq $false)
  Write-Output "      menu rule: progman=$($vProgman.Reason) / 32768=$($v32768.Reason) / app=$($vApp.Reason)"

  # ---------- lint: v1.7.0 J-07 A - the six "do not lose" contracts, named and pinned ----------
  # Owner ruling: the six things that saved the Steam session must never be lost to a
  # refactor. #5 (occlusion scan=/rect= labels) and #6 (--json key sets) are already
  # pinned by named checks elsewhere; here their TITLES are re-found by traversal so a
  # silent rename/deletion of those checks itself goes red. #1/#3/#4 get new source lints.
  # #2 (win-close -> wins no longer lists the pid) is behavioural and lives in the --live
  # section against the spawned probe window.
  $j7Img = @()
  $j7Mark = '"imgclick:' + ' $img'
  for ($j7i = 0; $j7i -lt $codeLines.Count; $j7i++) {
    if ($j7i -ge $j5ProdStart -and $j7i -lt $j5ProdEnd) { continue }
    if ($codeLines[$j7i] -match '^\s*#') { continue }
    if ($codeLines[$j7i].Contains($j7Mark)) { $j7Img += $codeLines[$j7i] }
  }
  $j7MapForm = @()
  $j7FMark = '$mapForm = $(if ($map.Scale' + ' -eq 1)'
  for ($j7i = 0; $j7i -lt $codeLines.Count; $j7i++) {
    if ($j7i -ge $j5ProdStart -and $j7i -lt $j5ProdEnd) { continue }
    if ($codeLines[$j7i] -match '^\s*#') { continue }
    if ($codeLines[$j7i].Contains($j7FMark)) { $j7MapForm += $codeLines[$j7i] }
  }
  ST-Check 'lint: J-07 #1 imgclick echo carries the sidecar name and the scale-aware screen = image formula (exactly 1 each)' (
    (@($j7Img).Count -eq 1) -and $j7Img[0].Contains('[map: ') -and
    (@($j7MapForm).Count -eq 1) -and $j7MapForm[0].Contains('screen = image + (') -and $j7MapForm[0].Contains('screen = image / '))
  $j7Keys = @()
  $j7KMark = '"sent keys' + ' '
  for ($j7i = 0; $j7i -lt $codeLines.Count; $j7i++) {
    if ($j7i -ge $j5ProdStart -and $j7i -lt $j5ProdEnd) { continue }
    if ($codeLines[$j7i] -match '^\s*#') { continue }
    if ($codeLines[$j7i].Contains($j7KMark)) { $j7Keys += $codeLines[$j7i] }
  }
  ST-Check 'lint: J-07 #3 keys --to echo self-verifies the landing with foreground after send (exactly 1 echo line)' (
    @($j7Keys).Count -eq 1 -and $j7Keys[0].Contains('foreground after send'))
  $j7Hit = @()
  $j7HMark = '"hit: text=' + "'"
  for ($j7i = 0; $j7i -lt $codeLines.Count; $j7i++) {
    if ($j7i -ge $j5ProdStart -and $j7i -lt $j5ProdEnd) { continue }
    if ($codeLines[$j7i] -match '^\s*#') { continue }
    if ($codeLines[$j7i].Contains($j7HMark)) { $j7Hit += $codeLines[$j7i] }
  }
  ST-Check 'lint: J-07 #4 find-text hit echo exposes the ready-made centre= click point (exactly 1 echo line)' (
    @($j7Hit).Count -eq 1 -and $j7Hit[0].Contains('centre=('))
  # #5/#6 by traversal: the pinning check titles must still exist (renaming or deleting
  # them is exactly the "checklist lost a file" drift this ruling exists to stop).
  $j7Titles = New-Object System.Collections.ArrayList
  for ($j7i = $j5ProdStart; $j7i -lt $j5ProdEnd; $j7i++) {
    if ($codeLines[$j7i] -match "ST-Check '([^']+)'") { [void]$j7Titles.Add($Matches[1]) }
  }
  ST-Check 'lint: J-07 #5 the occlusion scan/rect labelling contract check still exists (found by traversal, exactly 1)' (
    @(@($j7Titles) | Where-Object { $_.Contains('scan+rect') }).Count -eq 1)
  ST-Check 'lint: J-07 #6 the --json top-level key-set contract checks still exist (found by traversal, exactly 2)' (
    @(@($j7Titles) | Where-Object { $_.Contains('--json top-level keys are exactly') }).Count -eq 2)


  # ---------- v4.4.0 (A-15): the case shape is judged from the AST, and a shape break names the case ----------
  # Design gate 12, landed BEFORE any case body moves. Measured on this tree (a15-probe.ps1): the
  # dispatcher holds ONE switch with 79 clauses; 76 of them begin on a line the strict 76-case regex
  # sees; the other 3 are single-line cases and they are exactly selftest / script / replay; 0 clauses
  # begin on a line that is neither. The unscoped file-wide count of the same regex is 90 - 14 more
  # lines live in OTHER switches - which is why this gate (and the three older scans) must be scoped
  # to the dispatcher, and why the difference is asserted rather than a number being trusted.
  $a15Gap = Get-CaseShapeGap $j5SelfParsed $srcLines 'Invoke-DesktopCommand' @('selftest', 'script', 'replay') 76 79
  $a15Unscoped = 0
  foreach ($a15l in $srcLines) { if ([regex]::IsMatch([string]$a15l, '^    ''[a-z0-9-]+'' \{$')) { $a15Unscoped = $a15Unscoped + 1 } }
  ST-Check 'lint (A-15): every case the switch really has begins on a line the case scans can see (AST clauses = strict-shape cases + the three registered single-line cases), the three existing counts agree on 76 and 79, and the unscoped count is larger, so the scope is what is being measured' (
    ($a15Gap -ceq '') -and ($d1CaseStarts.Count -eq 76) -and ($hCaseStarts.Count -eq 76) -and
    ($gaCasesCount -eq 79) -and ($a15Unscoped -gt 76))
  Write-Output ('      A-15 case shape: gap=[' + $a15Gap + '] flag-scan=' + $d1CaseStarts.Count + ' help-index=' + $hCaseStarts.Count +
    ' f-00-a=' + $gaCasesCount + ' unscoped-file-wide=' + $a15Unscoped)
  # the teeth: every note this predicate can emit is planted, on text - not on the tree. The clean
  # fixture must be empty AND every breach must say which case, because "some count got smaller" is not
  # a finding a reader can act on.
  $a15Cases = @('function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {',
    '  switch ($Cmd) {',
    '    ''click'' {',
    '      Move-Mouse 1 2',
    '    }',
    '    ''grid'' {',
    '      Usage',
    '    }',
    '    ''selftest'' { Invoke-SelfTest $Rest }',
    '  }',
    '}')
  $a15F = 'Invoke-DesktopCommand'
  $a15Parsed = Parse-SourceForInventory ($a15Cases -join "`n")
  $a15Clean = Get-CaseShapeGap $a15Parsed $a15Cases $a15F @('selftest') 2 3
  # a brace that moved to the next line: measured on both engines, the switch STILL has the clause
  # (labels click@3, grid@6, selftest@10) while the strict regex now sees one line fewer - the exact
  # silent disappearance the design warned about for A-15, and the reason the AST is the authority here.
  $a15Odd = @($a15Cases[0..4]) + @('    ''grid''', '    {', '      Usage', '    }') + @($a15Cases[8..10])
  # a fourth single-line case that nobody registered as an exception
  $a15Extra = @($a15Cases[0..4]) + @('    ''grid'' { Usage }') + @($a15Cases[8..10])
  # a registered exception that changed shape (selftest written across three lines)
  $a15Regained = @($a15Cases[0..7]) + @('    ''selftest'' {', '      Invoke-SelfTest $Rest', '    }') + @($a15Cases[9..10])
  # a body with no switch at all, a name with no body, a null parse, an empty line set, and a text that
  # does not parse: every one of them must REFUSE with a named reason, never answer "no gap"
  $a15NoSwitch = @('function Invoke-DesktopCommand([string]$Cmd) {', '  Usage', '}')
  $a15Broken = @('function Invoke-DesktopCommand([string]$Cmd) {', '  switch ($Cmd) {', '    ''x'' {')
  $a15OddParsed = Parse-SourceForInventory ($a15Odd -join "`n")
  $a15ExtraParsed = Parse-SourceForInventory ($a15Extra -join "`n")
  $a15RegParsed = Parse-SourceForInventory ($a15Regained -join "`n")
  $a15NoSwitchParsed = Parse-SourceForInventory ($a15NoSwitch -join "`n")
  $a15BrokenParsed = Parse-SourceForInventory ($a15Broken -join "`n")
  $a15OddGap = Get-CaseShapeGap $a15OddParsed $a15Odd $a15F @('selftest') 2 3
  $a15ExtraGap = Get-CaseShapeGap $a15ExtraParsed $a15Extra $a15F @('selftest') 2 3
  $a15Regap = Get-CaseShapeGap $a15RegParsed $a15Regained $a15F @('selftest') 2 3
  $a15NoSwitchGap = Get-CaseShapeGap $a15NoSwitchParsed $a15NoSwitch $a15F @('selftest') 0 0
  $a15AbsentGap = Get-CaseShapeGap $a15Parsed $a15Cases 'Invoke-Nope' @('selftest') 2 3
  $a15NullGap = Get-CaseShapeGap $null $a15Cases $a15F @('selftest') 2 3
  $a15EmptyGap = Get-CaseShapeGap $a15Parsed @() $a15F @('selftest') 2 3
  $a15BrokenGap = Get-CaseShapeGap $a15BrokenParsed $a15Broken $a15F @('selftest') 0 0
  ST-Check 'unit (A-15): the case-shape predicate passes the clean fixture and names a moved brace, an unregistered single-line case, a registered exception that changed shape and a body with no switch, and refuses an absent body, a null parse, an empty line set and a text that does not parse' (
    ($a15Clean -ceq '') -and ($a15OddGap -ceq 'odd-shape=grid@6,strict-count=1-want=2') -and
    ($a15ExtraGap -ceq 'inline-not-allowed=grid,strict-count=1-want=2') -and
    ($a15Regap -ceq 'allowed-not-inline=selftest,strict-count=3-want=2') -and
    ($a15NoSwitchGap -ceq 'switch-count=0') -and ($a15AbsentGap -ceq '-absent-body:Invoke-Nope') -and
    ($a15NullGap -ceq '-no-parse') -and ($a15EmptyGap -ceq '-no-lines') -and ($a15BrokenGap -like '-parse-errors=*'))
  Write-Output ('      A-15 fixtures: clean=[' + $a15Clean + '] odd=[' + $a15OddGap + '] extra-inline=[' + $a15ExtraGap +
    '] regained=[' + $a15Regap + '] no-switch=[' + $a15NoSwitchGap + '] absent=[' + $a15AbsentGap +
    '] null=[' + $a15NullGap + '] empty=[' + $a15EmptyGap + '] broken=[' + $a15BrokenGap + ']')

  # ---------- v4.4.0 (A-15b): the named-stub conversion is machine-checked, one case at a time ----------
  # The conversion is 79 clauses turned into handler calls, and a card lowers the unwrapped count. That is
  # exactly the shape of work where a case can be lost in silence (a body copied wrong, a stub pointed at
  # another command's handler, a flag protocol half applied), so the predicate runs over the real parse
  # and every clause must answer with one of the four legal shapes. The registered numbers below are what
  # this card moves; the same commit that wraps a case lowers the count and raises the flag list.
  $a15bGap = Get-HandlerStubGap $j5SelfParsed $script:StHandlerInlineCases $script:StHandlerFlagCases ([int]$script:StHandlerUnwrapped)
  $a15bHandlers = 0
  foreach ($a15bf in @($j5SelfParsed.Root.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] }, $true))) {
    if (([string]$a15bf.Name).StartsWith('Invoke-Handler-')) { $a15bHandlers = $a15bHandlers + 1 }
  }
  ST-Check 'lint (A-15b): every dispatcher case is an allowed inline case, a plain handler stub, a flag stub or a registered unwrapped body; each stub names its own handler and passes the literal command name and $Rest; the [ref] protocol is complete on both sides; and the unwrapped count equals the registered number' (
    ($a15bGap -ceq '') -and (@($script:StHandlerInlineCases).Count -eq 3) -and (@($script:StHandlerFlagCases).Count -eq 4))
  Write-Output ('      A-15b stubs: gap=[' + $a15bGap + '] handlers=' + $a15bHandlers + ' inline=' + @($script:StHandlerInlineCases).Count +
    ' flag=' + @($script:StHandlerFlagCases).Count + ' unwrapped-want=' + [int]$script:StHandlerUnwrapped)
  # every note the predicate can emit, planted on text. The expectations are literal strings because a
  # reading that merely "is not empty" would pass on any bug - and this is the gate that watches 79 moves.
  $a15bGood = @'
  function Invoke-Handler-shot([string]$Cmd, [string[]]$Rest) {
    Write-Output 'shot ran'
  }
  function Invoke-Handler-uia-click([string]$Cmd, [string[]]$Rest, [ref]$SkipTail) {
    if ($Rest.Count -ge 2) { Invoke-UiaClickByPath $Rest; $SkipTail.Value = $true; return }
    Write-Output 'normal end'
  }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'shot' {
        Invoke-Handler-shot 'shot' $Rest
      }
      'uia-click' {
        $a15SkipTail = $false
        Invoke-Handler-uia-click 'uia-click' $Rest ([ref]$a15SkipTail)
        if ($a15SkipTail) { return }
      }
      'selftest' { Invoke-SelfTest $Rest }
      'legacy' {
        $a = 1
        Write-Output $a
      }
    }
    Trim-After
  }
'@
  $a15bWrongName = @'
  function Invoke-Handler-shot([string]$Cmd, [string[]]$Rest) { Write-Output 1 }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'shot' {
        Invoke-Handler-other 'shot' $Rest
      }
    }
  }
'@
  $a15bWrongCmd = @'
  function Invoke-Handler-shot([string]$Cmd, [string[]]$Rest) { Write-Output 1 }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'shot' {
        Invoke-Handler-shot 'shotx' $Rest
      }
    }
  }
'@
  $a15bWrongRest = @'
  function Invoke-Handler-shot([string]$Cmd, [string[]]$Rest) { Write-Output 1 }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'shot' {
        Invoke-Handler-shot 'shot' $Cmd
      }
    }
  }
'@
  $a15bInline = @'
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'selftest' { Invoke-SelfTest $Rest }
      'help' { Usage }
    }
  }
'@
  $a15bOrphan = @'
  function Invoke-Handler-orphaned([string]$Cmd, [string[]]$Rest) { Write-Output 1 }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'selftest' { Invoke-SelfTest $Rest }
    }
  }
'@
  $a15bNoMark = @'
  function Invoke-Handler-markme([string]$Cmd, [string[]]$Rest, [ref]$SkipTail) {
    if ($Rest.Count -ge 2) { Invoke-Something $Rest; return }
  }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'markme' {
        $a15SkipTail = $false
        Invoke-Handler-markme 'markme' $Rest ([ref]$a15SkipTail)
        if ($a15SkipTail) { return }
      }
    }
  }
'@
  $a15bEscape = @'
  function Invoke-Handler-escapeme([string]$Cmd, [string[]]$Rest, [ref]$SkipTail) {
    Write-Output $SkipTail
    $SkipTail.Value = $true
    return
  }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'escapeme' {
        $a15SkipTail = $false
        Invoke-Handler-escapeme 'escapeme' $Rest ([ref]$a15SkipTail)
        if ($a15SkipTail) { return }
      }
    }
  }
'@
  $a15bNoRef = @'
  function Invoke-Handler-noref([string]$Cmd, [string[]]$Rest, $SkipTail) {
    $SkipTail.Value = $true
    return
  }
  function Invoke-DesktopCommand([string]$Cmd, [string[]]$Rest) {
    switch ($Cmd) {
      'noref' {
        $a15SkipTail = $false
        Invoke-Handler-noref 'noref' $Rest ([ref]$a15SkipTail)
        if ($a15SkipTail) { return }
      }
    }
  }
'@
  $a15bTwo = @'
  function Invoke-DesktopCommand([string]$Cmd) { switch ($Cmd) { 'a' { } } ; switch ($Cmd) { 'b' { } } }
'@
  $a15bI = @('selftest')
  $a15bClean = Get-HandlerStubGap (Parse-SourceForInventory $a15bGood) $a15bI @('uia-click') 1
  $a15bNoFlag = Get-HandlerStubGap (Parse-SourceForInventory $a15bGood) $a15bI @() 1
  $a15bGhost = Get-HandlerStubGap (Parse-SourceForInventory $a15bGood) $a15bI @('uia-click', 'ghost') 1
  $a15bCount = Get-HandlerStubGap (Parse-SourceForInventory $a15bGood) $a15bI @('uia-click') 3
  $a15bName = Get-HandlerStubGap (Parse-SourceForInventory $a15bWrongName) $a15bI @() 0
  $a15bCmd = Get-HandlerStubGap (Parse-SourceForInventory $a15bWrongCmd) $a15bI @() 0
  $a15bRest = Get-HandlerStubGap (Parse-SourceForInventory $a15bWrongRest) $a15bI @() 0
  $a15bInlineGap = Get-HandlerStubGap (Parse-SourceForInventory $a15bInline) $a15bI @() 0
  $a15bOrphanGap = Get-HandlerStubGap (Parse-SourceForInventory $a15bOrphan) $a15bI @() 0
  $a15bMarkGap = Get-HandlerStubGap (Parse-SourceForInventory $a15bNoMark) $a15bI @('markme') 0
  $a15bEscGap = Get-HandlerStubGap (Parse-SourceForInventory $a15bEscape) $a15bI @('escapeme') 0
  $a15bRefGap = Get-HandlerStubGap (Parse-SourceForInventory $a15bNoRef) $a15bI @('noref') 0
  $a15bNullGap = Get-HandlerStubGap $null $a15bI @() 0
  $a15bAbsentGap = Get-HandlerStubGap (Parse-SourceForInventory 'function Other-Thing { return 1 }') $a15bI @() 0
  $a15bNoSwGap = Get-HandlerStubGap (Parse-SourceForInventory 'function Invoke-DesktopCommand([string]$Cmd) { Write-Output 1 }') $a15bI @() 0
  $a15bTwoGap = Get-HandlerStubGap (Parse-SourceForInventory $a15bTwo) $a15bI @() 0
  $a15bMap = (Get-HandlerName 'chrome-click') + '/' + (Get-HandlerName 'uia-settext')
  ST-Check 'unit (A-15b): the stub predicate passes the good fixture and names an unregistered flag case, a registered flag case that is gone, a wrong unwrapped count, a stub pointing at another handler, a wrong literal command name, a wrong rest argument, an unregistered inline case, an orphan handler, an unmarked early return, a flag that reaches the output, a third parameter that is not [ref], a null parse, an absent dispatcher and a switch count that is not one' (
    ($a15bClean -ceq '') -and ($a15bNoFlag -ceq 'flag-not-registered=uia-click') -and
    ($a15bGhost -ceq 'flag-registered-missing=ghost') -and ($a15bCount -ceq 'unwrapped=1-want=3') -and
    ($a15bName -ceq 'stub-name=shot=Invoke-Handler-other,handler-orphan=Invoke-Handler-shot') -and
    ($a15bCmd -ceq 'stub-cmdname=shot=shotx') -and ($a15bRest -ceq 'stub-rest=shot=Cmd') -and
    ($a15bInlineGap -ceq 'inline-not-allowed=help') -and ($a15bOrphanGap -ceq 'handler-orphan=Invoke-Handler-orphaned') -and
    ($a15bMarkGap -ceq 'flag-return-unmarked=Invoke-Handler-markme@2') -and ($a15bEscGap -ceq 'flag-escape=Invoke-Handler-escapeme@2') -and
    ($a15bRefGap -ceq 'handler-not-ref=Invoke-Handler-noref=$SkipTail') -and ($a15bNullGap -ceq '-no-parse') -and
    ($a15bAbsentGap -ceq '-absent-body:Invoke-DesktopCommand') -and ($a15bNoSwGap -ceq 'switch-count=0') -and
    ($a15bTwoGap -ceq 'switch-count=2') -and
    ($a15bMap -ceq 'Invoke-Handler-chrome-click/Invoke-Handler-uia-settext'))
  Write-Output ('      A-15b fixtures: clean=[' + $a15bClean + '] no-flag=[' + $a15bNoFlag + '] ghost=[' + $a15bGhost +
    '] count=[' + $a15bCount + '] name=[' + $a15bName + '] cmd=[' + $a15bCmd + '] rest=[' + $a15bRest +
    '] inline=[' + $a15bInlineGap + '] orphan=[' + $a15bOrphanGap + '] unmarked=[' + $a15bMarkGap +
    '] escape=[' + $a15bEscGap + '] no-ref=[' + $a15bRefGap + '] refusals=[' + $a15bNullGap + '/' + $a15bAbsentGap +
    '/' + $a15bNoSwGap + '/' + $a15bTwoGap + '] map=' + $a15bMap)

}

# lib/selftest-window-targeting.ps1 - family window-targeting of the selftest section, lifted out
# of lib/selftest.ps1 by A-14j (A-beta). Bodies are byte-identical to what the section carried.
# Eleven banners in ten gathered pieces: idempotent activation and --expect-change, the anonymous window
# label, the main-window rule as a pure function, the take-a-coordinate ladder, open-and-pick, the
# inverted --region validator, the composite locator, the UIA Chrome exit menu, Resolve-Window
# selector semantics, the uia-tree file route and the CU-REL-01 landing/state guards. State arrives
# only through $Ctx - the help-page line array it reads is the one A-14j hoisted and published, and
# lint (A-14b) names any read that reaches past the handover. Nine pieces from 793..6688 collapse into
# one call: the card counts the resulting reordering by name and position.
function Invoke-SelftestFamily-WindowTargeting($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $self = [string]$Ctx['self']
  $codeLines = $Ctx['codeLines']
  $j5ProdStart = $Ctx['j5ProdStart']
  $j5ProdEnd = $Ctx['j5ProdEnd']
  $hLines = $Ctx['hLines']

  # ---------- unit + lint: v1.5.6 idempotent activation, --always-activate, --expect-change ----------
  $v6On = Split-Target @('10', '20', '--always-activate', '--to', 'Win')
  ST-Check 'unit: --always-activate is parsed as a boolean and does not eat the selector' (
    $v6On.AlwaysActivate -eq $true -and $v6On.Sel -ceq 'Win' -and (@($v6On.Words) -join ' ') -ceq '10 20')
  $v6Off = Split-Target @('10', '20', '--to', 'Win')
  ST-Check 'unit: activation stays idempotent by default (flag absent -> AlwaysActivate false)' (
    $v6Off.AlwaysActivate -eq $false)
  $v6EcRect = Split-Target @('10', '20', '--expect-change', '5,6,70,80', '--to', 'Win')
  ST-Check 'unit: --expect-change takes an optional screen rect and keeps --to intact' (
    $v6EcRect.ExpectChange -ceq '5,6,70,80' -and $v6EcRect.Sel -ceq 'Win')
  $v6EcBare = Split-Target @('10', '20', '--expect-change')
  ST-Check 'unit: bare --expect-change means auto region, not an empty value' ($v6EcBare.ExpectChange -ceq 'auto')
  # a value is consumed only as a rect-looking token; a NON-numeric word after the flag
  # stays where it was, and a number-shaped-but-wrong value is refused rather than
  # quietly reinterpreted (measured in the live round: `--expect-change 1,2,3` used to
  # click with an auto region and leave the bad rect as a stray positional).
  $v6EcStray = Split-Target @('10', '20', '--expect-change', 'extra')
  ST-Check 'unit: --expect-change refuses to swallow a non-rect token (it stays in Words)' (
    $v6EcStray.ExpectChange -ceq 'auto' -and (@($v6EcStray.Words) -join ' ') -ceq '10 20 extra')
  $v6EcBad = ''
  try { [void](Split-Target @('10', '20', '--expect-change', '1,2,3')) } catch { $v6EcBad = $_.Exception.Message }
  ST-Check 'unit: a malformed --expect-change rect is refused by the parser, not silently ignored' (
    $v6EcBad.Contains('--expect-change needs x,y,w,h') -and $v6EcBad.Contains('1,2,3'))
  $v6EcWheel = ''
  try { [void](Split-Target @('10', '20', '--expect-change', '300')) } catch { $v6EcWheel = $_.Exception.Message }
  ST-Check 'unit: a lone number after --expect-change is refused too (ambiguous beats silent)' (
    $v6EcWheel.Contains('--expect-change needs x,y,w,h'))
  $v6Reg = Get-ExpectChangeRegion @{ ExpectChange = '7,8,90,100' } $null
  ST-Check 'unit: an explicit --expect-change rect is taken as screen pixels' (
    $v6Reg.X -eq 7 -and $v6Reg.Y -eq 8 -and $v6Reg.W -eq 90 -and $v6Reg.H -eq 100 -and $v6Reg.Source -ceq '--expect-change rect 7,8,90,100')
  $v6Auto = Get-ExpectChangeRegion @{ ExpectChange = 'auto'; Sel = '' } $null
  ST-Check 'unit: auto with no --to says so and measures the whole virtual screen' (
    $v6Auto.Source -like 'virtual screen*' -and $v6Auto.W -gt 0 -and $v6Auto.H -gt 0)
  # Item2 second half: an explicit rect must WIN over the target rect. A caller that
  # passes 1600,1050,700,200 while the target sits at 959,428 1924x1234 must get the
  # small rect measured, never the full window silently substituted back.
  $v6EcExplicitWins = Get-ExpectChangeRegion @{ ExpectChange = '1600,1050,700,200'; Sel = 'FakeWin' } @{ Left = 959; Top = 428; W = 1924; H = 1234; Title = 'FakeWin' }
  ST-Check 'unit: an explicit --expect-change rect wins over the target rect (given != full window)' (
    $v6EcExplicitWins.X -eq 1600 -and $v6EcExplicitWins.Y -eq 1050 -and $v6EcExplicitWins.W -eq 700 -and $v6EcExplicitWins.H -eq 200 -and
    $v6EcExplicitWins.Source -like '*1600,1050,700,200*')
  # Feedback item 2, first half: the shape that actually arrived in the wild - the rect as
  # ONE quoted argument with spaces, logged verbatim in actions.log 2026-10-10 00:48 UTC -
  # must be CONSUMED and canonicalised, never degraded to the auto region.
  $v6EcSpace = $null
  try { $v6EcSpace = Split-Target @('1658', '1087', '--expect-change', '1600 1050 700 200', '--to', 'Win') } catch { }
  ST-Check 'unit: a space-separated --expect-change rect is consumed and canonicalised, never degraded to auto' (
    ($null -ne $v6EcSpace) -and $v6EcSpace.ExpectChange -ceq '1600,1050,700,200' -and $v6EcSpace.Sel -ceq 'Win' -and
    (@($v6EcSpace.Words) -join ' ') -ceq '1658 1087')
  $v6EcSpaceReg = Get-ExpectChangeRegion @{ ExpectChange = '1600 1050 700 200'; Sel = 'FakeWin' } @{ Left = 959; Top = 428; W = 1924; H = 1234; Title = 'FakeWin' }
  ST-Check 'unit: the expect-change echo reports the rect it really measures, not the window it fell back to' (
    $v6EcSpaceReg.X -eq 1600 -and $v6EcSpaceReg.Y -eq 1050 -and $v6EcSpaceReg.W -eq 700 -and $v6EcSpaceReg.H -eq 200 -and
    $v6EcSpaceReg.Source -ceq '--expect-change rect 1600,1050,700,200')
  $v6EcShort = ''
  try { [void](Split-Target @('10', '20', '--expect-change', '1600 1050 700')) } catch { $v6EcShort = $_.Exception.Message }
  ST-Check 'unit: a three-number rect in either spelling is refused by name instead of degrading to the auto region' (
    $v6EcShort.Contains('--expect-change needs x,y,w,h') -and $v6EcShort.Contains('1600 1050 700'))
  $v6Bad = ''
  try { [void](Get-ExpectChangeRegion @{ ExpectChange = '1,2,3' } $null) } catch { $v6Bad = $_.Exception.Message }
  ST-Check 'unit: a malformed --expect-change rect is refused by name' ($v6Bad -like '--expect-change needs x,y,w,h*')
  # v3.0.1 (audit item 5): a SECOND gate inside the parser rejected what the first gate
  # had just admitted, so an explicit rect on a left-hand monitor (negative X, which is
  # where a dual-monitor layout puts it) could never be passed - while --guard-region and
  # --expect-region, which document the SAME convention, accept it. Width and height stay
  # unsigned: a negative extent has no meaning the tool could honour.
  $v6EcNeg = $null
  try { $v6EcNeg = Split-Target @('10', '20', '--expect-change', '-100,0,50,50', '--to', 'Win') } catch { }
  ST-Check 'unit: a negative --expect-change rect is consumed, not refused (left monitor)' (
    ($null -ne $v6EcNeg) -and $v6EcNeg.ExpectChange -ceq '-100,0,50,50' -and $v6EcNeg.Sel -ceq 'Win' -and (@($v6EcNeg.Words) -join ' ') -ceq '10 20')
  $v6NegReg = Get-ExpectChangeRegion @{ ExpectChange = '-100,20,50,60' } $null
  ST-Check 'unit: a negative --expect-change rect reaches the screen mapping with its sign' (
    $v6NegReg.X -eq -100 -and $v6NegReg.Y -eq 20 -and $v6NegReg.W -eq 50 -and $v6NegReg.H -eq 60)
  $v6EcNegW = ''
  try { [void](Split-Target @('10', '20', '--expect-change', '1,2,-3,4')) } catch { $v6EcNegW = $_.Exception.Message }
  ST-Check 'unit: a NEGATIVE width or height in --expect-change is still refused' (
    $v6EcNegW.Contains('--expect-change needs x,y,w,h'))
  # the three rect-taking flags must speak one signedness, or a call that works on one
  # command throws on another for the same token (measured: --expect-change alone).
  $v6SignOk = $true
  foreach ($v6SignProbe in @('-100,0,50,50', '0,-40,50,50', '-1,-2,3,4')) {
    $v6SignER = $true
    try { [void](Split-Target @('10', '20', '--expect-region', $v6SignProbe)) } catch { $v6SignER = $false }
    $v6SignEC = $true
    try { [void](Split-Target @('10', '20', '--expect-change', $v6SignProbe)) } catch { $v6SignEC = $false }
    $v6SignGR = $true
    try { [void](Split-Target @('10', '20', '--guard-region', ($v6SignProbe + '=needle here'))); } catch { $v6SignGR = $false }
    if (-not ($v6SignER -and $v6SignEC -and $v6SignGR)) { $v6SignOk = $false; Write-Output "      signed-rect disagreement for $v6SignProbe : expect-region=$v6SignER expect-change=$v6SignEC guard-region=$v6SignGR" }
  }
  ST-Check 'contract: expect-region, expect-change and guard-region accept the same signed screen rects' ($v6SignOk)
  # single-source lints: these verdicts must be produced in exactly one place, or a new
  # call site can start claiming "activated" / proving nothing without anyone noticing.
  # Every marker below is ASSEMBLED by concatenation on purpose: a scan line that
  # literally contains its own search string matches itself, and the first draft of
  # these three checks went red on the file's own selftest block.
  $v6ActMark = 'this call activated ' + 'the window'
  $v6ActSite = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($v6ActMark) })
  ST-Check 'lint: the activation NOTICE has exactly one producer (never per-call-site wording)' ($v6ActSite.Count -eq 1)
  # ...and that one producer must be CONDITIONAL: an unconditional NOTICE is printed on
  # every --to, which is noise, and noise is what makes warnings unread. Measured reason:
  # with only the count check above, mutating `if ($w.Activated)` to `if ($true)` stayed
  # green offline - the live case sees it, the fast gate did not.
  $v6CondOk = $false
  for ($v6j = 0; $v6j -lt $codeLines.Count; $v6j++) {
    if ($codeLines[$v6j].Contains($v6ActMark)) {
      for ($v6k = $v6j - 1; $v6k -ge [Math]::Max(0, $v6j - 6); $v6k--) {
        if ($codeLines[$v6k] -match '^\s*if \(' -and $codeLines[$v6k].Contains('Activated')) { $v6CondOk = $true; break }
      }
      break
    }
  }
  ST-Check 'lint: the NOTICE is emitted only under an Activated condition (never per-call noise)' ($v6CondOk -eq $true)
  # !! The contract this round's live run actually BROKE, now pinned: a function that
  # returns an object must not also write to the pipeline. `$tgt = Resolve-Target ...`
  # swallowed the activated= line into $tgt (an array of [string, object]), member
  # enumeration kept $tgt.Handle / $tgt.Pid working so 337 other checks stayed green,
  # and the user never saw the verdict the feature exists to print.
  $rtStart = -1; $rtEnd = $codeLines.Count
  for ($vi = 0; $vi -lt $codeLines.Count; $vi++) { if ($codeLines[$vi] -match '^function Resolve-Target') { $rtStart = $vi; break } }
  if ($rtStart -ge 0) { for ($vi = $rtStart + 1; $vi -lt $codeLines.Count; $vi++) { if ($codeLines[$vi] -match '^function ') { $rtEnd = $vi; break } } }
  $rtWrites = @($codeLines[$rtStart..($rtEnd - 1)] | Where-Object { $_ -notmatch '^\s*#' -and $_ -match '^\s*(Write-Output|Write-Host)\s' })
  ST-Check 'lint: an object-returning resolver (Resolve-Target) writes nothing to the pipeline' ($rtStart -ge 0 -and @($rtWrites).Count -eq 0)
  foreach ($rw in @($rtWrites)) { Write-Output "      pipeline write inside a resolver: $($rw.Trim())" }
  $emitV = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_ -match 'Write-Output \$script:ActivationLine' })
  $emitN = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_ -match 'Write-Output \$script:ActivationNotice' })
  ST-Check 'lint: the activation verdict is printed from exactly one place (Emit-ResolveNote)' (
    @($emitV).Count -eq 1 -and @($emitN).Count -eq 1)
  # v1.5.3 taught this the hard way: a parameter that only lives in the signature.
  $v6FwdPat = 'Resolve-Target \$p\.Sel \$p\.' + 'Force(?! \$p\.AlwaysActivate)'
  $v6NoArg = New-Object System.Collections.ArrayList
  for ($v6i = 0; $v6i -lt $codeLines.Count; $v6i++) {
    if ($codeLines[$v6i] -match '^\s*#') { continue }
    if ($codeLines[$v6i] -match $v6FwdPat) { [void]$v6NoArg.Add($v6i + 1) }
  }
  ST-Check 'lint: every --to call site forwards the rollback switch (no flag that only lives in the signature)' (@($v6NoArg).Count -eq 0)
  foreach ($v6n in @($v6NoArg)) { Write-Output "      Resolve-Target call without --always-activate: line $v6n" }
  $v6Plant = '  $t = Resolve-Target $p.Sel $p.' + 'Force'
  ST-Check 'lint: the forward-check detects a planted two-argument call' ($v6Plant -match $v6FwdPat)
  # X-02: the pinned spelling moved with the code it pins (the step object's optional fields now
  # go through the one reader), and the marker is still split so this scan line cannot match
  # itself. This edits the LITERAL being looked for, NOT the comparison: exactly one site, same as before.
  $v6ScriptMark = 'Resolve-Target (Get-OptValue $s ' + '''to'') ([bool](Get-OptValue $s ''force'')) ([bool](Get-OptValue $s ''alwaysActivate''))'
  $v6ScriptFwd = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($v6ScriptMark) })
  ST-Check 'lint: the script step path forwards alwaysActivate too (its own spelling)' (@($v6ScriptFwd).Count -eq 1)
  # both branches of the proof-of-effect verdict, asserted WITHOUT touching the desktop:
  # this is what makes the offline gate able to see a neutered WARN branch at all.
  $v6BaseSame = @{ X = 5; Y = 6; W = 7; H = 8; Source = 'unit fixture'; Hash = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' }
  $v6Same = Format-ExpectChangeVerdict $v6BaseSame 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' 'clicked'
  $v6Diff = Format-ExpectChangeVerdict $v6BaseSame 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb' 'clicked'
  ST-Check 'unit: a pixel-identical region produces the WARN, and it names the rect it measured' (
    $v6Same -like 'WARN: --expect-change:*' -and $v6Same.Contains('PIXEL-IDENTICAL (md5 aaaa') -and
    $v6Same.Contains('region (5,6) 7x8 from unit fixture'))
  ST-Check 'unit: a changed region reports the two hashes and never claims the WARN' (
    $v6Diff -like 'expect-change: after clicked*' -and $v6Diff.Contains('aaaa') -and $v6Diff.Contains('bbbb') -and
    -not $v6Diff.Contains('PIXEL-IDENTICAL'))
  ST-Check 'unit: the WARN still says it is not proof of failure (opt-in must not over-claim)' (
    $v6Same.Contains('NOT proof of failure'))
  $v6Quiet = @(Invoke-ExpectChangeCheck @{ ExpectChange = '' } $v6BaseSame 'clicked')
  ST-Check 'unit: without the flag the check prints nothing (default off, zero behaviour change)' (@($v6Quiet).Count -eq 0)
  $v6Wired = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains('Invoke-ExpectChangeCheck ') })
  ST-Check 'lint: every action command wires the proof-of-effect (click/rclick/dblclick/drag/find-click/wheel)' ($v6Wired.Count -ge 6)

  # ---------- unit: v1.5.5 (D-8) window label, including the anonymous surfaces ----------
  $wlT = Format-WindowLabel 'Notepad' 'Notepad'
  $wlTaskbar = Format-WindowLabel '' 'Shell_TrayWnd'
  $wlTaskbar2 = Format-WindowLabel '' 'Shell_SecondaryTrayWnd'
  $wlDesk = Format-WindowLabel '' 'Progman'
  $wlDesk2 = Format-WindowLabel '' 'WorkerW'
  $wlClass = Format-WindowLabel '' 'Chrome_WidgetWin_1'
  $wlNone = Format-WindowLabel '' ''
  $wlNull = Format-WindowLabel $null $null
  ST-Check 'unit: a titled covering window is still named verbatim in quotes (D-8 must not hide names)' (
    $wlT -ceq "'Notepad'")
  ST-Check 'unit: the taskbar and the desktop are named as themselves, not as an empty string' (
    $wlTaskbar -ceq '(taskbar)' -and $wlTaskbar2 -ceq '(taskbar)' -and
    $wlDesk -ceq '(desktop)' -and $wlDesk2 -ceq '(desktop)')
  ST-Check 'unit: any other anonymous window falls back to its class name' (
    $wlClass -ceq '(class Chrome_WidgetWin_1)')
  # the whole point of D-8: no combination may render as '' - that is the string that
  # sent people hunting for a window that does not exist.
  ST-Check 'unit: no title/class combination renders as an empty or quote-only label' (
    $wlNone -ceq '(untitled)' -and $wlNull -ceq '(untitled)' -and
    @( @($wlT, $wlTaskbar, $wlDesk, $wlClass, $wlNone) | Where-Object { -not $_ -or $_ -ceq "''" } ).Count -eq 0)

  # ---------- unit: v1.5.7 (D-7) the main-window rule is a pure function, so all of
  # these shapes are provable offline instead of waiting for a live fixture ----------
  $d7Rows = @(
    [pscustomobject]@{ Handle = [IntPtr]1; Pid = 100; Owner = 0; Area = 100 },
    [pscustomobject]@{ Handle = [IntPtr]2; Pid = 100; Owner = 0; Area = 50 },
    [pscustomobject]@{ Handle = [IntPtr]3; Pid = 100; Owner = 1; Area = 1000 },
    [pscustomobject]@{ Handle = [IntPtr]4; Pid = 200; Owner = 5; Area = 10 },
    [pscustomobject]@{ Handle = [IntPtr]5; Pid = 300; Owner = 0; Area = 70 },
    [pscustomobject]@{ Handle = [IntPtr]6; Pid = 300; Owner = 0; Area = 70 }
  )
  $d7Map = Select-MainWindowMap $d7Rows
  ST-Check 'unit: D-7 main map - largest UNOWNED window of a pid is the main one' (
    $d7Map[[int64]1] -ceq 'yes' -and $d7Map[[int64]2] -ceq 'no')
  ST-Check 'unit: D-7 main map - an owned window is never main even when it is far larger' ($d7Map[[int64]3] -ceq 'no')
  ST-Check 'unit: D-7 main map - a pid whose windows all have owners still gets exactly one main' ($d7Map[[int64]4] -ceq 'yes')
  ST-Check 'unit: D-7 main map - equal areas break deterministically (lowest handle)' ($d7Map[[int64]5] -ceq 'yes' -and $d7Map[[int64]6] -ceq 'no')
  $d7Map2 = Select-MainWindowMap @($d7Rows | Sort-Object -Property Area)
  $d7Same = $true
  foreach ($k in @($d7Map.Keys)) { if ($d7Map[$k] -cne $d7Map2[$k]) { $d7Same = $false } }
  ST-Check 'unit: D-7 main map - input order does not change the answer (same rows -> same map)' ($d7Same)
  $d7Picked = @(
    [pscustomobject]@{ Handle = [IntPtr]1; Pid = 100; Owner = 0; Area = 100; W = 10; H = 10; Title = 'MainWin'; Main = 'yes' },
    [pscustomobject]@{ Handle = [IntPtr]2; Pid = 100; Owner = 0; Area = 50; W = 5; H = 5; Title = 'PromoWin'; Main = 'no' },
    [pscustomobject]@{ Handle = [IntPtr]7; Pid = 700; Owner = 0; Area = 9; W = 3; H = 3; Title = 'Alone'; Main = 'yes' }
  )
  $d7Note = Format-NonMainPickNote $d7Picked[1] $d7Picked 'fg'
  ST-Check 'unit: D-7 note fires when a non-main window of a multi-window pid is picked and names the main one' (
    $d7Note.StartsWith('note: pid=100 has a main window handle=1') -and $d7Note.Contains('PromoWin') -and
    $d7Note.Contains('because it is the foreground window of that process'))
  $d7NoteL = Format-NonMainPickNote $d7Picked[1] $d7Picked 'largest'
  ST-Check 'unit: D-7 note states the real basis (largest) instead of blaming the foreground' ($d7NoteL.Contains('it is the largest matching window'))
  $d7NoteMain = Format-NonMainPickNote $d7Picked[0] $d7Picked 'fg'
  ST-Check 'unit: D-7 note is silent when the main window is the one picked' ($d7NoteMain -ceq '')
  $d7NoteSolo = Format-NonMainPickNote $d7Picked[2] $d7Picked 'fg'
  ST-Check 'unit: D-7 note is silent for a single-window process (no ambiguity to report)' ($d7NoteSolo -ceq '')
  # ---------- v2.1.0 (plan doc 1.3): the take-a-coordinate ladder lives IN the tool ----------
  # The ladder existed only as memory in whoever happened to have paid for it, so every
  # new session re-derived it wrong (four eyeballed clicks in one session, each one
  # costing a retry cycle to notice). Counted by KEY SENTENCE, never by line number -
  # numbers drift, this file has been bitten by that repeatedly. The usage page is a
  # here-string (blanked out of $codeLines), so the ladder is scanned in $hLines.
  $hLadderKey = 'Taking a coordinate off the screen - the ORDER'
  $hLadderHeader = @($hLines | Where-Object { $_.StartsWith('    ' + $hLadderKey) }).Count
  $hLadderMentions = @($hLines | Where-Object { $_.Contains($hLadderKey) }).Count
  $hPage = @($hLines) -join "`n"
  $hStep1 = $hPage.IndexOf('1  find <text>')
  $hStep2 = $hPage.IndexOf('2  uia-find')
  $hStep3 = $hPage.IndexOf('3  find-text / find-click')
  $hStep4 = $hPage.IndexOf('4  imgclick')
  # the four numbered lines start with command tokens, so Format-CommandHelp reads them as
  # entry headers and the ladder itself is NOT part of any single command's block - find's
  # entry therefore POINTS at the ladder, and that pointer is what per-command help shows.
  $hFindEntry = (@(Format-CommandHelp $hLines 'find') -join "`n")
  ST-Check 'unit: the help page carries the coordinate ladder exactly once, in find > uia-find > find-text > imgclick order, and help find points at it (plan 1.3)' (
    ($hLadderHeader -eq 1) -and ($hLadderMentions -eq 2) -and ($hStep1 -ge 0) -and ($hStep1 -lt $hStep2) -and ($hStep2 -lt $hStep3) -and ($hStep3 -lt $hStep4) -and
    $hFindEntry.Contains($hLadderKey))
  # Telling people NOT to eyeball a downscaled image without naming the road is how they
  # keep eyeballing it - both warnings must point at imgclick and at the .map.txt that is
  # already sitting next to the capture they just took.
  $hImgclickWarn = 0; $hMapWarn = 0; $hWarnSites = 0
  for ($hl = 0; $hl -lt $codeLines.Count; $hl++) {
    if ($hl -ge $j5ProdStart -and $hl -lt $j5ProdEnd) { continue }
    if ($codeLines[$hl] -match '^\s*#') { continue }
    if ($codeLines[$hl].Contains('DOWNSCALE this image') -or $codeLines[$hl].Contains('downscale it once more')) {
      $hWarnSites++
      if ($codeLines[$hl].Contains('imgclick')) { $hImgclickWarn++ }
      if ($codeLines[$hl].Contains('.map.txt')) { $hMapWarn++ }
    }
  }
  ST-Check 'lint: both downscaled-image warnings name imgclick AND the .map.txt beside the capture (forbid-the-guess without naming-the-road is the shape that keeps failing)' (
    ($hWarnSites -eq 2) -and ($hImgclickWarn -eq 2) -and ($hMapWarn -eq 2))
  Write-Output ("      coordinate ladder: header=$hLadderHeader mentions=$hLadderMentions steps=$hStep1/$hStep2/$hStep3/$hStep4 warn-sites=$hWarnSites imgclick=$hImgclickWarn map=$hMapWarn")

  # ---------- unit: v1.6.0 A-1 open-and-pick - parsing and refusal shapes (offline) ----------
  # The click/shoot/OCR chain needs a live desktop; everything BEFORE Resolve-Target is
  # provable here by invoking the real dispatcher and catching its refusals (a throw in a
  # unit is caught per the abort-vs-fail rule, never allowed to kill the gate).
  $opBad = 'NOT-THROWN'
  try { Parse-OpenPickRegion '10,20' | Out-Null } catch { $opBad = $_.Exception.Message }
  ST-Check 'unit: open-and-pick --region refuses a three-number spec by name' ($opBad.Contains('open-and-pick: --region needs x,y,w,h'))
  $opZero = 'NOT-THROWN'
  try { Parse-OpenPickRegion '10,20,0,50' | Out-Null } catch { $opZero = $_.Exception.Message }
  ST-Check 'unit: open-and-pick --region refuses a zero width/height' ($opZero.Contains('width/height must be > 0'))
  ST-Check 'unit: open-and-pick --region absent means the whole window (null, not an empty scan)' ($null -eq (Parse-OpenPickRegion ''))
  $opR = 'THREW'
  try { $opR = Parse-OpenPickRegion '10,20,300,120' } catch { $opR = 'THREW: ' + $_.Exception.Message }
  ST-Check 'unit: open-and-pick --region parses to a window-relative rect' (
    ($opR -isnot [string]) -and $opR.X -eq 10 -and $opR.Y -eq 20 -and $opR.W -eq 300 -and $opR.H -eq 120)
  $opShort = 'NO-THROW'
  try { Invoke-DesktopCommand 'open-and-pick' @('Notepad', '10', '20') | Out-Null } catch { $opShort = $_.Exception.Message }
  ST-Check 'unit: open-and-pick refuses to run with fewer than four positional arguments (usage names the shape)' ($opShort.Contains('usage: open-and-pick <sel> <opener-x> <opener-y> <needle...>'))
  $opNeedle = 'NO-THROW'
  try { Invoke-DesktopCommand 'open-and-pick' @('Notepad', '10', '20', '') | Out-Null } catch { $opNeedle = $_.Exception.Message }
  ST-Check 'unit: open-and-pick refuses an empty needle before anything is clicked' ($opNeedle -eq 'open-and-pick: empty needle')
  $opRegion = 'NO-THROW'
  try { Invoke-DesktopCommand 'open-and-pick' @('Notepad', '10', '20', 'x', '--region', 'bad') | Out-Null } catch { $opRegion = $_.Exception.Message }
  ST-Check 'unit: open-and-pick refuses a malformed --region before anything is clicked' ($opRegion.Contains('--region needs x,y,w,h'))
  $opCoords = 'NO-THROW'
  try { Invoke-DesktopCommand 'open-and-pick' @('Notepad', 'left', '20', 'File') | Out-Null } catch { $opCoords = $_.Exception.Message }
  ST-Check 'unit: open-and-pick refuses non-integer opener coordinates' ($opCoords.Contains('opener coordinates must be integers'))
  $opStrip = Strip-OwnFlags @('--region', '5,6,70,80', '--expect', 'Done', 'Notepad', '10', '20', 'File') 'open-and-pick'
  ST-Check 'unit: open-and-pick strips --region as a raw value and passes the expect family through to Split-Target' (
    "$((Get-OptValue $opStrip 'Values')['--region'])" -ceq '5,6,70,80' -and $opStrip.Present['--region'] -and (@($opStrip.Rest) -contains '--expect'))

  # ---------- unit+lint: v2.3.0 red-3 - find --region's inverted validator (real machine 2026-10-02) ----------
  # The shipped inline check demanded "count of non-numeric segments == 4": every VALID
  # x,y,w,h threw the named error and garbage like a,b,c,d sailed through to die at the
  # [int] cast (both shapes reproduced live on this machine, evidence archived in
  # .cowork-temp/zq-red-find-region-inverted.md). The extracted parser above is now the
  # single pure producer of both refusals; these checks hold it directly, and the two
  # lints keep the handler from ever growing a second copy of the logic. The lint needle
  # is built by concatenation so no scan line contains its own search string.
  $frOk = 'THREW'
  try { $frOk = Parse-FindRegionSpec '100,100,50,30' } catch { $frOk = 'THREW: ' + $_.Exception.Message }
  ST-Check 'unit: find --region accepts a legal x,y,w,h and parses every field (red-3 fix)' (
    ($frOk -isnot [string]) -and $frOk.X -eq 100 -and $frOk.Y -eq 100 -and $frOk.W -eq 50 -and $frOk.H -eq 30)
  $frNeg = 'THREW'
  try { $frNeg = Parse-FindRegionSpec '-10,-5,50,30' } catch { $frNeg = 'THREW: ' + $_.Exception.Message }
  ST-Check 'unit: find --region keeps negative x/y legal (the original character class allowed them)' (
    ($frNeg -isnot [string]) -and $frNeg.X -eq -10 -and $frNeg.Y -eq -5)
  $frBad = 'NOT-THROWN'
  try { Parse-FindRegionSpec 'a,b,50,30' | Out-Null } catch { $frBad = $_.Exception.Message }
  ST-Check 'unit: find --region refuses a non-numeric segment by name (it used to slip through)' ($frBad.Contains('find: --region needs x,y,w,h in screen pixels'))
  $frZero = 'NOT-THROWN'
  try { Parse-FindRegionSpec '100,100,0,30' | Out-Null } catch { $frZero = $_.Exception.Message }
  ST-Check 'unit: find --region still refuses a zero width' ($frZero.Contains('find: --region w/h must be positive'))
  $frThree = 'NOT-THROWN'
  try { Parse-FindRegionSpec '1,2,3' | Out-Null } catch { $frThree = $_.Exception.Message }
  $frFive = 'NOT-THROWN'
  try { Parse-FindRegionSpec '1,2,3,4,5' | Out-Null } catch { $frFive = $_.Exception.Message }
  ST-Check 'unit: find --region refuses segment counts other than four (three and five both tried)' (
    $frThree.Contains('find: --region needs x,y,w,h in screen pixels') -and $frFive.Contains('find: --region needs x,y,w,h in screen pixels'))
  $frDefNeedle = 'function Parse-' + 'FindRegionSpec'
  $frDefSites = @([regex]::Matches((@($codeLines) -join "`n"), $frDefNeedle)).Count
  ST-Check 'lint: find --region validation has exactly one definition (single-producer rule)' (
    $frDefSites -eq 1)
  $frCallNeedle = '= Parse-' + 'FindRegionSpec \$fRegion'
  $frCallSites = @([regex]::Matches((@($codeLines) -join "`n"), $frCallNeedle)).Count
  ST-Check 'lint: the find handler is the one production caller of the extracted --region parser' (
    $frCallSites -eq 1)
  $frInlineNeedle = '\$f' + 'Region -split'
  $frInline = @([regex]::Matches((@($codeLines) -join "`n"), $frInlineNeedle)).Count
  ST-Check 'lint: the inverted inline --region split is gone from the find handler (zero copies left)' (
    $frInline -eq 0)

  # ---------- v2.1.0 (plan doc 1.1): the composite locator 'find' ----------
  # The rule under test is WHICH ROAD ANSWERED, so every cell is pinned in both
  # directions: a UIA hit must win and must not be relabelled, an OCR-only answer must
  # be marked degraded (that is the whole point of the field), and the two-zeroes cell
  # must refuse with both volumes in the message. The message is checked as RENDERED
  # text - a miss line that names one road and not the other is the shape that lets a
  # caller conclude 'the text is not there' from a scan that never looked properly.
  $f12Uia = Get-FindSourceDecision 1 0
  ST-Check 'unit: find source decision - a UIA hit answers as uia and is never called a degradation' (
    ($f12Uia.Source -ceq 'uia') -and (-not $f12Uia.Degraded) -and (-not $f12Uia.Refuse))
  $f12UiaWins = Get-FindSourceDecision 1 5
  ST-Check 'unit: find source decision - OCR finding more lines does NOT steal the answer from UIA (road order, not hit count)' (
    $f12UiaWins.Source -ceq 'uia')
  $f12Ocr = Get-FindSourceDecision 0 3
  ST-Check 'unit: find source decision - UIA empty with OCR hits is source=ocr AND degraded=true (a silent fallback is the bug this field exists to prevent)' (
    ($f12Ocr.Source -ceq 'ocr') -and $f12Ocr.Degraded -and (-not $f12Ocr.Refuse))
  $f12None = Get-FindSourceDecision 0 0
  ST-Check 'unit: find source decision - both roads empty refuses, it never reports a source that produced nothing' (
    ($f12None.Source -ceq 'none') -and $f12None.Refuse)
  $f12Miss = Format-FindMiss 'QXABSENTTEXT' 14 'walks=2 cold-zero-reprobe=yes -> still 0 (scanned=14)' 7 'no retry ran' '(100,200) 420x240' '; occluded=0%'
  ST-Check 'unit: find miss text names BOTH roads with what each one measured (never a bare not-found)' (
    ($f12Miss.Contains('uia scanned 14 element(s)')) -and ($f12Miss.Contains('OCR read 7 line(s)')) -and
    ($f12Miss.Contains('walks=2')) -and ($f12Miss.Contains('no retry ran')) -and ($f12Miss.Contains("NOT 'absent'")))
  $f12Env = New-FindJsonEnvelope 'ocr' 'target=pid=7 region=(1,2,3x4) via=target' $null @(@{ road = 'ocr'; text = 'x' })
  $f12Keys = (@($f12Env.PSObject.Properties.Name) | Sort-Object) -join ','
  $f12Want = @(Get-FindJsonTopKeys | Sort-Object) -join ','
  ST-Check 'contract: find --json key set is exactly what Get-FindJsonTopKeys lists (source is a REQUIRED key of this envelope; the phrase "keys are exactly" stays owned by the two OCR contracts)' (
    ($f12Keys -ceq $f12Want) -and ($f12Keys.Contains('source')) -and ([int]$f12Env.schemaVersion -eq [int]$script:JsonSchemaVersion))
  $f12Probe = ($f12Env | ConvertTo-Json -Compress -Depth 5 | ConvertFrom-Json)
  ST-Check 'contract: find --json keeps hits an ARRAY for one hit (a scalar here silently breaks every consumer that iterates it)' (
    @($f12Probe.hits).Count -eq 1 -and ($f12Probe.hits[0].road -ceq 'ocr'))
  # find's own envelope must not be the OCR envelope: the two published key sets stay frozen.
  # v3.0.0 (B-6) updated this literal ON PURPOSE: contentTrust joined the OCR envelope and the
  # schema version moved with it, which is exactly the "bump it in the same commit" bookkeeping
  # the envelope comment demands. The inequality half is the part that still guards find.
  $f12OcrEnvKeys = (@((New-OcrJsonEnvelope 'hits' $null @()).PSObject.Properties.Name) | Sort-Object) -join ','
  ST-Check 'contract: adding find did not touch the published find-text/read-text key sets (the OCR envelope is still a different shape from find, whatever B-6 added to both)' (
    ($f12OcrEnvKeys -ceq (Get-JsonContractKeySet 'find')) -and ($f12OcrEnvKeys -ne $f12Want))
  # one producer per decision, and the road is never re-derived by hand in the handler
  $f12Decide = 0; $f12DegradedEcho = 0; $f12SourceEcho = 0
  for ($f12i = 0; $f12i -lt $codeLines.Count; $f12i++) {
    if ($f12i -ge $j5ProdStart -and $f12i -lt $j5ProdEnd) { continue }
    if ($codeLines[$f12i] -match '^\s*#') { continue }
    if ($codeLines[$f12i].Contains('= Get-FindSourceDecision ')) { $f12Decide++ }
    if ($codeLines[$f12i].Contains('falling back to OCR on the same rect')) { $f12DegradedEcho++ }
    if ($codeLines[$f12i].Contains('find: source=$($fDecision.Source)') -or $codeLines[$f12i].Contains('find: source=uia ') -or $codeLines[$f12i].Contains('find: source=ocr ')) { $f12SourceEcho++ }
  }
  ST-Check 'lint: find decides its source through one producer, announces the fallback exactly once, and echoes the source per road (no hand-rolled second opinion)' (
    ($f12Decide -eq 2) -and ($f12DegradedEcho -eq 1) -and ($f12SourceEcho -eq 2))
  Write-Output ("      find wiring: decision-sites=$f12Decide fallback-echo=$f12DegradedEcho source-echo=$f12SourceEcho")
  # Literal name matching. -like turned '[', ']' and '*' inside a control's own Name into
  # wildcards, so the element could not be found by the very string the tool printed.
  $c18Cases = @(
    @('TELEBOT [main] window', '[main]', $true),
    @('a*b', '*', $true),
    @('QXHELLO', 'qxhello', $true),
    @('plain name', 'xyz', $false),
    @('anything', '', $false),
    @('', 'x', $false)
  )
  $c18Bad = ''
  foreach ($c18c in $c18Cases) {
    $c18Got = $false
    try { $c18Got = [bool](Test-NameSubstring $c18c[0] $c18c[1]) } catch { $c18Got = 'THREW' }
    if ($c18Got -ne $c18c[2]) { $c18Bad = "name='$($c18c[0])' needle='$($c18c[1])' -> $c18Got, expected $($c18c[2])" }
  }
  ST-Check 'unit: UIA and tab name matching is literal - brackets and * inside a Name match themselves, an empty needle matches nothing, case stays insensitive' ($c18Bad -eq '')
  $c19Q = [string][char]34
  $c19Bad = New-Object System.Collections.ArrayList
  for ($c19i = 0; $c19i -lt $codeLines.Count; $c19i++) {
    if ($c19i -ge $j5ProdStart -and $c19i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c19i] -match '^\s*#') { continue }
    if ($codeLines[$c19i].Contains(('-like ' + $c19Q + '*$($Rest[1])*' + $c19Q)) -or $codeLines[$c19i].Contains(('-like ' + $c19Q + '*$nameSub*' + $c19Q))) { [void]$c19Bad.Add($c19i + 1) }
  }
  ST-Check 'lint: no uia-family command matches an element Name with -like any more (wildcards inside a Name made the Name unfindable)' (
    @($c19Bad).Count -eq 0)
  if (@($c19Bad).Count -gt 0) { Write-Output "      -like name matches left at lines: $(@($c19Bad) -join ', ')" }
  $c15Mark = ('Uia-WalkAll @($r0) ' + '$maxDepth')
  $c15Depth = 0
  for ($c15i = 0; $c15i -lt $codeLines.Count; $c15i++) { if ($codeLines[$c15i].Contains($c15Mark)) { $c15Depth++ } }
  # mark assembled, not literal: written plainly this search string also appears on
  # the scanning line itself and the count silently becomes 2 (this repo has been
  # bitten by that three times in one day).
  $c15FeedMark = ('Measure-A11yTree $w ' + '$bigDepth')
  $c15Feed = 0
  for ($c15i = 0; $c15i -lt $codeLines.Count; $c15i++) { if ($codeLines[$c15i].Contains($c15FeedMark)) { $c15Feed++ } }
  Write-Output ("      depth call sites: walker=" + $c15Depth + " probe=" + $c15Feed)
  ST-Check 'lint: a11y-probe depth reaches the walker, and Uia-WalkAll honours it (a knob that changes nothing is a fake flag)' (
    # 2 feed sites since A-6b: a11y-probe's first measurement and its cold-zero re-probe
    ($c15Depth -eq 1) -and ($c15Feed -eq 2))
  # A cold 'collapsed' must be re-measured before it becomes a verdict (A-6b: the first
  # UIA contact after a Chrome start reads 0 because that contact is what enables the
  # tree). Marks assembled by concatenation so this scan cannot satisfy itself.
  $c20MeasureMark = ('= Measure-A11yTree $w ') + '$bigDepth'
  $c20AdoptMark = 'if ($m2.PageHits -gt 0) { $m = $m2 }'
  $c20EchoMark = 'cold-zero-re' + 'probe='
  $c20Sites = 0; $c20Adopt = 0; $c20Echo = 0
  for ($c20i = 0; $c20i -lt $codeLines.Count; $c20i++) {
    if ($c20i -ge $j5ProdStart -and $c20i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c20i] -match '^\s*#') { continue }
    if ($codeLines[$c20i].Contains($c20MeasureMark)) { $c20Sites++ }
    if ($codeLines[$c20i].Contains($c20AdoptMark)) { $c20Adopt++ }
    if ($codeLines[$c20i].Contains($c20EchoMark)) { $c20Echo++ }
  }
  ST-Check 'lint: a11y-probe re-measures a collapsed page area before calling it collapsed, and self-reports that it did (cold-start zeros are not verdicts)' (
    # echo 1 -> 2 on 2026-10-01 (uia-find gained the same cold-start re-contact, plan 1.2)
    # and 2 -> 3 the same day (find's UIA road carries it too, plan 1.1). Expected value
    # follows a new measurement point - the strictness of the check is unchanged (same
    # precedent as the v1.8.0 3->4 / 1->2 count updates: the expected value moved, the
    # strictness did not).
    ($c20Sites -eq 2) -and ($c20Adopt -eq 1) -and ($c20Echo -eq 3))
  Write-Output "      a11y re-probe: measure-sites=$c20Sites adopt=$c20Adopt echo=$c20Echo"

  # ---------- option B: the UIA-driven Chrome exit menu (owner ruling 2026-09-30 22:0x) ----------
  # The exit menu is destructive when misread (sign-out sits one glyph away from quit), so
  # both selectors must refuse instead of guessing. These units feed synthetic rows; the
  # real menu is only opened by live runs. CJK corpus entries are code-point assembled -
  # this file stays pure ASCII beyond its BOM, and a GBK-rotted literal would still pass
  # an equality test written the same rotted way.
  $c30QuitBrowser = [string]([char]0x9000) + [char]0x51FA + [char]0x6D4F + [char]0x89C8 + [char]0x5668   # quit browser (5 glyphs)
  $c30QuitAccel = [string]([char]0x9000) + [char]0x51FA + '(X)'   # quit(X) - label as read on Chrome 154 zh-CN
  $c30SignOut = [string]([char]0x9000) + [char]0x51FA + [char]0x767B + [char]0x5F55   # sign out - must never satisfy an exit needle
  $c30Row = { param($ct, $nm, $x, $y, $w, $h) [pscustomobject]@{ ControlType = $ct; Name = $nm; X = $x; Y = $y; W = $w; H = $h } }
  # The 4-row corpus carries BOTH accident shapes the handover names: a TabItem titled
  # "<page> - Google Chrome" (never reaches the Name filter - the control-type filter
  # drops it first) and a BUTTON whose Name merely CONTAINS Chrome (the row substring
  # matching would actually select; exact matching must not).
  $c30Pick = Select-ChromeMenuButton @((& $c30Row 'Button' 'Chrome' 1700 160 46 30), (& $c30Row 'TabItem' 'TELEBOT console - Google Chrome' 600 160 300 30), (& $c30Row 'Button' 'TELEBOT console - Google Chrome' 600 200 300 30), (& $c30Row 'Text' 'Chrome' 0 0 100 20))
  ST-Check 'unit: Select-ChromeMenuButton picks the one Button named exactly Chrome and ignores a button or tab whose name merely contains Chrome' (
    $c30Pick.Ok -and ($c30Pick.Index -eq 0) -and ($c30Pick.Candidates -eq 1))
  $c30Two = Select-ChromeMenuButton @((& $c30Row 'Button' 'Chrome' 1700 160 46 30), (& $c30Row 'Button' 'Chrome' 1700 200 46 30))
  ST-Check 'unit: Select-ChromeMenuButton refuses two same-name buttons and reports the candidate count' (
    (-not $c30Two.Ok) -and ($c30Two.Candidates -eq 2))
  $c30Tab = Select-ChromeMenuButton @((& $c30Row 'TabItem' 'TELEBOT console - Google Chrome' 600 160 300 30))
  ST-Check 'unit: Select-ChromeMenuButton refuses when only a tab name contains Chrome, and says how many rows it swept' (
    (-not $c30Tab.Ok) -and ($c30Tab.Reason.Contains('among 1 row(s)')))
  $c30Text = Select-ChromeMenuButton @((& $c30Row 'Text' 'Chrome' 0 0 100 20))
  ST-Check 'unit: Select-ChromeMenuButton needs the Button control type (a Text named Chrome is not the app menu)' (-not $c30Text.Ok)
  $c30Zero = Select-ChromeMenuButton @()
  ST-Check 'unit: Select-ChromeMenuButton on an empty row set refuses and reports among 0 row(s)' (
    (-not $c30Zero.Ok) -and ($c30Zero.Reason.Contains('among 0 row(s)')))
  $c30Flat = Select-ChromeMenuButton @((& $c30Row 'Button' 'Chrome' 1700 160 0 0))
  ST-Check 'unit: Select-ChromeMenuButton drops zero-rect rows (an empty BoundingRectangle arrives as W/H 0 and is filtered, not crashed on)' (
    (-not $c30Flat.Ok) -and ($c30Flat.Reason.Contains('among 1 row(s)')))
  $c31Zh = Find-ChromeExitItem @('new tab', $c30QuitBrowser)
  ST-Check 'unit: Find-ChromeExitItem matches the full localized quit label' (
    $c31Zh.Ok -and ($c31Zh.Name -eq $c30QuitBrowser))
  $c31Accel = Find-ChromeExitItem @('new tab', 'zoom', $c30QuitAccel)
  ST-Check 'unit: Find-ChromeExitItem matches the access-key quit label read on this build (Chrome 154 zh-CN)' (
    $c31Accel.Ok -and ($c31Accel.Name -eq $c30QuitAccel))
  $c31En = Find-ChromeExitItem @('history', 'Exit')
  ST-Check 'unit: Find-ChromeExitItem matches the plain English Exit label' (
    $c31En.Ok -and ($c31En.Name -eq 'Exit'))
  $c31Sign = Find-ChromeExitItem @($c30SignOut)
  ST-Check 'unit: Find-ChromeExitItem refuses a menu that only offers sign-out (a bare quit stem would click it)' (-not $c31Sign.Ok)
  $c31Amb = Find-ChromeExitItem @('Exit', 'Exit the app')
  ST-Check 'unit: Find-ChromeExitItem refuses two items sharing one exit needle' (
    (-not $c31Amb.Ok) -and ($c31Amb.Reason.Contains('2 menu items contain the same exit needle')))
  $c31Empty = Find-ChromeExitItem @()
  $c31Miss = Find-ChromeExitItem @('new tab', 'settings')
  ST-Check 'unit: Find-ChromeExitItem empty read is its own refusal, distinct from scanned-but-no-match' (
    (-not $c31Empty.Ok) -and $c31Empty.Reason.Contains('no menu item names were read at all') -and
    (-not $c31Empty.Reason.Contains('matched any exit needle')) -and
    (-not $c31Miss.Ok) -and $c31Miss.Reason.Contains('no menu item matched any exit needle'))
  # Wiring of the close chain: option B sits between browser-close and WM_CLOSE, and
  # WM_CLOSE must stay guarded so a successful exit-menu click is never followed by a
  # second close signal (ruling 1: no blind accelerators, and never force-kill chrome).
  $c33Q = "'"
  $c33UiaMark = '$r.CloseVia = ' + $c33Q + 'uia-' + 'exit-menu' + $c33Q
  $c33WmMark = '$r.CloseVia = ' + $c33Q + 'wm-' + 'close' + $c33Q
  $c33GuardMark = '$r.CloseVia -ne ' + $c33Q + 'browser-' + 'close' + $c33Q + ' -and ' + '$r.CloseVia -ne ' + $c33Q + 'uia-' + 'exit-menu' + $c33Q + ')'
  $c33NoteMark = ('close-' + 'note=')
  $c33CommitMark = ('Invoke-Chrome' + 'ExitMenu ')
  $c33UiaN = 0; $c33WmN = 0; $c33GuardN = 0; $c33CommitN = 0; $c33NoteN = 0
  for ($c33i = 0; $c33i -lt $codeLines.Count; $c33i++) {
    if ($c33i -ge $j5ProdStart -and $c33i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c33i] -match '^\s*#') { continue }
    if ($codeLines[$c33i].Contains($c33UiaMark)) { $c33UiaN++ }
    if ($codeLines[$c33i].Contains($c33WmMark)) { $c33WmN++ }
    if ($codeLines[$c33i].Contains($c33GuardMark)) { $c33GuardN++ }
    if ($codeLines[$c33i].Contains($c33CommitMark) -and $codeLines[$c33i].Contains('-Commit')) { $c33CommitN++ }
    if ($codeLines[$c33i].Contains($c33NoteMark)) { $c33NoteN++ }
  }
  ST-Check 'lint: the restart close chain wires the exit-menu route (exactly one uia-exit-menu and one wm-close CloseVia, and the wm-close guard excludes both graceful paths)' (
    ($c33UiaN -eq 1) -and ($c33WmN -eq 1) -and ($c33GuardN -eq 1))
  ST-Check 'lint: Invoke-ChromeExitMenu commits at exactly one production site (reading the menu must never click; only the restart commits)' ($c33CommitN -eq 1)
  ST-Check 'lint: both restart consumers self-report close-note= (the operator reads how the browser actually closed)' ($c33NoteN -eq 2)
  # Two defects W-0 caught on the first real chrome-menu-read run, each nailed where it
  # was born: the bare namespace type literal (PS 5.1 cannot resolve it) and the
  # unguarded [int] cast of an empty BoundingRectangle (Infinity overflows Int32).
  $c32BareMark = ('[System.Windows.' + 'Automation]::')
  $c32BareList = New-Object System.Collections.ArrayList
  $c32Kill = 0
  for ($c32i = 0; $c32i -lt $codeLines.Count; $c32i++) {
    if ($c32i -ge $j5ProdStart -and $c32i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c32i] -match '^\s*#') { continue }
    if ($codeLines[$c32i].Contains($c32BareMark)) { [void]$c32BareList.Add($c32i + 1) }
    if ($codeLines[$c32i].ToLowerInvariant().Contains('chrome') -and ($codeLines[$c32i] -match 'Stop-Process|taskkill')) { $c32Kill++ }
  }
  ST-Check 'lint: no bare [System.Windows.Automation] type literal (PS 5.1 cannot resolve it - option B died on this before its first menu read)' (
    @($c32BareList).Count -eq 0)
  if (@($c32BareList).Count -gt 0) { Write-Output "      bare automation type literals at lines: $(@($c32BareList) -join ', ')" }
  $c32GuardMark = ('-not $br.' + 'IsEmpty')
  $c32Gbs = -1; $c32Gbe = $codeLines.Count
  for ($c32i = 0; $c32i -lt $codeLines.Count; $c32i++) {
    if ($codeLines[$c32i].StartsWith('function Get-ChromeMenuButton')) { $c32Gbs = $c32i; continue }
    if (($c32Gbs -ge 0) -and ($c32i -gt $c32Gbs) -and ($codeLines[$c32i] -match '^function ')) { $c32Gbe = $c32i; break }
  }
  $c32GuardCount = 0
  if ($c32Gbs -ge 0) { for ($c32i = $c32Gbs; $c32i -lt $c32Gbe; $c32i++) { if ($codeLines[$c32i].Contains($c32GuardMark)) { $c32GuardCount++ } } }
  ST-Check 'lint: the menu-button walk converts BoundingRectangle only behind the IsEmpty guard (Rect.Empty carries Infinity and the [int] cast of it killed the whole call)' (
    ($c32Gbs -ge 0) -and ($c32GuardCount -eq 1))
  ST-Check 'lint: chrome.exe is never force-killed (owner ruling 4: killing loses the session and leaves a headless debug-port holder)' ($c32Kill -eq 0)
  # v2.2.0 (R5-C): a BARE dollar-variable-dot-member inside a double-quoted string does NOT
  # interpolate in PS 5.1 - it emits the variable, then the literal member text, so this CDP
  # error line printed a TYPE NAME instead of what the page returned. Narrow pin on purpose: a
  # whole-file traversal for this shape is not sound, because "$base + a literal .ext"
  # concatenations (like the imgclick map line) are intentional and are 5 of the 7 matches the
  # naive scanner reports - the negative finding is registered in the iteration log.
  $cDqMark = ('page returned ' + 'non-JSON')
  # v3.0.1 (audit #24) moved the size behind a computed variable, because a null page
  # value has no .Length and the message used to print an empty field. The shape this pin
  # protects is unchanged - the size enters the message through a SUBEXPRESSION, never as
  # a bare $r.Value.Length - so only the marker's name followed the code.
  $cDqInterpMark = ('$($cdpVal' + 'Len)')
  $cDqQuietMark = ('page text ' + 'not echoed')
  $cDqBareMark = (': $' + 'r.Value"')
  $cDqSites = 0; $cDqInterp = 0; $cDqQuiet = 0; $cDqBare = 0
  for ($c32i = 0; $c32i -lt $codeLines.Count; $c32i++) {
    if ($codeLines[$c32i] -match '^\s*#') { continue }
    if ($codeLines[$c32i].Contains($cDqMark)) { $cDqSites++ }
    if ($codeLines[$c32i].Contains($cDqInterpMark)) { $cDqInterp++ }
    if ($codeLines[$c32i].Contains($cDqQuietMark)) { $cDqQuiet++ }
    if ($codeLines[$c32i].Contains($cDqBareMark)) { $cDqBare++ }
  }
  ST-Check 'lint: the CDP non-JSON message interpolates through a subexpression and carries only a char count (a bare dollar-r-dot-Value in a double-quoted string prints the TYPE NAME - PS 5.1 does not resolve member access there), and page text never enters an error line' (
    ($cDqSites -eq 1) -and ($cDqInterp -eq 1) -and ($cDqQuiet -eq 1) -and ($cDqBare -eq 0))
  if ($cDqSites -ne 1) { Write-Output "      CDP non-JSON message sites: $cDqSites (expected exactly 1)" }
  Write-Output ("      exit-menu wiring: uia-close=$c33UiaN wm-close=$c33WmN guard=$c33GuardN commit-sites=$c33CommitN close-note=$c33NoteN kill-lines=$c32Kill")

  # ---------- v1.11.0: Resolve-Window selector semantics go literal (owner ruling 3) ----------
  # The four contrast groups the owner named, fed as a synthetic window list through the
  # extracted pure selector. Each group has BOTH directions: the literal needle must find
  # its window, and the wildcard READING of the same needle must find nothing any more.
  $c42Win = { param($p, $pr, $cl, $ttl) [pscustomobject]@{ Pid = $p; Proc = $pr; Class = $cl; Title = $ttl; Handle = [IntPtr]$p; W = 100; H = 50; Area = 5000; Main = 'yes' } }
  $c42All = @(
    (& $c42Win 111 'notepad' 'Notepad' 'TELEBOT [main] - work'),
    (& $c42Win 222 'explorer' 'Chrome_WidgetWin_1' 'a*b archive'),
    (& $c42Win 333 'app' 'X?Y' 'settings q?x panel'),
    (& $c42Win 444 'chrome' 'Chrome_WidgetWin_1' 'TELEBOT console - Google Chrome')
  )
  $c42Pick = { param($sel) @((Select-WindowsBySelector $c42All $sel).Matches | ForEach-Object { $_.Pid }) }
  $c42Bad = ''
  if (@(& $c42Pick 't:[main]') -ne 111) { $c42Bad = 't:[main]' }
  if (@(& $c42Pick '[main]') -ne 111) { $c42Bad = "$c42Bad [main]" }
  if (@(& $c42Pick 't:[ma*n]').Count -ne 0) { $c42Bad = "$c42Bad [ma*n]-must-not-match" }
  if (@(& $c42Pick 'a*b') -ne 222) { $c42Bad = "$c42Bad a*b" }
  if (@(& $c42Pick 't:axb').Count -ne 0) { $c42Bad = "$c42Bad axb-must-not-match" }
  if (@(& $c42Pick 'q?x') -ne 333) { $c42Bad = "$c42Bad q?x" }
  if (@(& $c42Pick 't:qax').Count -ne 0) { $c42Bad = "$c42Bad qax-must-not-match" }
  if (@(& $c42Pick '[MAIN]') -ne 111) { $c42Bad = "$c42Bad case" }
  $c42ClsBad = ''
  if ((@(& $c42Pick 'class:WidgetWin') -join ',') -ne '222,444') { $c42ClsBad = 'class substring' }
  if (@(& $c42Pick 'class:Widget?in').Count -ne 0) { $c42ClsBad = "$c42ClsBad class-wildcard" }
  if (@(& $c42Pick 'proc:CHROME') -ne 444) { $c42ClsBad = "$c42ClsBad proc" }
  if (@(& $c42Pick '222') -ne 222) { $c42ClsBad = "$c42ClsBad pid" }
  if ((@(& $c42Pick 'class:WidgetWin') -join ',') -eq '222, 444') { $c42ClsBad = 'join-shape' }
  $c42EmptyThrows = 0
  foreach ($c42e in @('t:', 'title:   ', 'class:')) {
    try { [void](Select-WindowsBySelector $c42All $c42e) } catch { if ("$($_.Exception.Message)".Contains('must not be empty')) { $c42EmptyThrows++ } }
  }
  ST-Check 'unit: an empty needle is REFUSED, not a match-everything (t: / title: whitespace / class:)' ($c42EmptyThrows -eq 3)
  $c42BareEmpty = @((Select-WindowsBySelector $c42All '').Matches).Count
  ST-Check 'unit: a bare empty selector matches nothing (Resolve-Target intercepts "" for the foreground window before this runs)' ($c42BareEmpty -eq 0)
  $c43TitleLikeN = 0
  $c43ClassLikeN = 0
  for ($c43i = 0; $c43i -lt $codeLines.Count; $c43i++) {
    if ($c43i -ge $j5ProdStart -and $c43i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c43i] -match '^\s*#') { continue }
    if ($codeLines[$c43i].Contains('Title -like "*$sub*"')) { $c43TitleLikeN++ }
    if ($codeLines[$c43i].Contains('Class -like "*$sub*"')) { $c43ClassLikeN++ }
  }
  $c43TnsN = 0
  for ($c43i = 0; $c43i -lt $codeLines.Count; $c43i++) {
    if ($codeLines[$c43i].StartsWith('function Select-WindowsBySelector')) { $c43TnsN = $c43i; break }
  }
  $c43TnsBody = 0
  if ($c43TnsN -ge 0) {
    for ($c43i = $c43TnsN; $c43i -lt ($c43TnsN + 30); $c43i++) {
      if ($c43i -ge $codeLines.Count) { break }
      if (($c43i -gt $c43TnsN) -and ($codeLines[$c43i] -match '^function ')) { break }
      if ($codeLines[$c43i].Contains('Test-NameSubstring')) { $c43TnsBody++ }
    }
  }
  ST-Check 'unit/lint: selector is a literal substring - titles with [ * ? are found by their own text, the wildcard reading finds nothing, case stays insensitive' (
    ($c42Bad -eq '') -and ($c43TitleLikeN -eq 0) -and ($c43TnsBody -ge 2))
  ST-Check 'unit/lint: class goes literal too (substring found, wildcard dead), proc stays exact, numeric pid still routes to pid' (
    ($c42ClsBad -eq '') -and ($c43ClassLikeN -eq 0) -and ($c43TnsBody -ge 2))
  Write-Output ("      selector wiring: title-like=$c43TitleLikeN class-like=$c43ClassLikeN literal-matcher-sites=$c43TnsBody")

  $c44Amb = Get-SelectorAmbiguity @($c42All[0], $c42All[3]) 'TELEBOT'
  ST-Check 'unit: non-PID multi-match is refused with every candidate and an explicit disambiguation route' (
    $c44Amb.Ambiguous -and $c44Amb.Count -eq 2 -and
    $c44Amb.Message.Contains('pid=111') -and $c44Amb.Message.Contains('pid=444') -and
    $c44Amb.Message.Contains('class=') -and $c44Amb.Message.Contains('main=') -and
    $c44Amb.Message.Contains('rect=') -and $c44Amb.Message.Contains('choose pid / proc: / class:'))
  $c44Single = Get-SelectorAmbiguity @($c42All[0]) 'TELEBOT'
  ST-Check 'unit: a single selector match remains selectable' (-not $c44Single.Ambiguous -and $c44Single.Count -eq 1)
  $c44RefuseIf = @($codeLines | Where-Object { $_ -ceq '  if (-not $byPid -and $amb.Ambiguous) {' }).Count
  $c44RefuseThrow = @($codeLines | Where-Object { $_ -ceq '    throw $amb.Message' }).Count
  ST-Check 'lint: Resolve-Window refuses non-PID ambiguity before selecting a largest match' ($c44RefuseIf -eq 1 -and $c44RefuseThrow -eq 1)
  $c44WheelNoneOwn = Strip-OwnFlags @('-4', '2443', '1350') 'wheel'
  $c44WheelNone = Split-Target @($c44WheelNoneOwn.Rest) 'wheel'
  ST-Check 'unit: wheel without --expect-change keeps the legacy no-check shape' (
    $c44WheelNone.ExpectChange -ceq '' -and (@($c44WheelNone.Words) -join ' ') -ceq '-4 2443 1350')
  Write-Output "      wheel parser: absent -> active=none difference=delivery-only"
  $c44WheelBareOwn = Strip-OwnFlags @('-3', '--expect-change', '--at', 'proc:dtx') 'wheel'
  $c44WheelBare = Split-Target @((Get-OptValue $c44WheelBareOwn 'Rest')) 'wheel'
  ST-Check 'unit: wheel bare --expect-change means auto and strips --at through the shared path' (
    (Get-OptValue $c44WheelBare 'ExpectChange') -ceq 'auto' -and $c44WheelBareOwn.Values['--at'] -ceq 'proc:dtx' -and
    (@($c44WheelBare.Words) -join ' ') -ceq '-3')
  Write-Output "      wheel parser: bare -> active=auto difference=hash-check on target/virtual rect"
  $c44WheelRectOwn = Strip-OwnFlags @('-5', '--expect-change', '1,2,300,400') 'wheel'
  $c44WheelRect = Split-Target @($c44WheelRectOwn.Rest) 'wheel'
  ST-Check 'unit: wheel --expect-change consumes an explicit screen rect' (
    $c44WheelRect.ExpectChange -ceq '1,2,300,400' -and (@($c44WheelRect.Words) -join ' ') -ceq '-5')
  Write-Output "      wheel parser: explicit -> active=1,2,300,400 difference=hash-check on explicit screen rect"
  $c44WheelBad = ''
  try {
    $c44WheelBadOwn = Strip-OwnFlags @('-5', '--expect-change', '1,2,3') 'wheel'
    [void](Split-Target @($c44WheelBadOwn.Rest) 'wheel')
  } catch { $c44WheelBad = "$($_.Exception.Message)" }
  ST-Check 'unit: wheel malformed --expect-change is refused by name' ($c44WheelBad.Contains('--expect-change needs x,y,w,h') -and $c44WheelBad.Contains('1,2,3'))
  Write-Output "      wheel parser: malformed -> active=reject difference=one named error"
  $c44WheelAtBad = ''
  try { [void](Strip-OwnFlags @('-3', '--at') 'wheel') } catch { $c44WheelAtBad = "$($_.Exception.Message)" }
  ST-Check 'unit: wheel --at without a selector is refused before dispatch' ($c44WheelAtBad.Contains("'--at' needs a value"))
  $wheelCommandLines = @((Get-CommandCodeText $codeLines 'wheel') -split "`n")
  $c44WheelAtGuard = @($wheelCommandLines | Where-Object {
    $_.Contains('$atPresent -and (-not $atSel -or $atSel -like') -and $_.Contains("'--at' needs a window selector value")
  }).Count
  ST-Check 'lint: wheel dispatcher keeps its named --at missing-value guard' ($c44WheelAtGuard -eq 1)
  $c44WheelSites = @($codeLines | Where-Object { $_ -match 'Split-Target @\(\$own\.Rest\) ''wheel''' }).Count
  $c44WheelPrivateSites = @($codeLines | Where-Object { $_ -match 'Strip-OwnFlags \$Rest ''wheel''' }).Count
  ST-Check 'lint: wheel routes shared --expect-change through Split-Target after one private-flag strip' ($c44WheelSites -eq 1 -and $c44WheelPrivateSites -eq 1)
  $c44WheelEmptyGuard = @($wheelCommandLines | Where-Object {
    $_.Contains('$ecb = $null') -or $_.Contains('if ($p.ExpectChange -and -not $verificationRequested)') -or
      $_.Contains('if ($ecb) { Invoke-ExpectChangeCheck $p $ecb ''wheel'' }')
  }).Count
  ST-Check 'lint: wheel initializes no pixel expectation, acquires one only when requested, and checks only a present baseline' ($c44WheelEmptyGuard -eq 3)
  $c44WheelLiveCall = @($codeLines | Where-Object { $_ -match '\$outWheel = & powershell .* wheel -3 --at ''DTX-ExpectProbe''' }).Count
  ST-Check 'lint: live wheel proof executes exactly one real DTX-ExpectProbe call' ($c44WheelLiveCall -eq 1)
  $c44ClickPidAudit = @($codeLines | Where-Object { $_ -ceq '      if ($null -ne $tgt) { $clickLogArgs = @($clickLogArgs) + @("pid=$($tgt.Pid)") }' }).Count
  ST-Check 'lint: click audit appends the resolved target pid for an independent act witness' ($c44ClickPidAudit -eq 1)
  Write-Output ("      selector ambiguity + wheel parser: ambiguous=$($c44Amb.Count) wheel-sites=$c44WheelSites private-sites=$c44WheelPrivateSites")

  # ---------- unit: v4.2.0 feedback item 4 - uia-tree file route + --path ----------
  # The FILE half of the request is deliberately NOT a second writer. Two measured facts
  # pinned the decision: (a) `--out` cannot reach this file at all under `powershell -File`
  # - it binds at PowerShell's own parameter layer and dies as AmbiguousParameter between
  # -OutVariable and -OutBuffer (2026-10-10, both engines), so advertising it would be a
  # flag that only lives in the signature; (b) `--dump <file>` has shipped since v3.0.0
  # with uia-tree already in its accepted set, writing UTF-8 without BOM and refusing to
  # overwrite. So what needed adding was discoverability, not a writer.
  $v42DumpSet = @(Get-DumpCommandSet)
  ST-Check 'unit: uia-tree and uia-find are in the --dump accepted set, an action is not' (
    ($v42DumpSet -contains 'uia-tree') -and ($v42DumpSet -contains 'uia-find') -and (-not ($v42DumpSet -contains 'click')))
  $v42OutProbe = ''
  # v4.2.1 (self-check repair): capture the child's COMPLETE stderr, not the parent's truncated
  # error record. With $ErrorActionPreference = 'Stop' (line 26) a native command's stderr becomes
  # a terminating NativeCommandError whose .Exception.Message keeps only the FIRST physical line.
  # On a zh-CN console that line is Chinese, and the error record's Out-String() drops the child's
  # FullyQualifiedErrorId line as well - so the English tokens below matched nothing and this check
  # went RED on a tool that was working correctly (measured 2026-10-10: exception-message len=53,
  # full-error-record len=465, neither contained AmbiguousParameter). Relaxing EAP to 'Continue'
  # for THIS ONE probe lets the child's whole stderr reach the pipe, where the locale-independent
  # identifier `AmbiguousParameter` (also `OutVariable`) is present whatever the UI language is.
  # The assertion is NOT loosened: a reachable --out would print the tool's own output ("wrote ..."),
  # which the second half below still rejects - that negative control is what gives it teeth.
  $v42Eap = $ErrorActionPreference
  $ErrorActionPreference = 'Continue'
  # G-21 (owner ruling 2026-10-20 14:4x, item 3; the fourth site of the v4.1.3 finding-D family, which
  # was missed there): this probe calls `powershell` BY BARE NAME, so it measures the PATH face. When
  # the harness has no resolvable child at all there is nothing to measure - the child never runs, the
  # face comes back empty, and the assertion below matched none of its tokens and went RED for the
  # caller's environment (measured: contexts C and D of the A-25 four-context matrix, exit 1 both).
  # So the site now asks the same pre-flight every other `& powershell` check asks, and when the answer
  # is no it SKIPs under the IDENTICAL name, carrying the measured reason. When the answer is yes the
  # original assertion runs exactly as written - it is not weakened here, and a --out that really does
  # reach the parser still prints 'wrote ' and still goes red.
  if ($script:PsChildOk) {
    try { $v42OutProbe = (& powershell -NoProfile -ExecutionPolicy Bypass -File $self uia-tree --out 'D:/x/nul.txt' 2>&1 | Out-String) } catch { $v42OutProbe = $_.Exception.Message } finally { $ErrorActionPreference = $v42Eap }
    # This assertion accepts either shape the probe can produce: the raw child stderr (the normal
    # case while EAP is relaxed above) or the exception text, should a future edit capture it
    # through the terminating path. The claim under test is that PowerShell's own binder eats
    # --out - not which channel reported it. (v4.2.1 correction: the old comment said EAP=Stop
    # "merges stderr into the pipeline" so both shapes arrive; measurement showed the terminating
    # path yields ONLY the first physical line, which on zh-CN is Chinese and matches nothing.)
    ST-Check 'live: --out still never reaches the parser (PowerShell eats it) - the reason --dump is the advertised route' (
      ($v42OutProbe -match 'is ambiguous|AmbiguousParameter|OutVariable') -and (-not ($v42OutProbe -match 'wrote ')))
  } else {
    Write-Output ('      --out probe NOT VERIFIED (no child to probe): ' + $script:PsChildWhy)
    ST-Skip 'live: --out still never reaches the parser (PowerShell eats it) - the reason --dump is the advertised route' ($script:PsChildWhy + ' - this probe spawns its child through the call operator, so there is nothing to measure')
  }
  $ErrorActionPreference = $v42Eap
  # G-21 (owner ruling 2026-10-20 14:4x, item 3): the child-spawn face is gated, and the
  # gating itself has to be inspectable. What is claimed here is structural, not a rerun:
  #   A) the --out probe above must sit INSIDE a PATH-face pre-check, and the name it skips under must
  #      be the identical name it checks under (a skip under a different name would free a check slot);
  #   B) the step-probe block must gate BOTH child faces BEFORE it raises its fixture - the two faces
  #      answer differently (measured: PATH face unresolvable, Start-Process face still fine, because
  #      App Paths), and an ungated fixture launch is a window nobody cleans up;
  #   C) the mid-run path must STILL be able to report red - a pre-check may not become a blanket.
  # Needles are concatenated so none of these lines can match its own search (the self-pollution shape
  # this file has caught repeatedly). The detector is a scriptblock over a line array, so the planted
  # copies below are data, never source the real scan can see.
  $g21NProbe = "uia-tree " + "--out 'D:/x/nul.txt'"
  $g21NGuard = '  if (' + '$script:PsChildOk) {'
  $g21NChk = ('ST-' + "Check 'live: --out still never")
  $g21NSkip = ('ST-' + "Skip 'live: --out still never")
  $g21NGateChild = 'if (-not ' + '$script:PsChildOk) { $stepGate ='
  $g21NGateStart = 'if (-not ' + '$script:PsStartOk) { $stepGate ='
  $g21NInit = '$stepGate = ' + "''"
  $g21NFixture = '$stepProc = ' + 'Start-Process powershell'
  $g21NMidRed = ('ST-' + "Check 'live: step probe setup+run' ") + '$false'
  $g21Gap = {
    param([string[]]$Raw)
    $L = @($Raw | Where-Object { $_ -notmatch '^\s*#' })
    $idxOf = {
      param($needle)
      $r = @()
      for ($i = 0; $i -lt $L.Count; $i++) { if ($L[$i].Contains($needle)) { $r += $i } }
      return , @($r)
    }
    $iProbe = & $idxOf $g21NProbe
    if ($iProbe.Count -ne 1) { return 'A-probe-site-not-single:' + $iProbe.Count }
    $iGuard = & $idxOf $g21NGuard
    $p = $iProbe[0]
    $before = @($iGuard | Where-Object { $_ -lt $p -and ($p - $_) -le 14 })
    if ($before.Count -eq 0) { return 'A-probe-ungated' }
    $nameOf = {
      param($line, $kind)
      # Measured on the first pass: the usual quoted-first-argument pattern
      # "'((?:[^']|'')*)'" is GREEDY across the rest of the line, so on an ST-Skip line - whose second
      # argument is another quoted string - it swallows the closing quote plus the code after it, and
      # the REAL face reported a name drift that did not exist. Take one run of non-quote characters
      # and refuse to compare when the next character is another quote, because that is a doubled
      # quote inside the name (the very case the greedy form was written to allow).
      if ($line -match ('ST-' + $kind + "\s+'([^']*)'(.?)")) {
        if ($Matches[2] -eq "'") { return '~DOUBLED-QUOTE~' }
        return $Matches[1]
      }
      return ''
    }
    $iChk = & $idxOf $g21NChk
    $iSkip = & $idxOf $g21NSkip
    if ($iChk.Count -eq 0) { return 'A-check-name-missing' }
    if ($iSkip.Count -eq 0) { return 'A-skip-line-missing' }
    $nChk = & $nameOf $L[$iChk[0]] 'Check'
    $nSkip = & $nameOf $L[$iSkip[0]] 'Skip'
    if ($nChk -eq '~DOUBLED-QUOTE~' -or $nSkip -eq '~DOUBLED-QUOTE~') { return 'A-name-has-doubled-quote' }
    if (-not $nChk) { return 'A-check-name-unparseable' }
    if ($nChk -cne $nSkip) { return 'A-skip-name-drift' }
    $iChildGate = & $idxOf $g21NGateChild
    $iStartGate = & $idxOf $g21NGateStart
    $iInit = & $idxOf $g21NInit
    $iFixture = & $idxOf $g21NFixture
    $iMidRed = & $idxOf $g21NMidRed
    if ($iChildGate.Count -ne 1) { return 'B-child-gate-not-single:' + $iChildGate.Count }
    if ($iStartGate.Count -ne 1) { return 'B-start-gate-not-single:' + $iStartGate.Count }
    if ($iFixture.Count -ne 1) { return 'B-fixture-site-not-single:' + $iFixture.Count }
    if ($iInit.Count -ne 1) { return 'B-block-init-not-single:' + $iInit.Count }
    if ($iMidRed.Count -ne 1) { return 'C-midrun-red-lost:' + $iMidRed.Count }
    $f = $iFixture[0]
    if (-not ($iChildGate[0] -gt $iInit[0] -and $iChildGate[0] -lt $f)) { return 'B-child-gate-not-before-fixture' }
    if (-not ($iStartGate[0] -gt $iInit[0] -and $iStartGate[0] -lt $f)) { return 'B-start-gate-not-before-fixture' }
    return 'ok'
  }
  $g21Real = & $g21Gap -Raw @($codeLines)
  # plants: each is the REAL face with exactly one thing broken, so a gap can only come from that break
  $g21P1 = @($codeLines | Where-Object { $_ -cne $g21NGuard })
  # plant 2 drifts the SKIP name at its TAIL: breaking the head would stop the needle from matching at
  # all, and the honest detector answer to "no skip line here" is A-skip-line-missing (measured on the
  # first pass) - a different gap, so the drift branch would never have been exercised.
  $g21P2 = @($codeLines | ForEach-Object { if ($_.Contains($g21NSkip)) { $_.Replace('is the advertised route', 'is the advertised ROUTE') } else { $_ } })
  # plant 3 moves the two gates to AFTER the fixture launch. Each part is built as its own variable
  # because `cmd + cmd` on one line is not valid PowerShell (measured: 4 parse errors here on the
  # first pass), and the parts are concatenated in expression mode below.
  $g21P3Keep = @($codeLines | Where-Object { -not ($_.Contains($g21NGateChild) -or $_.Contains($g21NGateStart) -or $_.Contains($g21NFixture) -or $_.Contains($g21NMidRed)) })
  $g21P3Fx = @($codeLines | Where-Object { $_.Contains($g21NFixture) })
  $g21P3Gate = @($codeLines | Where-Object { $_.Contains($g21NGateChild) -or $_.Contains($g21NGateStart) })
  $g21P3Red = @($codeLines | Where-Object { $_.Contains($g21NMidRed) })
  $g21P3 = @($g21P3Keep + $g21P3Fx + $g21P3Gate + $g21P3Red)
  $g21P4 = @($codeLines | Where-Object { -not $_.Contains($g21NMidRed) })
  $g21R1 = & $g21Gap -Raw $g21P1
  $g21R2 = & $g21Gap -Raw $g21P2
  $g21R3 = & $g21Gap -Raw $g21P3
  $g21R4 = & $g21Gap -Raw $g21P4
  $g21CodeHits = @($codeLines | Where-Object { $_.Contains('$script:PsChildOk') -or $_.Contains('$script:PsStartOk') -or $_.Contains('$script:PsChildWhy') -or $_.Contains('$script:PsStartWhy') }).Count
  $g21PlantReport = (@($g21R1, $g21R2, $g21R3, $g21R4) -join '/')
  Write-Output ('      G-21 child-face gate: real=' + $g21Real + ' runtime PATH=' + [bool]$script:PsChildOk + ' runtime Start=' + [bool]$script:PsStartOk +
    ' code-hits=' + $g21CodeHits + ' plants=' + $g21PlantReport)
  ST-Check 'lint (G-21): the --out probe sits behind the PATH-face pre-check and skips under the identical name, the step-probe gates both child faces before its fixture starts, and the mid-run red line is still there' (
    $g21Real -ceq 'ok')
  ST-Check 'unit (G-21): the child-face gate detector has teeth - each planted break reports its own named gap and the unplanted face reports ok' (
    ($g21Real -ceq 'ok') -and ($g21R1 -ceq 'A-probe-ungated') -and ($g21R2 -ceq 'A-skip-name-drift') -and
    ($g21R3 -ceq 'B-child-gate-not-before-fixture') -and ($g21R4 -ceq 'C-midrun-red-lost:0'))
  $v42TreeUsage = (Get-UsageText | Out-String)
  ST-Check 'unit: the uia-tree usage entry names --dump as the file route and --path as the subtree route' (
    ($v42TreeUsage.Contains('--dump <file>')) -and ($v42TreeUsage.Contains('--path')))
  $v42TreeLines = @(
    'scan: handle=1 depth=6',
    'root: LobsterAI',
    "  A | name='m1' | path=/0/1",
    "    B | name='m1 reply' | path=/0/1/0",
    "    C | name='m2' | path=/0/1/1",
    "      D | name='other' | path=/0/1/1/0")
  $v42Keep = Test-UiaPathFilter $v42TreeLines '/0/1/0'
  ST-Check 'unit: --path keeps the ancestor chain + the subtree, drops siblings, and counts both' (
    (@($v42Keep.Lines).Count -eq 4) -and ($v42Keep.Sub -eq 1) -and ($v42Keep.Anc -eq 1) -and
    (@($v42Keep.Lines | Where-Object { "$_" -like '*path=/0/1/1*' }).Count -eq 0) -and
    ($v42Keep.Summary -ceq 'path=/0/1/0 -> 1 node(s) below it + 1 ancestor(s)'))
  $v42Miss = Test-UiaPathFilter @("  A | name='x' | path=/0/1") '/0/9/9'
  ST-Check 'unit: a --path token that matches nothing is reported as a miss, never as an empty tree' (
    (-not $v42Miss.Ok) -and ($v42Miss.Sub -eq 0) -and ($v42Keep.Ok -eq $true))
  # the needles are assembled so this check cannot count its own source as a hit.
  $v42PathNeedle = '--path'
  $v42PathSites = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_ -match "--eq '--path'" })
  $v42UnknownSites = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_ -match 'unknown flag ''\$w0''' })
  $v42DumpMentions = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_ -match 'unknown flag .\$w0.*--dump' })
  ST-Check 'lint: uia-tree parses --path, still refuses unknown --words, and that refusal names --dump' (
    (@($v42PathSites).Count -ge 1) -and (@($v42UnknownSites).Count -ge 1) -and (@($v42DumpMentions).Count -ge 1))

  # ---------- v4.4.1 (CU-REL-01): the landing identity check and the post-activation state read ----------
  # relclick used to add its offsets to the rect the SELECTOR handed back and click, passing none of
  # the pre-action checks its siblings pass; focus used to print the select-time pick next to
  # Activate-Win's boolean and never look at the window again. Both verdicts are now pure functions,
  # so every shape below is measured offline - including the one a live window would make hard to
  # arrange on purpose: a top-level of the SAME pid that is not the target sitting under the point
  # (the card names that case explicitly, and a fixture for it belongs to --live, not to this gate).
  $curelTarget = @{ Handle = [IntPtr]1000; Title = 'TARGET'; Pid = 42 }
  $curelOwnRoot = @{ Hwnd = [IntPtr]1000; Pid = 42 }
  $curelSamePid = @{ Hwnd = [IntPtr]2000; Pid = 42 }
  $curelForeign = @{ Hwnd = [IntPtr]3000; Pid = 99 }
  ST-Check 'unit (CU-REL-01): the landing verdict passes the target and its own controls, and refuses a same-pid top-level as well as a foreign one' (
    (Test-LandingOnTarget $curelOwnRoot $curelTarget) -and (-not (Test-LandingOnTarget $curelSamePid $curelTarget)) -and
    (-not (Test-LandingOnTarget $curelForeign $curelTarget)))
  ST-Check 'unit (CU-REL-01): a point where no window answers the hit test is a refusal, never a pass' (
    -not (Test-LandingOnTarget $null $curelTarget))
  $curelRefuse = Format-LandingVerdict 500 600 $curelSamePid $curelTarget $false
  $curelRelax = Format-LandingVerdict 500 600 $curelSamePid $curelTarget $true
  ST-Check 'unit (CU-REL-01): the refusal names the window under the point, says NOTHING was clicked and offers the relaxation flag' (
    ($curelRefuse.Contains('NOTHING was clicked')) -and ($curelRefuse.Contains('hwnd=2000')) -and
    ($curelRefuse.Contains('--allow-outside')) -and ($curelRefuse.Contains('not the resolved target hwnd=1000')))
  ST-Check 'unit (CU-REL-01): the relaxed line says which flag relaxed what - a relaxation is never silent' (
    ($curelRelax.Contains('RELAXED by --allow-outside')) -and ($curelRelax.Contains('hwnd=2000')) -and
    ($curelRelax.Contains('hwnd=1000')))
  $curelNoneRefusal = Format-LandingVerdict 1 2 $null $curelTarget $false
  $curelNoneWho = [regex]::Match($curelNoneRefusal, 'the window under \(1,2\) is (.*), not the resolved target').Groups[1].Value
  ST-Check 'unit (CU-REL-01): an absent hit window is rendered as a named reading, not as an empty handle' (
    ($curelNoneWho -ceq '(nothing answers the hit test)') -and ($curelNoneRefusal.Contains('hwnd=1000')))
  $curelUsable = @{ Fg = $true; Iconic = $false; Visible = $true; Rect = @{ X = 10; Y = 20; W = 300; H = 200 } }
  $curelBroken = @{
    'not-foreground' = @{ Fg = $false; Iconic = $false; Visible = $true; Rect = $curelUsable.Rect }
    'still-minimized' = @{ Fg = $true; Iconic = $true; Visible = $true; Rect = $curelUsable.Rect }
    'not-visible' = @{ Fg = $true; Iconic = $false; Visible = $false; Rect = $curelUsable.Rect }
    'no-rect' = @{ Fg = $true; Iconic = $false; Visible = $true; Rect = $null }
    'parked-off-screen' = @{ Fg = $true; Iconic = $false; Visible = $true; Rect = @{ X = -32000; Y = -32000; W = 300; H = 200 } }
  }
  $curelBrokenNames = @(Get-HashKeys $curelBroken)
  $curelRefusedNames = @($curelBrokenNames | Where-Object { -not (Test-FocusUsable $curelBroken[$_]) })
  ST-Check 'unit (CU-REL-01): usable needs all four faces good - five planted single-face breaks all refuse, the planted whole passes, and an unmeasured state refuses' (
    (Test-FocusUsable $curelUsable) -and (@($curelRefusedNames).Count -eq 5) -and (-not (Test-FocusUsable $null)))
  Write-Output ('      CU-REL-01 focus-usable refusals: ' + (@($curelRefusedNames) -join ','))
  $curelStateOk = Format-FocusState 'after-activate' $curelUsable
  $curelStateNoRect = Format-FocusState 'after-activate' $curelBroken['no-rect']
  ST-Check 'unit (CU-REL-01): the state line stamps which reading it is, spells the faces with fg= (never the fg_ok= token) and names a missing rect' (
    ($curelStateOk.StartsWith('after-activate fg=True iconic=False visible=True rect=(10,20,300x200)')) -and
    ($curelStateOk -notlike '*fg_ok=*') -and ($curelStateNoRect.Contains('rect=(none)')))
  ST-Check 'unit (CU-REL-01): a reading that never happened prints as not measured, so an empty state cannot look like a pass' (
    ((Format-FocusState 'after-activate' $null) -ceq 'after-activate (not measured)'))
  # Wiring: a pure guard nobody calls is the shape this repo has been caught with before, so the
  # handlers themselves are measured from the command's own code spans (case + named handler), not
  # from a remembered line number.
  $curelRelclickRanges = @(Get-CommandCodeRanges $codeLines 'relclick')
  $curelRelclickText = Get-CommandCodeText $codeLines 'relclick'
  $curelFocusRanges = @(Get-CommandCodeRanges $codeLines 'focus')
  $curelFocusText = Get-CommandCodeText $codeLines 'focus'
  ST-Check 'lint (CU-REL-01): the wiring scan really sees both command bodies (a scan over an empty span would make every claim below vacuous)' (
    (@($curelRelclickRanges).Count -ge 2) -and (@($curelFocusRanges).Count -ge 2))
  # A guard prefixed with '#' keeps every literal the mention-scan looks for, so it reads as wired.
  # The census below only counts a name where the line is live code; the planted pair proves the
  # difference, because "it stayed green with the guard commented out" is a whole class of breakage
  # that a text scan cannot see.
  $curelLiveCallLines = { param($Text, $Name)
    $src = @([string]$Text -split "`n")
    $at = @()
    for ($ci = 0; $ci -lt $src.Count; $ci++) {
      if (($src[$ci] -notmatch '^\s*#') -and ([string]$src[$ci]).Contains($Name)) { $at += $ci }
    }
    return @($at)
  }
  $curelRcNames = @('Resolve-Target', 'Invoke-ContentGuard', 'Get-WindowVisibleRect',
    'Invoke-HitWindowCheck', 'Test-LandingOnTarget', 'Move-Click')
  $curelRcMissing = @($curelRcNames | Where-Object { @(& $curelLiveCallLines $curelRelclickText $_).Count -eq 0 })
  Write-Output ('      CU-REL-01 relclick live call lines: ' + (($curelRcNames | ForEach-Object { $_ + '=' + @(& $curelLiveCallLines $curelRelclickText $_).Count }) -join ','))
  ST-Check 'lint (CU-REL-01): relclick walks the common target path - resolve, content guard, by-handle rect, hit-window check, landing identity - before it moves the cursor' (
    (@($curelRcMissing).Count -eq 0) -and ($curelRelclickText.Contains('Resolve-Target')) -and
    ($curelRelclickText.Contains('Invoke-ContentGuard')) -and ($curelRelclickText.Contains('Get-WindowVisibleRect')) -and
    ($curelRelclickText.Contains('Invoke-HitWindowCheck')) -and ($curelRelclickText.Contains('Test-LandingOnTarget')) -and
    ($curelRelclickText.Contains('Move-Click')))
  $curelPlantText = ('  # Invoke-HitWindowCheck 1 2 3' + "`n" + '  Invoke-ContentGuard 4 5' + "`n" + '#Move-Click 6' + "`n" + '  Move-Click 7 8')
  $curelPlantDead = @(& $curelLiveCallLines $curelPlantText 'Invoke-HitWindowCheck')
  $curelPlantHash = @(& $curelLiveCallLines $curelPlantText 'Move-Click')
  $curelPlantLive = @(& $curelLiveCallLines $curelPlantText 'Invoke-ContentGuard')
  ST-Check 'unit (CU-REL-01): the wiring census has teeth - a guard commented out with a leading space and one commented out flush read as absent, the live call two lines later still reads as present' (
    (@($curelPlantDead).Count -eq 0) -and (@($curelPlantHash).Count -eq 1) -and (@($curelPlantLive).Count -eq 1) -and
    (@($curelPlantLive)[0] -eq 1))
  Write-Output ('      CU-REL-01 planted census: commented=' + @($curelPlantDead).Count + ' flushCommented=' + @($curelPlantHash).Count + ' live=' + @($curelPlantLive).Count)
  $curelStaleHits = ([regex]::Matches($curelRelclickText, '\$w\.(Left|Top)')).Count
  ST-Check 'lint (CU-REL-01): relclick no longer reads geometry off the selector result - the select-time origin is gone from its body' (
    ($curelStaleHits -eq 0) -and ($curelRelclickText.Contains('$rcRect.X + $rcDx')) -and
    ($curelRelclickText.Contains('-le -32000')))
  ST-Check 'unit (CU-REL-01): the select-time-origin pattern the lint refuses still matches a planted counterexample (the scan is not blind)' (
    ('      $x = $w.Left + [int]$Rest[1]' -match '\$w\.(Left|Top)'))
  $curelClickCount = ([regex]::Matches($curelRelclickText, 'NOTHING was clicked')).Count
  ST-Check 'lint (CU-REL-01): every relclick refusal before the send says nothing was clicked, and the count is published (>=2: unmeasurable rect + parked rect)' (
    ($curelClickCount -ge 2))
  Write-Output ('      CU-REL-01 relclick pre-send refusals naming the no-op: ' + $curelClickCount)
  ST-Check 'lint (CU-REL-01): relclick keeps its positional selector form and refuses --to by name (a behaviour fix must not change the call shape silently)' (
    ($curelRelclickText.Contains('relclick <sel> <dx> <dy>')) -and ($curelRelclickText.Contains('$p.Sel')))
  $curelFocusNames = @('Resolve-Target', 'GetForegroundWindow', 'IsIconic', 'IsWindowVisible', 'Get-WindowVisibleRect')
  $curelFocusMissing = @($curelFocusNames | Where-Object { @(& $curelLiveCallLines $curelFocusText $_).Count -eq 0 })
  ST-Check 'lint (CU-REL-01): focus re-measures the same handle on all four faces after activation instead of trusting Activate-Win (foreground, iconic, visible, rect)' (
    (@($curelFocusMissing).Count -eq 0) -and ($curelFocusText.Contains('at-select')))
  $curelGuardSite = @(& $curelLiveCallLines $curelFocusText 'Test-FocusUsable')
  $curelEchoSite = @(& $curelLiveCallLines $curelFocusText 'focused pid=')
  $curelGuardAt = @($curelGuardSite)[0]
  $curelEchoAt = @($curelEchoSite)[0]
  ST-Check 'lint (CU-REL-01): the usable guard sits AHEAD of the success line (a guard that runs after the echo polices nothing)' (
    (@($curelGuardSite).Count -ge 1) -and (@($curelEchoSite).Count -ge 1) -and ($curelEchoAt -gt $curelGuardAt))
  $curelFocusFgOk = @((($curelFocusText -split "`n")) | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains('fg_ok=') })
  ST-Check 'lint (CU-REL-01): fg_ok= has exactly one producer inside focus and it is the guarded success line (a refusal cannot satisfy the live focus pin)' (
    (@($curelFocusFgOk).Count -eq 1) -and (@($curelFocusFgOk)[0].Contains('focused pid=')))
  # focus routes through the shared guard, whose sentence ends with "Re-run with" plus this flag - a
  # flag this command refuses on purpose, because a forced focus would print a usable-looking line for
  # a window it could not raise. So the correction has to live in focus (appended), and the shared
  # producer must keep saying what the commands that DO accept it need to hear. The needle is
  # assembled at runtime: written whole, this very line would be a second hit for its own scan (the
  # scanner-reads-its-own-source family, recorded four times in this repo already).
  $curelForceNeedle = 'Re-run with ' + '--force'
  $curelForceQuoted = ([string][char]39) + '--force' + ([string][char]39)
  $curelSharedForce = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($curelForceNeedle) })
  ST-Check 'lint (CU-REL-01): focus reads no force flag, the shared guard keeps its own force advice intact, and focus names its own refusal instead' (
    (-not $curelFocusText.Contains($curelForceQuoted)) -and (@($curelSharedForce).Count -eq 1) -and
    (-not $curelSharedForce[0].Contains('focus')) -and ($curelFocusText.Contains('focus has no --force')))
  ST-Check 'unit (CU-REL-01): the no-force scan has teeth - a planted flag read is detected by the same test' (
    (-not $curelFocusText.Contains($curelForceQuoted)) -and
    ('if ($p.Force -eq ' + $curelForceQuoted + ') { x }').Contains($curelForceQuoted))
  $curelUsage = (Get-UsageText | Out-String)
  ST-Check 'lint (CU-REL-01): the help page states both new contracts - relclick re-reads the rect after raising, focus re-reads the same handle, and the pointing set now polices the landing identity' (
    ($curelUsage.Contains('re-read AFTER it is raised')) -and ($curelUsage.Contains('the SAME handle')) -and
    ($curelUsage.Contains('is not the resolved target itself')))

}

# lib/selftest-chrome-cdp.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1 by A-14k (A-beta).
# Bodies are byte-identical to what the section carried. The only channel to the orchestrator is the
# explicit context object: shared state arrives through $Ctx and nothing else, because A-14e/A-14i
# measured what happens when a body reaches for a caller local instead.
# The Chrome/CDP and accessibility family: the CDP client and a11y route, the UIA cold-start
# re-contact, action tokens plus structural path handles, the Rect.Empty family, and the viewport
# fallback that once had only one axis.
function Invoke-SelftestFamily-ChromeCdp($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $clCount = $Ctx['clCount']
  $codeLines = $Ctx['codeLines']
  $hCaseStarts = $Ctx['hCaseStarts']
  $hFnEnd = $Ctx['hFnEnd']
  $j5ProdStart = $Ctx['j5ProdStart']
  $j5ProdEnd = $Ctx['j5ProdEnd']

  # ---------- v1.8.0 CDP client and a11y route (task book A-0..A-6) ----------
  # Offline half of the acceptance set: the judgements that can be pinned without a
  # desktop are pinned here, so a live round can only fail on the part that genuinely
  # needs one. Every case below is bidirectional - one accepted spelling is not enough
  # for a gate, and a mapping is not proven by one scale factor.
  $c1Bad = ''
  foreach ($spell in @('127.0.0.1', '127.0.0.1:9222', 'http://127.0.0.1:9222/json/version', 'ws://127.0.0.1:9222/devtools/page/ABC')) {
    $c1Got = ''
    try { $c1Got = Get-CdpLoopbackBase $spell } catch { $c1Got = 'THREW: ' + $_.Exception.Message }
    if ($c1Got -ne "http://127.0.0.1:$script:CdpPort") { $c1Bad = "spelling '$spell' resolved to '$c1Got'" }
  }
  ST-Check 'unit: cdp loopback gate accepts every loopback spelling and returns one normalized http base' ($c1Bad -eq '')
  # Each hostile spelling must be refused BY THE BRANCH THAT APPLIES TO IT. Checking
  # only that the message mentions 127.0.0.1 was toothless: with the bare-port branch
  # deleted, '9222' still falls through to the non-loopback refusal and still names
  # 127.0.0.1, so the run stayed green over a real regression (mutation
  # 'cdp-drop-bare-port' caught that; the per-case phrase below is what gives it teeth).
  $c2Bad = ''
  foreach ($c2case in @(
    @('0.0.0.0:9222', 'non-loopback'),
    @('192.168.1.20:9222', 'non-loopback'),
    @('10.0.0.5', 'non-loopback'),
    @('evil.example.com:9222', 'non-loopback'),
    @('http://0.0.0.0:9222/json', 'non-loopback'),
    @('ws://192.168.1.20:9222/devtools/page/X', 'non-loopback'),
    @('9222', 'bare port'),
    @('17895', 'bare port'))) {
    $c2Msg = ''
    try { [void](Get-CdpLoopbackBase $c2case[0]); $c2Msg = 'ACCEPTED' } catch { $c2Msg = $_.Exception.Message }
    if ($c2Msg -eq 'ACCEPTED') { $c2Bad = "gate let '$($c2case[0])' through" }
    elseif (-not $c2Msg.Contains($c2case[1])) { $c2Bad = "refusal for '$($c2case[0])' did not come from the '$($c2case[1])' rule: $c2Msg" }
    elseif (-not $c2Msg.Contains('127.0.0.1')) { $c2Bad = "refusal for '$($c2case[0])' does not name the loopback rule: $c2Msg" }
  }
  ST-Check 'unit: cdp loopback gate refuses 0.0.0.0, a LAN address, a bare port and a hostname, each from the branch that applies and naming the rule' ($c2Bad -eq '')
  $c3a = Get-CdpUrlDomain 'http://127.0.0.1:8460/dashboard?token=QRYSECRETA1'
  $c3b = Get-CdpUrlDomain 'https://sub.example.com/tok/3f2a9c8b7d5e4f1a'
  $c3c = Get-CdpUrlDomain 'chrome://settings/login'
  $c3d = Get-CdpUrlDomain 'about:blank'
  $c3e = Get-CdpUrlDomain 'file:///C:/Users/SomeOne/Desktop/report.html'
  ST-Check 'unit: cdp url logging keeps host+port, drops BOTH the query and the path, keeps internal schemes readable and reduces file: to the bare scheme (a token sits in the path as happily as in the query; a file path is a personal path)' (
    $c3a -eq '127.0.0.1:8460' -and (-not $c3a.Contains('QRYSECRETA1')) -and $c3b -eq 'sub.example.com' -and (-not $c3b.Contains('3f2a9c8b7d5e4f1a')) -and $c3c -eq 'chrome://settings/login' -and $c3d -eq 'about:blank' -and $c3e -eq 'file' -and (-not $c3e.Contains('SomeOne')))
  # A-3's arithmetic. The two dpr values must differ in all four fields, and the origin
  # must be ADDED as already-physical pixels (chrome-find scales it before calling in).
  $c4Css = @{ left = 10.0; top = 20.0; width = 100.0; height = 50.0 }
  $c4d2 = Convert-CdpRectToScreen $c4Css 2.0 0 0
  $c4d1 = Convert-CdpRectToScreen $c4Css 1.0 0 0
  $c4off = Convert-CdpRectToScreen $c4Css 2.0 100 200
  ST-Check 'unit: css rect mapping multiplies BOTH offset and size by the measured dpr and adds the physical client origin once' (
    $c4d2.X -eq 20 -and $c4d2.Y -eq 40 -and $c4d2.W -eq 200 -and $c4d2.H -eq 100 -and $c4d1.X -eq 10 -and $c4d1.W -eq 100 -and $c4off.X -eq 120 -and $c4off.Y -eq 240)
  # The nested-array shape: PS has been observed handing a decoded JSON array back as
  # ONE element that is itself an array, which member-enumerates .title across every
  # target - chrome-tabs then prints "1 page(s)" whose title is several titles joined.
  $c5Json = '[{"type":"page","title":"AA","url":"http://h/a"},{"type":"page","title":"BB","url":"http://h/b"},{"type":"worker","title":"WW","url":"http://h/w"}]'
  $c5Flat = @(Get-CdpTargetList $c5Json 'page')
  $c5Nest = @(Get-CdpTargetList ('[' + $c5Json + ']') 'page')
  $c5All = @(Get-CdpTargetList $c5Json '')
  ST-Check 'unit: cdp target list yields the same page set flat or nested, keeps everything unfiltered, and empties on empty input' (
    (@($c5Flat).Count -eq 2) -and ((@($c5Flat | ForEach-Object { $_.title }) -join ',') -eq 'AA,BB') -and ((@($c5Nest | ForEach-Object { $_.title }) -join ',') -eq 'AA,BB') -and (@($c5All).Count -eq 3) -and (@(Get-CdpTargetList '' 'page').Count -eq 0))
  # The gate must be LOAD-BEARING: a gate that only checks a value the code retypes
  # itself is decoration. These two lints fail the moment anyone re-hardcodes an
  # endpoint or lets a chrome command open its own connection.
  $c6Mark = ('"http://127.0.0.1:' + '$script:CdpPort"')
  $c6Hard = New-Object System.Collections.ArrayList
  for ($c6i = 0; $c6i -lt $codeLines.Count; $c6i++) {
    if ($c6i -ge $j5ProdStart -and $c6i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c6i] -match '^\s*#') { continue }
    if ($codeLines[$c6i].Contains($c6Mark)) { [void]$c6Hard.Add($c6i + 1) }
  }
  ST-Check 'lint: exactly one non-comment line spells out a loopback CDP endpoint - the gate function itself (callers use its return value)' (
    (@($c6Hard).Count -eq 1) -and (($codeLines[[int]$c6Hard[0] - 1]).Contains('return ')))
  $c7Mark = '/devtools/page/'
  $c7Sock = New-Object System.Collections.ArrayList
  for ($c7i = 0; $c7i -lt $codeLines.Count; $c7i++) {
    if ($c7i -ge $j5ProdStart -and $c7i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c7i] -match '^\s*#') { continue }
    if ($codeLines[$c7i].Contains($c7Mark)) { [void]$c7Sock.Add($c7i + 1) }
  }
  ST-Check 'lint: exactly one line builds a CDP page socket URL, derived from the gated base' (@($c7Sock).Count -eq 1)
  Write-Output "      cdp endpoint construction: literal-loopback lines=$(@($c6Hard).Count) at lines $(Format-SourceLineList $c6Hard) | page-socket-url lines=$(@($c7Sock).Count) at lines $(Format-SourceLineList $c7Sock)"
  $c8Missing = New-Object System.Collections.ArrayList
  foreach ($c8cmd in @('chrome-tabs', 'chrome-read', 'chrome-find', 'chrome-click', 'chrome-debug-off')) {
    # v4.4.0 (A-15): the endpoint a command builds may live in its handler now, so coverage is judged
    # on the command's code rather than on the case body alone.
    $c8Body = Get-CommandCodeText $codeLines $c8cmd
    if ($c8Body -ceq '') { [void]$c8Missing.Add("$c8cmd is not dispatched"); continue }
    if (-not $c8Body.Contains('Get-CdpLoopbackBase')) { [void]$c8Missing.Add("$c8cmd skips the gate") }
  }
  ST-Check 'lint: every cdp command builds its endpoint through the loopback gate (none may connect on its own terms)' (
    @($c8Missing).Count -eq 0)
  if (@($c8Missing).Count -gt 0) { Write-Output "      cdp gate coverage gaps: $(@($c8Missing) -join ', ')" }
  # Who resolves WHAT: tab-targeting commands go through the shared page resolver,
  # whole-list commands through the shared target list. chrome-click resolves nothing
  # itself by design - it delegates to chrome-find so both print one mapping line.
  $c8bMissing = New-Object System.Collections.ArrayList
  foreach ($c8b in @(@('chrome-read', 'Get-CdpPageId'), @('chrome-find', 'Get-CdpPageId'), @('chrome-tabs', 'Get-CdpTargets'), @('chrome-debug-off', 'Get-CdpTargets'))) {
    $c8bName = $c8b[0]; $c8bNeed = $c8b[1]
    if (-not $hCaseStarts.ContainsKey($c8bName)) { [void]$c8bMissing.Add("$c8bName is not dispatched"); continue }
    # v4.4.0 (A-15 pen 2): who resolves what is a property of the command, not of the line range it happened
    #    to be written in - read the command's own code, case plus handler.
    if (-not ((Get-CommandCodeText $codeLines $c8bName).Contains($c8bNeed))) { [void]$c8bMissing.Add("$c8bName does not use $c8bNeed") }
  }
  ST-Check 'lint: page-targeting cdp commands resolve tabs through Get-CdpPageId and list commands through Get-CdpTargets' (
    @($c8bMissing).Count -eq 0)
  if (@($c8bMissing).Count -gt 0) { Write-Output "      cdp resolver coverage gaps: $(@($c8bMissing) -join ', ')" }
  # The viewport origin must come from the measured bottom-anchor helper. Both
  # alternatives were tried and measured this round (JS arithmetic: 10px too low;
  # Win32 client area: 131px too high, because Chrome's client area is its own UI).
  $c8cBody = ''
  if ($hCaseStarts.ContainsKey('chrome-find')) {
    $c8cBody = Get-CommandCodeText $codeLines 'chrome-find'
  }
  ST-Check 'lint: chrome-find takes its viewport origin from Get-CdpViewportOrigin, self-reports which formula it used, and does not re-derive it inline' (
    ($c8cBody.Contains('Get-CdpViewportOrigin')) -and ($c8cBody.Contains('origin-formula=')) -and (-not $c8cBody.Contains('ClientToScreen')))
  $c8dMark = ('bottom-anchor' + '-dwm')
  $c8dSites = New-Object System.Collections.ArrayList
  for ($c8di = 0; $c8di -lt $codeLines.Count; $c8di++) {
    if ($c8di -ge $j5ProdStart -and $c8di -lt $j5ProdEnd) { continue }
    if ($codeLines[$c8di] -match '^\s*#') { continue }
    if ($codeLines[$c8di].Contains($c8dMark)) { [void]$c8dSites.Add($c8di + 1) }
  }
  ST-Check 'lint: the bottom-anchor origin formula exists in exactly one place (one mapping, one truth about where the viewport is)' (
    @($c8dSites).Count -eq 1)
  # One implementation per judgement (the repo's own anti-drug rule): the page-area
  # verdict and the graceful Chrome restart must each exist once and be CALLED twice.
  $c9Mark = 'function Measure-A11yTree'
  $c10Mark = 'function Restart-ChromeWithFlags'
  $c9Defs = @(); $c10Defs = @(); $c9Calls = @(); $c10Calls = @()
  for ($c9i = 0; $c9i -lt $codeLines.Count; $c9i++) {
    if ($c9i -ge $j5ProdStart -and $c9i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c9i] -match '^\s*#') { continue }
    if ($codeLines[$c9i].StartsWith($c9Mark)) { $c9Defs += ($c9i + 1) }
    if ($codeLines[$c9i].StartsWith($c10Mark)) { $c10Defs += ($c9i + 1) }
    if ($codeLines[$c9i].Contains('= Measure-A11yTree ')) { $c9Calls += ($c9i + 1) }
    if ($codeLines[$c9i].Contains('= Restart-ChromeWithFlags ')) { $c10Calls += ($c9i + 1) }
  }
  # 4 = a11y-probe's first measurement + its cold-zero re-probe (A-6b), plus chrome-a11y's
  # before/after pair. Pinned exactly, so dropping OR adding a call site both go red.
  ST-Check 'lint: the page-area a11y verdict has exactly one implementation and both a11y-probe and chrome-a11y call it' (
    (@($c9Defs).Count -eq 1) -and (@($c9Calls).Count -eq 4))
  ST-Check 'lint: the graceful Chrome restart has exactly one implementation, called by chrome-a11y and chrome-debug-off' (
    (@($c10Defs).Count -eq 1) -and (@($c10Calls).Count -eq 2))
  $c11Mark = 'Top + [int]($win.H / 2)'
  $c11Half = @()
  for ($c11i = 0; $c11i -lt $codeLines.Count; $c11i++) {
    if ($c11i -ge $j5ProdStart -and $c11i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c11i] -match '^\s*#') { continue }
    if ($codeLines[$c11i].Contains($c11Mark)) { $c11Half += ($c11i + 1) }
  }
  ST-Check 'lint: the page-area half-of-window boundary is computed in exactly one place (no second copy that can drift)' (
    @($c11Half).Count -eq 1)
  # The restart gate: handle-death was the shipped bug (window gone, process alive,
  # port still answering, relaunch swallowed by the singleton). Pin the replacement.
  $c12s = -1; $c12e = $codeLines.Count
  for ($c12i = 0; $c12i -lt $codeLines.Count; $c12i++) { if ($codeLines[$c12i].StartsWith($c10Mark)) { $c12s = $c12i; break } }
  if ($c12s -ge 0) { for ($c12j = $c12s + 1; $c12j -lt $codeLines.Count; $c12j++) { if ($codeLines[$c12j] -match '^function ') { $c12e = $c12j; break } } }
  $c12Body = $(if ($c12s -ge 0) { ($codeLines[$c12s..($c12e - 1)] -join "`n") } else { '' })
  ST-Check 'lint: the chrome restart gates on the before-pid set reaching zero, not on IsWindow of the closed frame' (
    ($c12s -ge 0) -and (-not $c12Body.Contains('IsWindow')) -and $c12Body.Contains('$beforePids'))
  ST-Check 'lint: the chrome restart carries the closed browser profile across the relaunch (a non-default scope must come back as itself)' (
    ($c12s -ge 0) -and (@(@($codeLines[$c12s..($c12e - 1)]) | Where-Object { $_.Contains('$anchorUdd -ne $defaultUdd') }).Count -eq 1))
  # No socket read may block forever. Measured 2026-09-30: `ReceiveAsync(...).GetAwaiter()
  # .GetResult()` hung a real chrome-debug-off call for 8 minutes with the loop's own
  # stopwatch check never getting a turn - a hung automation call is worse than a failed
  # one, because the operator cannot tell the difference from outside.
  $c16Unb = New-Object System.Collections.ArrayList
  $c16Bnd = 0
  for ($c16i = 0; $c16i -lt $codeLines.Count; $c16i++) {
    if ($c16i -ge $j5ProdStart -and $c16i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c16i] -match '^\s*#') { continue }
    if ($codeLines[$c16i].Contains('ReceiveAsync') -and $codeLines[$c16i].Contains('GetAwaiter')) { [void]$c16Unb.Add($c16i + 1) }
    if ($codeLines[$c16i].Contains(('if (-not $rt' + '.Wait(')) -or $codeLines[$c16i].Contains(('if (-not $rt2' + '.Wait('))) { $c16Bnd++ }
  }
  ST-Check 'lint: every CDP socket read is bounded (no ReceiveAsync + GetAwaiter().GetResult() combination may block forever)' (
    (@($c16Unb).Count -eq 0) -and ($c16Bnd -ge 2))
  if (@($c16Unb).Count -gt 0) { Write-Output "      unbounded receives at lines: $(@($c16Unb) -join ', ')" }
  $c13Bad = ''
  try { [void](Invoke-DesktopCommand 'chrome-a11y' @('sideways')) } catch { $c13Bad = $_.Exception.Message }
  $c13NoArg = ''
  try { [void](Invoke-DesktopCommand 'chrome-a11y' @()) } catch { $c13NoArg = $_.Exception.Message }
  ST-Check 'unit: chrome-a11y rejects a missing or unknown mode before it resolves a window (a bad argument must not bounce the browser)' (
    $c13Bad.Contains("must be 'on' or 'off'") -and $c13Bad.Contains('sideways') -and (-not $c13Bad.Contains('no Chrome window')) -and $c13NoArg.Contains('usage: chrome-a11y'))
  $c14Bad = ''
  try { [void](Invoke-DesktopCommand 'a11y-probe' @('DTX-NoSuchWindow-ZZ', '0')) } catch { $c14Bad = $_.Exception.Message }
  $c14NoSel = ''
  try { [void](Invoke-DesktopCommand 'a11y-probe' @()) } catch { $c14NoSel = $_.Exception.Message }
  ST-Check 'unit: a11y-probe rejects bigDepth below 1 and a missing selector before walking anything' (
    $c14Bad.Contains('bigDepth must be >= 1') -and $c14Bad.Contains('got 0') -and $c14NoSel.Contains('usage: a11y-probe'))
  # uia-find with an empty nameSub used to match EVERY element (measured: hits=149), so a
  # broken caller looked like a successful search. It must refuse, and refuse BEFORE any
  # window is resolved - the second call below proves the ordering by failing later, with
  # a different message.
  $c17Empty = ''
  try { [void](Invoke-DesktopCommand 'uia-find' @('DTX-NoSuchWindow-ZZ', ' ')) } catch { $c17Empty = $_.Exception.Message }
  $c17Order = ''
  try { [void](Invoke-DesktopCommand 'uia-find' @('DTX-NoSuchWindow-ZZ', 'x')) } catch { $c17Order = $_.Exception.Message }
  ST-Check 'unit: uia-find refuses an empty nameSub before resolving a window, and a non-empty one still reaches the window lookup' (
    $c17Empty.Contains('must not be empty') -and (-not $c17Empty.Contains('no window matching')) -and $c17Order.Contains('no window matching') -and (-not $c17Order.Contains('must not be empty')))
  # ---------- v2.1.0 (plan doc 1.2): the UIA cold-start re-contact ----------
  # Both directions of the rule, then the rule RUN with an injected walker. The
  # injection is the point: a live cold start cannot be staged on demand (owner ruling
  # closed v1.8.0 limitation 15 as structurally unprovable - any compliant restart path
  # lights the tree before the reader's first contact), so "the re-contact is what found
  # it" is proven offline and is NOT written up as an end-to-end live proof.
  $u12Hit = Get-UiaReprobeDecision 1 4 25
  ST-Check 'unit: uia reprobe - a first-contact hit never re-contacts (no second walk on a normal find)' (
    (-not $u12Hit.Rerun) -and $u12Hit.Reason.Contains('hit on first contact'))
  $u12Cold = Get-UiaReprobeDecision 0 14 25
  ST-Check 'unit: uia reprobe - 0 hits on a shallow first contact is the cold-start shape and re-contacts once' (
    $u12Cold.Rerun -and $u12Cold.Reason.Contains('scanned=14 < floor=25'))
  $u12Deep = Get-UiaReprobeDecision 0 25 25
  ST-Check 'unit: uia reprobe - 0 hits on a deep tree reads genuinely absent and does NOT re-contact (without this direction the floor is not a rule)' (
    (-not $u12Deep.Rerun) -and $u12Deep.Reason.Contains('genuinely absent'))
  $u12Off = Get-UiaReprobeDecision 0 3 0
  ST-Check 'unit: uia reprobe - floor 0 disables the re-contact and says which knob did it' (
    (-not $u12Off.Rerun) -and $u12Off.Reason.Contains('reprobe disabled'))
  $u12Walk = {
    param($contact)
    $late = [pscustomobject]@{ Current = [pscustomobject]@{ Name = $(if ($contact -ge 2) { 'DTXCOLDLATE' } else { 'unlit placeholder' }) } }
    $plain = [pscustomobject]@{ Current = [pscustomobject]@{ Name = 'always present' } }
    return @{ Elements = @($late, $plain); Scanned = 2; Roots = 1; Via = 'handle' }
  }
  $u12S = Search-UiaTree $u12Walk 'DTXCOLDLATE' '' (Get-UiaReprobeFloor)
  ST-Check 'unit: uia search - the re-contact is what turns a cold zero into a hit (walks=2 and the echo names the second scan)' (
    (@($u12S.Hits).Count -eq 1) -and ($u12S.Walks -eq 2) -and ($u12S.Reprobe -ceq 'yes -> scanned=2, hits=1'))
  $u12S2 = Search-UiaTree $u12Walk 'always present' '' (Get-UiaReprobeFloor)
  ST-Check 'unit: uia search - a first-contact hit walks exactly once and reports reprobe=no' (
    (@($u12S2.Hits).Count -eq 1) -and ($u12S2.Walks -eq 1) -and ($u12S2.Reprobe -ceq 'no'))
  $u12WalkNever = { param($contact) return @{ Elements = @(); Scanned = 3; Roots = 1; Via = 'pid-enum' } }
  $u12S3 = Search-UiaTree $u12WalkNever 'anything' '' (Get-UiaReprobeFloor)
  ST-Check 'unit: uia search - a re-contact that still finds nothing says so instead of leaving a bare zero' (
    (@($u12S3.Hits).Count -eq 0) -and ($u12S3.Walks -eq 2) -and ($u12S3.Reprobe -like 'yes -> still 0*'))
  # One floor producer, and every consumer of the rule must read it from that producer
  # (a threshold copy is how a11y-probe's and uia-find's cold-start behaviour would
  # silently split into two definitions of "cold").
  $u12FloorSites = 0; $u12FloorEcho = 0; $u12ReprobeEcho = 0
  for ($u12i = 0; $u12i -lt $codeLines.Count; $u12i++) {
    if ($u12i -ge $j5ProdStart -and $u12i -lt $j5ProdEnd) { continue }
    if ($codeLines[$u12i] -match '^\s*#') { continue }
    if ($codeLines[$u12i].Contains('= Get-UiaReprobeFloor')) { $u12FloorSites++ }
    if ($codeLines[$u12i].Contains('repro' + 'be-floor=')) { $u12FloorEcho++ }
    if ($codeLines[$u12i].Contains('cold-zero-repro' + 'be=')) { $u12ReprobeEcho++ }
  }
  ST-Check 'lint: the reprobe floor has one producer, both roads that read it self-report it, and the cold-start field is spoken by exactly the three readers that re-contact (a11y-probe, uia-find, find)' (
    ($u12FloorSites -eq 1) -and ($u12FloorEcho -eq 2) -and ($u12ReprobeEcho -eq 3))
  Write-Output ("      uia reprobe: floor-sites=$u12FloorSites echo-sites=$u12FloorEcho cold-field-sites=$u12ReprobeEcho")

  # ---------- v2.4.0: action tokens + structural path handles (pure rules, no UIA) ----------
  # The pattern singletons need the UIA assemblies: load them here (idempotent) -
  # the runtime loads them lazily inside Uia-Roots, but this block must also pass
  # in an offline selftest run that never dispatched a UIA command.
  Add-Type -AssemblyName UIAutomationClient
  Add-Type -AssemblyName UIAutomationTypes
  $v24Invoke = [System.Windows.Automation.InvokePattern]::Pattern
  $v24Value = [System.Windows.Automation.ValuePattern]::Pattern
  $v24ScrollItem = [System.Windows.Automation.ScrollItemPattern]::Pattern
  ST-Check 'unit: uia action tokens map an invoke-only pattern list to the invoke verb' (
    (Get-UiaActionTokensFromPatterns @($v24Invoke)) -ceq 'invoke')
  ST-Check 'unit: uia action tokens keep the canonical verb order regardless of pattern order' (
    (Get-UiaActionTokensFromPatterns @($v24ScrollItem, $v24Value)) -ceq 'value,scroll')
  ST-Check 'unit: uia action tokens for a probed pattern-less node are the empty (probed-none) string' (
    (Get-UiaActionTokensFromPatterns @()) -ceq '')
  ST-Check 'unit: uia path token shape accepts /0 and /0/2/1/4, refuses 0/2, /1 (root must be /0), /0//2 and /0/2/' (
    (Test-UiaPathTokenShape '/0') -and (Test-UiaPathTokenShape '/0/2/1/4') -and
    (-not (Test-UiaPathTokenShape '0/2')) -and (-not (Test-UiaPathTokenShape '/1')) -and
    (-not (Test-UiaPathTokenShape '/0//2')) -and (-not (Test-UiaPathTokenShape '/0/2/')))
  $v24E1 = Parse-UiaExpectToken 'Button|OK|123,45,80x24'
  $v24E2 = Parse-UiaExpectToken 'Pane||10,20,30x40'
  ST-Check 'unit: uia expect token parses Type|nameSub|rect incl. an empty name and parentheses' (
    ($null -ne $v24E1) -and ($v24E1.Type -ceq 'Button') -and ($v24E1.Name -ceq 'OK') -and ($v24E1.Rect -ceq '123,45,80x24') -and
    ($null -ne $v24E2) -and ($v24E2.Name -ceq ''))
  ST-Check 'unit: uia expect token refuses 2-field shapes, empty types and bad rects, tolerates a parenthesised rect' (
    ($null -eq (Parse-UiaExpectToken 'Button|OK')) -and ($null -eq (Parse-UiaExpectToken '|OK|1,2,3x4')) -and
    ($null -eq (Parse-UiaExpectToken 'Button|OK|123,45')) -and
    ($null -ne (Parse-UiaExpectToken 'Button|OK|(123,45,80x24)')))
  $v24Id = @{ Type = 'Button'; Name = 'OK, confirm'; Rect = '123,45,80x24'; RectParts = @(123, 45, 80, 24) }
  ST-Check 'unit: uia expect match passes when all three fields agree' ((Test-UiaExpectMatch $v24E1 $v24Id).Ok)
  ST-Check 'unit: uia expect match refuses a type mismatch, a name mismatch and a rect mismatch' (
    (-not (Test-UiaExpectMatch (Parse-UiaExpectToken 'Pane|OK|123,45,80x24') $v24Id).Ok) -and
    (-not (Test-UiaExpectMatch (Parse-UiaExpectToken 'Button|Cancel|123,45,80x24') $v24Id).Ok) -and
    (-not (Test-UiaExpectMatch (Parse-UiaExpectToken 'Button|OK|9,9,9x9') $v24Id).Ok))
  ST-Check 'unit: an empty-name expect matches an unnamed element and refuses a named one' (
    (Test-UiaExpectMatch (Parse-UiaExpectToken 'Button||123,45,80x24') @{ Type = 'Button'; Name = ''; Rect = '123,45,80x24'; RectParts = @(123, 45, 80, 24) }).Ok -and
    (-not (Test-UiaExpectMatch (Parse-UiaExpectToken 'Button||123,45,80x24') @{ Type = 'Button'; Name = 'X'; Rect = '123,45,80x24'; RectParts = @(123, 45, 80, 24) }).Ok))
  $v24Ref = Format-UiaPathRefusal '/0/2/1/4' @{ Ok = $false; Reason = 'stale'; Path = '/0/2/1/4' } (Parse-UiaExpectToken 'Button|OK|123,45,80x24') @{ Type = 'Pane'; Name = ''; Rect = '9,8,7x6'; RectParts = $null }
  ST-Check 'unit: the stale refusal names the path, both identities and the fallback roads' (
    ("$v24Ref".Contains('REFUSED: path=/0/2/1/4 stale')) -and
    ("$v24Ref".Contains("expected: Button | name='OK' | rect=123,45,80x24")) -and
    ("$v24Ref".Contains("actual: Pane | name='' | rect=9,8,7x6")) -and
    ("$v24Ref".Contains('fallback: uia-find / find <text> / find-text (OCR)')))
  $v24Td = Resolve-UiaPath @() '@/0/2/1/4' 2
  ST-Check 'unit: a path deeper than the walked bound refuses with "path depth N > walked M", never silently' (
    (-not $v24Td.Ok) -and ($v24Td.Reason -ceq 'too-deep') -and ("$($v24Td.Detail)".Contains('path depth 3 > walked 2')))
  $v24De = Resolve-UiaPath @() '@/0/2/1/9' 0
  ST-Check 'unit: an empty root list refuses as no-root instead of crashing or faking a hit' (
    (-not $v24De.Ok) -and ($v24De.Reason -ceq 'no-root'))
  $v24Dead = Format-UiaPathRefusal '/0/2/1/9' @{ Ok = $false; Reason = 'dead-end'; Path = '/0/2/1/9'; Detail = 'dead-end at /0/2/1 (child index 9 of 5)' } $null $null
  ST-Check 'unit: the dead-end refusal reports the parent, the index and the fallback roads' (
    ("$v24Dead".Contains('REFUSED: path=/0/2/1/9 dead-end')) -and ("$v24Dead".Contains('child index 9 of 5')) -and ("$v24Dead".Contains('fallback:')))
  ST-Check 'lint: the @-mark routes all three uia action commands through the verify-then-act helpers' (
    ((@($codeLines | Where-Object { $_ -match '\.StartsWith\(.@.\)' }).Count) -ge 3) -and
    ((@($codeLines | Where-Object { $_ -match 'Invoke-UiaClickByPath' }).Count) -ge 2) -and
    ((@($codeLines | Where-Object { $_ -match 'Invoke-UiaFocusByPath' }).Count) -ge 2) -and
    ((@($codeLines | Where-Object { $_ -match 'Invoke-UiaSettextByPath' }).Count) -ge 2) -and
    ((@($codeLines | Where-Object { $_ -match 'Format-UiaPathRefusal' }).Count) -ge 4))
  ST-Check 'lint: uia-tree strips its three v2.4.0 flags before the positional shape and refuses unknown --words' (
    ((@($codeLines | Where-Object { $_ -match "--eq '--actions-all'" }).Count) -ge 1) -and
    ((@($codeLines | Where-Object { $_ -match "--eq '--no-actions'" }).Count) -ge 1) -and
    ((@($codeLines | Where-Object { $_ -match "--eq '--no-paths'" }).Count) -ge 1) -and
    ((@($codeLines | Where-Object { $_ -match 'unknown flag ''\$w0''' }).Count) -ge 1))
  $v24Ci = -1
  for ($v24i = 0; $v24i -lt $clCount; $v24i++) { if ("$($codeLines[$v24i])" -match '^function Invoke-UiaClickByPath') { $v24Ci = $v24i; break } }
  $v24Cj = -1; $v24Ck = -1
  if ($v24Ci -ge 0) {
    for ($v24j = $v24Ci + 1; $v24j -lt [Math]::Min($v24Ci + 50, $clCount); $v24j++) {
      if ("$($codeLines[$v24j])" -match 'Invoke-UiaClickable') { $v24Cj = $v24j; break }
    }
    for ($v24k = $v24Ci + 1; $v24k -lt $v24Cj; $v24k++) {
      if ("$($codeLines[$v24k])" -match 'Test-UiaExpectMatch') { $v24Ck = $v24k; break }
    }
  }
  ST-Check 'lint: uia-click @path verifies the expected token BEFORE the click helper can run (verify-then-act)' (
    ($v24Ci -ge 0) -and ($v24Cj -gt $v24Ci) -and ($v24Ck -gt $v24Ci) -and ($v24Ck -lt $v24Cj))
  ST-Check 'contract: the usage block documents uia-path and the uia-tree action flags' (
    ((@($codeLines | Where-Object { $_ -match 'uia-path <sel> @/0/2/1 \[maxDepth\]' }).Count) -ge 1) -and
    ((@($codeLines | Where-Object { $_ -match '--actions-all' }).Count) -ge 2))
  # ---------- v3.0.1 (audit #3/#6/#7): the Rect.Empty family ----------
  # UIA answers "this element has no rectangle" with System.Windows.Rect.Empty, whose
  # members are INFINITIES (X=+Inf Y=+Inf Width=-Inf Height=-Inf), not zeros. Measured
  # on this machine before writing any of this: [int] of -Infinity throws, and
  # "$br.Y -ge $pageTop" is TRUE for an element that is nowhere. So the guard question
  # must come first at every consumer, and both directions are asserted here.
  $reRectOk = $true
  try { Add-Type -AssemblyName WindowsBase } catch { $reRectOk = $false }
  if (-not $reRectOk) {
    ST-Skip 'unit: Test-UiaRectUsable separates Rect.Empty from a real rectangle' 'WindowsBase did not load on this machine - no Rect type to test'
    ST-Skip 'unit: the page-area test refuses an element with no rectangle (its Y is +Infinity)' 'WindowsBase did not load on this machine - no Rect type to test'
  } else {
    $reEmpty = [System.Windows.Rect]::Empty
    $reReal = New-Object System.Windows.Rect(10, 200, 30, 40)
    $reNaN = New-Object System.Windows.Rect([double]::NaN, 0, 1, 1)
    ST-Check 'unit: Test-UiaRectUsable refuses Empty/null/NaN and accepts a real rectangle' (
      (-not (Test-UiaRectUsable $reEmpty)) -and (-not (Test-UiaRectUsable $null)) -and
      (-not (Test-UiaRectUsable $reNaN)) -and (Test-UiaRectUsable $reReal))
    # the #6 shape: the OLD code was "$br.Y -ge $pageTop", and Empty.Y is +Infinity, so
    # an element that is nowhere counted as page content and could flip the probe verdict.
    ST-Check 'unit: the page-area test refuses an element with no rectangle (its Y is +Infinity)' (
      (-not (Test-UiaInPageArea $reEmpty 100)) -and (Test-UiaInPageArea $reReal 100) -and
      (Test-UiaInPageArea $reReal 200) -and (-not (Test-UiaInPageArea $reReal 201)))
    Write-Output ("      Rect.Empty probe: X=" + $reEmpty.X + " W=" + $reEmpty.Width + " IsEmpty=" + $reEmpty.IsEmpty)
  }
  $reFuncStart = @()
  for ($rei = 0; $rei -lt $codeLines.Count; $rei++) { if ($codeLines[$rei] -match '^function ') { $reFuncStart += $rei } }
  $reUnguarded = New-Object System.Collections.ArrayList
  for ($rei = 0; $rei -lt $codeLines.Count; $rei++) {
    if ($rei -ge $j5ProdStart -and $rei -lt $j5ProdEnd) { continue }
    if ($codeLines[$rei] -match '^\s*#') { continue }
    if (-not $codeLines[$rei].Contains('BoundingRectangle')) { continue }
    $reFs = -1; $reFe = $codeLines.Count
    foreach ($cand in $reFuncStart) { if ($cand -le $rei) { $reFs = $cand } else { $reFe = $cand; break } }
    if ($reFs -lt 0) { [void]$reUnguarded.Add(($rei + 1)); continue }
    $reBody = ($codeLines[$reFs..($reFe - 1)] -join "`n")
    if (-not ($reBody.Contains('Test-UiaRectUsable') -or $reBody.Contains('.IsEmpty'))) { [void]$reUnguarded.Add(($rei + 1)) }
  }
  ST-Check 'lint: every production BoundingRectangle reader asks the emptiness question first (a new site that forgets is this family, again)' (
    @($reUnguarded).Count -eq 0)
  if (@($reUnguarded).Count -gt 0) { Write-Output "      unguarded BoundingRectangle read at line(s): $(Format-SourceLineList @($reUnguarded))" }

  # ---------- v3.0.1 (audit #4): the CDP viewport fallback had one axis ----------
  # The JS route computed Y from screenY and then, when no window could be resolved, put
  # screenY INTO X. It self-reported Formula='js-outer-minus-inner' and Ok=true the whole
  # time, so chrome-find mapped the page rect to a screen point nobody had measured.
  $cdpPt = Get-CdpViewportOriginJs 1.5 100 200 800 600 820 700
  ST-Check 'unit: the CDP JS-route origin computes each axis from its own screen coordinate' (
    ($cdpPt.X -eq 165) -and ($cdpPt.Y -eq 450))
  # the report's own falsification, run through the real function shape: a Y of 300 at 1.5
  # used to arrive as X=450. Asserting X is NOT that number is what keeps the axes apart.
  $cdpSwap = Get-CdpViewportOriginJs 1.5 40 300 1000 500 1000 500
  ST-Check 'unit: a large screenY cannot leak into X any more (the audit number was X=450 from Y=300 at dpr 1.5)' (
    ($cdpSwap.Y -eq 450) -and ($cdpSwap.X -eq 60))
  $cdpJsProbe = 0
  $cdpHelperUse = 0
  $cdpCallSites = 0
  for ($cdpI = 0; $cdpI -lt $clCount; $cdpI++) {
    if ($cdpI -ge $j5ProdStart -and $cdpI -lt $j5ProdEnd) { continue }
    $cdpL = [string]$codeLines[$cdpI]
    if ($cdpL.Contains('window.devicePixelRatio') -and $cdpL.Contains('sx: window.screenX') -and $cdpL.Contains('sy: window.screenY')) { $cdpJsProbe++ }
    if ($cdpL.Contains('= Get-CdpViewportOriginJs ')) { $cdpHelperUse++ }
    if ($cdpL.Contains('Get-CdpViewportOrigin ' + '$base')) { $cdpCallSites++ }
  }
  ST-Check 'lint: the CDP origin route derives from the one pure helper, and its metrics probe asks for both axes' (
    ($cdpJsProbe -eq 1) -and ($cdpHelperUse -ge 1) -and ($cdpCallSites -ge 1))
  Write-Output ("      cdp origin wiring: helper-calls=$cdpHelperUse probe-with-sx=$cdpJsProbe call-sites=$cdpCallSites")

  # ---------- TB-2 (2026-10-24): the send phase has a budget (dynamic, loopback) ----------
  # The connect-side half of the one-budget shape was measured against a no-handshake loopback
  # fixture (2026-10-23 rig, outside this repository). The send-side half had no dynamic cell:
  # a peer that completes the upgrade and then never read fills the socket buffers, SendAsync
  # never completes, and only the shared CancellationToken ends it. This cell builds that peer
  # for real - a background runspace completes the upgrade handshake and then blocks on a
  # second accept it never gets, so the socket stays open and unread - and asserts the budget
  # expired IN the send phase with the call returning bounded, not hung.
  $tb2ProbeResult = $null
  $tb2ElapsedMs = -1
  $tb2Ps = $null
  $tb2Rs = $null
  $tb2Listener = $null
  $tb2Handle = $null
  $tb2Hold = $null
  try {
    $tb2Listener = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback, 0)
    $tb2Listener.Start()
    $tb2Port = $tb2Listener.LocalEndpoint.Port
    $tb2Rs = [runspacefactory]::CreateRunspace()
    $tb2Rs.Open()
    $tb2Ps = [powershell]::Create()
    $tb2Ps.Runspace = $tb2Rs
    [void]$tb2Ps.AddScript({
      param($L)
      $c = $L.AcceptTcpClient()
      $s = $c.GetStream()
      $req = New-Object System.Text.StringBuilder
      $buf = New-Object byte[] 4096
      while (-not ($req.ToString().Contains("`r`n`r`n"))) {
        $n = $s.Read($buf, 0, $buf.Length)
        if ($n -le 0) { break }
        [void]$req.Append([Text.Encoding]::ASCII.GetString($buf, 0, $n))
      }
      $key = ''
      $m = [regex]::Match($req.ToString(), 'Sec-WebSocket-Key: ([^\r\n]+)')
      if ($m.Success) { $key = $m.Groups[1].Value.Trim() }
      $sha = [System.Security.Cryptography.SHA1]::Create()
      $accept = [Convert]::ToBase64String($sha.ComputeHash([Text.Encoding]::ASCII.GetBytes($key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')))
      $resp = "HTTP/1.1 101 Switching Protocols`r`nUpgrade: websocket`r`nConnection: Upgrade`r`nSec-WebSocket-Accept: $accept`r`n`r`n"
      $rbytes = [Text.Encoding]::ASCII.GetBytes($resp)
      $s.Write($rbytes, 0, $rbytes.Length)
      $s.Flush()
      # Never read again: the send side must be the side that runs out of budget. The pipeline
      # RETURNS the accepted client instead of blocking on a second accept - a blocked .NET call
      # is not interruptible by PowerShell.Stop(), so a hold-open loop here would hang Dispose.
      return $c
    }).AddArgument($tb2Listener)
    $tb2Handle = $tb2Ps.BeginInvoke()
    $tb2Sw = [System.Diagnostics.Stopwatch]::StartNew()
    $tb2ProbeResult = Invoke-CdpEval ("http://127.0.0.1:" + $tb2Port) 'TB2PAGE' ('"' + ('x' * 524288) + '"') 1200
    $tb2ElapsedMs = [int]$tb2Sw.ElapsedMilliseconds
    $tb2ErrText = "$($tb2ProbeResult.Error)"
    $tb2BoundedOk = (($null -ne $tb2ProbeResult) -and (-not $tb2ProbeResult.Ok) -and
      ($tb2ErrText.Contains('budget expired during the')) -and
      ($tb2ElapsedMs -ge 1100) -and ($tb2ElapsedMs -lt 8000))
    # Two arms, one name: the send-side premise (512KB blocks the send) is a PS 5.1 / .NET Framework
    # shape - the pwsh runtimes drain the frame, the budget then expires during the receive wait, and
    # that measured shape SKIPs under its OWN name with the reading (G-21/G-22 discipline: nothing
    # absorbed, the total stays). The bounded-return invariant holds on both arms and is asserted here.
    # The name is an INLINE literal on both arms on purpose: the static index only sees literal
    # arguments, and a variable-carried name is the exact rot this contract check exists to catch.
    if ($PSVersionTable.PSVersion.Major -le 5) {
      ST-Check 'unit (TB-2): a peer that handshakes and then never read keeps the shared CDP budget honest - the call returns bounded with the expired phase named and the wall clock inside the budget plus disposal slack' (
        $tb2BoundedOk -and ($tb2ErrText.Contains('budget expired during the send phase')))
    } else {
      ST-Skip 'unit (TB-2): a peer that handshakes and then never read keeps the shared CDP budget honest - the call returns bounded with the expired phase named and the wall clock inside the budget plus disposal slack' ('this engine (' + $PSVersionTable.PSVersion.ToString() + ') drains the 512KB probe frame without blocking the send - measured: ' + $tb2ErrText + ', elapsedMs=' + $tb2ElapsedMs + '; the send-phase shape stays pinned on the 5.1 arm')
    }
    Write-Output ('      TB-2 send-budget: ok=' + $tb2ProbeResult.Ok + ' elapsedMs=' + $tb2ElapsedMs + ' error=' + $tb2ErrText)
  } finally {
    # The handshake pipeline returned long ago (it only writes the upgrade response and comes
    # back). EndInvoke reclaims it and keeps the accepted client referenced, so the socket cannot
    # be finalized mid-check and no blocked .NET call is left for Dispose to interrupt.
    if ($null -ne $tb2Ps) {
      if ($null -ne $tb2Handle) { try { $tb2Hold = $tb2Ps.EndInvoke($tb2Handle) } catch { $tb2Hold = $_.Exception.Message } }
      $tb2Ps.Dispose()
    }
    if ($null -ne $tb2Rs) { $tb2Rs.Dispose() }
    if ($null -ne $tb2Listener) { $tb2Listener.Stop() }
  }

}

# lib/selftest-docs-contract.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1 by A-14k (A-beta).
# Bodies are byte-identical to what the section carried. The only channel to the orchestrator is the
# explicit context object: shared state arrives through $Ctx and nothing else, because A-14e/A-14i
# measured what happens when a body reaches for a caller local instead.
# The outward-documentation family: the help-page index and the per-command page, the document-
# consistency sweep over the markdown, the skill loader command list and its scripts, the quick-start
# guide, and the shape of the usage page itself. A-14j hoisted the producers this family used to own,
# so after that lift it needed nothing from another body - which is why it could move at all.
function Invoke-SelftestFamily-DocsContract($Ctx) {
  # context handover (the one thing in this file that is not lifted text)
  $clCount = $Ctx['clCount']
  $codeLines = $Ctx['codeLines']
  $hCaseStarts = $Ctx['hCaseStarts']
  $hFnStart = $Ctx['hFnStart']
  $hLines = $Ctx['hLines']
  $src = [string]$Ctx['src']

  # ---------- unit: v1.5.7 help <command> - the page gets an index ----------
  $hNames = Get-HelpCommandNames $hLines
  ST-Check 'unit: the help index sees the commands (>= 55 entries, scan is not vacuous)' (@($hNames).Count -ge 55)
  $hClick = @(Format-CommandHelp $hLines 'click')
  $hShot = @(Format-CommandHelp $hLines 'shot')
  $hWins = @(Format-CommandHelp $hLines 'wins')
  $hType = @(Format-CommandHelp $hLines 'type')
  $hExpChg = @(Format-CommandHelp $hLines '--expect-change')
  ST-Check 'unit: help click returns its own entry and points at where shared flags live' (
    (@($hClick).Count -ge 2) -and $hClick[0].Trim().StartsWith('click ') -and
    (@($hClick | Where-Object { $_ -match 'global flags' }).Count -eq 1))
  ST-Check 'unit: help <flag> finds the shared paragraph a per-command slice cannot show' (
    (@($hExpChg).Count -ge 2) -and (@($hExpChg | Where-Object { $_ -match 'expect-change' }).Count -ge 1))
  ST-Check 'unit: help shot lists its own flags including --no-grid (v1.5.7b)' (
    $hShot[0].Contains('--no-grid') -and $hShot[0].Contains('--grid'))
  ST-Check 'unit: help wins lists the D-7 columns' (@($hWins | Where-Object { $_ -match 'main' }).Count -ge 1)
  ST-Check 'unit: help type stays inside type (the slice does not run into type-in)' (
    $hType[0].Trim().StartsWith('type ') -and (@($hType | Where-Object { $_ -match '^    type-in ' }).Count -eq 0))
  # option-list pipes inside a synopsis (--occlude off|warn|strict) are NOT commands
  ST-Check 'unit: the help index does not mistake option values for command names' (
    -not (@($hNames) -contains 'warn') -and -not (@($hNames) -contains 'strict') -and (@($hNames) -contains 'shot'))
  # a multi-command synopsis line must resolve for EVERY name on it. These calls are
  # wrapped so a regression produces a NAMED FAIL instead of aborting selftest before its
  # summary (an abort is red too, but it hides every check that comes after it).
  $hMinTxt = ''
  try { $hMinTxt = (@(Format-CommandHelp $hLines 'win-min') -join "`n") } catch { $hMinTxt = 'THREW: ' + $_.Exception.Message }
  $hCloseTxt = ''
  try { $hCloseTxt = (@(Format-CommandHelp $hLines 'win-close') -join "`n") } catch { $hCloseTxt = 'THREW: ' + $_.Exception.Message }
  ST-Check 'unit: a shared synopsis line resolves for each name on it (win-min/win-close)' (
    ($hMinTxt -match 'win-min') -and ($hCloseTxt -match 'win-close'))
  $hErr = ''
  try { [void](Format-CommandHelp $hLines 'no-such-command') } catch { $hErr = $_.Exception.Message }
  ST-Check 'unit: help <unknown> refuses and offers the whole page' (
    $hErr.Contains("no help entry for 'no-such-command'") -and -not ($hErr -like '*did you mean*'))
  $hSug = ''
  try { [void](Format-CommandHelp $hLines 'clik') } catch { $hSug = $_.Exception.Message }
  ST-Check 'unit: a near-miss command name gets candidates, not a bare refusal' ($hSug.Contains('did you mean') -and $hSug.Contains('click'))
  $hFlag = ''
  try { [void](Format-CommandHelp $hLines '--definitely-not-a-flag') } catch { $hFlag = $_.Exception.Message }
  ST-Check 'unit: help --<unknown flag> refuses instead of printing nothing' ($hFlag.Contains('no mention of'))
  # a page-level entry resolves (selftest is documented at 2-space indent, not as a command
  # synopsis), but the GROUP HEADERS at the same indent are not commands and must be refused
  $hSelf = @(Format-CommandHelp $hLines 'selftest')
  ST-Check 'unit: help selftest finds the page-level entry' (@($hSelf | Where-Object { $_ -match 'mechanical regression' }).Count -ge 1)
  $hHdr = ''
  try { [void](Format-CommandHelp $hLines 'clipboard') } catch { $hHdr = $_.Exception.Message }
  ST-Check 'unit: a 2-space group header is not treated as a command' ($hHdr.Contains("no help entry for 'clipboard'"))
  # meta entries the page documents in prose instead of a synopsis line - kept as an
  # explicit list so a new command cannot quietly join it
  $hExcept = @()
  # @(hashtable).Count is ALWAYS 1 in PS 5.1, AND a key named 'keys' shadows the .Keys
  # property (see Get-HashKeys) - both traps are pinned here because the dispatcher scan is
  # keyed by COMMAND NAMES, one of which is literally 'keys'. The first version of the
  # reachability lint iterated .Keys, ran its body ONCE over an Int32 line number, and
  # reported green for every private flag in the table.
  $hkProbe = @{}
  $hkProbe['keys'] = 8017
  $hkProbe['click'] = 100
  $hkProbe['shot'] = 200
  ST-Check 'unit: a hashtable key shadows .Keys while Get-HashKeys stays honest' (
    @($hkProbe.Keys).Count -eq 1 -and @($hkProbe.Keys)[0] -eq 8017 -and (Get-HashKeys $hkProbe).Count -eq 3)
  $hNoDoc = @(@(Get-HashKeys $hCaseStarts) | Where-Object { -not (@($hNames) -contains $_) -and -not ($hExcept -contains $_) })
  ST-Check 'lint: every dispatcher command has a help entry (help <cmd> cannot have blind spots)' (
    $hFnStart -ge 0 -and $hCaseStarts.Count -ge 50 -and @($hNoDoc).Count -eq 0)
  foreach ($x in @($hNoDoc)) { Write-Output ("      command with no help entry: [" + $x + "] type=" + $(if ($null -eq $x) { 'null' } else { $x.GetType().Name }) + " cases=" + $hCaseStarts.Count) }
  Write-Output ("      all case keys: " + ((Get-HashKeys $hCaseStarts | Sort-Object) -join ' '))
  # @(hashtable).Count is ALWAYS 1 in PS 5.1 - use .Count / .Keys bare (see the D-1 note).
  Write-Output ("      help index entries=" + @($hNames).Count + " dispatcher cases=" + $hCaseStarts.Count)

  # ---------- lint: v1.7.0 document-consistency sweep (traversal, no hand-maintained list) ----------
  # The owner named this version for exactly one disease: stale references and checklists
  # that quietly lose a file. Both directions are checked by traversal, never a list:
  #   README quick-reference lines must name REAL dispatcher commands, and every
  #   dispatcher command must appear somewhere in the README.
  $rdPath = Join-Path $script:ToolRootPath 'README.md'
  if (Test-Path -LiteralPath $rdPath) {
  $rdLines = @(Get-Content -LiteralPath (Join-Path $script:ToolRootPath 'README.md') -Encoding UTF8)
  $rdAllText = $rdLines -join "`n"
  $dcStartPat = '^## ' + [string]::Join('', @([char]0x547D, [char]0x4EE4, [char]0x901F, [char]0x67E5))
  $dcEndPat = '^## ' + [string]::Join('', @([char]0x5FC5, [char]0x987B, [char]0x8BB0, [char]0x4F4F, [char]0x7684, [char]0x5751))
  $dcStart = -1; $dcEnd = -1
  for ($j7i = 0; $j7i -lt $rdLines.Count; $j7i++) {
    if ($dcStart -lt 0 -and $rdLines[$j7i] -match $dcStartPat) { $dcStart = $j7i }
    elseif ($dcStart -ge 0 -and $rdLines[$j7i] -match $dcEndPat) { $dcEnd = $j7i; break }
  }
  $dcNames = New-Object System.Collections.ArrayList
  for ($j7i = $dcStart + 1; $j7i -lt $dcEnd; $j7i++) {
    if ($rdLines[$j7i] -match ('^-\s+`([a-z][a-z0-9-]+)')) { [void]$dcNames.Add($Matches[1]) }
  }
  $dcCase = @(Get-HashKeys $hCaseStarts)
  # entry-point commands dispatched OUTSIDE Invoke-DesktopCommand - an explicit list like
  # $hExcept, and each entry must still exist as a real dispatch case (asserted below), so
  # the exemptions cannot grow into a second hand-maintained command universe.
  $dcMeta = @('script', 'replay', 'selftest')
  $dcMetaLive = @($codeLines | Where-Object { $_ -match ('^\s{4}' + "'" + '(script|replay|selftest)' + "'" + ' \{') })
  ST-Check 'lint: the README-sweep exemptions are real dispatch targets (script/replay/selftest cases exist)' (@($dcMetaLive).Count -ge 3)
  $dcStale = @(@($dcNames) | Where-Object { ($dcCase -notcontains $_) -and ($dcMeta -notcontains $_) })
  ST-Check 'lint: every command in the README quick reference exists in the dispatcher (no stale references)' (
    ($dcStart -ge 0) -and ($dcEnd -gt $dcStart) -and (@($dcNames).Count -ge 30) -and (@($dcStale).Count -eq 0))
  if (@($dcStale).Count -gt 0) { Write-Output "      stale README commands: $(@($dcStale) -join ', ')" }
  $dcMissing = @(@($dcCase) | Where-Object { -not ("$rdAllText".Contains($_)) })
  ST-Check 'lint: every dispatcher command appears in the README (no under-documented command)' (
    (@($dcCase).Count -ge 50) -and (@($dcMissing).Count -eq 0))
  if (@($dcMissing).Count -gt 0) { Write-Output "      commands missing from README: $(@($dcMissing) -join ', ')" }
  } else {
    ST-Skip 'lint: the README-sweep exemptions are real dispatch targets (script/replay/selftest cases exist)' 'README documentation not present (installed copy) - the sweep cannot run'
    ST-Skip 'lint: every command in the README quick reference exists in the dispatcher (no stale references)' 'README documentation not present (installed copy)'
    ST-Skip 'lint: every dispatcher command appears in the README (no under-documented command)' 'README documentation not present (installed copy)'
  }

  # ---------- v4.1.3 (external review L): the skill loader's command list is an outward ----
  # contract, so it may only name commands THIS tree can run. The loader docs ship with the
  # installed skill, which means a phantom there is something an agent will keep trying to
  # call. The README sweep above only reads README.md, so when this tree dropped the
  # Per-Monitor V2 block that the published tree still carries, `dpi` stayed taught in
  # SKILL.md and every offline check stayed green. Traversal, not a hand list: the case set
  # comes from the dispatcher itself, and the exemption list is pinned against it.
  $skCaseSet = @(Get-HashKeys $hCaseStarts)
  $skMeta = @('script', 'replay', 'selftest')
  $skDocs = @('skill/agent-computer-use/SKILL.md', 'skill/agent-computer-use/reference.md')
  $skPresent = @($skDocs | Where-Object { Test-Path -LiteralPath (Join-Path $script:ToolRootPath $_) })
  if (@($skPresent).Count -eq @($skDocs).Count) {
    $skPhantom = @()
    $skSeen = 0
    foreach ($skDoc in @($skPresent)) {
      $skLines = @(Get-Content -LiteralPath (Join-Path $script:ToolRootPath $skDoc) -Encoding UTF8)
      foreach ($skl in $skLines) {
        if ($skl -match '^-\s+`([a-z][a-z0-9-]+)') {
          $skName = $Matches[1]
          $skSeen = $skSeen + 1
          if ((-not (@($skCaseSet) -contains $skName)) -and (-not (@($skMeta) -contains $skName))) { $skPhantom += ($skDoc + ':' + $skName) }
        }
      }
    }
    # script/replay/selftest are dispatched OUTSIDE Invoke-DesktopCommand (the same
    # exemption the README sweep makes), so they are not in $skCaseSet by construction -
    # they must still be proven to be real targets, or the exemption list becomes a second
    # command universe that the phantom lint cannot see.
    $skMetaLive = @($codeLines | Where-Object { $_ -match ('^\s{4}' + "'" + '(script|replay|selftest)' + "'" + ' \{') })
    ST-Check 'lint: the loader-doc exemptions are real dispatch targets (script/replay/selftest cases exist outside the main dispatcher)' (
      (@($skCaseSet).Count -ge 50) -and (@($skMetaLive).Count -ge 3) -and (@($skMeta).Count -eq 3))
    ST-Check 'lint: every command the skill loader teaches exists in this tree dispatcher (no phantom in the outward contract)' (
      $skSeen -ge 40 -and (@($skPhantom).Count -eq 0))
    if (@($skPhantom).Count -gt 0) { Write-Output ("      loader teaches commands this tree cannot run: " + ((@($skPhantom) | Sort-Object -Unique) -join ', ')) }
    Write-Output ("      loader command lines seen=" + $skSeen + " dispatcher cases=" + @($skCaseSet).Count)
  } else {
    ST-Skip 'lint: the loader-doc exemptions are real dispatch targets (script/replay/selftest cases exist outside the main dispatcher)' 'skill loader docs not both present (installed copy) - the sweep cannot run'
    ST-Skip 'lint: every command the skill loader teaches exists in this tree dispatcher (no phantom in the outward contract)' 'skill loader docs not both present (installed copy) - the sweep cannot run'
  }

  # ---------- v4.2.3: the quick-start guide is an outward contract too ----------
  # The quick-start guide (its filename is assembled from code points just below, so this file
  # stays pure ASCII) is the FIRST document a new agent reads, and it teaches commands by name.
  # Nothing compared it against this tree: the v1.7.0 sweep covers README.md and the v4.1.3 lint
  # covers the two skill-loader docs - the guide was the THIRD carrier of the same disease
  # (rename or drop a command and the newcomer document keeps teaching a dead one, silently).
  # Traversal, not a hand list. The exemption list is the same three entry-point commands both
  # sweeps above already pin as real dispatch targets; the floors (>=50 cases, >=3 taught lines)
  # are the positive controls that stop an empty scan from reading as "nothing wrong".
  $qsName = [string]::Join('', @([char]0x5FEB, [char]0x901F, [char]0x4E0A, [char]0x624B, [char]0x6307, [char]0x5357)) + '.md'
  $qsCaseSet = @(Get-HashKeys $hCaseStarts)
  $qsMeta = @('script', 'replay', 'selftest')
  $qsFile = Join-Path $script:ToolRootPath $qsName
  if (Test-Path -LiteralPath $qsFile) {
    $qsSeen = 0
    $qsPhantom = @()
    foreach ($qsl in @(Get-Content -LiteralPath $qsFile -Encoding UTF8)) {
      # The CLOSING backtick is load-bearing: a taught command is written `cmd` in full, while a
      # PATH in backticks must not read as a command name. Without it this check failed on a
      # perfectly correct document - the shared-audit-log line captured "shots" from
      # `shots/actions.log` (measured 2026-10-10: seen=6 with the false positive, 5 without).
      # Tightening the pattern is the fix; whitelisting "shots" would have hidden a real miss.
      if ($qsl -match '^-\s+`([a-z][a-z0-9-]+)`') {
        $qsN = $Matches[1]
        $qsSeen = $qsSeen + 1
        if ((-not (@($qsCaseSet) -contains $qsN)) -and (-not (@($qsMeta) -contains $qsN))) { $qsPhantom += $qsN }
      }
    }
    ST-Check 'lint: every command the quick-start guide teaches exists in this tree dispatcher (the newcomer document cannot teach a dead command)' (
      (@($qsCaseSet).Count -ge 50) -and ($qsSeen -ge 3) -and (@($qsPhantom).Count -eq 0))
    if (@($qsPhantom).Count -gt 0) { Write-Output ("      quick-start teaches commands this tree cannot run: " + ((@($qsPhantom) | Sort-Object -Unique) -join ', ')) }
    Write-Output ("      quick-start guide command lines seen=" + $qsSeen)
  } else {
    ST-Skip 'lint: every command the quick-start guide teaches exists in this tree dispatcher (the newcomer document cannot teach a dead command)' 'quick-start guide not present (installed copy) - the sweep cannot run'
  }

  # ---------- contract: the usage PAGE itself is well-formed (v3.0.1, 3.0.0 audit item 15) ----------
  # The page is a here-string, so $codeLines blanks it out and every check above is
  # blind to it; these read the raw source. Three shapes were measured broken:
  #   * one command named by two entry lines -> `help <cmd>` prints two entries with
  #     two different descriptions (measured: hash, wheel, a11y-probe),
  #   * a description glued to its label with a wide space run instead of wrapped,
  #     which renders as a column the eye cannot follow (measured: replay, --needle),
  #   * a paragraph whose lead-in is printed twice, so the sentence has no verb left
  #     on the first line (measured: the occlusion paragraph).
  # The gap rule needs a number: a label column always ends before index 45 (widest
  # label measured starts its description at 36), and the two broken lines put theirs
  # at 55 and 83. That is where the 45 comes from - not a tolerance, a measured seam.
  $usageRaw = @()
  $usageIn = $false
  $usageOpen = $false
  foreach ($uLine in ($src -split "`r?`n")) {
    if (-not $usageIn) { if ($uLine -match '^function Get-UsageText \{') { $usageIn = $true }; continue }
    if (-not $usageOpen) { if ($uLine -match "^\s*@'") { $usageOpen = $true }; continue }
    if ($uLine -match "^'@") { break }
    $usageRaw += [string]$uLine
  }
  # the extractor must actually find the page, or all three checks below are vacuous
  ST-Check 'lint: the usage-page shape checks can see the page (extractor is not vacuous)' (
    (@($usageRaw).Count -gt 500) -and ((@($usageRaw | Where-Object { $_ -match '^  read$' }).Count) -eq 1))
  $usageSeen = @{}
  $usageDupes = @()
  foreach ($uLine in $usageRaw) {
    $uEntry = [regex]::Match($uLine, '^    ([a-z][a-z0-9-]*)[ <\[]')
    if (-not $uEntry.Success) { continue }
    $uName = $uEntry.Groups[1].Value
    if ($usageSeen.ContainsKey($uName)) { $usageDupes += $uName } else { $usageSeen[$uName] = 1 }
  }
  ST-Check 'contract: no command name heads two usage entries (help <cmd> prints exactly one)' (
    @($usageDupes).Count -eq 0)
  if (@($usageDupes).Count -gt 0) { Write-Output ("      duplicated usage entries: " + (($usageDupes | Sort-Object -Unique) -join ', ')) }
  $usageGlued = @()
  foreach ($uLine in $usageRaw) {
    foreach ($uGap in [regex]::Matches($uLine, ' {20,}')) { if ($uGap.Index -ge 45) { $usageGlued += $uLine.Trim() } }
  }
  ST-Check 'contract: no usage line glues a description to its label with a wide space run' (
    @($usageGlued).Count -eq 0)
  foreach ($uBad in $usageGlued) { Write-Output "      glued usage line: $uBad" }
  $coverLeadIn = 'A covered' + ' target prints'
  $coverLines = @($usageRaw | Where-Object { $_.Contains($coverLeadIn) })
  ST-Check 'contract: the occlusion paragraph says once what a covered target prints' (
    @($coverLines).Count -eq 1)
  # v3.0.1 (audit item 15, fourth spot): a two-line fragment had drifted to the tail of
  # the --expect-handle entry, leaving a continuation line that was only the word
  # "wait-stable". It now lives inside that command entry, where --changed belongs.
  ST-Check 'contract: wait-stable documents --changed once and no entry ends in a stray command name' (
    (@($usageRaw | Where-Object { $_.Contains('[--changed]') }).Count -eq 1) -and
    (@($usageRaw | Where-Object { $_.Trim() -ceq 'wait-stable' }).Count -eq 0))

  # ---------- contract: a comment that advertises a ladder must walk the same one ----------
  # v3.0.1 (audit item 24): the paragraph above Wait-Foreground still described the
  # pre-v1.5.2 loop ("3 tries, 400ms apart") after the code had become a six-step
  # back-off. Narrow on purpose - this pins ONE comment, because a general prose lint
  # needs an exemption list and gets switched off inside a week. The expected text is
  # DERIVED from the loop, so editing the ladder without editing the paragraph is red.
  $wfI = -1
  for ($wI = 0; $wI -lt $clCount; $wI++) { if ([string]$codeLines[$wI] -match '^function Wait-Foreground') { $wfI = $wI; break } }
  $wfWant = ''
  $wfHead = ''
  $wfProse = ''
  if ($wfI -gt 9) {
    $wfMs = [regex]::Match([string]$codeLines[$wfI + 1], '@\(([\d,\s]+)\)')
    if ($wfMs.Success) { $wfWant = ((@($wfMs.Groups[1].Value -split ',') | ForEach-Object { $_.Trim() }) -join '/') }
    $wfHead = (($codeLines[($wfI - 9)..($wfI - 1)]) -join ' ')
    # WHOLE token, not a substring: measured with the ladder shortened by one step, a
    # Contains() test stayed GREEN because "0/100/200/300/300" sits inside the prose's
    # "0/100/200/300/300/300". Exactly one slash-run in the paragraph, exactly equal.
    $wfRuns = @([regex]::Matches($wfHead, '\d+(/\d+)+'))
    if (@($wfRuns).Count -eq 1) { $wfProse = [string]$wfRuns[0].Value }
  }
  ST-Check 'contract: the Wait-Foreground paragraph names the back-off ladder the loop walks' (
    ($wfI -gt 9) -and ($wfWant -ne '') -and (@([regex]::Matches($wfHead, '\d+(/\d+)+')).Count -eq 1) -and
    ($wfProse -ceq $wfWant) -and (-not $wfHead.Contains('400ms')))
  if (($wfWant -ne '') -and ($wfProse -cne $wfWant)) { Write-Output "      ladder drift: the loop walks $wfWant, the paragraph above says '$wfProse'" }

  # ---------- v3.0.1 (audit #23): the skill loader scripts carry the project guards ----------
  # The two scripts are tracked files and were written before the three-hard-guards rule
  # existed, so nothing connected them to it. StrictMode is now ON in both (verified by
  # installing into and uninstalling from a throwaway temp dir with this round's change in
  # place); $ErrorActionPreference stays 'Continue' ON PURPOSE - a terminating first error
  # in an installer leaves a half-copied skill behind, which is worse than collecting the
  # problems and exiting with a code. The check therefore pins the guard AND the reason.
  $skillGuards = @('Set-StrictMode -Version Latest', 'ErrorActionPreference')
  $skillFiles = @('skill\agent-computer-use\install.ps1', 'skill\agent-computer-use\uninstall.ps1')
  # A-22: the two loader scripts ship with the REPOSITORY, not with the stitched artifact, so an installed
  #    copy cannot have them. The same shape the loader-doc sweep above already uses - measure when the
  #    carriers are here, say so out loud when they are not; never a silent disappearance either way.
  $skillHere = @($skillFiles | Where-Object { Test-Path -LiteralPath (Join-Path $script:ToolRootPath $_) })
  if (@($skillHere).Count -eq @($skillFiles).Count) {
    $skillNoGuard = @()
    $skillNoReason = @()
    foreach ($sf in @($skillHere)) {
      $sfText = [System.IO.File]::ReadAllText((Join-Path $script:ToolRootPath $sf), [System.Text.Encoding]::UTF8)
      foreach ($sg in $skillGuards) { if (-not $sfText.Contains($sg)) { $skillNoGuard += ("$sf lacks $sg") } }
      if (-not $sfText.Contains('audit item 23')) { $skillNoReason += $sf }
    }
    ST-Check 'lint: both skill loader scripts exist, carry StrictMode plus an explicit error preference, and state why Continue is deliberate' (
      (@($skillNoGuard).Count -eq 0) -and (@($skillNoReason).Count -eq 0))
    foreach ($sgb in (@($skillNoGuard) + @($skillNoReason))) { Write-Output "      skill guard: $sgb" }
  } else {
    ST-Skip 'lint: both skill loader scripts exist, carry StrictMode plus an explicit error preference, and state why Continue is deliberate' 'skill loader scripts not both present (installed copy) - the installer lives in the repository, never beside the stitched artifact'
  }

  # ---------- TB-5: the uninstaller's recursive delete is gated and bounded ----------
  # This is the only rm-rf-shaped operation shipped in the repository, and it deletes a CHILD of a
  # directory the operator names, so two properties have to survive edits: the delete sits behind
  # exactly one ShouldProcess gate whose inner cmdlet is explicitly told not to ask again, and the
  # dangerous-target refusal is in the file at all. The -Confirm:$false is load-bearing, not
  # cosmetic - measured on this machine, when -Confirm propagates into Remove-Item the recursive
  # delete throws NullReferenceException on BOTH Windows PowerShell 5.1 and PowerShell 7.6.7.
  $unRel = 'skill\agent-computer-use\uninstall.ps1'
  $unPath = Join-Path $script:ToolRootPath $unRel
  if (Test-Path -LiteralPath $unPath) {
    $unText = [System.IO.File]::ReadAllText($unPath, [System.Text.Encoding]::UTF8)
    # 'SupportsShouldProcess' alone is a weak needle: the header prose says the word too. The
    # bracketed attribute prefix appears exactly once, in [CmdletBinding(...)], so that is what
    # the predicate asks for, and the refusal needles are the reason strings the script emits.
    $unNeedles = @(
      '[CmdletBinding(SupportsShouldProcess',
      '$PSCmdlet.ShouldProcess(',
      'Remove-Item -LiteralPath $skillFull -Recurse -Force -Confirm:$false',
      'Test-ReparsePoint',
      'holds .git (a repository or worktree)',
      'holds desktop.ps1 (this tool owns that tree)',
      'source directory with .ps1 files',
      'is a volume root',
      'exit 5')
    $unLack = @($unNeedles | Where-Object { -not $unText.Contains($_) })
    $unGates = @([regex]::Matches($unText, '\$PSCmdlet\.ShouldProcess\(')).Count
    ST-Check 'lint (TB-5): the uninstaller gates its recursive delete behind one ShouldProcess call, keeps -Confirm off the inner cmdlet and refuses repository-shaped and reparse targets' (
      (@($unLack).Count -eq 0) -and ($unGates -eq 1))
    foreach ($ul in $unLack) { Write-Output "      TB-5 uninstall guard lacks: $ul" }
    Write-Output ("      TB-5 uninstall ShouldProcess call count: " + $unGates)
    # Teeth: rub the guards out of an in-memory copy and run the SAME predicate over it. A copy
    # with the attribute and the inner -Confirm:$false removed must come back flagged, or the
    # check above would stay green on a file that no longer has either.
    $unMutated = $unText.Replace('[CmdletBinding(SupportsShouldProcess', '[CmdletBinding(Process').Replace(' -Confirm:$false', '')
    $unMutLack = @($unNeedles | Where-Object { -not $unMutated.Contains($_) })
    ST-Check 'lint (TB-5): the uninstaller guard predicate flags the planted guard-free copy (teeth, not decoration)' (
      (@($unLack).Count -eq 0) -and (@($unMutLack).Count -ge 2) -and ($unMutLack.Contains('[CmdletBinding(SupportsShouldProcess')))
    Write-Output ("      TB-5 planted-copy flagged: " + (@($unMutLack).Count) + " needle(s)")
  } else {
    ST-Skip 'lint (TB-5): the uninstaller gates its recursive delete behind one ShouldProcess call, keeps -Confirm off the inner cmdlet and refuses repository-shaped and reparse targets' 'no uninstaller in this tree - the loader scripts ship with the repository, never beside the stitched artifact'
    ST-Skip 'lint (TB-5): the uninstaller guard predicate flags the planted guard-free copy (teeth, not decoration)' 'no uninstaller in this tree - the loader scripts ship with the repository, never beside the stitched artifact'
  }

  # ---------- TB-4: the outward docs must not teach a send into a real conversation ----------
  # A doc example that names a messaging window is an instruction an agent will follow against a
  # human on the other side. The guard family proves WHICH window took the keys; it never proves the
  # send was authorized, so the docs are the control here and both sides have to hold: the banned
  # example shape is gone from each carrier AND the red line is actually present in each - an
  # example-only edit would let the next round put the target back. The docs resolve either at the
  # repository path or, in an installed tree, above scripts\, so this reads the installed face
  # instead of substituting the source file for it.
  $tb4Banned = @('MyChat', 'into a chat window', 'for chat windows')
  $tb4Needles = @('paste-file --to "Notepad"', 'dtx-fixture.txt', 'hard red line')
  $tb4Docs = @('SKILL.md', 'reference.md')
  $tb4Texts = @{}
  $tb4Missing = @()
  $tb4Where = @()
  foreach ($tb4Name in $tb4Docs) {
    $tb4Cand = @(
      (Join-Path $script:ToolRootPath (Join-Path (Join-Path 'skill' 'agent-computer-use') $tb4Name)),
      (Join-Path (Split-Path -Parent $script:ToolRootPath) $tb4Name),
      (Join-Path $script:ToolRootPath $tb4Name))
    $tb4Hit = @($tb4Cand | Where-Object { Test-Path -LiteralPath $_ })
    if (@($tb4Hit).Count -eq 0) { $tb4Missing += $tb4Name }
    else {
      $tb4Where += ($tb4Name + '=' + $tb4Hit[0])
      $tb4Texts[$tb4Name] = [System.IO.File]::ReadAllText($tb4Hit[0], [System.Text.Encoding]::UTF8)
    }
  }
  if (@($tb4Missing).Count -eq 0) {
    $tb4Bad = @()
    foreach ($tb4Name in $tb4Docs) {
      $tb4T = [string]$tb4Texts[$tb4Name]
      # fail closed: an emptied needle list or a truncated read would both look like "nothing to flag"
      if ((@($tb4Needles).Count -lt 3) -or (@($tb4Banned).Count -lt 3)) { $tb4Bad += ($tb4Name + ': the guard lost its own needle list') }
      if ($tb4T.Length -lt 200) { $tb4Bad += ($tb4Name + ': read back only ' + $tb4T.Length + ' chars, too small to judge') }
      foreach ($tb4N in $tb4Needles) { if (-not $tb4T.Contains($tb4N)) { $tb4Bad += ($tb4Name + ' lacks: ' + $tb4N) } }
      foreach ($tb4X in $tb4Banned) { if ($tb4T.Contains($tb4X)) { $tb4Bad += ($tb4Name + ' still teaches the chat target: ' + $tb4X) } }
    }
    ST-Check 'lint (TB-4): both outward docs carry the messaging red line with a fixture-only send example and no chat-window target (read from whichever face this tree is)' (
      (@($tb4Bad).Count -eq 0))
    foreach ($tb4B in $tb4Bad) { Write-Output ("      TB-4 doc face: " + $tb4B) }
    Write-Output ("      TB-4 doc paths read: " + ($tb4Where -join ' | '))
    # Teeth: rebuild the pre-fix shape in memory - target back, red line out, fixture name out - and
    # run the SAME needles over it. If that copy is not flagged, the check above is a needle count.
    $tb4Mut = ([string]$tb4Texts['SKILL.md']).Replace('paste-file --to "Notepad"', 'paste-file --to "MyChat"').Replace('hard red line', 'note').Replace('dtx-fixture.txt', 'report.pdf')
    $tb4MutBad = @()
    foreach ($tb4X in $tb4Banned) { if ($tb4Mut.Contains($tb4X)) { $tb4MutBad += ('restored: ' + $tb4X) } }
    foreach ($tb4N in $tb4Needles) { if (-not $tb4Mut.Contains($tb4N)) { $tb4MutBad += ('lost: ' + $tb4N) } }
    ST-Check 'lint (TB-4): the doc-face predicate flags the planted copy that restores the chat target and drops the red line (teeth, not decoration)' (
      (@($tb4Bad).Count -eq 0) -and (@($tb4MutBad).Count -ge 1) -and ($tb4Mut.Contains('MyChat')) -and (-not $tb4Mut.Contains('hard red line')))
    Write-Output ("      TB-4 planted-copy flags: " + (@($tb4MutBad).Count) + " (" + ($tb4MutBad -join '; ') + ")")
  } else {
    ST-Skip 'lint (TB-4): both outward docs carry the messaging red line with a fixture-only send example and no chat-window target (read from whichever face this tree is)' ('outward doc(s) not resolvable here (missing: ' + (@($tb4Missing) -join ', ') + ') - nothing to read the red line off')
    ST-Skip 'lint (TB-4): the doc-face predicate flags the planted copy that restores the chat target and drops the red line (teeth, not decoration)' ('outward doc(s) not resolvable here (missing: ' + (@($tb4Missing) -join ', ') + ') - nothing to plant the mutant into')
  }

  # ---------- TB-6: the newcomer document the entry doc links at ships beside it ----------
  # SKILL.md pointed its quick-start link two levels ABOVE the package directory. That resolves inside a
  # repository clone and dangles in the installed layout - and the installed layout is the only place an
  # agent that loaded this skill ever reads the entry document. TB-6 makes the link a sibling and ships
  # the guide inside the package. The guide is also a THIRD carrier of the TB-4 disease: it taught a file
  # send aimed at a chat window, so delivering it into every install would have put that instruction in
  # front of every loader. Both halves are read from the face the run is on: the entry document and the
  # guide beside it are measured wherever they resolve (installed face included), while the carrier/root
  # byte identity and the installer behaviour only exist in a repository tree - an installed copy has
  # neither the root document nor install.ps1, and says so instead of silently passing.
  # Every CJK needle here is assembled from code points, like the quick-start name above: this file must
  # stay pure ASCII past its BOM, and a literal in the file would also be a hit in its own scan.
  $tb6Qs = [string]::Join('', @([char]0x5FEB, [char]0x901F, [char]0x4E0A, [char]0x624B, [char]0x6307, [char]0x5357)) + '.md'
  $tb6Ben = [string]::Join('', @([char]0x8BB0, [char]0x4E8B, [char]0x672C))
  $tb6ChatWin = [string]::Join('', @([char]0x804A, [char]0x5929, [char]0x7A97, [char]0x53E3))
  $tb6SendTo = [string]::Join('', @([char]0x7ED9, [char]0x804A, [char]0x5929, [char]0x7A97, [char]0x53E3, [char]0x53D1, [char]0x9001))
  $tb6Fixture = 'paste-file --to "' + $tb6Ben + '" dtx-fixture.txt'
  $tb6RedNeedles = @('hard red line', 'dtx-fixture.txt', $tb6Fixture)
  $tb6Banned = @($tb6SendTo, 'MyChat', 'into a chat window', 'for chat windows')
  $tb6SkillCand = @(
    (Join-Path $script:ToolRootPath (Join-Path (Join-Path 'skill' 'agent-computer-use') 'SKILL.md')),
    (Join-Path (Split-Path -Parent $script:ToolRootPath) 'SKILL.md'),
    (Join-Path $script:ToolRootPath 'SKILL.md'))
  $tb6SkillHit = @($tb6SkillCand | Where-Object { Test-Path -LiteralPath $_ })
  if (@($tb6SkillHit).Count -gt 0) {
    $tb6SkillPath = [string]$tb6SkillHit[0]
    $tb6SkillText = [string]([System.IO.File]::ReadAllText($tb6SkillPath, [System.Text.Encoding]::UTF8))
    $tb6QsPath = Join-Path (Split-Path -Parent $tb6SkillPath) $tb6Qs
    $tb6QsText = ''
    $tb6Bad = @()
    if ($tb6SkillText.Length -lt 200) { $tb6Bad += ('entry doc read back only ' + $tb6SkillText.Length + ' chars, too small to judge') }
    if (-not $tb6SkillText.Contains('](' + $tb6Qs + ')')) { $tb6Bad += 'entry doc carries no sibling link to the quick-start guide' }
    if ($tb6SkillText.Contains('../' + $tb6Qs)) { $tb6Bad += 'entry doc still links above the package directory' }
    if (-not (Test-Path -LiteralPath $tb6QsPath -PathType Leaf)) {
      $tb6Bad += ('no quick-start guide beside the entry doc: ' + $tb6Qs)
    } else {
      $tb6QsText = [string]([System.IO.File]::ReadAllText($tb6QsPath, [System.Text.Encoding]::UTF8))
      if ($tb6QsText.Length -lt 200) { $tb6Bad += ('guide read back only ' + $tb6QsText.Length + ' chars, too small to judge') }
      foreach ($tb6N in $tb6RedNeedles) { if (-not $tb6QsText.Contains($tb6N)) { $tb6Bad += ('guide lacks: ' + $tb6N) } }
      foreach ($tb6X in $tb6Banned) { if ($tb6QsText.Contains($tb6X)) { $tb6Bad += ('guide still teaches: ' + $tb6X) } }
    }
    ST-Check 'lint (TB-6): the entry document links the quick-start guide as a sibling, that guide is present beside it and carries the messaging red line with a fixture-only file-send example and no chat-window send teaching (read from whichever face this tree is)' (
      (@($tb6Bad).Count -eq 0) -and (@($tb6RedNeedles).Count -eq 3) -and (@($tb6Banned).Count -eq 4))
    foreach ($tb6B in @($tb6Bad)) { Write-Output ('      TB-6 delivery face: ' + [string]$tb6B) }
    Write-Output ('      TB-6 entry doc: ' + $tb6SkillPath + ' | guide: ' + $tb6QsPath + ' | guide chars: ' + $tb6QsText.Length)
    # Teeth: plant the pre-fix shape three ways and run the SAME arms over each copy - the escaped link
    # back into the entry doc, the red line out of the guide, the chat-window send line back into the
    # guide. Each plant carries its own positive control, so an arm that can only ever answer 'clean'
    # is named rather than flattered. Nothing is written to disk here.
    $tb6MutSkill = $tb6SkillText.Replace('](' + $tb6Qs + ')', ('](../../' + $tb6Qs + ')'))
    $tb6MutNoRed = $tb6QsText.Replace('hard red line', 'note')
    $tb6MutBanned = ($tb6QsText + '- ' + $tb6SendTo + ' report.pdf')
    $tb6Planted = @(
      [pscustomobject]@{ Name = 'escaped-link'; Text = $tb6MutSkill; Arm = 'link'; Took = ($tb6MutSkill.Contains('../' + $tb6Qs) -and (-not $tb6MutSkill.Contains('](' + $tb6Qs + ')'))) },
      [pscustomobject]@{ Name = 'red-line-removed'; Text = $tb6MutNoRed; Arm = 'needle'; Took = (-not $tb6MutNoRed.Contains('hard red line')) },
      [pscustomobject]@{ Name = 'chat-send-restored'; Text = $tb6MutBanned; Arm = 'banned'; Took = $tb6MutBanned.Contains($tb6SendTo) })
    $tb6PlantBad = @()
    foreach ($tb6P in @($tb6Planted)) {
      if (-not [bool]$tb6P.Took) { $tb6PlantBad += ('plant did not take: ' + [string]$tb6P.Name) }
      $tb6PFlagged = $false
      if (([string]$tb6P.Arm) -ceq 'link') {
        if ($tb6P.Text.Contains('../' + $tb6Qs)) { $tb6PFlagged = $true }
      } elseif (([string]$tb6P.Arm) -ceq 'needle') {
        foreach ($tb6N in $tb6RedNeedles) { if (-not $tb6P.Text.Contains($tb6N)) { $tb6PFlagged = $true } }
      } else {
        foreach ($tb6X in $tb6Banned) { if ($tb6P.Text.Contains($tb6X)) { $tb6PFlagged = $true } }
      }
      if (-not $tb6PFlagged) { $tb6PlantBad += ('planted copy NOT flagged: ' + [string]$tb6P.Name) }
    }
    ST-Check 'lint (TB-6): the delivery predicate flags each planted copy - the entry doc with the link escaped above the package, the guide with the red line removed and the guide with the chat-window send line restored (teeth, not decoration)' (
      (@($tb6PlantBad).Count -eq 0) -and (@($tb6Planted).Count -eq 3) -and (@($tb6Bad).Count -eq 0))
    foreach ($tb6Pb in @($tb6PlantBad)) { Write-Output ('      TB-6 teeth: ' + [string]$tb6Pb) }
    Write-Output ('      TB-6 planted copies: ' + (@($tb6Planted | ForEach-Object { [string]$_.Name }) -join ','))
  } else {
    ST-Skip 'lint (TB-6): the entry document links the quick-start guide as a sibling, that guide is present beside it and carries the messaging red line with a fixture-only file-send example and no chat-window send teaching (read from whichever face this tree is)' 'no entry document resolvable here - nothing to read the newcomer link off'
    ST-Skip 'lint (TB-6): the delivery predicate flags each planted copy - the entry doc with the link escaped above the package, the guide with the red line removed and the guide with the chat-window send line restored (teeth, not decoration)' 'no entry document resolvable here - nothing to plant into'
  }

  # ---------- TB-6 (repository face): two copies, one byte face, and an installer that refuses ----------
  # The package carries a COPY of the repository-root guide because the installed layout has no root to
  # link into. A copy without a reconciliation drifts silently, so the two are pinned by SHA256 over the
  # raw bytes, and the installer is pinned on both shapes it has to keep: it resolves the guide from the
  # package directory (not from the repository root, which is absent by then) and it REFUSES the install
  # when the carrier is missing instead of shipping a package whose entry document links at nothing.
  $tb6PkgDir = Join-Path $script:ToolRootPath (Join-Path 'skill' 'agent-computer-use')
  $tb6RootQs = Join-Path $script:ToolRootPath $tb6Qs
  $tb6PkgQs = Join-Path $tb6PkgDir $tb6Qs
  $tb6InstPath = Join-Path $tb6PkgDir 'install.ps1'
  if ((Test-Path -LiteralPath $tb6RootQs -PathType Leaf) -and (Test-Path -LiteralPath $tb6PkgQs -PathType Leaf) -and (Test-Path -LiteralPath $tb6InstPath -PathType Leaf)) {
    $tb6RootB = [System.IO.File]::ReadAllBytes($tb6RootQs)
    $tb6PkgB = [System.IO.File]::ReadAllBytes($tb6PkgQs)
    $tb6ShaRoot = [System.BitConverter]::ToString(([System.Security.Cryptography.SHA256]::Create()).ComputeHash([byte[]]$tb6RootB)).Replace('-', '')
    $tb6ShaPkg = [System.BitConverter]::ToString(([System.Security.Cryptography.SHA256]::Create()).ComputeHash([byte[]]$tb6PkgB)).Replace('-', '')
    $tb6InstText = [string]([System.IO.File]::ReadAllText($tb6InstPath, [System.Text.Encoding]::UTF8))
    $tb6InstNeedles = @('$srcQuickStart = Join-Path $PSScriptRoot', 'if (-not (Test-Path -LiteralPath $srcQuickStart -PathType Leaf)) { $missing += $srcQuickStart }', 'Copy-Item -LiteralPath $srcQuickStart', 'exit 3')
    $tb6Bad2 = @()
    if (@($tb6InstNeedles).Count -ne 4) { $tb6Bad2 += ('the installer needle list lost its own shape: ' + @($tb6InstNeedles).Count) }
    if ($tb6RootB.Length -lt 2000) { $tb6Bad2 += ('repository-root guide is only ' + $tb6RootB.Length + ' bytes') }
    if ($tb6RootB.Length -ne $tb6PkgB.Length) { $tb6Bad2 += ('carrier is ' + $tb6PkgB.Length + ' bytes, root guide is ' + $tb6RootB.Length) }
    if ($tb6ShaRoot -cne $tb6ShaPkg) { $tb6Bad2 += ('carrier differs from the repository-root guide: root=' + $tb6ShaRoot + ' carrier=' + $tb6ShaPkg) }
    foreach ($tb6IN in $tb6InstNeedles) { if (-not $tb6InstText.Contains([string]$tb6IN)) { $tb6Bad2 += ('installer lacks: ' + [string]$tb6IN) } }
    # Presence is not POSITION. The shape that was actually wrong carried both the refusal and the copy
    # in the same file - just after the first write, so a package with no carrier still landed an entry
    # document whose newcomer link dangles. The order is measured off the same text, and a -1 is
    # refused, so a missing needle cannot win the comparison by sorting before everything.
    $tb6RefusalAt = $tb6InstText.IndexOf('$missing += $srcQuickStart')
    $tb6FirstWriteAt = $tb6InstText.IndexOf('New-Item -ItemType Directory -Path $scriptsDir')
    $tb6OrderOk = (($tb6RefusalAt -ge 0) -and ($tb6FirstWriteAt -ge 0) -and ($tb6RefusalAt -lt $tb6FirstWriteAt))
    if (-not $tb6OrderOk) { $tb6Bad2 += ('the carrier is not refused before the first write: refusal at ' + $tb6RefusalAt + ', first write at ' + $tb6FirstWriteAt) }
    ST-Check 'lint (TB-6): the quick-start guide ships inside the skill package as a byte-for-byte copy of the repository-root document, and the installer resolves it from the package, refuses the install when it is absent (before its first write) and copies it beside the entry doc' (
      (@($tb6Bad2).Count -eq 0))
    foreach ($tb6B2 in @($tb6Bad2)) { Write-Output ('      TB-6 delivery: ' + [string]$tb6B2) }
    Write-Output ('      TB-6 copies sha256: root=' + $tb6ShaRoot + ' carrier=' + $tb6ShaPkg + ' bytes=' + $tb6RootB.Length + '/' + $tb6PkgB.Length)
    Write-Output ('      TB-6 installer order: refusal char ' + $tb6RefusalAt + ' < first write char ' + $tb6FirstWriteAt)
    # Teeth, both arms: rub the refusal and the copy step out of an in-memory installer and re-run the
    # SAME needles - they must come back missing AND the refusal-before-write test must stop holding.
    # Then flip ONE byte at the end of the carrier and re-hash - the identity comparison must be able
    # to say 'different', or the check above is a length test wearing a hash costume.
    $tb6MutInst = $tb6InstText.Replace('if (-not (Test-Path -LiteralPath $srcQuickStart -PathType Leaf)) { $missing += $srcQuickStart }', 'if ($false) {').Replace('Copy-Item -LiteralPath $srcQuickStart', 'Set-Content -Value 1')
    $tb6MutLack = @($tb6InstNeedles | Where-Object { -not $tb6MutInst.Contains([string]$_) })
    $tb6MutRefusalAt = $tb6MutInst.IndexOf('$missing += $srcQuickStart')
    $tb6MutOrderOk = (($tb6MutRefusalAt -ge 0) -and ($tb6MutRefusalAt -lt $tb6MutInst.IndexOf('New-Item -ItemType Directory -Path $scriptsDir')))
    $tb6PlantB = [byte[]]$tb6PkgB.Clone()
    $tb6PlantB[($tb6PlantB.Length - 1)] = [byte]((([int]$tb6PlantB[($tb6PlantB.Length - 1)]) + 1) -band 255)
    $tb6ShaPlant = [System.BitConverter]::ToString(([System.Security.Cryptography.SHA256]::Create()).ComputeHash([byte[]]$tb6PlantB)).Replace('-', '')
    ST-Check 'lint (TB-6): the delivery predicate flags the planted installer copy that drops both the refusal and the copy step, loses the refusal-before-first-write order, and the one-byte carrier mutation changes the hash (teeth, not decoration)' (
      (@($tb6MutLack).Count -ge 2) -and (-not $tb6MutOrderOk) -and ($tb6ShaPlant -cne $tb6ShaPkg) -and ($tb6ShaRoot -ceq $tb6ShaPkg) -and ($tb6PlantB.Length -eq $tb6PkgB.Length))
    Write-Output ('      TB-6 planted installer flags: ' + (@($tb6MutLack).Count) + ' | refusal-before-write on the plant: ' + $tb6MutOrderOk + ' | planted carrier sha: ' + $tb6ShaPlant)
  } else {
    ST-Skip 'lint (TB-6): the quick-start guide ships inside the skill package as a byte-for-byte copy of the repository-root document, and the installer resolves it from the package, refuses the install when it is absent (before its first write) and copies it beside the entry doc' 'no skill package / installer in this tree - the loader scripts and the root document ship with the repository, never beside the stitched artifact'
    ST-Skip 'lint (TB-6): the delivery predicate flags the planted installer copy that drops both the refusal and the copy step, loses the refusal-before-first-write order, and the one-byte carrier mutation changes the hash (teeth, not decoration)' 'no skill package / installer in this tree - nothing to plant into'
  }

}

# lib/selftest-popup-occlusion.ps1 - one family of the selftest section, lifted out of
# lib/selftest.ps1 by A-14l (A-beta). Bodies are byte-identical to what the section carried; the only
# channel to the orchestrator is the explicit context object, and since this card that channel runs
# both ways - shared state arrives through $Ctx and what a lifted body still produces leaves through
# the declared export list, because a value that stays in a function scope reaches the next body as
# whatever the orchestration happened to hold under that name.
#
# The popup/occlusion family: the same-process popup delta, the no---to baseline that has to match
# --to, the occlusion self-proof, dialog-cancel made mechanical, the red-1/red-2 front gate over the
# weak receipt chain, the script popup survival guard, and the popup delta merge.
function Invoke-SelftestFamily-PopupOcclusion($Ctx) {
  # context handover (the one thing in this file above the lifted text that is not lifted text)
  $codeLines = $Ctx['codeLines']
  $j5ProdStart = $Ctx['j5ProdStart']
  $j5ProdEnd = $Ctx['j5ProdEnd']

  # ---------- unit: v1.5.3 R-06 same-process popup delta ----------
  # The RULE is pure (which handles count as newly on top), the enumeration is
  # not - so the two are tested apart. Synthetic windows only here.
  $wA = [pscustomobject]@{ Handle = [IntPtr]100; Class = 'Win'; Title = 'A'; Transparent = $false }
  $wB = [pscustomobject]@{ Handle = [IntPtr]200; Class = '#32768'; Title = ''; Transparent = $false }
  $wT = [pscustomobject]@{ Handle = [IntPtr]300; Class = 'tooltips_class32'; Title = ''; Transparent = $true }
  $dSame = Compare-PopupDelta @($wA) @($wA)
  ST-Check 'unit: popup delta - nothing new on top means no warning' ($dSame.HasNew -eq $false -and @($dSame.New).Count -eq 0)
  $dNew = Compare-PopupDelta @($wA) @($wA, $wB)
  ST-Check 'unit: popup delta - a menu-shaped window that appeared on top is reported' (
    $dNew.HasNew -eq $true -and @($dNew.New)[0].Class -eq '#32768')
  $dTip = Compare-PopupDelta @($wA) @($wA, $wT)
  ST-Check 'unit: popup delta - a click-through tooltip never triggers (no noise on every type)' (
    $dTip.HasNew -eq $false -and @($dTip.New).Count -eq 0)
  $dPre = Compare-PopupDelta @($wA, $wB) @($wA, $wB)
  ST-Check 'unit: popup delta - a tool window that was already there is not a new event' ($dPre.HasNew -eq $false)
  # ---------- v3.1.0 (P-02): the no---to send path must take the SAME popup baseline as --to ----------
  # Second review batch, item 5. The contract comment above promises "a tool window or palette
  # that was already floating there does not fire on every single send", but the baseline had
  # exactly ONE producer - the --to path. Resolve-Target returned early for no --to without the
  # property, Test-PostSendForeground fell back to an EMPTY baseline, and every pre-existing
  # same-process window on top read as "appeared ON TOP after the guard passed": WARN + exit 1
  # on a send that worked, while the identical scene with --to stayed green. One reality, two
  # exit codes, and the message was factually false about when the window appeared.
  $p02RealAbove = ${function:Get-SamePidWindowsAbove}
  try {
    $script:p02Calls = 0
    ${function:Get-SamePidWindowsAbove} = { param($t) $script:p02Calls++; return @([pscustomobject]@{ Handle = [IntPtr]7; Class = 'p02-palette'; Title = 'p02' }) }
    $p02Tgt = Resolve-Target ''
    ST-Check 'unit (P-02): the no---to path carries the same PreSendAbove baseline as --to, so a palette that was already there cannot read as a new event' (
      ($script:p02Calls -eq 1) -and ($null -ne $p02Tgt) -and (@($p02Tgt.PSObject.Properties['PreSendAbove']).Count -eq 1) -and (@($p02Tgt.PreSendAbove).Count -eq 1) -and (@($p02Tgt.PreSendAbove)[0].Class -eq 'p02-palette'))
    Write-Output ("      P-02 baseline: producer-calls=$($script:p02Calls) items=" + @($p02Tgt.PreSendAbove).Count)
  } finally {
    ${function:Get-SamePidWindowsAbove} = $p02RealAbove
  }
  # v3.1.0 (P-05 sub-item): the guard's OWN failure used to be an empty catch - "did not run"
  # and "passed" were the same observable. Fail-open stays the right call, silence does not:
  # NOTICE* is the prefix the four send consumers print WITHOUT exiting 1.
  $p05RealAbove = ${function:Get-SamePidWindowsAbove}
  try {
    ${function:Get-SamePidWindowsAbove} = { param($t) throw 'p05-sampler-broke' }
    $p05Tgt = [pscustomobject]@{ Pid = 1; Handle = [IntPtr]0; Title = 'p05' }
    $p05Msg = Test-PostSendForeground $p05Tgt $false
    ST-Check 'unit (P-05): a broken post-send guard returns a NOTICE naming the failure and keeps the exit code, never the empty string' (
      ("$p05Msg" -like 'NOTICE*') -and ("$p05Msg" -like '*p05-sampler-broke*') -and ("$p05Msg" -like '*was NOT re-verified*'))
    Write-Output ('      P-05 self-report: [' + $p05Msg + ']')
  } finally {
    ${function:Get-SamePidWindowsAbove} = $p05RealAbove
  }
  # ---------- unit: v1.5.1 occlusion self-proof ----------
  $og = Get-OcclusionPoints 100 100 100 100 5
  $ogInset = $true
  foreach ($p in @($og.Points)) {
    if ($p.X -lt 102 -or $p.X -gt 198 -or $p.Y -lt 102 -or $p.Y -gt 198) { $ogInset = $false }
  }
  $ogDistinct = @($og.Points | ForEach-Object { "$($_.X),$($_.Y)" } | Sort-Object -Unique).Count
  ST-Check 'unit: occlusion grid - 5x5 = 25 points, all 2px inside the edges, distinct' (
    $og.N -eq 25 -and @($og.Points).Count -eq 25 -and $ogInset -and $ogDistinct -eq 25)
  $ogTiny = Get-OcclusionPoints 0 0 3 3 5
  ST-Check 'unit: occlusion grid - tiny region degrades to one centre point' (
    $ogTiny.N -eq 1 -and $ogTiny.Points[0].X -eq 1 -and $ogTiny.Points[0].Y -eq 1)
  $ogZero = Get-OcclusionPoints 0 0 0 5 5
  ST-Check 'unit: occlusion grid - zero size yields no points (no crash)' ($ogZero.N -eq 0)

  $vsO = [System.Windows.Forms.SystemInformation]::VirtualScreen
  $pgO = Get-OcclusionPoints ($vsO.X - 6) ($vsO.Y + 10) 30 30 5
  $expSkipO = 0
  foreach ($p in @($pgO.Points)) {
    if ($p.X -lt $vsO.X -or $p.X -ge ($vsO.X + $vsO.Width) -or $p.Y -lt $vsO.Y -or $p.Y -ge ($vsO.Y + $vsO.Height)) { $expSkipO++ }
  }
  $vO = Get-OcclusionVerdict ($vsO.X - 6) ($vsO.Y + 10) 30 30 ([IntPtr]0x0BADC0DE) 5
  ST-Check 'unit: occlusion - offscreen points go to Skipped, never Mismatch' (
    $expSkipO -gt 0 -and $vO.Skipped -eq $expSkipO -and $vO.Checked -eq (25 - $expSkipO) -and $vO.Mismatch -eq $vO.Checked)
  $vOff = Get-OcclusionVerdict ($vsO.X - 2000) ($vsO.Y + 10) 100 100 ([IntPtr]0x0BADC0DE) 5
  ST-Check 'unit: occlusion - all-offscreen is its own state (not a 0% pass)' (
    $vOff.Checked -eq 0 -and $vOff.Err -eq 'all-offscreen')
  $mO = Merge-OcclusionHits @(
    @{ Hwnd = [IntPtr]111; Pid = 42; Proc = 'aaa'; Title = 't1' },
    @{ Hwnd = [IntPtr]111; Pid = 42; Proc = 'aaa'; Title = 't1' },
    @{ Hwnd = [IntPtr]111; Pid = 42; Proc = 'aaa'; Title = 't1' },
    @{ Hwnd = [IntPtr]222; Pid = 43; Proc = 'bbb'; Title = 't2' })
  ST-Check 'unit: occlusion - Covering dedupes by root handle (count aggregated)' (
    @($mO.Covering).Count -eq 2 -and $mO.Covering[0].Count -eq 3 -and $mO.Covering[0].Pid -eq 42 -and $mO.Covering[1].Count -eq 1)
  $rmA = Resolve-OcclusionMode '' $false $false
  $rmB = Resolve-OcclusionMode '' $false $true
  $rmC = Resolve-OcclusionMode '' $true $true
  $rmD = Resolve-OcclusionMode 'off' $true $true
  $rmE = Resolve-OcclusionMode 'strict' $false $false
  ST-Check 'unit: occlusion mode - read=warn / strict default / allow downgrades / off bypasses / strict upgrades' (
    $rmA.Action -eq 'warn' -and $rmB.Action -eq 'strict' -and $rmC.Action -eq 'warn' -and $rmD.Action -eq 'off' -and $rmE.Action -eq 'strict')
  $rmBad = $true
  try { $null = Resolve-OcclusionMode 'nope' $false $false } catch { $rmBad = $false }
  ST-Check 'unit: occlusion mode rejects a bogus value' (-not $rmBad)
  $sfO = Split-OcclusionFlags @('a', '--occlude', 'warn', 'b', '--allow-occluded', '--occlude-grid', '7')
  ST-Check 'unit: Split-OcclusionFlags strips+parses' (
    @($sfO.Words).Count -eq 2 -and $sfO.Words[0] -eq 'a' -and $sfO.Words[1] -eq 'b' -and $sfO.Occlude -eq 'warn' -and $sfO.OcclGrid -eq 7 -and $sfO.AllowOccluded)

  $toks = Split-LogArgs "click 100 200 --to 'Some Window'"
  # v3.0.1 (audit #14): this used to read `$toks.Count -eq 4 -and $toks[3] -eq '--to' -or
  # ($toks -contains 'Some Window')`. Two faults in one line: -and binds tighter than -or,
  # so the whole front half could be discarded by the tail; and the input actually yields
  # FIVE tokens (click / 100 / 200 / --to / 'Some Window'), making `Count -eq 4 -and
  # $toks[3] -eq '--to'` structurally false - the assertion passed only on its weak tail,
  # i.e. it never checked the flag position at all. Positions are now pinned, because the
  # replay path reads exactly those indices back out.
  ST-Check 'unit: Split-LogArgs keeps the quoted arg whole AND the flag in its own slot (five tokens, --to at index 3)' (
    (@($toks).Count -eq 5) -and ($toks[3] -ceq '--to') -and ($toks[4] -ceq 'Some Window') -and
    ($toks[0] -ceq 'click') -and ($toks[1] -ceq '100') -and ($toks[2] -ceq '200'))
  # and the precedence trap itself, pinned: an -or tail must not be able to rescue a false
  # front half, so the same expression is asserted with a deliberately wrong index.
  $toksPrecedenceTrap = (@($toks).Count -eq 4 -and $toks[3] -ceq 'nope' -or ($toks -contains 'Some Window'))
  ST-Check 'unit: the old -and/-or shape is recorded as unsound (a wrong front half still ORs to true, which is why the assertion above lists every slot)' (
    $toksPrecedenceTrap -eq $true)

  $px = Get-PixelHex 5 5
  ST-Check 'unit: Get-PixelHex returns #RRGGBB' ($px -match '^#[0-9A-F]{6}$')
  $hh = Get-RegionHash 0 0 8 8
  ST-Check 'unit: Get-RegionHash returns md5 hex' ($hh -match '^[0-9a-f]{32}$')
  $sn = Default-ShotName 'rect'
  ST-Check 'unit: Default-ShotName is timestamped .png' ($sn -match 'rect_\d{8}T\d{9}\.png$')

  # ---------- v3.0.0 B-5: dialog-cancel (the operating rule, made mechanical) ----------
  # Name matching is pure, so the dangerous shapes are pinned here rather than in a live run:
  # a stem hit must not fire on a WORD THATmerely starts with the stem, and the two words that
  # would confirm something must never match.
  $cnQu = [string][char]0x53D6 + [string][char]0x6D88
  $cnTrue = @(
    (Test-DialogCancelName 'Cancel'), (Test-DialogCancelName '  CANCEL  '),
    (Test-DialogCancelName 'Cancel(C)'), (Test-DialogCancelName 'cancel(&C)'),
    (Test-DialogCancelName ($cnQu + '(&C)')), (Test-DialogCancelName $cnQu))
  $cnFalse = @(
    (Test-DialogCancelName 'OK'), (Test-DialogCancelName 'Yes'), (Test-DialogCancelName 'Close'),
    (Test-DialogCancelName 'Retry'), (Test-DialogCancelName 'Cancel Order'),
    (Test-DialogCancelName 'CancelButtonStyle'), (Test-DialogCancelName ''),
    (Test-DialogCancelName ([string][char]0x786E + [string][char]0x5B9A)))
  ST-Check 'unit: dialog-cancel matches the cancel stem in case, spacing and accelerator forms' (
    (@($cnTrue | Where-Object { $_ -ne $true }).Count -eq 0))
  ST-Check 'unit: dialog-cancel refuses the confirming words and any name that only starts with the stem' (
    (@($cnFalse | Where-Object { $_ -ne $false }).Count -eq 0))
  Write-Output ("      dialog-cancel name matrix true=[" + (@($cnTrue | ForEach-Object { if ($_) { '1' } else { '0' } }) -join '') +
    "] false=[" + (@($cnFalse | ForEach-Object { if ($_) { '1' } else { '0' } }) -join '') + "]")
  # the closed set IS the safety property, so assert its exact content by CODE POINTS (an
  # early version used `-contains $cnQu`, which stayed red for a reason that turned out to be
  # the comparison, not the set - code points are the only form that says what is in there).
  $cnStems = @(Get-DialogCancelStems)
  $cnOther = @($cnStems | Where-Object { "$_" -ne 'cancel' })
  $cnOtherS = ''
  if (@($cnOther).Count -eq 1) { $cnOtherS = "$($cnOther[0])" }
  $cnChars = @($cnOtherS.ToCharArray())
  ST-Check 'unit: the cancel candidate set is exactly two stems - the EN word and the CN word for cancel, and nothing else' (
    @($cnStems).Count -eq 2 -and (@($cnStems) -contains 'cancel') -and
    @($cnOther).Count -eq 1 -and @($cnChars).Count -eq 2 -and
    [int][char]$cnChars[0] -eq 0x53D6 -and [int][char]$cnChars[1] -eq 0x6D88)
  Write-Output ("      cancel stems: count=" + @($cnStems).Count + ' nonAsciiLen=' + @($cnChars).Count)
  ST-Check 'unit: dialog shape test - #32* class or an owner window yes, an ordinary top-level no' (
    (Test-DialogWindow ([pscustomobject]@{ Class = '#32770'; Owner = [IntPtr]0 })) -and
    (Test-DialogWindow ([pscustomobject]@{ Class = 'Chrome_WidgetWin_1'; Owner = [IntPtr]42 })) -and
    -not (Test-DialogWindow ([pscustomobject]@{ Class = 'Chrome_WidgetWin_1'; Owner = [IntPtr]0 })) -and
    -not (Test-DialogWindow $null))
  # both wiring sites, counted OUTSIDE the selftest body (the marker strings are assembled
  # because a scan that contains its own pattern counts itself - this repo's oldest family).
  $dcCaseMark = "'dialog-cance" + "l' {"
  $dcKnownMark = '$' + "known = @('click'"
  $dcCase = @(); $dcKnown = @()
  for ($ci = 0; $ci -lt $codeLines.Count; $ci++) {
    if ($ci -ge $j5ProdStart -and $ci -lt $j5ProdEnd) { continue }
    if ($codeLines[$ci] -match '^\s*#') { continue }
    if ($codeLines[$ci].Contains($dcCaseMark)) { $dcCase += ($ci + 1) }
    if ($codeLines[$ci].Contains($dcKnownMark)) { $dcKnown += ($ci + 1) }
  }
  $dcStepMember = @($codeLines | Where-Object { $_.Contains("'dialog-cancel'") -and $_.Contains('win-close') })
  ST-Check 'lint: dialog-cancel is a real dispatch case AND a known script step (both wiring sites exist)' (
    @($dcCase).Count -eq 1 -and @($dcKnown).Count -ge 1 -and @($dcStepMember).Count -ge 1)

  # ---------- v2.3.0 red-1/red-2: the occlusion front gate over the weak receipt chain ----------
  # Real machine, 2026-10-02: two negative controls (paste into Program Manager, a target that
  # receives nothing) were both ACCEPTED on receipt=lines-changed because the legs sampled the
  # screen rect and the coverer supplied the motion (a playing video; then the foreground
  # switch itself). The gate closes the whole weak chain while the target rect is covered and
  # names the percentage it measured.
  $pvGateThr = [double](Get-PasteReceiptOcclusionMax)
  ST-Check 'unit: the shipped receipt occlusion gate is one specific spoken number (0) - any covered sample point closes the weak chain, and a default nobody reads could be set to never-gate' (
    $pvGateThr -eq 0)
  $pvGateAll = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 12774; UiaBefore = 14; UiaAfter = 99; HeightBefore = 240; HeightAfter = 900; LinesBefore = 5; LinesAfter = 3; HashBefore = 'aaaa1111'; HashAfter = 'bbbb2222'; OccludedAfter = 100.0; OcclusionMax = 0; CoveredBy = "pid=999 'X' (25 of 25 sample points)" }
  ST-Check 'unit: paste receipt - an occluded target refuses the WHOLE weak chain even when uia-nodes AND grow-height AND lines-changed all moved, and names the pct, the coverer and why (front gate; covered pixels cannot tell target from coverer)' (
    (-not $pvGateAll.Ok) -and ($pvGateAll.Criterion -ceq 'occluded-refused') -and
    $pvGateAll.Detail.Contains('occluded-refused=100%') -and $pvGateAll.Detail.Contains('coveredBy=pid=999') -and
    $pvGateAll.Detail.Contains('nodes 14->99') -and $pvGateAll.Detail.Contains('h 240->900') -and
    $pvGateAll.Detail.Contains('lines 5->3') -and $pvGateAll.Detail.Contains('cannot tell the target from its coverer'))
  $pvGateOne = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 12774; UiaBefore = 14; UiaAfter = 14; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 3; HashBefore = 'aaaa1111'; HashAfter = 'bbbb2222'; OccludedAfter = 4.0; OcclusionMax = 0; CoveredBy = "pid=998 'Y' (1 of 25 sample points)" }
  ST-Check 'unit: paste receipt - ONE covered sample point out of 25 (4%) already closes the gate (the read is 25-point sampled; a single covered point is already not the target own pixels)' (
    (-not $pvGateOne.Ok) -and ($pvGateOne.Criterion -ceq 'occluded-refused') -and $pvGateOne.Detail.Contains('occluded-refused=4%'))
  $pvOpen = Get-PasteReceiptVerdict @{ VerbatimOk = $false; Threshold = 200; HeightMin = 8; PayloadChars = 8556; UiaBefore = 14; UiaAfter = 15; HeightBefore = 240; HeightAfter = 240; LinesBefore = 5; LinesAfter = 5; HashBefore = 'aaaa1111'; HashAfter = 'aaaa1111'; OccludedAfter = 0.0; OcclusionMax = 0; CoveredBy = '' }
  ST-Check 'unit: paste receipt - a clean target (occluded=0) keeps the shipped legs exactly, uia-nodes first (the gate must not silently weaken the clean path)' (
    $pvOpen.Ok -and $pvOpen.Degraded -and ($pvOpen.Criterion -ceq 'uia-nodes'))
  # The wiring, in production code only (the scan skips the selftest body the same way the
  # autoexpect lints above do).
  $prDef = 0; $prBaseCall = 0; $prAnnounce = 0; $prFloorDef = 0; $prFreshRect = 0; $prBodyIn = $false; $prOccKnob = 0; $prOccRefuse = 0
  for ($awi = 0; $awi -lt $codeLines.Count; $awi++) {
    if ($awi -ge $j5ProdStart -and $awi -lt $j5ProdEnd) { continue }
    if ($codeLines[$awi] -match '^\s*#') { continue }
    if ($codeLines[$awi].StartsWith('function Get-PasteReceiptVerdict')) { $prDef++ }
    if ($codeLines[$awi].StartsWith('function Get-PasteFoldThreshold')) { $prFloorDef++ }
    if ($codeLines[$awi].StartsWith('function Get-PasteReceiptOcclusionMax')) { $prOccKnob++ }
    if ($codeLines[$awi].Contains(('occluded-' + 'refused='))) { $prOccRefuse++ }
    if ($codeLines[$awi].Contains(('Get-PasteReceipt' + 'Baseline $p $target'))) { $prBaseCall++ }
    if ($codeLines[$awi].Contains(('accepted on ' + 'receipt='))) { $prAnnounce++ }
    if ($codeLines[$awi].StartsWith('function Get-PasteReceipt(')) { $prBodyIn = $true; continue }
    if ($prBodyIn -and ($codeLines[$awi] -match '^function ')) { $prBodyIn = $false }
    if ($prBodyIn -and $codeLines[$awi].Contains(('$_.Handle -eq $' + 'target.Handle'))) { $prFreshRect++ }
  }
  ST-Check 'lint: the paste receipt verdict has exactly one pure producer and one fold-threshold producer (a second copy of the rule would drift silently)' (
    ($prDef -eq 1) -and ($prFloorDef -eq 1))
  # Deliberately ONE call site: paste-file's needle is the attached FILE NAME, which targets do
  # render, so the fold problem does not apply there and its semantics stay exactly as shipped.
  ST-Check 'lint: only the text-payload paste captures a receipt baseline (exactly 1 site; paste-file keeps its verbatim-only judgement because its needle is a file name it does render)' (
    $prBaseCall -eq 1)
  if ($prBaseCall -ne 1) { Write-Output "      receipt baseline call sites: $prBaseCall (expected 1)" }
  ST-Check 'lint: a degraded paste receipt is announced in words on the message that grants it (no silent second criterion)' (
    $prAnnounce -eq 1)
  # The first live round proved this one the hard way: with the cached rect the grow-height leg
  # reads the size the window had when the command started, so it is permanently flat.
  ST-Check 'lint: the receipt re-queries the window rect by handle instead of trusting the target snapshot (grow-height on a cached rect can never fire - live-v220-1 caught it at h 287->287 while wins saw 287->335)' (
    $prFreshRect -eq 1)
  ST-Check 'lint: the receipt occlusion gate has exactly one knob producer (a second copy of the rule would drift silently)' (
    $prOccKnob -eq 1)
  ST-Check 'lint: the occlusion refusal wording is spoken by exactly one production line - the front gate verdict itself (the echo contract and the log field both read it from there)' (
    $prOccRefuse -eq 1)


  # ---------- v1.9.0: script popup survival guard (J-02 C) ----------
  # Pure-rule units first: Test-PopupGuardAlive carries the survival VERDICT (Compare-
  # PopupDelta answers "what appeared"; the guard needs the complementary "is THIS
  # baseline popup still there", the granularity gap the task order told us to expect).
  $c36Base = @{ Hwnd = [IntPtr]4321; Pid = 777; Class = '#32768'; X = 620; Y = 300; W = 480; H = 320; OwnerHwnd = [IntPtr]4000; Above0 = @(); Tolerance = 3; MustBeFg = $false }
  $c36Above = @([pscustomobject]@{ Handle = [IntPtr]4321; Class = '#32768'; Title = 'x'; Transparent = $false })
  $c36Ok = Test-PopupGuardAlive $c36Base $true $c36Above @{ X = 620; Y = 300; W = 480; H = 320 } ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - alive popup still above its owner with zero drift survives' (
    $c36Ok.Alive -and ($c36Ok.Present -eq 'yes') -and ($c36Ok.Above -eq 'yes') -and ($c36Ok.Drift -eq 'dx=0 dy=0 dw=0 dh=0'))
  $c36Gone = Test-PopupGuardAlive $c36Base $false $c36Above $null ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - destroyed window reads popup GONE with present=no' (
    (-not $c36Gone.Alive) -and ($c36Gone.Present -eq 'no') -and $c36Gone.Reason.Contains('popup GONE'))
  $c36Buried = Test-PopupGuardAlive $c36Base $true @() @{ X = 620; Y = 300; W = 480; H = 320 } ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - an owned popup no longer above its owner fails the z-order leg' (
    (-not $c36Buried.Alive) -and ($c36Buried.Above -eq 'no') -and $c36Buried.Reason.Contains('no longer above its owner'))
  $c36Moved = Test-PopupGuardAlive $c36Base $true $c36Above @{ X = 620; Y = 290; W = 480; H = 320 } ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - rect drift beyond tolerance fails with measured deltas' (
    (-not $c36Moved.Alive) -and $c36Moved.Reason.Contains('rect drift dx=0 dy=10') -and $c36Moved.Reason.Contains('exceeds tolerance=3'))
  $c36Jitter = Test-PopupGuardAlive $c36Base $true $c36Above @{ X = 622; Y = 299; W = 481; H = 320 } ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - drift within tolerance survives' ($c36Jitter.Alive -and ($c36Jitter.Drift -eq 'dx=2 dy=1 dw=1 dh=0'))
  $c36FgBase = @{ Hwnd = [IntPtr]4321; Pid = 777; Class = 'x'; X = 0; Y = 0; W = 10; H = 10; OwnerHwnd = [IntPtr]4000; Above0 = @(); Tolerance = 3; MustBeFg = $true }
  $c36FgLost = Test-PopupGuardAlive $c36FgBase $true $c36Above @{ X = 0; Y = 0; W = 10; H = 10 } ([IntPtr]9999)
  $c36FgKept = Test-PopupGuardAlive $c36FgBase $true $c36Above @{ X = 0; Y = 0; W = 10; H = 10 } ([IntPtr]4321)
  ST-Check 'unit: popup guard verdict - must-be-foreground leg fires only when the foreground moved away' (
    (-not $c36FgLost.Alive) -and $c36FgLost.Reason.Contains('foreground is no longer the guarded popup') -and $c36FgKept.Alive)
  $c36Free = Test-PopupGuardAlive (@{ Hwnd = [IntPtr]4321; Pid = 777; Class = 'x'; X = 0; Y = 0; W = 10; H = 10; OwnerHwnd = [IntPtr]::Zero; Above0 = @(); Tolerance = 3; MustBeFg = $false }) $true @() @{ X = 0; Y = 0; W = 10; H = 10 } ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - an ownerless popup skips the z-order leg as n/a and survives on IsWindow+rect' (
    $c36Free.Alive -and ($c36Free.Above -eq 'n/a (no owner)'))
  # v2.0.1 merge, two ways the guard can be wired WRONG while still looking alive:
  # (a) the arm-time z-order snapshot is fed to the differ as the AFTER set (then a
  #     popup that closed would still read present), (b) presence taken from the
  #     transparent-filtered New list (then a click-through popup aborts every script
  #     that guards it). Both are pinned against the merged differ's own answer.
  $c36SnapBase = @{ Hwnd = [IntPtr]4321; Pid = 777; Class = '#32768'; X = 620; Y = 300; W = 480; H = 320; OwnerHwnd = [IntPtr]4000; Above0 = $c36Above; Tolerance = 3; MustBeFg = $false }
  $c36SnapOk = Test-PopupGuardAlive $c36SnapBase $true @() @{ X = 620; Y = 300; W = 480; H = 320 } ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - the z-order leg reads the CURRENT enumeration, not the arm-time snapshot (buried popup fails even when it was in the baseline)' (
    (-not $c36SnapOk.Alive) -and ($c36SnapOk.Above -eq 'no'))
  $c36TipPopup = @([pscustomobject]@{ Handle = [IntPtr]4321; Class = 'tooltips_class32'; Title = 'x'; Transparent = $true })
  $c36TipAlive = Test-PopupGuardAlive $c36Base $true $c36TipPopup @{ X = 620; Y = 300; W = 480; H = 320 } ([IntPtr]0)
  ST-Check 'unit: popup guard verdict - a click-through guarded popup is still above its owner (the alarm filter must not decide existence)' (
    $c36TipAlive.Alive -and ($c36TipAlive.Above -eq 'yes'))
  $c36Log = '2026-10-01 00:00:00 UTC | script | C:\temp\steps.json | POPUP-GUARD-ABORTED at step 4 of 7: popup GONE (window destroyed)'
  $c36Clean = '2026-10-01 00:00:00 UTC | click | 10 20 | pid=1 title=x'
  ST-Check 'unit: replay abort scanner - the popup-guard marker is found and ordinary lines are not' (
    (@(Test-ReplayPopupAbort @($c36Log, $c36Clean)).Count -eq 1) -and (@(Test-ReplayPopupAbort @($c36Clean)).Count -eq 0))
  # Wiring: the two script steps exist, the guard aborts instead of skipping, the
  # win-close auto-release and the replay refusal are each wired exactly once, and
  # require-popup/release-popup stay OUT of the replayable list (they are script steps,
  # not CLI commands - replay must never see them).
  $c37Known = 0
  $c37ReplLine = New-Object System.Collections.ArrayList
  for ($c37i = 0; $c37i -lt $codeLines.Count; $c37i++) {
    if ($c37i -ge $j5ProdStart -and $c37i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c37i].Contains("`$known = @('click'")) { $c37Known++ }
    if ($codeLines[$c37i].Contains("`$replayable = @('move'")) { [void]$c37ReplLine.Add($codeLines[$c37i]) }
  }
  $c37ThrowN = 0; $c37AbortN = 0; $c37MarkN = 0; $c37AutoN = 0; $c37RefuseN = 0; $c37AliveCall = 0
  for ($c37i = 0; $c37i -lt $codeLines.Count; $c37i++) {
    if ($c37i -ge $j5ProdStart -and $c37i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c37i] -match '^\s*#') { continue }
    if ($codeLines[$c37i].Contains(('POPUP-GUARD-' + 'ABORT: popup guard: '))) { $c37ThrowN++ }
    if ($codeLines[$c37i].Contains(('script aborted: popup guard ' + 'failed'))) { $c37AbortN++ }
    if ($codeLines[$c37i].Contains(('POPUP-GUARD-AB' + 'ORTED at step'))) { $c37MarkN++ }
    if ($codeLines[$c37i].Contains(('win-close closed the guarded ' + 'popup'))) { $c37AutoN++ }
    if ($codeLines[$c37i].Contains(('refusing to replay a script that was aborted by the popup guard '))) { $c37RefuseN++ }
    if ($codeLines[$c37i].Contains('= Test-PopupGuardAlive ')) { $c37AliveCall++ }
  }
  ST-Check 'lint: require-popup/release-popup are known script steps, the survival verdict is called from exactly one place, and the abort/refusal contracts each have one producer' (
    ($c37Known -eq 1) -and ($c37AliveCall -eq 1) -and ($c37ThrowN -eq 1) -and ($c37AbortN -eq 1) -and ($c37MarkN -eq 1) -and ($c37AutoN -eq 2) -and ($c37RefuseN -eq 1))
  ST-Check 'lint: require-popup and release-popup never enter the replayable list (script steps, not CLI commands - replay must not see them)' (
    (@($c37ReplLine).Count -eq 1) -and (-not ($c37ReplLine[0].Contains('require-popup'))) -and (-not ($c37ReplLine[0].Contains('release-popup'))))
  Write-Output ("      popup guard wiring: known=$c37Known alive-call=$c37AliveCall throw=$c37ThrowN abort-line=$c37AbortN marker=$c37MarkN auto-release=$c37AutoN refuse=$c37RefuseN")

  # ---------- lint: v2.0.1 popup delta merge (owner ruling 2026-10-01) ----------
  # The failure mode of a MERGE is not a missing check, it is a second copy that
  # quietly disagrees - which is exactly why v1.9.0 shipped Test-PopupGuardAlive
  # beside the differ. So this pins: every handle-membership operator lives inside
  # Compare-PopupDelta, the guard asks the differ instead of computing it, and each
  # direction still has exactly one production consumer (the selftest body is skipped
  # so the units' own calls cannot satisfy or break the count).
  $c38Diff = @(-1, -1); $c38Grd = @(-1, -1); $c38Open = ''
  for ($c38i = 0; $c38i -lt $codeLines.Count; $c38i++) {
    if ($codeLines[$c38i] -match '^function ') {
      if ($c38Open -eq 'diff' -and $c38Diff[1] -lt 0) { $c38Diff[1] = $c38i }
      if ($c38Open -eq 'grd' -and $c38Grd[1] -lt 0) { $c38Grd[1] = $c38i }
      $c38Open = ''
      if ($codeLines[$c38i] -match '^function Compare-PopupDelta') { $c38Diff = @($c38i, -1); $c38Open = 'diff' }
      if ($codeLines[$c38i] -match '^function Test-PopupGuardAlive') { $c38Grd = @($c38i, -1); $c38Open = 'grd' }
    }
  }
  $c38Member = 0; $c38MemberInDiffer = 0; $c38Call = 0; $c38CallInGuard = 0
  for ($c38i = 0; $c38i -lt $codeLines.Count; $c38i++) {
    if ($c38i -ge $j5ProdStart -and $c38i -lt $j5ProdEnd) { continue }
    if ($codeLines[$c38i] -match '^\s*#') { continue }
    if ($codeLines[$c38i] -match '(-not)?contains \[int64\]') {
      $c38Member++
      if ($c38i -ge $c38Diff[0] -and $c38i -lt $c38Diff[1]) { $c38MemberInDiffer++ }
    }
    if ($codeLines[$c38i].Contains('= Compare-PopupDelta ')) {
      $c38Call++
      if ($c38i -ge $c38Grd[0] -and $c38i -lt $c38Grd[1]) { $c38CallInGuard++ }
    }
  }
  ST-Check 'lint: popup handle-set membership has one producer and the guard reads the differ (v2.0.1 merge, no second copy)' (
    ($c38Member -eq 2) -and ($c38MemberInDiffer -eq 2) -and ($c38Call -eq 2) -and ($c38CallInGuard -eq 1) -and ($c38Diff[1] -gt $c38Diff[0]) -and ($c38Grd[1] -gt $c38Grd[0]))
  Write-Output ("      popup delta merge: membership=$c38Member/$c38MemberInDiffer differ-range=$($c38Diff[0])..$($c38Diff[1]) guard-range=$($c38Grd[0])..$($c38Grd[1]) calls=$c38Call/$c38CallInGuard")


  # context hand-back (A-14l): these names were produced here while the section was inline and are
  # still read by bodies that stayed in lib/selftest.ps1 - the three sample window objects feed the
  # popup-delta units that sit under a later banner, and the dialog-cancel line numbers feed the audit
  # detail line further down. They leave through the declared channel, never through scope luck.
  $Ctx['dcCase'] = $dcCase
  $Ctx['dcKnown'] = $dcKnown
  $Ctx['wA'] = $wA
  $Ctx['wB'] = $wB
  $Ctx['wT'] = $wT
}

# lib/selftest-audit-output.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1
# by A-14m (A-beta). Bodies are byte-identical to what the section carried, with ONE line deliberately
# left behind: the dialog-cancel wiring echo reads popup-occlusion hand-backs, which A-14l binds into
# the orchestration scope by name, and a lifted family may only be handed published context. Routing a
# value from one family to another would be a new channel, not a move - so the echo stays where its
# inputs are and this file carries the gates.
#
# The audit/outlet family: audit-log redaction and rotation, the two OCR --json key sets, the covering
# list rendered in one place, the action family --json envelope, --json never accepted-and-ignored,
# --dump pointers, a stamp that claims UTC, resource hygiene, and the line/occurrence gap spoken aloud.
function Invoke-SelftestFamily-AuditOutput($Ctx) {
  # context handover (the one thing in this file above the lifted text that is not lifted text)
  $clCount = $Ctx['clCount']
  $code = $Ctx['code']
  $codeLines = $Ctx['codeLines']
  $evMark = $Ctx['evMark']
  $evWire = $Ctx['evWire']
  $j5ProdEnd = $Ctx['j5ProdEnd']
  $j5ProdStart = $Ctx['j5ProdStart']

  # ---------- contract: v1.5.3 the two OCR --json top-level key sets are pinned ----------
  # This shape is a PUBLISHED CONTRACT, not an implementation detail: nothing inside
  # this repo parses it (ConvertFrom-Json appears only in script/replay paths), the
  # real consumers are AI sessions reading the output. v1.5.1 already broke it once
  # (array -> object) with nothing but a README line to mark the boundary, so the
  # set is now compared EXACTLY - add a key or drop a key and this goes red, which
  # is the moment $JsonSchemaVersion and the two README lines must change together.
  $cFind = New-OcrJsonEnvelope 'hits' $null @()
  $cRead = New-OcrJsonEnvelope 'lines' $null @()
  # v3.0.0 (B-6) CONTRACT CHANGE: both envelopes gained `contentTrust` and schemaVersion moved
  # 1 -> 2. This is the bookkeeping the envelope comment demands ("changing the key set is a
  # breaking change: bump schemaVersion AND the two README lines in the same commit"), and it
  # is why the comparison is an EXACT set: had the check been "contains the keys I care
  # about", the new key would have shipped without a single check noticing.
  $cWantFind = Get-JsonContractKeySet 'find'
  $cWantRead = Get-JsonContractKeySet 'read'
  # The contract must have ONE home. Tokens are assembled at runtime because this scanner's own
  # source contains the very literals it hunts (measured twice this round already).
  $jkTok = "'schemaVersion', 'contentTrust', 'oc" + "cluded', 'coveredBy'"
  $jkCall = 'Get-JsonContract' + "KeySet '"
  $jkProducer = 0; $jkReaders = 0; $jkLits = 0
  foreach ($jkL in $codeLines) {
    $jkT = "$jkL"
    if ($jkT.StartsWith('function Get-JsonContractKeySet')) { $jkProducer++ }
    if ($jkT.Contains($jkCall)) { $jkReaders++ }
    if ($jkT.Contains($jkTok)) { $jkLits++ }
  }
  ST-Check 'lint: the published --json key contract has exactly one home (one producer, five readers, no stray literal copy - a second copy is how v3.0.0 drifted and two live checks sat red unseen for two rounds)' (
    ($jkProducer -eq 1) -and ($jkReaders -eq 5) -and ($jkLits -eq 2))
  Write-Output ('      json-contract homes: producer=' + $jkProducer + ' readers=' + $jkReaders + ' literals=' + $jkLits)
  $cGotFind = (@($cFind.PSObject.Properties.Name | Sort-Object) -join ',')
  $cGotRead = (@($cRead.PSObject.Properties.Name | Sort-Object) -join ',')
  ST-Check 'contract: find-text --json top-level keys are exactly schemaVersion+occluded+coveredBy+hits (add or drop one = breaking)' (
    $cGotFind -ceq $cWantFind)
  ST-Check 'contract: read-text --json top-level keys are exactly schemaVersion+occluded+coveredBy+lines (add or drop one = breaking)' (
    $cGotRead -ceq $cWantRead)
  # v3.0.0 (B-6) BREAKING CHANGE, declared: 1 -> 2, because `contentTrust` joined the key set
  # of every envelope. v3.1.0 (X-01) BREAKING CHANGE, declared: 2 -> 3, because the action
  # family got an envelope (see Get-ActionJsonCommandSet). The literal expectation stays a
  # literal ON PURPOSE - bumping the variable without coming here is the mistake this check
  # exists to make impossible, and the second conjunct proves the builders read the same
  # variable rather than a copied constant.
  ST-Check 'contract: both envelopes report the declared schemaVersion, which is 3 since the action family joined the contract' (
    [int]$script:JsonSchemaVersion -eq 3 -and $cFind.schemaVersion -eq 3 -and $cRead.schemaVersion -eq 3)
  # the occlusion half of the contract, from a synthetic gate: a gate that ran must
  # produce an INTEGER percent (not 37.4, not ''), and coveredBy must be an array
  # even for a single coverer - a scalar here silently breaks JSON consumers that
  # iterate it.
  $cGate = @{ Err = $false; Pct = 37.4; Covering = @(@{ Pid = 4242; Proc = 'notepad'; Title = 'T'; Count = 3 }) }
  $cGateObj = New-OcrJsonEnvelope 'hits' $cGate @()
  $cCov1 = @($cGateObj.coveredBy)[0]
  $cGotCov = (@($cCov1.PSObject.Properties.Name | Sort-Object) -join ',')
  $cWantCov = (@('count', 'pid', 'proc', 'title') | Sort-Object) -join ','
  ST-Check 'contract: occluded is the rounded integer percent and coveredBy stays an array of {pid,proc,title,count}' (
    $cGateObj.occluded -is [int] -and $cGateObj.occluded -eq 37 -and
    @($cGateObj.coveredBy).Count -eq 1 -and $cGotCov -ceq $cWantCov)
  $cNoGate = New-OcrJsonEnvelope 'hits' $null @()
  ST-Check 'contract: no gate means occluded=null and coveredBy=[] (keys never disappear, only their values do)' (
    $null -eq $cNoGate.occluded -and @($cNoGate.coveredBy).Count -eq 0)
  # Wiring nail: the checks above prove what the BUILDER emits. They would still be
  # green if a command quietly went back to hand-building its object at the call
  # site, so pin the emission path itself - exactly one ConvertTo-Json per command,
  # both fed by the envelope variable.
  $cWirePat = '^\s*\$envelope \| ConvertTo-Json -Compress -Depth (4|5)\s*$'
  $cWire = 0
  for ($i = 0; $i -lt $codeLines.Count; $i++) {
    if ($codeLines[$i] -match $cWirePat) { $cWire++ }
  }
  ST-Check 'contract: find-text and read-text both emit --json through the envelope builder (no hand-built object at the call site)' (
    $cWire -eq 2)
  $cPlantWire = '$envelope | ConvertTo-Json -Compress -Depth 5'
  ST-Check 'contract: wiring pattern detects a planted emission (not vacuous)' ($cPlantWire -match $cWirePat)
  # control: the set comparison is not comparing a constant - one extra key really
  # does break it, which is the entire point of pinning a contract
  $cWithExtra = [pscustomobject]@{ schemaVersion = 1; occluded = $null; coveredBy = @(); hits = @(); extraKey = 1 }
  $cGotExtra = (@($cWithExtra.PSObject.Properties.Name | Sort-Object) -join ',')
  ST-Check 'contract: an added top-level key breaks the comparison (control)' ($cGotExtra -cne $cWantFind)

  # ---------- contract: v1.5.4 (R-25) the covering list is rendered in ONE place ----------
  # R-25 reached me as "two pids blamed in one command". Measured, that reading came
  # from the observer truncating the report; the real defects were that three call
  # sites rendered the same list in three shapes, the gate path dropped everything
  # past the THIRD coverer silently, and no line said which rectangle it measured.
  # These assertions are what stop any of the three from coming back.
  # Deliberately UNSORTED input: the renderer must sort, so a future change to the
  # upstream ordering can never make the summary and the list disagree.
  $oC1 = @{ Hwnd = [IntPtr]11; Pid = 111; Proc = 'pA'; Title = 'T-A'; Count = 2 }
  $oC2 = @{ Hwnd = [IntPtr]22; Pid = 222; Proc = 'pB'; Title = 'T-B'; Count = 9 }
  $oC3 = @{ Hwnd = [IntPtr]33; Pid = 333; Proc = 'pC'; Title = 'T-C'; Count = 5 }
  $oR = Format-OcclusionCovering @($oC1, $oC3, $oC2) 25
  # A) THE contract the owner asked for: the one-line summary IS the first detailed
  # line's subject - not "whatever [0] happens to be in some other order".
  $oSumPid = ''
  if ((Get-OptValue $oR 'Summary') -match '^pid=(\d+)') { $oSumPid = $Matches[1] }
  $oFirstPid = ''
  if (@((Get-OptValue $oR 'Lines'))[0] -match '^pid=(\d+)') { $oFirstPid = $Matches[1] }
  ST-Check 'contract: the occlusion summary is the first rendered covering line (same pid, by construction)' (
    $oSumPid -ceq $oFirstPid -and $oSumPid -ceq '222')
  ST-Check 'contract: the covering list is ordered by sample points descending (unsorted input in, sorted out)' (
    (@((Get-OptValue $oR 'Items') | ForEach-Object { $_.Count }) -join ',') -ceq '9,5,2')
  # B) every coverer is named with its own count, and the summary ADMITS the rest.
  ST-Check 'contract: every coverer is named with its x/N share - nothing past the third is dropped' (
    @((Get-OptValue $oR 'Lines')).Count -eq 3 -and
    ((Get-OptValue $oR 'Lines') -join '|') -match 'pid=111 .*\(2 of 25 sample points\)' -and
    ((Get-OptValue $oR 'Lines') -join '|') -match 'pid=222 .*\(9 of 25 sample points\)')
  ST-Check 'contract: the one-line summary admits it only names one of them (+K more)' (
    (Get-OptValue $oR 'Summary') -like 'pid=222 * (+2 more)')
  # the marker itself: same helper for both paths, and it never lies
  ST-Check 'unit: (+K more) is empty when nothing is hidden and counts exactly when something is' (
    (Add-OcclusionMore 3 3) -ceq '' -and (Add-OcclusionMore 5 3) -ceq ' (+2 more)' -and
    (Add-OcclusionMore 1 1) -ceq '')
  # four coverers, the shape R-25 was reported in: the 4th must not be invisible
  $oC4 = @{ Hwnd = [IntPtr]44; Pid = 444; Proc = 'pD'; Title = 'T-D'; Count = 1 }
  $oR4 = Format-OcclusionCovering @($oC1, $oC2, $oC3, $oC4) 25
  ST-Check 'contract: with four coverers the gate list still names all four (R-25 was the 4th vanishing)' (
    @((Get-OptValue $oR4 'Lines')).Count -eq 4 -and ((Get-OptValue $oR4 'Lines') -join '|') -match 'pid=444 ' -and
    $oR4.Summary -like '*(+3 more)')
  # summed with an explicit loop, NOT Measure-Object -Property Count: measured here,
  # on hashtables that carry their own 'Count' KEY, Measure-Object sums the INTRINSIC
  # key count (5+5=10) while foreach { $_.Count } reads the entry (2+9=11). Same
  # expression text, two meanings - so anything touching these coverer rows sums by hand.
  $oSum4 = 0
  foreach ($it in @((Get-OptValue $oR4 'Items'))) { $oSum4 += [int]$it.Count }
  ST-Check 'contract: the rendered items are exactly the input items (no drop, no duplicate) and their shares sum' (
    @((Get-OptValue $oR4 'Items')).Count -eq 4 -and @($oR4.Lines).Count -eq @((Get-OptValue $oR4 'Items')).Count -and $oSum4 -eq 17)
  # anti-drift nail: the gate path must never go back to a silent cap. The owners
  # path is ALLOWED to cap (it now says so), so the pattern must exist exactly once.
  $oCap = New-Object System.Collections.ArrayList
  $oCapBound = New-Object System.Collections.ArrayList
  for ($i = 0; $i -lt $codeLines.Count; $i++) {
    $l = $codeLines[$i]
    if ($l -match 'SELFTEST-EXEMPT') { continue }
    # v1.5.7: the owners cap moved behind a named local ($ownMax) so the "we hid K more"
    # statement can sit one line from it (the truncation contract). The old literal
    # "-First 3" pattern therefore no longer matches - asserting on the literal would have
    # made this lint fire on a refactor that strictly improved the thing it cares about.
    if ($l -match 'Select-Object\s+-First\s+(3\b|\$ownMax\b)') { [void]$oCap.Add($i + 1) }
    # ASSEMBLED, not written whole: this scan reads the whole file including its own
    # selftest block, so a literal pattern here would match the line that declares it
    # and the count would be 2 on a file that has exactly one real cap.
    $oCapBindPat = 'Add-OcclusionMore .*Owners.*\$own' + 'Max'
    if ($l -match $oCapBindPat) { [void]$oCapBound.Add($i + 1) }
  }
  ST-Check 'lint: exactly one three-item cap survives in the occlusion code and it is the owners path' (
    @($oCap).Count -eq 1)
  ST-Check 'lint: that cap is bound to its hidden-count helper (a cut that cannot stop admitting)' (
    @($oCapBound).Count -eq 1)
  if (@($oCap).Count -ne 1) { Write-Output "      -First 3 caps at line(s): $(Format-SourceLineList @($oCap))" }
  # the label that made two correct lines look contradictory must always be present
  $oV = Format-OcclusionVerdict 'guard' @{ X = 10; Y = 20; W = 30; H = 40 } 36 (Get-OptValue $oR 'Summary') ''
  $oV0 = Format-OcclusionVerdict 'read' @{ X = 1; Y = 2; W = 3; H = 4 } 0 'unknown' ''
  $oVErr = Format-OcclusionVerdict 'hit' $null 0 '' 'all-offscreen'
  ST-Check 'contract: every occlusion verdict names its scan AND the rect it measured' (
    $oV -like 'scan=guard rect=(10,20,30x40) occluded=36% coveredBy=pid=222*' -and
    $oV0 -ceq 'scan=read rect=(1,2,3x4) occluded=0%')
  ST-Check 'contract: a failed scan says n/a with its reason and never invents a coveredBy' (
    $oVErr -like 'scan=hit occluded=n/a (all-offscreen)*' -and $oVErr -notmatch 'coveredBy')

  # ---------- unit: v1.5.7 (J-05) the line/occurrence gap must be spoken out loud ----------
  # The owner ruled line granularity STAYS (word hits would turn one line containing the
  # text twice into two hits and break every --index script), so the deliverable is the
  # sentence - and a sentence nobody can prove fires is just decoration.
  $j5Two = Format-MultiOccurrenceHint 'AAA' @([pscustomobject]@{ Text = 'AAA BBB AAA' })
  ST-Check 'unit: J-05 hint fires when one hit line holds the needle twice' (
    $j5Two -ne '' -and $j5Two.Contains('2 time(s)') -and $j5Two.Contains('1 hit line(s)') -and $j5Two.Contains('a hit is ONE LINE'))
  $j5One = Format-MultiOccurrenceHint 'AAA' @([pscustomobject]@{ Text = 'AAA BBB' })
  ST-Check 'unit: J-05 hint is silent when hits and occurrences agree' ($j5One -ceq '')
  $j5TwoLines = Format-MultiOccurrenceHint 'AAA' @([pscustomobject]@{ Text = 'AAA x' }, [pscustomobject]@{ Text = 'y AAA' })
  ST-Check 'unit: J-05 hint is silent for two lines with one occurrence each (those ARE two hits)' ($j5TwoLines -ceq '')
  $j5Fold = Format-MultiOccurrenceHint 'ZZZ' @([pscustomobject]@{ Text = 'AAA x' })
  ST-Check 'unit: J-05 never claims occurrences it could not count (a fold-only match says nothing)' ($j5Fold -ceq '')
  $j5Empty = Format-MultiOccurrenceHint '' @([pscustomobject]@{ Text = 'AAA' })
  $j5NoHits = Format-MultiOccurrenceHint 'AAA' @()
  ST-Check 'unit: J-05 prints nothing for an empty needle or an empty hit list' ($j5Empty -ceq '' -and $j5NoHits -ceq '')
  $j5Mark = 'Format-MultiOccurrence' + 'Hint '
  $j5Wire = @()
  for ($j5i = 0; $j5i -lt $codeLines.Count; $j5i++) {
    if ($j5i -ge $j5ProdStart -and $j5i -lt $j5ProdEnd) { continue }
    if ($codeLines[$j5i] -match '^\s*#') { continue }
    if ($codeLines[$j5i].Contains($j5Mark)) { $j5Wire += ($j5i + 1) }
  }
  ST-Check 'lint: find-text, find-click and menu-pick all route the J-05 hint through one producer' (
    @($j5Wire).Count -eq 3 -and $j5ProdStart -gt 0)
  Write-Output "      J-05 production call sites: $(@($j5Wire).Count) (lines $(Format-SourceLineList $j5Wire))"

  # ---------- unit: audit-log redaction + rotation (v1.4.1, audit #4/#13) ----------
  $red = Get-RedactedLogArgs @('type', '--to', 'notepad', 'SECRET-TOKEN-123', '--verify') @('SECRET-TOKEN-123') $false
  ST-Check 'unit: log redaction hides payload, keeps flags and target' (
    (($red -join ' ') -notmatch 'SECRET-TOKEN-123') -and (($red -join ' ') -match '<redacted:16chars>') -and ($red -contains '--to'))
  $redKeep = Get-RedactedLogArgs @('type', 'SECRET-TOKEN-123') @('SECRET-TOKEN-123') $true
  ST-Check 'unit: --log-payload records the payload verbatim' (($redKeep -join ' ') -match 'SECRET-TOKEN-123')
  $redGuard = Get-RedactedLogArgs @('click', '10', '20', '--guard-region', '0,0,600,50=SEEKRET') @() $false
  ST-Check 'unit: guard-region needle redacted, coordinates kept' (
    (($redGuard -join ' ') -notmatch 'SEEKRET') -and (($redGuard -join ' ') -match '0,0,600,50=<redacted:7chars>'))
  $rotDir = Join-Path $env:TEMP ('dtrot_' + [guid]::NewGuid().ToString('N'))
  [void](New-Item -ItemType Directory -Force -Path $rotDir)
  try {
    $rotLog = Join-Path $rotDir 'actions.log'
    [System.IO.File]::WriteAllText($rotLog, ('x' * 300))
    $did = Invoke-LogRotation $rotLog 100 2
    $rotated = (-not (Test-Path $rotLog)) -and (@(Get-ChildItem $rotDir -Filter 'actions_*.log').Count -ge 1)
    for ($ai = 1; $ai -le 4; $ai++) { [System.IO.File]::WriteAllText((Join-Path $rotDir ('actions_000' + $ai + '.log')), ('y' * 10)) }
    [System.IO.File]::WriteAllText($rotLog, ('z' * 300))
    Invoke-LogRotation $rotLog 100 2 | Out-Null
    $archives = @(Get-ChildItem $rotDir -Filter 'actions_*.log').Count
    ST-Check 'unit: log rotation archives the over-threshold log' ($did -and $rotated)
    ST-Check 'unit: log rotation prunes archives beyond keep' ($archives -eq 2)
  } finally { Remove-Item -LiteralPath $rotDir -Recurse -Force -ErrorAction SilentlyContinue }

  # ---------- v3.0.0 B-4: --dump (write the bulk to a file, print a pointer) ----------
  # The closed set first, both directions: every declared name must be a REAL command (a
  # typo in the set would advertise a flag that reaches nothing), and a real command that is
  # not in the set must be refused (the silent no-op is what --json had been doing).
  $dumpSet = @(Get-DumpCommandSet)
  $dumpNotCommands = @($dumpSet | Where-Object { -not ($code -match ("'" + [regex]::Escape($_) + "' \{")) })
  ST-Check 'lint: every --dump command is a real dispatch case (no advertised typo can reach nothing)' (@($dumpNotCommands).Count -eq 0)
  ST-Check 'unit: --dump is accepted for the declared read commands and refused for an action and for a non-command' (
    (Test-DumpCommand 'read-text') -and (Test-DumpCommand 'uia-tree') -and (Test-DumpCommand 'wins') -and
    -not (Test-DumpCommand 'click') -and -not (Test-DumpCommand 'wins2') -and -not (Test-DumpCommand ''))
  # production sites only: the units below call the emitter themselves, and a scan that
  # counts its own test corpus is the self-match family again.
  $dumpMark = 'Emit-Dump' + 'Output '
  $dumpWire = @()
  for ($di = 0; $di -lt $codeLines.Count; $di++) {
    if ($di -ge $j5ProdStart -and $di -lt $j5ProdEnd) { continue }
    if ($codeLines[$di] -match '^\s*#') { continue }
    if ($codeLines[$di].Contains($dumpMark)) { $dumpWire += ($di + 1) }
  }
  ST-Check 'lint: exactly one production emitter renders a dump (one pointer, not per-command copies)' (@($dumpWire).Count -eq 1)
  # behaviour on the real filesystem, in TEMP - including the two refusals that protect the
  # user's files: never overwrite, never create a directory tree.
  $dumpDir = Join-Path $env:TEMP ('dtx-dump-' + (Get-Date -Format 'yyyyMMddHHmmss'))
  [void](New-Item -ItemType Directory -Path $dumpDir)
  try {
    $dumpFile = Join-Path $dumpDir 'out.txt'
    $dumpLines = @()
    for ($dl = 1; $dl -le 12; $dl++) { $dumpLines += "line$dl" }
    $dumpEcho = @(Emit-DumpOutput $dumpLines $dumpFile 'wins')
    $dumpEchoTxt = ($dumpEcho -join "`n")
    $dumpReadBack = @([System.IO.File]::ReadAllLines($dumpFile))
    ST-Check 'unit: a dump writes every line and the pointer reports the file OWN counts (completeness read off the artifact, not off the input array)' (
      @($dumpReadBack).Count -eq 12 -and $dumpEchoTxt.Contains('lines=12 bytes=') -and
      $dumpEchoTxt.Contains('dump-readback: lines=12'))
    # a 12-line dump shows 5: the truncation must say the hidden count out loud (J-06).
    ST-Check 'unit: a truncated dump sample says how many lines it hid' (
      $dumpEchoTxt.Contains('(+7 more line(s) NOT shown here') -and $dumpEchoTxt.Contains('| line5') -and
      -not ($dumpEchoTxt -match '\| line6'))
    $dumpOver = ''
    try { Emit-DumpOutput @('x') $dumpFile 'wins' | Out-Null } catch { $dumpOver = "$($_.Exception.Message)" }
    ST-Check 'unit: --dump refuses to overwrite an existing file and writes nothing' (
      $dumpOver -like '*refusing to overwrite*' -and (@([System.IO.File]::ReadAllLines($dumpFile)).Count -eq 12))
    $dumpNoDir = ''
    try { Emit-DumpOutput @('x') (Join-Path $dumpDir 'nope\deep.txt') 'wins' | Out-Null } catch { $dumpNoDir = "$($_.Exception.Message)" }
    ST-Check 'unit: --dump refuses a missing parent instead of creating directories' (
      $dumpNoDir -like '*parent directory does not exist*' -and -not (Test-Path (Join-Path $dumpDir 'nope')))
    # the file must be readable by the NEXT call: UTF-8 without BOM, and the empty-output case
    # says so rather than looking like a failed write.
    $dumpEmptyFile = Join-Path $dumpDir 'empty.txt'
    $dumpEmpty = @(Emit-DumpOutput @() $dumpEmptyFile 'read-text') -join "`n"
    $dumpBytes = [System.IO.File]::ReadAllBytes($dumpEmptyFile)
    $dumpBom = ($dumpBytes.Length -ge 3 -and [int]$dumpBytes[0] -eq 0xEF -and [int]$dumpBytes[1] -eq 0xBB -and [int]$dumpBytes[2] -eq 0xBF)
    ST-Check 'unit: an empty dump still writes a file, self-reports lines=0 and carries no BOM' (
      $dumpEmpty.Contains('lines=0') -and $dumpEmpty.Contains('produced no output') -and
      (Test-Path -LiteralPath $dumpEmptyFile) -and -not $dumpBom)
  } finally {
    try { Remove-Item -Recurse -Force $dumpDir } catch { }
  }

  # ---------- v3.0.0 S-2: --json must never be accepted and ignored ----------------------
  # The gate is proved at the boundary the caller actually uses (a real subprocess, a real
  # command line) rather than by scanning the dispatcher for $script:Json: two attempts at
  # that scan measured the wrong region on their own terms (one latched onto a 4-space
  # quoted-brace line at file line 270 and derived an empty set while reporting 84 cases seen;
  # the other hit the hashtable key-vs-property trap because a command is literally named
  # `keys`). A scan whose failure mode is "silently agrees" is not evidence, and this repo's
  # own rule is to test the road the caller drives. So: the positive case must PARSE as JSON
  # and the negative case must refuse with the flag's own name and exit 1.
  $jcDeclared = @(Get-JsonCapableCommandSet | Sort-Object)
  $jcFake = @()
  foreach ($jd in @($jcDeclared)) {
    if (-not ($code -match ("'" + [regex]::Escape($jd) + "' \{"))) { $jcFake += $jd }
  }
  ST-Check 'lint: every declared --json command is a real dispatch case (the refusal text cannot name a phantom)' (@($jcFake).Count -eq 0)
  ST-Check 'unit: --json is refused for a command that cannot render it, and accepted for one that can' (
    (Test-JsonCapableCommand 'wins') -and (Test-JsonCapableCommand 'read-text') -and
    (Test-JsonCapableCommand 'click') -and (Test-JsonCapableCommand 'paste') -and
    -not (Test-JsonCapableCommand 'cursor') -and -not (Test-JsonCapableCommand 'shot') -and
    -not (Test-JsonCapableCommand ''))
  # A-24 gauge repair: one child-spawn runner for the offline probes.
  # Owner ruling of 2026-10-19, three content criteria: keep both child streams, read the child's REAL
  # exit code, and report a collection failure apart from a contract failure. Measured on this machine,
  # both engines, in .cowork-temp/a24g-channel/{shape,ctrl}-ps51.txt and -pwsh7.txt: under the entry's
  # `$ErrorActionPreference = 'Stop'` a native child that writes to stderr is promoted to a terminating
  # RemoteException on Windows PowerShell 5.1 whenever the capture REDIRECTS it - `2>&1` and `2> <file>`
  # both throw there, while pwsh 7 leaves the identical call non-terminating. So on 5.1 the line after
  # the call never runs, and by the time the catch reads `$LASTEXITCODE` the runtime has already rewritten
  # it to -1 (a seeded 42 comes back -1): -1 is what a broken collection looks like, which is where the
  # historical `refusal-exit=-1` reading came from. Not redirecting at all does not throw but drops the
  # child's stderr from the reading (measured stderr=0), which loses the diagnostics G-08 routed there on
  # purpose. Relaxing EAP around the call and restoring it in `finally` is the only measured shape that
  # keeps both streams AND yields the real code on both engines. `2>&1` stays deliberately: the elements
  # are split by type below, so stderr can never re-enter the face ConvertFrom-Json parses - the v4.1.3
  # bug is replaced here, not reinstated.
  # G-23 pre-flight: where the whole-stream evidence lands, and what it says it came from. The directory
  # lives outside the repository (the harness writes nothing into the delivery tree); a healthy run never
  # creates a file in it. It is named PER PROCESS on purpose: the plant checks below COUNT the files in
  # this directory, so a directory shared by two gates running at once (two trees, or my gate and the
  # monitor's) would read the other run's litter as its own - the same shape the CU-REL-01 live round
  # hit with a click counter shared across fixture instances. The id comes from a .NET call, not from $PID:
  # the A-14b context lint forbids a lifted body from reading a variable it did not declare, and writing
  # $PID was caught by it first-hand (`A-14b state gap: pid=free-read-at-19777`).
  $g23EvidenceDir = Join-Path $env:TEMP ('json-probe-evidence-' + [System.Diagnostics.Process]::GetCurrentProcess().Id)
  $g23SourceTag = 'entry=' + $script:ToolEntryPath + ' entry-sha=' + $(try { (Get-FileHash -LiteralPath $script:ToolEntryPath -Algorithm SHA256).Hash.Substring(0, 12) } catch { 'unreadable' }) + ' declared=' + [string]$script:DeclaredCheckTotal

  $cnpRun = {
    param([string[]]$ChildArgs)
    if (@($ChildArgs).Count -lt 1) { throw 'child runner: empty argument list - nothing would be measured' }
    $cnpRes = [pscustomobject]@{ ran = $false; code = $null; why = ''; out = ''; err = ''; outCount = 0; errCount = 0 }
    $cnpEap0 = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $cnpRaw = @()
    try {
      $cnpRaw = @(& powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath @ChildArgs 2>&1)
      $cnpRes.code = $LASTEXITCODE
      $cnpRes.ran = $true
    } catch { $cnpRes.why = $_.Exception.GetType().Name + ' :: ' + $_.Exception.Message }
    finally { $ErrorActionPreference = $cnpEap0 }
    $cnpSo = @(); $cnpSe = @()
    foreach ($cnpE in @($cnpRaw)) {
      if ($cnpE -is [System.Management.Automation.ErrorRecord]) { $cnpSe += [string]$cnpE.Exception.Message }
      else { $cnpSo += [string]$cnpE }
    }
    $cnpRes.out = ($cnpSo -join "`n"); $cnpRes.err = ($cnpSe -join "`n")
    $cnpRes.outCount = @($cnpSo).Count; $cnpRes.errCount = @($cnpSe).Count
    $cnpRes
  }
  $jsonPos = & $cnpRun -ChildArgs @('wins', '--json')
  $jsonPosObj = $null
  $jsonPosWhy = ''
  try { $jsonPosObj = @($jsonPos.out | ConvertFrom-Json) } catch { $jsonPosObj = $null; $jsonPosWhy = $_.Exception.Message }
  # G-23: this leg's contract is "stdout parses", so a failed parse is the surprise worth the whole stream.
  # A healthy run writes nothing here.
  $g23Evidence = ''
  if ($jsonPos.ran -and $null -eq $jsonPosObj) {
    $g23Evidence = Write-JsonProbeEvidence -Label 'read-json-leg' -Stdout $jsonPos.out -Stderr $jsonPos.err -Code ([string]$jsonPos.code) -Parsed $false -ParseWhy $jsonPosWhy -Dir $g23EvidenceDir -Source $g23SourceTag
  }
  $jsonNeg = & $cnpRun -ChildArgs @('cursor', '--json')
  if (-not $script:PsChildOk) {
    ST-Skip 'contract: --json on a capable command yields parseable JSON end to end (wins, real command line)' ($script:PsChildWhy + ' - the check spawns a child through the call operator, so there is nothing to measure')
    ST-Skip 'contract: --json on an incapable command REFUSES with exit 1 instead of printing text it never promised' ($script:PsChildWhy + ' - the check spawns a child through the call operator, so there is nothing to measure')
  } else {
  ST-Check 'contract: --json on a capable command yields parseable JSON end to end (wins, real command line)' (
    $jsonPos.code -eq 0 -and $null -ne $jsonPosObj -and @($jsonPosObj).Count -ge 1)
  ST-Check 'contract: --json on an incapable command REFUSES with exit 1 instead of printing text it never promised' (
    $jsonNeg.code -eq 1 -and ($jsonNeg.out + "`n" + $jsonNeg.err).Contains("--json is not supported by 'cursor'") -and
    -not (($jsonNeg.out + "`n" + $jsonNeg.err) -match 'cursor='))
  }

  # ---------- v4.4.0 (G-14, owner ruling): the residual resolve sentences must not enter the envelope ----------
  # End to end in two legs, because the scene that PRODUCES a non-main pick is desktop state and this run is
  # the offline-safe subset: leg A drives the real emitter in-process with a forced note (deterministic, and
  # it fails the moment the sentence goes back to the success stream), leg B spawns the real entry with
  # --json on a read command and requires stdout to parse with no note text anywhere in it.
  $g14Marker = ('DTX' + '-G14-NOTE-PROBE')
  $g14JsonLines = $null; $g14PlainLines = $null
  $g14JsonSave = $script:Json
  try {
    $script:Json = $true
    $script:ActivationLine = $g14Marker + '-act'; $script:ActivationNotice = $g14Marker + '-notice'; $script:ResolveNote = $g14Marker + '-pick'
    $g14JsonLines = @(& { Emit-ResolveNote })
    $g14JsonCleared = (-not $script:ActivationLine) -and (-not $script:ActivationNotice) -and (-not $script:ResolveNote)
    $script:Json = $false
    $script:ActivationLine = $g14Marker + '-act'; $script:ResolveNote = $g14Marker + '-pick'
    $g14PlainLines = @(& { Emit-ResolveNote })
    $g14PlainCleared = (-not $script:ActivationLine) -and (-not $script:ResolveNote)
  } finally {
    $script:Json = $g14JsonSave
    $script:ActivationLine = ''; $script:ActivationNotice = ''; $script:ResolveNote = ''
  }
  $g14JsonJoined = (@($g14JsonLines) -join "`n")
  $g14PlainJoined = (@($g14PlainLines) -join "`n")
  ST-Check 'e2e (G-14): with --json the three resolve sentences leave the success stream entirely, and without it they print verbatim in the same order (the real emitter, both roads, state cleared on both)' (
    (-not $g14JsonJoined.Contains($g14Marker)) -and (@($g14JsonLines).Count -eq 0) -and $g14JsonCleared -and
    (@($g14PlainLines).Count -eq 2) -and ($g14PlainJoined.Contains($g14Marker + '-act')) -and
    ($g14PlainJoined.Contains($g14Marker + '-pick')) -and ($g14PlainJoined.IndexOf($g14Marker + '-act') -lt $g14PlainJoined.IndexOf($g14Marker + '-pick')) -and
    $g14PlainCleared -and ($script:Json -eq $g14JsonSave))
  Write-Output ('      G-14 emitter: json-lines=' + @($g14JsonLines).Count + ' plain-lines=' + @($g14PlainLines).Count +
    ' json-leak=' + $g14JsonJoined.Contains($g14Marker) + ' cleared=' + $g14JsonCleared + '/' + $g14PlainCleared)
  $g14Child = & $cnpRun -ChildArgs @('wins', '--json')
  if ($script:PsChildOk) {
    ST-Check 'e2e (G-14): a real --json child of the read family still gives parseable JSON with no resolve sentence anywhere in stdout' (
      $g14Child.code -eq 0 -and ($g14Child.out -ne '') -and (-not $g14Child.out.Contains('activated=')) -and
      (-not $g14Child.out.Contains('picked the')) -and ($g14Child.out.Contains('pid')))
    # stdout-bytes is the face the assertion reads; the stderr counts are what the old `2> <file>` shape
    # believed it was keeping and, on 5.1, was not (the call threw before the file was ever written).
    Write-Output ('      G-14 child: exit=' + [string]$g14Child.code + ' ran=' + $g14Child.ran +
      ' stdout-lines=' + $g14Child.outCount + ' stdout-bytes=' + $g14Child.out.Length +
      ' stderr-lines=' + $g14Child.errCount + ' stderr-bytes=' + $g14Child.err.Length)
  } else {
    ST-Skip 'e2e (G-14): a real --json child of the read family still gives parseable JSON with no resolve sentence anywhere in stdout' ($script:PsChildWhy + ' - the check spawns a child process')
  }
  $jsonProbeDump = Format-JsonProbeDump $jsonPos.out ($null -ne $jsonPosObj)
  Write-Output ("      --json gate: declared=" + @($jcDeclared).Count + ' pos-exit=' + [string]$jsonPos.code +
    ' pos-ran=' + $jsonPos.ran + ' pos-stdout=' + $jsonPos.outCount + ' pos-stderr=' + $jsonPos.errCount +
    ' neg-exit=' + [string]$jsonNeg.code + ' neg-ran=' + $jsonNeg.ran +
    ' neg-stdout=' + $jsonNeg.outCount + ' neg-stderr=' + $jsonNeg.errCount +
    ' neg-hits-refusal=' + (($jsonNeg.out + "`n" + $jsonNeg.err).Contains('is not supported by')) +
    ' child-stdout=' + $jsonProbeDump + $(if ($g23Evidence) { ' ' + $g23Evidence } else { '' }))
  # A-24 gauge repair: the channel shape pin. The old pin read "the JSON probe may not merge the error
  # stream, the refusal probe must" - and THAT rule is where the -1 readings came from, because keeping
  # stderr out was done by not redirecting, which drops the diagnostics, and keeping it in was done by
  # merging, which throws on 5.1. The invariant is now: ONE runner, ONE spawn site inside it, the elements
  # split by type, and the face ConvertFrom-Json parses built from stdout only.
  # Both sides counted, because a one-sided lint is satisfied by deleting the pattern, so every predicate
  # is planted against a copy of its own violation. Markers AND plants are built by concatenation: this
  # file scans itself, and a contiguous literal of a marker in its own scanner or plant line counts as a
  # real site (the old gate went red on its own source lines that way on first run).
  # The scan is scoped to THIS family's lines on purpose: $codeLines is the aggregate, and a general shape
  # like a direct child spawn has ~40 legitimate sites in the live suite - unscoped, the count would be
  # meaningless. The slice runs from this family's function definition to the next top-level `function`,
  # which is also how it reads in the stitched single file (every lib body is present there in declaration
  # order). The slice size is reported and asserted non-trivial, because a scope that resolved to nothing
  # would make every count below read as a clean zero - the empty-ruler shape criterion 5 already bans.
  $chScopeMark = 'function Invoke-SelftestFamily-' + 'AuditOutput('
  $chScopeStart = -1
  $chScopeEnd = -1
  for ($chi = 0; $chi -lt $codeLines.Count; $chi++) {
    if ($chScopeStart -lt 0) { if ($codeLines[$chi].Contains($chScopeMark)) { $chScopeStart = $chi } }
    elseif ($codeLines[$chi] -match '^function ') { $chScopeEnd = $chi; break }
  }
  $chScope = @()
  if ($chScopeStart -ge 0) {
    if ($chScopeEnd -lt 0) { $chScope = @($codeLines[$chScopeStart..($codeLines.Count - 1)]) }
    else { $chScope = @($codeLines[$chScopeStart..($chScopeEnd - 1)]) }
  }
  $chDefMark = ('$cnpRu' + 'n = {')
  $chCallMark = ('= & $cnp' + 'Run')
  $chSpawnMark = ('& ' + 'powershell -NoProfile')
  $chSplatMark = ('@Child' + 'Args 2>&1')
  $chSplitMark = ('-is [System.Management.Automation.' + 'ErrorRecord]')
  $chMergeMark = ('.out +' + ' "`n"')
  $chJsonMark = ('| ' + 'ConvertFrom-Json')
  $chDefSites = @($chScope | Where-Object { $_.Contains($chDefMark) })
  $chCallSites = @($chScope | Where-Object { $_.Contains($chCallMark) })
  $chSpawnSites = @($chScope | Where-Object { $_.Contains($chSpawnMark) })
  $chSpawnLoose = @($chSpawnSites | Where-Object { -not $_.Contains($chSplatMark) })
  $chSplitSites = @($chScope | Where-Object { $_.Contains($chSplitMark) })
  $chJsonMerged = @($chScope | Where-Object { $_.Contains($chJsonMark) -and $_.Contains($chMergeMark) })
  $chPlant = @(
    ('  ' + '$chPlantA = ' + '& powershell -NoProf' + 'ile -File x wins --json 2>&1'),
    ('  ' + '$chPlantB = ($r.ou' + 't + "`n" + $r.er' + 'r) ' + '| ConvertF' + 'rom-Json'),
    ('  ' + '$cnpRu' + 'n = {'),
    ('  ' + '= & $cnp' + 'Run -ChildArgs @()')
  )
  $chPlantSpawnCaught = @($chPlant | Where-Object { $_.Contains($chSpawnMark) -and -not $_.Contains($chSplatMark) }).Count
  $chPlantMergeCaught = @($chPlant | Where-Object { $_.Contains($chJsonMark) -and $_.Contains($chMergeMark) }).Count
  $chPlantDefCaught = @($chPlant | Where-Object { $_.Contains($chDefMark) }).Count
  $chPlantCallCaught = @($chPlant | Where-Object { $_.Contains($chCallMark) }).Count
  ST-Check 'lint: every offline child probe in this family goes through the one runner (slice sized, one definition, one splatting spawn site, streams split by type, no merged face parsed as JSON) and each shape predicate catches its planted copy' (
    (@($chScope).Count -gt 400) -and (@($chDefSites).Count -eq 1) -and (@($chCallSites).Count -eq 5) -and
    (@($chSpawnSites).Count -eq 1) -and (@($chSpawnLoose).Count -eq 0) -and (@($chSplitSites).Count -eq 1) -and
    (@($chJsonMerged).Count -eq 0) -and ($chPlantSpawnCaught -eq 1) -and ($chPlantMergeCaught -eq 1) -and
    ($chPlantDefCaught -eq 1) -and ($chPlantCallCaught -eq 1))
  Write-Output ('      child channel: scope-lines=' + @($chScope).Count + ' runner-def=' + @($chDefSites).Count +
    ' call-sites=' + @($chCallSites).Count + ' spawn-sites=' + @($chSpawnSites).Count +
    ' unsplit-spawn=' + @($chSpawnLoose).Count + ' type-split=' + @($chSplitSites).Count +
    ' json-from-merged=' + @($chJsonMerged).Count + ' plants=[' + $chPlantSpawnCaught + '/' + $chPlantMergeCaught +
    '/' + $chPlantDefCaught + '/' + $chPlantCallCaught + ']')
  if (@($chSpawnLoose).Count -gt 0) { Write-Output '      a child spawn bypassed the runner - its exit code is a sentinel again' }
  if (@($chJsonMerged).Count -gt 0) { Write-Output '      a JSON probe parses a merged face again - warnings will break every caller that parses it' }
  # ---------- v3.1.0 X-01: the action family's --json envelope --------------------------------
  # The requirement this block exists to enforce is not "there is JSON", it is "the JSON cannot
  # lie and cannot drift": ONE producer, a CLOSED command table, a PINNED key set, and a
  # projection that is a subset of the text it carries. Every one of those has a planted
  # positive control below, because a set comparison over two empty sets is how this repo has
  # been fooled three times already (@($hashtable).Count, the scanner reading its own source,
  # and the v3.0.0 key-set copy that lived in three places).
  $xHelpSet = @(Get-ActionFamilyCommandsFromHelp (Get-UsageLines))
  $xTableSet = @(Get-ActionJsonCommandSet | Sort-Object -Unique)
  $xMissing = @($xHelpSet | Where-Object { $xTableSet -notcontains $_ })
  $xPhantom = @($xTableSet | Where-Object { $xHelpSet -notcontains $_ })
  Write-Output ('      action-json table: help=' + @($xHelpSet).Count + ' table=' + @($xTableSet).Count +
    ' missing=[' + ($xMissing -join ',') + '] phantom=[' + ($xPhantom -join ',') + ']')
  # the >=25 conjunct is the positive control: if the group parser ever returns an empty list,
  # both diffs below are empty and the equality would be vacuously true.
  ST-Check 'lint (X-01): the action --json command table is CLOSED (equals the help page act/text/clipboard set in BOTH directions, and the parse itself yields >=25 names)' (
    @($xMissing).Count -eq 0 -and @($xPhantom).Count -eq 0 -and @($xTableSet).Count -ge 25 -and @($xHelpSet).Count -ge 25)
  # Teeth for the parser itself: a group header must never be read as a command, and the option
  # lists inside a synopsis must never be read as commands (Get-HelpEntryNames' documented trap).
  $xFakeHelp = @('  act (absolute coords)', '    click <x> <y> [--occlude off|warn|strict]', '  clipboard', '    selftest [--live] = x')
  $xFakeGot = @(Get-ActionFamilyCommandsFromHelp $xFakeHelp)
  ST-Check 'unit (X-01): the action-set parser takes names from the act/clipboard groups only, never a group header and never an option token (off/warn/strict)' (
    (@($xFakeGot | Where-Object { $_ -in @('off', 'warn', 'strict', 'act', 'clipboard') }).Count -eq 0) -and
    (@($xFakeGot | Where-Object { $_ -eq 'click' }).Count -eq 1))
  # ONE producer + ONE pair of emission sites, both at the process boundary. Tokens assembled at
  # runtime: this scanner's own source sits on the face it scans (pit recorded in v3.1.0 7B).
  $xProdMark = 'function Format-Action' + 'JsonEnvelope'
  $xEmitMark = 'Format-Action' + 'JsonEnvelope $Cmd'
  $xProd = 0; $xEmit = @()
  for ($xi = 0; $xi -lt $codeLines.Count; $xi++) {
    if ($xi -ge $j5ProdStart -and $xi -lt $j5ProdEnd) { continue }
    if ($codeLines[$xi] -match '^\s*#') { continue }
    $xl = [string]$codeLines[$xi]
    if ($xl.StartsWith($xProdMark)) { $xProd++ }
    if ($xl.Contains($xEmitMark)) { $xEmit += ($xi + 1) }
  }
  Write-Output ('      action-json outlets: producer=' + $xProd + ' emit=[' + (Format-SourceLineList $xEmit) + ']')
  ST-Check 'lint (X-01): the action envelope has exactly one producer and exactly two emission sites (stdout + --dump), never a per-case copy' (
    $xProd -eq 1 -and @($xEmit).Count -eq 2)
  # The key sets. `signals` is DERIVED from the pattern map, so the map and a hardcoded contract
  # list are compared against each other - that is the drift nail; comparing the object to its
  # own source would be vacuous.
  $xWantSigLit = (@('expect', 'foreground', 'guard', 'hitWindow', 'notice', 'occluded', 'receipt', 'warning') | Sort-Object) -join ','
  $xEnv1 = Format-ActionJsonEnvelope 'click' @('hit-window: pid=1 proc=p title=T', 'clicked 1,2')
  $xObj1 = $null
  try { $xObj1 = $xEnv1 | ConvertFrom-Json } catch { $xObj1 = $null }
  $xTop = ''
  if ($null -ne $xObj1) { $xTop = (@($xObj1.PSObject.Properties.Name) | Sort-Object) -join ',' }
  ST-Check 'contract (X-01): the action envelope top-level keys are exactly schemaVersion+command+lines+signals and schemaVersion is the declared one (add or drop a key = breaking)' (
    $xTop -ceq (Get-ActionJsonKeySet) -and $null -ne $xObj1 -and [int]$xObj1.schemaVersion -eq [int]$script:JsonSchemaVersion)
  $xSigGot = ''
  if ($null -ne $xObj1) { $xSigGot = (@($xObj1.signals.PSObject.Properties.Name) | Sort-Object) -join ',' }
  ST-Check 'contract (X-01): signals carries exactly the eight pinned classes, the pattern map agrees with the pinned list, and the schema is 3 (this class of change was MAJOR in v3.0.0 - the conflict is registered, not eaten)' (
    $xSigGot -ceq $xWantSigLit -and (Get-ActionJsonSignalKeySet) -ceq $xWantSigLit -and [int]$script:JsonSchemaVersion -eq 3)
  # The projection has to be a SUBSET (it invents nothing) and COMPLETE per class (it drops
  # nothing) and must keep an unclassed line - all three on one planted fixture.
  $xL1 = 'hit-window: pid=7 proc=notepad title=T  (inside-target=True occluded=0% coveredBy=-)'
  $xL2 = "target pid=7 (foreground after send: pid=7 notepad 'T')"
  $xL3 = 'content guard FAILED: needle not present'
  $xL4 = 'receipt-tried=occluded-refused (lines 3->4)'
  $xL5 = 'unmap: C:\tmp\x.png (400x300 kind=rect scale=1) image (10,20) -> screen (110,220)'
  $xL6 = 'WARNING: something the reader must not lose'
  $xL7 = 'NOTICE: post-send foreground check unavailable: boom'
  $xL8 = 'expect refused: target occluded=44% coveredBy=pid=9 p'
  $xEnv2 = Format-ActionJsonEnvelope 'paste' @($xL1, $xL2, $xL3, $xL4, $xL5, $xL6, $xL7, $xL8)
  $xObj2 = $null
  try { $xObj2 = $xEnv2 | ConvertFrom-Json } catch { $xObj2 = $null }
  $xInvent = 0
  $xBlind = @()
  if ($null -ne $xObj2) {
    foreach ($pk in @($xObj2.signals.PSObject.Properties.Name)) {
      $pv = @($xObj2.signals.$pk)
      if ($pv.Count -lt 1) { $xBlind += $pk }
      foreach ($v in $pv) { if (@($xObj2.lines) -notcontains [string]$v) { $xInvent++ } }
    }
  } else { $xInvent = -1 }
  Write-Output ('      action-json projection: invented=' + $xInvent + ' blind=[' + ($xBlind -join ',') + '] lines=' +
    $(if ($null -ne $xObj2) { @($xObj2.lines).Count } else { -1 }))
  ST-Check 'unit (X-01): signals is a subset projection (invents nothing), every class catches its own planted line, and an unclassed line still survives in lines' (
    $xInvent -eq 0 -and @($xBlind).Count -eq 0 -and $null -ne $xObj2 -and
    @($xObj2.lines).Count -eq 8 -and (@($xObj2.lines) -contains $xL5))
  # End to end on the road the caller actually drives: a real subprocess, a side-effect-free
  # action (unmap = imgclick minus the click), and the refusal path must NOT be swallowed.
  $xImg = Join-Path $env:TEMP ('x01unmap' + [Guid]::NewGuid().ToString('N').Substring(0, 8) + '.png')
  [System.IO.File]::WriteAllText($xImg + '.map.txt',
    (@('origin_x=100', 'origin_y=200', 'scale=1', 'out_w=400', 'out_h=300', 'kind=rect') -join "`r`n"),
    (New-Object System.Text.UTF8Encoding($false)))
  # A-24, on the monitor's one-off `refusal-exit=-1` reading: -1 was NEVER an exit code. Both probes used to
  # start their code at -1 and only overwrite it on the success path, so a spawn that THROWS (the call
  # operator cannot resolve `powershell`, an access denial, a killed child) left the sentinel in the reading
  # and the gate went red as if the tool had returned -1. The sentinel now says what it is, the exception
  # text is kept for the reading line, and a probe that could not run is reported as not run - which is a
  # different fact from "the tool exited N", and the reason belongs in the same place the reason already
  # goes when the pre-flight says no child can be spawned at all ($script:PsChildOk).
  # A-24 gauge repair, correcting that attribution (measured in .cowork-temp/a24g-channel/ctrl-ps51.txt):
  # the sentinel was only ONE of two ways to print -1. On Windows PowerShell 5.1, once a redirected native
  # child writes to stderr the call itself is terminating AND the runtime rewrites `$LASTEXITCODE` to -1
  # before the catch runs (a seeded 42 reads back -1), so even a probe that assigned the code inside its
  # catch would have printed -1. The child's real code is unrecoverable through that channel; it is
  # recoverable through the runner below, which is why the repair relaxes EAP instead of only labelling
  # the sentinel. Both legs now share the runner, so stdout is what the JSON face parses and stderr is
  # counted in its own field instead of being dropped (unmap) or merged (refusal) as they each did before.
  $xSubLeg = & $cnpRun -ChildArgs @('unmap', $xImg, '10', '20', '--json')
  $xSubOut = $xSubLeg.out
  $xSubCode = $xSubLeg.code
  $xSubRan = $xSubLeg.ran
  $xSubWhy = $xSubLeg.why
  $xSubObj = $null
  $xSubWhy2 = ''
  try { $xSubObj = $xSubOut | ConvertFrom-Json } catch { $xSubObj = $null; $xSubWhy2 = $_.Exception.Message }
  $xSubEvidence = ''
  if ($xSubRan -and $null -eq $xSubObj) {
    $xSubEvidence = Write-JsonProbeEvidence -Label 'action-json-leg' -Stdout $xSubOut -Stderr $xSubLeg.err -Code ([string]$xSubCode) -Parsed $false -ParseWhy $xSubWhy2 -Dir $g23EvidenceDir -Source $g23SourceTag
  }
  $xSubTop = ''
  if ($null -ne $xSubObj) { $xSubTop = (@($xSubObj.PSObject.Properties.Name) | Sort-Object) -join ',' }
  $xNegLeg = & $cnpRun -ChildArgs @('click', '10', '10', '--to', 'DTX-NoSuchWindow-ZZ', '--json')
  $xNegOut = ($xNegLeg.out + "`n" + $xNegLeg.err)
  $xNegCode = $xNegLeg.code
  $xNegRan = $xNegLeg.ran
  $xNegWhy = $xNegLeg.why
  $xSubDump = Format-JsonProbeDump $xSubOut ($null -ne $xSubObj)
  Write-Output ('      action-json e2e: unmap-exit=' + [string]$xSubCode + ' unmap-ran=' + $xSubRan + ' keys=[' + $xSubTop + ']' +
    ' refusal-exit=' + [string]$xNegCode + ' refusal-ran=' + $xNegRan +
    ' refusal-is-text=' + ($xNegOut.StartsWith('ERROR:')) + ' child-stdout=' + $xSubDump + $(if ($xSubEvidence) { ' ' + $xSubEvidence } else { '' }))
  if (($xSubWhy -ne '') -or ($xNegWhy -ne '')) {
    # the one thing that used to be invisible: which leg could not be started, and what the runtime said.
    Write-Output ('      action-json e2e spawn failure: unmap=[' + $xSubWhy + '] refusal=[' + $xNegWhy + ']')
  }
  # A-24 gauge repair: the collection layer, named apart from every contract it feeds.
  # Owner criterion 3. A leg that could not be collected has no business being read as "the tool refused",
  # and before this repair four of these five legs seeded their exit code at -1 while the fifth could not
  # tell a refusal from a lost child at all. The contract gates below STILL require their own leg to have
  # run, so a collection failure reddens both layers on purpose - a contract gate that passed on an unread
  # child is the false green this card exists to remove. What this gate adds is the NAME of the first red:
  # collect red = the gauge broke, contract red with collect green = the product broke.
  # The literal 5 is a registration, not a convenience: add or drop a child probe and this goes red until
  # the pair list and the count are argued about in the same commit.
  $xCollectPairs = @(
    @('wins', $jsonPos), @('cursor', $jsonNeg), @('g14', $g14Child), @('unmap', $xSubLeg), @('refusal', $xNegLeg)
  )
  $xCollectRan = @($xCollectPairs | Where-Object { $_[1].ran }).Count
  $xCollectCode = @($xCollectPairs | Where-Object { $null -ne $_[1].code }).Count
  $xCollectAny = @($xCollectPairs | Where-Object { ($_[1].outCount + $_[1].errCount) -ge 1 }).Count
  $xCollectStdout = @($xCollectPairs | Where-Object { $_[1].outCount -ge 1 }).Count
  $xCollectFace = @()
  foreach ($xcp in $xCollectPairs) { $xCollectFace += ('[' + $xcp[0] + ' ' + [string]$xcp[1].outCount + '/' + [string]$xcp[1].errCount + ']') }
  Write-Output ('      child collection: legs=' + @($xCollectPairs).Count + ' ran=' + $xCollectRan +
    ' code-read=' + $xCollectCode + ' any-stream=' + $xCollectAny + ' stdout-stream=' + $xCollectStdout +
    ' (stdout/stderr per leg)=' + ($xCollectFace -join ''))
  if (-not $script:PsChildOk) {
    ST-Skip 'e2e (A-24g): every offline child probe reports its own collection - five legs ran, each read a real exit code from the child, each caught at least one stream and each left a stdout face to parse' ($script:PsChildWhy + ' - the checks spawn children through the call operator, so there is nothing to measure')
  } else {
  ST-Check 'e2e (A-24g): every offline child probe reports its own collection - five legs ran, each read a real exit code from the child, each caught at least one stream and each left a stdout face to parse' (
    (@($xCollectPairs).Count -eq 5) -and ($xCollectRan -eq 5) -and ($xCollectCode -eq 5) -and
    ($xCollectAny -eq 5) -and ($xCollectStdout -eq 5))
  }
  if (-not $script:PsChildOk) {
    ST-Skip 'contract (X-01): a real action subprocess with --json yields parseable JSON with the pinned four keys (unmap, side-effect-free) - and a refused action still yields ERROR + exit 1, never an envelope that hides the refusal' ($script:PsChildWhy + ' - the check spawns a child through the call operator, so there is nothing to measure')
  } else {
  ST-Check 'contract (X-01): a real action subprocess with --json yields parseable JSON with the pinned four keys (unmap, side-effect-free) - and a refused action still yields ERROR + exit 1, never an envelope that hides the refusal' (
    $xSubRan -and $xNegRan -and
    $xSubCode -eq 0 -and $xSubTop -ceq (Get-ActionJsonKeySet) -and
    @($xSubObj.lines).Count -ge 1 -and [int]$xSubObj.schemaVersion -eq 3 -and "$($xSubObj.command)" -eq 'unmap' -and
    $xNegCode -eq 1 -and $xNegOut.Contains('ERROR:') -and -not $xNegOut.Contains('"schemaVersion"'))
  }
  try { if (Test-Path -LiteralPath $xImg) { Remove-Item -LiteralPath $xImg -Force } } catch { }
  try { if (Test-Path -LiteralPath ($xImg + '.map.txt')) { Remove-Item -LiteralPath ($xImg + '.map.txt') -Force } } catch { }
  # G-23: whole-stream evidence, taken BEFORE any head is cut. Deliberately not a banner rule line: the
  # family census enumerates every banner and would report this section as a banner claimed by nobody.
  # The two shapes are planted here so the gate owns the counterexample the monitor measured by hand: both
  # printed heads end with the same ' (cut)' marker, so a head cannot tell a clean envelope from one with a
  # polluter glued after it - only the evidence file can. G-25 puts these planted files in a unique owned
  # directory; the check counts and removes only those files, never the shared evidence root.
  $g23Tok = 'TAIL-POLLUTER-' + ([Guid]::NewGuid().ToString('N')).Substring(0, 8)
  $g23Pad = '{"schemaVersion":3,"command":"plant","lines":[' + ((1..40 | ForEach-Object { '"line-' + $_ + '"' }) -join ',') + ']}'
  $g23CleanObj = $null
  try { $g23CleanObj = $g23Pad | ConvertFrom-Json } catch { $g23CleanObj = $null }
  $g23Dirty = $g23Pad + "`n" + $g23Tok
  $g23DirtyObj = $null
  $g23DirtyWhy = ''
  try { $g23DirtyObj = $g23Dirty | ConvertFrom-Json } catch { $g23DirtyObj = $null; $g23DirtyWhy = $_.Exception.Message }
  $g23CleanDump = Format-JsonProbeDump $g23Pad ($null -ne $g23CleanObj)
  $g23DirtyDump = Format-JsonProbeDump $g23Dirty ($null -ne $g23DirtyObj)
  $g23EvidenceFull = [System.IO.Path]::GetFullPath($g23EvidenceDir).TrimEnd('\')
  $g23TempFull = [System.IO.Path]::GetFullPath($env:TEMP).TrimEnd('\')
  $g23EvidenceParent = [System.IO.Path]::GetDirectoryName($g23EvidenceFull).TrimEnd('\')
  $g23EvidenceLeaf = [System.IO.Path]::GetFileName($g23EvidenceFull)
  $g23EvidenceRootOk = ($g23EvidenceParent -ieq $g23TempFull) -and
    $g23EvidenceFull.StartsWith($g23TempFull + '\', [System.StringComparison]::OrdinalIgnoreCase) -and
    ($g23EvidenceLeaf -ceq ('json-probe-evidence-' + [System.Diagnostics.Process]::GetCurrentProcess().Id))
  $g23OwnedDir = Join-Path $g23EvidenceDir ('g23-owned-' + [Guid]::NewGuid().ToString('N'))
  $g23OwnedFull = [System.IO.Path]::GetFullPath($g23OwnedDir).TrimEnd('\')
  $g23OwnedParent = [System.IO.Path]::GetDirectoryName($g23OwnedFull).TrimEnd('\')
  $g23OwnedLeaf = [System.IO.Path]::GetFileName($g23OwnedFull)
  $g23OwnedPathOk = $g23EvidenceRootOk -and ($g23OwnedParent -ieq $g23EvidenceFull) -and
    $g23OwnedLeaf.StartsWith('g23-owned-', [System.StringComparison]::Ordinal) -and
    $g23OwnedFull.StartsWith($g23EvidenceFull + '\', [System.StringComparison]::OrdinalIgnoreCase) -and
    -not (Test-Path -LiteralPath $g23OwnedFull)
  $g23OwnedCreated = $false
  if ($g23OwnedPathOk) {
    New-Item -ItemType Directory -Path $g23OwnedFull | Out-Null
    $g23OwnedCreated = Test-Path -LiteralPath $g23OwnedFull -PathType Container
  }
  # The synthetic evidence-shaped sentinel is outside the owned plant path. Check its hash after owned cleanup,
  # then remove only this exact fixture file so the test itself leaves no litter.
  $g23ForeignPath = Join-Path $g23EvidenceFull ('json-probe-plant-foreign-' + [Guid]::NewGuid().ToString('N') + '.txt')
  $g23ForeignFull = [System.IO.Path]::GetFullPath($g23ForeignPath)
  $g23ForeignParent = [System.IO.Path]::GetDirectoryName($g23ForeignFull).TrimEnd('\')
  $g23ForeignOutside = $g23EvidenceRootOk -and ($g23ForeignParent -ieq $g23EvidenceFull) -and
    -not $g23ForeignFull.StartsWith($g23OwnedFull + '\', [System.StringComparison]::OrdinalIgnoreCase) -and
    -not (Test-Path -LiteralPath $g23ForeignFull)
  $g23ForeignCreated = $false
  $g23ForeignHashBefore = ''
  $g23ForeignHashAfter = ''
  $g23HashFile = {
    param([string]$Path)
    $g23HashAlg = [System.Security.Cryptography.SHA256]::Create()
    try {
      return ([System.BitConverter]::ToString($g23HashAlg.ComputeHash([System.IO.File]::ReadAllBytes($Path)))).Replace('-', '')
    } finally { $g23HashAlg.Dispose() }
  }
  if ($g23ForeignOutside) {
    New-Item -ItemType Directory -Force -Path $g23EvidenceFull | Out-Null
    [System.IO.File]::WriteAllText($g23ForeignFull, ('JSON-PROBE-EVIDENCE label=plant-foreign parsed=false exit=1' + [Environment]::NewLine + 'synthetic G-25 sentinel' + [Environment]::NewLine), (New-Object System.Text.UTF8Encoding($false)))
    $g23ForeignCreated = Test-Path -LiteralPath $g23ForeignFull -PathType Leaf
    if ($g23ForeignCreated) { $g23ForeignHashBefore = & $g23HashFile $g23ForeignFull }
  }
  $g23Before = if ($g23OwnedCreated) { @(Get-ChildItem -LiteralPath $g23OwnedFull -Filter 'json-probe-plant-*' -File -ErrorAction SilentlyContinue).Count } else { -1 }
  $g23EvDesc = ''
  if ($g23OwnedCreated) {
    $g23EvDesc = Write-JsonProbeEvidence -Label 'plant-tail' -Stdout $g23Dirty -Stderr ('planted stderr noise ' + $g23Tok) -Code '0' -Parsed $false -ParseWhy $g23DirtyWhy -Dir $g23OwnedFull -Source $g23SourceTag
  }
  $g23EvPath = ($g23EvDesc -replace '^evidence=([^ ]+).*$', '$1')
  $g23EvText = ''
  if (Test-Path -LiteralPath $g23EvPath) { $g23EvText = [System.IO.File]::ReadAllText($g23EvPath) }
  $g23After = if ($g23OwnedCreated) { @(Get-ChildItem -LiteralPath $g23OwnedFull -Filter 'json-probe-plant-*' -File -ErrorAction SilentlyContinue).Count } else { -1 }
  Write-Output ('      G-23 plant: head-shapes=' + $g23CleanDump.EndsWith('(cut)') + '/' + $g23DirtyDump.EndsWith('(cut)') +
    ' token-in-head=' + $g23DirtyDump.Contains($g23Tok) + ' token-in-file=' + $g23EvText.Contains($g23Tok) +
    ' owned-files=' + $g23Before + '->' + $g23After + ' ' + $g23EvDesc)
  ST-Check 'unit (G-23): a tail polluter the printed head cannot tell apart still lands whole on disk - both heads end with the same cut marker, the tail token is absent from every head and present in the evidence file' (
    ($g23Pad.Length -gt 260) -and ($null -ne $g23CleanObj) -and ($null -eq $g23DirtyObj) -and
    ($g23CleanDump.EndsWith('(cut)')) -and ($g23DirtyDump.EndsWith('(cut)')) -and
    (-not $g23CleanDump.Contains($g23Tok)) -and (-not $g23DirtyDump.Contains($g23Tok)) -and
    ($g23EvText.Contains($g23Tok)) -and ($g23After -eq ($g23Before + 1)) -and
    ($g23EvText.Contains('stdout-sha256=')) -and ($g23EvText.Contains('stderr-sha256=')) -and
    ($g23EvText.Contains('exit=0')) -and ($g23EvText.Contains('entry=')) -and ($g23EvText.Contains('---- PARSE EXCEPTION ----')))
  # The second planted shape: diagnostics that only touch stderr must NOT move the trigger. The evidence
  # follows the parse verdict, so noise on the other stream cannot silently create or hide a file.
  $g23bWrote = 0
  if ($g23OwnedCreated -and $null -eq $g23CleanObj) {
    [void](Write-JsonProbeEvidence -Label 'plant-should-not-write' -Stdout $g23Pad -Stderr ('WARNING: noise only here ' + $g23Tok) -Code '0' -Parsed $false -ParseWhy '' -Dir $g23OwnedFull -Source $g23SourceTag)
    $g23bWrote = 1
  }
  $g23bFiles = if ($g23OwnedCreated) { @(Get-ChildItem -LiteralPath $g23OwnedFull -Filter 'json-probe-plant-should-not-write-*' -File -ErrorAction SilentlyContinue).Count } else { -1 }
  $g23dWrote = 0
  if ($g23OwnedCreated -and $null -eq $g23DirtyObj) {
    [void](Write-JsonProbeEvidence -Label 'plant-real-failure' -Stdout $g23Dirty -Stderr '' -Code '1' -Parsed $false -ParseWhy $g23DirtyWhy -Dir $g23OwnedFull -Source $g23SourceTag)
    $g23dWrote = 1
  }
  $g23dFiles = if ($g23OwnedCreated) { @(Get-ChildItem -LiteralPath $g23OwnedFull -Filter 'json-probe-plant-real-failure-*' -File -ErrorAction SilentlyContinue).Count } else { -1 }
  $g23Removed = 0
  if ($g23OwnedCreated -and $g23OwnedPathOk -and ([System.IO.Path]::GetDirectoryName($g23OwnedFull).TrimEnd('\') -ieq $g23EvidenceFull)) {
    foreach ($g23f in @(Get-ChildItem -LiteralPath $g23OwnedFull -Filter 'json-probe-plant-*' -File -ErrorAction SilentlyContinue)) {
      if ([System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($g23f.FullName)).TrimEnd('\') -ieq $g23OwnedFull) {
        try { Remove-Item -LiteralPath $g23f.FullName -Force; $g23Removed++ } catch { }
      }
    }
  }
  $g23Residue = if ($g23OwnedCreated) { @(Get-ChildItem -LiteralPath $g23OwnedFull -Filter 'json-probe-plant-*' -File -ErrorAction SilentlyContinue).Count } else { -1 }
  # Only the exact unique directory created above is eligible for removal, and only when empty. The shared
  # evidence root can contain genuine child-probe failures, so its existence and contents are not a verdict.
  $g23OwnedDirState = 'absent'
  if (Test-Path -LiteralPath $g23OwnedFull -PathType Container) {
    $g23OwnedLeft = @(Get-ChildItem -LiteralPath $g23OwnedFull -Force -ErrorAction SilentlyContinue).Count
    if ($g23OwnedLeft -eq 0) {
      try { Remove-Item -LiteralPath $g23OwnedFull -Force } catch { }
      $g23OwnedDirState = $(if (Test-Path -LiteralPath $g23OwnedFull) { 'still-there' } else { 'gone' })
    } else { $g23OwnedDirState = 'kept-with-' + $g23OwnedLeft + '-files' }
  }
  if ($g23ForeignCreated -and (Test-Path -LiteralPath $g23ForeignFull -PathType Leaf)) {
    $g23ForeignHashAfter = & $g23HashFile $g23ForeignFull
  }
  $g23ForeignPreserved = $g23ForeignCreated -and ($g23ForeignHashBefore.Length -eq 64) -and
    ($g23ForeignHashAfter -ceq $g23ForeignHashBefore) -and (Test-Path -LiteralPath $g23ForeignFull -PathType Leaf) -and $g23ForeignOutside
  $g23ForeignClean = $false
  if ($g23ForeignPreserved -and ($g23ForeignParent -ieq $g23EvidenceFull) -and
      ([System.IO.Path]::GetFileName($g23ForeignFull) -match '^json-probe-plant-foreign-[0-9a-f]{32}\.txt$')) {
    try { Remove-Item -LiteralPath $g23ForeignFull -Force; $g23ForeignClean = -not (Test-Path -LiteralPath $g23ForeignFull) } catch { }
  }
  Write-Output ('      G-23 trigger: parsed-clean=' + ($null -ne $g23CleanObj) + ' wrote-on-clean=' + $g23bWrote +
    ' files-on-clean=' + $g23bFiles + ' wrote-on-unparseable=' + $g23dWrote + ' files-on-unparseable=' + $g23dFiles +
    ' owned-planted-removed=' + $g23Removed + ' owned-residue=' + $g23Residue + ' owned-dir-state=' + $g23OwnedDirState +
    ' shared-root=' + (Test-Path -LiteralPath $g23EvidenceFull -PathType Container))
  ST-Check 'unit (G-23): stderr-only noise leaves stdout parseable and writes no evidence, an unparseable stdout does write it, and the planted files leave zero residue (the trigger is the parse verdict, not the presence of a second stream)' (
    ($null -ne $g23CleanObj) -and ($g23bWrote -eq 0) -and ($g23bFiles -eq 0) -and
    ($null -eq $g23DirtyObj) -and ($g23dWrote -eq 1) -and ($g23dFiles -eq 1) -and
    ($g23Removed -ge 2) -and ($g23Residue -eq 0) -and ($g23OwnedDirState -ceq 'gone'))
  Write-Output ('      G-25 cleanup: shared-root-contained=' + $g23EvidenceRootOk + ' owned-path=' + $g23OwnedPathOk + ' foreign-outside=' + $g23ForeignOutside +
    ' foreign-retained-same-sha=' + $g23ForeignPreserved + ' fixture-sentinel-removed=' + $g23ForeignClean +
    ' sha256=' + $g23ForeignHashBefore)
  ST-Check 'unit (G-25): planted evidence is contained in a unique owned path, cleanup leaves the foreign evidence-shaped sentinel byte-for-byte intact, then removes only that exact fixture sentinel' (
    $g23EvidenceRootOk -and $g23OwnedPathOk -and $g23OwnedCreated -and $g23ForeignOutside -and $g23ForeignCreated -and
    ($g23Residue -eq 0) -and ($g23OwnedDirState -ceq 'gone') -and $g23ForeignPreserved -and $g23ForeignClean)
  # The purity the monitor asked to keep: the formatter must stay two parameters in, one string out, with
  # no path built, no write call and no global read inside its own braces. Its name is assembled below:
  # the S-89 census counts every line that carries the literal token, so a scan that spells its own target
  # would inflate the consumer count it exists to pin (measured: spelling the name in the scan lines read
  # calls=8, spelling it once in the entry file's header comment read calls=5, both against 4 real sites).
  $g23pTok = 'Format-JsonProbe' + 'Dump'
  $g23pSigWant = 'function ' + $g23pTok + '([string]$Text, [bool]$Parsed) {'
  $g23SrcLines = @(Get-Content -LiteralPath $script:ToolEntryPath)
  $g23pStart = -1
  for ($g23i = 0; $g23i -lt $g23SrcLines.Count; $g23i++) {
    if (([string]$g23SrcLines[$g23i]).StartsWith('function ' + $g23pTok + '(')) { $g23pStart = $g23i; break }
  }
  $g23pEnd = -1
  if ($g23pStart -ge 0) {
    for ($g23j = $g23pStart + 1; $g23j -lt $g23SrcLines.Count; $g23j++) {
      if (([string]$g23SrcLines[$g23j]) -eq '}') { $g23pEnd = $g23j; break }
    }
  }
  $g23pBody = ''
  if ($g23pStart -ge 0 -and $g23pEnd -gt ($g23pStart + 1)) { $g23pBody = (@($g23SrcLines[($g23pStart + 1)..($g23pEnd - 1)]) -join "`n") }
  $g23pBad = @()
  foreach ($g23t in @('Write-Output', 'Write-Host', 'Write-Information', 'Set-Content', 'Add-Content', 'Out-File', 'New-Item', 'Join-Path', 'Get-Content', '[System.IO', '$script:')) {
    if ($g23pBody.Contains($g23t)) { $g23pBad += $g23t }
  }
  $g23pSig = if ($g23pStart -ge 0) { [string]$g23SrcLines[$g23pStart] } else { '' }
  Write-Output ('      G-23 purity: span=' + $g23pStart + '-' + $g23pEnd + ' bad-tokens=' + ($g23pBad -join ',') +
    ' returns=' + $g23pBody.Contains('return ') + ' sig=' + ($g23pSig -ceq $g23pSigWant))
  ST-Check 'lint (G-23): the json probe dump formatter stays a pure function - exactly two parameters, one returned string, and no write call, path build, file read or global reference inside its own braces' (
    ($g23pStart -ge 0) -and ($g23pEnd -gt ($g23pStart + 1)) -and (@($g23pBad).Count -eq 0) -and
    $g23pBody.Contains('return ') -and ($g23pSig -ceq $g23pSigWant))

  # B-6 on the text side: one producer, and it must reach the outlets that were chosen - a
  # label that exists only in the JSON would be invisible to the agents that read text.
  $utNoteMark = 'Get-UntrustedContent' + 'Note'
  $utWired = @()
  for ($ui = 0; $ui -lt $codeLines.Count; $ui++) {
    if ($ui -ge $j5ProdStart -and $ui -lt $j5ProdEnd) { continue }
    if ($codeLines[$ui] -match '^\s*#') { continue }
    if ($codeLines[$ui].Contains($utNoteMark)) { $utWired += ($ui + 1) }
  }
  $utTrustKey = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains('contentTrust = (Get-UntrustedContent' + 'Tag)') })
  ST-Check 'lint: the untrusted-content label has one producer, reaches BOTH outlets (text and every JSON envelope) and nothing else' (
    @($utWired).Count -eq 3 -and @($utTrustKey).Count -eq 2)
  ST-Check 'unit: the untrusted-text outlet set is a subset of real commands and excludes measurement-only reads' (
    (Test-UntrustedTextCommand 'wins') -and (Test-UntrustedTextCommand 'read-text') -and
    -not (Test-UntrustedTextCommand 'color-at') -and -not (Test-UntrustedTextCommand 'hash') -and
    -not (Test-UntrustedTextCommand 'cursor'))
  ST-Check 'unit: the content-trust tag is one fixed lowercase token (a consumer compares it, not reads it)' (
    (Get-UntrustedContentTag) -ceq 'untrusted-screen-text')
  # The ambiguity rule is the one safety property here that a live run would be badly placed
  # to test (it needs two cancel-shaped buttons in a real dialog), so the decision is a pure
  # function and the three shapes are pinned offline.
  $cnHitA = @{ Name = 'Cancel'; El = $null }
  # built from code points because a bare & inside the literal is the call operator to the
  # parser; and assembled char-by-char so the accelerator brackets are exactly one pair.
  $cnNameB = 'cancel' + [char]0x28 + [char]0x26 + 'C' + [char]0x29
  $cnHitB = @{ Name = $cnNameB; El = $null }
  $pick0 = Resolve-DialogCancelPick @()
  $pick1 = Resolve-DialogCancelPick @($cnHitA)
  $cnTwo = @($cnHitA, $cnHitB)
  $pick2 = Resolve-DialogCancelPick $cnTwo
  ST-Check 'unit: dialog-cancel - zero candidates fall back to Escape, one is pressed, two or more REFUSE' (
    $pick0.Action -eq 'escape' -and $pick1.Action -eq 'invoke' -and $pick1.Pick.Name -eq 'Cancel' -and
    $pick2.Action -eq 'refuse' -and $null -eq $pick2.Pick)
  ST-Check 'unit: a refusal names every candidate it could have guessed between' (
    $pick2.List.Contains("'Cancel'") -and $pick2.List.Contains("'$cnNameB'"))
  Write-Output ("      expect-verdict wiring sites: " + (Format-SourceLineList $evWire))
  $evPlant = "  throw `"`$verb OK but expectation NOT met: x`""
  ST-Check 'lint: the single-producer scan would catch a hand-written expectation tail' (
    -not $evPlant.Contains($evMark))
  # uia-tree takes [maxDepth] and hands it to Uia-Dump; the header must say which depth it
  # walked, or `uia-tree X 3` and `uia-tree X` print identical headers and a shallow read can
  # be mistaken for "this app exposes no controls" (the exact misread that cost a whole
  # investigation elsewhere). Teeth here are SOURCE-level (no live UIA case exists in the
  # suite - stated in the iteration log rather than pretended away).
  $uiDepthPat = 'via=$($rr.Via)' + ' depth=$depth'
  $uiDepthSite = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($uiDepthPat) })
  ST-Check 'lint: the uia-tree header reports the depth it actually walked' (@($uiDepthSite).Count -eq 1)

  # ---------- contract: a stamp that CLAIMS UTC must be UTC (v3.0.1, audit item 9) ----------
  # Two MANIFEST headings wrote (Get-Date) - local time - and then printed " UTC" after
  # it. A reader computing an age from that line is wrong by the whole UTC offset, and
  # the quarantine MANIFEST is exactly the document an agent trusts without re-checking.
  # Production lines only (the selftest body is skipped): this scan names both literals,
  # so scanning itself would flag its own declaration.
  $utcStamps = @()
  for ($uS = 0; $uS -lt $clCount; $uS++) {
    if ($uS -ge $j5ProdStart -and $uS -lt $j5ProdEnd) { continue }
    $uSL = [string]$codeLines[$uS]
    if ($uSL.Contains('ToString(' + [char]39 + 'yyyy-MM-dd HH:mm') -and $uSL.Contains('UTC') -and -not $uSL.Contains('ToUniversalTime')) { $utcStamps += ($uS + 1) }
  }
  ST-Check 'contract: no production line stamps local time under a UTC label' (@($utcStamps).Count -eq 0)
  if (@($utcStamps).Count -gt 0) { Write-Output ("      UTC-labelled local timestamps at line(s): $(Format-SourceLineList @($utcStamps))") }

  # ---------- v3.0.1 (audit #10/#11/#13/#24): resource hygiene, one check per claim ----------
  # These are the "a path with [ ] in it, a handle that does not fit, a stream nobody
  # closed" class. Each is asserted structurally where the fix is a code SHAPE (this call
  # inside that try) and behaviourally where a pure answer exists.
  $giRaw = @()
  for ($giI = 0; $giI -lt $clCount; $giI++) {
    if ($giI -ge $j5ProdStart -and $giI -lt $j5ProdEnd) { continue }
    $giL = [string]$codeLines[$giI]
    if ($giL -match '^\s*#') { continue }
    if ($giL -match 'Get-Item\s' -and -not $giL.Contains('Get-Item -LiteralPath')) { $giRaw += ($giI + 1) }
  }
  ST-Check 'lint: every production Get-Item is given a literal path (a user path with [ ] or * is a wildcard to the provider)' (
    @($giRaw).Count -eq 0)
  if (@($giRaw).Count -gt 0) { Write-Output "      bare Get-Item at line(s): $(Format-SourceLineList @($giRaw))" }
  $emptyNeedleErr = ''
  $emptyNeedleHits = -1
  $enLines = @([pscustomobject]@{ Text = 'ALPHA ONE'; X = 0; Y = 0; W = 10; H = 10 }, [pscustomobject]@{ Text = 'BETA TWO'; X = 0; Y = 1; W = 10; H = 1 })
  try { $emptyNeedleHits = Find-OcrHits $enLines '' } catch { $emptyNeedleErr = $_.Exception.Message }
  ST-Check 'unit: Find-OcrHits refuses an empty needle instead of matching every line (IndexOf("") is 0)' (
    ($emptyNeedleErr -like '*empty needle*') -and ($emptyNeedleHits -lt 0))
  $enOne = Find-OcrHits $enLines 'BETA'
  ST-Check 'unit: the same two lines still answer one hit for a real needle (the refusal did not eat the function)' (
    (@($enOne).Count) -eq 1)
  $ocrSlice = Get-FunctionSlice 'Invoke-OcrBitmap' $codeLines
  $ocrTryIdx = $ocrSlice.Text.IndexOf('try {')
  $ocrSaveIdx = $ocrSlice.Text.IndexOf('$src.Save(')
  $ocrFinIdx = $ocrSlice.Text.IndexOf('} finally')
  # Every marker below is ASSEMBLED by concatenation, the same way the older structural
  # lints do it: a check that quotes the exact text it hunts cannot be teeth-tested by a
  # global search-and-replace (the mutation edits the check too, and both stay green).
  $ocrDisposeMark = ('$ocrDisposables.Dispos' + 'e()')
  $ocrRemoveMark = ('Remove-Item -LiteralPath ' + '$tmp')
  ST-Check 'lint: the OCR temp file is written INSIDE the try and the WinRT stream and bitmap are disposed on the way out' (
    $ocrSlice.Found -and ($ocrTryIdx -ge 0) -and ($ocrSaveIdx -gt $ocrTryIdx) -and ($ocrFinIdx -gt $ocrSaveIdx) -and
    ($ocrSlice.Text.Contains($ocrDisposeMark)) -and ($ocrSlice.Text.Contains($ocrRemoveMark)))
  $cdpSlice = Get-FunctionSlice 'Invoke-CdpEval' $codeLines
  # The claim is not "the words $result and Ok=false appear somewhere in the function" -
  # they do four times on the normal paths. It is that the CATCH clause itself answers
  # through the contract, so the clause is sliced out and searched on its own.
  $cdpCatchTxt = ''
  $cdpCatchAt = $cdpSlice.Text.IndexOf('} catch {')
  if ($cdpCatchAt -ge 0) {
    $cdpFinAt = $cdpSlice.Text.IndexOf('} finally', $cdpCatchAt)
    if ($cdpFinAt -gt $cdpCatchAt) { $cdpCatchTxt = $cdpSlice.Text.Substring($cdpCatchAt, $cdpFinAt - $cdpCatchAt) }
  }
  $cdpCatchAssign = ('$result = @{ ' + 'Ok = $false')
  ST-Check 'lint: Invoke-CdpEval answers through the Ok/Error contract (the catch clause itself sets a refused verdict, the socket still always closes)' (
    $cdpSlice.Found -and ($cdpCatchTxt.Length -gt 20) -and ($cdpCatchTxt.Contains($cdpCatchAssign)) -and
    ($cdpSlice.Text.Contains('finally { $ws.Dispose() }')))
  $cdpNullMark = ('value=' + 'null')
  $cdpBlindMark = ('$($r.Value.' + 'Length) chars')
  $cdpJsonSlice = Get-FunctionSlice 'Invoke-CdpJson' $codeLines
  ST-Check 'lint: the non-JSON refusal states a size it can actually state (a null value says value=null, not an empty field)' (
    $cdpJsonSlice.Found -and ($cdpJsonSlice.Text.Contains($cdpNullMark)) -and (-not $cdpJsonSlice.Text.Contains($cdpBlindMark)))
  $tabSlice = Get-FunctionSlice 'Write-TabManifest' $codeLines
  $tabTryW = $tabSlice.Text.IndexOf('try {')
  $tabNewW = $tabSlice.Text.IndexOf('New-Object System.IO.StreamWriter')
  $tabFinW = $tabSlice.Text.IndexOf('} finally')
  $tabDisposeMark = ('$swMan.Dispos' + 'e()')
  ST-Check 'lint: the tab manifest writer is disposed in a finally (a half-written evidence file is worse than no file)' (
    $tabSlice.Found -and ($tabTryW -ge 0) -and ($tabNewW -gt $tabTryW) -and ($tabFinW -gt $tabNewW) -and
    ($tabSlice.Text.Contains($tabDisposeMark)))
  $hprSlice = Get-FunctionSlice 'Format-HandlePinReason' $codeLines
  $hprSites = 0
  for ($hprI = 0; $hprI -lt $clCount; $hprI++) {
    if ($hprI -ge $j5ProdStart -and $hprI -lt $j5ProdEnd) { continue }
    if (([string]$codeLines[$hprI]).Contains('Format-HandlePinReason $')) { $hprSites++ }
  }
  ST-Check 'lint: every handle-pin refusal line prints through the one formatter (three routes, one wording)' (
    $hprSlice.Found -and ($hprSites -eq 3))

}

# lib/selftest-expect-family.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1
# by A-14n (A-beta). Bodies are byte-identical to what the section carried, with three structural
# notes: the F-02 section travels inside the try/finally that contains it (a deeper-indented banner is
# not a run boundary, and cutting at one would lift the middle of a block out of the block); one
# banner of this family - the live --verify-timeout case - is nested inside a body that has not moved
# yet, so it stays in lib/selftest.ps1 and moves with that body; and the dialog-cancel wiring echo
# (left here by A-14m, physically inside this family's run) stays too, because it reads the
# hand-back names A-14l binds into the orchestration scope and a lifted family reads only published
# context.
#
# The expectation family: --verify-timeout parsing and forwarding, the patience each verdict names,
# B-1/B-2/B-3 (fold marker, handle pin, needle lists), autoexpect wiring, the fail-closed anchor, the
# verbatim expectation legs, every verify call site passing the patience, and the 7th positional
# argument that IS the occlusion gate switch.
function Invoke-SelftestFamily-ExpectFamily($Ctx) {
  # context handover (the one thing in this file above the lifted text that is not lifted text)
  $clCount = $Ctx['clCount']
  $codeLines = $Ctx['codeLines']
  $evWire = $Ctx['evWire']
  $j5ProdEnd = $Ctx['j5ProdEnd']
  $j5ProdStart = $Ctx['j5ProdStart']

  # ---------- unit: v1.5.3 --verify-timeout is parsed and forwarded ----------
  # Closes the '--verify 4s not parameterised' leftover: the parameter already
  # existed on Invoke-TypedVerify, the flag was never wired to it. Teeth follow
  # the --needle lesson - the assertions must be able to tell "parsed" from
  # "ignored", not merely "the command still ran".
  $vtOn = $null
  try { $vtOn = Split-Target @('--to', 'Notepad', '--needle', '--DTX-VERIFY', '--verify', '--verify-timeout', '9') } catch { }
  ST-Check 'unit: --verify-timeout value is parsed out of the payload' (
    $null -ne $vtOn -and $vtOn.VerifyTimeout -eq 9 -and $vtOn.Verify -eq $true)
  # the payload is a '--' sentinel fed through --needle (the --needle lesson): if
  # this flag ever stops being consumed, the sentinel is what goes red first - the
  # leftover '--verify-timeout' then hits the unknown-flag branch and the whole
  # call throws, and a half-eaten value would leave '9' in the text. Both are
  # caught here BEFORE anything is ever sent to a real window.
  ST-Check 'unit: --verify-timeout and its value never reach the typed text' (
    $null -ne $vtOn -and $vtOn.Words -notcontains '--verify-timeout' -and $vtOn.Words -notcontains '9' -and ($vtOn.Words -join ' ') -ceq '--DTX-VERIFY')
  $vtDef = $null
  try { $vtDef = Split-Target @('--to', 'Notepad', '--needle', '--DTX-VERIFY', '--verify') } catch { }
  ST-Check 'unit: --verify-timeout default stays 4s (no silent behaviour drift for existing callers)' (
    $null -ne $vtDef -and $vtDef.VerifyTimeout -eq 4)
  ST-Check 'unit: a -- payload without --verify-timeout is still typed verbatim' (
    $null -ne $vtDef -and ($vtDef.Words -join ' ') -ceq '--DTX-VERIFY')
  $vtBad = ''
  try { [void](Split-Target @('--verify-timeout')) } catch { $vtBad = $_.Exception.Message }
  ST-Check 'unit: --verify-timeout without a value throws' ($vtBad -like '--verify-timeout needs seconds*')
  $vtTxt = ''
  try { [void](Split-Target @('abc', '--verify-timeout', 'x')) } catch { $vtTxt = $_.Exception.Message }
  ST-Check 'unit: --verify-timeout rejects a non-numeric value instead of coercing it' ($vtTxt -like '*needs a number of seconds, got: x*')
  $vtLo = ''
  try { [void](Split-Target @('--verify-timeout', '0.2')) } catch { $vtLo = $_.Exception.Message }
  ST-Check 'unit: --verify-timeout below the 400ms poll floor is refused with a reason' ($vtLo -like '*must be >= 0.5*')
  # the sharp one: a flag name must never be eaten as the timeout value
  $vtFlag = ''
  try { [void](Split-Target @('--verify-timeout', '--to', 'Notepad', 'hi')) } catch { $vtFlag = $_.Exception.Message }
  ST-Check 'unit: --verify-timeout refuses to swallow the next FLAG as its value' (
    $vtFlag -like '*needs a number of seconds, got: --to*' -and $vtFlag -notlike '--to needs*')
  # 'type-in' has its own flag loop (it never goes through Split-Target), so its
  # parse is asserted separately. Both cases below throw DURING PARSING, before
  # any click or keystroke, so they are safe to run offline.
  $tiBad = ''
  try { Invoke-DesktopCommand 'type-in' @('10', '20', 'hello', '--verify-timout', '3') } catch { $tiBad = $_.Exception.Message }
  # J-06: type-in's refusal now comes from the one renderer (it used to hand-write its own),
  # so the anchors are the flag it mistyped and the list of what really reaches type-in -
  # still thrown during PARSING, before any click or keystroke.
  ST-Check 'unit: type-in refuses a mistyped --verify-timeout instead of typing it into the window' (
    $tiBad.Contains("unknown flag '--verify-timout' for 'type-in'") -and $tiBad.Contains('--verify-timeout') -and
    $tiBad.Contains('valid here:'))
  $tiNoVal = ''
  try { Invoke-DesktopCommand 'type-in' @('10', '20', 'hello', '--verify-timeout') } catch { $tiNoVal = $_.Exception.Message }
  ST-Check 'unit: type-in --verify-timeout without a value throws (and says so, not a silent 4s)' (
    $tiNoVal -like 'type-in: --verify-timeout needs seconds*')
  $tiPay = ''
  try { Invoke-DesktopCommand 'type-in' @('10', '20', '--verify-timeout', '0.2') } catch { $tiPay = $_.Exception.Message }
  ST-Check 'unit: type-in enforces the same 0.5s floor as type (one grammar, not two)' (
    $tiPay -like 'type-in: --verify-timeout must be >= 0.5*')

  # ---------- lint: v1.5.3 every verify call site passes the patience ----------
  # The offline units above prove the flag is PARSED; they cannot prove the parsed
  # value is HANDED OVER - dropping the third argument silently falls back to the
  # parameter default and every offline check stays green. This nails the shape of
  # the call itself. A bare call is "two arguments and no third", and that has to
  # be caught mid-line too (an assignment inside an if-block), so the test is
  # "has 2 args" AND NOT "has 3" rather than an end-of-line anchor.
  $vtArg2Pat = 'Invoke-TypedVerify' + '\s+\$\w+\s+\$\w+'
  $vtArg3Pat = 'Invoke-TypedVerify' + '\s+\$\w+\s+\$\w+\s+\$'
  $vtBare = New-Object System.Collections.ArrayList
  $vtFull = 0
  for ($i = 0; $i -lt $codeLines.Count; $i++) {
    $l = $codeLines[$i]
    if ($l -match 'SELFTEST-EXEMPT') { continue }
    if ($l -match '^\s*function\s') { continue }
    $has3 = ($l -match $vtArg3Pat)
    if (($l -match $vtArg2Pat) -and -not $has3) { [void]$vtBare.Add($i + 1) }
    if ($has3) { $vtFull++ }
  }
  ST-Check 'lint: no Invoke-TypedVerify call omits the timeout argument' ($vtBare.Count -eq 0)
  if ($vtBare.Count -gt 0) { Write-Output "      bare verify calls at line(s): $(Format-SourceLineList $vtBare)" }
  # two call sites exist today (type, type-in); a third is welcome but a drop is not
  ST-Check 'lint: both verify call sites pass a timeout argument' ($vtFull -ge 2)
  # the defaults themselves: 'don't change a default on the way past' is an
  # explicit instruction, so drift must be machine-caught, not review-caught
  $vtDefaults = 0
  for ($i = 0; $i -lt $codeLines.Count; $i++) {
    if ($codeLines[$i] -match '^\s*\$v(erifyTimeout|Timeout)\s*=\s*4\s*$') { $vtDefaults++ }
  }
  ST-Check 'lint: both --verify-timeout defaults are still the literal 4' ($vtDefaults -eq 2)
  # positive controls: neither pattern is vacuous, and the mid-line form - the one
  # the first draft of this lint missed - is what actually trips the bare pattern.
  # Built by concatenation: written plainly, these sample lines would be scanned
  # as real call sites and the lint would fail on its own test fixture.
  $vtName = 'Invoke-TypedVerify'
  $vtPlantBare = '$v = ' + $vtName + ' $t $x'
  $vtPlantMid = 'if ($p.Verify) { $ver = ' + $vtName + ' $target $text }'
  ST-Check 'lint: bare-call pattern detects planted violations (line-end and mid-line)' (
    ($vtPlantBare -match $vtArg2Pat) -and ($vtPlantBare -notmatch $vtArg3Pat) -and
    ($vtPlantMid -match $vtArg2Pat) -and ($vtPlantMid -notmatch $vtArg3Pat))
  $vtPlantFull = '$v = ' + $vtName + ' $t $x $p.VerifyTimeout'
  ST-Check 'lint: a planted full call trips neither the bare rule nor a false end' (
    ($vtPlantFull -match $vtArg3Pat) -and (-not (($vtPlantFull -match $vtArg2Pat) -and -not ($vtPlantFull -match $vtArg3Pat))))
  # passing a literal instead of the parsed value is the other way this regresses
  $vtPlantLit = '$v = ' + $vtName + ' $t $x 4'
  ST-Check 'lint: hardcoding the patience is refused too, not just dropping it' (
    ($vtPlantLit -match $vtArg2Pat) -and ($vtPlantLit -notmatch $vtArg3Pat))

  # ---------- unit: v1.5.7 "self-reported value" - the expect family names its patience ----------
  $evOk = Format-ExpectationVerdict $true 1.24 6.0 300 '' '' '' 'clicked'
  ST-Check 'unit: a satisfied expectation names the patience and interval it ran with' (
    $evOk.StartsWith('  + verified in 1.2 s') -and $evOk.Contains('patience 6s') -and $evOk.Contains('polled every 300 ms'))
  $evBad = Format-ExpectationVerdict $false 6.02 30.0 100 'Saved' 'not visible' 'whole anchored region' 'clicked'
  ST-Check 'unit: an unmet expectation says OF HOW MUCH patience, so --timeout cannot be silently ignored' (
    $evBad.Contains("clicked OK but expectation NOT met: 'Saved' not visible in whole anchored region") -and
    $evBad.Contains('after 6s of 30s') -and $evBad.Contains('patience 30s, polled every 100 ms'))
  # the printed number must be what the LOOP used: the clamp rewrites $intervalMs at the top
  # of Invoke-Expectation, so every return has to carry it out or the verdict lies.
  # the marker is assembled AND the count is exact: the first version wrote the literal
  # inline, so this very line matched itself (4 instead of 3) and a dropped `Timeout =`
  # still left 3 - the mutation came back green and that was the lint's fault, not the
  # code's (third time today a scan matched its own search string).
  $evCarryPat = 'Timeout = $timeoutSec;' + ' Interval = $intervalMs'
  $evCarry = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($evCarryPat) })
  # v3.0.0 EXPECTATION CHANGE - 3 -> 2, and the reason is a merge, NOT a loosening.
  # Pre-v3.0.0 Invoke-Expectation had three patience-carrying returns because the "expect"
  # and "expect-gone" successes were two separate return statements; the any-of/all-gone
  # lists (B-3) made them one AND-semantics return, so the literal now appears twice.
  # The invariant this check exists for is unchanged and still holds: EVERY return that can
  # be reached after waiting carries the patience and the clamped interval it ran with, and
  # the early "nothing asked" return never did and still does not. Verified, not assumed:
  # dropping `Timeout =` from either remaining return still turns this red.
  $evCarryExpect = 2
  ST-Check 'unit: every Invoke-Expectation return carries the patience/interval it ran with (exactly 2 since the v3.0.0 merge)' (@($evCarry).Count -eq $evCarryExpect)
  if (@($evCarry).Count -ne $evCarryExpect) { Write-Output "      returns carrying patience: $(@($evCarry).Count)" }
  ST-Check 'lint: both expect verdicts come from the one formatter (exactly 2 production sites)' (@($evWire).Count -eq 2)

  # ---------- unit + lint: v3.0.0 B-1/B-2/B-3 (expect evidence, handle pin, needle lists) ----------
  # B-1: the fold marker first, because splitting Get-FoldMarkerFromCounts out of
  # Get-OcrFoldMarker is what surfaced a SHIPPED defect: the partial-fold branch was
  # " [$$($folded.Count) of ...]" and `$$(` in a double-quoted string is neither an escape
  # nor a subexpression - it stringifies the ARRAY and appends a literal ".Count", so a
  # 2-of-5 fold printed "[lineA lineB.Count of 5 matched via confusable-fold ...]". Only the
  # all-folded branch was ever exercised (its corpus had exactly one hit) and that branch has
  # no interpolation, so the marker whose whole job is honesty was lying in the one shape no
  # check built. These cases build that shape.
  ST-Check 'unit: fold marker - no folds prints nothing' (
    (Get-FoldMarkerFromCounts 0 5) -eq '' -and (Get-FoldMarkerFromCounts 0 0) -eq '')
  ST-Check 'unit: fold marker - all-folded wording is unchanged from v1.5.2' (
    (Get-FoldMarkerFromCounts 5 5) -eq ' [matched via confusable-fold - not an exact read]')
  # the exact rendered line, not a substring: `-like '*confusable-fold*'` (the pre-v3.0.0
  # check) passed on the broken output, which is why "the phrase appears" is not a verdict.
  ST-Check 'unit: fold marker - the PARTIAL branch renders counts, not the hit list' (
    (Get-FoldMarkerFromCounts 2 5) -eq ' [2 of 5 matched via confusable-fold - not an exact read]')
  $foldCorpus = New-Object System.Collections.ArrayList
  for ($fk = 1; $fk -le 5; $fk++) {
    $fo = [pscustomobject]@{ Text = "QXHELL0123$fk"; X = 10; Y = 10; W = 80; H = 14 }
    if ($fk -le 2) { $fo | Add-Member -NotePropertyName Folded -NotePropertyValue $true }
    [void]$foldCorpus.Add($fo)
  }
  ST-Check 'unit: Get-OcrFoldMarker on a real 2-of-5 corpus agrees with the count renderer (one producer, both callers)' (
    (Get-OcrFoldMarker $foldCorpus) -eq (Get-FoldMarkerFromCounts 2 5) -and
    (Get-OcrFoldMarker $foldCorpus) -eq ' [2 of 5 matched via confusable-fold - not an exact read]')
  ST-Check 'unit: Get-OcrFoldMarker on exact hits prints nothing (the corpus is not all-folded)' (
    (Get-OcrFoldMarker @([pscustomobject]@{ Text = 'x' })) -eq '')

  # B-1: what a satisfied expectation now says out loud. Built from a result object, so the
  # shape is pinned offline; the live check that the real loop fills these keys is separate.
  $pfFull = Format-ExpectationProof @{ Matched = 'QXOK'; Rect = '(606,861,260x24)'; Centre = '736,873'; Hits = 3; Via = 'tiled(4)'; FoldedHits = 0; Polls = 2 }
  ST-Check 'unit: a satisfied --expect echoes the rect it read, where it would click, how it read it and how often' (
    $pfFull.Contains('matched=QXOK') -and $pfFull.Contains('at=(606,861,260x24)') -and
    $pfFull.Contains('centre=736,873') -and $pfFull.Contains('hits=3') -and
    $pfFull.Contains('via=tiled(4)') -and $pfFull.Contains('polls=2'))
  # a single hit must not print hits=1 (noise), and a gone-list success has no rect at all -
  # the absence is the honest output, not an empty at=().
  ST-Check 'unit: the proof line omits what did not happen (no hits=1, no empty at= for a gone-list)' (
    (Format-ExpectationProof @{ Rect = '(1,2,3x4)'; Hits = 1; Polls = 1 }).Contains('hits=') -eq $false -and
    (Format-ExpectationProof @{ Polls = 3 }) -eq ' polls=3')
  ST-Check 'unit: a folded expectation success carries the fold marker in its proof line' (
    (Format-ExpectationProof @{ Matched = 'A'; Rect = '(1,2,3x4)'; Hits = 2; FoldedHits = 1; Polls = 1 }) -like '*1 of 2 matched via confusable-fold*')
  ST-Check 'unit: Format-ExpectationProof on nothing-to-say prints the empty string, not a stray space' (
    (Format-ExpectationProof @{}) -eq '')
  # the retry geometry as ONE word, and it must be able to tell 1x from 2x from tiled - the
  # three-state shape Format-OcrRetryNote already established for miss messages.
  ST-Check 'unit: the via word distinguishes 1x, single 2x and tiled(n) - never a bare "retried"' (
    (Get-ExpectationVia $false $false 0) -eq '1x' -and (Get-ExpectationVia $true $false 1) -eq '2x' -and
    (Get-ExpectationVia $true $true 6) -eq 'tiled(6)')
  # missing keys must degrade to '1x', not abort: an absent hashtable key reads as $null, and
  # a [bool] parameter on $null is a conversion ERROR that would kill the command after the
  # action already worked (measured: this exact shape aborted a selftest run mid-way).
  ST-Check 'unit: the via word survives an absent Scaled/Tiled key instead of erroring the caller' (
    (Get-ExpectationVia $null $null $null) -eq '1x' -and (Get-ExpectationVia '' '' '') -eq '1x')
  # production-side anchor: before v3.0.0 the success return carried no Rect, so this red.
  # The marker is assembled because this very line would otherwise match its own search.
  $exRectPat = '$r.' + 'Rect ='
  $exRectSites = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($exRectPat) })
  ST-Check 'lint: Invoke-Expectation success actually populates a rect (production site, not a test fixture)' (@($exRectSites).Count -ge 1)
  Write-Output "      expect-evidence: rect-sites=$(@($exRectSites).Count)"

  # B-2: the handle pin. Pure comparison first - including the two shapes that would make a
  # pin useless if they were wrong: an EMPTY pin must mean "nobody asked" (Ok), never
  # "match nothing" (which would refuse every call), and a mismatch must name BOTH handles
  # so the reader can see which window the selector actually landed on.
  $pinH = [IntPtr]0x1F3A
  $pinOk = Test-HandlePin '' $pinH
  ST-Check 'unit: an absent handle pin passes and reports the window it saw (never "match nothing")' (
    $pinOk.Ok -and $pinOk.Expected -eq '' -and $pinOk.Actual -eq '0x1f3a' -and $pinOk.Reason -eq '')
  $pinHex = Test-HandlePin '0x1f3a' $pinH
  $pinDec = Test-HandlePin '7994' $pinH
  ST-Check 'unit: a handle pin accepts 0x-hex and decimal and normalizes both to one hex form' (
    $pinHex.Ok -and $pinDec.Ok -and $pinHex.Expected -eq '0x1f3a' -and $pinDec.Expected -eq '0x1f3a')
  $pinBad = Test-HandlePin '0x9999' $pinH
  ST-Check 'unit: a mismatched pin refuses and names both handles (the drift must be visible)' (
    -not $pinBad.Ok -and $pinBad.Reason -eq 'mismatch' -and $pinBad.Expected -eq '0x9999' -and $pinBad.Actual -eq '0x1f3a')
  $pinJunk = Test-HandlePin 'hwnd=123' $pinH
  ST-Check 'unit: a malformed pin is refused as invalid-format, quoting the raw token' (
    -not $pinJunk.Ok -and $pinJunk.Reason -eq 'invalid-format' -and $pinJunk.Expected -eq 'hwnd=123')
  # v3.0.1 (audit #24): the RIGHT shape and the WRONG range used to be different failures -
  # a 20-hex-digit pin matched the pattern and then died inside [Convert]::ToInt64 with a
  # raw OverflowException, so the flag whose whole job is a legible refusal printed a .NET
  # stack trace. Both directions are refused here, with the reason spelled out.
  $pinHugeHex = $null
  $pinHugeHexErr = ''
  try { $pinHugeHex = Test-HandlePin '0x1234567890abcdef1234' $pinH } catch { $pinHugeHexErr = $_.Exception.GetType().Name }
  ST-Check 'unit: an out-of-range hex handle pin is refused, not thrown as OverflowException' (
    ($pinHugeHexErr -ceq '') -and ($null -ne $pinHugeHex) -and (-not $pinHugeHex.Ok) -and
    ($pinHugeHex.Reason -ceq 'invalid-format') -and ("$($pinHugeHex.Hint)".Length -gt 0))
  $pinHugeDec = $null
  $pinHugeDecErr = ''
  # built, not written as a literal: a 23-digit run in this file is exactly what the
  # publication gate's LONG-HEX rule exists to question, and a fixture must not cost an
  # exemption (the same lesson as the app-name comment the v3.0.0 gate caught).
  $pinHugeDecIn = ('9' * 23)
  try { $pinHugeDec = Test-HandlePin $pinHugeDecIn $pinH } catch { $pinHugeDecErr = $_.Exception.GetType().Name }
  ST-Check 'unit: an out-of-range DECIMAL handle pin is refused the same way (both casts are guarded)' (
    ($pinHugeDecErr -ceq '') -and ($null -ne $pinHugeDec) -and (-not $pinHugeDec.Ok) -and
    ($pinHugeDec.Reason -ceq 'invalid-format') -and ("$($pinHugeDec.Hint)".Length -gt 0))
  ST-Check 'unit: the refusal formatter appends the hint only when there is one (three call sites print through it)' (
    ((Format-HandlePinReason @{ Reason = 'mismatch'; Hint = '' }) -ceq 'mismatch') -and
    ((Format-HandlePinReason @{ Reason = 'invalid-format'; Hint = 'too wide' }) -ceq 'invalid-format: too wide'))
  # parser-side: the flag must be refused where it is typed, naming the flag, before any
  # window resolution happens. (Written with try/catch on purpose: an earlier draft of this
  # very check was `($p.ExpectHandle -eq '') -or ($p.ExpectHandle -eq 'hwnd=123')`, which
  # passes whichever way the parser behaves - i.e. a check with no teeth at all.)
  $pinThrew = ''
  try { [void](Split-Target @('500', '600', '--to', 'X', '--expect-handle', 'hwnd=123') 'click') } catch { $pinThrew = "$($_.Exception.Message)" }
  ST-Check 'unit: --expect-handle refuses a non-handle value at the parser and names the flag' (
    $pinThrew -like '*--expect-handle*' -and $pinThrew -like '*0x*')
  $pinEmptyThrew = ''
  try { [void](Split-Target @('500', '600', '--expect-handle') 'click') } catch { $pinEmptyThrew = "$($_.Exception.Message)" }
  ST-Check 'unit: --expect-handle with no value is refused (it must not eat the next selector)' (
    $pinEmptyThrew -like '*--expect-handle needs*')
  $pinGood = Split-Target @('500', '600', '--to', 'X', '--expect-handle', '0x1f3a') 'click'
  ST-Check 'unit: --expect-handle keeps the handle token and does not leak it into the payload' (
    $pinGood.ExpectHandle -eq '0x1f3a' -and -not (@($pinGood.Words) -contains '0x1f3a') -and
    -not (@($pinGood.Words) -contains '--expect-handle'))
  # --expect-handle must be declared as a VALUE-consuming flag, or the central pre-strip in
  # Strip-OwnFlags validates the handle as a flag - the exact shape that ate `--needle
  # --DTXVT` in v1.5.7 and only went red on a --live round.
  $pinValueFlags = @('--expect-handle', '--expect-any', '--expect-any-gone')
  $pinVsShared = @($pinValueFlags | Where-Object { -not (@(Get-SharedFlagSet) -contains $_) })
  $pinVsValue = @($pinValueFlags | Where-Object { -not (@(Get-SharedValueFlagSet) -contains $_) })
  ST-Check 'lint: every new expect flag is in BOTH the shared set and the value-consuming set (error text and pre-strip cannot lie)' (
    @($pinVsShared).Count -eq 0 -and @($pinVsValue).Count -eq 0)
  # wiring, production only: a pin that is parsed but never reaches the resolver is the D-1
  # defect ("documented, parsed, unreachable") one layer down. Marker assembled to self-match.
  $pinWirePat = 'AlwaysActivate ' + '$p.ExpectHandle'
  $pinWire = @($codeLines | Where-Object { $_ -notmatch '^\s*#' -and $_.Contains($pinWirePat) })
  ST-Check 'lint: every canonical Resolve-Target call threads the handle pin through (>= 14 production sites)' (@($pinWire).Count -ge 14)
  # and the refusal must happen BEFORE activation, or the call that says "I refused" has
  # already moved the user's window.
  $pinFnStart = -1; $pinFnEnd = -1
  for ($pk = 0; $pk -lt $codeLines.Count; $pk++) {
    if ($codeLines[$pk] -match '^\s*function Resolve-Target\(' -and $pinFnStart -lt 0) { $pinFnStart = $pk }
    elseif ($pinFnStart -ge 0 -and $codeLines[$pk] -match '^\}$' -and $pk -gt $pinFnStart) { $pinFnEnd = $pk; break }
  }
  $pinBody = @()
  $pinAct = -1; $pinCheck = -1
  if ($pinFnStart -ge 0 -and $pinFnEnd -gt $pinFnStart) {
    for ($pk = $pinFnStart; $pk -lt $pinFnEnd; $pk++) {
      if ($codeLines[$pk].Contains('Activate-Win $w') -and $pinAct -lt 0) { $pinAct = $pk }
      if ($codeLines[$pk].Contains('Test-HandlePin $expectHandle $w.Handle') -and $pinCheck -lt 0) { $pinCheck = $pk }
    }
  }
  ST-Check 'lint: the handle pin is evaluated before Activate-Win, so a refusal never disturbs the desktop' (
    $pinFnStart -ge 0 -and $pinCheck -ge 0 -and $pinAct -gt $pinCheck)
  Write-Output "      handle pin: wire-sites=$(@($pinWire).Count) pin-line=$(Format-SourceLineList @($pinCheck + 1)) activate-line=$(Format-SourceLineList @($pinAct + 1))"

  # B-3: needle LISTS. The parsing is checked directly; the MERGE (single flags + list flags
  # into one assertion) is checked with Invoke-Expectation replaced in-process (the v1.5.9
  # ${function:...} technique this repo already allows for the autoexpect orchestration), because the
  # thing worth pinning is "what list reaches the matcher" - and that must not depend on a
  # real OCR round trip or on the desktop.
  $b3Orig = ${function:Invoke-Expectation}
  try {
    ${function:Invoke-Expectation} = { param($base, $pres, $gones, $region, $to, $iv, $ah)
      $script:B3Seen = @{ Present = @($pres); Gone = @($gones) }
      return @{ Ok = $true; Elapsed = 0.4; Timeout = $to; Interval = $iv; Polls = 1; Matched = 'A'; Rect = '(1,2,3x4)'; Centre = '2,3'; Hits = 1 }
    }
    $b3a = Split-Target @('10', '20', '--to', 'X', '--expect', 'A', '--expect-any', 'B,C') 'click'
    $null = Invoke-ActionExpectation $b3a $null 'clicked'
    $b3ListA = (@($script:B3Seen.Present) -join ',')
    $b3a2 = Split-Target @('10', '20', '--to', 'X', '--expect-gone', 'D', '--expect-any-gone', 'E,F') 'click'
    $null = Invoke-ActionExpectation $b3a2 $null 'clicked'
    $b3ListB = (@($script:B3Seen.Gone) -join ',')
    # AND across the two kinds: a caller that asks for both gets both lists, never one.
    $b3a3 = Split-Target @('10', '20', '--to', 'X', '--expect', 'A', '--expect-any-gone', 'G') 'click'
    $null = Invoke-ActionExpectation $b3a3 $null 'clicked'
    $b3Both = (@($script:B3Seen.Present).Count -eq 1 -and (@($script:B3Seen.Gone) -join ',') -eq 'G')
    # duplicates are collapsed (the same text from two flags is one assertion, not two OCR passes)
    $b3a4 = Split-Target @('10', '20', '--to', 'X', '--expect', 'A', '--expect-any', 'A') 'click'
    $null = Invoke-ActionExpectation $b3a4 $null 'clicked'
    $b3Dedup = (@($script:B3Seen.Present).Count -eq 1)
    $b3a5 = Split-Target @('10', '20', '--to', 'X') 'click'
    $script:B3Seen = $null
    $null = Invoke-ActionExpectation $b3a5 $null 'clicked'
    $b3Skipped = ($null -eq $script:B3Seen)
    ST-Check 'unit: single + list expectation flags merge into one needle list in order' (
      $b3ListA -eq 'A,B,C' -and $b3ListB -eq 'D,E,F' -and $b3Both -and $b3Dedup)
    ST-Check 'unit: a command with no expectation at all never reaches the matcher' ($b3Skipped)
    # the success line must carry the proof through the SHARED tail, not just the builder
    $b3Line = (Invoke-ActionExpectation (Split-Target @('10', '20', '--to', 'X', '--expect', 'A') 'click') $null 'clicked') -join ' '
    ST-Check 'unit: the shared expect tail prints the proof line (at=/centre=/polls=) after the verdict' (
      $b3Line.StartsWith('  + verified in 0.4 s') -and $b3Line.Contains('at=(1,2,3x4)') -and
      $b3Line.Contains('centre=2,3') -and $b3Line.Contains('polls=1') -and $b3Line.Contains('via=1x'))
  } finally {
    ${function:Invoke-Expectation} = $b3Orig
    $script:B3Seen = $null
  }
  # parsing shapes: trim, drop empty items, refuse an all-empty list, and --no-expect must
  # clear the new flags too (a stale list surviving --no-expect is a send-only escape that
  # still asserts, which is the opposite of what the flag promises).
  $b3p = Split-Target @('10', '20', '--to', 'X', '--expect-any', ' A, B,,C, ') 'click'
  ST-Check 'unit: --expect-any trims items and drops empty ones (a,b,, is not an empty-string assertion)' (
    (@($b3p.ExpectAny) -join ',') -eq 'A,B,C')
  $b3pOff = Split-Target @('10', '20', '--to', 'X', '--expect', 'A', '--expect-any', 'B', '--expect-gone', 'C', '--expect-any-gone', 'D', '--no-expect') 'click'
  ST-Check 'unit: --no-expect clears the single AND the list expectation flags' (
    $b3pOff.Expect -eq '' -and $b3pOff.ExpectGone -eq '' -and
    @($b3pOff.ExpectAny).Count -eq 0 -and @($b3pOff.ExpectAnyGone).Count -eq 0 -and $b3pOff.NoExpect)
  $b3Throw = ''
  try { [void](Split-Target @('10', '20', '--expect-any', ',,') 'click') } catch { $b3Throw = "$($_.Exception.Message)" }
  ST-Check 'unit: an --expect-any that reduces to nothing is refused (an assertion that cannot fail)' (
    $b3Throw -like '*--expect-any*non-empty*')
  $b3NoVal = ''
  try { [void](Split-Target @('10', '20', '--expect-any') 'click') } catch { $b3NoVal = "$($_.Exception.Message)" }
  ST-Check 'unit: --expect-any with no value is refused rather than swallowing the next token' (
    $b3NoVal -like '*--expect-any needs*')
  # a '--' leading list must still be reachable through --needle-style data flow: the value
  # is DATA, so the central pre-strip may not validate it as a flag (covered above by the
  # Get-SharedValueFlagSet lint; this pins the observable behaviour for one list flag).
  $b3Lead = Split-Target @('10', '20', '--expect-any', '--DTXA,--DTXB') 'click'
  ST-Check 'unit: --expect-any accepts a list whose items start with -- (they are data, not flags)' (
    (@($b3Lead.ExpectAny) -join ',') -eq '--DTXA,--DTXB')

  # ---------- unit: v1.5.9 P-1 autoexpect - needle derivation, orchestration, gate ----------
  # The v1.5.9 task order allows exactly this offline shape: "mock out the OCR result".
  # The function override below stands in for the screen-reading loop, so the skip logic,
  # both messages and the failure gate are behaviour-tested without a desktop. The
  # finally is load-bearing: a leaking mock would silently re-route every later OCR
  # expectation (including the --live section) through the fake.
  $anLast = Get-AutoExpectNeedle "first line`nsecond line`n  DTX tail for readback  `n`n"
  ST-Check 'unit: autoexpect needle is the LAST non-empty line, trimmed (not the first)' ($anLast -ceq 'DTX tail for readback')
  $anCap = Get-AutoExpectNeedle ("x`n" + ('A' * 40))
  ST-Check 'unit: autoexpect needle caps the payload tail at 24 chars' ($anCap.Length -eq 24 -and $anCap -ceq ('A' * 24))
  ST-Check 'unit: autoexpect needle of a whitespace-only payload is empty (readback skipped)' ((Get-AutoExpectNeedle "  `n`t`n") -ceq '')
  ST-Check 'unit: autoexpect needle of an empty payload is empty' ((Get-AutoExpectNeedle '') -ceq '')

  $aeMockSeen = New-Object System.Collections.ArrayList
  $aeMockReal = ${function:Invoke-Expectation}
  $aeReceiptSeen = New-Object System.Collections.ArrayList
  $aeReceiptReal = ${function:Get-PasteReceipt}
  $pAe = @{ Expect = ''; ExpectGone = ''; ExpectRegion = ''; NoExpect = $false; TimeoutSec = 6; IntervalMs = 300 }
  try {
    ${function:Invoke-Expectation} = { param($baseRect, $ex, $exGone, $exRegion, $to, $iv, $ah)
      [void]$aeMockSeen.Add(@{ Needle = $ex; PassedTo = $to; Iv = $iv })
      if ($script:aeMockOk) { return @{ Ok = $true; Elapsed = 0.4; Where = 'mock region'; Timeout = 6; Interval = 300 } }
      return @{ Ok = $false; Elapsed = 6.0; Where = 'mock region'; Timeout = 6; Interval = 300 }
    }
    # Get-PasteReceipt really captures the screen and walks a UIA tree, so the receipt
    # half of this gate is mocked too - an offline selftest must never touch the desktop.
    ${function:Get-PasteReceipt} = { param($t) [void]$aeReceiptSeen.Add('call'); return @{ H = 100; Lines = 1; Nodes = 2; Hash = 'mockhash'; Rect = @(0, 0, 10, 10); Occluded = 0.0; CoveredBy = '' } }
    $script:aeMockOk = $false
    [void]$aeMockSeen.Clear()
    $aeBad = Invoke-AutoPasteExpect $pAe $null 'DTXMOCKTAIL'
    ST-Check 'unit: autoexpect unreadable payload -> NOT ok, names the escape hatch and the patience it used' (
      $aeBad.Ran -and (-not $aeBad.Ok) -and $aeBad.Message.Contains('WARN: payload not visible in target after send') -and
      $aeBad.Message.Contains('pass --no-expect to accept send-only') -and $aeBad.Message.Contains('patience 6s') -and
      $aeBad.Message.Contains('polled every 300 ms') -and $aeBad.Message.Contains('autoexpect=11chars') -and
      $aeBad.Message.Contains('DO NOT resend blindly') -and $aeBad.Message.Contains('receipt-tried=verbatim-tail-only'))
    ST-Check 'unit: the autoexpect failure message does not echo the payload tail' (-not $aeBad.Message.Contains('DTXMOCKTAIL'))
    # v4.2.0 item 1: the verdict's EXIT must lead with verification, never with a resend.
    # Both halves are pinned by position, not by presence - "DO NOT resend" appearing
    # somewhere after a "please resend" would not be a fix.
    $aeIdxNoResend = $aeBad.Message.IndexOf('DO NOT resend blindly')
    $aeIdxVerify = $aeBad.Message.IndexOf('Verify first with read-text / uia-find / find-text')
    $aeIdxRetry = $aeBad.Message.IndexOf('only if verified absent')
    ST-Check 'unit: the autoexpect failure leads with "do not resend" + a verification route, and the retry comes last' (
      ($aeIdxNoResend -ge 0) -and ($aeIdxVerify -gt $aeIdxNoResend) -and ($aeIdxRetry -gt $aeIdxVerify))
    # short payload (no baseline): the SAME three v2.2.0 measurements still run, AFTER
    # only, and say so - a number without a "not a verdict" label would be read as one.
    ST-Check 'unit: the short-payload failure still reports the three receipt measurements, labelled AFTER-state and not a verdict' (
      $aeBad.Message.Contains('receipt-tried=verbatim-tail-only') -and
      $aeBad.Message.Contains('after-state: diag-skipped(no-target)') -and
      $aeBad.Message.Contains('AFTER-state only, not a verdict') -and
      $aeBad.Message.Contains('no baseline was taken'))
    ST-Check 'unit: the failure Receipt field carries the same numbers as the message (gate and caller cannot disagree)' (
      $aeBad.Receipt -ceq 'after-state: diag-skipped(no-target)')
    # long payload WITH a baseline: all three legs ran in the verdict and the refusal
    # prints what each measured (none-of-three detail), so "we looked" is visible.
    $aeBase = @{ H = 100; Lines = 1; Nodes = 2; Hash = 'aaaa1111bbbb2222'; Rect = @(0, 0, 10, 10); Occluded = 0.0; CoveredBy = '' }
    $script:aeMockOk = $false
    $aeLong = Invoke-AutoPasteExpect $pAe $null 'DTXMOCKTAIL' $aeBase 240
    ST-Check 'unit: a long-payload failure reports every receipt leg''s measured numbers instead of a bare "not visible"' (
      $aeLong.Ran -and (-not $aeLong.Ok) -and
      $aeLong.Message.Contains('receipt-tried=none-of-three') -and
      $aeLong.Message.Contains('uia nodes 2->2') -and
      $aeLong.Message.Contains('h 100->100 (needs +8)') -and
      $aeLong.Message.Contains('lines 1->1') -and
      $aeLong.Message.Contains('fold-threshold=200'))
    # that probe spent one receipt call of its own; hand the counter back to zero so the
    # baseline assertion below still measures ITS two calls (counters are per-assertion).
    [void]$aeReceiptSeen.Clear()
    $script:aeMockOk = $true
    [void]$aeMockSeen.Clear()
    $aeOk = Invoke-AutoPasteExpect $pAe $null 'DTXMOCKTAIL'
    ST-Check 'unit: autoexpect verified payload -> + verified line carrying the autoexpect tag and patience' (
      $aeOk.Ran -and $aeOk.Ok -and $aeOk.Message.StartsWith('  + verified in 0.4 s') -and
      $aeOk.Message.Contains('patience 6s') -and $aeOk.Message.Contains('polled every 300 ms') -and
      $aeOk.Message.Contains('autoexpect=11chars'))
    ST-Check 'unit: autoexpect polls the OCR loop exactly once per call, with the payload tail as needle' (
      @($aeMockSeen).Count -eq 1 -and "$($aeMockSeen[0].Needle)" -ceq 'DTXMOCKTAIL' -and
      $aeMockSeen[0].PassedTo -eq 6 -and $aeMockSeen[0].Iv -eq 300)
    [void]$aeMockSeen.Clear()
    $pNoExp = @{ Expect = ''; ExpectGone = ''; ExpectRegion = ''; NoExpect = $true; TimeoutSec = 6; IntervalMs = 300 }
    $pExplicit = @{ Expect = 'Given'; ExpectGone = ''; ExpectRegion = ''; NoExpect = $false; TimeoutSec = 6; IntervalMs = 300 }
    $pRegion = @{ Expect = ''; ExpectGone = ''; ExpectRegion = '1,2,30,40'; NoExpect = $false; TimeoutSec = 6; IntervalMs = 300 }
    $aeSkip1 = Invoke-AutoPasteExpect $pNoExp $null 'DTXMOCKTAIL'
    $aeSkip2 = Invoke-AutoPasteExpect $pExplicit $null 'DTXMOCKTAIL'
    $aeSkip3 = Invoke-AutoPasteExpect $pRegion $null 'DTXMOCKTAIL'
    $aeSkip4 = Invoke-AutoPasteExpect $pAe $null ''
    ST-Check 'unit: --no-expect / explicit --expect / --expect-region / empty needle all skip the readback' (
      @($aeMockSeen).Count -eq 0 -and (-not $aeSkip1.Ran) -and (-not $aeSkip2.Ran) -and (-not $aeSkip3.Ran) -and (-not $aeSkip4.Ran))
    # v3.0.1 (audit item 2, the one this round SHIPPED): the two skip gates enumerate the
    # expect flags by hand, and the v3.0.0 list form (--expect-any / --expect-any-gone)
    # was added to neither - so a call that already asserts an any-of list ALSO paid the
    # verbatim-tail readback and could fail on it. One producer now, both shapes.
    $pAny = @{ Expect = ''; ExpectGone = ''; ExpectRegion = ''; NoExpect = $false; TimeoutSec = 6; IntervalMs = 300; ExpectAny = @('A', 'B'); ExpectAnyGone = @() }
    $pAnyGone = @{ Expect = ''; ExpectGone = ''; ExpectRegion = ''; NoExpect = $false; TimeoutSec = 6; IntervalMs = 300; ExpectAny = @(); ExpectAnyGone = @('C') }
    [void]$aeMockSeen.Clear()
    $aeSkip5 = Invoke-AutoPasteExpect $pAny $null 'DTXMOCKTAIL'
    $aeSkip6 = Invoke-AutoPasteExpect $pAnyGone $null 'DTXMOCKTAIL'
    ST-Check 'unit: an --expect-any / --expect-any-gone list counts as an explicit expectation and skips the readback' (
      @($aeMockSeen).Count -eq 0 -and (-not $aeSkip5.Ran) -and (-not $aeSkip6.Ran))
    # the same gate guards the CHEAP half: a paste that already asserts must not pay for
    # a receipt baseline either. Asserted through the mock, not through the screen.
    [void]$aeMockSeen.Clear()
    $rbSkipAny = Get-PasteReceiptBaseline $pAny $null ('x' * 200)
    $rbRunPlain = Get-PasteReceiptBaseline $pAe $null ('x' * 200)
    ST-Check 'unit: the receipt baseline is skipped for an any-of expectation and still taken without one' (
      (@($aeReceiptSeen).Count -eq 1) -and ($null -eq $rbSkipAny) -and ($null -ne $rbRunPlain))
    try { Confirm-AutoExpect $aeBad; $aeGate = 'NO-THROW' } catch { $aeGate = $_.Exception.Message }
    ST-Check 'unit: the autoexpect gate throws a self-reporting FAIL on an unmet verdict' (
      $aeGate.Contains('autoexpect NOT met') -and $aeGate.Contains('patience 6s') -and $aeGate.Contains('autoexpect=11chars') -and
      $aeGate.Contains('pass --no-expect to accept send-only') -and $aeGate.Contains('DO NOT resend blindly'))
    $aeGateOk = 'NOT-RUN'
    try { Confirm-AutoExpect $aeOk; $aeGateOk = 'SILENT' } catch { $aeGateOk = 'THREW: ' + $_.Exception.Message }
    ST-Check 'unit: the autoexpect gate is silent on a met verdict' ($aeGateOk -ceq 'SILENT')
  } finally {
    ${function:Invoke-Expectation} = $aeMockReal
    ${function:Get-PasteReceipt} = $aeReceiptReal
  }

  # ---------- lint: v1.5.9 P-1 wiring (default-on must stay WIRED, not just defined) ----------
  $aeWire = @()
  for ($awi = 0; $awi -lt $codeLines.Count; $awi++) {
    if ($awi -ge $j5ProdStart -and $awi -lt $j5ProdEnd) { continue }
    if ($codeLines[$awi] -match '^\s*#') { continue }
    if ($codeLines[$awi].Contains('Invoke-AutoPasteExpect')) { $aeWire += ($awi + 1) }
  }
  ST-Check 'lint: paste AND paste-file both wire the autoexpect readback (exactly 3 sites: 1 def + 2 calls)' (@($aeWire).Count -eq 3)
  if (@($aeWire).Count -ne 3) { Write-Output "      autoexpect wiring sites: $(@($aeWire) -join ', ')" }
  # The skip decision must have ONE producer. Counting calls is not enough on its own:
  # a hand-written enumeration re-added somewhere else would leave the call count alone,
  # so the scan also fails any production line that chains -or through the flags again.
  $tewDef = -1
  $tewEnd = -1
  for ($ti = 0; $ti -lt $clCount; $ti++) {
    if ($ti -ge $j5ProdStart -and $ti -lt $j5ProdEnd) { continue }
    if ($tewDef -lt 0) { if (([string]$codeLines[$ti]) -match '^function Test-ExpectationGiven') { $tewDef = $ti }; continue }
    if ([string]$codeLines[$ti] -ceq '}') { $tewEnd = $ti; break }
  }
  $tewHand = @()
  $tewCalls = @()
  for ($ti = 0; $ti -lt $clCount; $ti++) {
    if ($ti -ge $j5ProdStart -and $ti -lt $j5ProdEnd) { continue }
    if ($tewDef -ge 0 -and $ti -ge $tewDef -and ($tewEnd -lt 0 -or $ti -le $tewEnd)) { continue }
    $tiLine = [string]$codeLines[$ti]
    if ($tiLine -match 'NoExpect\s+-or\s+\$p\.' -and $tiLine -match '\$p\.Expect\w*\s+-or') { $tewHand += ($ti + 1) }
    if ($tiLine.Contains('Test-ExpectationGiven $')) { $tewCalls += ($ti + 1) }
  }
  ST-Check 'lint: the "an expectation was already given" decision has one producer and no hand-run enumeration left' (
    ($tewDef -ge 0) -and ($tewEnd -gt $tewDef) -and (@($tewCalls).Count -eq 2) -and (@($tewHand).Count -eq 0))
  Write-Output ("      expectation-given producer: def=" + (Format-SourceLineRef ($tewDef + 1)) + " calls=" + (Format-SourceLineList $tewCalls) + " hand-run enumerations left=" + @($tewHand).Count)
  $aeNeedleSites = @()
  for ($awi = 0; $awi -lt $codeLines.Count; $awi++) {
    if ($awi -ge $j5ProdStart -and $awi -lt $j5ProdEnd) { continue }
    if ($codeLines[$awi] -match '^\s*#') { continue }
    if ($codeLines[$awi].Contains('Get-AutoExpectNeedle')) { $aeNeedleSites += ($awi + 1) }
  }
  ST-Check 'lint: both autoexpect call sites derive the needle from the payload (exactly 3 sites)' (@($aeNeedleSites).Count -eq 3)
  if (@($aeNeedleSites).Count -ne 3) { Write-Output "      needle derivation sites: $(@($aeNeedleSites) -join ', ')" }
  $aeGateSites = @()
  for ($awi = 0; $awi -lt $codeLines.Count; $awi++) {
    if ($awi -ge $j5ProdStart -and $awi -lt $j5ProdEnd) { continue }
    if ($codeLines[$awi] -match '^\s*#') { continue }
    if ($codeLines[$awi].Contains('Confirm-AutoExpect')) { $aeGateSites += ($awi + 1) }
  }
  ST-Check 'lint: both autoexpect call sites run the failure gate (exactly 3 sites: 1 def + 2 calls)' (@($aeGateSites).Count -eq 3)
  if (@($aeGateSites).Count -ne 3) { Write-Output "      gate wiring sites: $(@($aeGateSites) -join ', ')" }
  # search string assembled by concatenation: the scan line must not contain its own
  # pattern (the self-match shape that fed "at least N" lints three times in one day)
  $aeUsagePat = "throw 'usage: pas" + "te(-file)? \["
  $aeUsage = @()
  for ($awi = 0; $awi -lt $codeLines.Count; $awi++) {
    if ($awi -ge $j5ProdStart -and $awi -lt $j5ProdEnd) { continue }
    if ($codeLines[$awi] -match '^\s*#') { continue }
    if ($codeLines[$awi] -match $aeUsagePat) { $aeUsage += $codeLines[$awi] }
  }
  ST-Check 'lint: paste and paste-file usage lines list the expect family (default-on must be discoverable)' (
    @($aeUsage).Count -eq 2 -and @($aeUsage | Where-Object { $_.Contains('--expect') }).Count -eq 2 -and
    @($aeUsage | Where-Object { $_.Contains('--no-expect') }).Count -eq 2)

  # ---------- v3.1.0 (P-03): the expectation anchor is fail-closed for a lost target, and
  # the no-target case self-reports what it is actually waiting on ----------
  # Pre-fix, "gave --to but the window died before the wait" and "never gave a target"
  # both fell into the same silent whole-virtual-screen fallback that called itself
  # "whole anchored region" - an expectation answering from the whole screen is not an
  # anchored expectation at all, and the content guard has thrown on the same situation
  # all along. Now: lost target = refuse (Confirm-ExpectAnchor, one producer, callers
  # Invoke-ActionExpectation and Invoke-AutoPasteExpect); no target = still allowed, but
  # the verdict carries anchor=no-target (whole virtual screen) instead of the old
  # honest-sounding label.
  $exOcrReal = ${function:Find-OcrHitsScaled}
  $script:ex4Sentinel = 0
  try {
    ${function:Find-OcrHitsScaled} = { param($x, $y, $w, $h, $needle, $scale, $maxTiles, $noTile)
      $script:ex4Sentinel++
      throw 'ex4-sentinel: the OCR loop was reached (the anchor refusal did not run first)' }
    $ex4NoRectTarget = [pscustomobject]@{ Pid = 41998; Title = 'ex4-fake-gone'; Handle = [IntPtr]::Zero }
    $ex4P = @{ Expect = @('NEEDLE'); ExpectAny = @(); ExpectGone = @(); ExpectAnyGone = @(); ExpectRegion = $null; TimeoutSec = 0.3; IntervalMs = 100; MinLineDensity = 1.5 }
    $ex4Err = ''
    try { Invoke-ActionExpectation $ex4P $ex4NoRectTarget 'clicked' | Out-Null }
    catch { $ex4Err = "$($_.Exception.Message)" }
    $ex4AOk = ((($ex4Err -like '*expectation anchor*') -and ($ex4Err -like '*NOT waiting on the whole screen*')) -and ($script:ex4Sentinel -eq 0))
    ST-Check 'unit (P-03): an expectation whose target existed but whose rect is gone refuses with the anchor refusal before a single OCR poll happens (the content guard has failed this way all along; the silent whole-screen fallback was the lie)' (
      $ex4AOk)
    if (-not $ex4AOk) { Write-Output ("      P-03 unitA: err=[" + $ex4Err + "] sentinel=" + $script:ex4Sentinel) }
    ${function:Find-OcrHitsScaled} = { param($x, $y, $w, $h, $needle, $scale, $maxTiles, $noTile)
      return @{ Hits = @([pscustomobject]@{ X = 1; Y = 1; W = 8; H = 8 }); Lines = @('ex4-line'); Scaled = $false; Tiled = $false; TileCount = 0 } }
    $ex4B = Invoke-Expectation $null @('NEEDLE') @() $null 0.3 100
    ST-Check 'unit (P-03): no target at all still waits on the whole virtual screen, but the verdict now SAYS so - Where is exactly anchor=no-target (whole virtual screen), not the old whole-anchored-region label' (
      (($ex4B.Ok) -and ($ex4B.Where -ceq 'anchor=no-target (whole virtual screen)')))
    $ex4C = Invoke-Expectation $null @('NEEDLE') @() '5,5,50,50' 0.3 100
    ST-Check 'unit (P-03): no-target with --expect-region keeps the virtual-screen anchor NAMED in the verdict (anchor=no-target (whole virtual screen), region ... (anchor-relative))' (
      (($ex4C.Ok) -and ($ex4C.Where -like 'anchor=no-target (whole virtual screen), region 5,5,50x50 (anchor-relative)')))
    $ex4D = Invoke-Expectation @{ X = 0; Y = 0; W = 100; H = 100 } @() @() $null 0.3 100
    ST-Check 'unit (P-03): a real target rect keeps the historical wording - whole anchored region means the TARGET rect there, and that case did not drift' (
      (($ex4D.Ok) -and ($ex4D.Where -ceq 'whole anchored region')))
  } finally {
    ${function:Find-OcrHitsScaled} = $exOcrReal
  }

  # ---------- v3.1.0 (P-04): the verbatim expectation legs get the occlusion front gate ----------
  # v2.3.0 measured the false-accept on the receipt chain (a covered target's screen rect
  # reads the COVERER, so lines-changed "moved" on someone else's video). The verbatim
  # expect legs read the same kind of screen rect on every poll and had no gate at all.
  # The gate is same-source same-knob (Get-OcclusionVerdict + Get-PasteReceiptOcclusionMax,
  # shipped at 0): a covered anchor refuses the wait at once with exit 1; sampler failure
  # is fail-OPEN and self-reported through OccErr (registered limitation); no target
  # handle (the P-03 anchor=no-target case) has no occlusion semantics, so no gate there.
  $ex5OccReal = ${function:Get-OcclusionVerdict}
  $ex5FocReal = ${function:Format-OcclusionCovering}
  $ex5KnobReal = ${function:Get-PasteReceiptOcclusionMax}
  $ex5OcrReal = ${function:Find-OcrHitsScaled}
  $script:ex5OccCalls = 0
  $script:ex5OcrCalls = 0
  try {
    ${function:Format-OcclusionCovering} = { param($items, $checked) return @{ Items = @($items); Lines = @(); Summary = "pid=999 'ex5-coverer' (" + @($items).Count + " of " + $checked + " sample points)"; Top = $null } }
    ${function:Find-OcrHitsScaled} = { param($x, $y, $w, $h, $needle, $scale, $maxTiles, $noTile)
      $script:ex5OcrCalls++
      return @{ Hits = @([pscustomobject]@{ X = 1; Y = 1; W = 8; H = 8 }); Lines = @('ex5-line'); Scaled = $false; Tiled = $false; TileCount = 0 } }
    ${function:Get-OcclusionVerdict} = { param($x, $y, $w, $h, $handle, $grid) $script:ex5OccCalls++; return @{ Checked = 25; Mismatch = 0; Pct = 0.0; Covering = @(); Skipped = 0; Err = ''; Ms = 1.0 } }
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $ex5Clean = Invoke-Expectation @{ X = 0; Y = 0; W = 100; H = 100 } @('NEEDLE') @() $null 0.3 100 ([IntPtr]1)
    ST-Check 'unit (P-04): a clean anchor (occluded=0) passes the verbatim wait and the gate really sampled the anchor rect (the sampler runs before the first OCR poll)' (
      (($ex5Clean.Ok) -and ($script:ex5OccCalls -ge 1) -and ($script:ex5OcrCalls -ge 1) -and (-not $ex5Clean.OccErr)))
    ${function:Get-OcclusionVerdict} = { param($x, $y, $w, $h, $handle, $grid) $script:ex5OccCalls++; return @{ Checked = 25; Mismatch = 25; Pct = 100.0; Covering = @([pscustomobject]@{ Pid = 999; Samples = 25 }); Skipped = 0; Err = ''; Ms = 1.0 } }
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $ex5Err = ''
    try { Invoke-Expectation @{ X = 0; Y = 0; W = 100; H = 100 } @('NEEDLE') @() $null 0.3 100 ([IntPtr]1) | Out-Null }
    catch { $ex5Err = "$($_.Exception.Message)" }
    $ex5Leg2Ok = ((($ex5Err -like '*expect refused*') -and ($ex5Err -like '*occluded=100%*') -and ($ex5Err -like '*coveredBy=pid=999*')) -and ($script:ex5OcrCalls -eq 0))
    ST-Check 'unit (P-04): a covered anchor refuses the wait AT ONCE with expect refused: target occluded=N% coveredBy=... - and the refusal lands BEFORE the first OCR read of that poll (no wait-and-see; the coverer never gets to answer the needle)' (
      $ex5Leg2Ok)
    if (-not $ex5Leg2Ok) { Write-Output ("      P-04 leg2: err=[" + $ex5Err + "] occ-calls=" + $script:ex5OccCalls + " ocr-calls=" + $script:ex5OcrCalls) }
    ${function:Get-OcclusionVerdict} = { param($x, $y, $w, $h, $handle, $grid) $script:ex5OccCalls++; return @{ Checked = 0; Mismatch = 0; Pct = 0.0; Covering = @(); Skipped = 25; Err = 'ex5-sample-failed'; Ms = 1.0 } }
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $ex5Open = Invoke-Expectation @{ X = 0; Y = 0; W = 100; H = 100 } @('NEEDLE') @() $null 0.3 100 ([IntPtr]1)
    ST-Check 'unit (P-04): a failed occlusion sampler does NOT refuse (Err is not a rejection reason, same as the receipt gate) and the wait self-reports it through OccErr' (
      (($ex5Open.Ok) -and ($ex5Open.OccErr -ceq 'ex5-sample-failed') -and ($script:ex5OcrCalls -ge 1)))
    # leg 3 leaves a FAILED sampler mock on the wire (Err non-empty), and the gate fail-opens on
    # Err BEFORE comparing anything - so flipping the knob there is structurally invisible. Measured:
    # replacing the production knob with a literal 0 left this leg green. Put a real 100%-covered
    # verdict back, then move ONLY the knob and demand two outcomes from the same input.
    ${function:Get-OcclusionVerdict} = { param($x, $y, $w, $h, $handle, $grid) $script:ex5OccCalls++; return @{ Checked = 25; Mismatch = 25; Pct = 100.0; Covering = @([pscustomobject]@{ Pid = 999; Samples = 25 }); Skipped = 0; Err = ''; Ms = 1.0 } }
    ${function:Get-PasteReceiptOcclusionMax} = { return 100 }
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $ex5Knob = $null
    $ex5KnobOpenErr = ''
    try { $ex5Knob = Invoke-Expectation @{ X = 0; Y = 0; W = 100; H = 100 } @('NEEDLE') @() $null 0.3 100 ([IntPtr]1) }
    catch { $ex5KnobOpenErr = "$($_.Exception.Message)" }
    $ex5KnobPassed = (($null -ne $ex5Knob) -and $ex5Knob.Ok)
    # the OCR counter has to be read from the PASSING half - the refusing half throws before the
    # first read by design, so asserting it after the second call would pin nothing (measured).
    $ex5KnobOcrCalls = $script:ex5OcrCalls
    ${function:Get-PasteReceiptOcclusionMax} = $ex5KnobReal
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $ex5KnobErr = ''
    try { Invoke-Expectation @{ X = 0; Y = 0; W = 100; H = 100 } @('NEEDLE') @() $null 0.3 100 ([IntPtr]1) | Out-Null }
    catch { $ex5KnobErr = "$($_.Exception.Message)" }
    ST-Check 'unit (P-04): the gate compares against Get-PasteReceiptOcclusionMax - the SAME 100%-covered anchor passes at knob=100 and refuses at the production knob (a hardcoded zero cannot pass this)' (
      ($ex5KnobPassed) -and ($ex5KnobOcrCalls -ge 1) -and ($ex5KnobErr -like '*expect refused*'))
    if (-not (($ex5KnobPassed) -and ($ex5KnobOcrCalls -ge 1) -and ($ex5KnobErr -like '*expect refused*'))) { Write-Output ("      P-04 leg4: knob100-pass=" + $ex5KnobPassed + " knob100-err=[" + $ex5KnobOpenErr + "] knob100-ocr=" + $ex5KnobOcrCalls + " prod-refused=[" + $ex5KnobErr + "] occ-calls=" + $script:ex5OccCalls) }
    # ---------- F-02: the 7th positional argument IS the gate switch ------------------------
    # Invoke-Expectation's LAST parameter ($anchorHandle) is the only thing that turns the v3.1.0
    # P-04 occlusion front gate on; the body reads
    #   if (($null -ne $anchorHandle) -and (-not $anchorHandle.Equals([IntPtr]::Zero)))
    # so a call that forgets it does not fail, does not warn and does not refuse - it waits with
    # the coverer free to answer the needle, which is the exact false-accept P-04 exists to stop.
    # The pre-existing arity lint only catches TOO MANY arguments (Get-CallArgCount vs declared),
    # so "one short" was structurally invisible. Three arities on the SAME wire, with a 100%
    # covered anchor in place: handle -> refuse; nothing -> silently no gate (the defect);
    # explicit [IntPtr]::Zero -> silently no gate (the documented anchor=no-target case).
    # The behavioural half matters as much as the text count: a lint that counts arguments would
    # still be green if the parameter did nothing at all.
    $f2Rect5 = @{ X = 0; Y = 0; W = 100; H = 100 }
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $f2Six = $null; $f2SixErr = ''
    try { $f2Six = Invoke-Expectation $f2Rect5 @('NEEDLE') @() $null 0.3 100 }
    catch { $f2SixErr = "$($_.Exception.Message)" }
    $f2SixOcc = $script:ex5OccCalls; $f2SixOcr = $script:ex5OcrCalls
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $f2ZeroErr = ''
    try { $null = Invoke-Expectation $f2Rect5 @('NEEDLE') @() $null 0.3 100 ([IntPtr]::Zero) }
    catch { $f2ZeroErr = "$($_.Exception.Message)" }
    $f2ZeroOcc = $script:ex5OccCalls
    $script:ex5OccCalls = 0; $script:ex5OcrCalls = 0
    $f2SevenErr = ''
    try { $null = Invoke-Expectation $f2Rect5 @('NEEDLE') @() $null 0.3 100 ([IntPtr]1) }
    catch { $f2SevenErr = "$($_.Exception.Message)" }
    $f2SevenOcc = $script:ex5OccCalls
    Write-Output ('      F-02 arity behaviour: six(six-occ,ocr,err)=' + $f2SixOcc + ',' + $f2SixOcr + ',[' + $f2SixErr +
      '] zero-occ=' + $f2ZeroOcc + ' seven-occ=' + $f2SevenOcc + ' seven-err=[' + $f2SevenErr + ']')
    ST-Check 'unit (F-02): the anchor handle is load-bearing - same 100%-covered anchor, a handle refuses, NO handle silently skips the gate (occ-calls=0 and the needle is read off the coverer), an explicit [IntPtr]::Zero is the documented no-anchor case' (
      ($null -ne $f2Six) -and ($f2Six.Ok) -and ($f2SixErr -eq '') -and ($f2SixOcc -eq 0) -and ($f2SixOcr -ge 1) -and
      ($f2ZeroOcc -eq 0) -and ($f2ZeroErr -eq '') -and
      ($f2SevenOcc -ge 1) -and ($f2SevenErr -like '*expect refused*'))
    # The static half: every PRODUCTION call site must pass all seven (the two autoexpect/expect
    # legs), and the declaration itself must still have seven parameters - an eighth added here
    # without touching this check is a red, not a silent widening. Marker assembled at runtime:
    # the scanner's own source names the function it hunts (fifth occurrence of that family).
    $f2Mark = 'Invoke-' + 'Expectation '
    $f2SigMark = 'function Invoke-' + 'Expectation'
    $f2Sites = @(); $f2Offend = @(); $f2Decl = 0
    for ($f2i = 0; $f2i -lt $codeLines.Count; $f2i++) {
      if ($f2i -ge $j5ProdStart -and $f2i -lt $j5ProdEnd) { continue }
      $f2l = [string]$codeLines[$f2i]
      if ($f2l -match '^\s*#') { continue }
      if ($f2l.StartsWith($f2SigMark)) {
        # declared parameter count = comma-separated slots in the signature
        $f2Decl = (("$f2l" -split ',').Count)
        continue
      }
      $f2After = Get-CodeTailAfterMark $f2l $f2Mark
      if ($null -eq $f2After) { continue }
      $f2Sites += ($f2i + 1)
      $f2N = Get-CallArgCount $f2After
      if ($f2N -ne 7) { $f2Offend += ('' + ($f2i + 1) + '=' + $f2N) }
    }
    Write-Output ('      F-02 arity lint: sites=[' + ($f2Sites -join ',') + '] offenders=[' + ($f2Offend -join ',') + '] declared-params=' + $f2Decl)
    ST-Check 'lint (F-02): every production Invoke-Expectation call site passes all seven arguments (a missing anchor handle is a silent gate-off, and the >=2 site floor proves the scan is looking)' (
      @($f2Offend).Count -eq 0 -and @($f2Sites).Count -ge 2 -and $f2Decl -eq 7)
    # Teeth for the detector itself (a text counter that always answers 7 fails nothing):
    # the real production tail and a hand-stripped six-argument tail must read differently.
    $f2RealTail = '$base $presentList $goneList $p.ExpectRegion $p.TimeoutSec $p.IntervalMs $exHandle'
    $f2ShortTail = '$base $presentList $goneList $p.ExpectRegion $p.TimeoutSec $p.IntervalMs'
    $f2ZoneTail = '$base $presentList $goneList $p.ExpectRegion $p.TimeoutSec $p.IntervalMs ([IntPtr]::Zero)'
    Write-Output ('      F-02 counter: seven=' + (Get-CallArgCount $f2RealTail) + ' six=' + (Get-CallArgCount $f2ShortTail) +
      ' zero-literal=' + (Get-CallArgCount $f2ZoneTail))
    ST-Check 'unit (F-02): the arity counter reads 7 / 6 / 7 on the planted tails (a counter blind to a dropped argument would make the lint above decorative)' (
      (Get-CallArgCount $f2RealTail) -eq 7 -and (Get-CallArgCount $f2ShortTail) -eq 6 -and (Get-CallArgCount $f2ZoneTail) -eq 7)
  } finally {
    ${function:Get-OcclusionVerdict} = $ex5OccReal
    ${function:Format-OcclusionCovering} = $ex5FocReal
    ${function:Get-PasteReceiptOcclusionMax} = $ex5KnobReal
    ${function:Find-OcrHitsScaled} = $ex5OcrReal
  }

}

# lib/selftest-drag-press.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1
# by A-14o (A-beta). Bodies are byte-identical to what the section carried; the only channel to the
# orchestrator is the context object, and this family hands nothing back (measured: every name it
# computes is consumed inside these gates).
#
# The drag/press family: the drag mid-state gate (a drag that lands on its own origin must not read
# as a move), the pairing id that is HANDED OVER rather than re-read, and the landing guard that
# judges both endpoints before the press.
function Invoke-SelftestFamily-DragPress($Ctx) {
  # context handover (the one thing in this file above the lifted text that is not lifted text)
  $codeLines = $Ctx['codeLines']
  $gaCaseIdx = $Ctx['gaCaseIdx']
  $gaCases = $Ctx['gaCases']
  $j5ProdEnd = $Ctx['j5ProdEnd']
  $j5ProdStart = $Ctx['j5ProdStart']

  # ---------- v2.0.1 (P-3): the drag mid-state gate ----------
  # The whole risk of this feature is machine-wide state leaking out of a process, so
  # the DECISION is a pure truth table (measured button state in, action out) and is
  # pinned in BOTH directions: every cell has a "held" case and an "idle" case, because
  # a rule that only ever fires one way is not a rule.
  $p3WatchStray = Get-PressGate 'watchdog' 'wins' $true
  ST-Check 'unit: press gate - the entry watchdog releases a stray press for an ordinary command and names what it did' (
    $p3WatchStray.Release -and ($p3WatchStray.Warn -ceq 'released a button left down by a previous run'))
  $p3WatchUp = Get-PressGate 'watchdog' 'press-up' $true
  $p3WatchDrag = Get-PressGate 'watchdog' 'drag-to' $true
  ST-Check 'unit: press gate - press-up and drag-to are exempt from the entry watchdog (releasing first would destroy the state they act on and report about)' (
    (-not $p3WatchUp.Release) -and (-not $p3WatchDrag.Release) -and (-not $p3WatchUp.Refuse) -and (-not $p3WatchDrag.Refuse))
  $p3WatchIdle = Get-PressGate 'watchdog' 'wins' $false
  ST-Check 'unit: press gate - nothing pressed means the watchdog stays silent (no WARNING line on every ordinary call)' (
    (-not $p3WatchIdle.Release) -and ($p3WatchIdle.Warn -ceq ''))
  $p3DownHeld = Get-PressGate 'press-down' 'press-down' $true
  ST-Check 'unit: press gate - a second press-down while held is refused so DOWN/UP stay a 1:1 pair' (
    $p3DownHeld.Refuse -and $p3DownHeld.Reason.Contains('1:1 pair'))
  $p3DownIdle = Get-PressGate 'press-down' 'press-down' $false
  ST-Check 'unit: press gate - press-down on an idle button proceeds (and does not "release")' (
    (-not $p3DownIdle.Refuse) -and (-not $p3DownIdle.Release))
  $p3UpHeld = Get-PressGate 'press-up' 'press-up' $true
  $p3UpIdle = Get-PressGate 'press-up' 'press-up' $false
  ST-Check 'unit: press gate - press-up releases while held and REFUSES when nothing is down (a release that did not happen must never be reported as success)' (
    $p3UpHeld.Release -and $p3UpIdle.Refuse -and $p3UpIdle.Reason.Contains('not down'))
  $p3DragIdle = Get-PressGate 'drag-to' 'drag-to' $false
  $p3DragHeld = Get-PressGate 'drag-to' 'drag-to' $true
  ST-Check 'unit: press gate - drag-to refuses without a press and travels with one (offline half of "not a silent success")' (
    $p3DragIdle.Refuse -and $p3DragIdle.Reason.Contains('press-down') -and (-not $p3DragHeld.Refuse))
  $p3Bogus = Get-PressGate 'press-sideways' 'press-sideways' $false
  ST-Check 'unit: press gate - an unknown op refuses instead of returning a do-nothing verdict' ($p3Bogus.Refuse)

  # Wiring: one gate call per press op (no hand-inlined state tests in the handlers),
  # the entry watchdog called exactly once (process entry), the DOWN echo from one
  # producer, the trio in $known and OUT of $replayable (replay must never resurrect a
  # press state), and every --max-hold bound living in the flag table, not the handler.
  $p3Gate = 0; $p3Watch = 0; $p3Echo = 0; $p3Timer = 0
  $p3KnownLine = ''; $p3ReplLine = ''
  for ($p3i = 0; $p3i -lt $codeLines.Count; $p3i++) {
    if ($p3i -ge $j5ProdStart -and $p3i -lt $j5ProdEnd) { continue }
    if ($codeLines[$p3i] -match '^\s*#') { continue }
    if ($codeLines[$p3i].Contains('= Get-PressGate ')) { $p3Gate++ }
    if ($codeLines[$p3i].Contains('$pressWarn = Invoke-PressWatchdog ')) { $p3Watch++ }
    if ($codeLines[$p3i].Contains('"button is DOWN at ')) { $p3Echo++ }
    if ($codeLines[$p3i].Contains('= Wait-PressRelease ')) { $p3Timer++ }
    if ($codeLines[$p3i].Contains("`$known = @('click'")) { $p3KnownLine = $codeLines[$p3i] }
    if ($codeLines[$p3i].Contains("`$replayable = @('move'")) { $p3ReplLine = $codeLines[$p3i] }
  }
  ST-Check 'lint: the press trio routes every decision through one gate, one entry watchdog and one DOWN echo (no second copy of the mid-state rule)' (
    ($p3Gate -eq 4) -and ($p3Watch -eq 1) -and ($p3Echo -eq 1) -and ($p3Timer -eq 1))
  ST-Check 'lint: press-down/drag-to/press-up are script steps but never replayable commands' (
    ($p3KnownLine.Contains("'press-down'")) -and ($p3KnownLine.Contains("'drag-to'")) -and ($p3KnownLine.Contains("'press-up'")) -and
    (-not $p3ReplLine.Contains('press-down')) -and (-not $p3ReplLine.Contains('drag-to')) -and (-not $p3ReplLine.Contains('press-up')))
  # The measurement itself is a gate: [Windows.Forms.MouseButtons]::Buttons is an ENUM
  # type and the member does not exist, so the naive form returns NOTHING - every press
  # then reads "not down" and the trio degrades into permanent refusals plus a watchdog
  # that never fires (measured 2026-10-01 with the button physically held down).
  $p3Reader = 0; $p3ReaderBad = 0
  for ($p3j = 0; $p3j -lt $codeLines.Count; $p3j++) {
    if ($p3j -ge $j5ProdStart -and $p3j -lt $j5ProdEnd) { continue }
    if ($codeLines[$p3j] -match '^\s*#') { continue }
    if ($codeLines[$p3j].Contains('Control]::MouseButtons')) { $p3Reader++ }
    if ($codeLines[$p3j].Contains('MouseButtons]::Buttons')) { $p3ReaderBad++ }
  }
  ST-Check 'lint: the press-state reader is the one form that actually measures (no silently-empty MouseButtons::Buttons)' (
    ($p3Reader -eq 1) -and ($p3ReaderBad -eq 0))
  # Watchdog 1 must be armed NATIVELY. A PowerShell scriptblock marshalled as a
  # System.Threading.Timer callback kills the process (first live round, 2026-10-01:
  # press-down died with exit code 2 having printed only its DOWN echo, so the button
  # stayed down and the next check in the same round - drag-to's refusal - saw a press
  # that nobody had asked for). A dead process is the one thing a deadline watchdog
  # cannot be, so the deadline lives in DT.ArmLeftUpHold and PS only reads the flag.
  $p3Native = 0; $p3PsTimer = 0
  for ($p3k = 0; $p3k -lt $codeLines.Count; $p3k++) {
    if ($p3k -ge $j5ProdStart -and $p3k -lt $j5ProdEnd) { continue }
    if ($codeLines[$p3k] -match '^\s*#') { continue }
    if ($codeLines[$p3k].Contains('::ArmLeftUpHold(')) { $p3Native++ }
    if ($codeLines[$p3k].Contains('New-Object System.Threading.Timer')) { $p3PsTimer++ }
  }
  ST-Check 'lint: the hold deadline is armed natively, never by a marshalled PowerShell timer callback (that kills the process and leaves the button down)' (
    ($p3Native -eq 1) -and ($p3PsTimer -eq 0))
  Write-Output ("      press hold arming: native=$p3Native ps-timer=$p3PsTimer reader=$p3Reader/$p3ReaderBad")
  Write-Output ("      press trio: gate=$p3Gate watchdog=$p3Watch echo=$p3Echo hold-wait=$p3Timer")
  # ---------- v2.2.0 (P3-6 hardening): the pairing id is HANDED OVER, never rebuilt -------
  # The whole point of the change is that a release noticed by a process that did not press
  # cannot invent the id. These four cases are the shape of that rule; the live pairing
  # contract cannot see the difference (it passes either way today), so the teeth live here.
  $p6A = Format-PressReleaseLine 'p777-1' 'p888-1' 'max-hold'
  ST-Check 'unit: press release line - an id the CALLER hands over beats whatever this process remembers, and says it came from the caller (the party that notices a release is usually not the party that pressed)' (
    $p6A.Contains('id=p777-1 ') -and $p6A.Contains('cause=max-hold') -and $p6A.Contains('id-source=caller'))
  $p6B = Format-PressReleaseLine '' 'p888-1' 'max-hold'
  ST-Check 'unit: press release line - with nothing handed over it falls back to this process id and LABELS that honestly (id-source=process)' (
    $p6B.Contains('id=p888-1 ') -and $p6B.Contains('id-source=process'))
  $p6C = Format-PressReleaseLine '' '' 'external'
  ST-Check 'unit: press release line - an unattributable release STILL writes a line and calls itself out, instead of the old silent skip that left a DOWN dangling with no trace at all' (
    $p6C.Contains('id-source=none') -and $p6C.Contains('ON PURPOSE') -and $p6C.Contains('cause=external'))
  $p6D = Format-PressReleaseLine 'p1-1' '' 'press-up'
  ST-Check 'unit: press release line - the cause is carried verbatim through the single producer (a hardcoded cause would make every release look like a deadline)' (
    $p6D.Contains('cause=press-up') -and (-not $p6D.Contains('cause=max-hold')))
  $p6Def = 0; $p6InProducer = $false; $p6Outside = 0; $p6Sites = 0; $p6Explicit = 0
  for ($p6j = 0; $p6j -lt $codeLines.Count; $p6j++) {
    if ($p6j -ge $j5ProdStart -and $p6j -lt $j5ProdEnd) { continue }
    if ($codeLines[$p6j].StartsWith('function Format-PressReleaseLine')) { $p6Def++; $p6InProducer = $true; continue }
    if ($p6InProducer -and ($codeLines[$p6j] -match '^(function |ST-Check )')) { $p6InProducer = $false }
    if ($codeLines[$p6j] -match '^\s*#') { continue }
    if ((-not $p6InProducer) -and $codeLines[$p6j].Contains(('button=' + 'UP'))) { $p6Outside++ }
    if ($codeLines[$p6j].Contains('Close-PressHold @(') -or $codeLines[$p6j].Contains('Close-PressHold $prLog')) { $p6Sites++ }
    if ($codeLines[$p6j].Contains(('Close-PressHold $prLog ' + '$prId'))) { $p6Explicit++ }
  }
  ST-Check 'lint: the UP pairing line is spelled by exactly one producer function and nowhere else in the tool (three copies used to write it, and only one could be right about the id)' (
    ($p6Def -eq 1) -and ($p6Outside -eq 0))
  if ($p6Outside -ne 0) { Write-Output "      button=UP text sites outside the producer: $p6Outside (expected 0)" }
  ST-Check 'lint: all four Close-PressHold call sites pass an id argument, and exactly one of them passes the id it issued (the three cross-process ones pass empty on purpose and get labelled, never skipped)' (
    ($p6Sites -eq 4) -and ($p6Explicit -eq 1))

  # ---------- v3.1.0 (P-01): drag's landing guard - both endpoints, judged before the press ----------
  # drag was the only command whose comment promised the family guard wiring while its body
  # ran none of the landing check (the F-00-A lint above is the promise-side tooth; this
  # block pins the fix side). drag is the only two-point command, so the check must run
  # TWICE - start then end - and both verdicts must exist BEFORE mouse-down: refusing after
  # the press would drop the drag somewhere along a path nobody approved. The mouse layer is
  # static ([DT]::) and cannot be mocked, so every offline path here aborts before
  # SetCursorPos by construction: the reject paths throw inside the check itself, and the
  # accept-side mock throws a sentinel at Get-ExpectChangeBaseline, the step that would
  # otherwise lead into the press - which is also what keeps every MUTANT of this block safe
  # to run on a real desktop.
  $dgIdx = & $gaCaseIdx 'drag'
  # v4.4.0 (A-15 pen 2): drag's body is a handler now. What is judged is still FILE order, so every range
  #    of the command is walked in order and the first mouse-down line seen anywhere is the boundary.
  $dgHits = @(); $dgLdown = -1
  foreach ($dgRg in @(Get-CommandCodeRanges $codeLines 'drag')) {
    for ($dgi = [int]$dgRg[0]; $dgi -lt [int]$dgRg[1]; $dgi++) {
      if ($codeLines[$dgi] -match '^\s*#') { continue }
      if (($codeLines[$dgi].Contains('MOUSE_LDOWN')) -and ($dgLdown -lt 0)) { $dgLdown = $dgi }
      if ($codeLines[$dgi].Contains('Invoke-HitWindowCheck')) { $dgHits += $dgi }
    }
  }
  ST-Check 'lint (P-01): drag passes BOTH endpoints through the landing check before the mouse-down line (exactly 2 calls, start coords then end coords; a drag variant that skips one is this family again)' (
    ((@($dgHits).Count -eq 2) -and ($dgLdown -gt $dgHits[1]) -and
    ($codeLines[$dgHits[0]].Contains('$x1 $y1')) -and ($codeLines[$dgHits[1]].Contains('$x2 $y2'))))
  $dgHwcReal = ${function:Invoke-HitWindowCheck}
  $dgRtReal = ${function:Resolve-Target}
  $dgLaReal = ${function:Log-Action}
  $dgEcbReal = ${function:Get-ExpectChangeBaseline}
  $script:dgGuardCalls = New-Object System.Collections.ArrayList
  $script:dgLogCalls = New-Object System.Collections.ArrayList
  $dgFakeTarget = [pscustomobject]@{ Pid = 41999; Title = 'dg-fake-target'; Handle = [IntPtr]::Zero; Left = 0; Top = 0; W = 100; H = 100 }
  try {
    ${function:Resolve-Target} = { param($sel, $force, $always, $eh) return $dgFakeTarget }
    ${function:Log-Action} = { param($la, $detail, $cn) [void]$script:dgLogCalls.Add("$detail") }
    ${function:Get-ExpectChangeBaseline} = { param($pp, $tt) throw 'dg-sentinel: the accept path was reached without the landing checks (guards did not run first)' }
    ${function:Invoke-HitWindowCheck} = { param($x, $y, $tgt, $enforce, $allow)
      [void]$script:dgGuardCalls.Add(@($x, $y))
      if ($x -ge 4000) { throw "landing guard: point ($x,$y) is OUTSIDE target window (unit mock) visible rect - action NOT sent." } }
    $dgErrA = ''
    try { Invoke-DesktopCommand 'drag' @('10', '10', '4000', '4000', '--to', 'dg-fake') | Out-Null }
    catch { $dgErrA = "$($_.Exception.Message)" }
    ST-Check 'unit (P-01): drag judges the start point, then the end point, and refuses on the END point before any audit line exists (a refused drag logs nothing - the same contract the one-point commands run)' (
      (($dgErrA -like '*landing guard*') -and ($dgErrA -like '*action NOT sent*')) -and
      ((@($script:dgGuardCalls).Count -eq 2)) -and
      (($script:dgGuardCalls[0][0] -eq 10) -and ($script:dgGuardCalls[0][1] -eq 10)) -and
      (($script:dgGuardCalls[1][0] -eq 4000) -and ($script:dgGuardCalls[1][1] -eq 4000)) -and
      ((@($script:dgLogCalls).Count -eq 0)))
    [void]$script:dgGuardCalls.Clear(); [void]$script:dgLogCalls.Clear()
    ${function:Invoke-HitWindowCheck} = { param($x, $y, $tgt, $enforce, $allow)
      [void]$script:dgGuardCalls.Add(@($x, $y))
      if ($x -ge 4000) { throw "landing guard: point ($x,$y) is OUTSIDE target window (unit mock) visible rect - action NOT sent." } }
    $dgErrB = ''
    try { Invoke-DesktopCommand 'drag' @('5000', '5000', '60', '60', '--to', 'dg-fake') | Out-Null }
    catch { $dgErrB = "$($_.Exception.Message)" }
    ST-Check 'unit (P-01): drag refuses at the START point with the end point never judged and the audit log untouched (the refusal comes before the drag exists, not after it)' (
      (($dgErrB -like '*landing guard*') -and ($dgErrB -like '*action NOT sent*')) -and
      ((@($script:dgGuardCalls).Count -eq 1)) -and (($script:dgGuardCalls[0][0] -eq 5000)) -and
      ((@($script:dgLogCalls).Count -eq 0)))
    [void]$script:dgGuardCalls.Clear(); [void]$script:dgLogCalls.Clear()
    ${function:Invoke-HitWindowCheck} = $dgHwcReal
    $dgErrC = ''
    $dgOut = New-Object System.Collections.ArrayList
    try { Invoke-DesktopCommand 'drag' @('10', '10', '4000', '4000', '--to', 'dg-fake') | ForEach-Object { [void]$dgOut.Add("$_") } }
    catch { $dgErrC = "$($_.Exception.Message)" }
    $dgE2eOk = ((($dgErrC -like '*landing guard*') -and ($dgErrC -like '*action NOT sent*') -and ($dgErrC -like '*allow-outside*')) -and
      ((@($script:dgLogCalls).Count -eq 0)) -and
      ((@($dgOut | Where-Object { $_ -like 'hit-window:*' }).Count -ge 1)) -and
      ((@($dgOut | Where-Object { $_ -like '*inside-target=no*' }).Count -ge 1)))
    ST-Check 'e2e (P-01): drag 10 10 4000 4000 --to <target at 0,0 100x100> refuses through the REAL landing-check machinery with the production refusal text, one hit-window echo per point, no audit line, and the post-guard steps unreached' (
      $dgE2eOk)
    if (-not $dgE2eOk) { Write-Output ("      P-01 e2e: err=[" + $dgErrC + "] log-calls=" + @($script:dgLogCalls).Count + " echo-lines=" + @($dgOut).Count) }
  } finally {
    ${function:Invoke-HitWindowCheck} = $dgHwcReal
    ${function:Resolve-Target} = $dgRtReal
    ${function:Log-Action} = $dgLaReal
    ${function:Get-ExpectChangeBaseline} = $dgEcbReal
  }

}

# lib/selftest-live-suite.ps1 - one family of the selftest section, lifted out of lib/selftest.ps1
# by A-14p (A-beta). The body is byte-identical to what the section carried: the span was hashed before
# the cut and this region is re-hashed after it, so "identical" is a measurement, not a claim. The only
# channel to the orchestrator is the context object, and this family hands nothing back - it writes no
# $Ctx[...] key (measured: zero $Ctx index-assignments in the span), and the $script: names it sets
# (popup, pgProc, chProc, held, ups, gaN, and the temporary $script:Json flip around one child run) are
# script-scope state the inline body already shared with the rest of the section, not hand-backs on the
# declared channel.
#
# live-suite is a MODE family, not a topic: all 20 banners here are checks that only run under --live,
# and each of them also repeats its topic family's words. That claim conflict is decided by data -
# StFamilyOrder puts live-suite first, so precedence is a choice someone made rather than a hashtable
# accident. Three structural notes, all measured before the cut:
# * the run is ONE contiguous block. 20 banners are attributed to this family but exactly one of them
#   delimits a run (two-space indent); the other 19 ride inside the block that contains them, and
#   cutting at each of the 20 would have lifted the middle of the if ($live) block out of that block.
# * the workshop self-report leg and the outcome-prefix ownership lint at the tail sit INSIDE this run,
#   so they travel with it.
# * the window snapshot is handed over by reference, not re-taken: a family that enumerated the screen
#   again would judge a different screen than the one the inline body judged. lint (A-14p) pins that.
# * nothing this body assigns survives the lift (audited: of the 719 names bound inside the span, the 4
#   that are read again after it bind that value themselves before reading it).
function Invoke-SelftestFamily-LiveSuite($Ctx) {
  # context handover (the one thing in this file above the lifted text that is not lifted text)
  $ActionLog = $Ctx['actionLog']
  $codeLines = $Ctx['codeLines']
  $j5ProdEnd = $Ctx['j5ProdEnd']
  $j5ProdStart = $Ctx['j5ProdStart']
  $live = $Ctx['live']
  $OutDir = $Ctx['outDir']
  $w0 = $Ctx['w0']
  $wins = $Ctx['wins']

  # ---------- live: real OCR against a real window ----------
  if ($live) {
    # ---------- live: workshop self-report (printed first, every round) ----------
    # This repo's "is the workshop clean?" gate reads shots/actions.log - which only ever
    # contains activity ORIGINATED BY THIS TOOL. The blind spot was proved on 2026-10-01:
    # another actor drove the desktop through raw UIAutomation for about two minutes (a
    # near-fullscreen window raised to the foreground), produced ZERO lines in
    # actions.log, and coordinate-class checks (hover / drag / type-in) ran underneath it
    # while the gate said "clean". The gate cannot see that class of actor, so the round
    # stops pretending it does: say out loud who owns the foreground and the cursor the
    # moment the round starts, so the transcript can be reconciled against an external
    # timeline afterwards. This is a DISCLOSURE, not an exclusivity guarantee.
    $wsFg = [DT]::GetForegroundWindow()
    $wsPid = 0
    [void][DT]::GetWindowThreadProcessId($wsFg, [ref]$wsPid)
    $wsProc = 'unknown'
    try { $wsProc = (Get-Process -Id $wsPid -ErrorAction Stop).ProcessName } catch { }
    $wsCur = New-Object DT+POINT
    [void][DT]::GetCursorPos([ref]$wsCur)
    Write-Output "      workshop: foreground pid=$wsPid proc='$wsProc' title='$([DT]::Text($wsFg))' cursor=$($wsCur.X),$($wsCur.Y) (actions.log only proves tool-originated activity - an actor using raw Win32/UIAutomation leaves no line here)"
    ST-Check 'live: workshop self-report measured a real foreground owner at round start (the transcript names who holds the desktop, not just "clean")' (
      ($wsPid -gt 0) -and ($wsProc -ne 'unknown') -and ("$wsProc").Length -gt 0)
    $wsNeed = '      workshop: foreground ' + 'pid='
    $wsMarker = 0
    for ($wsi = $j5ProdStart; $wsi -lt $j5ProdEnd; $wsi++) {
      if ($codeLines[$wsi].Contains($wsNeed)) { $wsMarker++ }
    }
    ST-Check 'lint: the live ladder opens with the workshop self-report (deleting the disclosure must be loud)' ($wsMarker -eq 1)
    # Skip full-screen phantom windows (the IME host window, Program Manager,
    # the NVIDIA overlay): they are the biggest by area but hold no text of
    # their own, so OCR'ing them proves nothing about a real target.
    $vs = [System.Windows.Forms.SystemInformation]::VirtualScreen
    $real = @($wins | Where-Object { $_.Title -and -not ($_.W -ge $vs.Width -and $_.H -ge $vs.Height) })
    $tgt = if ($real.Count -gt 0) { $real | Sort-Object -Property Area -Descending | Select-Object -First 1 } else { $w0 }
    $ocrOk = $true
    try { $null = Get-OcrEngine } catch { $ocrOk = $false }
    if (-not $ocrOk) {
      ST-Skip 'live: OCR engine unavailable' 'no OCR language pack installed - OCR-backed checks cannot run'
    }
    else {
      $linesL = Invoke-OcrRegion $tgt.Left $tgt.Top $tgt.W $tgt.H
      ST-Check 'live: Invoke-OcrRegion returns ArrayList' ($linesL -is [System.Collections.ArrayList])
      Write-Output "      OCR read $($linesL.Count) line(s) from '$($tgt.Title)' [$($tgt.Proc)]"
      if ($linesL.Count -gt 0) {
        $needle = $linesL[0].Text
        $hitsL = Find-OcrHits $linesL $needle
        ST-Check 'live: needle taken from OCR output is found again' ($hitsL.Count -ge 1)
        ST-Check 'live: hit rect is screen-space and inside the window' (
          $hitsL[0].X -ge $tgt.Left -and $hitsL[0].Y -ge $tgt.Top -and ($hitsL[0].X + $hitsL[0].W) -le $tgt.Right)
        # Whole-window search through the scaled matcher: on a >2200px window
        # this is exactly the path the old hardcoded guard silently skipped.
        $fL = Find-OcrHitsScaled $tgt.Left $tgt.Top $tgt.W $tgt.H $needle
        ST-Check 'live: scaled whole-window search finds the self-OCR needle' ($fL.Hits.Count -ge 1)
        Write-Output "      scaled search on $($tgt.W)x$($tgt.H) window: retried=$($fL.Retried) verdict-from-2x=$($fL.Scaled)"
        # item 12 (WP-3 sidecar): imgclick --dry must land within 2px of the
        # find-text centre for the same control. Capture this window WITH a
        # sidecar, convert the centre into image pixels through the sidecar
        # scale, and let imgclick --dry map it back (<=2px).
        $mapPath = Join-Path $OutDir ('st-map-' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.png')
        Invoke-DesktopCommand 'rect' @([string]$tgt.Left, [string]$tgt.Top, [string]$tgt.W, [string]$tgt.H, $mapPath, '--fit', '1400') | Out-Null
        $mapS = Read-MapSidecar $mapPath
        $ccx = $hitsL[0].X + $hitsL[0].W / 2.0
        $ccy = $hitsL[0].Y + $hitsL[0].H / 2.0
        $mix = [int][math]::Round(($ccx - $mapS.OriginX) * $mapS.Scale)
        $miy = [int][math]::Round(($ccy - $mapS.OriginY) * $mapS.Scale)
        if ($mix -ge $mapS.OutW) { $mix = $mapS.OutW - 1 }
        if ($miy -ge $mapS.OutH) { $miy = $mapS.OutH - 1 }
        if ($mix -lt 0) { $mix = 0 }
        if ($miy -lt 0) { $miy = 0 }
        $dryOut = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath imgclick $mapPath $mix $miy --dry 2>&1 | Out-String
        $dryCode = $LASTEXITCODE
        $mRt = $dryOut -match 'screen \((\d+),(\d+)\)'
        $rtD1 = 9999; $rtD2 = 9999; $rtPt = 'none'
        if ($mRt) {
          $rtD1 = [math]::Abs([int]$Matches[1] - [int]$ccx)
          $rtD2 = [math]::Abs([int]$Matches[2] - [int]$ccy)
          $rtPt = "$($Matches[1]),$($Matches[2])"
        }
        ST-Check 'live: imgclick --dry within 2px of find-text centre (sidecar round-trip)' ($dryCode -eq 0 -and $mRt -and $rtD1 -le 2 -and $rtD2 -le 2)
        Write-Output "      sidecar round-trip: centre=$([int]$ccx),$([int]$ccy) dry=$rtPt delta=$rtD1,$rtD2 px (map=$($mapS.OutW)x$($mapS.OutH) scale=$($mapS.Scale))"
      } else {
        ST-Skip 'live: window self-check needle' 'the largest real window yielded no text'
      }

      # Synthetic-bitmap tiled OCR: the hard evidence that the tiled path
      # reads text at a known position. The canvas is drawn by System.Drawing
      # (deterministic - real-window screenshots change run to run and are
      # explicitly not acceptable for this check), then fed through the tiled
      # bitmap path; the unique probe string must come back with its rect at
      # the drawn position (<= 3px).
      $canvas1 = $null; $canvas2 = $null
      try {
        # Fixed short token (readback-verified exact over many trials): random
        # tails kept attracting OCR slips (confusable digits, inserted spaces
        # and CJK punctuation), and the canvas is memory-only so no anti-stale
        # randomness is needed.
        $probeA = 'TILEDPROBEA'
        $canvas1 = New-Object System.Drawing.Bitmap(2600, 1600)
        $gA = [System.Drawing.Graphics]::FromImage($canvas1)
        $gA.Clear([System.Drawing.Color]::FromArgb(18, 18, 22))
        $fntA = New-Object System.Drawing.Font('Consolas', 11, [System.Drawing.FontStyle]::Regular)
        $brsA = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(240, 240, 240))
        # Draw so the INK (not the layout box) starts at (1200,800): the glyph
        # outline offset is measured with the same GDI+ text engine, keeping
        # the <=3px assertion meaningful instead of absorbing font padding.
        $gpA = New-Object System.Drawing.Drawing2D.GraphicsPath
        $gpA.AddString($probeA, $fntA.FontFamily, [int]$fntA.Style, $fntA.Size, (New-Object System.Drawing.PointF(0, 0)), [System.Drawing.StringFormat]::GenericDefault)
        $inkA = $gpA.GetBounds()
        $gA.DrawString($probeA, $fntA, $brsA, [single](1200 - $inkA.X), [single](800 - $inkA.Y))
        $gA.Dispose(); $fntA.Dispose(); $brsA.Dispose()
        $tA = Invoke-OcrBitmapTiled $canvas1 2600 1600 2.0 16 0 0
        # Space-insensitive local match: live readback showed the engine
        # inserts spaces into long letter runs ('DTXPROBEWUUDJ E'), and the
        # tool's matcher preserves English spacing BY DESIGN - the mapping
        # assertion must not flake on that.
        $hA = @($tA.Lines | Where-Object { ($_.Text -replace ' ', '') -like ('*' + $probeA + '*') })
        $synA = ($hA.Count -eq 1 -and $tA.Tiles -ge 1 -and [math]::Abs($hA[0].X - 1200) -le 3 -and [math]::Abs($hA[0].Y - 800) -le 3)
        ST-Check 'live: synthetic bitmap 2600x1600 via tiled OCR - hit + <=3px mapping' $synA
        $rA = 'none'; if ($hA.Count -gt 0) { $rA = "$($hA[0].X),$($hA[0].Y)" }
        Write-Output "      synthetic tiled OCR (2600x1600): tiles=$($tA.Tiles) hits=$($hA.Count) rect=$rA (expect 1200,800) [$probeA]"
        if ($hA.Count -eq 0) { Write-Output ("      tile notes: " + (@($tA.Notes) -join ' ') + " | lines: " + ((@($tA.Lines | Select-Object -First 6 | ForEach-Object { $_.Text })) -join ' / ')) }
        # Same idea, sized so the plan actually SPLITS on this engine's limit.
        # Both probes sit in single-tile zones (b1 left of the overlap, b2
        # right of tile1's reach) so each maps through exactly one tile - the
        # per-tile offset math of BOTH tiles is proven. Fidelity is asserted
        # against a SAME-RUN 1x reference read of the very same canvas: the
        # engine's absolute boxes carry pad/jitter of their own (+1..9px, and
        # on some draw phases a line is reported up to ~90px off even though
        # the image is pixel-verified - all measured live), so absolute-vs-ink
        # comparisons bounce on engine noise instead of testing OUR transform.
        # mapped-vs-reference isolates the split/upscale/map math (the <=3px
        # clause) and cancels the pad. Draw phases below are live-verified
        # deterministic (3/3 runs, deltas (-1,0) and (-1,-1)).
        $dimSyn = 0L; try { $dimSyn = Get-OcrMaxDimension } catch { $dimSyn = 0L }
        if ($dimSyn -le 0) { $dimSyn = 4000L }
        $multiW = [int]([math]::Floor($dimSyn / 2.0)) + 1200
        $pb1x = 602; $pb1y = 803
        $pb2x = 5300; $pb2y = 800
        $probeB1 = 'TILEDPROBEA'
        $probeB2 = 'TILEDPROBEB'
        $canvas2 = New-Object System.Drawing.Bitmap($multiW, 1600)
        $gB = [System.Drawing.Graphics]::FromImage($canvas2)
        $gB.Clear([System.Drawing.Color]::FromArgb(18, 18, 22))
        $fntB = New-Object System.Drawing.Font('Consolas', 16, [System.Drawing.FontStyle]::Regular)
        $brsB = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(240, 240, 240))
        $gpB1 = New-Object System.Drawing.Drawing2D.GraphicsPath
        $gpB1.AddString($probeB1, $fntB.FontFamily, [int]$fntB.Style, $fntB.Size, (New-Object System.Drawing.PointF(0, 0)), [System.Drawing.StringFormat]::GenericDefault)
        $inkB1 = $gpB1.GetBounds()
        $gpB2 = New-Object System.Drawing.Drawing2D.GraphicsPath
        $gpB2.AddString($probeB2, $fntB.FontFamily, [int]$fntB.Style, $fntB.Size, (New-Object System.Drawing.PointF(0, 0)), [System.Drawing.StringFormat]::GenericDefault)
        $inkB2 = $gpB2.GetBounds()
        $gB.DrawString($probeB1, $fntB, $brsB, [single]($pb1x - $inkB1.X), [single]($pb1y - $inkB1.Y))
        $gB.DrawString($probeB2, $fntB, $brsB, [single]($pb2x - $inkB2.X), [single]($pb2y - $inkB2.Y))
        $gB.Dispose(); $fntB.Dispose(); $brsB.Dispose()
        # v2.9.0 - the reference is the SAME TILE cropped and read at 1x, not the whole
        # canvas. The old shape compared a 2x-upscaled tile against a whole-canvas 1x read,
        # and on this machine the engine moves line boxes by tens of pixels on tiles whose
        # upscaled size sits exactly at MaxImageDimension (measured: Y off 53px, X off 1px -
        # identical on two consecutive rounds and on the pre-change HEAD, so it was neither
        # flaky nor ours). That assertion was measuring the engine's geometry while claiming
        # to measure our mapping math, and the only way it could react was going red on a
        # round where nothing of ours was wrong. Both sides now come from one tile and the
        # 3px tolerance stays; the whole-canvas delta is REPORTED as engine-jitter= so drift
        # is visible without being a gate.
        $refB = Invoke-OcrBitmap $canvas2
        $rB1 = @($refB.Lines | Where-Object { ($_.Text -replace ' ', '') -like ('*' + $probeB1 + '*') })
        $rB2 = @($refB.Lines | Where-Object { ($_.Text -replace ' ', '') -like ('*' + $probeB2 + '*') })
        $tB = Invoke-OcrBitmapTiled $canvas2 $multiW 1600 2.0 16 0 0
        $hB1 = @($tB.Lines | Where-Object { ($_.Text -replace ' ', '') -like ('*' + $probeB1 + '*') })
        $hB2 = @($tB.Lines | Where-Object { ($_.Text -replace ' ', '') -like ('*' + $probeB2 + '*') })
        $synMaxDim = 0
        try { $synMaxDim = Get-OcrMaxDimension } catch { $synMaxDim = 0 }
        $synPlan = Get-OcrTilePlan $multiW 1600 2.0 $synMaxDim 64 16
        $tileRef = @{}
        $tileRefErr = ''
        foreach ($pd in @(@{ N = $probeB1; X = $pb1x; Y = $pb1y }, @{ N = $probeB2; X = $pb2x; Y = $pb2y })) {
          $ht = $null
          foreach ($tl in @($synPlan.Tiles)) {
            if ($pd.X -ge $tl.X -and $pd.X -lt ($tl.X + $tl.W) -and $pd.Y -ge $tl.Y -and $pd.Y -lt ($tl.Y + $tl.H)) { $ht = $tl; break }
          }
          if ($null -eq $ht) { $tileRefErr += "no-tile-for-$($pd.N) "; continue }
          $tcrop = $canvas2.Clone((New-Object System.Drawing.Rectangle($ht.X, $ht.Y, $ht.W, $ht.H)), $canvas2.PixelFormat)
          $tl2 = @()
          try { $tl2 = @((Invoke-OcrBitmap $tcrop).Lines) } finally { $tcrop.Dispose() }
          $th = @($tl2 | Where-Object { ($_.Text -replace ' ', '') -like ('*' + $pd.N + '*') })
          if ($th.Count -ne 1) { $tileRefErr += "$($pd.N) crop-hits=$($th.Count) "; continue }
          $tileRef[$pd.N] = @{ X = ($ht.X + [int]$th[0].X); Y = ($ht.Y + [int]$th[0].Y) }
        }
        # >=2 tiles, both probes found in the merged result, and each mapped 2x rect within
        # 3px of its OWN TILE's 1x read - per axis, strictly.
        $synB = ($tB.Tiles -ge 2) -and (-not $synPlan.Error) -and ($tileRefErr -eq '') -and
          ($hB1.Count -eq 1) -and ($hB2.Count -eq 1) -and
          [bool]($tileRef.ContainsKey($probeB1)) -and [bool]($tileRef.ContainsKey($probeB2)) -and
          [math]::Abs($hB1[0].X - $tileRef[$probeB1].X) -le 3 -and [math]::Abs($hB1[0].Y - $tileRef[$probeB1].Y) -le 3 -and
          [math]::Abs($hB2[0].X - $tileRef[$probeB2].X) -le 3 -and [math]::Abs($hB2[0].Y - $tileRef[$probeB2].Y) -le 3
        ST-Check 'live: synthetic split - >=2 tiles, mapped reads within 3px of the SAME TILE read at 1x (engine jitter reported, not asserted)' $synB
        $sB1 = 'none'; if ($hB1.Count -gt 0) { $sB1 = "$($hB1[0].X),$($hB1[0].Y)" }
        $sB2 = 'none'; if ($hB2.Count -gt 0) { $sB2 = "$($hB2[0].X),$($hB2[0].Y)" }
        $sR1 = 'none'; if ($rB1.Count -gt 0) { $sR1 = "$($rB1[0].X),$($rB1[0].Y)" }
        $sR2 = 'none'; if ($rB2.Count -gt 0) { $sR2 = "$($rB2[0].X),$($rB2[0].Y)" }
        $sT1 = 'none'; if ($tileRef.ContainsKey($probeB1)) { $sT1 = "$($tileRef[$probeB1].X),$($tileRef[$probeB1].Y)" }
        $sT2 = 'none'; if ($tileRef.ContainsKey($probeB2)) { $sT2 = "$($tileRef[$probeB2].X),$($tileRef[$probeB2].Y)" }
        # reported, NOT asserted: how far the merged tiled read sits from a whole-canvas 1x
        # read. This is the engine's own box placement on limit-sized tiles.
        $jit1 = 'n/a'; if ($hB1.Count -eq 1 -and $rB1.Count -eq 1) { $jit1 = "$([math]::Abs($hB1[0].X - $rB1[0].X))/$([math]::Abs($hB1[0].Y - $rB1[0].Y))px" }
        $jit2 = 'n/a'; if ($hB2.Count -eq 1 -and $rB2.Count -eq 1) { $jit2 = "$([math]::Abs($hB2[0].X - $rB2[0].X))/$([math]::Abs($hB2[0].Y - $rB2[0].Y))px" }
        Write-Output "      synthetic tiled OCR (${multiW}x1600): tiles=$($tB.Tiles) plan=$($synPlan.Count) mapped1=$sB1 tileRef1=$sT1 whole1=$sR1 engine-jitter1=$jit1"
        Write-Output "      synthetic tiled OCR probe2: mapped2=$sB2 tileRef2=$sT2 whole2=$sR2 engine-jitter2=$jit2 (jitter is reported, not asserted - see the comment above)"
        if ($tileRefErr) { Write-Output "      tile reference problem: $tileRefErr" }
        if (-not $synB) {
          Write-Output "      DEBUG split failure: tiles=$($tB.Tiles) planErr='$($synPlan.Error)' hB1=$($hB1.Count) hB2=$($hB2.Count) tileRefErr='$tileRefErr'"
          Write-Output "      DEBUG merged tiled lines ($($tB.Lines.Count)):"
          $tB.Lines | Select-Object -First 12 | ForEach-Object { Write-Output "        [$($_.Text)] X=$($_.X) Y=$($_.Y) W=$($_.W) H=$($_.H)" }
          Write-Output "      DEBUG reference lines ($($refB.Lines.Count)):"
          $refB.Lines | Select-Object -First 8 | ForEach-Object { Write-Output "        [$($_.Text)] X=$($_.X) Y=$($_.Y)" }
        }
      } finally {
        if ($null -ne $canvas1) { $canvas1.Dispose() }
        if ($null -ne $canvas2) { $canvas2.Dispose() }
      }

      # Big-window retry lock + --no-tile contrast (miss needle): the
      # v1.3.1-v1.4.1 bug silently skipped the retry on big windows
      # (Retried stayed false and nothing said so). No window on this display
      # can exceed maxDim/2 at the probed limit, so the lock asserts the
      # retry ACTIVATES on the largest real window; --no-tile must match the
      # v1.4.1 decision exactly (never tiled; single 2x only when it fits).
      $absent9 = 'DTXABSENT-' + [guid]::NewGuid().ToString('N').Substring(0, 8)
      $dim9 = 0L; try { $dim9 = Get-OcrMaxDimension } catch { $dim9 = 0L }
      $fits9 = Test-OcrRetryFits $tgt.W $tgt.H $dim9
      $fBig = Find-OcrHitsScaled $tgt.Left $tgt.Top $tgt.W $tgt.H $absent9 'auto' 16 $false
      ST-Check 'live: big-window miss still retried (Retried=true - no silent skip)' ($fBig.Retried -eq $true -and $fBig.Tiled -eq (-not $fits9))
      Write-Output "      retry lock on $($tgt.W)x$($tgt.H) (maxDim=$dim9): fits=$fits9 retried=$($fBig.Retried) tiled=$($fBig.Tiled)"
      $fNT = Find-OcrHitsScaled $tgt.Left $tgt.Top $tgt.W $tgt.H $absent9 'auto' 16 $true
      ST-Check 'live: --no-tile matches v1.4.1 decision (never tiled, retry == fits)' ((-not $fNT.Tiled) -and ($fNT.Retried -eq $fits9))
      Write-Output "      --no-tile contrast: fits=$fits9 retried=$($fNT.Retried) tiled=$($fNT.Tiled)"

      # Expect family exit codes + message split, against a probe window THIS
      # test owns (no user app involved): one click must verify (exit 0,
      # "+ verified"), one must fail loudly (exit 1, "clicked OK but
      # expectation NOT met").
      $staleP = Resolve-Window 'DTX-ExpectProbe'
      if ($staleP) {
        [void][DT]::PostMessage($staleP.Handle, 0x0010, [IntPtr]::Zero, [IntPtr]::Zero)
        Start-Sleep -Milliseconds 400
      }
      $probeScript = Join-Path $env:TEMP ('dtx-probe-' + [guid]::NewGuid().ToString('N') + '.ps1')
      $probeProc = $null
      try {
        # Constant label with no random tail: OCR inserts spaces into LONG
        # letter runs (live readback: 'DTXPROBEWUUDJ E'), and the tool's
        # matcher preserves English spacing by design - an 8-char run reads
        # cleanly every time. Freshness comes from closing any stale probe
        # window before spawning.
        $safeP = 'ACDEFHJKLMNPRTUVWXY'
        $randP = ''
        1..6 | ForEach-Object { $randP += $safeP[(Get-Random -Maximum $safeP.Length)] }
        $labelText = 'DTXPROBE'
        $pSrc = @'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
$f = New-Object System.Windows.Forms.Form
$f.Text = 'DTX-ExpectProbe'
$f.ClientSize = New-Object System.Drawing.Size(460, 240)
$f.StartPosition = 'CenterScreen'
$f.TopMost = $true
$f.BackColor = [System.Drawing.Color]::FromArgb(35, 35, 40)
$lbl = New-Object System.Windows.Forms.Label
$lbl.Text = 'LABELTEXT'
$lbl.ForeColor = [System.Drawing.Color]::White
$lbl.Font = New-Object System.Drawing.Font('Consolas', 22, [System.Drawing.FontStyle]::Bold)
$lbl.AutoSize = $true
$lbl.Location = New-Object System.Drawing.Point(30, 40)
$f.Controls.Add($lbl)
[System.Windows.Forms.Application]::Run($f)
'@
        [System.IO.File]::WriteAllText($probeScript, $pSrc.Replace('LABELTEXT', $labelText), (New-Object System.Text.UTF8Encoding($false)))
        $probeProc = Start-Process powershell -ArgumentList '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $probeScript -PassThru
        $pw2 = $null
        $swP = [System.Diagnostics.Stopwatch]::StartNew()
        while ($swP.Elapsed.TotalSeconds -lt 15) {
          $pw2 = Resolve-Window 'DTX-ExpectProbe'
          if ($pw2) { break }
          Start-Sleep -Milliseconds 400
        }
        if ($null -eq $pw2) { throw 'expect-probe window did not appear within 15s' }
        Start-Sleep -Milliseconds 600
        [void][DT]::SetForegroundWindow($pw2.Handle)
        Start-Sleep -Milliseconds 200
        $cpx = [int]($pw2.Left + $pw2.W / 2)
        $cpy = [int]($pw2.Top + $pw2.H - 60)
        $outOk = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath click $cpx $cpy --to 'DTX-ExpectProbe' --expect $labelText --timeout 6 2>&1 | Out-String
        $codeOk = $LASTEXITCODE
        # "self-reported value" (v1.5.7): the two calls pass DIFFERENT --timeout values, so demanding the
        # printed patience match each one is what proves the flag reached the loop - an echo of
        # elapsed time alone cannot tell a honoured --timeout 2 from a silently ignored one.
        $okPatience = ($outOk -match 'patience 6s, polled every [0-9]+ ms')
        ST-Check 'live: expect satisfied -> exit 0 + verified, naming the 6s patience it used' (
          ($codeOk -eq 0) -and ($outOk -match '\+ verified in') -and $okPatience)
        Write-Output "      expect probe: satisfied-exit=$codeOk patience-named=$okPatience label=$labelText"
        Write-Output ("      satisfied-output: " + (($outOk.Trim() -split "`r?`n" | Select-Object -First 4) -join ' | '))
        $absentP = 'DTXABSENT' + $randP
        $outBad = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath click $cpx $cpy --to 'DTX-ExpectProbe' --expect $absentP --timeout 2 2>&1 | Out-String
        $codeBad = $LASTEXITCODE
        $badPatience = ($outBad -match 'after [0-9.]+s of 2s') -and ($outBad -match 'patience 2s')
        ST-Check 'live: expect unsatisfied -> exit 1 + action/assertion split message naming the 2s patience' (
          (($codeBad -eq 1) -and ($outBad -match 'clicked OK but expectation NOT met')) -and $badPatience)
        Write-Output "      expect probe: unsatisfied-exit=$codeBad patience-named=$badPatience"
        Write-Output ("      unsatisfied-output: " + (($outBad.Trim() -split "`r?`n" | Select-Object -First 4) -join ' | '))
        $outWheel = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath wheel -3 --at 'DTX-ExpectProbe' 2>&1 | Out-String
        $codeWheel = $LASTEXITCODE
        $wheelSelfReport = ($outWheel -match 'wheel -3') -and ($outWheel -match 'delivered to hwnd=') -and
          ($outWheel -match 'pid=' + [regex]::Escape("$($pw2.Pid)")) -and ($outWheel -match "title='DTX-ExpectProbe'")
        ST-Check 'live: wheel executes once on a DTX window and self-reports amount plus hwnd/class/pid/title delivery target' (
          ($codeWheel -eq 0) -and $wheelSelfReport)
        Write-Output "      wheel probe: exit=$codeWheel self-report=$wheelSelfReport"
        Write-Output ("      wheel-output: " + (($outWheel.Trim() -split "`r?`n" | Select-Object -First 2) -join ' | '))
        # v1.7.0 (J-07 A, "do not lose" #2): win-close must REALLY remove the window -
        # close it via the tool, then 'wins' must no longer list that pid.
        $outClose = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath win-close 'DTX-ExpectProbe' 2>&1 | Out-String
        $codeClose = $LASTEXITCODE
        Start-Sleep -Milliseconds 800
        $winsAfter = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath wins 2>&1 | Out-String
        $gonePat = 'pid=' + $probeProc.Id + '\s'
        $stillListed = ($winsAfter -match $gonePat)
        ST-Check 'live: win-close removes the target - wins no longer lists that pid (J-07 contract)' (
          ($codeClose -eq 0) -and (-not $stillListed))
        Write-Output "      win-close contract: close-exit=$codeClose wins-still-lists-pid=$stillListed"
      } catch {
        ST-Check 'live: expect probe setup+run' $false
        Write-Output "      expect probe error: $($_.Exception.Message)"
      } finally {
        if ($probeProc -and -not $probeProc.HasExited) { try { Stop-Process -Id $probeProc.Id -Force -ErrorAction SilentlyContinue } catch { } }
        if (Test-Path -LiteralPath $probeScript) { Remove-Item -LiteralPath $probeScript -Force -ErrorAction SilentlyContinue }
      }

      # ---------- live: v1.9.0 popup survival guard end-to-end (T-1..T-4) ----------
      # Fixture: DTX-PGMain spawns an OWNED popup DTX-PGPopup when clicked (real window,
      # tool-owned - never a real app's flaky popup). mode=fuse destroys the popup 800ms
      # after it opens (the synthetic self-closing popup the task order demands); mode=keep
      # leaves it alive for the control run and the win-close dismissal path.
      # X-02 residual (v4.1.1): see the chProc note - this block reads $script:pgProc in its
      # finally (and the inner finally re-reads it), while the real initialiser sat INSIDE the
      # try, so a throw before it left the outer finally reading an unassigned variable.
      $script:pgProc = $null
      $pgTmp = New-Object System.Collections.ArrayList
      try {
        foreach ($pgStale in @('DTX-PGMain', 'DTX-PGPopup')) {
          $pgOld = Resolve-Window $pgStale
          if ($pgOld) { try { Stop-Process -Id $pgOld.Pid -Force -ErrorAction SilentlyContinue } catch { }; Start-Sleep -Milliseconds 400 }
        }
        $pgScript = Join-Path $env:TEMP ('dtx-pg-' + [guid]::NewGuid().ToString('N') + '.ps1')
        [void]$pgTmp.Add($pgScript)
        $pgSrc = @'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class HXPG {
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}
"@
[void][HXPG]::SetProcessDPIAware()
$mode = if ($args.Count -ge 1) { $args[0] } else { 'keep' }
$main = New-Object System.Windows.Forms.Form
$main.Text = 'DTX-PGMain'
$main.ClientSize = New-Object System.Drawing.Size(300, 180)
$main.StartPosition = 'Manual'
$main.Location = New-Object System.Drawing.Point(160, 1500)
$main.TopMost = $true
$script:popup = $null
$main.Add_MouseClick({
  param($s, $e)
  if ($null -ne $script:popup) { return }
  $p = New-Object System.Windows.Forms.Form
  $p.Text = 'DTX-PGPopup'
  $p.ClientSize = New-Object System.Drawing.Size(220, 120)
  $p.StartPosition = 'Manual'
  $p.Location = New-Object System.Drawing.Point($s.Location.X + 330, $s.Location.Y)
  $p.TopMost = $true
  $s.AddOwnedForm($p)
  $p.Show()
  $script:popup = $p
  if ($mode -eq 'fuse') {
    $t = New-Object System.Windows.Forms.Timer
    $t.Interval = 800
    $t.Add_Tick({ param($ts, $te) $ts.Stop(); if ($null -ne $script:popup) { $script:popup.Close(); $script:popup = $null } })
    $t.Start()
  }
})
[System.Windows.Forms.Application]::Run($main)
'@
        [System.IO.File]::WriteAllText($pgScript, $pgSrc, (New-Object System.Text.UTF8Encoding($false)))
        # spawn / run / stop are separate phases: the click coordinates must come from
        # the RESOLVED physical rect of the spawned window (150% scaling - a fixture
        # without SetProcessDPIAware parks its windows at virtualized coordinates and
        # the click lands on the desktop instead; measured in the first live run).
        $script:pgProc = $null
        $pgSpawn = {
          param($mode, $tag)
          $pgArgs = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $pgScript, $mode)
          $script:pgProc = Start-Process powershell -ArgumentList $pgArgs -PassThru
          $pgMain = $null
          $swPg = [System.Diagnostics.Stopwatch]::StartNew()
          while ($swPg.Elapsed.TotalSeconds -lt 15) {
            $pgMain = Resolve-Window 'DTX-PGMain'
            if ($pgMain) { break }
            Start-Sleep -Milliseconds 400
          }
          if ($null -eq $pgMain) { throw "popup-guard fixture ($tag) did not appear within 15s" }
          Start-Sleep -Milliseconds 500
          return $pgMain
        }
        $pgStop = {
          if ($script:pgProc -and -not $script:pgProc.HasExited) { try { Stop-Process -Id $script:pgProc.Id -Force -ErrorAction SilentlyContinue } catch { } }
          $script:pgProc = $null
        }
        $pgScriptRun = {
          param($stepsJson)
          $pgSteps = Join-Path $env:TEMP ('dtx-pg-' + [guid]::NewGuid().ToString('N') + '.json')
          [void]$pgTmp.Add($pgSteps)
          [System.IO.File]::WriteAllText($pgSteps, $stepsJson, (New-Object System.Text.UTF8Encoding($false)))
          $out = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath script $pgSteps 2>&1 | Out-String
          return @{ Out = $out; Code = $LASTEXITCODE }
        }
        # T-1: the popup opens, is guarded alive, then self-closes - a later step must
        # hit the guard and abort the REST of the script with measured values.
        $pgMain1 = & $pgSpawn 'fuse' 'T-1'
        $cx = [int]($pgMain1.Left + $pgMain1.W / 2)
        $cy = [int]($pgMain1.Top + $pgMain1.H / 2)
        $t1Json = '[{"click":[' + $cx + ',' + $cy + ']},{"sleep":150},{"require-popup":"DTX-PGPopup","tolerance":3},{"sleep":1500},{"assert-window":"DTX-PGPopup"}]'
        $t1 = & $pgScriptRun $t1Json
        & $pgStop
        $t1Shape = ($t1.Out -match 'popup guard: popup GONE') -and ($t1.Out -match 'before step 5 of 5') -and
          ($t1.Out -match '  baseline: pid=') -and ($t1.Out -match '  now     : ') -and ($t1.Out -match '  delta   : ') -and
          ($t1.Out -match 'script aborted: popup guard failed \(nothing after this step ran\)') -and
          ($t1.Out -match 'armed at step 3 ') -and (-not ($t1.Out -match '#5 assert-window FAIL'))
        ST-Check 'live: T-1 a self-closing popup aborts the rest of the script with baseline/now/delta echoed, nothing after it runs' (
          ($t1.Code -eq 1) -and $t1Shape)
        Write-Output "      T-1 exit=$($t1.Code) shape=$t1Shape"
        Write-Output ("      T-1 output: " + (($t1.Out.Trim() -split "`r?`n" | Where-Object { $_ -match 'popup guard|baseline|now|delta|aborted' } | Select-Object -First 6) -join ' | '))
        # T-4: the aborted run left its marker in actions.log - replay must refuse the
        # slice that carries it (dry run included; no --force backdoor exists).
        $t4Out = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath replay --last 6 2>&1 | Out-String
        $t4Code = $LASTEXITCODE
        ST-Check 'live: T-4 replay of an aborted-by-the-popup-guard run is refused by default' (
          ($t4Code -eq 1) -and ($t4Out -match 'refusing to replay a script that was aborted by the popup guard'))
        Write-Output "      T-4 exit=$t4Code refused=$($t4Out -match 'refusing to replay')"
        # T-2 (control): the same shape with a popup that STAYS - the script must run to
        # completion, arm at step 3 and release at step 5, exit 0 (no false red).
        $pgMain2 = & $pgSpawn 'keep' 'T-2'
        $cx2 = [int]($pgMain2.Left + $pgMain2.W / 2)
        $cy2 = [int]($pgMain2.Top + $pgMain2.H / 2)
        $t2Json = '[{"click":[' + $cx2 + ',' + $cy2 + ']},{"sleep":150},{"require-popup":"DTX-PGPopup","tolerance":3},{"assert-window":"DTX-PGPopup"},{"release-popup":""},{"assert-window":"DTX-PGMain"}]'
        $t2 = & $pgScriptRun $t2Json
        & $pgStop
        $t2Ok = ($t2.Code -eq 0) -and ($t2.Out -match 'armed at step 3 ') -and ($t2.Out -match 'popup guard: released at step 5') -and ($t2.Out -match '6 steps, all ok')
        ST-Check 'live: T-2 a popup alive throughout runs to completion and releases cleanly (exit 0, no false red)' ($t2Ok)
        Write-Output "      T-2 exit=$($t2.Code) ok=$t2Ok"
        Write-Output ("      T-2 output: " + (($t2.Out.Trim() -split "`r?`n" | Where-Object { $_ -match 'popup guard|FAIL|aborted|steps,' } | Select-Object -First 6) -join ' | '))
        # T-4 negative control: a slice WITHOUT an abort marker must replay (the gate
        # bites only aborted runs, not every guarded script). --last 3 = the click line
        # plus the two markers of the successful T-2 run: one replayable job, no marker.
        $t4bOut = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath replay --last 3 2>&1 | Out-String
        $t4bCode = $LASTEXITCODE
        ST-Check 'live: T-4 negative - a successful run leaves no abort marker, its slice still replays (the gate bites only abort markers)' (
          ($t4bCode -eq 0) -and ($t4bOut -match 'WOULD'))
        Write-Output "      T-4n exit=$t4bCode would-list=$($t4bOut -match 'WOULD')"
        # T-3: the script's OWN win-close of the guarded popup is a legal dismissal -
        # auto-release with a notice, then later steps keep running (exit 0).
        $pgMain3 = & $pgSpawn 'keep' 'T-3'
        $cx3 = [int]($pgMain3.Left + $pgMain3.W / 2)
        $cy3 = [int]($pgMain3.Top + $pgMain3.H / 2)
        $t3Json = '[{"click":[' + $cx3 + ',' + $cy3 + ']},{"sleep":150},{"require-popup":"DTX-PGPopup","tolerance":3},{"win-close":"DTX-PGPopup"},{"assert-window":"DTX-PGMain"}]'
        $t3 = & $pgScriptRun $t3Json
        & $pgStop
        $t3Ok = ($t3.Code -eq 0) -and ($t3.Out -match 'popup guard: released at step 4 \(win-close closed the guarded popup\)') -and ($t3.Out -match '5 steps, all ok')
        ST-Check 'live: T-3 the script closing its own guarded popup via win-close auto-releases and continues (no false red)' ($t3Ok)
        Write-Output "      T-3 exit=$($t3.Code) ok=$t3Ok"
        Write-Output ("      T-3 output: " + (($t3.Out.Trim() -split "`r?`n" | Where-Object { $_ -match 'popup guard|FAIL|aborted|steps,' } | Select-Object -First 6) -join ' | '))
      } catch {
        ST-Check 'live: popup guard setup+run' $false
        Write-Output "      popup guard error: $($_.Exception.Message)"
      } finally {
        # belt and suspenders: the runs stop their own fixture, a crashed run leaves
        # nothing (both windows belong to the fixture process)
        if ($script:pgProc -and -not $script:pgProc.HasExited) { try { Stop-Process -Id $script:pgProc.Id -Force -ErrorAction SilentlyContinue } catch { } }
        foreach ($pgTitle in @('DTX-PGMain', 'DTX-PGPopup')) {
          $pgLeft = Resolve-Window $pgTitle
          if ($pgLeft) { try { Stop-Process -Id $pgLeft.Pid -Force -ErrorAction SilentlyContinue } catch { } }
        }
        foreach ($f in $pgTmp) { if (Test-Path -LiteralPath $f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue } }
      }

      # ---------- live: v2.0.1 P-3 drag mid-state (press-down / drag-to / press-up + the three watchdogs) ----------
      # Fixture: one plain DTX window. Every press is computed from ITS rect, and the
      # CLI half passes --to, so the hit-window guard refuses any point outside that
      # window - the red line "act judgements only hit tool-made DTX-* windows" is
      # enforced by the tool, not by this comment.
      $p3Proc = $null; $p3Child = $null
      $p3Tmp = New-Object System.Collections.ArrayList
      $p3Ids = New-Object System.Collections.ArrayList
      # v2.2.0 (P3-6 reverse direction): remember how many audit lines exist BEFORE this block
      # runs, so the reverse check can only see pairings this round opened. A tail window alone
      # cannot do that - the first round of the reverse check called eleven 'orphans' that were
      # simply the previous round's presses.
      $p3LogStart = 0
      try { $p3LogStart = @(Get-Content -LiteralPath $ActionLog -Encoding UTF8 -ErrorAction SilentlyContinue).Count } catch { }
      try {
        $p3Old = Resolve-Window 'DTX-PressProbe'
        if ($p3Old) { try { Stop-Process -Id $p3Old.Pid -Force -ErrorAction SilentlyContinue } catch { }; Start-Sleep -Milliseconds 500 }
        $p3Script = Join-Path $env:TEMP ('dtx-press-' + [guid]::NewGuid().ToString('N') + '.ps1')
        [void]$p3Tmp.Add($p3Script)
        $p3Src = @'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class HXP3 {
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}
"@
[void][HXP3]::SetProcessDPIAware()
$f = New-Object System.Windows.Forms.Form
$f.Text = 'DTX-PressProbe held=0 up=0'
$f.ClientSize = New-Object System.Drawing.Size(420, 240)
$f.StartPosition = 'Manual'
$f.Location = New-Object System.Drawing.Point(60, 1500)
$f.TopMost = $true
$script:held = 0
$script:ups = 0
$f.Add_MouseMove({
  param($s, $e)
  if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
    $script:held++
    $s.Text = 'DTX-PressProbe held=' + $script:held + ' up=' + $script:ups
  }
})
$f.Add_MouseUp({
  param($s, $e)
  if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
    $script:ups++
    $s.Text = 'DTX-PressProbe held=' + $script:held + ' up=' + $script:ups
  }
})
[System.Windows.Forms.Application]::Run($f)
'@
        [System.IO.File]::WriteAllText($p3Script, $p3Src, (New-Object System.Text.UTF8Encoding($false)))
        $p3Proc = Start-Process -FilePath powershell -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $p3Script) -PassThru
        $p3Sw = [System.Diagnostics.Stopwatch]::StartNew()
        $p3Win = $null
        while ($p3Sw.Elapsed.TotalSeconds -lt 15) { $p3Win = Resolve-Window 'DTX-PressProbe'; if ($p3Win) { break }; Start-Sleep -Milliseconds 400 }
        if ($null -eq $p3Win) { throw 'press-probe window did not appear within 15s' }
        Start-Sleep -Milliseconds 600
        $p3X = [int]($p3Win.Left + $p3Win.W / 2)
        $p3Y = [int]($p3Win.Top + [int]($p3Win.H / 2))

        # P3-1 watchdog 1 OBSERVED: the child holds the button, its own deadline lets
        # go. The echo must carry the measured state (not the requested one) and the
        # parent must see the button genuinely up afterwards.
        $p3aOut = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath press-down $p3X $p3Y --to 'DTX-PressProbe' --max-hold 2000 2>&1 | Out-String
        $p3aEcho = ($p3aOut -match 'button is DOWN at \(') -and ($p3aOut -match 'measured-down=yes') -and ($p3aOut -match 'will auto-release after 2000ms')
        $p3aAuto = ($p3aOut -match 'auto-released after 2000ms \(id=(p\d+-\d+) cause=max-hold\)')
        if ($p3aAuto) { [void]$p3Ids.Add($Matches[1]) }
        ST-Check 'live: P3-1 press-down reports the measured press state and --max-hold releases it inside the same process (watchdog 1 observed, not claimed)' (
          $p3aEcho -and $p3aAuto -and (-not (Get-LeftButtonDown)))
        Write-Output ("      P3-1 " + (($p3aOut.Trim() -split "`r?`n" | Where-Object { $_ -match 'button is|hit-window|ERROR' } | Select-Object -First 5) -join ' | '))

        # P3-2 / P3-3 the two refusals with their real exit codes (a refusal that only
        # prints and still exits 0 is the silent-success shape).
        $p3bOut = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath drag-to $p3X $p3Y 2>&1 | Out-String
        $p3bCode = $LASTEXITCODE
        ST-Check 'live: P3-2 drag-to with nothing pressed is REFUSED with exit 1 (it must not echo a drag that never happened)' (
          ($p3bCode -eq 1) -and ($p3bOut -match 'needs an existing press state'))
        $p3cOut = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath press-up $p3X $p3Y 2>&1 | Out-String
        $p3cCode = $LASTEXITCODE
        ST-Check 'live: P3-3 press-up with nothing pressed is REFUSED with exit 1 instead of reporting a release' (
          ($p3cCode -eq 1) -and ($p3cOut -match 'the left button is not down'))

        # P3-4 the mid-state really delivers a HELD drag: press inside the fixture's
        # client area, travel while held, let go. The witness is the fixture itself -
        # it counts MouseMove events that arrive with the left button down and
        # MouseUp events, and publishes both in its window title. (A window-manager
        # caption drag was tried first and measures nothing: WinForms captions do not
        # move on a synthetic press here, and a counter in the target is the honest
        # replacement - it proves delivery to the window under the cursor.)
        $p3Witness = {
          $p3w2 = Resolve-Window 'DTX-PressProbe'
          if ($null -eq $p3w2) { return @{ Held = -1; Up = -1 } }
          $p3h = -1; $p3u = -1
          if ("$($p3w2.Title)" -match 'held=(\d+) up=(\d+)') { $p3h = [int]$Matches[1]; $p3u = [int]$Matches[2] }
          return @{ Held = $p3h; Up = $p3u }
        }
        $p3Before = & $p3Witness
        $p3Win2 = Resolve-Window 'DTX-PressProbe'
        $p3Tx = [int]($p3Win2.Left + 80)
        $p3Ty = [int]($p3Win2.Top + 100)
        $p3Ex = [int]($p3Win2.Left + 300)
        $p3Ey = [int]($p3Win2.Top + 240)
        $p3Json = '[{"press-down":[' + $p3Tx + ',' + $p3Ty + '],"to":"DTX-PressProbe"},' + '{"sleep":120},' +
          '{"drag-to":[' + $p3Ex + ',' + $p3Ey + ',14],"to":"DTX-PressProbe"},' + '{"sleep":120},' +
          '{"press-up":[' + $p3Ex + ',' + $p3Ey + '],"to":"DTX-PressProbe"}]'
        $p3JsonPath = Join-Path $env:TEMP ('dtx-press-' + [guid]::NewGuid().ToString('N') + '.json')
        [void]$p3Tmp.Add($p3JsonPath)
        [System.IO.File]::WriteAllText($p3JsonPath, $p3Json, (New-Object System.Text.UTF8Encoding($false)))
        $p3dOut = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath script $p3JsonPath 2>&1 | Out-String
        $p3dCode = $LASTEXITCODE
        Start-Sleep -Milliseconds 400
        $p3After = & $p3Witness
        $p3HeldDelta = $p3After.Held - $p3Before.Held
        $p3UpDelta = $p3After.Up - $p3Before.Up
        $p3dUp = ($p3dOut -match 'button is UP \(id=(p\d+-\d+) cause=press-up\)')
        if ($p3dUp) { [void]$p3Ids.Add($Matches[1]) }
        ST-Check 'live: P3-4 press-down -> drag-to -> press-up delivers a HELD drag to the target (>=5 MouseMoves with the button down, exactly 1 MouseUp) and the button is measurably down between the steps' (
          ($p3dCode -eq 0) -and ($p3dOut -match 'button is DOWN') -and ($p3dOut -match 'button still DOWN \(measured-down=yes\)') -and
          $p3dUp -and ($p3dOut -match '5 steps, all ok') -and ($p3HeldDelta -ge 5) -and ($p3UpDelta -eq 1))
        Write-Output ("      P3-4 exit=$p3dCode held-delta=$p3HeldDelta up-delta=$p3UpDelta  " + (($p3dOut.Trim() -split "`r?`n" | Where-Object { $_ -match 'button is|button still|steps,' } | Select-Object -First 4) -join ' | '))

        # P3-5 THE TEETH (the task order: "must be measured, code that merely says so
        # does not count"). A process that dies mid-press must be recovered by the NEXT
        # invocation. No clean exit can leave the button down (the entry finally
        # releases it), so the crash is simulated by stopping the tool's OWN child -
        # nothing else on this machine is touched.
        $p3eWin = Resolve-Window 'DTX-PressProbe'
        $p3eX = [int]($p3eWin.Left + $p3eWin.W / 2)
        $p3eY = [int]($p3eWin.Top + [int]($p3eWin.H / 2))
        $p3Child = Start-Process -FilePath powershell -PassThru -WindowStyle Hidden -ArgumentList @(
          '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $script:ToolEntryPath, 'press-down', "$p3eX", "$p3eY", '--to', 'DTX-PressProbe', '--max-hold', '60000')
        $p3eDown = $false
        $p3eSw = [System.Diagnostics.Stopwatch]::StartNew()
        while ($p3eSw.Elapsed.TotalSeconds -lt 10) { if (Get-LeftButtonDown) { $p3eDown = $true; break }; Start-Sleep -Milliseconds 100 }
        try { if ($p3Child -and -not $p3Child.HasExited) { Stop-Process -Id $p3Child.Id -Force -ErrorAction SilentlyContinue } } catch { }
        Start-Sleep -Milliseconds 400
        $p3eStray = Get-LeftButtonDown
        $p3eOut = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath wins 2>&1 | Out-String
        $p3eWarn = ($p3eOut -match 'released a button left down by a previous run')
        ST-Check 'live: P3-5 a press left down by a dead process is released by the NEXT invocation (WARNING echoed and the button measurably up again) - watchdog 2 has teeth' (
          $p3eDown -and $p3eStray -and $p3eWarn -and (-not (Get-LeftButtonDown)))
        Write-Output ("      P3-5 pressed-by-child=$p3eDown stray-after-kill=$p3eStray warning=$p3eWarn now=" + $(if (Get-LeftButtonDown) { 'down' } else { 'up' }))

        # P3-6 the pairing contract: every DOWN opened in this round must have its UP
        # in actions.log (the task order: an unpaired press-down FAILS the round).
        # The >= 2 floor is the anti-vacuity guard - if the ids were never collected
        # this check must go red, not green by absence of evidence.
        $p3Log = @(Get-Content -LiteralPath $ActionLog -Encoding UTF8 -ErrorAction SilentlyContinue | Select-Object -Last 600)
        $p3Unpaired = New-Object System.Collections.ArrayList
        $p3WrongId = New-Object System.Collections.ArrayList
        foreach ($p3i2 in @($p3Ids)) {
          # the pairing is by ID, not by "some UP line exists": an UP that names a different
          # id, or one that admits it could not attribute the id, does not close this DOWN.
          $p3UpHit = @($p3Log | Where-Object { $_.Contains('button=UP') -and $_.Contains("id=$p3i2 ") -and $_.Contains('id-source=') -and (-not $_.Contains('id-source=none')) })
          if (@($p3UpHit).Count -lt 1) { [void]$p3Unpaired.Add($p3i2) }
        }
        # the reverse direction: a UP line whose id never appeared in a DOWN this round is a
        # rebuilt/guessed id - exactly the shape the hardening is meant to make impossible.
        # Two things this had to learn the hard way (first round of the check, 2026-10-02):
        # 1) actions.log renders as `<args> | <verb> | <text>', so the press id sits in the
        #    ARGUMENTS - BEFORE the words 'button=DOWN'. A regex demanding both in one order
        #    matches nothing, and every UP line looked like an orphan.
        # 2) the window must be scoped to this round (see $p3LogStart), or the previous round's
        #    perfectly-paired presses are reported as orphans.
        $p3Round = @()
        try { $p3Round = @(Get-Content -LiteralPath $ActionLog -Encoding UTF8 -ErrorAction SilentlyContinue | Select-Object -Skip $p3LogStart) } catch { }
        $p3DownIds = New-Object System.Collections.ArrayList
        foreach ($p3l2 in $p3Round) {
          if ($p3l2.Contains('button=DOWN') -and ($p3l2 -match 'id=(p\d+-\d+)')) { [void]$p3DownIds.Add($Matches[1]) }
        }
        foreach ($p3l3 in $p3Round) {
          if ($p3l3.Contains('button=UP') -and ($p3l3 -match 'id=(p\d+-\d+)') -and (@($p3DownIds) -notcontains $Matches[1])) { [void]$p3WrongId.Add($Matches[1]) }
        }
        Write-Output ("      P3-6 scope: before-block=" + $p3LogStart + " in-round=" + @($p3Round).Count + " down-ids=" + (@($p3DownIds) -join ','))
        ST-Check 'live: P3-6 every press-down this round left a paired press-up line in actions.log, carrying the SAME id and an attributable id-source (a UP with another id, an empty id, or a UP never opened by any DOWN all fail the round)' (
          (@($p3Ids).Count -ge 2) -and (@($p3Unpaired).Count -eq 0) -and (@($p3WrongId).Count -eq 0))
        Write-Output ("      P3-6 ids=" + (@($p3Ids) -join ',') + " unpaired=" + (@($p3Unpaired) -join ',') + " orphan-up-ids=" + (@($p3WrongId) -join ','))
      } catch {
        ST-Check 'live: press trio setup+run' $false
        Write-Output "      press trio error: $($_.Exception.Message)"
      } finally {
        if ($p3Child -and -not $p3Child.HasExited) { try { Stop-Process -Id $p3Child.Id -Force -ErrorAction SilentlyContinue } catch { } }
        if ($p3Proc -and -not $p3Proc.HasExited) { try { Stop-Process -Id $p3Proc.Id -Force -ErrorAction SilentlyContinue } catch { } }
        $p3Left = Resolve-Window 'DTX-PressProbe'
        if ($p3Left) { try { Stop-Process -Id $p3Left.Pid -Force -ErrorAction SilentlyContinue } catch { } }
        # whatever happened above, the OWNER is never left holding a button
        if (Get-LeftButtonDown) {
          Invoke-LeftPress $false
          Write-Output 'WARNING: the press fixture left the button down - released in the live finally'
        }
        foreach ($p3f in $p3Tmp) { if (Test-Path -LiteralPath $p3f) { Remove-Item -LiteralPath $p3f -Force -ErrorAction SilentlyContinue } }
      }

      # ---------- live: v2.1.0 (plan doc 1.1) the composite locator 'find' ----------
      # One fixture, two roads, proven from opposite directions: a real Button carries the
      # ASCII name (UIA sees it, OCR would too), and a CJK string is PAINTED with GDI so no
      # control and no Name exist anywhere - UIA genuinely cannot answer that one and OCR
      # must. CJK on purpose: Windows OCR inserts spaces inside latin strings
      # non-deterministically (same bitmap read as 'AAA BBB' then 'AAAB BB'), which would
      # turn this into a flake instead of a gate.
      # Nothing here activates or raises a window, and every click point stays inside this
      # fixture's own rect - find is a locator, and act-class judgements only ever hit DTX-*.
      $fFindProc = $null
      $fFindTmp = New-Object System.Collections.ArrayList
      try {
        $fPaint = [string]::Join('', @([char]0x5B9A, [char]0x4F4D, [char]0x515C, [char]0x5E95))
        $fOld = Resolve-Window 'DTX-FindProbe'
        if ($fOld) { try { Stop-Process -Id $fOld.Pid -Force -ErrorAction SilentlyContinue } catch { }; Start-Sleep -Milliseconds 500 }
        $fFixScript = Join-Path $env:TEMP ('dtx-find-' + [guid]::NewGuid().ToString('N') + '.ps1')
        [void]$fFindTmp.Add($fFixScript)
        $fSrc = @'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class HXFIND {
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}
"@
[void][HXFIND]::SetProcessDPIAware()
$form = New-Object System.Windows.Forms.Form
$form.Text = 'DTX-FindProbe'
$form.ClientSize = New-Object System.Drawing.Size(660, 430)
$form.StartPosition = 'Manual'
$form.Location = New-Object System.Drawing.Point(60, 1000)
$form.TopMost = $true
$form.BackColor = [System.Drawing.Color]::White
$btn = New-Object System.Windows.Forms.Button
$btn.Text = 'DTXFINDHITU01'
$btn.Location = New-Object System.Drawing.Point(30, 30)
$btn.Size = New-Object System.Drawing.Size(320, 70)
$form.Controls.Add($btn)
$form.Add_Paint({
  param($s, $e)
  # assembled FROM CODE POINTS inside the fixture: this file is written UTF-8 WITHOUT a
  # BOM (every fixture here is), and PowerShell 5.1 decodes a BOM-less .ps1 as ANSI/GBK,
  # so a literal CJK string in it paints mojibake instead of the glyphs the test asks
  # for - that is how this case first failed live (OCR found nothing, exit 1).
  $paint = [string]::Join('', @([char]0x5B9A, [char]0x4F4D, [char]0x515C, [char]0x5E95))
  $fnt = New-Object System.Drawing.Font('SansSerif', 34)
  $br = [System.Drawing.Brushes]::Black
  $e.Graphics.DrawString($paint, $fnt, $br, 30, 300)
  $fnt.Dispose()
})
[System.Windows.Forms.Application]::Run($form)
'@
        [System.IO.File]::WriteAllText($fFixScript, $fSrc, (New-Object System.Text.UTF8Encoding($false)))
        $fFindProc = Start-Process powershell -PassThru -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $fFixScript)
        $fWin = $null
        $fSw = [System.Diagnostics.Stopwatch]::StartNew()
        while ($fSw.Elapsed.TotalSeconds -lt 15) { $fWin = Resolve-Window 'DTX-FindProbe'; if ($fWin) { break }; Start-Sleep -Milliseconds 400 }
        if ($null -eq $fWin) { throw 'the DTX-FindProbe fixture window did not appear within 15s' }
        Start-Sleep -Milliseconds 800
        # 1) UIA road: a control whose Name the tree really exposes must be answered by UIA
        $fOutUia = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath find DTXFINDHITU01 --target DTX-FindProbe 2>&1 | Out-String
        $fCodeUia = $LASTEXITCODE
        ST-Check 'live: find answers a UIA-reachable Name with source=uia and hands back a ready centre (road 1 wins where road 1 can see)' (
          ($fCodeUia -eq 0) -and ($fOutUia -match 'find: source=uia ') -and ($fOutUia -match 'DTXFINDHITU01') -and ($fOutUia -match 'centre=[0-9]+,[0-9]+ -> click '))
        # 2) the OCR road must STILL WORK and must announce itself - plan 2 forbids deleting
        # or weakening it because of 'UIA first', and forbids a silent fallback.
        # The assertion deliberately does NOT compare the CJK text through the pipe: a
        # child's stdout is decoded with the PARENT's console codepage (GBK here), so CJK
        # coming back through `& powershell ... | Out-String` is mojibake whatever the
        # child printed - that is what kept this case red while the feature worked (found
        # by 'find live: ocr=exit0' next to a FAIL line, 2026-10-01). Text equality is
        # checked in the --json case below, where ConvertTo-Json escapes to \uXXXX and
        # survives the pipe. Here the witness is geometric and encoding-free: exactly one
        # hit line, inside the target window, and BELOW the button (the painted string).
        $fOutOcr = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath find $fPaint --target DTX-FindProbe 2>&1 | Out-String
        $fCodeOcr = $LASTEXITCODE
        $fOcrLines = @($fOutOcr -split "`r?`n" | Where-Object { $_ -like '  line *centre=*' })
        $fOcrCx = -1; $fOcrCy = -1
        if (@($fOcrLines).Count -ge 1 -and $fOcrLines[0] -match 'centre=([0-9]+),([0-9]+)') { $fOcrCx = [int]$Matches[1]; $fOcrCy = [int]$Matches[2] }
        $fOcrInside = ($fOcrCx -ge $fWin.Left) -and ($fOcrCx -lt ($fWin.Left + $fWin.W)) -and ($fOcrCy -ge $fWin.Top) -and ($fOcrCy -lt ($fWin.Top + $fWin.H))
        ST-Check 'live: find falls back to OCR for painted text UIA cannot see, announces the fallback in words, and lands on one rect inside the target and below the button (no silent degradation, OCR road intact)' (
          ($fCodeOcr -eq 0) -and ($fOutOcr -match 'falling back to OCR on the same rect') -and ($fOutOcr -match 'find: source=ocr ') -and
          (@($fOcrLines).Count -eq 1) -and $fOcrInside -and ($fOcrCy -gt 1200))
        # 3) a miss names BOTH roads with what each measured
        $fOutMiss = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath find QXNOSUCHTHINGZQX9 --target DTX-FindProbe 2>&1 | Out-String
        $fCodeMiss = $LASTEXITCODE
        ST-Check 'live: a find miss exits 1 and states what EACH road scanned (uia scanned N elements / OCR read M lines) instead of a bare not-found' (
          ($fCodeMiss -eq 1) -and ($fOutMiss -match 'uia scanned [0-9]+ element') -and ($fOutMiss -match 'OCR read [0-9]+ line') -and ($fOutMiss -match "NOT 'absent'"))
        # 4/5) --json carries the same verdict end to end (the key set is a published shape)
        $fJsonUia = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath find DTXFINDHITU01 --target DTX-FindProbe --json 2>&1 | Out-String
        $fJsonOcr = & powershell -NoProfile -ExecutionPolicy Bypass -File $script:ToolEntryPath find $fPaint --target DTX-FindProbe --json 2>&1 | Out-String
        $fJokUia = $false; $fJokOcr = $false
        try {
          $fPJ1 = ($fJsonUia.Trim() -split "`r?`n" | Where-Object { $_ -like '{*"schemaVersion*' } | Select-Object -First 1) | ConvertFrom-Json
          $fKeys1 = (@($fPJ1.PSObject.Properties.Name) | Sort-Object) -join ','
          $fJokUia = ($fKeys1 -ceq (@(Get-FindJsonTopKeys | Sort-Object) -join ',')) -and ($fPJ1.source -ceq 'uia') -and (@($fPJ1.hits).Count -ge 1) -and (@($fPJ1.hits[0].road) -ceq 'uia')
          $fPJ2 = ($fJsonOcr.Trim() -split "`r?`n" | Where-Object { $_ -like '{*"schemaVersion*' } | Select-Object -First 1) | ConvertFrom-Json
          $fJokOcr = ($fPJ2.source -ceq 'ocr') -and (@($fPJ2.hits).Count -ge 1) -and (@($fPJ2.PSObject.Properties.Name) -contains 'target')
        } catch { Write-Output "      find --json parse error: $($_.Exception.Message)" }
        ST-Check 'live: find --json emits the pinned key set end to end with source=uia on the UIA road (the field consumers route on is real output, not only an offline shape)' (
          $fJokUia -and ($fJsonUia -notmatch 'find: source=|  uia: scanned|  line '))
        ST-Check 'live: find --json reports source=ocr through a real child process, with the pinned key set intact (ASCII-safe fields only - see the next case for the text)' ($fJokOcr)
        # 6) the hit TEXT itself, compared IN PROCESS. Measured twice the hard way on
        # 2026-10-01: PS 5.1 ConvertTo-Json emits CJK RAW (no \uXXXX), and a child's
        # stdout is decoded by the parent's GBK console - so any CJK equality routed
        # through a pipe is mojibake no matter what the code does. In process there is no
        # console in the way, and OCR's raw line text may still carry inter-glyph spaces,
        # which is exactly what Normalize-OcrText exists to fold for matching.
        $fJsonSave = $script:Json; $script:Json = $true
        $fTextOk = $false
        try {
          $fInProc = (@(Invoke-DesktopCommand 'find' @($fPaint, '--target', 'DTX-FindProbe')) -join "`n")
          $fObj = ($fInProc -split "`r?`n" | Where-Object { $_ -like '{*"schemaVersion*' } | Select-Object -First 1) | ConvertFrom-Json
          $fTextOk = ($fObj.source -ceq 'ocr') -and (@($fObj.hits).Count -ge 1) -and
            ((Normalize-OcrText "$($fObj.hits[0].text)") -ceq (Normalize-OcrText $fPaint))
        } catch {
          Write-Output "      find in-process json error: $($_.Exception.Message)"
        }
        $script:Json = $fJsonSave
        ST-Check 'live: find hands back the painted string ITSELF as the hit text (compared in-process on purpose: ConvertTo-Json emits raw CJK and a GBK console makes any piped CJK comparison false)' ($fTextOk)
        Write-Output ("      find live: uia=" + $(if ($fCodeUia -eq 0) { 'exit0' } else { "exit$fCodeUia" }) + " ocr=" + $(if ($fCodeOcr -eq 0) { 'exit0' } else { "exit$fCodeOcr" }) + " miss=exit$fCodeMiss jsonUia=$fJokUia jsonOcr=$fJokOcr")
